pub fn lowerExplainPlanWithOptionsAlloc(
    alloc: std.mem.Allocator,
    sql: []const u8,
    schema: runtime_schema.TableSchema,
    params: []const SqlValue,
    options: LowerWritePlanOptions,
) !LoweredExplainPlan {
    return try lowerExplainPlanWithOptionsAndCatalogAlloc(alloc, sql, schema, params, options, null);
}

fn lowerExplainPlanWithCatalogAlloc(
    alloc: std.mem.Allocator,
    sql: []const u8,
    schema: runtime_schema.TableSchema,
    params: []const SqlValue,
    catalog: ?table_catalog.CatalogSource,
) !LoweredExplainPlan {
    return try lowerExplainPlanWithOptionsAndCatalogAlloc(alloc, sql, schema, params, .{}, catalog);
}

fn lowerExplainPlanWithOptionsAndCatalogAlloc(
    alloc: std.mem.Allocator,
    sql: []const u8,
    schema: runtime_schema.TableSchema,
    params: []const SqlValue,
    options: LowerWritePlanOptions,
    catalog: ?table_catalog.CatalogSource,
) !LoweredExplainPlan {
    const parsed = try parseExplainPrefix(sql);
    var read_err: ?anyerror = null;
    if (catalog) |source_catalog| {
        if (lowerReadPlanWithCatalogAlloc(alloc, parsed.inner_sql, schema, params, source_catalog)) |read| {
            return .{
                .analyze = parsed.analyze,
                .format = parsed.format,
                .verbose = parsed.verbose,
                .costs = parsed.costs,
                .subject = .{ .read = read },
            };
        } else |err| {
            if (!sqlWritePlanFallbackAllowed(err)) return err;
            read_err = err;
        }
        if (lowerWritePlanWithCatalogAlloc(alloc, parsed.inner_sql, schema, params, options, source_catalog)) |write| {
            return .{
                .analyze = parsed.analyze,
                .format = parsed.format,
                .verbose = parsed.verbose,
                .costs = parsed.costs,
                .subject = .{ .write = write },
            };
        } else |write_err| {
            return writePlanFallbackError(read_err, write_err);
        }
    }
    if (lowerReadPlanAlloc(alloc, parsed.inner_sql, schema, params)) |read| {
        return .{
            .analyze = parsed.analyze,
            .format = parsed.format,
            .verbose = parsed.verbose,
            .costs = parsed.costs,
            .subject = .{ .read = read },
        };
    } else |err| {
        if (!sqlWritePlanFallbackAllowed(err)) return err;
        read_err = err;
    }
    if (lowerWritePlanAlloc(alloc, parsed.inner_sql, schema, params, options)) |write| {
        return .{
            .analyze = parsed.analyze,
            .format = parsed.format,
            .verbose = parsed.verbose,
            .costs = parsed.costs,
            .subject = .{ .write = write },
        };
    } else |write_err| {
        return writePlanFallbackError(read_err, write_err);
    }
}

pub fn lowerRelationPopulationPlanAlloc(
    alloc: std.mem.Allocator,
    sql: []const u8,
    schema: runtime_schema.TableSchema,
    params: []const SqlValue,
) !LoweredRelationPopulationPlan {
    return try lowerRelationPopulationPlanWithCatalogAlloc(alloc, sql, schema, params, null);
}

pub fn lowerRelationPopulationPlanWithCatalogAlloc(
    alloc: std.mem.Allocator,
    sql: []const u8,
    schema: runtime_schema.TableSchema,
    params: []const SqlValue,
    catalog: ?table_catalog.CatalogSource,
) !LoweredRelationPopulationPlan {
    var parsed = try parseRelationPopulationSqlAlloc(alloc, sql);
    defer parsed.deinit(alloc);
    var source = if (catalog) |source_catalog|
        try lowerReadPlanWithCatalogAlloc(alloc, parsed.source_sql, schema, params, source_catalog)
    else
        try lowerReadPlanAlloc(alloc, parsed.source_sql, schema, params);
    errdefer source.deinit(alloc);
    const target = parsed.target_table_name;
    parsed.target_table_name = "";
    return .{
        .mode = parsed.mode,
        .target_table_name = target,
        .source = source,
    };
}

const ParsedRelationPopulationSql = struct {
    mode: RelationPopulationMode,
    target_table_name: []const u8,
    source_sql: []u8,

    fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
        if (self.target_table_name.len > 0) alloc.free(self.target_table_name);
        alloc.free(self.source_sql);
        self.* = undefined;
    }
};

fn parseRelationPopulationSqlAlloc(alloc: std.mem.Allocator, sql: []const u8) !ParsedRelationPopulationSql {
    var tokens = try tokenizeAlloc(alloc, sql);
    defer freeTokens(alloc, &tokens);
    if (tokens.items.len == 0 or tokens.items[0].kind != .identifier) return error.UnsupportedSqlShape;
    if (std.ascii.eqlIgnoreCase(tokens.items[0].text, "select")) {
        return try parseSelectIntoPopulationSqlAlloc(alloc, sql, tokens.items);
    }
    if (std.ascii.eqlIgnoreCase(tokens.items[0].text, "create")) {
        return try parseCreateTableAsPopulationSqlAlloc(alloc, sql, tokens.items);
    }
    return error.UnsupportedSqlShape;
}

fn parseSelectIntoPopulationSqlAlloc(
    alloc: std.mem.Allocator,
    sql: []const u8,
    tokens: []const Token,
) !ParsedRelationPopulationSql {
    const into_relative = findTopLevelKeyword(tokens[1..], "into") orelse return error.UnsupportedSqlShape;
    const into_index = 1 + into_relative;
    const from_relative = findTopLevelKeyword(tokens[into_index + 1 ..], "from") orelse return error.UnsupportedSqlShape;
    const from_index = into_index + 1 + from_relative;
    if (from_index != into_index + 2) return error.UnsupportedSqlShape;
    if (tokens[into_index + 1].kind != .identifier) return error.UnsupportedSqlShape;
    const target = try normalizeSqlObjectIdentifierAlloc(alloc, tokens[into_index + 1].text);
    var target_transferred = false;
    errdefer if (!target_transferred) alloc.free(target);

    const into_start = try tokenStartOffset(sql, tokens[into_index]);
    const from_start = try tokenStartOffset(sql, tokens[from_index]);
    const source_sql = try std.fmt.allocPrint(
        alloc,
        "{s} {s}",
        .{ std.mem.trim(u8, sql[0..into_start], " \t\r\n"), sql[from_start..] },
    );
    target_transferred = true;
    return .{
        .mode = .select_into,
        .target_table_name = target,
        .source_sql = source_sql,
    };
}

fn parseCreateTableAsPopulationSqlAlloc(
    alloc: std.mem.Allocator,
    sql: []const u8,
    tokens: []const Token,
) !ParsedRelationPopulationSql {
    var index: usize = 1;
    if (!consumeKeyword(tokens, &index, "table")) return error.UnsupportedSqlShape;
    if (consumeKeyword(tokens, &index, "if")) {
        try expectTokenKeyword(tokens, &index, "not");
        try expectTokenKeyword(tokens, &index, "exists");
    }
    if (index >= tokens.len or tokens[index].kind != .identifier) return error.UnsupportedSqlShape;
    const target = try normalizeSqlObjectIdentifierAlloc(alloc, tokens[index].text);
    var target_transferred = false;
    errdefer if (!target_transferred) alloc.free(target);
    index += 1;
    if (!consumeKeyword(tokens, &index, "as")) return error.UnsupportedSqlShape;
    if (index >= tokens.len or tokens[index].kind != .identifier or !std.ascii.eqlIgnoreCase(tokens[index].text, "select")) return error.UnsupportedSqlShape;
    const select_start = try tokenStartOffset(sql, tokens[index]);
    const source_sql = try alloc.dupe(u8, sql[select_start..]);
    target_transferred = true;
    return .{
        .mode = .create_table_as,
        .target_table_name = target,
        .source_sql = source_sql,
    };
}

fn expectTokenKeyword(tokens: []const Token, index: *usize, keyword: []const u8) !void {
    if (!consumeKeyword(tokens, index, keyword)) return error.UnsupportedSqlShape;
}

fn tokenStartOffset(sql: []const u8, token: Token) !usize {
    const sql_start = @intFromPtr(sql.ptr);
    const sql_end = sql_start + sql.len;
    const token_start = @intFromPtr(token.text.ptr);
    if (token_start < sql_start or token_start > sql_end) return error.UnsupportedSqlShape;
    return token_start - sql_start;
}

const ExplainPrefix = struct {
    analyze: bool = false,
    format: ExplainFormat = .text,
    verbose: bool = false,
    costs: bool = true,
    inner_sql: []const u8,
};

fn parseExplainPrefix(sql: []const u8) !ExplainPrefix {
    var index = skipSqlWhitespace(sql, 0);
    if (!consumeSqlKeyword(sql, &index, "explain")) return error.UnsupportedSqlShape;
    index = skipSqlWhitespace(sql, index);
    if (index >= sql.len) return error.UnsupportedSqlShape;

    var prefix = ExplainPrefix{ .inner_sql = "" };
    if (sql[index] == '(') {
        try parseExplainOptions(sql, &index, &prefix);
        index = skipSqlWhitespace(sql, index);
        if (index >= sql.len) return error.UnsupportedSqlShape;
    }

    if (consumeSqlKeyword(sql, &index, "analyze")) {
        prefix.analyze = true;
        index = skipSqlWhitespace(sql, index);
        if (index >= sql.len) return error.UnsupportedSqlShape;
    }

    const inner = std.mem.trim(u8, sql[index..], " \t\r\n;");
    if (inner.len == 0) return error.UnsupportedSqlShape;
    prefix.inner_sql = inner;
    return prefix;
}

fn parseExplainOptions(sql: []const u8, index: *usize, prefix: *ExplainPrefix) !void {
    if (index.* >= sql.len or sql[index.*] != '(') return error.UnsupportedSqlShape;
    index.* += 1;
    while (true) {
        index.* = skipSqlWhitespace(sql, index.*);
        if (index.* >= sql.len) return error.UnsupportedSqlShape;
        if (consumeSqlKeyword(sql, index, "format")) {
            index.* = skipSqlWhitespace(sql, index.*);
            if (consumeSqlKeyword(sql, index, "json")) {
                prefix.format = .json;
            } else if (consumeSqlKeyword(sql, index, "text")) {
                prefix.format = .text;
            } else {
                return error.UnsupportedSqlShape;
            }
        } else if (consumeSqlKeyword(sql, index, "verbose")) {
            prefix.verbose = try parseOptionalExplainBool(sql, index, true);
        } else if (consumeSqlKeyword(sql, index, "costs")) {
            prefix.costs = try parseOptionalExplainBool(sql, index, true);
        } else if (consumeSqlKeyword(sql, index, "analyze")) {
            prefix.analyze = try parseOptionalExplainBool(sql, index, true);
        } else {
            return error.UnsupportedSqlShape;
        }

        index.* = skipSqlWhitespace(sql, index.*);
        if (index.* >= sql.len) return error.UnsupportedSqlShape;
        if (sql[index.*] == ',') {
            index.* += 1;
            continue;
        }
        if (sql[index.*] == ')') {
            index.* += 1;
            return;
        }
        return error.UnsupportedSqlShape;
    }
}

fn parseOptionalExplainBool(sql: []const u8, index: *usize, default_value: bool) !bool {
    const before = index.*;
    index.* = skipSqlWhitespace(sql, index.*);
    if (consumeSqlKeyword(sql, index, "true") or
        consumeSqlKeyword(sql, index, "on") or
        consumeSqlKeyword(sql, index, "yes"))
    {
        return true;
    }
    if (consumeSqlKeyword(sql, index, "false") or
        consumeSqlKeyword(sql, index, "off") or
        consumeSqlKeyword(sql, index, "no"))
    {
        return false;
    }
    index.* = before;
    return default_value;
}

fn skipSqlWhitespace(sql: []const u8, start: usize) usize {
    var index = start;
    while (index < sql.len and std.ascii.isWhitespace(sql[index])) : (index += 1) {}
    return index;
}

fn consumeSqlKeyword(sql: []const u8, index: *usize, keyword: []const u8) bool {
    const start = index.*;
    const end = start + keyword.len;
    if (end > sql.len) return false;
    if (!std.ascii.eqlIgnoreCase(sql[start..end], keyword)) return false;
    if (end < sql.len and isSqlIdentifierByte(sql[end])) return false;
    if (start > 0 and isSqlIdentifierByte(sql[start - 1])) return false;
    index.* = end;
    return true;
}

fn isSqlIdentifierByte(byte: u8) bool {
    return std.ascii.isAlphanumeric(byte) or byte == '_';
}

pub fn lowerWindowPlanAlloc(
    alloc: std.mem.Allocator,
    sql: []const u8,
    schema: runtime_schema.TableSchema,
    params: []const SqlValue,
) !LoweredWindowPlan {
    if (schema.storage_mode != .relational or schema.primary_key == null) return error.InvalidSqlCatalog;
    var tokens = try tokenizeAlloc(alloc, sql);
    defer freeTokens(alloc, &tokens);

    var parser = Parser{
        .alloc = alloc,
        .tokens = tokens.items,
        .schema = schema,
        .params = params,
    };
    var lowered = parser.parseWindowPlan() catch |err| switch (err) {
        error.InvalidRowsRequest => return error.UnsupportedSqlShape,
        else => return err,
    };
    errdefer lowered.deinit(alloc);
    relational_rows.validateRowsWindowPlanCteOutputAlloc(alloc, schema, lowered.plan) catch |err| switch (err) {
        error.InvalidRowsRequest => return error.UnsupportedSqlShape,
        else => return err,
    };
    return lowered;
}

