pub fn runtimeSchemaFromCreateTablePlanAlloc(
    alloc: std.mem.Allocator,
    plan: CreateTablePlan,
) !runtime_schema.TableSchema {
    if (plan.replace_existing and plan.if_not_exists) return error.InvalidSqlCatalog;
    try validateRelationalColumnCatalog(plan.columns);
    try validateRelationalPeriodCatalog(plan.columns, plan.periods);
    if (plan.primary_key) |primary_key| {
        try validatePrimaryKeyColumns(plan.columns, primary_key);
        try validatePrimaryKeyTemporalCatalog(plan.periods, primary_key);
    }
    try validateUniqueConstraintCatalog(plan.columns, plan.periods, plan.unique_constraints);
    try validateForeignKeyCatalog(plan.columns, plan.periods, plan.foreign_keys);
    try validateRelationalCheckCatalog(plan.columns, plan.checks);
    for (plan.columns) |column| {
        if (column.default_value) |default_value| try validateDefaultValueForColumnAlloc(alloc, column, default_value);
        if (column.on_update_value) |on_update_value| try validateDefaultValueForColumnAlloc(alloc, column, on_update_value);
    }

    const default_type = try alloc.dupe(u8, "_default");
    const ttl_field = alloc.dupe(u8, "_timestamp") catch |err| {
        alloc.free(default_type);
        return err;
    };
    var schema: runtime_schema.TableSchema = .{
        .default_type = default_type,
        .ttl_field = ttl_field,
        .enforce_types = true,
        .storage_mode = .relational,
    };
    errdefer runtime_schema.freeSchema(alloc, schema);
    schema.relational_columns = try cloneDdlRelationalColumns(alloc, plan.columns);
    schema.primary_key = try cloneDdlPrimaryKeyMaybe(alloc, plan.primary_key);
    schema.periods = try cloneDdlPeriods(alloc, plan.periods);
    schema.unique_constraints = try cloneDdlUniqueConstraints(alloc, plan.unique_constraints);
    schema.foreign_keys = try cloneDdlForeignKeys(alloc, plan.foreign_keys);
    schema.checks = try cloneDdlRelationalChecks(alloc, plan.checks);
    return schema;
}

pub fn applyDdlPlanToRuntimeSchemaAlloc(
    alloc: std.mem.Allocator,
    current: runtime_schema.TableSchema,
    plan: LoweredDdlPlan,
) !runtime_schema.TableSchema {
    return switch (plan) {
        .adapter_noop => if (current.storage_mode == .relational)
            cloneRelationalRuntimeSchemaAlloc(alloc, current)
        else
            cloneEmptyRuntimeSchemaAlloc(alloc, current),
        .create_table => |create_table| applyCreateTablePlanAlloc(alloc, current, create_table),
        .table_clone => |table_clone| blk: {
            var create_table = try createTablePlanFromTableCloneSourceAlloc(alloc, current, table_clone);
            defer create_table.deinit(alloc);
            break :blk try runtimeSchemaFromCreateTablePlanAlloc(alloc, create_table);
        },
        .view_catalog => error.UnsupportedSqlShape,
        .materialized_view_catalog => error.UnsupportedSqlShape,
        .relation_lifetime => error.UnsupportedSqlShape,
        .enum_type_catalog => error.UnsupportedSqlShape,
        .domain_catalog => error.UnsupportedSqlShape,
        .sequence_catalog => error.UnsupportedSqlShape,
        .identity_allocator_catalog => error.UnsupportedSqlShape,
        .schema_namespace_catalog => error.UnsupportedSqlShape,
        .extension_catalog => error.UnsupportedSqlShape,
        .function_catalog => error.UnsupportedSqlShape,
        .authorization_catalog => error.UnsupportedSqlShape,
        .bulk_io => error.UnsupportedSqlShape,
        .table_partition_catalog => error.UnsupportedSqlShape,
        .row_security_catalog => error.UnsupportedSqlShape,
        .database_catalog => error.UnsupportedSqlShape,
        .tablespace_catalog => error.UnsupportedSqlShape,
        .notification_channel => error.UnsupportedSqlShape,
        .logical_replication => error.UnsupportedSqlShape,
        .type_system_catalog => error.UnsupportedSqlShape,
        .maintenance_job => error.UnsupportedSqlShape,
        .prepared_statement => error.UnsupportedSqlShape,
        .cursor_portal => error.UnsupportedSqlShape,
        .savepoint_transaction => error.UnsupportedSqlShape,
        .comment_metadata => |comment| applyCommentMetadataPlanAlloc(alloc, current, comment),
        .transaction_control => error.UnsupportedSqlShape,
        .create_index => |create_index| applyCreateIndexPlanAlloc(alloc, current, create_index),
        .drop_index => |drop_index| applyDropIndexPlanAlloc(alloc, current, drop_index),
        .drop_table => |drop_table| applyDropTablePlanAlloc(alloc, current, drop_table),
        .alter_table => |alter_table| applyAlterTablePlanAlloc(alloc, current, alter_table),
        .create_update_policy => |update_policy| applyCreateUpdatePolicyPlanAlloc(alloc, current, update_policy),
    };
}

pub fn schemaJsonFromCreateTablePlanAlloc(
    alloc: std.mem.Allocator,
    plan: CreateTablePlan,
) ![]u8 {
    const runtime = try runtimeSchemaFromCreateTablePlanAlloc(alloc, plan);
    defer runtime_schema.freeSchema(alloc, runtime);

    var arena_impl = std.heap.ArenaAllocator.init(alloc);
    defer arena_impl.deinit();
    const arena = arena_impl.allocator();
    const root = try schemaJsonValueFromCreateTablePlanAlloc(arena, plan);
    const schema_json = try std.json.Stringify.valueAlloc(alloc, root, .{ .emit_null_optional_fields = false });
    errdefer alloc.free(schema_json);
    try validateDdlAppliedSchemaJsonAlloc(alloc, schema_json);
    return schema_json;
}

fn clearClonedColumnDefault(alloc: std.mem.Allocator, column: *runtime_schema.RelationalColumn) void {
    if (column.default_value) |value| alloc.free(value.value_json);
    column.default_value = null;
}

fn clearClonedColumnGenerated(alloc: std.mem.Allocator, column: *runtime_schema.RelationalColumn) void {
    if (column.generated) |generated| freeDdlGeneratedValue(alloc, generated);
    column.generated = null;
}

fn clearClonedColumnUpdatePolicy(alloc: std.mem.Allocator, column: *runtime_schema.RelationalColumn) void {
    if (column.on_update_value) |value| alloc.free(value.value_json);
    column.on_update_value = null;
}

fn clearClonedColumnIndexMetadata(alloc: std.mem.Allocator, column: *runtime_schema.RelationalColumn) void {
    if (column.index_name) |index_name| alloc.free(index_name);
    column.index_name = null;
    freeStringSlice(alloc, column.index_include_columns);
    column.index_include_columns = &.{};
    column.indexed = false;
    column.index_lifecycle = .ready;
    column.index_generation = 0;
    freeDdlUniquePredicates(alloc, column.index_where);
    column.index_where = &.{};
    freeExpressionConditions(alloc, column.index_where_expressions);
    if (column.index_where_expressions.len > 0) alloc.free(column.index_where_expressions);
    column.index_where_expressions = &.{};
}

fn createTablePlanFromTableCloneSourceAlloc(
    alloc: std.mem.Allocator,
    source: runtime_schema.TableSchema,
    plan: TableClonePlan,
) !CreateTablePlan {
    if (source.storage_mode != .relational) return error.InvalidSqlCatalog;
    if (!plan.options.columns or !plan.options.constraints or source.primary_key == null) return error.UnsupportedSqlShape;

    const table_name = try alloc.dupe(u8, plan.table_name);
    errdefer alloc.free(table_name);

    var columns = std.ArrayListUnmanaged(runtime_schema.RelationalColumn).empty;
    errdefer {
        clearDdlRelationalColumns(alloc, columns.items);
        columns.deinit(alloc);
    }
    for (source.relational_columns) |source_column| {
        var column = try cloneDdlRelationalColumn(alloc, source_column);
        var column_transferred = false;
        errdefer if (!column_transferred) freeDdlRelationalColumn(alloc, column);
        if (!plan.options.defaults) clearClonedColumnDefault(alloc, &column);
        if (!plan.options.generated) clearClonedColumnGenerated(alloc, &column);
        if (!plan.options.update_policies) clearClonedColumnUpdatePolicy(alloc, &column);
        if (!plan.options.indexes) clearClonedColumnIndexMetadata(alloc, &column);
        try columns.append(alloc, column);
        column_transferred = true;
    }

    const primary_key = try cloneDdlPrimaryKey(alloc, source.primary_key.?);
    errdefer freeDdlPrimaryKey(alloc, primary_key);
    const periods = if (plan.options.periods) try cloneDdlPeriods(alloc, source.periods) else &.{};
    errdefer freeDdlPeriods(alloc, periods);
    const unique_constraints = if (plan.options.constraints) try cloneDdlUniqueConstraints(alloc, source.unique_constraints) else &.{};
    errdefer freeDdlUniqueConstraints(alloc, unique_constraints);
    const foreign_keys = if (plan.options.constraints) try cloneDdlForeignKeys(alloc, source.foreign_keys) else &.{};
    errdefer freeDdlForeignKeys(alloc, foreign_keys);
    const checks = if (plan.options.checks or plan.options.constraints) try cloneDdlRelationalChecks(alloc, source.checks) else &.{};
    errdefer freeDdlRelationalChecks(alloc, checks);

    return .{
        .table_name = table_name,
        .if_not_exists = plan.if_not_exists,
        .columns = try columns.toOwnedSlice(alloc),
        .primary_key = primary_key,
        .periods = periods,
        .unique_constraints = unique_constraints,
        .foreign_keys = foreign_keys,
        .checks = checks,
    };
}

fn schemaJsonFromTableClonePlanAlloc(
    alloc: std.mem.Allocator,
    source_schema_json: []const u8,
    plan: TableClonePlan,
) ![]u8 {
    if (source_schema_json.len == 0) return error.InvalidSqlCatalog;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, source_schema_json);
    defer parsed.deinit(alloc);
    const source = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, source);

    var create_table = try createTablePlanFromTableCloneSourceAlloc(alloc, source, plan);
    defer create_table.deinit(alloc);
    return try schemaJsonFromCreateTablePlanAlloc(alloc, create_table);
}

pub fn applyDdlPlanToSchemaJsonAlloc(
    alloc: std.mem.Allocator,
    current_schema_json: []const u8,
    plan: LoweredDdlPlan,
) !AppliedDdlSchemaJson {
    switch (plan) {
        .adapter_noop => return .{ .schema_json = try alloc.dupe(u8, current_schema_json) },
        .create_table => |create_table| {
            if (current_schema_json.len != 0) {
                if (create_table.replace_existing) return .{
                    .schema_json = try schemaJsonFromCreateTablePlanAlloc(alloc, create_table),
                    .requires_rebuild = true,
                    .validation_required = true,
                    .rewrite_required = true,
                };
                if (!create_table.if_not_exists) return error.InvalidSqlCatalog;
                return .{ .schema_json = try alloc.dupe(u8, current_schema_json) };
            }
            return .{ .schema_json = try schemaJsonFromCreateTablePlanAlloc(alloc, create_table) };
        },
        .table_clone => |table_clone| return .{
            .schema_json = try schemaJsonFromTableClonePlanAlloc(alloc, current_schema_json, table_clone),
            .requires_rebuild = table_clone.options.indexes,
            .validation_required = table_clone.options.constraints or table_clone.options.checks,
        },
        .drop_table => |drop_table| {
            if (current_schema_json.len == 0) {
                if (drop_table.if_exists) return .{ .schema_json = try alloc.dupe(u8, "") };
                return error.InvalidSqlCatalog;
            }
            try validateDdlAppliedSchemaJsonAlloc(alloc, current_schema_json);
            return .{ .schema_json = try alloc.dupe(u8, "") };
        },
        .view_catalog => return error.UnsupportedSqlShape,
        .materialized_view_catalog => return error.UnsupportedSqlShape,
        .relation_lifetime => return error.UnsupportedSqlShape,
        .enum_type_catalog => return error.UnsupportedSqlShape,
        .domain_catalog => return error.UnsupportedSqlShape,
        .sequence_catalog => return error.UnsupportedSqlShape,
        .identity_allocator_catalog => return error.UnsupportedSqlShape,
        .schema_namespace_catalog => return error.UnsupportedSqlShape,
        .extension_catalog => return error.UnsupportedSqlShape,
        .function_catalog => return error.UnsupportedSqlShape,
        .authorization_catalog => return error.UnsupportedSqlShape,
        .bulk_io => return error.UnsupportedSqlShape,
        .table_partition_catalog => return error.UnsupportedSqlShape,
        .row_security_catalog => return error.UnsupportedSqlShape,
        .database_catalog => return error.UnsupportedSqlShape,
        .tablespace_catalog => return error.UnsupportedSqlShape,
        .notification_channel => return error.UnsupportedSqlShape,
        .logical_replication => return error.UnsupportedSqlShape,
        .type_system_catalog => return error.UnsupportedSqlShape,
        .maintenance_job => return error.UnsupportedSqlShape,
        .prepared_statement => return error.UnsupportedSqlShape,
        .cursor_portal => return error.UnsupportedSqlShape,
        .savepoint_transaction => return error.UnsupportedSqlShape,
        .transaction_control => return error.UnsupportedSqlShape,
        .create_index, .drop_index, .alter_table, .create_update_policy, .comment_metadata => {},
    }

    if (current_schema_json.len == 0) {
        return switch (plan) {
            .adapter_noop => unreachable,
            .drop_index => |drop_index| if (drop_index.if_exists) .{ .schema_json = try alloc.dupe(u8, current_schema_json) } else error.InvalidSqlCatalog,
            .alter_table => |alter_table| if (alter_table.if_exists) .{ .schema_json = try alloc.dupe(u8, current_schema_json) } else error.InvalidSqlCatalog,
            .create_table => unreachable,
            .table_clone => unreachable,
            .view_catalog => unreachable,
            .materialized_view_catalog => unreachable,
            .relation_lifetime => unreachable,
            .enum_type_catalog => unreachable,
            .domain_catalog => unreachable,
            .sequence_catalog => unreachable,
            .identity_allocator_catalog => unreachable,
            .schema_namespace_catalog => unreachable,
            .extension_catalog => unreachable,
            .function_catalog => unreachable,
            .authorization_catalog => unreachable,
            .bulk_io => unreachable,
            .table_partition_catalog => unreachable,
            .row_security_catalog => unreachable,
            .database_catalog => unreachable,
            .tablespace_catalog => unreachable,
            .notification_channel => unreachable,
            .logical_replication => unreachable,
            .type_system_catalog => unreachable,
            .maintenance_job => unreachable,
            .prepared_statement => unreachable,
            .cursor_portal => unreachable,
            .savepoint_transaction => unreachable,
            .comment_metadata => error.InvalidSqlCatalog,
            .transaction_control => unreachable,
            .drop_table => unreachable,
            .create_index, .create_update_policy => error.InvalidSqlCatalog,
        };
    }
    var arena_impl = std.heap.ArenaAllocator.init(alloc);
    defer arena_impl.deinit();
    const arena = arena_impl.allocator();
    var parsed = try std.json.parseFromSlice(std.json.Value, arena, current_schema_json, .{});
    const root = switch (parsed.value) {
        .object => |*object| object,
        else => return error.InvalidSqlCatalog,
    };

    var result: AppliedDdlSchemaJson = .{ .schema_json = &.{} };
    switch (plan) {
        .adapter_noop => unreachable,
        .create_table => unreachable,
        .table_clone => unreachable,
        .view_catalog => unreachable,
        .materialized_view_catalog => unreachable,
        .relation_lifetime => unreachable,
        .enum_type_catalog => unreachable,
        .domain_catalog => unreachable,
        .sequence_catalog => unreachable,
        .identity_allocator_catalog => unreachable,
        .schema_namespace_catalog => unreachable,
        .extension_catalog => unreachable,
        .function_catalog => unreachable,
        .authorization_catalog => unreachable,
        .bulk_io => unreachable,
        .table_partition_catalog => unreachable,
        .row_security_catalog => unreachable,
        .database_catalog => unreachable,
        .tablespace_catalog => unreachable,
        .notification_channel => unreachable,
        .logical_replication => unreachable,
        .type_system_catalog => unreachable,
        .maintenance_job => unreachable,
        .prepared_statement => unreachable,
        .cursor_portal => unreachable,
        .savepoint_transaction => unreachable,
        .comment_metadata => |comment| try applyCommentMetadataPlanToSchemaJsonValue(arena, root, comment),
        .transaction_control => unreachable,
        .drop_table => unreachable,
        .create_index => |create_index| {
            const changed = try applyCreateIndexPlanToSchemaJsonValue(arena, root, create_index);
            result.requires_rebuild = changed;
            result.validation_required = changed and create_index.unique;
        },
        .drop_index => |drop_index| try applyDropIndexPlanToSchemaJsonValue(arena, root, drop_index),
        .alter_table => |alter_table| {
            const flags = try alterTablePlanWorkFlagsForSchemaJson(root, alter_table);
            result.requires_rebuild = flags.requires_rebuild;
            result.validation_required = flags.validation_required;
            result.rewrite_required = flags.rewrite_required;
            try applyAlterTablePlanToSchemaJsonValue(arena, root, alter_table);
        },
        .create_update_policy => |update_policy| {
            try applyCreateUpdatePolicyPlanToSchemaJsonValue(arena, root, update_policy);
        },
    }
    result.schema_json = try std.json.Stringify.valueAlloc(alloc, parsed.value, .{ .emit_null_optional_fields = false });
    errdefer alloc.free(result.schema_json);
    try validateDdlAppliedSchemaJsonAlloc(alloc, result.schema_json);
    return result;
}

const DdlWorkFlags = struct {
    requires_rebuild: bool = false,
    validation_required: bool = false,
    rewrite_required: bool = false,
};

fn applyCreateTablePlanAlloc(
    alloc: std.mem.Allocator,
    current: runtime_schema.TableSchema,
    plan: CreateTablePlan,
) !runtime_schema.TableSchema {
    if (tableSchemaCatalogExists(current)) {
        if (plan.replace_existing) return try runtimeSchemaFromCreateTablePlanAlloc(alloc, plan);
        if (plan.if_not_exists and current.storage_mode == .relational) return try cloneRelationalRuntimeSchemaAlloc(alloc, current);
        return error.InvalidSqlCatalog;
    }
    return try runtimeSchemaFromCreateTablePlanAlloc(alloc, plan);
}

fn tableSchemaCatalogExists(current: runtime_schema.TableSchema) bool {
    return current.storage_mode == .relational or
        current.dynamic_templates.len != 0 or
        current.full_text_documents.len != 0 or
        current.relational_columns.len != 0 or
        current.primary_key != null or
        current.periods.len != 0 or
        current.foreign_keys.len != 0 or
        current.unique_constraints.len != 0 or
        current.checks.len != 0;
}

fn alterTablePlanWorkFlags(plan: AlterTablePlan) DdlWorkFlags {
    var flags: DdlWorkFlags = .{};
    for (plan.operations) |operation| {
        switch (operation) {
            .alter_column_default => {},
            .drop_constraint => |drop_constraint| {
                if (defaultPrimaryKeyNameEquals(plan.table_name, drop_constraint.name)) {
                    flags.requires_rebuild = true;
                    flags.rewrite_required = true;
                }
            },
            .rename_constraint => {},
            .drop_update_policy => {},
            .alter_column_nullability => |nullability| {
                if (!nullability.nullable) flags.validation_required = true;
            },
            .drop_column, .rename_column, .alter_column_type => {
                flags.requires_rebuild = true;
                flags.validation_required = true;
                flags.rewrite_required = true;
            },
            .add_column => |add_column| {
                flags.requires_rebuild = true;
                flags.validation_required = !add_column.column.nullable or
                    add_column.unique_constraints.len != 0 or
                    add_column.foreign_keys.len != 0 or
                    add_column.checks.len != 0;
                flags.rewrite_required = add_column.column.generated != null or
                    add_column.column.default_value != null or
                    !add_column.column.nullable;
            },
            else => {
                flags.requires_rebuild = true;
                flags.validation_required = true;
            },
        }
    }
    return flags;
}

fn alterTablePlanWorkFlagsForSchemaJson(root: *std.json.ObjectMap, plan: AlterTablePlan) !DdlWorkFlags {
    var flags = alterTablePlanWorkFlags(plan);
    for (plan.operations) |operation| {
        switch (operation) {
            .drop_constraint => |drop_constraint| {
                if (try schemaJsonPrimaryKeyNameEquals(root, plan.table_name, drop_constraint.name)) {
                    flags.requires_rebuild = true;
                    flags.rewrite_required = true;
                }
            },
            else => {},
        }
    }
    return flags;
}

fn isCaseFoldExpressionOp(op: runtime_schema.UniqueExpressionOp) bool {
    return switch (op) {
        .lower, .upper, .md5 => true,
    };
}

fn relationalGeneratedOpForUniqueExpressionOp(op: runtime_schema.UniqueExpressionOp) runtime_schema.RelationalGeneratedOp {
    return switch (op) {
        .lower => .lower,
        .upper => .upper,
        .md5 => .md5,
    };
}

fn uniqueExpressionOpToken(op: runtime_schema.UniqueExpressionOp) []const u8 {
    return switch (op) {
        .lower => "lower",
        .upper => "upper",
        .md5 => "md5",
    };
}

fn applyCreateIndexPlanAlloc(
    alloc: std.mem.Allocator,
    current: runtime_schema.TableSchema,
    plan: CreateIndexPlan,
) !runtime_schema.TableSchema {
    var schema = try cloneRelationalRuntimeSchemaAlloc(alloc, current);
    errdefer runtime_schema.freeSchema(alloc, schema);

    if (relationalIndexNameExists(schema, plan.index_name)) {
        if (plan.if_not_exists) return schema;
        return error.InvalidSqlCatalog;
    }

    if (plan.method == .gin) {
        if (plan.unique or plan.columns.len != 1 or plan.include_columns.len != 0 or plan.expressions.len != 0 or plan.generated_expression != null) return error.UnsupportedSqlShape;
        const column = relationalColumnForDdl(schema.relational_columns, plan.columns[0]) orelse return error.InvalidSqlCatalog;
        switch (column.field_type) {
            .json => if (plan.opclass == .array_ops) return error.InvalidSqlCatalog,
            .array => if (plan.opclass == .jsonb_path_ops) return error.InvalidSqlCatalog,
            else => return error.InvalidSqlCatalog,
        }
    }

    if (plan.unique) {
        try validateCreateIndexIncludeColumns(schema.relational_columns, plan.columns, plan.include_columns);
        const constraint: runtime_schema.UniqueConstraint = .{
            .name = plan.index_name,
            .columns = plan.columns,
            .expressions = plan.expressions,
            .include_columns = plan.include_columns,
            .without_overlaps_period = plan.without_overlaps_period,
            .where = plan.where,
            .where_expressions = plan.where_expressions,
            .validation_state = .unvalidated,
        };
        try validateUniqueConstraintForColumns(schema.relational_columns, schema.periods, constraint);
        try appendUniqueConstraintAlloc(alloc, &schema, constraint);
        return schema;
    }

    const index_generation = stableSecondaryIndexGeneration(plan);
    if (plan.generated_expression) |generated_expression| {
        if (plan.columns.len != 0 or plan.include_columns.len != 0 or plan.expressions.len != 0) return error.UnsupportedSqlShape;
        if (relationalColumnIndex(schema.relational_columns, plan.index_name) != null) return error.InvalidSqlCatalog;
        const column: runtime_schema.RelationalColumn = .{
            .name = plan.index_name,
            .path = plan.index_name,
            .field_type = .keyword,
            .nullable = true,
            .indexed = true,
            .index_lifecycle = .building,
            .index_generation = index_generation,
            .index_name = plan.index_name,
            .generated = generated_expression,
            .index_where = plan.where,
            .index_where_expressions = plan.where_expressions,
        };
        try validateGeneratedColumnForColumns(schema.relational_columns, column);
        try validateUniquePredicatesForColumns(schema.relational_columns, plan.where);
        try validateUniquePredicateExpressionsForColumns(schema.relational_columns, plan.where_expressions);
        try appendRelationalColumnAlloc(alloc, &schema, column);
        return schema;
    }

    if (plan.columns.len == 0 or plan.expressions.len != 0) return error.UnsupportedSqlShape;
    try validateCreateIndexIncludeColumns(schema.relational_columns, plan.columns, plan.include_columns);
    try validateUniquePredicatesForColumns(schema.relational_columns, plan.where);
    try validateUniquePredicateExpressionsForColumns(schema.relational_columns, plan.where_expressions);
    try markColumnsIndexedAlloc(alloc, &schema, plan.index_name, plan.columns, plan.include_columns, plan.where, plan.where_expressions, index_generation);
    return schema;
}

fn relationalIndexNameExists(schema: runtime_schema.TableSchema, index_name: []const u8) bool {
    return uniqueConstraintNameExists(schema.unique_constraints, index_name) or
        relationalColumnIndexForIndexName(schema.relational_columns, index_name) != null;
}

fn applyCommentMetadataPlanAlloc(
    alloc: std.mem.Allocator,
    current: runtime_schema.TableSchema,
    plan: CommentMetadataPlan,
) !runtime_schema.TableSchema {
    if (!tableSchemaCatalogExists(current)) return error.InvalidSqlCatalog;
    try validateCommentMetadataPlanForRuntimeSchemaAlloc(alloc, current, plan);
    return try cloneRelationalRuntimeSchemaAlloc(alloc, current);
}

fn validateCommentMetadataPlanForRuntimeSchemaAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    plan: CommentMetadataPlan,
) !void {
    if (plan.object_name.len == 0) return error.InvalidSqlCatalog;
    try validateStringCommentJsonAlloc(alloc, plan.comment_json);
    switch (plan.target) {
        .table => {},
        .column => {
            const column_name = commentColumnName(plan.object_name);
            _ = relationalColumnForDdl(schema.relational_columns, column_name) orelse return error.InvalidSqlCatalog;
        },
        .index => {
            if (!relationalIndexNameExists(schema, plan.object_name)) return error.InvalidSqlCatalog;
        },
        .constraint => {
            const parent_table = plan.parent_table_name orelse return error.InvalidSqlCatalog;
            if (!relationalConstraintNameExists(schema, parent_table, plan.object_name)) return error.InvalidSqlCatalog;
        },
    }
}

fn validateStringCommentJsonAlloc(alloc: std.mem.Allocator, comment_json: ?[]const u8) !void {
    const raw = comment_json orelse return;
    var parsed = try std.json.parseFromSlice(std.json.Value, alloc, raw, .{});
    defer parsed.deinit();
    switch (parsed.value) {
        .string => {},
        else => return error.UnsupportedSqlShape,
    }
}

fn applyDropIndexPlanAlloc(
    alloc: std.mem.Allocator,
    current: runtime_schema.TableSchema,
    plan: DropIndexPlan,
) !runtime_schema.TableSchema {
    if (!tableSchemaCatalogExists(current)) {
        if (plan.if_exists) return try cloneEmptyRuntimeSchemaAlloc(alloc, current);
        return error.InvalidSqlCatalog;
    }
    var schema = try cloneRelationalRuntimeSchemaAlloc(alloc, current);
    errdefer runtime_schema.freeSchema(alloc, schema);
    try dropIndexFromRuntimeSchemaAlloc(alloc, &schema, plan);
    return schema;
}

fn applyDropTablePlanAlloc(
    alloc: std.mem.Allocator,
    current: runtime_schema.TableSchema,
    plan: DropTablePlan,
) !runtime_schema.TableSchema {
    if (!tableSchemaCatalogExists(current)) {
        if (plan.if_exists) return try cloneEmptyRuntimeSchemaAlloc(alloc, .{});
        return error.InvalidSqlCatalog;
    }
    return try cloneEmptyRuntimeSchemaAlloc(alloc, .{});
}

fn applyAlterTablePlanAlloc(
    alloc: std.mem.Allocator,
    current: runtime_schema.TableSchema,
    plan: AlterTablePlan,
) !runtime_schema.TableSchema {
    if (!tableSchemaCatalogExists(current)) {
        if (plan.if_exists) return try cloneEmptyRuntimeSchemaAlloc(alloc, current);
        return error.InvalidSqlCatalog;
    }
    var schema = try cloneRelationalRuntimeSchemaAlloc(alloc, current);
    errdefer runtime_schema.freeSchema(alloc, schema);

    for (plan.operations) |operation| {
        switch (operation) {
            .add_column => |add_column| try addRelationalColumnOperationAlloc(alloc, &schema, add_column),
            .add_period => |period| try addRelationalPeriodAlloc(alloc, &schema, period),
            .add_primary_key => |primary_key| try addRelationalPrimaryKeyAlloc(alloc, &schema, primary_key),
            .rename_column => |rename_column| try renameRelationalColumnAlloc(alloc, &schema, rename_column),
            .rename_constraint => |rename_constraint| try renameRelationalConstraintAlloc(alloc, &schema, plan.table_name, rename_constraint),
            .drop_column => |drop_column| try dropRelationalColumnAlloc(alloc, &schema, drop_column),
            .drop_constraint => |drop_constraint| try dropRelationalConstraintAlloc(alloc, &schema, plan.table_name, drop_constraint),
            .drop_update_policy => |drop_update_policy| try dropUpdatePolicyFromRuntimeSchemaAlloc(alloc, &schema, drop_update_policy),
            .alter_column_default => |alter_column_default| try alterRelationalColumnDefaultAlloc(alloc, &schema, alter_column_default),
            .alter_column_nullability => |alter_column_nullability| try alterRelationalColumnNullability(&schema, alter_column_nullability),
            .alter_column_type => |alter_column_type| try alterRelationalColumnTypeAlloc(alloc, &schema, alter_column_type),
            .add_unique_constraint => |constraint| {
                try validateUniqueConstraintForColumns(schema.relational_columns, schema.periods, constraint);
                try appendUniqueConstraintAlloc(alloc, &schema, constraint);
            },
            .add_foreign_key => |foreign_key| {
                try validateForeignKeyForColumns(schema.relational_columns, schema.periods, foreign_key);
                try appendForeignKeyAlloc(alloc, &schema, foreign_key);
            },
            .add_check => |check| {
                try validateCheckForColumns(schema.relational_columns, check);
                try appendRelationalCheckAlloc(alloc, &schema, check);
            },
            .validate_constraint => |constraint_name| try validateConstraintByName(&schema, plan.table_name, constraint_name),
        }
    }
    return schema;
}

fn applyCreateUpdatePolicyPlanAlloc(
    alloc: std.mem.Allocator,
    current: runtime_schema.TableSchema,
    plan: CreateUpdatePolicyPlan,
) !runtime_schema.TableSchema {
    var schema = try cloneRelationalRuntimeSchemaAlloc(alloc, current);
    errdefer runtime_schema.freeSchema(alloc, schema);
    try setColumnOnUpdatePolicyAlloc(alloc, &schema, plan.column_name, plan.on_update_value);
    return schema;
}

fn dropUpdatePolicyFromRuntimeSchemaAlloc(
    alloc: std.mem.Allocator,
    schema: *runtime_schema.TableSchema,
    operation: DropUpdatePolicyOperation,
) anyerror!void {
    _ = operation.trigger_name;
    var policy_count: usize = 0;
    var policy_index: usize = 0;
    for (schema.relational_columns, 0..) |column, i| {
        if (column.on_update_value == null) continue;
        policy_count += 1;
        policy_index = i;
    }
    if (policy_count == 0) {
        if (operation.if_exists) return;
        return error.InvalidSqlCatalog;
    }
    if (policy_count > 1) return error.InvalidSqlCatalog;
    const columns = @constCast(schema.relational_columns);
    if (columns[policy_index].on_update_value) |value| alloc.free(value.value_json);
    columns[policy_index].on_update_value = null;
}

fn addRelationalColumnOperationAlloc(
    alloc: std.mem.Allocator,
    schema: *runtime_schema.TableSchema,
    operation: AddColumnOperation,
) anyerror!void {
    if (relationalColumnIndex(schema.relational_columns, operation.column.name) != null) {
        if (operation.if_not_exists) return;
        return error.InvalidSqlCatalog;
    }
    try validateGeneratedColumnForColumns(schema.relational_columns, operation.column);
    try validateUniquePredicatesForColumns(schema.relational_columns, operation.column.index_where);
    try appendRelationalColumnAlloc(alloc, schema, operation.column);
    for (operation.unique_constraints) |constraint| {
        try validateUniqueConstraintForColumns(schema.relational_columns, schema.periods, constraint);
        try appendUniqueConstraintAlloc(alloc, schema, constraint);
    }
    for (operation.foreign_keys) |foreign_key| {
        try validateForeignKeyForColumns(schema.relational_columns, schema.periods, foreign_key);
        try appendForeignKeyAlloc(alloc, schema, foreign_key);
    }
    for (operation.checks) |check| {
        try validateCheckForColumns(schema.relational_columns, check);
        try appendRelationalCheckAlloc(alloc, schema, check);
    }
}

fn addRelationalPeriodAlloc(
    alloc: std.mem.Allocator,
    schema: *runtime_schema.TableSchema,
    period: runtime_schema.RelationalPeriod,
) !void {
    if (relationalPeriodNameExists(schema.periods, period.name)) return error.InvalidSqlCatalog;
    const len = schema.periods.len;
    const out = try alloc.alloc(runtime_schema.RelationalPeriod, len + 1);
    var appended = false;
    errdefer {
        if (appended) freeDdlPeriod(alloc, out[len]);
        alloc.free(out);
    }
    @memcpy(out[0..len], schema.periods);
    out[len] = try cloneDdlPeriod(alloc, period);
    appended = true;
    try validateRelationalPeriodCatalog(schema.relational_columns, out);
    if (len > 0) alloc.free(schema.periods);
    schema.periods = out;
}

fn addRelationalPrimaryKeyAlloc(
    alloc: std.mem.Allocator,
    schema: *runtime_schema.TableSchema,
    primary_key: runtime_schema.PrimaryKey,
) !void {
    if (schema.primary_key != null) return error.InvalidSqlCatalog;
    try validatePrimaryKeyColumns(schema.relational_columns, primary_key);
    try validatePrimaryKeyTemporalCatalog(schema.periods, primary_key);
    schema.primary_key = try cloneDdlPrimaryKey(alloc, primary_key);
}

const InsertSourceTableNames = struct {
    target: []const u8,
    source: []const u8,

    fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
        alloc.free(@constCast(self.target));
        alloc.free(@constCast(self.source));
        self.* = undefined;
    }
};

fn insertSourceTableNamesAlloc(alloc: std.mem.Allocator, sql: []const u8) !?InsertSourceTableNames {
    var tokens = try tokenizeAlloc(alloc, sql);
    defer freeTokens(alloc, &tokens);
    if (tokens.items.len == 0 or tokens.items[0].kind != .identifier) return null;
    if (std.ascii.eqlIgnoreCase(tokens.items[0].text, "with")) return try insertSourceTableNamesFromWithAlloc(alloc, tokens.items);
    if (!std.ascii.eqlIgnoreCase(tokens.items[0].text, "insert")) return null;
    return try insertSourceTableNamesFromInsertAlloc(alloc, tokens.items, 0);
}

fn insertSourceTableNamesFromInsertAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    insert_index: usize,
) !?InsertSourceTableNames {
    if (insert_index >= tokens.len or tokens[insert_index].kind != .identifier or !std.ascii.eqlIgnoreCase(tokens[insert_index].text, "insert")) return null;
    var index: usize = insert_index + 1;
    if (!consumeKeyword(tokens, &index, "into")) return null;
    _ = consumeKeyword(tokens, &index, "only");
    if (index >= tokens.len or tokens[index].kind != .identifier) return error.UnsupportedSqlShape;
    const target = try normalizeSqlObjectIdentifierAlloc(alloc, tokens[index].text);
    var target_transferred = false;
    errdefer if (!target_transferred) alloc.free(target);
    index += 1;

    const select_index = findTopLevelKeyword(tokens[index..], "select") orelse {
        alloc.free(target);
        return null;
    };
    const absolute_select = index + select_index;
    const from_index = findTopLevelKeyword(tokens[absolute_select + 1 ..], "from") orelse return error.UnsupportedSqlShape;
    var source_index = absolute_select + 1 + from_index + 1;
    _ = consumeKeyword(tokens, &source_index, "only");
    if (source_index >= tokens.len or tokens[source_index].kind != .identifier) return error.UnsupportedSqlShape;
    const source = try normalizeSqlObjectIdentifierAlloc(alloc, tokens[source_index].text);
    errdefer alloc.free(source);

    target_transferred = true;
    return .{ .target = target, .source = source };
}

fn insertSourceTableNamesFromWithAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
) !?InsertSourceTableNames {
    var index: usize = 1;
    if (consumeKeyword(tokens, &index, "recursive")) return error.UnsupportedSqlShape;

    var cte_names = std.ArrayListUnmanaged([]const u8).empty;
    defer {
        for (cte_names.items) |name| alloc.free(name);
        cte_names.deinit(alloc);
    }
    var base_source: ?[]const u8 = null;
    errdefer if (base_source) |source| alloc.free(source);

    while (true) {
        if (index >= tokens.len or tokens[index].kind != .identifier) return error.UnsupportedSqlShape;
        const cte_name = try normalizeSqlObjectIdentifierAlloc(alloc, tokens[index].text);
        var cte_name_transferred = false;
        errdefer if (!cte_name_transferred) alloc.free(cte_name);
        if (sqlStringSliceContains(cte_names.items, cte_name)) return error.UnsupportedSqlShape;
        try cte_names.append(alloc, cte_name);
        cte_name_transferred = true;
        index += 1;

        if (index < tokens.len and tokens[index].kind == .lparen) {
            index = (findMatchingRParenIndex(tokens, index) orelse return error.UnsupportedSqlShape) + 1;
        }
        if (!consumeKeyword(tokens, &index, "as")) return error.UnsupportedSqlShape;
        if (index >= tokens.len or tokens[index].kind != .lparen) return error.UnsupportedSqlShape;
        const close_index = findMatchingRParenIndex(tokens, index) orelse return error.UnsupportedSqlShape;
        const from_index = findTopLevelKeyword(tokens[index + 1 .. close_index], "from") orelse return error.UnsupportedSqlShape;
        var source_index = index + 1 + from_index + 1;
        _ = consumeKeyword(tokens, &source_index, "only");
        if (source_index >= close_index or tokens[source_index].kind != .identifier) return error.UnsupportedSqlShape;
        const source = try normalizeSqlObjectIdentifierAlloc(alloc, tokens[source_index].text);
        var source_transferred = false;
        errdefer if (!source_transferred) alloc.free(source);
        if (!sqlStringSliceContains(cte_names.items, source)) {
            if (base_source) |existing| {
                if (!std.mem.eql(u8, existing, source)) return error.UnsupportedSqlShape;
                alloc.free(source);
            } else {
                base_source = source;
                source_transferred = true;
            }
        } else {
            alloc.free(source);
        }

        index = close_index + 1;
        if (index < tokens.len and tokens[index].kind == .comma) {
            index += 1;
            continue;
        }
        break;
    }

    var final = (try insertSourceTableNamesFromInsertAlloc(alloc, tokens, index)) orelse return null;
    errdefer final.deinit(alloc);
    if (sqlStringSliceContains(cte_names.items, final.source)) {
        const resolved_source = base_source orelse return error.UnsupportedSqlShape;
        const target = final.target;
        alloc.free(@constCast(final.source));
        base_source = null;
        return .{
            .target = target,
            .source = resolved_source,
        };
    }
    if (base_source) |source| alloc.free(source);
    base_source = null;
    return final;
}

fn sqlStringSliceContains(items: []const []const u8, needle: []const u8) bool {
    for (items) |item| {
        if (std.mem.eql(u8, item, needle)) return true;
    }
    return false;
}

fn joinedWriteSourceTableNamesAlloc(alloc: std.mem.Allocator, sql: []const u8) !?InsertSourceTableNames {
    var tokens = try tokenizeAlloc(alloc, sql);
    defer freeTokens(alloc, &tokens);
    if (tokens.items.len == 0 or tokens.items[0].kind != .identifier) return null;

    if (std.ascii.eqlIgnoreCase(tokens.items[0].text, "update")) {
        var target_index: usize = 1;
        _ = consumeKeyword(tokens.items, &target_index, "only");
        if (target_index >= tokens.items.len or tokens.items[target_index].kind != .identifier) return error.UnsupportedSqlShape;
        const target = try normalizeSqlObjectIdentifierAlloc(alloc, tokens.items[target_index].text);
        var target_transferred = false;
        errdefer if (!target_transferred) alloc.free(target);

        const from_index = findTopLevelKeyword(tokens.items[target_index + 1 ..], "from") orelse {
            alloc.free(target);
            return null;
        };
        var source_index = target_index + 1 + from_index + 1;
        _ = consumeKeyword(tokens.items, &source_index, "only");
        if (source_index >= tokens.items.len or tokens.items[source_index].kind != .identifier) return error.UnsupportedSqlShape;
        const source = try normalizeSqlObjectIdentifierAlloc(alloc, tokens.items[source_index].text);
        errdefer alloc.free(source);

        target_transferred = true;
        return .{ .target = target, .source = source };
    }

    if (std.ascii.eqlIgnoreCase(tokens.items[0].text, "delete")) {
        var target_index: usize = 1;
        if (!consumeKeyword(tokens.items, &target_index, "from")) return null;
        _ = consumeKeyword(tokens.items, &target_index, "only");
        if (target_index >= tokens.items.len or tokens.items[target_index].kind != .identifier) return error.UnsupportedSqlShape;
        const target = try normalizeSqlObjectIdentifierAlloc(alloc, tokens.items[target_index].text);
        var target_transferred = false;
        errdefer if (!target_transferred) alloc.free(target);

        const using_index = findTopLevelKeyword(tokens.items[target_index + 1 ..], "using") orelse {
            alloc.free(target);
            return null;
        };
        var source_index = target_index + 1 + using_index + 1;
        _ = consumeKeyword(tokens.items, &source_index, "only");
        if (source_index >= tokens.items.len or tokens.items[source_index].kind != .identifier) return error.UnsupportedSqlShape;
        const source = try normalizeSqlObjectIdentifierAlloc(alloc, tokens.items[source_index].text);
        errdefer alloc.free(source);

        target_transferred = true;
        return .{ .target = target, .source = source };
    }

    if (std.ascii.eqlIgnoreCase(tokens.items[0].text, "merge")) {
        var target_index: usize = 1;
        if (!consumeKeyword(tokens.items, &target_index, "into")) return null;
        _ = consumeKeyword(tokens.items, &target_index, "only");
        if (target_index >= tokens.items.len or tokens.items[target_index].kind != .identifier) return error.UnsupportedSqlShape;
        const target = try normalizeSqlObjectIdentifierAlloc(alloc, tokens.items[target_index].text);
        var target_transferred = false;
        errdefer if (!target_transferred) alloc.free(target);

        const using_index = findTopLevelKeyword(tokens.items[target_index + 1 ..], "using") orelse {
            alloc.free(target);
            return null;
        };
        var source_index = target_index + 1 + using_index + 1;
        _ = consumeKeyword(tokens.items, &source_index, "only");
        if (source_index >= tokens.items.len or tokens.items[source_index].kind != .identifier) return error.UnsupportedSqlShape;
        const source = try normalizeSqlObjectIdentifierAlloc(alloc, tokens.items[source_index].text);
        errdefer alloc.free(source);

        target_transferred = true;
        return .{ .target = target, .source = source };
    }

    return null;
}

const ReadSourceTableNames = struct {
    left: []const u8,
    source: []const u8,

    fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
        alloc.free(@constCast(self.left));
        alloc.free(@constCast(self.source));
        self.* = undefined;
    }
};

fn readSourceTableNamesAlloc(alloc: std.mem.Allocator, sql: []const u8) !?ReadSourceTableNames {
    var tokens = try tokenizeAlloc(alloc, sql);
    defer freeTokens(alloc, &tokens);
    if (tokens.items.len == 0 or tokens.items[0].kind != .identifier or !std.ascii.eqlIgnoreCase(tokens.items[0].text, "select")) return null;

    const from_index = findTopLevelKeyword(tokens.items, "from") orelse return null;
    var left_index = from_index + 1;
    _ = consumeKeyword(tokens.items, &left_index, "only");
    if (left_index >= tokens.items.len or tokens.items[left_index].kind != .identifier) return error.UnsupportedSqlShape;
    const left = try normalizeSqlObjectIdentifierAlloc(alloc, tokens.items[left_index].text);
    var left_transferred = false;
    errdefer if (!left_transferred) alloc.free(left);

    const join_index = if (findTopLevelKeyword(tokens.items[left_index + 1 ..], "join")) |relative|
        left_index + 1 + relative
    else {
        alloc.free(left);
        return null;
    };
    var source_index = join_index + 1;
    if (consumeKeyword(tokens.items, &source_index, "lateral")) {
        if (source_index >= tokens.items.len or tokens.items[source_index].kind != .lparen) return error.UnsupportedSqlShape;
        const close_index = findMatchingRParenIndex(tokens.items, source_index) orelse return error.UnsupportedSqlShape;
        const inner_from = findTopLevelKeyword(tokens.items[source_index + 1 .. close_index], "from") orelse return error.UnsupportedSqlShape;
        source_index = source_index + 1 + inner_from + 1;
    }
    _ = consumeKeyword(tokens.items, &source_index, "only");
    if (source_index >= tokens.items.len or tokens.items[source_index].kind != .identifier) return error.UnsupportedSqlShape;
    const source = try normalizeSqlObjectIdentifierAlloc(alloc, tokens.items[source_index].text);
    errdefer alloc.free(source);

    left_transferred = true;
    return .{ .left = left, .source = source };
}

fn consumeKeyword(tokens: []const Token, index: *usize, keyword: []const u8) bool {
    if (index.* >= tokens.len) return false;
    const token = tokens[index.*];
    if (token.kind != .identifier or !std.ascii.eqlIgnoreCase(token.text, keyword)) return false;
    index.* += 1;
    return true;
}

fn findTopLevelKeyword(tokens: []const Token, keyword: []const u8) ?usize {
    var depth: usize = 0;
    for (tokens, 0..) |token, i| {
        switch (token.kind) {
            .lparen => depth += 1,
            .rparen => {
                if (depth == 0) return null;
                depth -= 1;
            },
            .semicolon => if (depth == 0) return null,
            .identifier => if (depth == 0 and std.ascii.eqlIgnoreCase(token.text, keyword)) return i,
            else => {},
        }
    }
    return null;
}

fn findMatchingRParenIndex(tokens: []const Token, lparen_index: usize) ?usize {
    if (lparen_index >= tokens.len or tokens[lparen_index].kind != .lparen) return null;
    var depth: usize = 1;
    var index = lparen_index + 1;
    while (index < tokens.len) : (index += 1) {
        switch (tokens[index].kind) {
            .lparen => depth += 1,
            .rparen => {
                depth -= 1;
                if (depth == 0) return index;
            },
            else => {},
        }
    }
    return null;
}

fn catalogRuntimeSchemaAlloc(
    alloc: std.mem.Allocator,
    catalog: table_catalog.CatalogSource,
    table_name: []const u8,
) !runtime_schema.TableSchema {
    var snapshot = try catalog.adminSnapshot();
    defer catalog.freeAdminSnapshot(&snapshot);
    const schema_json = catalogTableSchemaJson(&snapshot, table_name) orelse return error.InvalidSqlCatalog;
    if (schema_json.len == 0) return error.InvalidSqlCatalog;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    return try schema_api.deriveRuntimeTableSchema(alloc, parsed);
}

fn catalogTableSchemaJson(snapshot: *const metadata_api.AdminSnapshot, table_name: []const u8) ?[]const u8 {
    for (snapshot.tables) |table| {
        if (std.mem.eql(u8, table.name, table_name)) return table.schema_json;
    }
    return null;
}

const AppParitySourceSchemaCatalog = struct {
    tables: [1]metadata_table_manager.TableRecord,

    fn init(table_name: []const u8, source_schema_json: []const u8) @This() {
        return .{ .tables = .{
            .{ .table_id = 90_001, .name = table_name, .placement_role = "data", .schema_json = source_schema_json },
        } };
    }

    fn iface(self: *@This()) table_catalog.CatalogSource {
        return .{
            .ptr = self,
            .vtable = &.{
                .admin_snapshot = adminSnapshot,
                .free_admin_snapshot = freeAdminSnapshot,
            },
        };
    }

    fn adminSnapshot(ptr: *anyopaque) !metadata_api.AdminSnapshot {
        const self: *@This() = @ptrCast(@alignCast(ptr));
        return .{
            .status = .{ .metadata_group_id = 1, .metrics = .{} },
            .tables = self.tables[0..],
            .ranges = @constCast((&[_]metadata_table_manager.RangeRecord{})[0..]),
            .stores = @constCast((&[_]metadata_table_manager.StoreRecord{})[0..]),
            .placement_intents = @constCast((&[_]raft_reconciler.PlacementIntent{})[0..]),
            .split_transitions = @constCast((&[_]metadata_transition_state.SplitTransitionRecord{})[0..]),
            .merge_transitions = @constCast((&[_]metadata_transition_state.MergeTransitionRecord{})[0..]),
        };
    }

    fn freeAdminSnapshot(_: *anyopaque, _: *metadata_api.AdminSnapshot) void {}
};

fn appParitySourceTableNameAlloc(alloc: std.mem.Allocator, entry: AppParityCorpusEntry) !?[]const u8 {
    if (entry.source_schema_json.len == 0) return null;

    switch (entry.family) {
        .insert_source => {
            var tables = (try insertSourceTableNamesAlloc(alloc, entry.sql)) orelse return error.InvalidSqlCatalog;
            defer tables.deinit(alloc);
            return try alloc.dupe(u8, tables.source);
        },
        .update_joined_source,
        .delete_joined_source,
        .merge_mutation,
        => {
            var tables = (try joinedWriteSourceTableNamesAlloc(alloc, entry.sql)) orelse return error.InvalidSqlCatalog;
            defer tables.deinit(alloc);
            return try alloc.dupe(u8, tables.source);
        },
        .read,
        .join,
        .lateral,
        => {
            var tables = (try readSourceTableNamesAlloc(alloc, entry.sql)) orelse return error.InvalidSqlCatalog;
            defer tables.deinit(alloc);
            return try alloc.dupe(u8, tables.source);
        },
        else => return error.InvalidSqlCatalog,
    }
}

const Parser = struct {
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: usize = 0,
    schema: runtime_schema.TableSchema = .{},
    joined_source_schema: ?runtime_schema.TableSchema = null,
    params: []const SqlValue = &.{},
    unique_resolver: ?relational_rows.UniqueSelectorResolver = null,
    mutation_claim: ?db_mod.types.RowClaimRequest = null,
    returning_expression_qualifiers: []const []const u8 = &.{},
    field_expression_qualifiers: []const []const u8 = &.{},
    joined_target_expression_qualifiers: []const []const u8 = &.{},
    joined_source_expression_qualifiers: []const []const u8 = &.{},
    pending_joined_source_alias: ?[]const u8 = null,
    named_window_specs: []const NamedWindowSpec = &.{},
    insert_source_allows_different_table: bool = false,
    row_expression_field_source_override: ?db_mod.types.RelationalRowsExpressionFieldSource = null,
    defer_row_expression_field_validation: bool = false,
    conflict_existing_qualifiers: []const []const u8 = &.{},
    allow_primary_key_assignment: bool = false,
    saw_primary_key_assignment: bool = false,
    allow_select_set_boundary: bool = false,
    allow_select_set_result_tail_boundary: bool = false,

    fn parseDdlPlan(self: *@This()) !LoweredDdlPlan {
        if (self.matchKeyword("create")) {
            if (self.matchKeyword("or")) {
                try self.expectKeyword("replace");
                if (self.peekKeyword("trigger")) {
                    return .{ .create_update_policy = try self.parseCreateTriggerPolicyDdl() };
                }
                if (self.peekKeyword("materialized")) {
                    return .{ .materialized_view_catalog = .{ .create = try self.parseCreateMaterializedViewDdl(true) } };
                }
                if (self.peekKeyword("view")) {
                    return .{ .view_catalog = .{ .create = try self.parseCreateViewDdl(true) } };
                }
                if (self.peekKeyword("function") or self.peekKeyword("procedure")) {
                    return .{ .function_catalog = .{ .create = try self.parseCreateRoutineDdl(true) } };
                }
                if (!self.peekKeyword("table")) return error.UnsupportedSqlShape;
                var create_table = try self.parseCreateTableDdl();
                if (create_table.if_not_exists) {
                    create_table.deinit(self.alloc);
                    return error.UnsupportedSqlShape;
                }
                create_table.replace_existing = true;
                return .{ .create_table = create_table };
            }
            const unique = self.matchKeyword("unique");
            if (self.peekKeyword("index")) {
                return .{ .create_index = try self.parseCreateIndexDdl(unique) };
            }
            if (unique) return error.UnsupportedSqlShape;
            if (self.peekKeyword("trigger")) {
                return .{ .create_update_policy = try self.parseCreateTriggerPolicyDdl() };
            }
            if (self.peekKeyword("materialized")) {
                return .{ .materialized_view_catalog = .{ .create = try self.parseCreateMaterializedViewDdl(false) } };
            }
            if (self.peekKeyword("view")) {
                return .{ .view_catalog = .{ .create = try self.parseCreateViewDdl(false) } };
            }
            if (self.peekKeyword("domain")) {
                return .{ .domain_catalog = .{ .create = try self.parseCreateDomainDdl() } };
            }
            if (self.peekKeyword("sequence")) {
                return .{ .sequence_catalog = .{ .create = try self.parseCreateSequenceDdl() } };
            }
            if (self.peekKeyword("type")) {
                return .{ .enum_type_catalog = .{ .create = try self.parseCreateEnumTypeDdl() } };
            }
            if (self.peekKeyword("schema")) {
