                return .{ .type_system_catalog = .{ .aggregate = .{ .create = try self.parseCreateAggregateDdl() } } };
            }
            if (self.peekKeyword("cast")) {
                return .{ .type_system_catalog = .{ .cast = .{ .create = try self.parseCreateCastDdl() } } };
            }
