            if (self.peekKeyword("view")) return .{ .view_catalog = .{ .drop = try self.parseDropViewDdl() } };
            if (self.peekKeyword("domain")) return .{ .domain_catalog = .{ .drop = try self.parseDropDomainDdl() } };
            if (self.peekKeyword("sequence")) return .{ .sequence_catalog = .{ .drop = try self.parseDropSequenceDdl() } };
            if (self.peekKeyword("type")) return .{ .enum_type_catalog = .{ .drop = try self.parseDropEnumTypeDdl() } };
            if (self.peekKeyword("schema")) return .{ .schema_namespace_catalog = .{ .drop = try self.parseDropSchemaNamespaceDdl() } };
            if (self.peekKeyword("database")) return .{ .database_catalog = .{ .drop = try self.parseDropDatabaseDdl() } };
            if (self.peekKeyword("tablespace")) return .{ .tablespace_catalog = .{ .drop = try self.parseDropTablespaceDdl() } };
            if (self.peekKeyword("publication")) return .{ .logical_replication = .{ .publication = .{ .drop = try self.parseDropPublicationDdl() } } };
            if (self.peekKeyword("subscription")) return .{ .logical_replication = .{ .subscription = .{ .drop = try self.parseDropSubscriptionDdl() } } };
            if (self.peekKeyword("collation")) return .{ .type_system_catalog = .{ .collation = .{ .drop = try self.parseDropCollationDdl() } } };
            if (self.peekKeyword("operator")) return .{ .type_system_catalog = .{ .operator = .{ .drop = try self.parseDropOperatorDdl() } } };
            if (self.peekKeyword("aggregate")) return .{ .type_system_catalog = .{ .aggregate = .{ .drop = try self.parseDropAggregateDdl() } } };
            if (self.peekKeyword("cast")) return .{ .type_system_catalog = .{ .cast = .{ .drop = try self.parseDropCastDdl() } } };
            if (self.peekKeyword("function") or self.peekKeyword("procedure")) return .{ .function_catalog = .{ .drop = try self.parseDropRoutineDdl() } };
            if (self.peekKeyword("role")) return .{ .authorization_catalog = .{ .drop_role = try self.parseDropRoleDdl() } };
            if (self.peekKeyword("policy")) return .{ .row_security_catalog = .{ .drop_policy = try self.parseDropRowSecurityPolicyDdl() } };
            if (self.peekKeyword("table")) return .{ .drop_table = try self.parseDropTableDdl() };
            if (self.peekKeyword("trigger")) return .{ .alter_table = try self.parseDropTriggerPolicyDdl() };
            return .{ .drop_index = try self.parseDropIndexDdl() };
        }
        if (self.matchKeyword("refresh")) {
            return .{ .materialized_view_catalog = .{ .refresh = try self.parseRefreshMaterializedViewDdl() } };
        }
        if (self.matchKeyword("listen")) {
            return .{ .notification_channel = .{ .listen = try self.parseListenNotificationDdl() } };
        }
        if (self.matchKeyword("notify")) {
            return .{ .notification_channel = .{ .notify = try self.parseNotifyNotificationDdl() } };
        }
        if (self.matchKeyword("unlisten")) {
            return .{ .notification_channel = .{ .unlisten = try self.parseUnlistenNotificationDdl() } };
        }
        if (self.matchKeyword("vacuum")) {
            return .{ .maintenance_job = .{ .vacuum = try self.parseVacuumMaintenanceDdl() } };
        }
        if (self.matchKeyword("analyze")) {
            return .{ .maintenance_job = .{ .analyze = try self.parseAnalyzeMaintenanceDdl() } };
        }
        if (self.matchKeyword("reindex")) {
            return .{ .maintenance_job = .{ .reindex = try self.parseReindexMaintenanceDdl() } };
        }
        if (self.matchKeyword("cluster")) {
            return .{ .maintenance_job = .{ .cluster = try self.parseClusterMaintenanceDdl() } };
        }
        if (self.matchKeyword("copy")) {
            return .{ .bulk_io = try self.parseBulkIoDdl() };
        }
        if (self.matchKeyword("prepare")) {
            return .{ .prepared_statement = .{ .prepare = try self.parsePrepareStatementDdl() } };
        }
        if (self.matchKeyword("execute")) {
            return .{ .prepared_statement = .{ .execute = try self.parseExecutePreparedStatementDdl() } };
        }
        if (self.matchKeyword("deallocate")) {
            return .{ .prepared_statement = .{ .deallocate = try self.parseDeallocatePreparedStatementDdl() } };
        }
        if (self.matchKeyword("declare")) {
            return .{ .cursor_portal = .{ .declare = try self.parseDeclareCursorPortalDdl() } };
        }
        if (self.matchKeyword("fetch")) {
            return .{ .cursor_portal = .{ .fetch = try self.parseFetchCursorPortalDdl() } };
        }
        if (self.matchKeyword("close")) {
            return .{ .cursor_portal = .{ .close = try self.parseCloseCursorPortalDdl() } };
        }
        if (self.matchKeyword("savepoint")) {
            return .{ .savepoint_transaction = .{ .savepoint = try self.parseSavepointTransactionDdl() } };
        }
        if (self.matchKeyword("release")) {
            return .{ .savepoint_transaction = .{ .release = try self.parseReleaseSavepointDdl() } };
        }
        if (self.matchKeyword("rollback")) {
            if (!self.peekKeyword("to") and !self.peekKeyword("savepoint")) {
                if (!try self.matchAdapterNoopTransactionBoundaryTail(.{ .work = true, .transaction = true })) return error.UnsupportedSqlShape;
                return .{ .adapter_noop = .{ .reason = .transaction_control } };
            }
            return .{ .savepoint_transaction = .{ .rollback_to = try self.parseRollbackToSavepointDdl() } };
        }
        if (self.matchKeyword("commit")) {
            if (!try self.matchAdapterNoopTransactionBoundaryTail(.{ .work = true, .transaction = true })) return error.UnsupportedSqlShape;
            return .{ .adapter_noop = .{ .reason = .transaction_control } };
        }
        if (self.matchKeyword("comment")) {
            return .{ .comment_metadata = try self.parseCommentMetadataDdl() };
        }
        if (self.matchKeyword("grant")) {
            return .{ .authorization_catalog = .{ .grant_privilege = try self.parsePrivilegeChangeDdl(.grant) } };
        }
        if (self.matchKeyword("revoke")) {
            return .{ .authorization_catalog = .{ .revoke_privilege = try self.parsePrivilegeChangeDdl(.revoke) } };
        }
        if (self.matchKeyword("lock")) {
            return .{ .transaction_control = .{ .table_lock = try self.parseTableLockDdl() } };
        }
        if (self.matchKeyword("set")) {
            if (self.peekKeyword("constraints")) return .{ .transaction_control = .{ .constraint_mode = try self.parseConstraintModeDdl() } };
            if (self.peekKeyword("transaction")) return .{ .transaction_control = .{ .transaction_mode = try self.parseTransactionModeDdl(.set_transaction) } };
            try self.parseAdapterNoopStatementTail();
            return .{ .adapter_noop = .{ .reason = .session_setting } };
        }
        if (self.matchKeyword("reset")) {
            try self.parseAdapterNoopStatementTail();
            return .{ .adapter_noop = .{ .reason = .session_setting } };
        }
        if (self.matchKeyword("show")) {
            try self.parseAdapterNoopStatementTail();
            return .{ .adapter_noop = .{ .reason = .session_setting } };
        }
        if (self.matchKeyword("discard")) {
            try self.parseAdapterNoopStatementTail();
            return .{ .adapter_noop = .{ .reason = .session_setting } };
        }
        if (self.matchKeyword("start")) {
            const checkpoint = self.pos;
            if (self.matchKeyword("transaction") and try self.matchAdapterNoopTransactionBoundaryTail(.{})) {
                return .{ .adapter_noop = .{ .reason = .transaction_control } };
            }
            self.pos = checkpoint;
            return .{ .transaction_control = .{ .transaction_mode = try self.parseTransactionModeDdl(.start_transaction) } };
        }
        if (self.matchKeyword("begin")) {
            if (try self.matchAdapterNoopTransactionBoundaryTail(.{ .work = true, .transaction = true })) {
                return .{ .adapter_noop = .{ .reason = .transaction_control } };
            }
            return .{ .transaction_control = .{ .transaction_mode = try self.parseTransactionModeDdl(.begin) } };
        }
        if (self.matchKeyword("select")) {
            return .{ .transaction_control = .{ .advisory_lock = try self.parseAdvisoryLockDdl() } };
        }
        return error.UnsupportedSqlShape;
    }

    fn parseAdapterNoopStatementTail(self: *@This()) !void {
        while (!self.atEnd() and !self.peekKind(.semicolon)) {
            self.pos += 1;
        }
        if (self.match(.semicolon) != null and !self.atEnd()) return error.UnsupportedSqlShape;
        if (!self.atEnd()) return error.UnsupportedSqlShape;
    }

    const AdapterNoopTransactionBoundaryTail = struct {
        work: bool = false,
        transaction: bool = false,
    };

    fn matchAdapterNoopTransactionBoundaryTail(self: *@This(), options: AdapterNoopTransactionBoundaryTail) !bool {
        const checkpoint = self.pos;
        if (try self.matchStatementEnd()) return true;
        if ((options.work and self.matchKeyword("work")) or
            (options.transaction and self.matchKeyword("transaction")))
        {
            if (try self.matchStatementEnd()) return true;
        }
        self.pos = checkpoint;
        return false;
    }

    fn matchStatementEnd(self: *@This()) !bool {
        if (self.match(.semicolon) != null) {
            if (!self.atEnd()) return error.UnsupportedSqlShape;
            return true;
        }
        return self.atEnd();
    }

    fn parseCreateDomainDdl(self: *@This()) !CreateDomainPlan {
        try self.expectKeyword("domain");
        const domain_name = try self.parseSqlObjectIdentifierOwned();
        var domain_transferred = false;
        errdefer if (!domain_transferred) self.alloc.free(domain_name);
        try self.expectKeyword("as");
        const ddl_type = try self.parseDdlType();
        var not_null = false;
        var default_value: ?runtime_schema.RelationalDefaultValue = null;
        errdefer if (default_value) |default| self.alloc.free(default.value_json);
        var checks = std.ArrayListUnmanaged(runtime_schema.RelationalCheck).empty;
        errdefer {
            clearDdlRelationalChecks(self.alloc, checks.items);
            checks.deinit(self.alloc);
        }
        while (!self.atEnd() and !self.peekKind(.semicolon)) {
            if (self.matchKeyword("default")) {
                if (default_value != null) return error.UnsupportedSqlShape;
                default_value = try self.parseDdlDefaultValue(ddl_type.field_type);
            } else if (self.matchKeyword("not")) {
                try self.expectKeyword("null");
                not_null = true;
            } else if (self.matchKeyword("null")) {
                not_null = false;
            } else if (self.matchKeyword("constraint")) {
                const constraint_name = try self.parseIdentifierOwned();
                defer self.alloc.free(constraint_name);
                const check = try self.parseDomainCheckConstraint(constraint_name, ddl_type.field_type);
                var check_transferred = false;
                errdefer if (!check_transferred) freeDdlRelationalCheck(self.alloc, check);
                try checks.append(self.alloc, check);
                check_transferred = true;
            } else if (self.matchKeyword("check")) {
                const check = try self.parseDomainCheckConstraint(null, ddl_type.field_type);
                var check_transferred = false;
                errdefer if (!check_transferred) freeDdlRelationalCheck(self.alloc, check);
                try checks.append(self.alloc, check);
                check_transferred = true;
            } else {
                return error.UnsupportedSqlShape;
            }
        }
        if (self.match(.semicolon) != null and !self.atEnd()) return error.UnsupportedSqlShape;
        if (!self.atEnd()) return error.UnsupportedSqlShape;
        const out_default = default_value;
        default_value = null;
        domain_transferred = true;
        return .{
            .domain_name = domain_name,
            .field_type = ddl_type.field_type,
            .array_item_type = ddl_type.array_item_type,
            .not_null = not_null,
            .default_value = out_default,
            .checks = try checks.toOwnedSlice(self.alloc),
        };
    }

    fn parseCreateSchemaNamespaceDdl(self: *@This()) !CreateSchemaNamespacePlan {
        try self.expectKeyword("schema");
        var if_not_exists = false;
        if (self.matchKeyword("if")) {
            try self.expectKeyword("not");
            try self.expectKeyword("exists");
            if_not_exists = true;
        }
        const schema_name = try self.parseSqlObjectIdentifierOwned();
        var schema_transferred = false;
        errdefer if (!schema_transferred) self.alloc.free(schema_name);
        if (self.peekKeyword("authorization") or self.peekKeyword("create") or self.peekKeyword("grant")) return error.UnsupportedSqlShape;
        if (self.match(.semicolon) != null and !self.atEnd()) return error.UnsupportedSqlShape;
        if (!self.atEnd()) return error.UnsupportedSqlShape;
        schema_transferred = true;
        return .{ .schema_name = schema_name, .if_not_exists = if_not_exists };
    }

    fn parseRenameSchemaNamespaceDdl(self: *@This()) !RenameSchemaNamespacePlan {
        try self.expectKeyword("schema");
        const schema_name = try self.parseSqlObjectIdentifierOwned();
        var schema_transferred = false;
        errdefer if (!schema_transferred) self.alloc.free(schema_name);
        try self.expectKeyword("rename");
        try self.expectKeyword("to");
        const new_schema_name = try self.parseSqlObjectIdentifierOwned();
        var new_schema_transferred = false;
        errdefer if (!new_schema_transferred) self.alloc.free(new_schema_name);
        if (self.match(.semicolon) != null and !self.atEnd()) return error.UnsupportedSqlShape;
        if (!self.atEnd()) return error.UnsupportedSqlShape;
        schema_transferred = true;
        new_schema_transferred = true;
        return .{ .schema_name = schema_name, .new_schema_name = new_schema_name };
    }

    fn parseDropSchemaNamespaceDdl(self: *@This()) !DropSchemaNamespacePlan {
        try self.expectKeyword("schema");
        var if_exists = false;
        if (self.matchKeyword("if")) {
            try self.expectKeyword("exists");
            if_exists = true;
        }
        const schema_name = try self.parseSqlObjectIdentifierOwned();
        var schema_transferred = false;
        errdefer if (!schema_transferred) self.alloc.free(schema_name);
        if (self.match(.comma) != null) return error.UnsupportedSqlShape;
        const cascade = self.matchKeyword("cascade");
        if (!cascade) _ = self.matchKeyword("restrict");
        if (self.match(.semicolon) != null and !self.atEnd()) return error.UnsupportedSqlShape;
        if (!self.atEnd()) return error.UnsupportedSqlShape;
        schema_transferred = true;
        return .{ .schema_name = schema_name, .if_exists = if_exists, .cascade = cascade };
    }

    fn parseCreateExtensionDdl(self: *@This()) !CreateExtensionPlan {
        try self.expectKeyword("extension");
        var if_not_exists = false;
        if (self.matchKeyword("if")) {
            try self.expectKeyword("not");
            try self.expectKeyword("exists");
            if_not_exists = true;
        }
        const extension_name = try self.parseSqlObjectIdentifierOwned();
        var extension_transferred = false;
        errdefer if (!extension_transferred) self.alloc.free(extension_name);
        if (self.matchKeyword("with")) {
            try self.expectKeyword("schema");
            const schema_name = try self.parseSqlObjectIdentifierOwned();
            defer self.alloc.free(schema_name);
            if (!if_not_exists or
                !isAdapterNoopExtensionName(extension_name) or
                !std.ascii.eqlIgnoreCase(schema_name, "public"))
            {
                return error.UnsupportedSqlShape;
            }
        } else if (self.matchKeyword("schema")) {
            const schema_name = try self.parseSqlObjectIdentifierOwned();
            defer self.alloc.free(schema_name);
            if (!if_not_exists or
                !isAdapterNoopExtensionName(extension_name) or
                !std.ascii.eqlIgnoreCase(schema_name, "public"))
            {
                return error.UnsupportedSqlShape;
            }
        }
        if (self.peekKeyword("version") or self.peekKeyword("from") or self.peekKeyword("cascade")) return error.UnsupportedSqlShape;
        if (self.match(.semicolon) != null and !self.atEnd()) return error.UnsupportedSqlShape;
        if (!self.atEnd()) return error.UnsupportedSqlShape;
        extension_transferred = true;
        return .{ .extension_name = extension_name, .if_not_exists = if_not_exists };
    }

    fn isAdapterNoopExtensionName(extension_name: []const u8) bool {
        return std.ascii.eqlIgnoreCase(extension_name, "pgcrypto") or
            std.ascii.eqlIgnoreCase(extension_name, "uuid-ossp");
    }

    fn parseRoutineKindKeyword(self: *@This()) !RoutineKind {
        if (self.matchKeyword("function")) return .function;
        try self.expectKeyword("procedure");
        return .procedure;
    }

    fn parseRoutineSignatureArgumentCount(self: *@This()) !usize {
        try self.expect(.lparen);
        if (self.match(.rparen) != null) return 0;
        var count: usize = 0;
        while (true) {
            var saw_argument_token = false;
            while (!self.peekKind(.comma) and !self.peekKind(.rparen)) {
                if (self.atEnd() or self.peekKind(.semicolon)) return error.UnsupportedSqlShape;
                self.pos += 1;
                saw_argument_token = true;
            }
            if (!saw_argument_token) return error.UnsupportedSqlShape;
            count += 1;
            if (self.match(.comma) != null) continue;
            try self.expect(.rparen);
            return count;
        }
    }

    fn parseCreateRoutineDdl(self: *@This(), replace_existing: bool) !CreateRoutinePlan {
        const kind = try self.parseRoutineKindKeyword();
        const routine_name = try self.parseSqlObjectIdentifierOwned();
        errdefer self.alloc.free(routine_name);
        const argument_count = try self.parseRoutineSignatureArgumentCount();
        var returns_type: ?[]const u8 = null;
        errdefer if (returns_type) |value| self.alloc.free(value);
        var language: ?[]const u8 = null;
        errdefer if (language) |value| self.alloc.free(value);
        while (!self.atEnd() and !self.peekKind(.semicolon)) {
            if (self.matchKeyword("returns")) {
                if (kind != .function or returns_type != null) return error.UnsupportedSqlShape;
                returns_type = try self.parseSqlObjectIdentifierOwned();
                continue;
            }
            if (self.matchKeyword("language")) {
                if (language != null) return error.UnsupportedSqlShape;
                language = try self.parseIdentifierOwned();
                continue;
            }
            return error.UnsupportedSqlShape;
        }
        if (kind == .function and returns_type == null) return error.UnsupportedSqlShape;
        if (self.match(.semicolon) != null and !self.atEnd()) return error.UnsupportedSqlShape;
        if (!self.atEnd()) return error.UnsupportedSqlShape;
        return .{
            .kind = kind,
            .routine_name = routine_name,
            .replace_existing = replace_existing,
            .argument_count = argument_count,
            .returns_type = returns_type,
            .language = language,
        };
    }

    fn parseDropRoutineDdl(self: *@This()) !DropRoutinePlan {
        const kind = try self.parseRoutineKindKeyword();
        var if_exists = false;
