    fn parseTransactionModeDdl(self: *@This(), starter: TransactionModeStarter) !TransactionModePlan {
        switch (starter) {
            .set_transaction, .start_transaction => try self.expectKeyword("transaction"),
            .begin => _ = self.matchKeyword("transaction"),
