            checks.deinit(self.alloc);
        }

        while (!self.atEnd() and !self.peekKind(.comma) and !self.peekKind(.semicolon)) {
            if (self.matchKeyword("unique")) {
                var constraint = try self.makeDdlUniqueConstraint(null, &.{column.name}, null);
                constraint.validation_state = .unvalidated;
                try unique_constraints.append(self.alloc, constraint);
            } else if (self.matchKeyword("check")) {
                var check = try self.parseDdlCheckConstraint(null);
                _ = self.consumeOptionalDdlNotValid();
                check.validation_state = .unvalidated;
                try checks.append(self.alloc, check);
            } else if (self.matchKeyword("references")) {
                var foreign_key = try self.parseDdlInlineForeignKeyConstraint(column.name, null);
                _ = self.consumeOptionalDdlNotValid();
                foreign_key.validation_state = .unvalidated;
                try foreign_keys.append(self.alloc, foreign_key);
            } else if (self.matchKeyword("constraint")) {
                const constraint_name = try self.parseIdentifierOwned();
                var constraint_name_transferred = false;
                errdefer if (!constraint_name_transferred) self.alloc.free(constraint_name);
                if (self.matchKeyword("unique")) {
                    var constraint = try self.makeDdlUniqueConstraint(constraint_name, &.{column.name}, null);
                    self.alloc.free(constraint_name);
                    constraint_name_transferred = true;
                    constraint.validation_state = .unvalidated;
                    try unique_constraints.append(self.alloc, constraint);
                } else if (self.matchKeyword("check")) {
                    var check = try self.parseDdlCheckConstraint(constraint_name);
                    self.alloc.free(constraint_name);
                    constraint_name_transferred = true;
                    _ = self.consumeOptionalDdlNotValid();
                    check.validation_state = .unvalidated;
                    try checks.append(self.alloc, check);
                } else if (self.matchKeyword("references")) {
                    var foreign_key = try self.parseDdlInlineForeignKeyConstraint(column.name, constraint_name);
                    self.alloc.free(constraint_name);
                    constraint_name_transferred = true;
                    _ = self.consumeOptionalDdlNotValid();
                    foreign_key.validation_state = .unvalidated;
                    try foreign_keys.append(self.alloc, foreign_key);
                } else {
                    return error.UnsupportedSqlShape;
                }
            } else {
                return error.UnsupportedSqlShape;
            }
        }

        const owned_unique_constraints = try unique_constraints.toOwnedSlice(self.alloc);
        var unique_transferred = false;
        errdefer if (!unique_transferred) freeDdlUniqueConstraints(self.alloc, owned_unique_constraints);
        const owned_foreign_keys = try foreign_keys.toOwnedSlice(self.alloc);
        var foreign_transferred = false;
        errdefer if (!foreign_transferred) freeDdlForeignKeys(self.alloc, owned_foreign_keys);
        const owned_checks = try checks.toOwnedSlice(self.alloc);
        var checks_transferred = false;
        errdefer if (!checks_transferred) freeDdlRelationalChecks(self.alloc, owned_checks);

        try self.appendAlterTableOperation(operations, .{ .add_column = .{
            .column = column,
            .if_not_exists = if_not_exists,
            .unique_constraints = owned_unique_constraints,
            .foreign_keys = owned_foreign_keys,
            .checks = owned_checks,
        } });
        column_transferred = true;
        unique_transferred = true;
        foreign_transferred = true;
        checks_transferred = true;
    }

    fn appendAlterTableOperation(
        self: *@This(),
        operations: *std.ArrayListUnmanaged(AlterTableOperation),
        operation: AlterTableOperation,
    ) !void {
        var operation_transferred = false;
        errdefer if (!operation_transferred) freeAlterTableOperation(self.alloc, operation);
        try operations.append(self.alloc, operation);
        operation_transferred = true;
    }

    fn parseCreateIndexDdl(self: *@This(), unique: bool) !CreateIndexPlan {
        try self.expectKeyword("index");
        _ = self.matchKeyword("concurrently");
        var if_not_exists = false;
        if (self.matchKeyword("if")) {
            try self.expectKeyword("not");
            try self.expectKeyword("exists");
            if_not_exists = true;
        }
        const index_name = try self.parseSqlObjectIdentifierOwned();
        var index_name_transferred = false;
        errdefer if (!index_name_transferred) self.alloc.free(index_name);
        try self.expectKeyword("on");
        const table_name = try self.parseSqlTableReferenceIdentifierOwned();
        var table_name_transferred = false;
        errdefer if (!table_name_transferred) self.alloc.free(table_name);
        var method: DdlIndexMethod = .btree;
        if (self.matchKeyword("using")) {
            const method_token = self.match(.identifier) orelse return error.UnsupportedSqlShape;
            if (std.ascii.eqlIgnoreCase(method_token.text, "btree")) {
                method = .btree;
            } else if (std.ascii.eqlIgnoreCase(method_token.text, "gin")) {
                method = .gin;
            } else return error.UnsupportedSqlShape;
        }

        var columns = std.ArrayListUnmanaged([]const u8).empty;
        var opclass: DdlIndexOpClass = .default;
        errdefer {
            for (columns.items) |column| self.alloc.free(column);
            columns.deinit(self.alloc);
        }
        var expressions = std.ArrayListUnmanaged(runtime_schema.UniqueExpression).empty;
        errdefer {
            for (expressions.items) |expression| self.alloc.free(expression.field);
            expressions.deinit(self.alloc);
        }
        var generated_expression: ?runtime_schema.RelationalGeneratedValue = null;
        errdefer if (generated_expression) |generated| freeDdlGeneratedValue(self.alloc, generated);
        var without_overlaps_period: ?[]const u8 = null;
        errdefer if (without_overlaps_period) |period| self.alloc.free(period);
        try self.expect(.lparen);
        while (true) {
            if (self.nextDdlIndexElementIsSupportedExpression()) {
                const wrapper_count = self.consumeDdlIndexExpressionWrappers();
                if (unique) {
                    if (self.peekKeyword("concat") or self.peekKeyword("concat_ws")) return error.UnsupportedSqlShape;
                    const op: runtime_schema.UniqueExpressionOp = if (self.matchKeyword("lower"))
                        .lower
                    else if (self.matchKeyword("upper"))
                        .upper
                    else blk: {
                        if (!self.matchMd5FunctionKeyword()) return error.UnsupportedSqlShape;
                        break :blk .md5;
                    };
                    try self.expect(.lparen);
                    const field = try self.parseIdentifierOwned();
                    var field_transferred = false;
                    errdefer if (!field_transferred) self.alloc.free(field);
                    try self.expect(.rparen);
                    try expressions.append(self.alloc, .{ .op = op, .field = field });
                    field_transferred = true;
                } else {
                    if (generated_expression != null) return error.UnsupportedSqlShape;
                    const generated = try self.parseDdlGeneratedExpression();
                    var generated_transferred = false;
                    errdefer if (!generated_transferred) freeDdlGeneratedValue(self.alloc, generated);
                    generated_expression = generated;
                    generated_transferred = true;
                }
                try self.closeDdlIndexExpressionWrappers(wrapper_count);
                try self.parseDdlIndexElementOrderOptions();
            } else {
                const column = try self.parseIdentifierOwned();
                var column_transferred = false;
                errdefer if (!column_transferred) self.alloc.free(column);
                if (self.matchKeyword("without")) {
                    try self.expectKeyword("overlaps");
                    if (!unique or without_overlaps_period != null) return error.UnsupportedSqlShape;
                    without_overlaps_period = column;
                    column_transferred = true;
                    if (self.match(.comma) == null) break;
                    continue;
                }
                if (method == .gin and self.peekKind(.identifier)) {
                    const opclass_token = self.match(.identifier) orelse unreachable;
                    if (std.ascii.eqlIgnoreCase(opclass_token.text, "jsonb_path_ops")) {
                        opclass = .jsonb_path_ops;
                    } else if (std.ascii.eqlIgnoreCase(opclass_token.text, "array_ops")) {
                        opclass = .array_ops;
                    } else return error.UnsupportedSqlShape;
                }
                if (self.peekKind(.lparen)) return error.UnsupportedSqlShape;
                try self.parseDdlIndexElementOrderOptions();
                try columns.append(self.alloc, column);
                column_transferred = true;
            }
            if (self.match(.comma) == null) break;
        }
        try self.expect(.rparen);
        if (columns.items.len == 0 and expressions.items.len == 0 and generated_expression == null) return error.UnsupportedSqlShape;
        try validateSqlIdentifierListUnique(columns.items);
        try validateSqlUniqueExpressionListUnique(expressions.items);

        var include_columns: []const []const u8 = &.{};
        var include_columns_owned = false;
        errdefer if (include_columns_owned) freeStringSlice(self.alloc, include_columns);
        if (self.matchKeyword("include")) {
            if (method == .gin or generated_expression != null) return error.UnsupportedSqlShape;
            include_columns = try self.parseDdlColumnListAlloc();
            include_columns_owned = true;
            try validateSqlIdentifierListsDisjoint(columns.items, include_columns);
        }

        var predicates: []const runtime_schema.UniquePredicate = &.{};
        errdefer freeDdlUniquePredicates(self.alloc, predicates);
        var where_expressions: []const db_mod.types.RelationalRowsExpressionCondition = &.{};
        errdefer {
            freeExpressionConditions(self.alloc, where_expressions);
            if (where_expressions.len > 0) self.alloc.free(where_expressions);
        }
        if (self.matchKeyword("where")) {
            const predicate_start = self.pos;
            predicates = self.parseDdlUniquePredicatesAlloc() catch |err| switch (err) {
                error.UnsupportedSqlShape => blk: {
                    self.pos = predicate_start;
                    break :blk &.{};
                },
                else => return err,
            };
            if (predicates.len == 0) {
                self.pos = predicate_start;
                const previous_defer_field_validation = self.defer_row_expression_field_validation;
                self.defer_row_expression_field_validation = true;
                defer self.defer_row_expression_field_validation = previous_defer_field_validation;
                where_expressions = try self.parseUniquePredicateWhereExpressionConditionsAlloc();
            }
        }
        if (self.match(.semicolon) != null and !self.atEnd()) return error.UnsupportedSqlShape;
        if (!self.atEnd()) return error.UnsupportedSqlShape;

        const owned_columns = try columns.toOwnedSlice(self.alloc);
        var columns_transferred = false;
        errdefer if (!columns_transferred) freeStringSlice(self.alloc, owned_columns);
        const owned_include_columns = include_columns;
        const owned_expressions = try expressions.toOwnedSlice(self.alloc);
        var expressions_transferred = false;
        errdefer if (!expressions_transferred) freeDdlUniqueExpressions(self.alloc, owned_expressions);
        const period = without_overlaps_period;
        without_overlaps_period = null;

        index_name_transferred = true;
        table_name_transferred = true;
        columns_transferred = true;
        include_columns_owned = false;
        expressions_transferred = true;
        return .{
            .index_name = index_name,
            .table_name = table_name,
            .if_not_exists = if_not_exists,
            .unique = unique,
            .method = method,
            .opclass = opclass,
            .columns = owned_columns,
            .include_columns = owned_include_columns,
            .expressions = owned_expressions,
            .generated_expression = generated_expression,
            .without_overlaps_period = period,
            .where = predicates,
            .where_expressions = where_expressions,
        };
    }

    fn nextDdlIndexElementIsSupportedExpression(self: *@This()) bool {
        var pos = self.pos;
        while (pos < self.tokens.len and self.tokens[pos].kind == .lparen) : (pos += 1) {}
        if (pos >= self.tokens.len or self.tokens[pos].kind != .identifier) return false;
        return std.ascii.eqlIgnoreCase(self.tokens[pos].text, "lower") or
            std.ascii.eqlIgnoreCase(self.tokens[pos].text, "upper") or
            std.ascii.eqlIgnoreCase(self.tokens[pos].text, "md5") or
            std.ascii.eqlIgnoreCase(self.tokens[pos].text, "concat") or
            std.ascii.eqlIgnoreCase(self.tokens[pos].text, "concat_ws");
    }

    fn consumeDdlIndexExpressionWrappers(self: *@This()) usize {
        var count: usize = 0;
        while (self.match(.lparen) != null) count += 1;
        return count;
    }

    fn closeDdlIndexExpressionWrappers(self: *@This(), count: usize) !void {
        var remaining = count;
        while (remaining > 0) : (remaining -= 1) {
            try self.expect(.rparen);
        }
    }

    fn parseDdlIndexElementOrderOptions(self: *@This()) !void {
        _ = self.matchKeyword("asc") or self.matchKeyword("desc");
        if (self.matchKeyword("nulls")) {
            if (!(self.matchKeyword("first") or self.matchKeyword("last"))) return error.UnsupportedSqlShape;
        }
    }

    fn parseIdentityAllocatorDdl(self: *@This()) !IdentityAllocatorPlan {
        if (self.matchKeyword("temporary") or self.matchKeyword("temp") or self.matchKeyword("unlogged")) return error.UnsupportedSqlShape;
        try self.expectKeyword("table");
        if (self.matchKeyword("if")) return error.UnsupportedSqlShape;

        const table_name = try self.parseSqlObjectIdentifierOwned();
        var table_name_transferred = false;
        errdefer if (!table_name_transferred) self.alloc.free(table_name);
        try self.expect(.lparen);

        const column_name = try self.parseIdentifierOwned();
        var column_name_transferred = false;
        errdefer if (!column_name_transferred) self.alloc.free(column_name);
        const path = try self.alloc.dupe(u8, column_name);
        var path_transferred = false;
        errdefer if (!path_transferred) self.alloc.free(path);

        var identity = try self.parseIdentityAllocatorSpec();
        var identity_transferred = false;
        errdefer if (!identity_transferred) identity.deinit(self.alloc);
        var primary_key = false;
        if (self.matchKeyword("primary")) {
            try self.expectKeyword("key");
            primary_key = true;
        }

        const column: runtime_schema.RelationalColumn = .{
            .name = column_name,
            .path = path,
            .field_type = .numeric,
            .nullable = !primary_key,
        };
        var column_transferred = false;
        errdefer if (!column_transferred) freeDdlRelationalColumn(self.alloc, column);

        var additional_columns = std.ArrayListUnmanaged(runtime_schema.RelationalColumn).empty;
        errdefer {
            clearDdlRelationalColumns(self.alloc, additional_columns.items);
            additional_columns.deinit(self.alloc);
        }
        while (self.match(.comma) != null) {
            if (self.peekKeyword("constraint") or self.peekKeyword("primary") or self.peekKeyword("unique") or self.peekKeyword("foreign") or self.peekKeyword("check") or self.peekKeyword("period")) return error.UnsupportedSqlShape;
            const additional = try self.parseDdlColumnDefinitionStandalone();
            var additional_transferred = false;
            errdefer if (!additional_transferred) freeDdlRelationalColumn(self.alloc, additional);
            try additional_columns.append(self.alloc, additional);
            additional_transferred = true;
        }
        try self.expect(.rparen);
        try self.expectDdlEnd();

        const owned_additional_columns = try additional_columns.toOwnedSlice(self.alloc);
        var additional_columns_transferred = false;
        errdefer if (!additional_columns_transferred) {
            clearDdlRelationalColumns(self.alloc, owned_additional_columns);
            self.alloc.free(owned_additional_columns);
        };

        table_name_transferred = true;
        column_name_transferred = true;
        path_transferred = true;
        column_transferred = true;
        identity_transferred = true;
        additional_columns_transferred = true;
        return .{
            .table_name = table_name,
            .column = column,
            .kind = identity.kind,
            .options = identity.options,
            .primary_key = primary_key,
            .additional_columns = owned_additional_columns,
        };
    }

    fn parseIdentityAllocatorSpec(self: *@This()) !IdentityAllocatorSpec {
        if (self.matchKeyword("serial")) return .{ .kind = .serial };
        if (self.matchKeyword("bigserial")) return .{ .kind = .bigserial };
        const ddl_type = try self.parseDdlType();
        if (ddl_type.field_type != .numeric) return error.UnsupportedSqlShape;
        try self.expectKeyword("generated");
        const kind: IdentityAllocatorKind = if (self.matchKeyword("always"))
            .generated_always
        else blk: {
            try self.expectKeyword("by");
            try self.expectKeyword("default");
            break :blk .generated_by_default;
        };
        try self.expectKeyword("as");
        try self.expectKeyword("identity");
        var options: SequenceOptions = .{};
        errdefer options.deinit(self.alloc);
        if (self.match(.lparen) != null) {
            while (!self.peekKind(.rparen)) {
                try self.parseIdentitySequenceOption(&options);
            }
            try self.expect(.rparen);
        }
        return .{ .kind = kind, .options = options };
    }

    fn parseIdentitySequenceOption(self: *@This(), options: *SequenceOptions) !void {
        if (self.peekKeyword("as") or self.peekKeyword("owned")) return error.UnsupportedSqlShape;
        try self.parseCreateSequenceOption(options);
    }

    fn parseCreateTableDdl(self: *@This()) !CreateTablePlan {
        var plan = try self.parseCreateTableDefinitionDdl();
        errdefer plan.deinit(self.alloc);
        if (self.match(.semicolon) != null and !self.atEnd()) return error.UnsupportedSqlShape;
        if (!self.atEnd()) return error.UnsupportedSqlShape;
        return plan;
    }

    fn parseCreateTableDefinitionDdl(self: *@This()) !CreateTablePlan {
        if (self.matchKeyword("temporary") or self.matchKeyword("temp") or self.matchKeyword("unlogged")) return error.UnsupportedSqlShape;
        try self.expectKeyword("table");
        var if_not_exists = false;
        if (self.matchKeyword("if")) {
            try self.expectKeyword("not");
            try self.expectKeyword("exists");
            if_not_exists = true;
        }

        const table_name = try self.parseSqlObjectIdentifierOwned();
        errdefer self.alloc.free(table_name);
        try self.expect(.lparen);

        var columns = std.ArrayListUnmanaged(runtime_schema.RelationalColumn).empty;
        errdefer {
            clearDdlRelationalColumns(self.alloc, columns.items);
            columns.deinit(self.alloc);
        }
        var primary_key: ?runtime_schema.PrimaryKey = null;
        errdefer if (primary_key) |pk| freeDdlPrimaryKey(self.alloc, pk);
        var periods = std.ArrayListUnmanaged(runtime_schema.RelationalPeriod).empty;
        errdefer {
            for (periods.items) |period| freeDdlPeriod(self.alloc, period);
            periods.deinit(self.alloc);
        }
        var unique_constraints = std.ArrayListUnmanaged(runtime_schema.UniqueConstraint).empty;
        errdefer {
            clearDdlUniqueConstraints(self.alloc, unique_constraints.items);
            unique_constraints.deinit(self.alloc);
        }
        var foreign_keys = std.ArrayListUnmanaged(runtime_schema.ForeignKey).empty;
        errdefer {
            clearDdlForeignKeys(self.alloc, foreign_keys.items);
            foreign_keys.deinit(self.alloc);
        }
        var checks = std.ArrayListUnmanaged(runtime_schema.RelationalCheck).empty;
        errdefer {
            clearDdlRelationalChecks(self.alloc, checks.items);
            checks.deinit(self.alloc);
        }

        while (true) {
            const constraint_name = if (self.matchKeyword("constraint")) try self.parseIdentifierOwned() else null;
            var constraint_name_transferred = false;
            errdefer if (!constraint_name_transferred) if (constraint_name) |name| self.alloc.free(name);

            if (self.peekKeyword("primary") or self.peekKeyword("unique") or self.peekKeyword("foreign") or self.peekKeyword("check") or self.peekKeyword("period")) {
                try self.parseDdlTableConstraint(constraint_name, &primary_key, &periods, &unique_constraints, &foreign_keys, &checks);
                if (constraint_name) |name| self.alloc.free(name);
                constraint_name_transferred = true;
            } else {
                if (constraint_name != null) return error.UnsupportedSqlShape;
                try self.parseDdlColumnDefinition(&columns, &periods, &primary_key, &unique_constraints, &foreign_keys, &checks);
            }

            if (self.match(.comma) == null) break;
        }
        try self.expect(.rparen);

        return .{
            .table_name = table_name,
            .if_not_exists = if_not_exists,
            .columns = try columns.toOwnedSlice(self.alloc),
            .primary_key = primary_key,
            .periods = try periods.toOwnedSlice(self.alloc),
            .unique_constraints = try unique_constraints.toOwnedSlice(self.alloc),
            .foreign_keys = try foreign_keys.toOwnedSlice(self.alloc),
            .checks = try checks.toOwnedSlice(self.alloc),
        };
    }

    fn parseCreatePartitionedTableDdl(self: *@This()) !CreatePartitionedTablePlan {
        var create_table = try self.parseCreateTableDefinitionDdl();
        var create_table_transferred = false;
        errdefer if (!create_table_transferred) create_table.deinit(self.alloc);

        try self.expectKeyword("partition");
        try self.expectKeyword("by");
        const method = try self.parseTablePartitionMethod();
        const keys = try self.parseDdlColumnListAlloc();
        var keys_transferred = false;
        errdefer if (!keys_transferred) freeStringSlice(self.alloc, keys);
        try self.expectDdlEnd();

        create_table_transferred = true;
        keys_transferred = true;
        return .{
            .create_table = create_table,
            .method = method,
            .keys = keys,
        };
    }

    fn parseCreateTablePartitionDdl(self: *@This()) !CreateTablePartitionPlan {
        if (self.matchKeyword("temporary") or self.matchKeyword("temp") or self.matchKeyword("unlogged")) return error.UnsupportedSqlShape;
        try self.expectKeyword("table");
        var if_not_exists = false;
        if (self.matchKeyword("if")) {
            try self.expectKeyword("not");
            try self.expectKeyword("exists");
            if_not_exists = true;
        }
        const table_name = try self.parseSqlObjectIdentifierOwned();
        var table_name_transferred = false;
        errdefer if (!table_name_transferred) self.alloc.free(table_name);
        try self.expectKeyword("partition");
        try self.expectKeyword("of");
        if (if_not_exists) return error.UnsupportedSqlShape;
        const parent_table_name = try self.parseSqlObjectIdentifierOwned();
        var parent_transferred = false;
        errdefer if (!parent_transferred) self.alloc.free(parent_table_name);
        const bounds = try self.parseTablePartitionBounds();
        var bounds_transferred = false;
        errdefer if (!bounds_transferred) {
            var mutable_bounds = bounds;
            mutable_bounds.deinit(self.alloc);
        };
        try self.expectDdlEnd();

        table_name_transferred = true;
        parent_transferred = true;
        bounds_transferred = true;
        return .{
            .table_name = table_name,
            .parent_table_name = parent_table_name,
            .bounds = bounds,
        };
    }

    fn parseAlterTablePartitionDdl(self: *@This()) !TablePartitionCatalogPlan {
        try self.expectKeyword("table");
        const parent_table_name = try self.parseSqlObjectIdentifierOwned();
        var parent_transferred = false;
        errdefer if (!parent_transferred) self.alloc.free(parent_table_name);
        if (self.matchKeyword("attach")) {
            try self.expectKeyword("partition");
            const partition_table_name = try self.parseSqlObjectIdentifierOwned();
            var partition_transferred = false;
            errdefer if (!partition_transferred) self.alloc.free(partition_table_name);
            const bounds = try self.parseTablePartitionBounds();
            var bounds_transferred = false;
            errdefer if (!bounds_transferred) {
                var mutable_bounds = bounds;
                mutable_bounds.deinit(self.alloc);
            };
            try self.expectDdlEnd();
            parent_transferred = true;
            partition_transferred = true;
            bounds_transferred = true;
            return .{ .attach = .{
                .parent_table_name = parent_table_name,
                .partition_table_name = partition_table_name,
                .bounds = bounds,
            } };
        }
        if (self.matchKeyword("detach")) {
            try self.expectKeyword("partition");
            const partition_table_name = try self.parseSqlObjectIdentifierOwned();
            var partition_transferred = false;
            errdefer if (!partition_transferred) self.alloc.free(partition_table_name);
            try self.expectDdlEnd();
            parent_transferred = true;
            partition_transferred = true;
            return .{ .detach = .{
                .parent_table_name = parent_table_name,
                .partition_table_name = partition_table_name,
            } };
        }
        return error.UnsupportedSqlShape;
    }

    fn parseTablePartitionMethod(self: *@This()) !TablePartitionMethod {
        if (self.matchKeyword("range")) return .range;
        return error.UnsupportedSqlShape;
    }

    fn parseTablePartitionBounds(self: *@This()) !TablePartitionBounds {
        try self.expectKeyword("for");
        try self.expectKeyword("values");
        try self.expectKeyword("from");
        try self.expect(.lparen);
        const lower_json = try self.parseSqlUntypedValueJsonAlloc();
        var lower_transferred = false;
        errdefer if (!lower_transferred) self.alloc.free(lower_json);
        try self.expect(.rparen);
        try self.expectKeyword("to");
        try self.expect(.lparen);
        const upper_json = try self.parseSqlUntypedValueJsonAlloc();
        var upper_transferred = false;
        errdefer if (!upper_transferred) self.alloc.free(upper_json);
        try self.expect(.rparen);

        lower_transferred = true;
        upper_transferred = true;
        return .{
            .lower_json = lower_json,
            .upper_json = upper_json,
        };
    }

    fn expectDdlEnd(self: *@This()) !void {
        if (self.match(.semicolon) != null and !self.atEnd()) return error.UnsupportedSqlShape;
        if (!self.atEnd()) return error.UnsupportedSqlShape;
    }

    fn parseTableCloneDdl(self: *@This()) !TableClonePlan {
        if (self.matchKeyword("temporary") or self.matchKeyword("temp") or self.matchKeyword("unlogged")) return error.UnsupportedSqlShape;
        try self.expectKeyword("table");
        var if_not_exists = false;
        if (self.matchKeyword("if")) {
            try self.expectKeyword("not");
            try self.expectKeyword("exists");
            if_not_exists = true;
        }

        const table_name = try self.parseSqlObjectIdentifierOwned();
        var table_name_transferred = false;
        errdefer if (!table_name_transferred) self.alloc.free(table_name);
        try self.expect(.lparen);
        try self.expectKeyword("like");
        const source_table_name = try self.parseSqlObjectIdentifierOwned();
        var source_transferred = false;
        errdefer if (!source_transferred) self.alloc.free(source_table_name);

        var options: TableCloneOptions = .{};
        while (!self.atEnd() and !self.peekKind(.rparen)) {
            const include = if (self.matchKeyword("including"))
                true
            else if (self.matchKeyword("excluding"))
                false
            else
                return error.UnsupportedSqlShape;
            try self.applyTableCloneOption(&options, include);
        }
        try self.expect(.rparen);
        if (self.match(.semicolon) != null and !self.atEnd()) return error.UnsupportedSqlShape;
        if (!self.atEnd()) return error.UnsupportedSqlShape;
        table_name_transferred = true;
        source_transferred = true;
        return .{
            .table_name = table_name,
            .source_table_name = source_table_name,
            .if_not_exists = if_not_exists,
            .options = options,
        };
    }

    fn applyTableCloneOption(self: *@This(), options: *TableCloneOptions, include: bool) !void {
        if (self.matchKeyword("all")) {
            options.* = if (include) TableCloneOptions.includingAll() else .{};
            return;
        }
        if (self.matchKeyword("defaults")) {
            options.defaults = include;
            return;
        }
        if (self.matchKeyword("generated")) {
            options.generated = include;
            return;
        }
        if (self.matchKeyword("constraints")) {
            options.checks = include;
            options.constraints = include;
            return;
        }
        if (self.matchKeyword("indexes")) {
            options.indexes = include;
            return;
        }
        if (self.matchKeyword("periods")) {
            options.periods = include;
            return;
        }
        if (self.matchKeyword("update")) {
            try self.expectKeyword("policies");
            options.update_policies = include;
            return;
        }
        if (self.matchKeyword("comments") or
            self.matchKeyword("storage") or
            self.matchKeyword("statistics") or
            self.matchKeyword("compression") or
            self.matchKeyword("identity"))
        {
            return;
        }
        return error.UnsupportedSqlShape;
    }

    const DdlType = struct {
        field_type: runtime_schema.AntflyType,
        array_item_type: ?runtime_schema.AntflyType = null,
    };

    fn parseDdlColumnDefinition(
        self: *@This(),
        columns: *std.ArrayListUnmanaged(runtime_schema.RelationalColumn),
        periods: *std.ArrayListUnmanaged(runtime_schema.RelationalPeriod),
        primary_key: *?runtime_schema.PrimaryKey,
        unique_constraints: *std.ArrayListUnmanaged(runtime_schema.UniqueConstraint),
        foreign_keys: *std.ArrayListUnmanaged(runtime_schema.ForeignKey),
        checks: *std.ArrayListUnmanaged(runtime_schema.RelationalCheck),
    ) !void {
        if (self.peekDdlRangeColumnDefinition()) {
            try self.parseDdlRangeColumnDefinition(columns, periods);
            return;
        }

        var column = try self.parseDdlColumnDefinitionStandalone();
        var column_transferred = false;
        errdefer if (!column_transferred) freeDdlRelationalColumn(self.alloc, column);
        if (findDdlColumn(columns.items, column.name) != null) return error.UnsupportedSqlShape;
        while (!self.atEnd() and !self.peekKind(.comma) and !self.peekKind(.rparen) and !self.peekKind(.semicolon)) {
            if (try self.parseOptionalDdlCollationAlloc(column.field_type)) |collation| {
                if (column.collation != null) {
                    self.alloc.free(collation);
                    return error.UnsupportedSqlShape;
                }
                column.collation = collation;
                continue;
            } else if (self.matchKeyword("not")) {
                try self.expectKeyword("null");
                column.nullable = false;
            } else if (self.matchKeyword("null")) {
                column.nullable = true;
            } else if (self.matchKeyword("default")) {
                if (column.default_value != null) return error.UnsupportedSqlShape;
                if (column.generated != null) return error.UnsupportedSqlShape;
                column.default_value = try self.parseDdlDefaultValue(column.field_type);
            } else if (self.matchKeyword("generated")) {
                if (column.default_value != null or column.generated != null) return error.UnsupportedSqlShape;
                column.generated = try self.parseDdlGeneratedValue();
            } else if (self.matchKeyword("primary")) {
                try self.expectKeyword("key");
                column.nullable = false;
                try self.installDdlPrimaryKey(primary_key, null, &.{column.name}, null);
            } else if (self.matchKeyword("unique")) {
                try self.appendDdlUniqueConstraint(unique_constraints, null, &.{column.name}, null);
            } else if (self.matchKeyword("check")) {
                const check = try self.parseDdlCheckConstraint(null);
                var check_transferred = false;
                errdefer if (!check_transferred) freeDdlRelationalCheck(self.alloc, check);
                try checks.append(self.alloc, check);
                check_transferred = true;
            } else if (self.matchKeyword("references")) {
                const foreign_key = try self.parseDdlInlineForeignKeyConstraint(column.name, null);
                var foreign_key_transferred = false;
                errdefer if (!foreign_key_transferred) freeDdlForeignKey(self.alloc, foreign_key);
                try foreign_keys.append(self.alloc, foreign_key);
                foreign_key_transferred = true;
            } else if (self.matchKeyword("constraint")) {
                const constraint_name = try self.parseIdentifierOwned();
                var constraint_name_transferred = false;
                errdefer if (!constraint_name_transferred) self.alloc.free(constraint_name);
                if (self.matchKeyword("primary")) {
                    try self.expectKeyword("key");
                    column.nullable = false;
                    try self.installDdlPrimaryKey(primary_key, constraint_name, &.{column.name}, null);
                    self.alloc.free(constraint_name);
                    constraint_name_transferred = true;
                } else if (self.matchKeyword("unique")) {
                    try self.appendDdlUniqueConstraint(unique_constraints, constraint_name, &.{column.name}, null);
                    self.alloc.free(constraint_name);
                    constraint_name_transferred = true;
                } else if (self.matchKeyword("check")) {
                    const check = try self.parseDdlCheckConstraint(constraint_name);
                    self.alloc.free(constraint_name);
                    constraint_name_transferred = true;
                    var check_transferred = false;
                    errdefer if (!check_transferred) freeDdlRelationalCheck(self.alloc, check);
                    try checks.append(self.alloc, check);
                    check_transferred = true;
                } else if (self.matchKeyword("references")) {
                    const foreign_key = try self.parseDdlInlineForeignKeyConstraint(column.name, constraint_name);
                    self.alloc.free(constraint_name);
                    constraint_name_transferred = true;
                    var foreign_key_transferred = false;
                    errdefer if (!foreign_key_transferred) freeDdlForeignKey(self.alloc, foreign_key);
                    try foreign_keys.append(self.alloc, foreign_key);
                    foreign_key_transferred = true;
                } else {
                    return error.UnsupportedSqlShape;
                }
            } else {
                return error.UnsupportedSqlShape;
            }
        }

        try columns.append(self.alloc, column);
        column_transferred = true;
    }

    fn peekDdlRangeColumnDefinition(self: *@This()) bool {
        if (self.pos + 1 >= self.tokens.len) return false;
        return self.tokens[self.pos].kind == .identifier and
            self.tokens[self.pos + 1].kind == .identifier and
            ddlRangeBoundTypeForName(self.tokens[self.pos + 1].text) != null;
    }

    fn parseDdlRangeColumnDefinition(
        self: *@This(),
        columns: *std.ArrayListUnmanaged(runtime_schema.RelationalColumn),
        periods: *std.ArrayListUnmanaged(runtime_schema.RelationalPeriod),
    ) !void {
        const period_name = try self.parseIdentifierOwned();
        var period_transferred = false;
        errdefer if (!period_transferred) self.alloc.free(period_name);
        const type_token = self.match(.identifier) orelse return error.UnsupportedSqlShape;
        const bound_type = ddlRangeBoundTypeForName(type_token.text) orelse return error.UnsupportedSqlShape;
        const range_type = ddlRangeTypeForName(type_token.text) orelse return error.UnsupportedSqlShape;

        if (findDdlColumn(columns.items, period_name) != null) return error.UnsupportedSqlShape;
        if (relationalPeriodNameExists(periods.items, period_name)) return error.UnsupportedSqlShape;

        while (!self.atEnd() and !self.peekKind(.comma) and !self.peekKind(.rparen) and !self.peekKind(.semicolon)) {
            if (self.matchKeyword("not")) {
                try self.expectKeyword("null");
            } else if (self.matchKeyword("null")) {} else {
                return error.UnsupportedSqlShape;
            }
        }

        const start_column_name = try std.fmt.allocPrint(self.alloc, "{s}_start", .{period_name});
        var start_name_transferred = false;
        errdefer if (!start_name_transferred) self.alloc.free(start_column_name);
        const end_column_name = try std.fmt.allocPrint(self.alloc, "{s}_end", .{period_name});
        var end_name_transferred = false;
        errdefer if (!end_name_transferred) self.alloc.free(end_column_name);
        if (findDdlColumn(columns.items, start_column_name) != null or findDdlColumn(columns.items, end_column_name) != null) return error.UnsupportedSqlShape;

        const start_path = try self.alloc.dupe(u8, start_column_name);
        var start_path_transferred = false;
        errdefer if (!start_path_transferred) self.alloc.free(start_path);
        const end_path = try self.alloc.dupe(u8, end_column_name);
        var end_path_transferred = false;
        errdefer if (!end_path_transferred) self.alloc.free(end_path);

        const start_column: runtime_schema.RelationalColumn = .{
            .name = start_column_name,
            .path = start_path,
            .field_type = bound_type,
            .nullable = true,
        };
        var start_column_transferred = false;
        errdefer if (!start_column_transferred) freeDdlRelationalColumn(self.alloc, start_column);
        const end_column: runtime_schema.RelationalColumn = .{
            .name = end_column_name,
            .path = end_path,
            .field_type = bound_type,
            .nullable = true,
        };
        var end_column_transferred = false;
        errdefer if (!end_column_transferred) freeDdlRelationalColumn(self.alloc, end_column);
        const period_start = try self.alloc.dupe(u8, start_column_name);
        var period_start_transferred = false;
        errdefer if (!period_start_transferred) self.alloc.free(period_start);
        const period_end = try self.alloc.dupe(u8, end_column_name);
        var period_end_transferred = false;
        errdefer if (!period_end_transferred) self.alloc.free(period_end);

        try columns.append(self.alloc, start_column);
        start_column_transferred = true;
        start_name_transferred = true;
        start_path_transferred = true;
        try columns.append(self.alloc, end_column);
        end_column_transferred = true;
        end_name_transferred = true;
        end_path_transferred = true;
        try periods.append(self.alloc, .{
            .name = period_name,
            .start_column = period_start,
            .end_column = period_end,
            .range_type = range_type,
        });
        period_transferred = true;
        period_start_transferred = true;
        period_end_transferred = true;
    }

    fn parseDdlColumnDefinitionStandalone(self: *@This()) !runtime_schema.RelationalColumn {
        const name = try self.parseIdentifierOwned();
        var name_transferred = false;
        errdefer if (!name_transferred) self.alloc.free(name);

        const ddl_type = try self.parseDdlType();
        const path = try self.alloc.dupe(u8, name);
        var path_transferred = false;
        errdefer if (!path_transferred) self.alloc.free(path);
        var column: runtime_schema.RelationalColumn = .{
            .name = name,
            .path = path,
            .field_type = ddl_type.field_type,
            .array_item_type = ddl_type.array_item_type,
            .nullable = true,
        };
        var column_transferred = false;
        errdefer if (!column_transferred) freeDdlRelationalColumn(self.alloc, column);
        name_transferred = true;
        path_transferred = true;

        while (!self.atEnd() and !self.peekKind(.comma) and !self.peekKind(.rparen) and !self.peekKind(.semicolon) and !self.peekKeyword("primary") and !self.peekKeyword("unique") and !self.peekKeyword("check") and !self.peekKeyword("references") and !self.peekKeyword("constraint")) {
            if (try self.parseOptionalDdlCollationAlloc(column.field_type)) |collation| {
                if (column.collation != null) {
                    self.alloc.free(collation);
                    return error.UnsupportedSqlShape;
                }
                column.collation = collation;
                continue;
            } else if (self.matchKeyword("not")) {
                try self.expectKeyword("null");
                column.nullable = false;
            } else if (self.matchKeyword("null")) {
                column.nullable = true;
            } else if (self.matchKeyword("default")) {
                if (column.default_value != null) return error.UnsupportedSqlShape;
                if (column.generated != null) return error.UnsupportedSqlShape;
                column.default_value = try self.parseDdlDefaultValue(column.field_type);
            } else if (self.matchKeyword("generated")) {
                if (column.default_value != null or column.generated != null) return error.UnsupportedSqlShape;
                column.generated = try self.parseDdlGeneratedValue();
            } else {
                return error.UnsupportedSqlShape;
            }
        }

        column_transferred = true;
        return column;
    }

    fn parseOptionalDdlCollationAlloc(self: *@This(), field_type: runtime_schema.AntflyType) !?[]const u8 {
        if (!self.matchKeyword("collate")) return null;
        if (!relationalFieldTypeSupportsCollation(field_type)) return error.UnsupportedSqlShape;
        const first = self.match(.identifier) orelse return error.UnsupportedSqlShape;
        if (std.mem.endsWith(u8, first.text, ".")) {
            const second = self.match(.identifier) orelse return error.UnsupportedSqlShape;
            return try std.fmt.allocPrint(self.alloc, "{s}{s}", .{ first.text, second.text });
        }
        return try self.alloc.dupe(u8, first.text);
    }

    fn parseDdlGeneratedValue(self: *@This()) !runtime_schema.RelationalGeneratedValue {
        try self.expectKeyword("always");
        try self.expectKeyword("as");
        try self.expect(.lparen);
        const generated = try self.parseDdlGeneratedExpression();
        var generated_transferred = false;
        errdefer if (!generated_transferred) freeDdlGeneratedValue(self.alloc, generated);
        try self.expect(.rparen);
        try self.expectKeyword("stored");
        generated_transferred = true;
        return generated;
    }

    fn parseDdlGeneratedExpression(self: *@This()) !runtime_schema.RelationalGeneratedValue {
        if (self.peekKeyword("lower") or self.peekKeyword("upper") or self.peekMd5FunctionCall()) {
            const op: runtime_schema.RelationalGeneratedOp = if (self.matchKeyword("lower"))
                .lower
            else if (self.matchKeyword("upper"))
                .upper
            else blk: {
                if (!self.matchMd5FunctionKeyword()) return error.UnsupportedSqlShape;
                break :blk .md5;
            };
            try self.expect(.lparen);
            const field = try self.parseIdentifierOwned();
            var field_transferred = false;
            errdefer if (!field_transferred) self.alloc.free(field);
            try self.expect(.rparen);
            const separator = try self.alloc.dupe(u8, "");
            var separator_transferred = false;
            errdefer if (!separator_transferred) self.alloc.free(separator);
            field_transferred = true;
            separator_transferred = true;
            return .{ .op = op, .field = field, .separator = separator };
        }
        if (self.matchKeyword("concat")) return try self.parseDdlGeneratedConcatExpression(.concat);
        if (self.matchKeyword("concat_ws")) return try self.parseDdlGeneratedConcatExpression(.concat_ws);
        return error.UnsupportedSqlShape;
    }

    fn parseDdlGeneratedConcatExpression(
        self: *@This(),
        op: runtime_schema.RelationalGeneratedOp,
    ) !runtime_schema.RelationalGeneratedValue {
        try self.expect(.lparen);
        var fields = std.ArrayListUnmanaged([]const u8).empty;
        errdefer {
            for (fields.items) |field| self.alloc.free(field);
            fields.deinit(self.alloc);
        }

        var separator: ?[]const u8 = null;
        errdefer if (separator) |value| self.alloc.free(value);
        if (op == .concat_ws) {
            const separator_token = self.match(.string) orelse return error.UnsupportedSqlShape;
            separator = try self.alloc.dupe(u8, separator_token.text);
            try self.expect(.comma);
        }
        const first = try self.parseIdentifierOwned();
        var first_transferred = false;
        errdefer if (!first_transferred) self.alloc.free(first);
        try fields.append(self.alloc, first);
        first_transferred = true;
        while (self.match(.comma) != null) {
            if (op == .concat) {
                if (self.match(.string)) |token| {
                    if (separator) |existing| {
                        if (!std.mem.eql(u8, existing, token.text)) return error.UnsupportedSqlShape;
                    } else {
                        separator = try self.alloc.dupe(u8, token.text);
                    }
                    try self.expect(.comma);
                }
            } else if (separator == null) {
                separator = try self.alloc.dupe(u8, "");
            }
            const field = try self.parseIdentifierOwned();
            var field_transferred = false;
            errdefer if (!field_transferred) self.alloc.free(field);
            try fields.append(self.alloc, field);
            field_transferred = true;
        }
        try self.expect(.rparen);
        if (fields.items.len < 2) return error.UnsupportedSqlShape;
        const owned_fields = try fields.toOwnedSlice(self.alloc);
        var fields_transferred = false;
        errdefer if (!fields_transferred) freeStringSlice(self.alloc, owned_fields);
        const owned_separator = separator orelse try self.alloc.dupe(u8, "");
        separator = null;
        fields_transferred = true;
        return .{ .op = op, .fields = owned_fields, .separator = owned_separator };
    }

    fn parseDdlTableConstraint(
        self: *@This(),
        constraint_name: ?[]const u8,
        primary_key: *?runtime_schema.PrimaryKey,
        periods: *std.ArrayListUnmanaged(runtime_schema.RelationalPeriod),
        unique_constraints: *std.ArrayListUnmanaged(runtime_schema.UniqueConstraint),
        foreign_keys: *std.ArrayListUnmanaged(runtime_schema.ForeignKey),
        checks: *std.ArrayListUnmanaged(runtime_schema.RelationalCheck),
    ) !void {
        if (self.matchKeyword("primary")) {
            try self.expectKeyword("key");
            const columns = try self.parseDdlTemporalColumnListAlloc();
            defer columns.deinit(self.alloc);
            try self.installDdlPrimaryKey(primary_key, constraint_name, columns.columns, columns.without_overlaps_period);
        } else if (self.matchKeyword("unique")) {
            const columns = try self.parseDdlTemporalColumnListAlloc();
            defer columns.deinit(self.alloc);
            try self.appendDdlUniqueConstraint(unique_constraints, constraint_name, columns.columns, columns.without_overlaps_period);
        } else if (self.matchKeyword("foreign")) {
            const foreign_key = try self.parseDdlForeignKeyConstraint(constraint_name);
            var transferred = false;
            errdefer if (!transferred) freeDdlForeignKey(self.alloc, foreign_key);
            try foreign_keys.append(self.alloc, foreign_key);
            transferred = true;
        } else if (self.matchKeyword("check")) {
            const check = try self.parseDdlCheckConstraint(constraint_name);
            var transferred = false;
            errdefer if (!transferred) freeDdlRelationalCheck(self.alloc, check);
            try checks.append(self.alloc, check);
            transferred = true;
        } else if (self.matchKeyword("period")) {
            if (constraint_name != null) return error.UnsupportedSqlShape;
            const period = try self.parseDdlPeriodConstraint();
            var transferred = false;
            errdefer if (!transferred) freeDdlPeriod(self.alloc, period);
            try periods.append(self.alloc, period);
            transferred = true;
        } else {
            return error.UnsupportedSqlShape;
        }
    }

    fn parseDdlType(self: *@This()) !DdlType {
        const first = self.match(.identifier) orelse return error.UnsupportedSqlShape;
        const base = ddlBaseTypeForName(first.text) orelse blk: {
            if (std.ascii.eqlIgnoreCase(first.text, "character")) {
                try self.expectKeyword("varying");
                break :blk runtime_schema.AntflyType.keyword;
            }
            if (std.ascii.eqlIgnoreCase(first.text, "double")) {
                try self.expectKeyword("precision");
                break :blk runtime_schema.AntflyType.numeric;
            }
            if (std.ascii.eqlIgnoreCase(first.text, "timestamp")) {
                if (self.matchKeyword("with")) {
                    try self.expectKeyword("time");
                    try self.expectKeyword("zone");
                } else if (self.matchKeyword("without")) {
                    try self.expectKeyword("time");
                    try self.expectKeyword("zone");
                }
                break :blk runtime_schema.AntflyType.datetime;
            }
            return error.UnsupportedSqlShape;
        };

        if (self.peekKind(.lparen)) try self.skipParenthesizedTokens();
        const is_array = if (self.match(.lbracket) != null) blk: {
            try self.expect(.rbracket);
            break :blk true;
        } else false;
        if (!is_array) return .{ .field_type = base };
        if (base == .json or base == .array or base == .blob) return error.UnsupportedSqlShape;
        return .{ .field_type = .array, .array_item_type = base };
    }

    fn parseDdlPeriodConstraint(self: *@This()) !runtime_schema.RelationalPeriod {
        try self.expectKeyword("for");
        const name = try self.parseIdentifierOwned();
        var name_transferred = false;
        errdefer if (!name_transferred) self.alloc.free(name);
        try self.expect(.lparen);
        const start_column = try self.parseIdentifierOwned();
        var start_transferred = false;
        errdefer if (!start_transferred) self.alloc.free(start_column);
        try self.expect(.comma);
        const end_column = try self.parseIdentifierOwned();
        var end_transferred = false;
        errdefer if (!end_transferred) self.alloc.free(end_column);
        try self.expect(.rparen);
        name_transferred = true;
        start_transferred = true;
        end_transferred = true;
        return .{ .name = name, .start_column = start_column, .end_column = end_column };
    }

    fn parseDdlDefaultValue(self: *@This(), field_type: runtime_schema.AntflyType) !runtime_schema.RelationalDefaultValue {
        if (self.matchKeyword("null")) {
            return .{ .kind = .literal, .value_json = try self.alloc.dupe(u8, "null") };
        }
        if (self.matchKeyword("gen_random_uuid") or self.matchKeyword("uuid_generate_v4")) {
            try self.expect(.lparen);
            try self.expect(.rparen);
            if (field_type != .keyword and field_type != .text and field_type != .link) return error.UnsupportedSqlShape;
            return .{ .kind = .uuid_v4, .value_json = try self.alloc.dupe(u8, "") };
        }
        if (self.matchKeyword("now")) {
            try self.expect(.lparen);
            try self.expect(.rparen);
            if (field_type != .numeric and field_type != .datetime) return error.UnsupportedSqlShape;
            return .{ .kind = .now_ns, .value_json = try self.alloc.dupe(u8, "") };
        }
        if (self.matchKeyword("current_timestamp")) {
            try self.parseOptionalCurrentTimestampPrecision();
            if (field_type != .numeric and field_type != .datetime) return error.UnsupportedSqlShape;
            return .{ .kind = .now_ns, .value_json = try self.alloc.dupe(u8, "") };
        }
        if (self.matchKeyword("current_date")) {
            if (field_type != .numeric and field_type != .datetime) return error.UnsupportedSqlShape;
            return .{ .kind = .current_date_ns, .value_json = try self.alloc.dupe(u8, "") };
        }
        const value = try self.parseSqlColumnValueAlloc(.{ .name = "", .path = "", .field_type = field_type });
        return .{ .kind = .literal, .value_json = value };
    }

    fn parseDdlDefaultValueUntyped(self: *@This()) !runtime_schema.RelationalDefaultValue {
        if (self.matchKeyword("null")) {
            return .{ .kind = .literal, .value_json = try self.alloc.dupe(u8, "null") };
        }
        if (self.matchKeyword("gen_random_uuid") or self.matchKeyword("uuid_generate_v4")) {
            try self.expect(.lparen);
            try self.expect(.rparen);
            return .{ .kind = .uuid_v4, .value_json = try self.alloc.dupe(u8, "") };
        }
        if (self.matchKeyword("now")) {
            try self.expect(.lparen);
            try self.expect(.rparen);
            return .{ .kind = .now_ns, .value_json = try self.alloc.dupe(u8, "") };
        }
        if (self.matchKeyword("current_timestamp")) {
            try self.parseOptionalCurrentTimestampPrecision();
            return .{ .kind = .now_ns, .value_json = try self.alloc.dupe(u8, "") };
        }
        if (self.matchKeyword("current_date")) {
            return .{ .kind = .current_date_ns, .value_json = try self.alloc.dupe(u8, "") };
        }
        return .{ .kind = .literal, .value_json = try self.parseSqlUntypedValueJsonAlloc() };
    }

    fn parseOptionalCurrentTimestampPrecision(self: *@This()) !void {
        if (self.match(.lparen) == null) return;
        const token = self.match(.number) orelse return error.UnsupportedSqlShape;
        const precision = std.fmt.parseUnsigned(u8, token.text, 10) catch return error.UnsupportedSqlShape;
        if (precision > 6) return error.UnsupportedSqlShape;
        try self.expect(.rparen);
    }

    fn parseDdlCheckConstraint(self: *@This(), constraint_name: ?[]const u8) !runtime_schema.RelationalCheck {
        try self.expect(.lparen);
        const previous_defer_field_validation = self.defer_row_expression_field_validation;
        self.defer_row_expression_field_validation = true;
        defer self.defer_row_expression_field_validation = previous_defer_field_validation;
        const condition = try self.parseDdlCheckExpressionConditionAlloc();
        var condition_transferred = false;
        errdefer if (!condition_transferred) freeExpressionCondition(self.alloc, condition);
        try self.expect(.rparen);
        const name = try self.ddlCheckConstraintNameAlloc(constraint_name, condition);
        var name_transferred = false;
        errdefer if (!name_transferred) self.alloc.free(name);

        if (try self.simpleDdlRelationalCheckFromExpressionConditionAlloc(name, condition)) |check| {
            condition_transferred = false;
            freeExpressionCondition(self.alloc, condition);
            self.alloc.free(name);
            return check;
        }

        const field = try self.alloc.dupe(u8, "");
        var field_transferred = false;
        errdefer if (!field_transferred) self.alloc.free(field);
        const expression = try cloneExpressionConditionAlloc(self.alloc, condition);
        var expression_transferred = false;
        errdefer if (!expression_transferred) freeExpressionCondition(self.alloc, expression);
        condition_transferred = false;
        freeExpressionCondition(self.alloc, condition);
        name_transferred = true;
        field_transferred = true;
        expression_transferred = true;
        return .{ .name = name, .field = field, .expression = expression };
    }

    fn ddlCheckConstraintNameAlloc(
        self: *@This(),
        constraint_name: ?[]const u8,
        condition: db_mod.types.RelationalRowsExpressionCondition,
    ) ![]const u8 {
        if (constraint_name) |name| return try self.alloc.dupe(u8, name);
        if (condition.lhs.kind == .field and condition.lhs.field.len > 0) {
            return try std.fmt.allocPrint(self.alloc, "{s}_{s}_check", .{ condition.lhs.field, relationalCheckOpToken(condition.op) });
        }
        return try std.fmt.allocPrint(self.alloc, "expression_{s}_check", .{relationalCheckOpToken(condition.op)});
    }

    fn simpleDdlRelationalCheckFromExpressionConditionAlloc(
        self: *@This(),
        name: []const u8,
        condition: db_mod.types.RelationalRowsExpressionCondition,
    ) !?runtime_schema.RelationalCheck {
        if (condition.lhs.kind != .field or condition.lhs.field.len == 0 or condition.lhs.field_source != .row) return null;
        const value_json: ?[]const u8 = switch (condition.op) {
            .is_null, .is_not_null => if (condition.rhs.len == 0) null else return null,
            else => blk: {
                if (condition.rhs.len != 1 or condition.rhs[0].kind != .value or condition.rhs[0].value_json.len == 0) return null;
                break :blk condition.rhs[0].value_json;
            },
        };
        const owned_name = try self.alloc.dupe(u8, name);
        var name_transferred = false;
        errdefer if (!name_transferred) self.alloc.free(owned_name);
        const field = try self.alloc.dupe(u8, condition.lhs.field);
        var field_transferred = false;
        errdefer if (!field_transferred) self.alloc.free(field);
        const owned_value = if (value_json) |value| try self.alloc.dupe(u8, value) else null;
        var value_transferred = false;
        errdefer if (!value_transferred) if (owned_value) |value| self.alloc.free(value);
        name_transferred = true;
        field_transferred = true;
        value_transferred = true;
        return .{
            .name = owned_name,
            .field = field,
            .op = condition.op,
            .value_json = owned_value,
        };
    }

    fn parseDdlCheckExpressionConditionAlloc(self: *@This()) !db_mod.types.RelationalRowsExpressionCondition {
        var groups = try self.parseDdlCheckExpressionPredicateGroupsAlloc();
        defer self.alloc.free(groups);
        errdefer freeExpressionPredicateGroups(self.alloc, groups);

        if (groups.len == 1 and groups[0].conditions.len == 1) {
            const conditions = groups[0].conditions;
            const condition = conditions[0];
            groups[0].conditions = &.{};
            self.alloc.free(conditions);
            return condition;
        }

        const expression = try self.booleanExpressionFromPredicateGroupsAlloc(groups);
        var expression_transferred = false;
        errdefer if (!expression_transferred) freeExpression(self.alloc, expression);

        const rhs = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
        var rhs_transferred = false;
        errdefer if (!rhs_transferred) self.alloc.free(rhs);
        rhs[0] = try self.booleanLiteralExpressionAlloc(true);
        var rhs_expression_transferred = false;
        errdefer if (!rhs_expression_transferred) freeExpression(self.alloc, rhs[0]);

        expression_transferred = true;
        rhs_expression_transferred = true;
        rhs_transferred = true;
        return .{
            .lhs = expression,
            .op = .eq,
            .rhs = rhs,
        };
    }

    fn parseDdlCheckExpressionPredicateGroupsAlloc(self: *@This()) anyerror![]db_mod.types.RelationalRowsExpressionPredicateGroup {
        var groups = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
        errdefer {
            freeExpressionPredicateGroups(self.alloc, groups.items);
            groups.deinit(self.alloc);
        }

        while (true) {
            var branch_groups = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
            var branch_groups_transferred = false;
            defer branch_groups.deinit(self.alloc);
            errdefer if (!branch_groups_transferred) freeExpressionPredicateGroups(self.alloc, branch_groups.items);
            try branch_groups.append(self.alloc, .{ .conditions = &.{} });

            while (true) {
                var alternatives = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
                defer alternatives.deinit(self.alloc);
                errdefer freeExpressionPredicateGroups(self.alloc, alternatives.items);
                try self.parseDdlCheckExpressionPredicateFactorAlternatives(&alternatives);
                try self.andExpressionPredicateAlternatives(&branch_groups, alternatives.items);
                freeExpressionPredicateGroups(self.alloc, alternatives.items);
                if (!self.matchKeyword("and")) break;
            }

            if (branch_groups.items.len == 0) return error.UnsupportedSqlShape;
            try groups.appendSlice(self.alloc, branch_groups.items);
            branch_groups_transferred = true;

            if (!self.matchKeyword("or")) break;
        }

        return try groups.toOwnedSlice(self.alloc);
    }

    fn parseDdlCheckExpressionPredicateFactorAlternatives(
        self: *@This(),
        alternatives: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
    ) anyerror!void {
        if (self.matchKeyword("not")) {
            const groups = try self.parseDdlCheckNegatedPredicateGroupsAlloc();
            defer self.alloc.free(groups);
            errdefer freeExpressionPredicateGroups(self.alloc, groups);

            const expression = try self.booleanExpressionFromPredicateGroupsAlloc(groups);
            var expression_transferred = false;
            errdefer if (!expression_transferred) freeExpression(self.alloc, expression);
            const negated = try self.booleanNotExpressionAlloc(expression);
            expression_transferred = true;
            var negated_transferred = false;
            errdefer if (!negated_transferred) freeExpression(self.alloc, negated);
            const condition = try self.booleanExpressionConditionAlloc(negated);
            negated_transferred = true;
            try self.appendExpressionConditionGroup(alternatives, condition);
            return;
        }

        if (self.ddlCheckParenthesizedGroupCanStartAt(self.pos)) {
            try self.expect(.lparen);
            const groups = try self.parseDdlCheckExpressionPredicateGroupsAlloc();
            var groups_transferred = false;
            defer self.alloc.free(groups);
            errdefer if (!groups_transferred) freeExpressionPredicateGroups(self.alloc, groups);
            try self.expect(.rparen);
            try alternatives.appendSlice(self.alloc, groups);
            groups_transferred = true;
            return;
        }

        try self.parseExpressionWhereConditionAlternatives(alternatives);
    }

    fn parseDdlCheckNegatedPredicateGroupsAlloc(self: *@This()) anyerror![]db_mod.types.RelationalRowsExpressionPredicateGroup {
        if (self.ddlCheckParenthesizedGroupCanStartAt(self.pos)) {
            try self.expect(.lparen);
            const groups = try self.parseDdlCheckExpressionPredicateGroupsAlloc();
            errdefer {
                freeExpressionPredicateGroups(self.alloc, groups);
                self.alloc.free(groups);
            }
            try self.expect(.rparen);
            return groups;
        }

        var groups = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
        errdefer {
            freeExpressionPredicateGroups(self.alloc, groups.items);
            groups.deinit(self.alloc);
        }
        try self.parseExpressionWhereConditionAlternatives(&groups);
        return try groups.toOwnedSlice(self.alloc);
    }

    fn ddlCheckParenthesizedGroupCanStartAt(self: *@This(), index: usize) bool {
        if (index >= self.tokens.len or self.tokens[index].kind != .lparen) return false;
        const close = findMatchingRParenIndex(self.tokens, index) orelse return false;
        if (close + 1 >= self.tokens.len) return true;
        const next = self.tokens[close + 1];
        switch (next.kind) {
            .eq, .neq, .gt, .gte, .lt, .lte, .arrow_text, .arrow_json, .path_arrow_text, .path_arrow_json => return false,
            else => {},
        }
        if (next.kind == .identifier) {
            if (std.ascii.eqlIgnoreCase(next.text, "is") or
                std.ascii.eqlIgnoreCase(next.text, "like") or
                std.ascii.eqlIgnoreCase(next.text, "ilike") or
                std.ascii.eqlIgnoreCase(next.text, "in") or
                std.ascii.eqlIgnoreCase(next.text, "between"))
            {
                return false;
            }
            if (std.ascii.eqlIgnoreCase(next.text, "not") and close + 2 < self.tokens.len and self.tokens[close + 2].kind == .identifier) {
                const after_not = self.tokens[close + 2].text;
                if (std.ascii.eqlIgnoreCase(after_not, "like") or
                    std.ascii.eqlIgnoreCase(after_not, "ilike") or
                    std.ascii.eqlIgnoreCase(after_not, "in") or
                    std.ascii.eqlIgnoreCase(after_not, "between"))
                {
                    return false;
                }
            }
        }
        return true;
    }

    fn booleanExpressionFromPredicateGroupsAlloc(
        self: *@This(),
        groups: []db_mod.types.RelationalRowsExpressionPredicateGroup,
    ) !db_mod.types.RelationalRowsExpression {
        if (groups.len == 0) return error.UnsupportedSqlShape;
        if (groups.len == 1) return try self.booleanExpressionFromPredicateGroupAlloc(&groups[0]);

        const operands = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, groups.len);
        var initialized: usize = 0;
        errdefer {
            for (operands[0..initialized]) |operand| freeExpression(self.alloc, operand);
            self.alloc.free(operands);
        }
        for (groups) |*group| {
            operands[initialized] = try self.booleanExpressionFromPredicateGroupAlloc(group);
            initialized += 1;
        }
        return .{
            .kind = .bool_or,
            .operands = operands,
        };
    }

    fn booleanExpressionFromPredicateGroupAlloc(
        self: *@This(),
        group: *db_mod.types.RelationalRowsExpressionPredicateGroup,
    ) !db_mod.types.RelationalRowsExpression {
        if (group.conditions.len == 0) return try self.booleanLiteralExpressionAlloc(true);
        if (group.conditions.len == 1) {
            const conditions = group.conditions;
            const condition = conditions[0];
            @constCast(conditions)[0] = emptyExpressionCondition();
            const expression = try self.booleanExpressionFromConditionAlloc(condition);
            group.conditions = &.{};
            self.alloc.free(conditions);
            return expression;
        }

        const operands = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, group.conditions.len);
        var initialized: usize = 0;
        errdefer {
            for (operands[0..initialized]) |operand| freeExpression(self.alloc, operand);
            self.alloc.free(operands);
        }
        const conditions = group.conditions;
        for (conditions, 0..) |condition, i| {
            @constCast(conditions)[i] = emptyExpressionCondition();
            operands[initialized] = try self.booleanExpressionFromConditionAlloc(condition);
            initialized += 1;
        }
        group.conditions = &.{};
        self.alloc.free(conditions);
        return .{
            .kind = .bool_and,
            .operands = operands,
        };
    }

    fn emptyExpressionCondition() db_mod.types.RelationalRowsExpressionCondition {
        return .{
            .lhs = .{ .kind = .value },
            .op = .eq,
            .rhs = &.{},
        };
    }

    fn booleanNotExpressionAlloc(
        self: *@This(),
        operand: db_mod.types.RelationalRowsExpression,
    ) !db_mod.types.RelationalRowsExpression {
        var operand_transferred = false;
        errdefer if (!operand_transferred) freeExpression(self.alloc, operand);
        const operands = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
        var operands_transferred = false;
        errdefer if (!operands_transferred) self.alloc.free(operands);
        operands[0] = operand;
        operand_transferred = true;
        operands_transferred = true;
        return .{
            .kind = .bool_not,
            .operands = operands,
        };
    }

    fn booleanExpressionConditionAlloc(
        self: *@This(),
        expression: db_mod.types.RelationalRowsExpression,
    ) !db_mod.types.RelationalRowsExpressionCondition {
        var expression_transferred = false;
        errdefer if (!expression_transferred) freeExpression(self.alloc, expression);
        const rhs = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
        var rhs_transferred = false;
        errdefer if (!rhs_transferred) self.alloc.free(rhs);
        rhs[0] = try self.booleanLiteralExpressionAlloc(true);
        var rhs_expression_transferred = false;
        errdefer if (!rhs_expression_transferred) freeExpression(self.alloc, rhs[0]);
        expression_transferred = true;
        rhs_expression_transferred = true;
        rhs_transferred = true;
        return .{
            .lhs = expression,
            .op = .eq,
            .rhs = rhs,
        };
    }

    fn booleanExpressionFromConditionAlloc(
        self: *@This(),
        condition: db_mod.types.RelationalRowsExpressionCondition,
    ) !db_mod.types.RelationalRowsExpression {
        var condition_transferred = false;
        errdefer if (!condition_transferred) freeExpressionCondition(self.alloc, condition);

        const branches = try self.alloc.alloc(db_mod.types.RelationalRowsExpressionCaseBranch, 1);
        var branches_transferred = false;
        errdefer if (!branches_transferred) self.alloc.free(branches);
        const then_expression = try self.booleanLiteralExpressionAlloc(true);
        var then_transferred = false;
        errdefer if (!then_transferred) freeExpression(self.alloc, then_expression);

        const fallback = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
        var fallback_transferred = false;
        errdefer if (!fallback_transferred) self.alloc.free(fallback);
        fallback[0] = try self.booleanLiteralExpressionAlloc(false);
        var fallback_expression_transferred = false;
        errdefer if (!fallback_expression_transferred) freeExpression(self.alloc, fallback[0]);

        branches[0] = .{
            .when = condition,
            .then = then_expression,
        };
        condition_transferred = true;
        then_transferred = true;
        branches_transferred = true;
        fallback_expression_transferred = true;
        fallback_transferred = true;
        return .{
            .kind = .case,
            .case_branches = branches,
            .case_else = fallback,
        };
    }

    fn booleanLiteralExpressionAlloc(self: *@This(), value: bool) !db_mod.types.RelationalRowsExpression {
        return .{
            .kind = .value,
            .value_json = try self.alloc.dupe(u8, if (value) "true" else "false"),
        };
    }

    fn parseDdlForeignKeyConstraint(self: *@This(), constraint_name: ?[]const u8) !runtime_schema.ForeignKey {
        try self.expectKeyword("key");
        const child = try self.parseDdlForeignKeyColumnListAlloc();
        var child_transferred = false;
        errdefer if (!child_transferred) child.deinit(self.alloc);

        try self.expectKeyword("references");
        const parent_table = try self.parseSqlObjectIdentifierOwned();
        var parent_table_transferred = false;
        errdefer if (!parent_table_transferred) self.alloc.free(parent_table);
        const parent = try self.parseDdlForeignKeyColumnListAlloc();
        var parent_transferred = false;
        errdefer if (!parent_transferred) parent.deinit(self.alloc);

        const options = try self.parseDdlForeignKeyOptions();
        if ((child.period == null) != (parent.period == null)) return error.UnsupportedSqlShape;
        if (child.period != null and !foreignKeyActionIsRestrictive(options.on_update)) return error.UnsupportedSqlShape;

        const name = if (constraint_name) |existing|
            try self.alloc.dupe(u8, existing)
        else
            try std.fmt.allocPrint(self.alloc, "{s}_{s}_fkey", .{ parent_table, child.columns[0] });
        var name_transferred = false;
        errdefer if (!name_transferred) self.alloc.free(name);

        child_transferred = true;
        parent_table_transferred = true;
        parent_transferred = true;
        name_transferred = true;
        return .{
            .name = name,
            .child_columns = child.columns,
            .child_period = child.period,
            .parent_table = parent_table,
            .parent_columns = parent.columns,
            .parent_period = parent.period,
            .on_delete = options.on_delete,
            .on_update = options.on_update,
            .deferrable = options.deferrable,
            .timing = options.timing,
        };
    }

    const DdlForeignKeyColumnList = struct {
        columns: []const []const u8,
        period: ?[]const u8 = null,

        fn deinit(self: @This(), alloc: std.mem.Allocator) void {
            freeStringSlice(alloc, self.columns);
            if (self.period) |period| alloc.free(period);
        }
    };

    fn parseDdlForeignKeyColumnListAlloc(self: *@This()) !DdlForeignKeyColumnList {
        try self.expect(.lparen);
        var columns = std.ArrayListUnmanaged([]const u8).empty;
        errdefer {
            for (columns.items) |column| self.alloc.free(column);
            columns.deinit(self.alloc);
        }
        var period: ?[]const u8 = null;
        errdefer if (period) |value| self.alloc.free(value);
        while (true) {
            if (self.matchKeyword("period")) {
                if (period != null) return error.UnsupportedSqlShape;
                period = try self.parseIdentifierOwned();
            } else {
                const column = try self.parseIdentifierOwned();
                var transferred = false;
                errdefer if (!transferred) self.alloc.free(column);
                try columns.append(self.alloc, column);
                transferred = true;
            }
            if (self.match(.comma) == null) break;
        }
        try self.expect(.rparen);
        if (columns.items.len == 0) return error.UnsupportedSqlShape;
        try validateSqlIdentifierListUnique(columns.items);
        const owned_columns = try columns.toOwnedSlice(self.alloc);
        errdefer freeStringSlice(self.alloc, owned_columns);
        const owned_period = period;
        period = null;
        return .{ .columns = owned_columns, .period = owned_period };
    }

    fn parseDdlInlineForeignKeyConstraint(
        self: *@This(),
        column_name: []const u8,
        constraint_name: ?[]const u8,
    ) !runtime_schema.ForeignKey {
        const child_columns = try cloneStringSlice(self.alloc, &.{column_name});
        var child_transferred = false;
        errdefer if (!child_transferred) freeStringSlice(self.alloc, child_columns);

        const parent_table = try self.parseSqlObjectIdentifierOwned();
        var parent_table_transferred = false;
        errdefer if (!parent_table_transferred) self.alloc.free(parent_table);

        const parent_columns = if (self.peekKind(.lparen))
            try self.parseDdlColumnListAlloc()
        else
            try cloneStringSlice(self.alloc, &.{"id"});
        var parent_transferred = false;
        errdefer if (!parent_transferred) freeStringSlice(self.alloc, parent_columns);

        const options = try self.parseDdlForeignKeyOptions();

        const name = if (constraint_name) |existing|
            try self.alloc.dupe(u8, existing)
        else
            try std.fmt.allocPrint(self.alloc, "{s}_{s}_fkey", .{ parent_table, child_columns[0] });
        var name_transferred = false;
        errdefer if (!name_transferred) self.alloc.free(name);

        child_transferred = true;
        parent_table_transferred = true;
        parent_transferred = true;
        name_transferred = true;
        return .{
            .name = name,
            .child_columns = child_columns,
            .parent_table = parent_table,
            .parent_columns = parent_columns,
            .on_delete = options.on_delete,
            .on_update = options.on_update,
            .deferrable = options.deferrable,
            .timing = options.timing,
        };
    }

    const DdlForeignKeyOptions = struct {
        on_delete: runtime_schema.ForeignKeyAction = .restrict,
        on_update: runtime_schema.ForeignKeyAction = .restrict,
        deferrable: bool = false,
        timing: runtime_schema.ForeignKeyTiming = .immediate,
    };

    fn parseDdlForeignKeyOptions(self: *@This()) !DdlForeignKeyOptions {
        var options: DdlForeignKeyOptions = .{};
        while (!self.atEnd() and !self.peekKind(.comma) and !self.peekKind(.rparen) and !self.peekKind(.semicolon)) {
            if (self.peekDdlNotValid()) break;
            if (self.matchKeyword("on")) {
                if (self.matchKeyword("delete")) {
                    options.on_delete = try self.parseDdlForeignKeyAction();
                } else if (self.matchKeyword("update")) {
                    options.on_update = try self.parseDdlForeignKeyAction();
                } else {
                    return error.UnsupportedSqlShape;
                }
            } else if (self.matchKeyword("deferrable")) {
                options.deferrable = true;
            } else if (self.matchKeyword("not")) {
                try self.expectKeyword("deferrable");
                options.deferrable = false;
            } else if (self.matchKeyword("initially")) {
                if (self.matchKeyword("deferred")) {
                    options.timing = .deferred;
                    options.deferrable = true;
                } else {
                    try self.expectKeyword("immediate");
                    options.timing = .immediate;
                }
            } else {
                return error.UnsupportedSqlShape;
            }
        }
        return options;
    }

    fn consumeOptionalDdlNotValid(self: *@This()) bool {
        if (!self.peekDdlNotValid()) return false;
        self.pos += 2;
        return true;
    }

    fn peekDdlNotValid(self: *@This()) bool {
        if (self.pos + 1 >= self.tokens.len) return false;
        const not_token = self.tokens[self.pos];
        const valid_token = self.tokens[self.pos + 1];
        return not_token.kind == .identifier and valid_token.kind == .identifier and
            std.ascii.eqlIgnoreCase(not_token.text, "not") and
            std.ascii.eqlIgnoreCase(valid_token.text, "valid");
    }

    fn parseDdlForeignKeyAction(self: *@This()) !runtime_schema.ForeignKeyAction {
        if (self.matchKeyword("cascade")) return .cascade;
        if (self.matchKeyword("restrict")) return .restrict;
        if (self.matchKeyword("no")) {
            try self.expectKeyword("action");
            return .no_action;
        }
        if (self.matchKeyword("set")) {
            try self.expectKeyword("null");
            return .set_null;
        }
        return error.UnsupportedSqlShape;
    }

    fn parseDdlColumnListAlloc(self: *@This()) ![]const []const u8 {
        try self.expect(.lparen);
        var columns = std.ArrayListUnmanaged([]const u8).empty;
        errdefer {
            for (columns.items) |column| self.alloc.free(column);
            columns.deinit(self.alloc);
        }
        while (true) {
            const column = try self.parseIdentifierOwned();
            var transferred = false;
            errdefer if (!transferred) self.alloc.free(column);
            try columns.append(self.alloc, column);
            transferred = true;
            if (self.match(.comma) == null) break;
        }
        try self.expect(.rparen);
        try validateSqlIdentifierListUnique(columns.items);
        return try columns.toOwnedSlice(self.alloc);
    }

    const DdlTemporalColumnList = struct {
        columns: []const []const u8,
        without_overlaps_period: ?[]const u8 = null,

        fn deinit(self: @This(), alloc: std.mem.Allocator) void {
            freeStringSlice(alloc, self.columns);
            if (self.without_overlaps_period) |period| alloc.free(period);
        }
    };

    fn parseDdlTemporalColumnListAlloc(self: *@This()) !DdlTemporalColumnList {
        try self.expect(.lparen);
        var columns = std.ArrayListUnmanaged([]const u8).empty;
        errdefer {
            for (columns.items) |column| self.alloc.free(column);
            columns.deinit(self.alloc);
        }
        var without_overlaps_period: ?[]const u8 = null;
        errdefer if (without_overlaps_period) |period| self.alloc.free(period);
        while (true) {
            const column = try self.parseIdentifierOwned();
            var column_transferred = false;
            errdefer if (!column_transferred) self.alloc.free(column);
            if (self.matchKeyword("without")) {
                try self.expectKeyword("overlaps");
                if (without_overlaps_period != null) return error.UnsupportedSqlShape;
                without_overlaps_period = column;
                column_transferred = true;
            } else {
                try columns.append(self.alloc, column);
                column_transferred = true;
            }
            if (self.match(.comma) == null) break;
        }
        try self.expect(.rparen);
        if (columns.items.len == 0) return error.UnsupportedSqlShape;
        try validateSqlIdentifierListUnique(columns.items);
        const owned_columns = try columns.toOwnedSlice(self.alloc);
        errdefer freeStringSlice(self.alloc, owned_columns);
        const period = without_overlaps_period;
        without_overlaps_period = null;
        return .{ .columns = owned_columns, .without_overlaps_period = period };
    }

    fn parseDdlUniquePredicatesAlloc(self: *@This()) ![]const runtime_schema.UniquePredicate {
        var predicates = std.ArrayListUnmanaged(runtime_schema.UniquePredicate).empty;
        errdefer {
            for (predicates.items) |predicate| {
                self.alloc.free(predicate.field);
                if (predicate.value_json) |value| self.alloc.free(value);
            }
            predicates.deinit(self.alloc);
        }
        while (true) {
            const atom_start = self.pos;
            var depth: usize = 0;
            while (self.pos < self.tokens.len) {
                const token = self.tokens[self.pos];
                if (depth == 0 and token.kind == .identifier and std.ascii.eqlIgnoreCase(token.text, "and")) break;
                if (depth == 0 and token.kind == .semicolon) break;
                switch (token.kind) {
                    .lparen => depth += 1,
                    .rparen => {
                        if (depth == 0) return error.UnsupportedSqlShape;
                        depth -= 1;
                    },
                    else => {},
                }
                self.pos += 1;
            }
            if (depth != 0 or atom_start == self.pos) return error.UnsupportedSqlShape;

            const predicate = try self.parseDdlUniquePredicateAtomAlloc(self.tokens[atom_start..self.pos]);
            var predicate_transferred = false;
            errdefer if (!predicate_transferred) {
                self.alloc.free(predicate.field);
                if (predicate.value_json) |value| self.alloc.free(value);
            };
            try predicates.append(self.alloc, predicate);
            predicate_transferred = true;
            if (!self.matchKeyword("and")) break;
        }
        return try predicates.toOwnedSlice(self.alloc);
    }

    fn parseDdlUniquePredicateAtomAlloc(self: *@This(), raw_tokens: []const Token) !runtime_schema.UniquePredicate {
        const tokens = stripDdlPredicateOuterParens(raw_tokens);
        if (tokens.len == 0) return error.UnsupportedSqlShape;

        var idx: usize = 0;
        const field_token = try parseDdlPredicateIdentifierOperand(tokens, &idx);
        const field = try self.alloc.dupe(u8, field_token.text);
        var field_transferred = false;
        errdefer if (!field_transferred) self.alloc.free(field);

        if (idx >= tokens.len) return error.UnsupportedSqlShape;
        if (tokens[idx].kind == .identifier and std.ascii.eqlIgnoreCase(tokens[idx].text, "is")) {
            idx += 1;
            const op: runtime_schema.UniquePredicateOp = if (idx < tokens.len and tokens[idx].kind == .identifier and std.ascii.eqlIgnoreCase(tokens[idx].text, "not")) blk: {
                idx += 1;
                if (idx >= tokens.len or tokens[idx].kind != .identifier or !std.ascii.eqlIgnoreCase(tokens[idx].text, "null")) return error.UnsupportedSqlShape;
                idx += 1;
                break :blk .is_not_null;
            } else blk: {
                if (idx >= tokens.len or tokens[idx].kind != .identifier or !std.ascii.eqlIgnoreCase(tokens[idx].text, "null")) return error.UnsupportedSqlShape;
                idx += 1;
                break :blk .is_null;
            };
            if (idx != tokens.len) return error.UnsupportedSqlShape;
            field_transferred = true;
            return .{ .field = field, .op = op };
        }

        const op: runtime_schema.UniquePredicateOp = if (tokens[idx].kind == .eq) .eq else if (tokens[idx].kind == .neq) .ne else return error.UnsupportedSqlShape;
        idx += 1;
        if (idx >= tokens.len) return error.UnsupportedSqlShape;
        const value_json = try self.sqlUntypedValueTokensJsonAlloc(tokens, &idx);
        var value_transferred = false;
        errdefer if (!value_transferred) self.alloc.free(value_json);
        if (idx != tokens.len) return error.UnsupportedSqlShape;

        field_transferred = true;
        value_transferred = true;
        return .{ .field = field, .op = op, .value_json = value_json };
    }

    fn sqlUntypedValueTokensJsonAlloc(self: *@This(), tokens: []const Token, idx: *usize) ![]const u8 {
        if (idx.* >= tokens.len) return error.UnsupportedSqlShape;
        const token = tokens[idx.*];
        if (token.kind == .minus) {
            idx.* += 1;
            if (idx.* >= tokens.len) return error.UnsupportedSqlShape;
            const number = tokens[idx.*];
            if (number.kind != .number) return error.UnsupportedSqlShape;
            idx.* += 1;
            return try std.fmt.allocPrint(self.alloc, "-{s}", .{number.text});
        }
        idx.* += 1;
        if (token.kind == .identifier and std.ascii.eqlIgnoreCase(token.text, "true")) return try self.alloc.dupe(u8, "true");
        if (token.kind == .identifier and std.ascii.eqlIgnoreCase(token.text, "false")) return try self.alloc.dupe(u8, "false");
        if (token.kind == .identifier and std.ascii.eqlIgnoreCase(token.text, "null")) return try self.alloc.dupe(u8, "null");
        if (token.kind == .string) return try std.json.Stringify.valueAlloc(self.alloc, token.text, .{});
        if (token.kind == .number) return try self.alloc.dupe(u8, token.text);
        return error.UnsupportedSqlShape;
    }

    fn installDdlPrimaryKey(
        self: *@This(),
        primary_key: *?runtime_schema.PrimaryKey,
        constraint_name: ?[]const u8,
        columns: []const []const u8,
        without_overlaps_period: ?[]const u8,
    ) !void {
        if (primary_key.* != null) return error.UnsupportedSqlShape;
        primary_key.* = try self.makeDdlPrimaryKey(constraint_name, columns, without_overlaps_period);
    }

    fn makeDdlPrimaryKey(
        self: *@This(),
        constraint_name: ?[]const u8,
        columns: []const []const u8,
        without_overlaps_period: ?[]const u8,
    ) !runtime_schema.PrimaryKey {
        const name = if (constraint_name) |value| try self.alloc.dupe(u8, value) else null;
        errdefer if (name) |value| self.alloc.free(value);
        const cloned_columns = try cloneStringSlice(self.alloc, columns);
        errdefer freeStringSlice(self.alloc, cloned_columns);
        const period = if (without_overlaps_period) |value| try self.alloc.dupe(u8, value) else null;
        return .{
            .name = name,
            .columns = cloned_columns,
            .without_overlaps_period = period,
        };
    }

    fn appendDdlUniqueConstraint(
        self: *@This(),
        unique_constraints: *std.ArrayListUnmanaged(runtime_schema.UniqueConstraint),
        constraint_name: ?[]const u8,
        columns: []const []const u8,
        without_overlaps_period: ?[]const u8,
    ) !void {
        const constraint = try self.makeDdlUniqueConstraint(constraint_name, columns, without_overlaps_period);
        var transferred = false;
        errdefer if (!transferred) freeDdlUniqueConstraint(self.alloc, constraint);
        try unique_constraints.append(self.alloc, constraint);
        transferred = true;
    }

    fn makeDdlUniqueConstraint(
        self: *@This(),
        constraint_name: ?[]const u8,
        columns: []const []const u8,
        without_overlaps_period: ?[]const u8,
    ) !runtime_schema.UniqueConstraint {
        const owned_columns = try cloneStringSlice(self.alloc, columns);
        var columns_transferred = false;
        errdefer if (!columns_transferred) freeStringSlice(self.alloc, owned_columns);
        const name = if (constraint_name) |existing|
            try self.alloc.dupe(u8, existing)
        else
            try self.defaultUniqueConstraintNameAlloc(columns);
        var name_transferred = false;
        errdefer if (!name_transferred) self.alloc.free(name);
        columns_transferred = true;
        name_transferred = true;
        const owned_period = if (without_overlaps_period) |period| try self.alloc.dupe(u8, period) else null;
        var period_transferred = false;
        errdefer if (!period_transferred) if (owned_period) |period| self.alloc.free(period);
        period_transferred = true;
        return .{ .name = name, .columns = owned_columns, .without_overlaps_period = owned_period };
    }

    fn defaultUniqueConstraintNameAlloc(self: *@This(), columns: []const []const u8) ![]const u8 {
        var buf = std.ArrayListUnmanaged(u8).empty;
        errdefer buf.deinit(self.alloc);
        try buf.appendSlice(self.alloc, columns[0]);
        for (columns[1..]) |column| {
            try buf.append(self.alloc, '_');
            try buf.appendSlice(self.alloc, column);
        }
        try buf.appendSlice(self.alloc, "_key");
        return try buf.toOwnedSlice(self.alloc);
    }

    fn parseSqlUntypedValueJsonAlloc(self: *@This()) ![]const u8 {
        if (self.matchKeyword("true")) return try self.alloc.dupe(u8, "true");
        if (self.matchKeyword("false")) return try self.alloc.dupe(u8, "false");
        if (self.matchKeyword("null")) return try self.alloc.dupe(u8, "null");
        if (self.match(.string)) |token| return try std.json.Stringify.valueAlloc(self.alloc, token.text, .{});
        if (self.match(.number)) |token| return try self.alloc.dupe(u8, token.text);
        if (self.match(.minus) != null) return try self.parseNegativeNumberJsonAlloc();
        return error.UnsupportedSqlShape;
    }

    fn parseNegativeNumberJsonAlloc(self: *@This()) ![]const u8 {
        const token = self.match(.number) orelse return error.UnsupportedSqlShape;
        return try std.fmt.allocPrint(self.alloc, "-{s}", .{token.text});
    }

    fn skipParenthesizedTokens(self: *@This()) !void {
        try self.expect(.lparen);
        var depth: usize = 1;
        while (self.pos < self.tokens.len and depth > 0) {
            if (self.match(.lparen) != null) {
                depth += 1;
            } else if (self.match(.rparen) != null) {
                depth -= 1;
            } else {
                self.pos += 1;
            }
        }
        if (depth != 0) return error.UnsupportedSqlShape;
    }

    fn parseCtesForPlanAlloc(
        self: *@This(),
        base_table_name: *?[]const u8,
    ) ![]const db_mod.types.RelationalRowsCte {
        try self.expectKeyword("with");
        var ctes = std.ArrayListUnmanaged(db_mod.types.RelationalRowsCte).empty;
        errdefer {
            for (ctes.items) |cte| {
                var owned = cte;
                owned.deinit(self.alloc);
            }
            ctes.deinit(self.alloc);
        }

        while (true) {
            const cte_name = try self.parseIdentifierOwned();
            var cte_name_transferred = false;
            errdefer if (!cte_name_transferred) self.alloc.free(cte_name);
            if (findCteByName(ctes.items, cte_name) != null) return error.UnsupportedSqlShape;
            try self.expectKeyword("as");
            try self.expect(.lparen);
            const close_index = try self.findMatchingRParen();
            var sub = Parser{
                .alloc = self.alloc,
                .tokens = self.tokens[self.pos..close_index],
                .schema = self.schema,
                .params = self.params,
                .unique_resolver = self.unique_resolver,
            };
            var lowered = try sub.parseSelect();
            errdefer lowered.deinit(self.alloc);
            self.pos = close_index + 1;
            try self.resolveSelectSourceForPlan(&lowered, ctes.items, base_table_name);
            try ctes.append(self.alloc, .{
                .name = cte_name,
                .query = lowered.query,
            });
            lowered.query = .{};
            lowered.clearSelectOutputs(self.alloc);
            self.alloc.free(lowered.table_name);
            lowered.table_name = "";
            cte_name_transferred = true;
            if (self.match(.comma) == null) break;
        }

        return try ctes.toOwnedSlice(self.alloc);
    }

    fn parseQueryPlan(self: *@This()) !LoweredQueryPlan {
        if (!self.peekKeyword("with")) {
            var lowered = try self.parseSelectWithSetBoundary(true);
            errdefer lowered.deinit(self.alloc);
            if (!self.atEnd()) {
                const op = try self.parseSelectSetOperation();
                var rhs = try self.parseSelectWithSetResultTailBoundary();
                defer rhs.deinit(self.alloc);
                try self.applySimpleSelectSetOperation(&lowered, rhs, op);
                try self.parseSimpleSelectSetResultTail(&lowered);
            }
            const table_name = lowered.table_name;
            lowered.table_name = "";
            lowered.clearSelectOutputs(self.alloc);
            return .{
                .table_name = table_name,
                .plan = .{ .query = lowered.query },
            };
        }

        try self.expectKeyword("with");
        var ctes = std.ArrayListUnmanaged(db_mod.types.RelationalRowsCte).empty;
        errdefer {
            for (ctes.items) |cte| {
                self.alloc.free(cte.name);
                var query = cte.query;
                query.deinit(self.alloc);
            }
            ctes.deinit(self.alloc);
        }
        var base_table_name: ?[]const u8 = null;
        defer if (base_table_name) |table| self.alloc.free(table);

        while (true) {
            const cte_name = try self.parseIdentifierOwned();
            var cte_name_transferred = false;
            errdefer if (!cte_name_transferred) self.alloc.free(cte_name);
            if (findCteByName(ctes.items, cte_name) != null) return error.UnsupportedSqlShape;
            try self.expectKeyword("as");
            try self.expect(.lparen);
            const close_index = try self.findMatchingRParen();
            var sub = Parser{
                .alloc = self.alloc,
                .tokens = self.tokens[self.pos..close_index],
                .schema = self.schema,
                .params = self.params,
                .unique_resolver = self.unique_resolver,
            };
            var lowered = try sub.parseSelect();
            errdefer lowered.deinit(self.alloc);
            self.pos = close_index + 1;
            try self.resolveSelectSourceForPlan(&lowered, ctes.items, &base_table_name);
            try ctes.append(self.alloc, .{
                .name = cte_name,
                .query = lowered.query,
            });
            lowered.query = .{};
            lowered.clearSelectOutputs(self.alloc);
            self.alloc.free(lowered.table_name);
            lowered.table_name = "";
            cte_name_transferred = true;
            if (self.match(.comma) == null) break;
        }

        var final = try self.parseSelectWithSetBoundary(true);
        errdefer final.deinit(self.alloc);
        try self.resolveSelectSourceForPlan(&final, ctes.items, &base_table_name);
        if (!self.atEnd()) {
            const op = try self.parseSelectSetOperation();
            var rhs = try self.parseSelectWithSetResultTailBoundary();
            defer rhs.deinit(self.alloc);
            try self.resolveSelectSourceForPlan(&rhs, ctes.items, &base_table_name);
            try self.applySimpleSelectSetOperation(&final, rhs, op);
            try self.parseSimpleSelectSetResultTail(&final);
        }
        if (self.match(.semicolon) != null and !self.atEnd()) return error.UnsupportedSqlShape;
        if (!self.atEnd()) return error.UnsupportedSqlShape;

        const table_name = base_table_name orelse return error.UnsupportedSqlShape;
        base_table_name = null;
        const owned_ctes = try ctes.toOwnedSlice(self.alloc);
        self.alloc.free(final.table_name);
        final.table_name = "";
        final.clearSelectOutputs(self.alloc);
        return .{
            .table_name = table_name,
            .plan = .{
                .ctes = owned_ctes,
                .query = final.query,
            },
        };
    }

    fn parseSelectWithSetBoundary(self: *@This(), allow_boundary: bool) !LoweredSelect {
        const previous = self.allow_select_set_boundary;
        self.allow_select_set_boundary = allow_boundary;
        defer self.allow_select_set_boundary = previous;
        return try self.parseSelect();
    }

    fn parseSelectWithSetResultTailBoundary(self: *@This()) !LoweredSelect {
        const previous = self.allow_select_set_result_tail_boundary;
        self.allow_select_set_result_tail_boundary = true;
        defer self.allow_select_set_result_tail_boundary = previous;
        return try self.parseSelect();
    }

    fn parseSelectSetOperation(self: *@This()) !SelectSetOperation {
        const op: SelectSetOperation = if (self.matchKeyword("union")) blk: {
            if (self.matchKeyword("all")) break :blk .union_all;
            break :blk .union_distinct;
        } else if (self.matchKeyword("intersect"))
            .intersect
        else if (self.matchKeyword("except"))
            .except
        else
            return error.UnsupportedSqlShape;
        _ = self.matchKeyword("distinct");
        return op;
    }

    fn applySimpleSelectSetOperation(
        self: *@This(),
        lhs: *LoweredSelect,
        rhs: LoweredSelect,
        op: SelectSetOperation,
    ) !void {
        if (!std.mem.eql(u8, lhs.table_name, rhs.table_name)) return error.UnsupportedSqlShape;
        try self.validateSimpleSetOperationSelect(lhs.query, rhs.query);
        if (!simpleSelectProjectionsEqual(lhs.query, rhs.query, lhs.select_outputs, rhs.select_outputs)) return error.UnsupportedSqlShape;

        switch (op) {
            .union_distinct => try self.applySimpleUnion(lhs, rhs.query),
            .union_all => try self.applySimpleUnionAll(lhs, rhs.query),
            .intersect => try self.applySimpleIntersect(lhs, rhs.query),
            .except => try self.applySimpleExcept(lhs, rhs.query),
        }
    }

    fn parseSimpleSelectSetResultTail(self: *@This(), lowered: *LoweredSelect) !void {
        var order_by = std.ArrayListUnmanaged(db_mod.types.RelationalRowsQueryOrder).empty;
        errdefer {
            freeOrderBy(self.alloc, order_by.items);
            order_by.deinit(self.alloc);
        }
        const select = SelectList{
            .fields = lowered.query.select,
            .json_extract = lowered.query.json_extract,
            .array_length = lowered.query.array_length,
            .coalesce = lowered.query.coalesce,
            .field_aliases = lowered.query.field_aliases,
            .expressions = lowered.query.expressions,
            .outputs = lowered.select_outputs,
            .select_all = lowered.query.select_all,
        };

        while (!self.atEnd()) {
            if (self.matchKeyword("order")) {
                if (order_by.items.len > 0) return error.UnsupportedSqlShape;
                try self.expectKeyword("by");
                try self.parseSelectOutputOrderBy(&order_by, select);
            } else if (self.matchKeyword("limit")) {
                if (lowered.query.limit != null) return error.UnsupportedSqlShape;
                lowered.query.limit = try self.parseLimitValue();
            } else if (self.matchKeyword("offset")) {
                if (lowered.query.offset != 0) return error.UnsupportedSqlShape;
                lowered.query.offset = try self.parseOffsetValue();
            } else if (self.matchKeyword("fetch")) {
                if (lowered.query.limit != null) return error.UnsupportedSqlShape;
                lowered.query.limit = try self.parseFetchLimitValue();
            } else if (self.match(.semicolon) != null) {
                if (!self.atEnd()) return error.UnsupportedSqlShape;
            } else {
                return error.UnsupportedSqlShape;
            }
        }

        if (order_by.items.len > 0) {
            lowered.query.order_by = try order_by.toOwnedSlice(self.alloc);
        }
    }

    fn validateSimpleSetOperationSelect(
        self: *@This(),
        lhs: db_mod.types.RelationalRowsQueryRequest,
        rhs: db_mod.types.RelationalRowsQueryRequest,
    ) !void {
        _ = self;
        if (!std.mem.eql(u8, lhs.source_cte, rhs.source_cte)) return error.UnsupportedSqlShape;
        _ = querySimpleSetPredicateMode(lhs) orelse return error.UnsupportedSqlShape;
        _ = querySimpleSetPredicateMode(rhs) orelse return error.UnsupportedSqlShape;
    }

    fn applySimpleUnion(
        self: *@This(),
        lhs: *LoweredSelect,
        rhs: db_mod.types.RelationalRowsQueryRequest,
    ) !void {
        if (queryHasNoSimpleSetPredicates(lhs.query) or queryHasNoSimpleSetPredicates(rhs)) {
            freeRelationalChecks(self.alloc, lhs.query.predicates);
            if (lhs.query.predicates.len > 0) self.alloc.free(lhs.query.predicates);
            lhs.query.predicates = &.{};
            freeExpressionConditions(self.alloc, lhs.query.expression_predicates);
            if (lhs.query.expression_predicates.len > 0) self.alloc.free(lhs.query.expression_predicates);
            lhs.query.expression_predicates = &.{};
            return;
        }
        if (lhs.query.expression_predicates.len > 0 or rhs.expression_predicates.len > 0) {
            return try self.applySimpleExpressionUnion(lhs, rhs);
        }

        const groups = try self.alloc.alloc(db_mod.types.RelationalRowsPredicateGroup, 2);
        var initialized: usize = 0;
        errdefer {
            for (groups[0..initialized]) |group| freePredicateGroup(self.alloc, group);
            self.alloc.free(groups);
        }
        groups[0] = .{ .predicates = try cloneQueryRelationalChecksAlloc(self.alloc, lhs.query.predicates) };
        initialized += 1;
        groups[1] = .{ .predicates = try cloneQueryRelationalChecksAlloc(self.alloc, rhs.predicates) };
        initialized += 1;

        freeRelationalChecks(self.alloc, lhs.query.predicates);
        if (lhs.query.predicates.len > 0) self.alloc.free(lhs.query.predicates);
        lhs.query.predicates = &.{};
        freePredicateGroups(self.alloc, lhs.query.or_predicates);
        if (lhs.query.or_predicates.len > 0) self.alloc.free(lhs.query.or_predicates);
        lhs.query.or_predicates = groups;
    }

    fn applySimpleUnionAll(
        self: *@This(),
        lhs: *LoweredSelect,
        rhs: db_mod.types.RelationalRowsQueryRequest,
    ) !void {
        if (!simpleSetQueriesProvablyDisjoint(lhs.query, rhs)) return error.UnsupportedSqlShape;
        try self.applySimpleUnion(lhs, rhs);
    }

    fn applySimpleExpressionUnion(
        self: *@This(),
        lhs: *LoweredSelect,
        rhs: db_mod.types.RelationalRowsQueryRequest,
    ) !void {
        const groups = try self.alloc.alloc(db_mod.types.RelationalRowsExpressionPredicateGroup, 2);
        var initialized: usize = 0;
        errdefer {
            for (groups[0..initialized]) |group| freeExpressionPredicateGroup(self.alloc, group);
            self.alloc.free(groups);
        }
        groups[0] = .{ .conditions = try expressionConditionsFromSimpleSetQueryAlloc(self.alloc, lhs.query) };
        initialized += 1;
        groups[1] = .{ .conditions = try expressionConditionsFromSimpleSetQueryAlloc(self.alloc, rhs) };
        initialized += 1;

        freeRelationalChecks(self.alloc, lhs.query.predicates);
        if (lhs.query.predicates.len > 0) self.alloc.free(lhs.query.predicates);
        lhs.query.predicates = &.{};
        freeExpressionConditions(self.alloc, lhs.query.expression_predicates);
        if (lhs.query.expression_predicates.len > 0) self.alloc.free(lhs.query.expression_predicates);
        lhs.query.expression_predicates = &.{};
        freeExpressionPredicateGroups(self.alloc, lhs.query.expression_or_predicates);
        if (lhs.query.expression_or_predicates.len > 0) self.alloc.free(lhs.query.expression_or_predicates);
        lhs.query.expression_or_predicates = groups;
    }

    fn applySimpleIntersect(
        self: *@This(),
        lhs: *LoweredSelect,
        rhs: db_mod.types.RelationalRowsQueryRequest,
    ) !void {
        if (rhs.predicates.len > 0) {
            const predicates = try cloneQueryRelationalChecksConcatAlloc(self.alloc, lhs.query.predicates, rhs.predicates);
            freeRelationalChecks(self.alloc, lhs.query.predicates);
            if (lhs.query.predicates.len > 0) self.alloc.free(lhs.query.predicates);
            lhs.query.predicates = predicates;
        }
        if (rhs.expression_predicates.len > 0) {
            const expression_predicates = try cloneExpressionConditionsConcatAlloc(self.alloc, lhs.query.expression_predicates, rhs.expression_predicates);
            freeExpressionConditions(self.alloc, lhs.query.expression_predicates);
            if (lhs.query.expression_predicates.len > 0) self.alloc.free(lhs.query.expression_predicates);
            lhs.query.expression_predicates = expression_predicates;
        }
    }

    fn applySimpleExcept(
        self: *@This(),
        lhs: *LoweredSelect,
        rhs: db_mod.types.RelationalRowsQueryRequest,
    ) !void {
        if (rhs.predicates.len == 0 and rhs.expression_predicates.len == 0) return error.UnsupportedSqlShape;
        if (rhs.expression_predicates.len > 0) {
            const groups = try self.alloc.alloc(db_mod.types.RelationalRowsExpressionPredicateGroup, 1);
            var initialized: usize = 0;
            errdefer {
                for (groups[0..initialized]) |group| freeExpressionPredicateGroup(self.alloc, group);
                self.alloc.free(groups);
            }
            groups[0] = .{ .conditions = try expressionConditionsFromSimpleSetQueryAlloc(self.alloc, rhs) };
            initialized += 1;
            freeExpressionPredicateGroups(self.alloc, lhs.query.expression_not_predicates);
            if (lhs.query.expression_not_predicates.len > 0) self.alloc.free(lhs.query.expression_not_predicates);
            lhs.query.expression_not_predicates = groups;
            return;
        }
        const groups = try self.alloc.alloc(db_mod.types.RelationalRowsPredicateGroup, 1);
        var initialized: usize = 0;
        errdefer {
            for (groups[0..initialized]) |group| freePredicateGroup(self.alloc, group);
            self.alloc.free(groups);
        }
        groups[0] = .{ .predicates = try cloneQueryRelationalChecksAlloc(self.alloc, rhs.predicates) };
        initialized += 1;
        freePredicateGroups(self.alloc, lhs.query.not_predicates);
        if (lhs.query.not_predicates.len > 0) self.alloc.free(lhs.query.not_predicates);
        lhs.query.not_predicates = groups;
    }

    fn parseWindowPlan(self: *@This()) !LoweredWindowPlan {
        if (!self.peekKeyword("with")) return try self.parseWindowSelect();

        try self.expectKeyword("with");
        var ctes = std.ArrayListUnmanaged(db_mod.types.RelationalRowsCte).empty;
        errdefer {
            for (ctes.items) |cte| {
                self.alloc.free(cte.name);
                var query = cte.query;
                query.deinit(self.alloc);
            }
            ctes.deinit(self.alloc);
        }
        var base_table_name: ?[]const u8 = null;
        defer if (base_table_name) |table| self.alloc.free(table);

        while (true) {
            const cte_name = try self.parseIdentifierOwned();
            var cte_name_transferred = false;
            errdefer if (!cte_name_transferred) self.alloc.free(cte_name);
            if (findCteByName(ctes.items, cte_name) != null) return error.UnsupportedSqlShape;
            try self.expectKeyword("as");
            try self.expect(.lparen);
            const close_index = try self.findMatchingRParen();
            var sub = Parser{
                .alloc = self.alloc,
                .tokens = self.tokens[self.pos..close_index],
                .schema = self.schema,
                .params = self.params,
                .unique_resolver = self.unique_resolver,
            };
            var lowered = try sub.parseSelect();
            errdefer lowered.deinit(self.alloc);
            self.pos = close_index + 1;
            try self.resolveSelectSourceForPlan(&lowered, ctes.items, &base_table_name);
            try ctes.append(self.alloc, .{
                .name = cte_name,
                .query = lowered.query,
            });
            lowered.query = .{};
            lowered.clearSelectOutputs(self.alloc);
            self.alloc.free(lowered.table_name);
            lowered.table_name = "";
            cte_name_transferred = true;
            if (self.match(.comma) == null) break;
        }

        var final = try self.parseWindowSelect();
        errdefer final.deinit(self.alloc);
        try self.resolveWindowSourceForPlan(&final, ctes.items, &base_table_name);
        if (self.match(.semicolon) != null and !self.atEnd()) return error.UnsupportedSqlShape;
        if (!self.atEnd()) return error.UnsupportedSqlShape;

        const table_name = base_table_name orelse return error.UnsupportedSqlShape;
        base_table_name = null;
        const owned_ctes = try ctes.toOwnedSlice(self.alloc);
        self.alloc.free(final.table_name);
        final.table_name = table_name;
        final.plan.ctes = owned_ctes;
        return final;
    }

    fn parseAggregatePlan(self: *@This()) !LoweredAggregatePlan {
        if (!self.peekKeyword("with")) {
            var lowered = try self.parseAggregate();
            errdefer lowered.deinit(self.alloc);
            const table_name = lowered.table_name;
