    fn canParseJoinedBooleanAssignmentExpression(self: *@This(), target_alias: []const u8) bool {
        if (!self.joinedBooleanExpressionCanStartAt(self.pos, target_alias)) return false;

        var depth: usize = 0;
        var i = self.pos;
        var saw_boolean_operator = false;
        while (i < self.tokens.len) : (i += 1) {
            const token = self.tokens[i];
            switch (token.kind) {
                .semicolon, .comma => if (depth == 0) break,
                .rparen => {
                    if (depth == 0) break;
                    depth -= 1;
                },
                .lparen => depth += 1,
                .eq, .neq, .gt, .gte, .lt, .lte, .arrow_text, .arrow_json, .path_arrow_text, .path_arrow_json, .at_contains, .range_overlap, .question, .regex_match, .regex_imatch, .regex_not_match, .regex_not_imatch => return false,
