                    continue;
                }
                if (not) {
                    try self.expectKeyword("null");
                    break :blk .is_not_null;
                }
                try self.expectKeyword("null");
                break :blk .is_null;
            } else try self.parseComparisonOp();

            if (op == .eq and self.matchAnyOrSomeKeyword()) {
                try self.expect(.lparen);
                const values_json = try self.parseJsonArrayValueAlloc();
                var values_transferred = false;
                errdefer if (!values_transferred) self.alloc.free(values_json);
                try self.expect(.rparen);
                try self.appendJoinedMutationInPredicate(lhs_in_predicates, lhs.field, lhs_column, values_json, false);
                values_transferred = true;
            } else if (op == .ne and self.matchKeyword("all")) {
                try self.expect(.lparen);
                const values_json = try self.parseJsonArrayValueAlloc();
                var values_transferred = false;
                errdefer if (!values_transferred) self.alloc.free(values_json);
                try self.expect(.rparen);
                try self.appendJoinedMutationInPredicate(lhs_in_predicates, lhs.field, lhs_column, values_json, true);
                values_transferred = true;
            } else if (self.peekKind(.identifier) and identifierContainsQualifier(self.tokens[self.pos].text)) {
                if (op != .eq) return error.UnsupportedSqlShape;
                const rhs = try self.parseQualifiedFieldAlloc();
                defer freeQualifiedField(self.alloc, rhs);
                const rhs_side = try joinSideForQualifier(rhs.qualifier, target_alias, source_alias);
                if (lhs_side == rhs_side) return error.UnsupportedSqlShape;
                const rhs_column = try self.joinedMutationColumnForQualifier(rhs.qualifier, rhs.field, target_alias, source_alias);
                if (lhs_column.field_type != rhs_column.field_type) return error.UnsupportedSqlShape;
                const left_source = if (lhs_side == .left) lhs.field else rhs.field;
                const right_source = if (lhs_side == .right) lhs.field else rhs.field;
                const left_field = try self.alloc.dupe(u8, left_source);
                var left_transferred = false;
                errdefer if (!left_transferred) self.alloc.free(left_field);
                const right_field = try self.alloc.dupe(u8, right_source);
                var right_transferred = false;
                errdefer if (!right_transferred) self.alloc.free(right_field);
                try on.append(self.alloc, .{ .left_field = left_field, .right_field = right_field });
                left_transferred = true;
                right_transferred = true;
            } else {
                const value_json = if (op == .is_null or op == .is_not_null)
                    null
                else if (lhs_column.field_type == .array and op == .eq)
                    try self.parseArrayPredicateValueAlloc()
                else
                    try self.parseSqlColumnValueAlloc(lhs_column);
                var value_transferred = false;
                errdefer if (!value_transferred) if (value_json) |json| self.alloc.free(json);
                const field = try self.alloc.dupe(u8, lhs.field);
                var field_transferred = false;
                errdefer if (!field_transferred) self.alloc.free(field);
                if (lhs_column.field_type == .array and op == .eq) {
                    try self.validateSqlArrayValueJson(lhs_column, value_json.?);
                    try lhs_array_eq.append(self.alloc, .{ .field = field, .value_json = value_json.? });
                    field_transferred = true;
                    value_transferred = true;
                    if (!self.matchKeyword("and")) break;
                    continue;
                }
                try lhs_predicates.append(self.alloc, .{ .name = "", .field = field, .op = op, .value_json = value_json });
                field_transferred = true;
                value_transferred = true;
            }
            if (!self.matchKeyword("and")) break;
        }
    }

    const JoinedMutationExpressionSide = union(enum) {
        single: db_mod.types.RelationalRowsJoinProjectionSide,
        mixed,
    };

    fn joinedMutationExpressionSideAtCurrent(
        self: *@This(),
        target_alias: []const u8,
        source_alias: []const u8,
    ) !?JoinedMutationExpressionSide {
        if (!self.joinedMutationExpressionCanStartAtCurrent()) return null;

        var side: ?db_mod.types.RelationalRowsJoinProjectionSide = null;
        var mixed = false;
        var depth: usize = 0;
        var i = self.pos;
        while (i < self.tokens.len) : (i += 1) {
            const token = self.tokens[i];
            switch (token.kind) {
                .lparen => depth += 1,
                .rparen => {
                    if (depth == 0) break;
                    depth -= 1;
                },
                .semicolon => if (depth == 0) break,
                .identifier => {
                    if (depth == 0 and (std.ascii.eqlIgnoreCase(token.text, "and") or
                        std.ascii.eqlIgnoreCase(token.text, "or") or
                        tokenStartsWhereTailClause(token.text)))
                    {
                        break;
                    }
                    if (identifierContainsQualifier(token.text)) {
                        const dot = std.mem.indexOfScalar(u8, token.text, '.') orelse unreachable;
                        const next_side = try joinSideForQualifier(token.text[0..dot], target_alias, source_alias);
                        if (side) |existing| {
                            if (existing != next_side) mixed = true;
                        } else {
                            side = next_side;
                        }
                    }
                },
                else => {},
            }
        }
        if (mixed) return .mixed;
        if (side) |single| return .{ .single = single };
        return null;
    }

    fn joinedMutationExpressionCanStartAtCurrent(self: *@This()) bool {
        if (self.peekKind(.identifier) and self.pos + 1 < self.tokens.len and identifierContainsQualifier(self.tokens[self.pos].text)) {
            return switch (self.tokens[self.pos + 1].kind) {
                .plus, .minus, .star, .slash, .percent, .arrow_json, .arrow_text, .path_arrow_json, .path_arrow_text, .pipe_concat, .question_any, .question_all => true,
                else => false,
            };
        }
        if (self.expressionPredicateCanStartAt(self.pos)) return true;
        if (self.canParseExpressionNotWhere()) return true;
        if (self.peekKeyword("string_to_array") and self.stringToArrayPredicateIsContainment()) return true;
        if (self.peekKind(.lparen)) {
            const inner = self.predicateStartIndexAfterOpenParens(self.pos);
            return self.expressionPredicateCanStartAt(inner);
        }
        return false;
    }

    fn parseJoinedMutationExpressionWhereCondition(
        self: *@This(),
        side: JoinedMutationExpressionSide,
        left_expression_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition),
        right_expression_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition),
        left_expression_or_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
        right_expression_or_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
        left_expression_not_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
        right_expression_not_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
        left_expression_array_contains: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionArrayContainsPredicate),
        right_expression_array_contains: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionArrayContainsPredicate),
        match_expression_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition),
        match_expression_or_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
        match_expression_not_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
        match_expression_array_contains: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionArrayContainsPredicate),
        target_alias: []const u8,
        source_alias: []const u8,
    ) !void {
        const previous_schema = self.schema;
        const previous_field_expression_qualifiers = self.field_expression_qualifiers;
        const previous_joined_target_expression_qualifiers = self.joined_target_expression_qualifiers;
        const previous_joined_source_expression_qualifiers = self.joined_source_expression_qualifiers;
        const previous_defer_row_expression_field_validation = self.defer_row_expression_field_validation;
        const target_qualifiers = [_][]const u8{target_alias};
        const source_qualifiers = [_][]const u8{source_alias};
        const single_side = switch (side) {
            .single => |single| single,
            .mixed => null,
        };
        if (single_side) |single| {
            const qualifiers = [_][]const u8{if (single == .left) target_alias else source_alias};
            self.schema = if (single == .left) self.schema else self.joined_source_schema orelse self.schema;
            self.field_expression_qualifiers = qualifiers[0..];
        } else {
            self.joined_target_expression_qualifiers = target_qualifiers[0..];
            self.joined_source_expression_qualifiers = source_qualifiers[0..];
        }
        self.defer_row_expression_field_validation = true;
        defer {
            self.schema = previous_schema;
            self.field_expression_qualifiers = previous_field_expression_qualifiers;
            self.joined_target_expression_qualifiers = previous_joined_target_expression_qualifiers;
            self.joined_source_expression_qualifiers = previous_joined_source_expression_qualifiers;
            self.defer_row_expression_field_validation = previous_defer_row_expression_field_validation;
        }

        const expression_predicates = if (single_side) |single| if (single == .left) left_expression_predicates else right_expression_predicates else match_expression_predicates;
        const expression_or_predicates = if (single_side) |single| if (single == .left) left_expression_or_predicates else right_expression_or_predicates else match_expression_or_predicates;
        const expression_not_predicates = if (single_side) |single| if (single == .left) left_expression_not_predicates else right_expression_not_predicates else match_expression_not_predicates;
        const expression_array_contains = if (single_side) |single| if (single == .left) left_expression_array_contains else right_expression_array_contains else match_expression_array_contains;

        if (self.canParseExpressionNotWhere()) {
            try self.parseExpressionNotWhere(expression_not_predicates);
            return;
        }

        if (self.peekKeyword("string_to_array") and self.stringToArrayPredicateIsContainment()) {
            const predicate = try self.parseExpressionArrayContainsPredicateAlloc();
            var predicate_transferred = false;
            errdefer if (!predicate_transferred) freeExpressionArrayContainsOne(self.alloc, predicate);
            try expression_array_contains.append(self.alloc, predicate);
            predicate_transferred = true;
            return;
        }

        if (self.whereHasTopLevelOr() or self.parenthesizedExpressionOrWhereCanStart()) {
            try self.parseExpressionOrWhere(expression_or_predicates);
            return;
        }

        if (try self.canParseBareBooleanWhereExpression()) {
            try self.parseBareBooleanWhereExpression(expression_predicates);
            return;
        }

        try self.parseExpressionWhereConditions(expression_predicates, expression_or_predicates, expression_not_predicates);
    }

    fn appendJoinedMutationInPredicate(
        self: *@This(),
        in_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsInPredicate),
        field: []const u8,
        column: runtime_schema.RelationalColumn,
        values_json: []const u8,
        negated: bool,
    ) !void {
        if (column.field_type == .array or column.field_type == .json) return error.InvalidSqlCatalog;
        try self.validateSqlScalarValuesJson(column, values_json);
        const owned_field = try self.alloc.dupe(u8, field);
        var field_transferred = false;
        errdefer if (!field_transferred) self.alloc.free(owned_field);
        try in_predicates.append(self.alloc, .{
            .field = owned_field,
            .values_json = values_json,
            .negated = negated,
        });
        field_transferred = true;
    }

    fn joinedMutationColumnForQualifier(
        self: *@This(),
        qualifier: []const u8,
        field: []const u8,
        target_alias: []const u8,
        source_alias: []const u8,
    ) !runtime_schema.RelationalColumn {
        if (std.mem.eql(u8, qualifier, target_alias)) {
            return relationalColumnForField(self.schema, field, null) orelse error.InvalidSqlCatalog;
        }
        if (std.mem.eql(u8, qualifier, source_alias)) {
            return relationalColumnForField(self.joined_source_schema orelse self.schema, field, null) orelse error.InvalidSqlCatalog;
        }
        return error.UnsupportedSqlShape;
    }

    fn parseTargetOrderBy(
        self: *@This(),
        order_by: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsQueryOrder),
        target_alias: []const u8,
    ) !void {
        while (true) {
            const field = if (self.peekKind(.identifier) and identifierContainsQualifier(self.tokens[self.pos].text)) blk: {
                const source = try self.parseQualifiedFieldAlloc();
                defer freeQualifiedField(self.alloc, source);
                if (!std.mem.eql(u8, source.qualifier, target_alias)) return error.UnsupportedSqlShape;
                break :blk try self.alloc.dupe(u8, source.field);
            } else try self.parseIdentifierOwned();
            var field_transferred = false;
            errdefer if (!field_transferred) self.alloc.free(field);
            if (relationalColumnForField(self.schema, field, null) == null) return error.InvalidSqlCatalog;
            var order: db_mod.types.RelationalRowsQueryOrder = .{ .field = field };
            const explicit_nulls_first = try self.applyOrderModifiers(&order);
            try self.appendOrderWithNullPlacement(order_by, order, explicit_nulls_first);
            field_transferred = true;
            if (self.match(.comma) == null) break;
        }
    }

    fn parseLateralWhere(
        self: *@This(),
        left_alias: []const u8,
        right_alias: []const u8,
        predicates: *std.ArrayListUnmanaged(runtime_schema.RelationalCheck),
        json_contains: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonContainsPredicate),
        json_path_exists: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonPathExistsPredicate),
        array_contains: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayContainsPredicate),
        array_eq: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayEqPredicate),
        in_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsInPredicate),
        text_patterns: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsTextPatternPredicate),
        expression_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition),
        expression_or_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
        expression_not_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
        expression_array_contains: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionArrayContainsPredicate),
        match_expression_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition),
        match_expression_or_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
        match_expression_not_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
        match_expression_array_contains: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionArrayContainsPredicate),
        correlations: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsLateralCorrelation),
    ) !void {
        while (true) {
            if (try self.joinedMutationExpressionSideAtCurrent(left_alias, right_alias)) |expression_side| {
                switch (expression_side) {
                    .single => |single| if (single != .right) return error.UnsupportedSqlShape,
                    .mixed => {},
                }
                var unsupported_left_expression_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition).empty;
                defer {
                    freeExpressionConditions(self.alloc, unsupported_left_expression_predicates.items);
                    unsupported_left_expression_predicates.deinit(self.alloc);
                }
                var unsupported_left_expression_or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
                defer {
                    freeExpressionPredicateGroups(self.alloc, unsupported_left_expression_or_predicates.items);
                    unsupported_left_expression_or_predicates.deinit(self.alloc);
                }
                var unsupported_left_expression_not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
                defer {
                    freeExpressionPredicateGroups(self.alloc, unsupported_left_expression_not_predicates.items);
                    unsupported_left_expression_not_predicates.deinit(self.alloc);
                }
                var unsupported_left_expression_array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionArrayContainsPredicate).empty;
                defer {
                    freeExpressionArrayContains(self.alloc, unsupported_left_expression_array_contains.items);
                    unsupported_left_expression_array_contains.deinit(self.alloc);
                }
                var unsupported_match_expression_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition).empty;
                defer {
                    freeExpressionConditions(self.alloc, unsupported_match_expression_predicates.items);
                    unsupported_match_expression_predicates.deinit(self.alloc);
                }
                var unsupported_match_expression_or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
                defer {
                    freeExpressionPredicateGroups(self.alloc, unsupported_match_expression_or_predicates.items);
                    unsupported_match_expression_or_predicates.deinit(self.alloc);
                }
                var unsupported_match_expression_not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
                defer {
                    freeExpressionPredicateGroups(self.alloc, unsupported_match_expression_not_predicates.items);
                    unsupported_match_expression_not_predicates.deinit(self.alloc);
                }
                var unsupported_match_expression_array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionArrayContainsPredicate).empty;
                defer {
                    freeExpressionArrayContains(self.alloc, unsupported_match_expression_array_contains.items);
                    unsupported_match_expression_array_contains.deinit(self.alloc);
                }
                const effective_side: JoinedMutationExpressionSide = switch (expression_side) {
                    .single => .{ .single = .right },
                    .mixed => .mixed,
                };
                try self.parseJoinedMutationExpressionWhereCondition(
                    effective_side,
                    &unsupported_left_expression_predicates,
                    expression_predicates,
                    &unsupported_left_expression_or_predicates,
                    expression_or_predicates,
                    &unsupported_left_expression_not_predicates,
                    expression_not_predicates,
                    &unsupported_left_expression_array_contains,
                    expression_array_contains,
                    match_expression_predicates,
                    match_expression_or_predicates,
                    match_expression_not_predicates,
                    match_expression_array_contains,
                    left_alias,
                    right_alias,
                );
                if (unsupported_left_expression_predicates.items.len != 0 or
                    unsupported_left_expression_or_predicates.items.len != 0 or
                    unsupported_left_expression_not_predicates.items.len != 0 or
                    unsupported_left_expression_array_contains.items.len != 0 or
                    unsupported_match_expression_predicates.items.len != 0 or
                    unsupported_match_expression_or_predicates.items.len != 0 or
                    unsupported_match_expression_not_predicates.items.len != 0 or
                    unsupported_match_expression_array_contains.items.len != 0) return error.UnsupportedSqlShape;
                if (!self.matchKeyword("and")) break;
                continue;
            }

            const lhs = try self.parseQualifiedFieldAlloc();
            defer freeQualifiedField(self.alloc, lhs);
            const lhs_side = try joinSideForQualifier(lhs.qualifier, left_alias, right_alias);
            const column = try self.joinColumnForSide(lhs_side, lhs.field);
            if (self.match(.at_contains) != null) {
                if (lhs_side != .right) return error.UnsupportedSqlShape;
                const value_json = try self.parseStructuredPredicateValueAlloc(column);
                var value_transferred = false;
                errdefer if (!value_transferred) self.alloc.free(value_json);
                const field = try self.alloc.dupe(u8, lhs.field);
                var field_transferred = false;
                errdefer if (!field_transferred) self.alloc.free(field);
                if (column.field_type == .array) {
                    try self.validateSqlArrayValueJson(column, value_json);
                    try array_contains.append(self.alloc, .{ .field = field, .value_json = value_json });
                } else {
                    if (column.field_type != .json) return error.InvalidSqlCatalog;
                    try json_contains.append(self.alloc, .{ .field = field, .value_json = value_json });
                }
                field_transferred = true;
                value_transferred = true;
                if (!self.matchKeyword("and")) break;
                continue;
            }
            if (self.match(.question) != null) {
                if (lhs_side != .right) return error.UnsupportedSqlShape;
                if (column.field_type != .json) return error.InvalidSqlCatalog;
                const path = try self.parseJsonPathOwned();
                var path_transferred = false;
                errdefer if (!path_transferred) self.alloc.free(path);
                const field = try self.alloc.dupe(u8, lhs.field);
                var field_transferred = false;
                errdefer if (!field_transferred) self.alloc.free(field);
                try json_path_exists.append(self.alloc, .{ .field = field, .path = path });
                field_transferred = true;
                path_transferred = true;
                if (!self.matchKeyword("and")) break;
                continue;
            }
            if (self.matchKeyword("like") or self.matchKeyword("ilike")) {
                if (lhs_side != .right) return error.UnsupportedSqlShape;
                const case_insensitive = std.ascii.eqlIgnoreCase(self.tokens[self.pos - 1].text, "ilike");
                try self.appendTextPatternPredicate(text_patterns, lhs.field, column, case_insensitive, false);
                if (!self.matchKeyword("and")) break;
                continue;
            }
            if (self.matchKeyword("not")) {
                if (lhs_side != .right) return error.UnsupportedSqlShape;
                if (self.matchKeyword("like") or self.matchKeyword("ilike")) {
                    const case_insensitive = std.ascii.eqlIgnoreCase(self.tokens[self.pos - 1].text, "ilike");
                    try self.appendTextPatternPredicate(text_patterns, lhs.field, column, case_insensitive, true);
                    if (!self.matchKeyword("and")) break;
                    continue;
                }
                try self.expectKeyword("in");
                if (column.field_type == .array or column.field_type == .json) return error.InvalidSqlCatalog;
                const values_json = try self.parseSqlInValuesJsonAlloc();
                var values_transferred = false;
                errdefer if (!values_transferred) self.alloc.free(values_json);
                try self.validateSqlScalarValuesJson(column, values_json);
                const field = try self.alloc.dupe(u8, lhs.field);
                var field_transferred = false;
                errdefer if (!field_transferred) self.alloc.free(field);
                try in_predicates.append(self.alloc, .{ .field = field, .values_json = values_json, .negated = true });
                field_transferred = true;
                values_transferred = true;
                if (!self.matchKeyword("and")) break;
                continue;
            }
            if (self.matchKeyword("in")) {
                if (lhs_side != .right) return error.UnsupportedSqlShape;
                if (column.field_type == .array or column.field_type == .json) return error.InvalidSqlCatalog;
                const values_json = try self.parseSqlInValuesJsonAlloc();
                var values_transferred = false;
                errdefer if (!values_transferred) self.alloc.free(values_json);
                try self.validateSqlScalarValuesJson(column, values_json);
                const field = try self.alloc.dupe(u8, lhs.field);
                var field_transferred = false;
                errdefer if (!field_transferred) self.alloc.free(field);
                try in_predicates.append(self.alloc, .{ .field = field, .values_json = values_json, .negated = false });
                field_transferred = true;
                values_transferred = true;
                if (!self.matchKeyword("and")) break;
                continue;
            }
            const op: runtime_schema.RelationalCheckOp = if (self.matchKeyword("is")) blk: {
                if (lhs_side != .right) return error.UnsupportedSqlShape;
                const not = self.matchKeyword("not");
                if (try self.parseSqlBooleanIsUnknown(column)) {
                    break :blk if (not) .is_not_null else .is_null;
                }
                if (not and (self.peekKeyword("true") or self.peekKeyword("false"))) {
                    const value = (try self.parseSqlBooleanIsValue(column)) orelse return error.UnsupportedSqlShape;
                    try self.appendBooleanIsNotExpressionGroups(expression_or_predicates, lhs.field, value);
                    if (!self.matchKeyword("and")) break;
                    continue;
                }
                if (try self.parseSqlBooleanIsValueAlloc(column, not)) |value_json| {
                    var value_transferred = false;
                    errdefer if (!value_transferred) self.alloc.free(value_json);
                    const field = try self.alloc.dupe(u8, lhs.field);
                    var field_transferred = false;
                    errdefer if (!field_transferred) self.alloc.free(field);
                    try predicates.append(self.alloc, .{
                        .name = "",
                        .field = field,
                        .op = .eq,
                        .value_json = value_json,
                    });
                    field_transferred = true;
                    value_transferred = true;
                    if (!self.matchKeyword("and")) break;
                    continue;
                }
                if (not) {
                    try self.expectKeyword("null");
                    break :blk .is_not_null;
                }
                try self.expectKeyword("null");
                break :blk .is_null;
            } else try self.parseComparisonOp();
            if (op == .eq and self.matchAnyOrSomeKeyword()) {
                if (lhs_side != .right) return error.UnsupportedSqlShape;
                if (column.field_type == .array or column.field_type == .json) return error.InvalidSqlCatalog;
                try self.expect(.lparen);
                const values_json = try self.parseJsonArrayValueAlloc();
                var values_transferred = false;
                errdefer if (!values_transferred) self.alloc.free(values_json);
                try self.expect(.rparen);
                try self.validateSqlScalarValuesJson(column, values_json);
                const field = try self.alloc.dupe(u8, lhs.field);
                var field_transferred = false;
                errdefer if (!field_transferred) self.alloc.free(field);
                try in_predicates.append(self.alloc, .{ .field = field, .values_json = values_json, .negated = false });
                field_transferred = true;
                values_transferred = true;
                if (!self.matchKeyword("and")) break;
                continue;
            }
            if (self.peekKind(.identifier) and identifierContainsQualifier(self.tokens[self.pos].text)) {
                if (op != .eq) return error.UnsupportedSqlShape;
                const rhs = try self.parseQualifiedFieldAlloc();
                defer freeQualifiedField(self.alloc, rhs);
                const rhs_side = try joinSideForQualifier(rhs.qualifier, left_alias, right_alias);
                if (lhs_side == rhs_side) return error.UnsupportedSqlShape;
                const rhs_column = try self.joinColumnForSide(rhs_side, rhs.field);
                if (column.field_type != rhs_column.field_type) return error.UnsupportedSqlShape;
                const left_source = if (lhs_side == .left) lhs.field else rhs.field;
                const right_source = if (lhs_side == .right) lhs.field else rhs.field;
                const left_field = try self.alloc.dupe(u8, left_source);
                var left_transferred = false;
                errdefer if (!left_transferred) self.alloc.free(left_field);
                const right_field = try self.alloc.dupe(u8, right_source);
                var right_transferred = false;
                errdefer if (!right_transferred) self.alloc.free(right_field);
                try correlations.append(self.alloc, .{ .left_field = left_field, .right_field = right_field });
                left_transferred = true;
                right_transferred = true;
            } else {
                if (lhs_side != .right) return error.UnsupportedSqlShape;
                const value_json = if (op == .is_null or op == .is_not_null)
                    null
                else if (column.field_type == .array and op == .eq)
                    try self.parseArrayPredicateValueAlloc()
                else
                    try self.parseSqlColumnValueAlloc(column);
                var value_transferred = false;
                errdefer if (!value_transferred) if (value_json) |json| self.alloc.free(json);
                const field = try self.alloc.dupe(u8, lhs.field);
                var field_transferred = false;
                errdefer if (!field_transferred) self.alloc.free(field);
                if (column.field_type == .array and op == .eq) {
                    try self.validateSqlArrayValueJson(column, value_json.?);
                    try array_eq.append(self.alloc, .{ .field = field, .value_json = value_json.? });
                    field_transferred = true;
                    value_transferred = true;
                    if (!self.matchKeyword("and")) break;
                    continue;
                }
                try predicates.append(self.alloc, .{ .name = "", .field = field, .op = op, .value_json = value_json });
                field_transferred = true;
                value_transferred = true;
            }
            if (!self.matchKeyword("and")) break;
        }
    }

    fn parseJoinOrderBy(
        self: *@This(),
        order_by: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsQueryOrder),
        select: []const db_mod.types.RelationalRowsJoinProjection,
    ) !void {
        while (true) {
            var order = if (self.match(.number)) |token| blk: {
                const ordinal = std.fmt.parseInt(u32, token.text, 10) catch return error.UnsupportedSqlShape;
                const field = try self.joinOutputFieldByOrdinalAlloc(select, ordinal);
                if (!joinProjectionOutputIsUnique(select, field)) {
                    self.alloc.free(field);
                    return error.UnsupportedSqlShape;
                }
                break :blk db_mod.types.RelationalRowsQueryOrder{ .field = field };
            } else if (self.peekJoinOutputOrderExpression()) blk: {
                break :blk try self.parseJoinOutputOrderExpressionAlloc(select);
            } else blk: {
                const field = try self.parseIdentifierOwned();
                if (!joinProjectionOutputIsUnique(select, field)) {
                    self.alloc.free(field);
                    return error.UnsupportedSqlShape;
                }
                break :blk db_mod.types.RelationalRowsQueryOrder{ .field = field };
            };
            var order_transferred = false;
            errdefer if (!order_transferred) {
                if (order.field.len > 0) self.alloc.free(order.field);
                if (order.expression) |expression| freeExpression(self.alloc, expression);
            };
            const explicit_nulls_first = try self.applyOrderModifiers(&order);
            try self.appendOrderWithNullPlacement(order_by, order, explicit_nulls_first);
            order_transferred = true;
            if (self.match(.comma) == null) break;
        }
    }

    fn peekJoinOutputOrderExpression(self: *@This()) bool {
        return self.peekAggregateOutputOrderExpression();
    }

    fn parseJoinOutputOrderExpressionAlloc(
        self: *@This(),
        select: []const db_mod.types.RelationalRowsJoinProjection,
    ) !db_mod.types.RelationalRowsQueryOrder {
        const output_columns = try self.joinOutputColumnsAlloc(select);
        defer if (output_columns.len > 0) self.alloc.free(output_columns);
        const prior_schema = self.schema;
        self.schema = .{
            .storage_mode = .relational,
            .relational_columns = output_columns,
        };
        defer self.schema = prior_schema;
        return try self.parseOrderExpressionAlloc();
    }

    fn joinOutputFieldByOrdinalAlloc(
        self: *@This(),
        select: []const db_mod.types.RelationalRowsJoinProjection,
        ordinal: u32,
    ) ![]const u8 {
        if (ordinal == 0) return error.UnsupportedSqlShape;
        const index: usize = @intCast(ordinal - 1);
        if (index >= select.len) return error.UnsupportedSqlShape;
        return try self.alloc.dupe(u8, select[index].output);
    }

    fn joinOutputColumnsAlloc(
        self: *@This(),
        select: []const db_mod.types.RelationalRowsJoinProjection,
    ) ![]runtime_schema.RelationalColumn {
        if (select.len == 0) return &.{};
        const out = try self.alloc.alloc(runtime_schema.RelationalColumn, select.len);
        var initialized: usize = 0;
        errdefer self.alloc.free(out);
        for (select) |projection| {
            if (aggregateOutputColumnExists(out[0..initialized], projection.output)) return error.UnsupportedSqlShape;
            const column = relationalColumnForField(self.schema, projection.field, null) orelse return error.InvalidSqlCatalog;
            out[initialized] = .{
                .name = projection.output,
                .path = projection.output,
                .field_type = column.field_type,
                .array_item_type = column.array_item_type,
                .nullable = true,
            };
            initialized += 1;
        }
        return out;
    }

    const SelectItem = union(enum) {
        field: []const u8,
        json_extract: db_mod.types.RelationalRowsJsonExtractProjection,
        array_length: db_mod.types.RelationalRowsArrayLengthProjection,
        coalesce: db_mod.types.RelationalRowsCoalesceProjection,
        expression: db_mod.types.RelationalRowsExpressionProjection,
        field_alias: db_mod.types.RelationalRowsFieldAliasProjection,
    };

    const FieldJsonValue = struct {
        field: []const u8,
        value_json: []const u8,
    };

    const JoinedMutationSourceAssignment = struct {
        field: []const u8,
        source_qualifier: []const u8,
        source_field: []const u8,
    };

    const FieldExpressionValue = struct {
        field: []const u8,
        expression: db_mod.types.RelationalRowsExpression,
    };

    const FieldPredicate = struct {
        field: []const u8,
        op: runtime_schema.UniquePredicateOp,
        value_json: ?[]const u8 = null,
    };

    const JsonSetValue = struct {
        field: []const u8,
        path: []const []const u8,
        value_json: ?[]const u8 = null,
        expression: ?db_mod.types.RelationalRowsExpression = null,
    };

    const JsonSetParsedValue = struct {
        value_json: ?[]const u8 = null,
        expression: ?db_mod.types.RelationalRowsExpression = null,
    };

    const ArrayTransformValue = struct {
        field: []const u8,
        op: db_mod.types.TransformOpType,
        value_json: []const u8,
    };

    const ConflictAction = enum {
        nothing,
        update,
    };

    const ConflictTarget = union(enum) {
        primary,
        unique: UniqueConflictTarget,
    };

    const UniqueConflictTarget = struct {
        name: []const u8,
        where_json: []const u8 = "",
        where_expressions: []const db_mod.types.RelationalRowsExpressionCondition = &.{},
    };

    const ConflictClause = struct {
        target: ConflictTarget,
        action: ConflictAction,
        patch: []const FieldJsonValue = &.{},
        patch_expr: []const FieldExpressionValue = &.{},
        increment: []const FieldJsonValue = &.{},
        increment_expr: []const FieldExpressionValue = &.{},
        json_set: []const JsonSetValue = &.{},
        array_update: []const ArrayTransformValue = &.{},
        where_expression: ?db_mod.types.RelationalRowsExpressionCondition = null,
        where_expressions: []const db_mod.types.RelationalRowsExpressionCondition = &.{},
        where_any: []const db_mod.types.RelationalRowsExpressionPredicateGroup = &.{},
        where_not: []const db_mod.types.RelationalRowsExpressionPredicateGroup = &.{},
    };

    fn validateSqlInsertColumnsUnique(self: *@This(), columns: []const []const u8) !void {
        for (columns, 0..) |lhs, i| {
            const lhs_path = try self.sqlCanonicalMutationFieldPath(lhs);
            for (columns[i + 1 ..]) |rhs| {
                if (sqlDottedPathsConflict(lhs_path, try self.sqlCanonicalMutationFieldPath(rhs))) return error.UnsupportedSqlShape;
            }
        }
    }

    fn validateSqlIdentifierListUnique(columns: []const []const u8) !void {
        for (columns, 0..) |lhs, i| {
            for (columns[i + 1 ..]) |rhs| {
                if (std.ascii.eqlIgnoreCase(lhs, rhs)) return error.UnsupportedSqlShape;
            }
        }
    }

    fn validateSqlIdentifierListsDisjoint(left: []const []const u8, right: []const []const u8) !void {
        for (left) |lhs| {
            for (right) |rhs| {
                if (std.ascii.eqlIgnoreCase(lhs, rhs)) return error.UnsupportedSqlShape;
            }
        }
    }

    fn validateSqlUniqueExpressionListUnique(expressions: []const runtime_schema.UniqueExpression) !void {
        for (expressions, 0..) |lhs, i| {
            for (expressions[i + 1 ..]) |rhs| {
                if (lhs.op == rhs.op and std.ascii.eqlIgnoreCase(lhs.field, rhs.field)) return error.UnsupportedSqlShape;
            }
        }
    }

    fn validateSqlUpdateTargetPaths(
        self: *@This(),
        patch: []const FieldJsonValue,
        patch_expr: []const FieldExpressionValue,
        increment: []const FieldJsonValue,
        increment_expr: []const FieldExpressionValue,
        json_set: []const JsonSetValue,
        array_update: []const ArrayTransformValue,
    ) !void {
        for (patch, 0..) |lhs, i| {
            try self.validateSqlFieldDoesNotConflictFieldJson(lhs.field, patch[i + 1 ..]);
            try self.validateSqlFieldDoesNotConflictFieldExpressions(lhs.field, patch_expr);
            try self.validateSqlFieldDoesNotConflictFieldJson(lhs.field, increment);
            try self.validateSqlFieldDoesNotConflictFieldExpressions(lhs.field, increment_expr);
            try self.validateSqlFieldDoesNotConflictJsonSet(lhs.field, json_set);
            try self.validateSqlFieldDoesNotConflictArrayUpdates(lhs.field, array_update);
        }
        for (patch_expr, 0..) |lhs, i| {
            try self.validateSqlFieldDoesNotConflictFieldExpressions(lhs.field, patch_expr[i + 1 ..]);
            try self.validateSqlFieldDoesNotConflictFieldJson(lhs.field, increment);
            try self.validateSqlFieldDoesNotConflictFieldExpressions(lhs.field, increment_expr);
            try self.validateSqlFieldDoesNotConflictJsonSet(lhs.field, json_set);
            try self.validateSqlFieldDoesNotConflictArrayUpdates(lhs.field, array_update);
        }
        for (increment, 0..) |lhs, i| {
            try self.validateSqlFieldDoesNotConflictFieldJson(lhs.field, increment[i + 1 ..]);
            try self.validateSqlFieldDoesNotConflictFieldExpressions(lhs.field, increment_expr);
            try self.validateSqlFieldDoesNotConflictJsonSet(lhs.field, json_set);
            try self.validateSqlFieldDoesNotConflictArrayUpdates(lhs.field, array_update);
        }
        for (increment_expr, 0..) |lhs, i| {
            try self.validateSqlFieldDoesNotConflictFieldExpressions(lhs.field, increment_expr[i + 1 ..]);
            try self.validateSqlFieldDoesNotConflictJsonSet(lhs.field, json_set);
            try self.validateSqlFieldDoesNotConflictArrayUpdates(lhs.field, array_update);
        }
        for (json_set, 0..) |lhs, i| {
            for (json_set[i + 1 ..]) |rhs| {
                if (self.sqlJsonSetPathsConflict(lhs, rhs)) return error.UnsupportedSqlShape;
            }
            try self.validateSqlJsonSetDoesNotConflictArrayUpdates(lhs, array_update);
        }
    }

    fn validateSqlJoinedMutationTargetPaths(
        self: *@This(),
        source_assignments: []const JoinedMutationSourceAssignment,
        patch: []const FieldJsonValue,
        patch_expr: []const FieldExpressionValue,
        json_set: []const JsonSetValue,
    ) !void {
        for (source_assignments, 0..) |lhs, i| {
            try self.validateSqlJoinedAssignmentDoesNotConflictAssignments(lhs.field, source_assignments[i + 1 ..]);
            try self.validateSqlFieldDoesNotConflictFieldJson(lhs.field, patch);
            try self.validateSqlFieldDoesNotConflictFieldExpressions(lhs.field, patch_expr);
            try self.validateSqlFieldDoesNotConflictJsonSet(lhs.field, json_set);
        }
        for (patch, 0..) |lhs, i| {
            try self.validateSqlFieldDoesNotConflictFieldJson(lhs.field, patch[i + 1 ..]);
            try self.validateSqlFieldDoesNotConflictFieldExpressions(lhs.field, patch_expr);
            try self.validateSqlFieldDoesNotConflictJsonSet(lhs.field, json_set);
        }
        for (patch_expr, 0..) |lhs, i| {
            try self.validateSqlFieldDoesNotConflictFieldExpressions(lhs.field, patch_expr[i + 1 ..]);
            try self.validateSqlFieldDoesNotConflictJsonSet(lhs.field, json_set);
        }
        for (json_set, 0..) |lhs, i| {
            for (json_set[i + 1 ..]) |rhs| {
                if (self.sqlJsonSetPathsConflict(lhs, rhs)) return error.UnsupportedSqlShape;
            }
        }
    }

    fn validateSqlFieldDoesNotConflictFieldJson(self: *@This(), field: []const u8, values: []const FieldJsonValue) !void {
        const lhs = try self.sqlCanonicalMutationFieldPath(field);
        for (values) |value| {
            if (sqlDottedPathsConflict(lhs, try self.sqlCanonicalMutationFieldPath(value.field))) return error.UnsupportedSqlShape;
        }
    }

    fn validateSqlFieldDoesNotConflictFieldExpressions(self: *@This(), field: []const u8, values: []const FieldExpressionValue) !void {
        const lhs = try self.sqlCanonicalMutationFieldPath(field);
        for (values) |value| {
            if (sqlDottedPathsConflict(lhs, try self.sqlCanonicalMutationFieldPath(value.field))) return error.UnsupportedSqlShape;
        }
    }

    fn validateSqlFieldDoesNotConflictJsonSet(self: *@This(), field: []const u8, values: []const JsonSetValue) !void {
        const lhs = try self.sqlCanonicalMutationFieldPath(field);
        for (values) |value| {
            if (self.sqlDottedPathConflictsJsonSetPath(lhs, value)) return error.UnsupportedSqlShape;
        }
    }

    fn validateSqlFieldDoesNotConflictArrayUpdates(self: *@This(), field: []const u8, values: []const ArrayTransformValue) !void {
        const lhs = try self.sqlCanonicalMutationFieldPath(field);
        for (values) |value| {
            if (sqlDottedPathsConflict(lhs, try self.sqlCanonicalMutationFieldPath(value.field))) return error.UnsupportedSqlShape;
        }
    }

    fn validateSqlJsonSetDoesNotConflictArrayUpdates(self: *@This(), value: JsonSetValue, values: []const ArrayTransformValue) !void {
        for (values) |array_update| {
            if (self.sqlDottedPathConflictsJsonSetPath(try self.sqlCanonicalMutationFieldPath(array_update.field), value)) return error.UnsupportedSqlShape;
        }
    }

    fn validateSqlJoinedAssignmentDoesNotConflictAssignments(
        self: *@This(),
        field: []const u8,
        values: []const JoinedMutationSourceAssignment,
    ) !void {
        const lhs = try self.sqlCanonicalMutationFieldPath(field);
        for (values) |value| {
            if (sqlDottedPathsConflict(lhs, try self.sqlCanonicalMutationFieldPath(value.field))) return error.UnsupportedSqlShape;
        }
    }

    fn sqlJsonSetPathsConflict(self: *@This(), lhs: JsonSetValue, rhs: JsonSetValue) bool {
        const lhs_field = self.sqlCanonicalMutationFieldPath(lhs.field) catch return true;
        const rhs_field = self.sqlCanonicalMutationFieldPath(rhs.field) catch return true;
        if (!std.mem.eql(u8, lhs_field, rhs_field)) return sqlDottedPathsConflict(lhs_field, rhs_field);
        const shared = @min(lhs.path.len, rhs.path.len);
        for (lhs.path[0..shared], rhs.path[0..shared]) |lhs_segment, rhs_segment| {
            if (!std.mem.eql(u8, lhs_segment, rhs_segment)) return false;
        }
        return true;
    }

    fn sqlDottedPathConflictsJsonSetPath(self: *@This(), path: []const u8, value: JsonSetValue) bool {
        const json_field = self.sqlCanonicalMutationFieldPath(value.field) catch return true;
        if (sqlDottedPathsConflict(path, json_field)) return true;
        if (path.len <= json_field.len + 1) return false;
        if (!std.mem.startsWith(u8, path, json_field) or path[json_field.len] != '.') return false;
        return sqlJsonSegmentsConflictDottedPath(value.path, path[json_field.len + 1 ..]);
    }

    fn sqlCanonicalMutationFieldPath(self: *@This(), field: []const u8) ![]const u8 {
        const column = relationalColumnForField(self.schema, field, null) orelse return error.InvalidSqlCatalog;
        return column.path;
    }

    fn sqlDottedPathsConflict(lhs: []const u8, rhs: []const u8) bool {
        if (std.mem.eql(u8, lhs, rhs)) return true;
        return sqlDottedPathIsAncestor(lhs, rhs) or sqlDottedPathIsAncestor(rhs, lhs);
    }

    fn sqlDottedPathIsAncestor(parent: []const u8, child: []const u8) bool {
        return parent.len < child.len and
            std.mem.startsWith(u8, child, parent) and
            child[parent.len] == '.';
    }

    fn sqlJsonSegmentsConflictDottedPath(json_path: []const []const u8, dotted_path: []const u8) bool {
        if (json_path.len == 0 or dotted_path.len == 0) return false;
        var offset: usize = 0;
        for (json_path, 0..) |segment, i| {
            if (offset >= dotted_path.len) return true;
            if (!std.mem.startsWith(u8, dotted_path[offset..], segment)) return false;
            offset += segment.len;
            const dotted_done = offset == dotted_path.len;
            const json_done = i + 1 == json_path.len;
            if (!dotted_done and dotted_path[offset] != '.') return false;
            if (dotted_done or json_done) return true;
            offset += 1;
        }
        return offset == dotted_path.len;
    }

    fn parseConflictClause(
        self: *@This(),
        table_name: []const u8,
        existing_qualifiers: []const []const u8,
        insert_columns: []const []const u8,
        insert_values: []const []const u8,
    ) !ConflictClause {
        const previous_conflict_existing_qualifiers = self.conflict_existing_qualifiers;
        self.conflict_existing_qualifiers = existing_qualifiers;
        defer self.conflict_existing_qualifiers = previous_conflict_existing_qualifiers;

        try self.expectKeyword("conflict");
        const target = try self.parseConflictTarget(table_name);
        errdefer freeConflictTarget(self.alloc, target);
        try self.expectKeyword("do");

        if (self.matchKeyword("nothing")) {
            return .{
                .target = target,
                .action = .nothing,
            };
        }

        try self.expectKeyword("update");
        try self.expectKeyword("set");
        var patch = std.ArrayListUnmanaged(FieldJsonValue).empty;
        errdefer {
            freeFieldJsonValues(self.alloc, patch.items);
            patch.deinit(self.alloc);
        }
        var patch_expr = std.ArrayListUnmanaged(FieldExpressionValue).empty;
        errdefer {
            freeFieldExpressionValues(self.alloc, patch_expr.items);
            patch_expr.deinit(self.alloc);
        }
        var increment = std.ArrayListUnmanaged(FieldJsonValue).empty;
        errdefer {
            freeFieldJsonValues(self.alloc, increment.items);
            increment.deinit(self.alloc);
        }
        var increment_expr = std.ArrayListUnmanaged(FieldExpressionValue).empty;
        errdefer {
            freeFieldExpressionValues(self.alloc, increment_expr.items);
            increment_expr.deinit(self.alloc);
        }
        var json_set = std.ArrayListUnmanaged(JsonSetValue).empty;
        errdefer {
            freeJsonSetValues(self.alloc, json_set.items);
            json_set.deinit(self.alloc);
        }
        var array_update = std.ArrayListUnmanaged(ArrayTransformValue).empty;
        errdefer {
            freeArrayTransformValues(self.alloc, array_update.items);
            array_update.deinit(self.alloc);
        }
        var where_expression: ?db_mod.types.RelationalRowsExpressionCondition = null;
        errdefer if (where_expression) |condition| freeExpressionCondition(self.alloc, condition);
        var where_expressions = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition).empty;
        errdefer {
            freeExpressionConditions(self.alloc, where_expressions.items);
            where_expressions.deinit(self.alloc);
        }
        var where_any = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
        errdefer {
            freeExpressionPredicateGroups(self.alloc, where_any.items);
            where_any.deinit(self.alloc);
        }
        var where_not = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
        errdefer {
            freeExpressionPredicateGroups(self.alloc, where_not.items);
            where_not.deinit(self.alloc);
        }
        while (true) {
            try self.parseConflictUpdateSetAssignment(insert_columns, insert_values, &patch, &patch_expr, &increment, &increment_expr, &json_set, &array_update);
            if (self.match(.comma) == null) break;
        }
        if (patch.items.len == 0 and patch_expr.items.len == 0 and increment.items.len == 0 and increment_expr.items.len == 0 and json_set.items.len == 0 and array_update.items.len == 0) return error.UnsupportedSqlShape;
        try self.validateSqlUpdateTargetPaths(patch.items, patch_expr.items, increment.items, increment_expr.items, json_set.items, array_update.items);
        if (self.matchKeyword("where")) {
            if (self.schema.relational_columns.len == 0) return error.InvalidSqlCatalog;
            try self.parseConflictActionWhereClause(insert_columns, &where_expression, &where_expressions, &where_any, &where_not);
        }

        return .{
            .target = target,
            .action = .update,
            .patch = try patch.toOwnedSlice(self.alloc),
            .patch_expr = try patch_expr.toOwnedSlice(self.alloc),
            .increment = try increment.toOwnedSlice(self.alloc),
            .increment_expr = try increment_expr.toOwnedSlice(self.alloc),
            .json_set = try json_set.toOwnedSlice(self.alloc),
            .array_update = try array_update.toOwnedSlice(self.alloc),
            .where_expression = where_expression,
            .where_expressions = try where_expressions.toOwnedSlice(self.alloc),
            .where_any = try where_any.toOwnedSlice(self.alloc),
            .where_not = try where_not.toOwnedSlice(self.alloc),
        };
    }

    fn parseConflictActionWhereClause(
        self: *@This(),
        insert_columns: []const []const u8,
        where_expression: *?db_mod.types.RelationalRowsExpressionCondition,
        where_expressions: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition),
        where_any: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
        where_not: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
    ) !void {
        const column = self.schema.relational_columns[0];
        if (self.matchKeyword("not")) {
            try self.expect(.lparen);
            while (true) {
                const branch_groups = try self.parseConflictActionWhereBranchGroupsAlloc(column, insert_columns);
                var branch_groups_transferred = false;
                errdefer if (!branch_groups_transferred) {
                    freeExpressionPredicateGroups(self.alloc, branch_groups);
                    self.alloc.free(branch_groups);
                };
                try where_not.appendSlice(self.alloc, branch_groups);
                branch_groups_transferred = true;
                self.alloc.free(branch_groups);
                if (!self.matchKeyword("or")) break;
            }
            try self.expect(.rparen);
            return;
        }

        const wrapped_disjunction = self.conflictParenthesizedDisjunctionCanStart();
        if (wrapped_disjunction) try self.expect(.lparen);

        var groups = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
        var groups_transferred = false;
        defer groups.deinit(self.alloc);
        errdefer if (!groups_transferred) freeExpressionPredicateGroups(self.alloc, groups.items);
        while (true) {
            const branch_groups = try self.parseConflictActionWhereBranchGroupsAlloc(column, insert_columns);
            var branch_groups_transferred = false;
            errdefer if (!branch_groups_transferred) {
                freeExpressionPredicateGroups(self.alloc, branch_groups);
                self.alloc.free(branch_groups);
            };
            try groups.appendSlice(self.alloc, branch_groups);
            branch_groups_transferred = true;
            self.alloc.free(branch_groups);
            if (!self.matchKeyword("or")) break;
        }
        if (wrapped_disjunction) try self.expect(.rparen);

        if (groups.items.len == 1) {
            const conditions = groups.items[0].conditions;
            groups.items[0].conditions = &.{};
            if (conditions.len == 1) {
                where_expression.* = conditions[0];
                self.alloc.free(conditions);
            } else {
                try where_expressions.appendSlice(self.alloc, conditions);
                self.alloc.free(conditions);
            }
            groups_transferred = true;
            return;
        }

        try where_any.appendSlice(self.alloc, groups.items);
        groups_transferred = true;
    }

    fn parseConflictActionWhereBranchGroupsAlloc(
        self: *@This(),
        column: runtime_schema.RelationalColumn,
        insert_columns: []const []const u8,
    ) ![]const db_mod.types.RelationalRowsExpressionPredicateGroup {
        const parenthesized = self.conflictParenthesizedConjunctionCanStart();
        if (parenthesized) try self.expect(.lparen);

        var groups = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
        errdefer {
            freeExpressionPredicateGroups(self.alloc, groups.items);
            groups.deinit(self.alloc);
        }
        try groups.append(self.alloc, .{ .conditions = &.{} });

        while (true) {
            var alternatives = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
            defer alternatives.deinit(self.alloc);
            errdefer freeExpressionPredicateGroups(self.alloc, alternatives.items);
            try self.parseConflictActionWhereConditionAlternatives(column, insert_columns, &alternatives);
            try self.andExpressionPredicateAlternatives(&groups, alternatives.items);
            freeExpressionPredicateGroups(self.alloc, alternatives.items);
            if (!self.matchKeyword("and")) break;
        }

        if (groups.items.len == 0) return error.UnsupportedSqlShape;
        if (parenthesized) try self.expect(.rparen);
        return try groups.toOwnedSlice(self.alloc);
    }

    fn conflictParenthesizedConjunctionCanStart(self: *@This()) bool {
        if (!self.peekKind(.lparen)) return false;

        var depth: usize = 0;
        var i = self.pos;
        while (i < self.tokens.len) : (i += 1) {
            const token = self.tokens[i];
            switch (token.kind) {
                .lparen => depth += 1,
                .rparen => {
                    if (depth == 0) return false;
                    depth -= 1;
                    if (depth == 0) return false;
                },
                .identifier => if (depth == 1 and std.ascii.eqlIgnoreCase(token.text, "and")) return true,
                .semicolon => if (depth == 0) return false,
                else => {},
            }
        }
        return false;
    }

    fn conflictParenthesizedDisjunctionCanStart(self: *@This()) bool {
        if (!self.peekKind(.lparen)) return false;

        var depth: usize = 0;
        var i = self.pos;
        while (i < self.tokens.len) : (i += 1) {
            const token = self.tokens[i];
            switch (token.kind) {
                .lparen => depth += 1,
                .rparen => {
                    if (depth == 0) return false;
                    depth -= 1;
                    if (depth == 0) return false;
                },
                .identifier => if (depth == 1 and std.ascii.eqlIgnoreCase(token.text, "or")) return true,
                .semicolon => if (depth == 0) return false,
                else => {},
            }
        }
        return false;
    }

    fn parseConflictActionWhereConditionGroupAlloc(
        self: *@This(),
        column: runtime_schema.RelationalColumn,
        insert_columns: []const []const u8,
    ) !db_mod.types.RelationalRowsExpressionPredicateGroup {
        var conditions = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition).empty;
        errdefer {
            freeExpressionConditions(self.alloc, conditions.items);
            conditions.deinit(self.alloc);
        }
        while (true) {
            const condition = try self.parseConflictActionWhereConditionAlloc(column, insert_columns);
            var condition_transferred = false;
            errdefer if (!condition_transferred) freeExpressionCondition(self.alloc, condition);
            try conditions.append(self.alloc, condition);
            condition_transferred = true;
            if (!self.matchKeyword("and")) break;
        }
        if (conditions.items.len == 0) return error.UnsupportedSqlShape;
        return .{ .conditions = try conditions.toOwnedSlice(self.alloc) };
    }

    fn parseConflictActionWhereConditionAlternatives(
        self: *@This(),
        column: runtime_schema.RelationalColumn,
        insert_columns: []const []const u8,
        alternatives: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
    ) !void {
        const parenthesized = self.match(.lparen) != null;
        if (self.canParseBareBooleanConflictExpression(insert_columns)) {
            const condition = try self.parseBareBooleanConflictExpressionConditionAlloc(column, insert_columns);
            try self.appendExpressionConditionGroup(alternatives, condition);
            if (parenthesized) try self.expect(.rparen);
            return;
        }

        const lhs = try self.parseConflictUntypedExpressionAlloc(column, insert_columns);
        var lhs_transferred = false;
        errdefer if (!lhs_transferred) freeExpression(self.alloc, lhs);

        const op: runtime_schema.RelationalCheckOp = if (self.matchKeyword("is")) blk: {
            const not = self.matchKeyword("not");
            if (self.matchKeyword("distinct")) {
                try self.expectKeyword("from");
                break :blk if (not) .is_not_distinct else .is_distinct;
            }
            if (self.matchKeyword("unknown")) {
                try self.validateBooleanRowExpression(lhs);
                const condition = expressionNullTestCondition(lhs, if (not) .is_not_null else .is_null);
                lhs_transferred = true;
                try self.appendExpressionConditionGroup(alternatives, condition);
                if (parenthesized) try self.expect(.rparen);
                return;
            }
            if (self.matchKeyword("true") or self.matchKeyword("false")) {
                const value = std.ascii.eqlIgnoreCase(self.tokens[self.pos - 1].text, "true");
                try self.validateBooleanRowExpression(lhs);
                if (not) {
                    try self.appendExpressionBooleanIsNotGroups(alternatives, lhs, value);
                    freeExpression(self.alloc, lhs);
                    lhs_transferred = true;
                    if (parenthesized) try self.expect(.rparen);
                    return;
                }
                const condition = try self.expressionBooleanComparisonConditionAlloc(lhs, .eq, value);
                lhs_transferred = true;
                try self.appendExpressionConditionGroup(alternatives, condition);
                if (parenthesized) try self.expect(.rparen);
                return;
            }
            try self.expectKeyword("null");
            break :blk if (not) .is_not_null else .is_null;
        } else if (self.matchPostfixNullTest()) |postfix_null_test|
            postfix_null_test
        else
            try self.parseComparisonOp();

        if (op == .eq and self.matchAnyOrSomeKeyword()) {
            try self.expect(.lparen);
            const values_json = try self.parseJsonArrayValueAlloc();
            defer self.alloc.free(values_json);
            try self.expect(.rparen);
            return error.UnsupportedSqlShape;
        }

        const rhs = switch (op) {
            .is_null, .is_not_null => &.{},
            else => blk: {
                const out = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
                var out_transferred = false;
                errdefer if (!out_transferred) self.alloc.free(out);
                out[0] = try self.parseConflictUntypedExpressionAlloc(column, insert_columns);
                out_transferred = true;
                break :blk out;
            },
        };
        var rhs_transferred = false;
        errdefer if (!rhs_transferred and rhs.len > 0) {
            for (rhs) |expression| freeExpression(self.alloc, expression);
            self.alloc.free(rhs);
        };
        try self.validateExpressionConditionTypes(lhs, op, rhs);

        const condition: db_mod.types.RelationalRowsExpressionCondition = .{
            .lhs = lhs,
            .op = op,
            .rhs = rhs,
        };
        lhs_transferred = true;
        rhs_transferred = true;
        try self.appendExpressionConditionGroup(alternatives, condition);
        if (parenthesized) try self.expect(.rparen);
    }

    fn parseConflictActionWhereConditionAlloc(
        self: *@This(),
        column: runtime_schema.RelationalColumn,
        insert_columns: []const []const u8,
    ) !db_mod.types.RelationalRowsExpressionCondition {
        const parenthesized = self.match(.lparen) != null;
        const condition = try self.parseConflictExpressionConditionAlloc(column, insert_columns);
        errdefer freeExpressionCondition(self.alloc, condition);
        if (parenthesized) try self.expect(.rparen);
        return condition;
    }

    fn parseConflictTarget(self: *@This(), table_name: []const u8) !ConflictTarget {
        if (self.matchKeyword("on")) {
            try self.expectKeyword("constraint");
            const constraint_name = try self.parseIdentifierOwned();
            defer self.alloc.free(constraint_name);
            return try self.conflictTargetForNamedConstraintAlloc(table_name, constraint_name);
        }

        try self.expect(.lparen);
        var columns = std.ArrayListUnmanaged([]const u8).empty;
        errdefer {
            for (columns.items) |column| self.alloc.free(column);
            columns.deinit(self.alloc);
        }
        var expressions = std.ArrayListUnmanaged(runtime_schema.UniqueExpression).empty;
        errdefer {
            for (expressions.items) |expression| self.alloc.free(expression.field);
            expressions.deinit(self.alloc);
        }
        while (true) {
            if (self.nextConflictTargetElementIsUniqueExpression()) {
                const wrapper_count = self.consumeDdlIndexExpressionWrappers();
                const expression = try self.parseConflictTargetUniqueExpressionAlloc();
                var expression_transferred = false;
                errdefer if (!expression_transferred) self.alloc.free(expression.field);
                try expressions.append(self.alloc, expression);
                expression_transferred = true;
                try self.closeDdlIndexExpressionWrappers(wrapper_count);
            } else {
                const column = try self.parseIdentifierOwned();
                var column_transferred = false;
                errdefer if (!column_transferred) self.alloc.free(column);
                if (self.peekKind(.lparen)) return error.UnsupportedSqlShape;
                if (relationalColumnForField(self.schema, column, null) == null) return error.InvalidSqlCatalog;
                try columns.append(self.alloc, column);
                column_transferred = true;
            }
            if (self.match(.comma) == null) break;
        }
        try self.expect(.rparen);
        if (columns.items.len == 0 and expressions.items.len == 0) return error.UnsupportedSqlShape;
        try self.validateSqlInsertColumnsUnique(columns.items);
        try validateSqlUniqueExpressionListUnique(expressions.items);

        var where_json: []const u8 = "";
        errdefer if (where_json.len > 0) self.alloc.free(where_json);
        var where_expressions: []const db_mod.types.RelationalRowsExpressionCondition = &.{};
        errdefer {
            freeExpressionConditions(self.alloc, where_expressions);
            if (where_expressions.len > 0) self.alloc.free(where_expressions);
        }
        if (self.matchKeyword("where")) {
            const where_start = self.pos;
            where_json = self.parseUniquePredicateWhereJsonAlloc() catch |err| switch (err) {
                error.UnsupportedSqlShape, error.InvalidSqlCatalog => blk: {
                    self.pos = where_start;
                    break :blk "";
                },
                else => return err,
            };
            if (where_json.len == 0) {
                where_expressions = try self.parseUniquePredicateWhereExpressionConditionsAlloc();
            }
        }

        if (expressions.items.len == 0 and columnsMatchPrimaryKey(self.schema.primary_key.?, columns.items)) {
            if (where_json.len > 0 or where_expressions.len > 0) return error.UnsupportedSqlShape;
            for (columns.items) |column| self.alloc.free(column);
            columns.deinit(self.alloc);
            return .primary;
        }

        const constraint = try findUniqueConstraintByColumnsExpressionsAndConflictWhere(self.alloc, self.schema, columns.items, expressions.items, where_json, where_expressions) orelse return error.InvalidSqlCatalog;

        const name = try self.alloc.dupe(u8, constraint.name);
        errdefer self.alloc.free(name);
        const out_where = try self.uniquePredicateWhereJsonAlloc(constraint.where);
        errdefer if (out_where.len > 0) self.alloc.free(out_where);
        const out_where_expressions = try cloneExpressionConditionsAlloc(self.alloc, constraint.where_expressions);
        errdefer {
            freeExpressionConditions(self.alloc, out_where_expressions);
            if (out_where_expressions.len > 0) self.alloc.free(out_where_expressions);
        }
        for (columns.items) |column| self.alloc.free(column);
        columns.deinit(self.alloc);
        for (expressions.items) |expression| self.alloc.free(expression.field);
        expressions.deinit(self.alloc);
        if (where_json.len > 0) self.alloc.free(where_json);
        where_json = "";
        freeExpressionConditions(self.alloc, where_expressions);
        if (where_expressions.len > 0) self.alloc.free(where_expressions);
        where_expressions = &.{};
        return .{ .unique = .{
            .name = name,
            .where_json = out_where,
            .where_expressions = out_where_expressions,
        } };
    }

    fn parseUniquePredicateWhereExpressionConditionsAlloc(self: *@This()) ![]const db_mod.types.RelationalRowsExpressionCondition {
        var conditions = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition).empty;
        errdefer {
            freeExpressionConditions(self.alloc, conditions.items);
            conditions.deinit(self.alloc);
        }
        while (true) {
            var condition = try self.parseCaseExpressionConditionAlloc();
            var condition_transferred = false;
            errdefer if (!condition_transferred) freeExpressionCondition(self.alloc, condition);
            try conditions.append(self.alloc, condition);
            condition = undefined;
            condition_transferred = true;
            if (!self.matchKeyword("and")) break;
        }
        return try conditions.toOwnedSlice(self.alloc);
    }

    fn nextConflictTargetElementIsUniqueExpression(self: *@This()) bool {
        var pos = self.pos;
        while (pos < self.tokens.len and self.tokens[pos].kind == .lparen) : (pos += 1) {}
        if (pos >= self.tokens.len or self.tokens[pos].kind != .identifier) return false;
        return std.ascii.eqlIgnoreCase(self.tokens[pos].text, "lower") or
            std.ascii.eqlIgnoreCase(self.tokens[pos].text, "upper") or
            std.ascii.eqlIgnoreCase(self.tokens[pos].text, "md5");
    }

    fn parseConflictTargetUniqueExpressionAlloc(self: *@This()) !runtime_schema.UniqueExpression {
        const op: runtime_schema.UniqueExpressionOp = if (self.matchKeyword("lower"))
            .lower
        else if (self.matchKeyword("upper"))
            .upper
        else blk: {
            if (!self.matchMd5FunctionKeyword()) return error.UnsupportedSqlShape;
            break :blk .md5;
        };
        try self.expect(.lparen);
        const field = try self.parseIdentifierOwned();
        var field_transferred = false;
        errdefer if (!field_transferred) self.alloc.free(field);
        if (relationalColumnForField(self.schema, field, null) == null) return error.InvalidSqlCatalog;
        try self.expect(.rparen);
        field_transferred = true;
        return .{ .op = op, .field = field };
    }

    fn conflictTargetForNamedConstraintAlloc(
        self: *@This(),
        table_name: []const u8,
        constraint_name: []const u8,
    ) !ConflictTarget {
        if (try self.namedConstraintIsPrimaryKey(table_name, constraint_name)) return .primary;

        const constraint = findUniqueConstraintByName(self.schema, constraint_name) orelse return error.InvalidSqlCatalog;
        const name = try self.alloc.dupe(u8, constraint.name);
        errdefer self.alloc.free(name);
        const where_json = try self.uniquePredicateWhereJsonAlloc(constraint.where);
        errdefer if (where_json.len > 0) self.alloc.free(where_json);
        const where_expressions = try cloneExpressionConditionsAlloc(self.alloc, constraint.where_expressions);
        errdefer {
            freeExpressionConditions(self.alloc, where_expressions);
            if (where_expressions.len > 0) self.alloc.free(where_expressions);
        }
        return .{ .unique = .{
            .name = name,
            .where_json = where_json,
            .where_expressions = where_expressions,
        } };
    }

    fn namedConstraintIsPrimaryKey(
        self: *@This(),
        table_name: []const u8,
        constraint_name: []const u8,
    ) !bool {
        if (self.schema.primary_key) |primary_key| {
            if (primary_key.name) |name| {
                if (std.mem.eql(u8, constraint_name, name)) return true;
            }
        }
        const default_primary_name = try std.fmt.allocPrint(self.alloc, "{s}_pkey", .{table_name});
        defer self.alloc.free(default_primary_name);
        return std.mem.eql(u8, constraint_name, default_primary_name);
    }

    fn uniquePredicateWhereJsonAlloc(
        self: *@This(),
        predicates: []const runtime_schema.UniquePredicate,
    ) ![]const u8 {
        if (predicates.len == 0) return "";
        var out: std.Io.Writer.Allocating = .init(self.alloc);
        errdefer out.deinit();
        const writer = &out.writer;
        try writer.writeAll("{\"all\":[");
        for (predicates, 0..) |predicate, i| {
            if (i != 0) try writer.writeByte(',');
            try writer.print("{{\"field\":{f},\"op\":{f}", .{
                std.json.fmt(predicate.field, .{}),
                std.json.fmt(uniquePredicateOpToken(predicate.op), .{}),
            });
            if (predicate.value_json) |value_json| {
                try writer.writeAll(",\"value\":");
                try writer.writeAll(value_json);
            }
            try writer.writeByte('}');
        }
        try writer.writeAll("]}");
        return try out.toOwnedSlice();
    }

    fn rejectDuplicateConflictUpdateTargets(
        self: *@This(),
        insert_columns: []const []const u8,
        rows: InsertValueRows,
        conflicts: []const ConflictClause,
    ) !void {
        if (rows.len <= 1 or conflicts.len == 0) return;
        if (conflicts.len != rows.len) return error.UnsupportedSqlShape;

        var identities = std.ArrayListUnmanaged([]const u8).empty;
        defer {
            for (identities.items) |identity| self.alloc.free(identity);
            identities.deinit(self.alloc);
        }

        for (rows, conflicts) |row, conflict| {
            if (conflict.action != .update) continue;
            const identity = try self.conflictTargetIdentityAlloc(insert_columns, row, conflict.target);
            var identity_transferred = false;
            errdefer if (!identity_transferred) self.alloc.free(identity);
            for (identities.items) |existing| {
                if (std.mem.eql(u8, existing, identity)) return error.UnsupportedSqlShape;
            }
            try identities.append(self.alloc, identity);
            identity_transferred = true;
        }
    }

    fn conflictTargetIdentityAlloc(
        self: *@This(),
        insert_columns: []const []const u8,
        row: []const []const u8,
        target: ConflictTarget,
    ) ![]const u8 {
        return switch (target) {
            .primary => try self.conflictColumnIdentityAlloc("primary", self.schema.primary_key.?.columns, insert_columns, row),
            .unique => |unique| blk: {
                const constraint = findUniqueConstraintByName(self.schema, unique.name) orelse return error.InvalidSqlCatalog;
                break :blk try self.conflictUniqueConstraintIdentityAlloc(unique.name, constraint, insert_columns, row);
            },
        };
    }

    fn conflictUniqueConstraintIdentityAlloc(
        self: *@This(),
        label: []const u8,
        constraint: runtime_schema.UniqueConstraint,
        insert_columns: []const []const u8,
        row: []const []const u8,
    ) ![]const u8 {
        if (constraint.columns.len == 0 and constraint.expressions.len == 0) return error.UnsupportedSqlShape;
        var out: std.Io.Writer.Allocating = .init(self.alloc);
        errdefer out.deinit();
        const writer = &out.writer;
        try writer.print("{f}:[", .{std.json.fmt(label, .{})});
        var wrote = false;
        for (constraint.columns) |target_column| {
            const value_json = conflictInsertedValueForColumn(insert_columns, row, target_column) orelse return error.UnsupportedSqlShape;
            if (wrote) try writer.writeByte(',');
            try writer.print("{{\"column\":{f},\"value\":", .{std.json.fmt(target_column, .{})});
            try writer.writeAll(value_json);
            try writer.writeByte('}');
            wrote = true;
        }
        for (constraint.expressions) |expression| {
            const value = try self.conflictExpressionValueAlloc(expression, insert_columns, row);
            defer self.alloc.free(value);
            if (wrote) try writer.writeByte(',');
            try writer.print("{{\"expression\":{{\"op\":{f},\"field\":{f}}},\"value\":{f}}}", .{
                std.json.fmt(uniqueExpressionOpToken(expression.op), .{}),
                std.json.fmt(expression.field, .{}),
                std.json.fmt(value, .{}),
            });
            wrote = true;
        }
        try writer.writeByte(']');
        return try out.toOwnedSlice();
    }

    fn conflictColumnIdentityAlloc(
        self: *@This(),
        label: []const u8,
        target_columns: []const []const u8,
        insert_columns: []const []const u8,
        row: []const []const u8,
    ) ![]const u8 {
        var out: std.Io.Writer.Allocating = .init(self.alloc);
        errdefer out.deinit();
        const writer = &out.writer;
        try writer.print("{f}:[", .{std.json.fmt(label, .{})});
        for (target_columns, 0..) |target_column, i| {
            const value_json = conflictInsertedValueForColumn(insert_columns, row, target_column) orelse return error.UnsupportedSqlShape;
            if (i != 0) try writer.writeByte(',');
            try writer.print("{f}:", .{std.json.fmt(target_column, .{})});
            try writer.writeAll(value_json);
        }
        try writer.writeByte(']');
        return try out.toOwnedSlice();
    }

    fn conflictExpressionValueAlloc(
        self: *@This(),
        expression: runtime_schema.UniqueExpression,
        insert_columns: []const []const u8,
        row: []const []const u8,
    ) ![]const u8 {
        const value_json = conflictInsertedValueForColumn(insert_columns, row, expression.field) orelse return error.UnsupportedSqlShape;
        var parsed = std.json.parseFromSlice(std.json.Value, self.alloc, value_json, .{}) catch return error.UnsupportedSqlShape;
        defer parsed.deinit();
        if (parsed.value != .string) return error.UnsupportedSqlShape;
        return switch (expression.op) {
            .lower => try std.ascii.allocLowerString(self.alloc, parsed.value.string),
            .upper => try std.ascii.allocUpperString(self.alloc, parsed.value.string),
            .md5 => try md5HexTextAlloc(self.alloc, parsed.value.string),
        };
    }

    fn conflictExpressionIdentityAlloc(
        self: *@This(),
        label: []const u8,
        expression: runtime_schema.UniqueExpression,
        insert_columns: []const []const u8,
        row: []const []const u8,
    ) ![]const u8 {
        const folded = try self.conflictExpressionValueAlloc(expression, insert_columns, row);
        defer self.alloc.free(folded);
        return try std.fmt.allocPrint(self.alloc, "{f}:[{f}:{f}]", .{
            std.json.fmt(label, .{}),
            std.json.fmt(expression.field, .{}),
            std.json.fmt(folded, .{}),
        });
    }

    fn parseJsonSetSqlValueAlloc(
        self: *@This(),
        column: runtime_schema.RelationalColumn,
        insert_columns: []const []const u8,
    ) anyerror!JsonSetParsedValue {
        if (!self.peekKeyword("to_jsonb")) {
            return .{ .value_json = try self.parseJsonValueAlloc() };
        }

        try self.expectKeyword("to_jsonb");
        try self.expect(.lparen);
        if (self.peekStaticToJsonbValue()) {
            const value_json = try self.parseJsonValueAlloc();
            errdefer self.alloc.free(value_json);
            try self.expect(.rparen);
            return .{ .value_json = value_json };
        }

        const expression = if (insert_columns.len > 0)
            try self.parseConflictUntypedExpressionAlloc(column, insert_columns)
        else
            try self.parseRowExpressionAlloc();
        var expression_transferred = false;
        errdefer if (!expression_transferred) freeExpression(self.alloc, expression);
        try self.expect(.rparen);
        expression_transferred = true;
        return .{ .expression = expression };
    }

    fn peekStaticToJsonbValue(self: *@This()) bool {
        if (self.peekKeyword("null") or self.peekKeyword("true") or self.peekKeyword("false")) return true;
        if (self.peekKind(.placeholder) or self.peekKind(.string) or self.peekKind(.number)) return true;
        return self.peekKind(.minus) and self.pos + 1 < self.tokens.len and self.tokens[self.pos + 1].kind == .number;
    }

    fn parseConflictUpdateSetAssignment(
        self: *@This(),
        insert_columns: []const []const u8,
        insert_values: []const []const u8,
        patch: *std.ArrayListUnmanaged(FieldJsonValue),
        patch_expr: *std.ArrayListUnmanaged(FieldExpressionValue),
        increment: *std.ArrayListUnmanaged(FieldJsonValue),
        increment_expr: *std.ArrayListUnmanaged(FieldExpressionValue),
        json_set: *std.ArrayListUnmanaged(JsonSetValue),
        array_update: *std.ArrayListUnmanaged(ArrayTransformValue),
    ) !void {
        if (self.peekKind(.lparen)) {
            return try self.parseConflictUpdateRowAssignment(insert_columns, insert_values, patch, patch_expr, increment, increment_expr, json_set, array_update);
        }
        return try self.parseConflictUpdateAssignment(insert_columns, insert_values, patch, patch_expr, increment, increment_expr, json_set, array_update);
    }

    fn parseConflictUpdateRowAssignment(
        self: *@This(),
        insert_columns: []const []const u8,
        insert_values: []const []const u8,
        patch: *std.ArrayListUnmanaged(FieldJsonValue),
        patch_expr: *std.ArrayListUnmanaged(FieldExpressionValue),
        increment: *std.ArrayListUnmanaged(FieldJsonValue),
        increment_expr: *std.ArrayListUnmanaged(FieldExpressionValue),
        json_set: *std.ArrayListUnmanaged(JsonSetValue),
        array_update: *std.ArrayListUnmanaged(ArrayTransformValue),
    ) !void {
        try self.expect(.lparen);
        var fields = std.ArrayListUnmanaged([]const u8).empty;
        defer {
            for (fields.items) |field| {
                if (field.len != 0) self.alloc.free(field);
            }
            fields.deinit(self.alloc);
        }
        while (true) {
            const field = try self.parseIdentifierOwned();
            var field_transferred = false;
            errdefer if (!field_transferred) self.alloc.free(field);
