            field_transferred = true;
            if (self.match(.comma) == null) break;
        }
        if (fields.items.len == 0) return error.UnsupportedSqlShape;
        try validateSqlIdentifierListUnique(fields.items);
        try self.expect(.rparen);
        try self.expect(.eq);
        try self.expect(.lparen);
        for (fields.items, 0..) |field, i| {
            const column = relationalColumnForField(self.schema, field, null) orelse return error.InvalidSqlCatalog;
            try self.notePrimaryKeyAssignment(field);
            var field_transferred = false;
            try self.parseConflictUpdateAssignmentValue(field, column, insert_columns, insert_values, patch, patch_expr, increment, increment_expr, json_set, array_update, &field_transferred);
            if (field_transferred) fields.items[i] = "";
            if (i + 1 < fields.items.len) {
                try self.expect(.comma);
            }
        }
        try self.expect(.rparen);
    }

    fn parseConflictUpdateAssignment(
        self: *@This(),
        insert_columns: []const []const u8,
        insert_values: []const []const u8,
        patch: *std.ArrayListUnmanaged(FieldJsonValue),
        patch_expr: *std.ArrayListUnmanaged(FieldExpressionValue),
        increment: *std.ArrayListUnmanaged(FieldJsonValue),
        increment_expr: *std.ArrayListUnmanaged(FieldExpressionValue),
        json_set: *std.ArrayListUnmanaged(JsonSetValue),
        array_update: *std.ArrayListUnmanaged(ArrayTransformValue),
    ) !void {
        const field = try self.parseIdentifierOwned();
        var field_transferred = false;
        defer if (!field_transferred) self.alloc.free(field);
        const column = relationalColumnForField(self.schema, field, null) orelse return error.InvalidSqlCatalog;
        try self.notePrimaryKeyAssignment(field);
        try self.expect(.eq);
        try self.parseConflictUpdateAssignmentValue(field, column, insert_columns, insert_values, patch, patch_expr, increment, increment_expr, json_set, array_update, &field_transferred);
    }

    fn notePrimaryKeyAssignment(self: *@This(), field: []const u8) !void {
        if (!primaryKeyContains(self.schema.primary_key.?, field)) return;
        if (!self.allow_primary_key_assignment) return error.UnsupportedSqlShape;
        self.saw_primary_key_assignment = true;
    }

    fn parseConflictUpdateAssignmentValue(
        self: *@This(),
        field: []const u8,
        column: runtime_schema.RelationalColumn,
        insert_columns: []const []const u8,
        insert_values: []const []const u8,
        patch: *std.ArrayListUnmanaged(FieldJsonValue),
        patch_expr: *std.ArrayListUnmanaged(FieldExpressionValue),
        increment: *std.ArrayListUnmanaged(FieldJsonValue),
        increment_expr: *std.ArrayListUnmanaged(FieldExpressionValue),
        json_set: *std.ArrayListUnmanaged(JsonSetValue),
        array_update: *std.ArrayListUnmanaged(ArrayTransformValue),
        field_transferred: *bool,
    ) !void {
        if (self.matchKeyword("jsonb_set")) {
            if (column.field_type != .json) return error.InvalidSqlCatalog;
            try self.expect(.lparen);
            const json_field = try self.parseIdentifierOwned();
            defer self.alloc.free(json_field);
            if (!std.mem.eql(u8, json_field, field)) return error.UnsupportedSqlShape;
            try self.expect(.comma);
            const path = try self.parsePostgresJsonPathAlloc();
            var path_transferred = false;
            errdefer if (!path_transferred) freeStringSlice(self.alloc, path);
            try self.expect(.comma);
            const value = try self.parseJsonSetSqlValueAlloc(column, insert_columns);
            var value_transferred = false;
            errdefer if (!value_transferred) freeJsonSetParsedValue(self.alloc, value);
            if (self.match(.comma) != null) {
                if (!self.matchKeyword("true") and !self.matchKeyword("false")) return error.UnsupportedSqlShape;
            }
            try self.expect(.rparen);
            try json_set.append(self.alloc, .{
                .field = field,
                .path = path,
                .value_json = value.value_json,
                .expression = value.expression,
            });
            field_transferred.* = true;
            path_transferred = true;
            value_transferred = true;
            return;
        }
        if (self.peekArrayTransformSelfAssignment(field) and (self.matchKeyword("array_append") or self.matchKeyword("array_remove"))) {
            const op: db_mod.types.TransformOpType = if (std.ascii.eqlIgnoreCase(self.tokens[self.pos - 1].text, "array_append")) .push else .pull;
            if (column.field_type != .array) return error.InvalidSqlCatalog;
            try self.expect(.lparen);
            const array_field = try self.parseIdentifierOwned();
            defer self.alloc.free(array_field);
            if (!std.mem.eql(u8, array_field, field)) return error.UnsupportedSqlShape;
            try self.expect(.comma);
            const value_json = try self.parseConflictArrayElementValueJsonAlloc(column, insert_columns, insert_values);
            var value_transferred = false;
            errdefer if (!value_transferred) self.alloc.free(value_json);
            try self.expect(.rparen);
            try array_update.append(self.alloc, .{
                .field = field,
                .op = op,
                .value_json = value_json,
            });
            field_transferred.* = true;
            value_transferred = true;
            return;
        }
        if (column.field_type == .json and self.peekKind(.identifier) and self.pos + 1 < self.tokens.len and self.tokens[self.pos + 1].kind == .pipe_concat) {
            const json_field_token = self.match(.identifier).?;
            if (!std.mem.eql(u8, json_field_token.text, field)) return error.UnsupportedSqlShape;
            try self.expect(.pipe_concat);
            try self.appendJsonObjectConcatSetValues(field, json_set);
            return;
        }
        if (self.peekConflictExistingFieldIncrement(field, column)) {
            try self.parseConflictIncrementAssignment(field, column, insert_columns, insert_values, increment, increment_expr);
            return;
        }
        if (column.field_type == .boolean and self.canParseConflictBooleanAssignmentExpression(insert_columns)) {
            const expression = try self.parseConflictBooleanExpressionAlloc(column, insert_columns);
            var expression_transferred = false;
            errdefer if (!expression_transferred) freeExpression(self.alloc, expression);
            try patch_expr.append(self.alloc, .{
                .field = field,
                .expression = expression,
            });
            field_transferred.* = true;
            expression_transferred = true;
            return;
        }
        if (self.canParseConflictAssignmentExpression(insert_columns)) {
            const expression = try self.parseConflictAssignmentExpressionAlloc(column, insert_columns);
            var expression_transferred = false;
            errdefer if (!expression_transferred) freeExpression(self.alloc, expression);
            try patch_expr.append(self.alloc, .{
                .field = field,
                .expression = expression,
            });
            field_transferred.* = true;
            expression_transferred = true;
            return;
        }

        const value_json = try self.parseConflictValueJsonAlloc(column, insert_columns, insert_values);
        var value_transferred = false;
        errdefer if (!value_transferred) self.alloc.free(value_json);
        try patch.append(self.alloc, .{
            .field = field,
            .value_json = value_json,
        });
        field_transferred.* = true;
        value_transferred = true;
    }

    fn peekArrayTransformSelfAssignment(self: *@This(), field: []const u8) bool {
        if (!(self.peekKeyword("array_append") or self.peekKeyword("array_remove"))) return false;
        if (self.pos + 3 >= self.tokens.len) return false;
        return self.tokens[self.pos + 1].kind == .lparen and
            self.tokens[self.pos + 2].kind == .identifier and
            std.mem.eql(u8, self.tokens[self.pos + 2].text, field) and
            self.tokens[self.pos + 3].kind == .comma;
    }

    fn parseConflictValueJsonAlloc(
        self: *@This(),
        column: runtime_schema.RelationalColumn,
        insert_columns: []const []const u8,
        insert_values: []const []const u8,
    ) ![]const u8 {
        if (self.peekKeyword("jsonb_build_object")) {
            if (column.field_type != .json) return error.InvalidSqlCatalog;
            return try self.parseConflictJsonbBuildObjectAlloc(insert_columns, insert_values);
        }
        if (self.peekKeyword("coalesce")) {
            return try self.parseConflictCoalesceValueJsonAlloc(column, insert_columns, insert_values);
        }
        if (self.peekKind(.identifier) and self.pos < self.tokens.len) {
            const token = self.tokens[self.pos];
            if (std.mem.startsWith(u8, token.text, "excluded.")) {
                self.pos += 1;
                return try self.conflictExcludedValueJsonAlloc(column, token.text["excluded.".len..], insert_columns, insert_values);
            }
        }
        return try self.parseSqlColumnValueAlloc(column);
    }

    fn parseConflictArrayElementValueJsonAlloc(
        self: *@This(),
        column: runtime_schema.RelationalColumn,
        insert_columns: []const []const u8,
        insert_values: []const []const u8,
    ) ![]const u8 {
        const item_type = column.array_item_type orelse return error.InvalidSqlCatalog;
        const element_column: runtime_schema.RelationalColumn = .{
            .name = column.name,
            .path = column.path,
            .field_type = item_type,
        };
        if (self.peekKeyword("coalesce")) {
            const value_json = try self.parseConflictCoalesceValueJsonAlloc(element_column, insert_columns, insert_values);
            errdefer self.alloc.free(value_json);
            try self.validateSqlArrayElementValueJson(column, value_json);
            return value_json;
        }
        if (self.peekKind(.identifier) and self.pos < self.tokens.len) {
            const token = self.tokens[self.pos];
            if (std.mem.startsWith(u8, token.text, "excluded.")) {
                self.pos += 1;
                const source = token.text["excluded.".len..];
                const source_column = relationalColumnForField(self.schema, source, null) orelse return error.InvalidSqlCatalog;
                if (source_column.field_type != item_type) return error.UnsupportedSqlShape;
                for (insert_columns, insert_values) |insert_column, insert_value| {
                    if (std.mem.eql(u8, insert_column, source)) {
                        try self.validateSqlArrayElementValueJson(column, insert_value);
                        return try self.alloc.dupe(u8, insert_value);
                    }
                }
                return error.UnsupportedSqlShape;
            }
        }
        const value_json = try self.parseJsonValueAlloc();
        errdefer self.alloc.free(value_json);
        try self.validateSqlArrayElementValueJson(column, value_json);
        return value_json;
    }

    fn validateSqlArrayElementValueJson(
        self: *@This(),
        column: runtime_schema.RelationalColumn,
        value_json: []const u8,
    ) !void {
        const item_type = column.array_item_type orelse return error.InvalidSqlCatalog;
        var parsed = std.json.parseFromSlice(std.json.Value, self.alloc, value_json, .{}) catch return error.UnsupportedSqlShape;
        defer parsed.deinit();
        if (!sqlArrayItemValueMatches(item_type, parsed.value)) return error.UnsupportedSqlShape;
    }

    fn validateSqlArrayValueJson(
        self: *@This(),
        column: runtime_schema.RelationalColumn,
        value_json: []const u8,
    ) !void {
        const item_type = column.array_item_type orelse return error.InvalidSqlCatalog;
        var parsed = std.json.parseFromSlice(std.json.Value, self.alloc, value_json, .{}) catch return error.UnsupportedSqlShape;
        defer parsed.deinit();
        if (parsed.value != .array) return error.UnsupportedSqlShape;
        for (parsed.value.array.items) |item| {
            if (!sqlArrayItemValueMatches(item_type, item)) return error.UnsupportedSqlShape;
        }
    }

    fn validateSqlScalarValuesJson(
        self: *@This(),
        column: runtime_schema.RelationalColumn,
        values_json: []const u8,
    ) !void {
        if (column.field_type == .array or column.field_type == .json) return error.InvalidSqlCatalog;
        var parsed = std.json.parseFromSlice(std.json.Value, self.alloc, values_json, .{}) catch return error.UnsupportedSqlShape;
        defer parsed.deinit();
        if (parsed.value != .array) return error.UnsupportedSqlShape;
        for (parsed.value.array.items) |item| {
            if (!sqlScalarValueMatches(column.field_type, item)) return error.UnsupportedSqlShape;
        }
    }

    fn parseConflictJsonbBuildObjectAlloc(
        self: *@This(),
        insert_columns: []const []const u8,
        insert_values: []const []const u8,
    ) ![]const u8 {
        try self.expectKeyword("jsonb_build_object");
        try self.expect(.lparen);
        if (self.match(.rparen) != null) return try self.alloc.dupe(u8, "{}");

        var seen = std.StringHashMapUnmanaged(void).empty;
        defer seen.deinit(self.alloc);
        var out: std.Io.Writer.Allocating = .init(self.alloc);
        errdefer out.deinit();
        const writer = &out.writer;
        try writer.writeByte('{');
        var first = true;
        while (true) {
            const key = try self.parseJsonbBuildObjectKey();
            const entry = try seen.getOrPut(self.alloc, key);
            if (entry.found_existing) return error.UnsupportedSqlShape;
            try self.expect(.comma);
            const value_json = try self.parseConflictJsonbBuildObjectValueAlloc(insert_columns, insert_values);
            defer self.alloc.free(value_json);
            if (!first) try writer.writeByte(',');
            first = false;
            try writer.print("{f}:", .{std.json.fmt(key, .{})});
            try writer.writeAll(value_json);
            if (self.match(.comma) == null) break;
        }
        try self.expect(.rparen);
        try writer.writeByte('}');
        return try out.toOwnedSlice();
    }

    fn parseConflictJsonbBuildObjectValueAlloc(
        self: *@This(),
        insert_columns: []const []const u8,
        insert_values: []const []const u8,
    ) ![]const u8 {
        if (self.peekKeyword("to_jsonb")) {
            try self.expectKeyword("to_jsonb");
            try self.expect(.lparen);
            const value_json = try self.parseConflictJsonbBuildObjectValueAlloc(insert_columns, insert_values);
            errdefer self.alloc.free(value_json);
            try self.expect(.rparen);
            return value_json;
        }
        if (self.peekKind(.identifier) and self.pos < self.tokens.len) {
            const token = self.tokens[self.pos];
            if (std.mem.startsWith(u8, token.text, "excluded.")) {
                self.pos += 1;
                return try self.conflictExcludedJsonObjectValueAlloc(token.text["excluded.".len..], insert_columns, insert_values);
            }
        }
        return try self.parseJsonValueAlloc();
    }

    fn conflictExcludedJsonObjectValueAlloc(
        self: *@This(),
        source: []const u8,
        insert_columns: []const []const u8,
        insert_values: []const []const u8,
    ) ![]const u8 {
        _ = relationalColumnForField(self.schema, source, null) orelse return error.InvalidSqlCatalog;
        for (insert_columns, insert_values) |insert_column, insert_value| {
            if (std.mem.eql(u8, insert_column, source)) return try self.alloc.dupe(u8, insert_value);
        }
        return error.UnsupportedSqlShape;
    }

    fn canParseConflictBooleanAssignmentExpression(
        self: *@This(),
        insert_columns: []const []const u8,
    ) bool {
        if (!self.conflictBooleanExpressionCanStartAt(self.pos, insert_columns)) return false;

        var depth: usize = 0;
        var i = self.pos;
        var saw_boolean_operator = false;
        while (i < self.tokens.len) : (i += 1) {
            const token = self.tokens[i];
            switch (token.kind) {
                .semicolon, .comma => if (depth == 0) break,
                .rparen => {
                    if (depth == 0) break;
                    depth -= 1;
                },
                .lparen => depth += 1,
                .eq, .neq, .gt, .gte, .lt, .lte, .arrow_text, .arrow_json, .path_arrow_text, .path_arrow_json, .at_contains, .range_overlap, .question, .regex_match, .regex_imatch, .regex_not_match, .regex_not_imatch => return false,
                .identifier => {
                    if (depth == 0 and sqlAssignmentTailKeyword(token.text)) break;
                    if (sqlKeywordStartsScalarPredicate(token.text)) return false;
                    if (std.ascii.eqlIgnoreCase(token.text, "and") or
                        std.ascii.eqlIgnoreCase(token.text, "or") or
                        std.ascii.eqlIgnoreCase(token.text, "not"))
                    {
                        saw_boolean_operator = true;
                    }
                },
                else => {},
            }
        }
        return saw_boolean_operator;
    }

    fn canParseConflictAssignmentExpression(
        self: *@This(),
        insert_columns: []const []const u8,
    ) bool {
        if (self.peekKind(.minus)) {
            if (self.pos + 1 >= self.tokens.len) return false;
            return self.tokens[self.pos + 1].kind != .number;
        }
        if (self.nextRowExpressionHasTopLevelPipeConcat()) return true;
        if (self.peekKeyword("case") or
            self.peekKeyword("cast") or
            self.peekKeyword("coalesce") or
            self.peekKeyword("lower") or
            self.peekKeyword("upper") or
            self.peekInitcapFunctionCall() or
            self.peekKeyword("trim") or
            self.peekTrimVariantFunctionCall() or
            self.peekKeyword("replace") or
            self.peekKeyword("regexp_replace") or
            self.peekRegexpSubstrFunctionCall() or
            self.peekRegexpMatchFunctionCall() or
            self.peekRegexpCountFunctionCall() or
            self.peekRegexpInstrFunctionCall() or
            self.peekTranslateFunctionCall() or
            self.peekKeyword("concat") or
            self.peekKeyword("concat_ws") or
            self.peekKeyword("nullif") or
            self.peekTextLengthFunctionKeyword() or
            self.peekAsciiFunctionCall() or
            self.peekChrFunctionCall() or
            self.peekSubstringFunctionKeyword() or
            self.peekOverlayFunctionCall() or
            self.peekSplitPartFunctionKeyword() or
            self.peekStrposFunctionKeyword() or
            self.peekLeftRightFunctionCall() or
            self.peekPadFunctionCall() or
            self.peekRepeatFunctionCall() or
            self.peekReverseFunctionCall() or
            self.peekMd5FunctionCall() or
            self.peekStartsWithFunctionCall() or
            self.peekEndsWithFunctionCall() or
            self.peekDateTruncFunctionCall() or
            self.peekDateBinFunctionCall() or
            self.peekDatePartFunctionCall() or
            self.peekKeyword("position") or
            self.peekKeyword("abs") or
            self.peekKeyword("round") or
            self.peekFunctionCall("trunc") or
            self.peekFunctionCall("floor") or
            self.peekFunctionCall("ceil") or
            self.peekFunctionCall("sqrt") or
            self.peekFunctionCall("sign") or
            self.peekFunctionCall("mod") or
            self.peekFunctionCall("power") or
            self.peekKeyword("greatest") or
            self.peekKeyword("least") or
            self.peekJsonExtractPathFunctionCall() or
            self.peekJsonTypeofFunctionCall() or
            self.peekJsonArrayLengthFunctionCall() or
            self.peekJsonBuildObjectFunctionCall() or
            self.peekArrayLengthFunctionCall() or
            self.peekArrayPositionFunctionCall() or
            self.peekKeyword("array_append") or
            self.peekKeyword("array_prepend") or
            self.peekKeyword("array_cat") or
            self.peekKeyword("array_remove") or
            self.peekKeyword("array_replace") or
            self.peekKeyword("array_to_string") or
            self.peekKeyword("string_to_array") or
            self.peekKeyword("now") or
            self.peekKeyword("current_timestamp") or
            self.peekKeyword("current_date") or
            self.peekSqlTypedDatetimeLiteral() or
            self.peekKeyword("interval"))
        {
            return true;
        }
        if (self.peekKind(.lparen)) return true;
        if (!self.peekKind(.identifier) or
            self.peekKeyword("default") or
            self.peekKeyword("null") or
            self.peekKeyword("true") or
            self.peekKeyword("false"))
        {
            return false;
        }
        const token = self.tokens[self.pos];
        if (std.mem.startsWith(u8, token.text, "excluded.")) {
            const source = token.text["excluded.".len..];
            const source_column = relationalColumnForField(self.schema, source, null) orelse return false;
            return conflictProposedColumnAvailable(insert_columns, source_column, source);
        }
        if (self.conflictExistingFieldName(token.text)) |field| {
            return relationalColumnForField(self.schema, field, null) != null;
        }
        return relationalColumnForField(self.schema, token.text, null) != null;
    }

    fn conflictProposedColumnAvailable(
        insert_columns: []const []const u8,
        source_column: runtime_schema.RelationalColumn,
        source: []const u8,
    ) bool {
        for (insert_columns) |insert_column| {
            if (std.mem.eql(u8, insert_column, source)) return true;
        }
        return source_column.default_value != null or source_column.generated != null;
    }

    fn conflictExistingFieldName(self: *@This(), text: []const u8) ?[]const u8 {
        var dot: ?usize = std.mem.indexOfScalar(u8, text, '.');
        while (dot) |index| {
            if (index > 0 and index + 1 < text.len) {
                const qualifier = text[0..index];
                const field = text[index + 1 ..];
                if (self.conflictQualifierMatches(qualifier)) return field;
            }
            dot = std.mem.indexOfScalarPos(u8, text, index + 1, '.');
        }
        return null;
    }

    fn conflictQualifierMatches(self: *@This(), qualifier: []const u8) bool {
        for (self.conflict_existing_qualifiers) |expected| {
            if (std.mem.eql(u8, qualifier, expected)) return true;
        }
        const normalized = normalizeSqlObjectIdentifierAlloc(self.alloc, qualifier) catch return false;
        defer self.alloc.free(normalized);
        for (self.conflict_existing_qualifiers) |expected| {
            if (std.mem.eql(u8, normalized, expected)) return true;
        }
        return false;
    }

    fn conflictExcludedValueJsonAlloc(
        self: *@This(),
        column: runtime_schema.RelationalColumn,
        source: []const u8,
        insert_columns: []const []const u8,
        insert_values: []const []const u8,
    ) ![]const u8 {
        const source_column = relationalColumnForField(self.schema, source, null) orelse return error.InvalidSqlCatalog;
        if (source_column.field_type != column.field_type) return error.UnsupportedSqlShape;
        for (insert_columns, insert_values) |insert_column, insert_value| {
            if (std.mem.eql(u8, insert_column, source)) return try self.alloc.dupe(u8, insert_value);
        }
        return error.UnsupportedSqlShape;
    }

    fn parseConflictCoalesceValueJsonAlloc(
        self: *@This(),
        column: runtime_schema.RelationalColumn,
        insert_columns: []const []const u8,
        insert_values: []const []const u8,
    ) ![]const u8 {
        try self.expectKeyword("coalesce");
        try self.expect(.lparen);

        var selected: ?[]const u8 = null;
        errdefer if (selected) |value| self.alloc.free(value);
        var operands: usize = 0;
        while (true) {
            const value_json = try self.parseConflictCoalesceOperandJsonAlloc(column, insert_columns, insert_values);
            var value_transferred = false;
            defer if (!value_transferred) self.alloc.free(value_json);
            operands += 1;
            if (selected == null and !std.mem.eql(u8, value_json, "null")) {
                selected = value_json;
                value_transferred = true;
            }
            if (self.match(.comma) == null) break;
        }
        if (operands == 0) return error.UnsupportedSqlShape;
        try self.expect(.rparen);

        if (selected) |value| {
            selected = null;
            return value;
        }
        return try self.alloc.dupe(u8, "null");
    }

    fn parseConflictCoalesceOperandJsonAlloc(
        self: *@This(),
        column: runtime_schema.RelationalColumn,
        insert_columns: []const []const u8,
        insert_values: []const []const u8,
    ) ![]const u8 {
        if (self.peekKind(.identifier) and self.pos < self.tokens.len) {
            const token = self.tokens[self.pos];
            if (std.mem.startsWith(u8, token.text, "excluded.")) {
                self.pos += 1;
                return try self.conflictExcludedValueJsonAlloc(column, token.text["excluded.".len..], insert_columns, insert_values);
            }
        }
        return try self.parseSqlColumnValueAlloc(column);
    }

    fn parseConflictAssignmentExpressionAlloc(
        self: *@This(),
        column: runtime_schema.RelationalColumn,
        insert_columns: []const []const u8,
