            try self.expect(.rparen);
        }
        const expression: db_mod.types.RelationalRowsExpression = .{
            .kind = .json_build_object,
            .operands = try operands.toOwnedSlice(self.alloc),
        };
        try self.validateJsonBuildObjectExpression(expression);
        return expression;
    }

