    fn parseConflictExpressionConditionAlloc(
        self: *@This(),
        column: runtime_schema.RelationalColumn,
        insert_columns: []const []const u8,
    ) anyerror!db_mod.types.RelationalRowsExpressionCondition {
        if (self.canParseBareBooleanConflictExpression(insert_columns)) {
            return try self.parseBareBooleanConflictExpressionConditionAlloc(column, insert_columns);
        }

        const lhs = try self.parseConflictUntypedExpressionAlloc(column, insert_columns);
        var lhs_transferred = false;
        errdefer if (!lhs_transferred) freeExpression(self.alloc, lhs);

        const op: runtime_schema.RelationalCheckOp = if (self.matchKeyword("is")) blk: {
            const not = self.matchKeyword("not");
            if (self.matchKeyword("distinct")) {
                try self.expectKeyword("from");
                break :blk if (not) .is_not_distinct else .is_distinct;
            }
            if (self.matchKeyword("unknown")) {
                try self.validateBooleanRowExpression(lhs);
                lhs_transferred = true;
                return expressionNullTestCondition(lhs, if (not) .is_not_null else .is_null);
            }
            if (self.matchKeyword("true") or self.matchKeyword("false")) {
                const value = std.ascii.eqlIgnoreCase(self.tokens[self.pos - 1].text, "true");
                try self.validateBooleanRowExpression(lhs);
                if (not) return error.UnsupportedSqlShape;
                const condition = try self.expressionBooleanComparisonConditionAlloc(lhs, .eq, value);
                lhs_transferred = true;
                return condition;
            }
            try self.expectKeyword("null");
            break :blk if (not) .is_not_null else .is_null;
        } else if (self.matchPostfixNullTest()) |postfix_null_test|
            postfix_null_test
        else
            try self.parseComparisonOp();

        if (op == .eq and self.matchAnyOrSomeKeyword()) {
            try self.expect(.lparen);
            const values_json = try self.parseJsonArrayValueAlloc();
            defer self.alloc.free(values_json);
            try self.expect(.rparen);
            return error.UnsupportedSqlShape;
        }

        const rhs = switch (op) {
            .is_null, .is_not_null => &.{},
            else => blk: {
                const out = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
                var out_transferred = false;
                errdefer if (!out_transferred) self.alloc.free(out);
                out[0] = try self.parseConflictUntypedExpressionAlloc(column, insert_columns);
                out_transferred = true;
                break :blk out;
            },
        };
        var rhs_transferred = false;
        errdefer if (!rhs_transferred and rhs.len > 0) {
            for (rhs) |expression| freeExpression(self.alloc, expression);
            self.alloc.free(rhs);
        };
        try self.validateExpressionConditionTypes(lhs, op, rhs);

        lhs_transferred = true;
        rhs_transferred = true;
        return .{
            .lhs = lhs,
            .op = op,
            .rhs = rhs,
        };
    }

    fn canParseBareBooleanConflictExpression(
        self: *@This(),
        insert_columns: []const []const u8,
    ) bool {
        if (!self.conflictBooleanExpressionCanStartAt(self.pos, insert_columns)) return false;

        var depth: usize = 0;
        var i = self.pos;
        var saw_boolean_syntax = false;
        var saw_token = false;
        while (i < self.tokens.len) : (i += 1) {
            const token = self.tokens[i];
            switch (token.kind) {
                .semicolon, .comma => if (depth == 0) break,
                .rparen => {
                    if (depth == 0) break;
                    depth -= 1;
                },
                .lparen => {
                    depth += 1;
                    saw_token = true;
                },
                .eq, .neq, .gt, .gte, .lt, .lte, .arrow_text, .arrow_json, .path_arrow_text, .path_arrow_json, .at_contains, .range_overlap, .question, .regex_match, .regex_imatch, .regex_not_match, .regex_not_imatch => return false,
                .identifier => {
                    if (depth == 0 and tokenStartsWhereTailClause(token.text)) break;
                    if (sqlKeywordStartsScalarPredicate(token.text)) return false;
                    if (std.ascii.eqlIgnoreCase(token.text, "and") or
                        std.ascii.eqlIgnoreCase(token.text, "or") or
                        std.ascii.eqlIgnoreCase(token.text, "not"))
                    {
                        saw_boolean_syntax = true;
                    }
                    saw_token = true;
                },
                else => saw_token = true,
            }
        }
        if (!saw_token) return false;
        return saw_boolean_syntax or self.singleConflictBooleanExpressionCanStartAt(self.pos, insert_columns);
    }

    fn conflictBooleanExpressionCanStartAt(
        self: *@This(),
        index: usize,
        insert_columns: []const []const u8,
    ) bool {
        if (index >= self.tokens.len) return false;
        if (self.tokens[index].kind == .lparen) {
            const inner = self.predicateStartIndexAfterOpenParens(index);
            return self.conflictBooleanExpressionCanStartAt(inner, insert_columns);
        }
        return self.singleConflictBooleanExpressionCanStartAt(index, insert_columns);
    }

    fn singleConflictBooleanExpressionCanStartAt(
        self: *@This(),
        index: usize,
        insert_columns: []const []const u8,
    ) bool {
        if (index >= self.tokens.len) return false;
        const token = self.tokens[index];
        if (token.kind != .identifier) return false;
        if (std.ascii.eqlIgnoreCase(token.text, "not") or
            std.ascii.eqlIgnoreCase(token.text, "true") or
            std.ascii.eqlIgnoreCase(token.text, "false") or
            std.ascii.eqlIgnoreCase(token.text, "case") or
            std.ascii.eqlIgnoreCase(token.text, "cast") or
            std.ascii.eqlIgnoreCase(token.text, "coalesce") or
            std.ascii.eqlIgnoreCase(token.text, "nullif") or
            sqlKeywordIsStartsWithFunction(token.text))
        {
            return true;
        }
        if (std.mem.startsWith(u8, token.text, "excluded.")) {
            const field = token.text["excluded.".len..];
            const source_column = relationalColumnForField(self.schema, field, .boolean) orelse return false;
            return conflictProposedColumnAvailable(insert_columns, source_column, field);
        }
        const field = self.conflictExistingFieldName(token.text) orelse token.text;
        return relationalColumnForField(self.schema, field, .boolean) != null;
    }

