    fn parseWhere(
        self: *@This(),
        predicates: *std.ArrayListUnmanaged(runtime_schema.RelationalCheck),
        json_contains: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonContainsPredicate),
        json_path_eq: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonPathEqPredicate),
        json_path_exists: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonPathExistsPredicate),
        array_any: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayAnyPredicate),
        array_contains: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayContainsPredicate),
        array_eq: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayEqPredicate),
        in_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsInPredicate),
        text_patterns: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsTextPatternPredicate),
        or_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsPredicateGroup),
        not_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsPredicateGroup),
        access_or_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsAccessPredicateGroup),
        access_not_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsAccessPredicateGroup),
        expression_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition),
        expression_or_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
        expression_not_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
        expression_array_contains: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionArrayContainsPredicate),
    ) !void {
        if (try self.canParseBareBooleanWhereExpression()) {
            try self.parseBareBooleanWhereExpression(expression_predicates);
            return;
        }
        if (self.whereHasTopLevelOr()) {
            if (self.whereTopLevelOrHasExpressionPredicateStart()) {
                try self.parseExpressionOrWhere(expression_or_predicates);
            } else if (self.whereTopLevelOrHasAccessPredicate()) {
                try self.parseAccessOrWhere(access_or_predicates);
            } else {
                try self.parseScalarOrWhere(or_predicates);
            }
            return;
        }
        if (!self.canParseAccessNotWhere() and try self.whereHasArrayOverlapPredicate()) {
            try self.parseAccessOrWhere(access_or_predicates);
            return;
        }
        while (true) {
            if (self.canParseScalarNotWhere()) {
                try self.parseScalarNotWhere(not_predicates);
            } else if (self.canParseExpressionNotWhere()) {
                try self.parseExpressionNotWhere(expression_not_predicates);
            } else if (self.canParseAccessNotWhere()) {
                try self.parseAccessNotWhere(access_not_predicates);
            } else if (self.peekKeyword("string_to_array")) {
                if (self.stringToArrayPredicateIsContainment()) {
                    const predicate = try self.parseExpressionArrayContainsPredicateAlloc();
                    var predicate_transferred = false;
                    errdefer if (!predicate_transferred) freeExpressionArrayContainsOne(self.alloc, predicate);
                    try expression_array_contains.append(self.alloc, predicate);
                    predicate_transferred = true;
                } else {
                    try self.parseExpressionWhereConditions(expression_predicates, expression_or_predicates, expression_not_predicates);
                }
            } else if (try self.canParseBareBooleanWhereExpression()) {
                try self.parseBareBooleanWhereExpression(expression_predicates);
            } else if (try self.canParseExpressionWhereCondition()) {
                try self.parseExpressionWhereConditions(expression_predicates, expression_or_predicates, expression_not_predicates);
            } else {
                try self.parseWhereAtom(predicates, json_contains, json_path_eq, json_path_exists, array_any, array_contains, array_eq, in_predicates, text_patterns, or_predicates, false);
            }
            if (!self.matchKeyword("and")) break;
        }
    }

    fn canParseBareBooleanWhereExpression(self: *@This()) !bool {
        if (!self.booleanExpressionCanStartAt(self.pos)) return false;

        var depth: usize = 0;
        var i = self.pos;
        var saw_boolean_syntax = false;
        var saw_token = false;
        while (i < self.tokens.len) : (i += 1) {
            const token = self.tokens[i];
            switch (token.kind) {
                .semicolon, .comma => if (depth == 0) break,
                .rparen => {
                    if (depth == 0) break;
                    depth -= 1;
                },
                .lparen => {
                    depth += 1;
                    saw_token = true;
                },
                .eq, .neq, .gt, .gte, .lt, .lte, .arrow_text, .arrow_json, .path_arrow_text, .path_arrow_json, .at_contains, .range_overlap, .question, .regex_match, .regex_imatch, .regex_not_match, .regex_not_imatch => return false,
                .identifier => {
                    if (depth == 0 and tokenStartsWhereTailClause(token.text)) break;
                    if (sqlKeywordStartsScalarPredicate(token.text)) return false;
                    if (std.ascii.eqlIgnoreCase(token.text, "and") or
                        std.ascii.eqlIgnoreCase(token.text, "or") or
                        std.ascii.eqlIgnoreCase(token.text, "not"))
                    {
                        saw_boolean_syntax = true;
                    }
                    saw_token = true;
                },
                else => saw_token = true,
            }
        }
        if (!saw_token) return false;
        return saw_boolean_syntax or self.singleBooleanExpressionCanStartAt(self.pos);
    }

    fn booleanExpressionCanStartAt(self: *@This(), index: usize) bool {
        if (index >= self.tokens.len) return false;
        if (self.tokens[index].kind == .lparen) {
            const inner = self.predicateStartIndexAfterOpenParens(index);
            return self.booleanExpressionCanStartAt(inner);
        }
        return self.singleBooleanExpressionCanStartAt(index);
    }

    fn singleBooleanExpressionCanStartAt(self: *@This(), index: usize) bool {
        if (index >= self.tokens.len) return false;
        const token = self.tokens[index];
        if (token.kind != .identifier) return false;
        return std.ascii.eqlIgnoreCase(token.text, "not") or
            std.ascii.eqlIgnoreCase(token.text, "true") or
            std.ascii.eqlIgnoreCase(token.text, "false") or
            std.ascii.eqlIgnoreCase(token.text, "case") or
            std.ascii.eqlIgnoreCase(token.text, "cast") or
            std.ascii.eqlIgnoreCase(token.text, "coalesce") or
            std.ascii.eqlIgnoreCase(token.text, "nullif") or
            sqlKeywordIsRegexpMatchFunction(token.text) or
            sqlKeywordIsStartsWithFunction(token.text) or
            relationalColumnForField(self.schema, token.text, null) != null;
    }

    fn parseBareBooleanWhereExpression(
        self: *@This(),
        expression_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition),
    ) !void {
        const expression = try self.parseBooleanRowExpressionAlloc();
        var expression_transferred = false;
        errdefer if (!expression_transferred) freeExpression(self.alloc, expression);
        try self.validateBooleanRowExpression(expression);
        if (expression.kind == .value and std.mem.eql(u8, expression.value_json, "true")) {
            freeExpression(self.alloc, expression);
            expression_transferred = true;
            return;
        }

        const value_json = try self.alloc.dupe(u8, "true");
        var value_transferred = false;
        errdefer if (!value_transferred) self.alloc.free(value_json);
        const rhs = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
        var rhs_transferred = false;
        errdefer if (!rhs_transferred) self.alloc.free(rhs);
        rhs[0] = .{
            .kind = .value,
            .value_json = value_json,
        };

        try expression_predicates.append(self.alloc, .{
            .lhs = expression,
            .op = .eq,
            .rhs = rhs,
        });
        expression_transferred = true;
        value_transferred = true;
        rhs_transferred = true;
    }

    fn valueEqualsAnyArrayPredicateCanStart(self: *@This()) bool {
        if (self.pos >= self.tokens.len) return false;
        const value_end = switch (self.tokens[self.pos].kind) {
            .string, .number, .placeholder => self.pos + 1,
            .minus => blk: {
                if (self.pos + 1 >= self.tokens.len or self.tokens[self.pos + 1].kind != .number) return false;
                break :blk self.pos + 2;
            },
            .identifier => blk: {
                const text = self.tokens[self.pos].text;
                if (!std.ascii.eqlIgnoreCase(text, "null") and
                    !std.ascii.eqlIgnoreCase(text, "true") and
                    !std.ascii.eqlIgnoreCase(text, "false"))
                {
                    return false;
                }
                break :blk self.pos + 1;
            },
            else => return false,
        };
        if (value_end + 3 >= self.tokens.len) return false;
        return self.tokens[value_end].kind == .eq and
            self.tokens[value_end + 1].kind == .identifier and
            sqlKeywordIsAnyOrSome(self.tokens[value_end + 1].text) and
            self.tokens[value_end + 2].kind == .lparen and
            self.tokens[value_end + 3].kind == .identifier;
    }

    fn canParseExpressionWhereCondition(self: *@This()) !bool {
        if (self.peekStandaloneSqlBooleanLiteral() != null) return true;
        if (self.nextRowExpressionHasTopLevelPipeConcat()) return true;
        if (self.peekKind(.minus)) return true;
        if (self.peekKeyword("lower") or self.peekKeyword("upper")) return !(try self.generatedExpressionCallHasGeneratedColumn());
        if (self.peekInitcapFunctionCall()) return true;
        if (self.peekMd5FunctionCall()) return !(try self.generatedExpressionCallHasGeneratedColumn());
        if (self.peekKeyword("concat") or self.peekKeyword("concat_ws")) return !(try self.generatedExpressionCallHasGeneratedColumn());
        if (self.peekJsonExtractPathFunctionCall() or
            self.peekJsonTypeofFunctionCall() or
            self.peekJsonArrayLengthFunctionCall() or
            self.peekJsonBuildObjectFunctionCall() or
            self.peekArrayLengthFunctionCall() or
            self.peekArrayPositionFunctionCall() or
            self.peekKeyword("array_append") or
            self.peekKeyword("array_prepend") or
            self.peekKeyword("array_cat") or
            self.peekKeyword("array_remove") or
            self.peekKeyword("array_replace") or
            self.peekKeyword("array_to_string") or
            self.peekKeyword("case") or
            self.peekKeyword("cast") or
            self.peekKeyword("coalesce") or
            self.peekRegexpMatchFunctionCall() or
            self.peekRegexpSubstrFunctionCall() or
            self.peekRegexpCountFunctionCall() or
            self.peekRegexpInstrFunctionCall() or
            self.peekKeyword("nullif") or
            self.peekTextLengthFunctionKeyword() or
            self.peekAsciiFunctionCall() or
            self.peekChrFunctionCall() or
            self.peekSubstringFunctionKeyword() or
            self.peekOverlayFunctionCall() or
            self.peekSplitPartFunctionKeyword() or
            self.peekStrposFunctionKeyword() or
            self.peekLeftRightFunctionCall() or
            self.peekPadFunctionCall() or
            self.peekRepeatFunctionCall() or
            self.peekReverseFunctionCall() or
            self.peekStartsWithFunctionCall() or
            self.peekEndsWithFunctionCall() or
            self.peekDateTruncFunctionCall() or
            self.peekDateBinFunctionCall() or
            self.peekDatePartFunctionCall() or
            self.peekKeyword("position") or
            self.peekKeyword("abs") or
            self.peekKeyword("round") or
            self.peekFunctionCall("trunc") or
            self.peekFunctionCall("floor") or
            self.peekFunctionCall("ceil") or
            self.peekFunctionCall("sqrt") or
            self.peekFunctionCall("sign") or
            self.peekFunctionCall("mod") or
            self.peekFunctionCall("power") or
            self.peekKeyword("greatest") or
            self.peekKeyword("least")) return true;
        if (self.expressionNullSafeDistinctPredicateCanStartAt(self.pos)) return true;
        if (self.textPatternSetPredicateCanStartAt(self.pos)) return true;
        if (self.peekKeyword("trim")) return true;
        if (self.peekTrimVariantFunctionCall()) return true;
        if (self.peekKeyword("replace")) return true;
        if (self.peekKeyword("regexp_replace")) return true;
        if (self.peekRegexpMatchFunctionCall()) return true;
        if (self.peekRegexpCountFunctionCall()) return true;
        if (self.peekRegexpInstrFunctionCall()) return true;
        if (self.peekTranslateFunctionCall()) return true;
        if (self.peekKeyword("concat_ws")) return true;
        if (self.jsonExtractNullTestPredicateCanStartAt(self.pos)) return true;
        if (self.jsonExtractNullSafeDistinctPredicateCanStartAt(self.pos)) return true;
        if (self.jsonExtractMembershipPredicateCanStartAt(self.pos)) return true;
        if (self.jsonKeySetExpressionCanStartAt(self.pos)) return true;
        if (self.peekKind(.identifier) and
            !self.peekKeyword("null") and
            !self.peekKeyword("true") and
            !self.peekKeyword("false") and
            self.pos + 1 < self.tokens.len)
        {
            return switch (self.tokens[self.pos + 1].kind) {
                .plus, .minus, .star, .slash, .percent, .pipe_concat, .regex_match, .regex_imatch, .regex_not_match, .regex_not_imatch => true,
                else => false,
            };
        }
        if (self.parenthesizedBooleanIsPredicateCanStartAt(self.pos)) return true;
