        }
        var json_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonContainsPredicate).empty;
        errdefer {
            freeJsonContains(self.alloc, json_contains.items);
            json_contains.deinit(self.alloc);
        }
        var json_path_exists = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonPathExistsPredicate).empty;
        errdefer {
            freeJsonPathExists(self.alloc, json_path_exists.items);
            json_path_exists.deinit(self.alloc);
        }
        var array_any = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayAnyPredicate).empty;
        errdefer {
            freeArrayAny(self.alloc, array_any.items);
            array_any.deinit(self.alloc);
        }
        var array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayContainsPredicate).empty;
        errdefer {
            freeArrayContains(self.alloc, array_contains.items);
            array_contains.deinit(self.alloc);
        }
        var array_eq = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayEqPredicate).empty;
        errdefer {
            freeArrayEq(self.alloc, array_eq.items);
            array_eq.deinit(self.alloc);
        }
        var in_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsInPredicate).empty;
        errdefer {
            freeInPredicates(self.alloc, in_predicates.items);
            in_predicates.deinit(self.alloc);
        }
        var text_patterns = std.ArrayListUnmanaged(db_mod.types.RelationalRowsTextPatternPredicate).empty;
        errdefer {
            freeTextPatterns(self.alloc, text_patterns.items);
            text_patterns.deinit(self.alloc);
        }
        var nested_or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsPredicateGroup).empty;
        defer {
            freePredicateGroups(self.alloc, nested_or_predicates.items);
            nested_or_predicates.deinit(self.alloc);
        }

        try self.parseWhereAtom(
            &predicates,
            &json_contains,
            &json_path_eq,
            &json_path_exists,
            &array_any,
            &array_contains,
            &array_eq,
            &in_predicates,
            &text_patterns,
            &nested_or_predicates,
            false,
        );
        if (nested_or_predicates.items.len > 0) return error.UnsupportedSqlShape;

        const group = db_mod.types.RelationalRowsAccessPredicateGroup{
            .predicates = try predicates.toOwnedSlice(self.alloc),
            .array_any = try array_any.toOwnedSlice(self.alloc),
            .array_contains = try array_contains.toOwnedSlice(self.alloc),
            .array_eq = try array_eq.toOwnedSlice(self.alloc),
            .in_predicates = try in_predicates.toOwnedSlice(self.alloc),
            .json_contains = try json_contains.toOwnedSlice(self.alloc),
            .json_path_eq = try json_path_eq.toOwnedSlice(self.alloc),
            .json_path_exists = try json_path_exists.toOwnedSlice(self.alloc),
            .text_patterns = try text_patterns.toOwnedSlice(self.alloc),
        };
        if (!accessPredicateGroupHasAnyPredicate(group)) {
            freeAccessPredicateGroup(self.alloc, group);
            return error.UnsupportedSqlShape;
        }
        return group;
    }

    fn parseAccessOrWhere(
        self: *@This(),
        access_or_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsAccessPredicateGroup),
    ) !void {
        while (true) {
            const parenthesized = self.match(.lparen) != null;
            const groups = try self.parseAccessPredicateGroupsAlloc();
            var groups_transferred = false;
            errdefer if (!groups_transferred) {
                freeAccessPredicateGroups(self.alloc, groups);
                self.alloc.free(groups);
            };
            if (parenthesized) try self.expect(.rparen);
            try access_or_predicates.appendSlice(self.alloc, groups);
            groups_transferred = true;
            self.alloc.free(groups);
            if (!self.matchKeyword("or")) break;
        }
    }

    fn parseAccessNotWhere(
        self: *@This(),
        access_not_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsAccessPredicateGroup),
    ) !void {
        try self.expectKeyword("not");
        try self.expect(.lparen);
        while (true) {
            const parenthesized = self.match(.lparen) != null;
            const groups = try self.parseAccessPredicateGroupsAlloc();
            var groups_transferred = false;
            errdefer if (!groups_transferred) {
                freeAccessPredicateGroups(self.alloc, groups);
                self.alloc.free(groups);
            };
            if (parenthesized) try self.expect(.rparen);
            try access_not_predicates.appendSlice(self.alloc, groups);
            groups_transferred = true;
            self.alloc.free(groups);
            if (!self.matchKeyword("or")) break;
        }
        try self.expect(.rparen);
    }

    fn parseArrayOverlapIntoAccessBranches(
        self: *@This(),
        branches: *std.ArrayListUnmanaged(AccessPredicateBranch),
    ) !bool {
        const saved_pos = self.pos;
        const parsed_field = self.parseFieldExpressionOwned() catch |err| {
            self.pos = saved_pos;
            return switch (err) {
                error.UnsupportedSqlShape, error.InvalidSqlCatalog => false,
                else => err,
            };
        };
        defer self.alloc.free(parsed_field);
        if (!self.peekKind(.range_overlap)) {
            self.pos = saved_pos;
            return false;
        }

        const field = self.normalizeRowExpressionFieldAlloc(parsed_field) catch |err| {
            self.pos = saved_pos;
            return switch (err) {
                error.UnsupportedSqlShape, error.InvalidSqlCatalog => false,
                else => err,
            };
        };
        defer self.alloc.free(field);
        const column = relationalColumnForField(self.schema, field, .array) orelse {
            self.pos = saved_pos;
            return false;
        };
        _ = self.match(.range_overlap);
        const values_json = try self.parseArrayPredicateValueAlloc();
        defer self.alloc.free(values_json);
        try self.validateSqlArrayValueJson(column, values_json);
        try self.expandArrayOverlapValuesIntoAccessBranches(branches, field, values_json);
        return true;
    }

    fn expandArrayOverlapValuesIntoAccessBranches(
        self: *@This(),
        branches: *std.ArrayListUnmanaged(AccessPredicateBranch),
        field: []const u8,
        values_json: []const u8,
    ) !void {
        var parsed = std.json.parseFromSlice(std.json.Value, self.alloc, values_json, .{}) catch return error.UnsupportedSqlShape;
        defer parsed.deinit();
        if (parsed.value != .array or parsed.value.array.items.len == 0) return error.UnsupportedSqlShape;
        if (branches.items.len == 0 or branches.items.len > max_scalar_or_expanded_branches / parsed.value.array.items.len) return error.UnsupportedSqlShape;

        var expanded = std.ArrayListUnmanaged(AccessPredicateBranch).empty;
        errdefer self.freeAccessPredicateBranches(&expanded);
        for (branches.items) |source_branch| {
            for (parsed.value.array.items) |value| {
                var branch: AccessPredicateBranch = .{};
                var branch_transferred = false;
                errdefer if (!branch_transferred) self.freeAccessPredicateBranch(&branch);
                try self.cloneAccessPredicateBranchInto(&branch, source_branch);
                try self.appendArrayAnyJsonValueToAccessBranch(&branch, field, value);
                try expanded.append(self.alloc, branch);
                branch_transferred = true;
            }
        }

        self.freeAccessPredicateBranches(branches);
        branches.* = expanded;
    }

    fn appendArrayAnyJsonValueToAccessBranch(
        self: *@This(),
        branch: *AccessPredicateBranch,
        field: []const u8,
        value: std.json.Value,
    ) !void {
        const owned_field = try self.alloc.dupe(u8, field);
        var field_transferred = false;
        errdefer if (!field_transferred) self.alloc.free(owned_field);
        const value_json = try std.json.Stringify.valueAlloc(self.alloc, value, .{});
        var value_transferred = false;
        errdefer if (!value_transferred) self.alloc.free(value_json);
        try branch.array_any.append(self.alloc, .{
            .field = owned_field,
            .value_json = value_json,
        });
        field_transferred = true;
        value_transferred = true;
    }

    fn appendAccessPredicateGroupToBranches(
        self: *@This(),
        branches: *std.ArrayListUnmanaged(AccessPredicateBranch),
        group: db_mod.types.RelationalRowsAccessPredicateGroup,
    ) !void {
        if (branches.items.len == 0) return error.UnsupportedSqlShape;
        for (branches.items) |*branch| {
            try self.appendAccessPredicateGroupToBranch(branch, group);
        }
    }

    fn appendAccessPredicateGroupToBranch(
        self: *@This(),
        branch: *AccessPredicateBranch,
        group: db_mod.types.RelationalRowsAccessPredicateGroup,
    ) !void {
        for (group.predicates) |predicate| try self.appendRelationalCheckClone(&branch.predicates, predicate);
        for (group.array_any) |predicate| try self.appendArrayAnyClone(&branch.array_any, predicate);
        for (group.array_contains) |predicate| try self.appendArrayContainsClone(&branch.array_contains, predicate);
        for (group.array_eq) |predicate| try self.appendArrayEqClone(&branch.array_eq, predicate);
        for (group.in_predicates) |predicate| try self.appendInPredicateClone(&branch.in_predicates, predicate);
        for (group.json_contains) |predicate| try self.appendJsonContainsClone(&branch.json_contains, predicate);
        for (group.json_path_eq) |predicate| try self.appendJsonPathEqClone(&branch.json_path_eq, predicate);
        for (group.json_path_exists) |predicate| try self.appendJsonPathExistsClone(&branch.json_path_exists, predicate);
        for (group.text_patterns) |predicate| try self.appendTextPatternClone(&branch.text_patterns, predicate);
    }

    fn cloneAccessPredicateBranchInto(
        self: *@This(),
        dest: *AccessPredicateBranch,
        source: AccessPredicateBranch,
    ) !void {
        try self.appendAccessPredicateGroupToBranch(dest, .{
            .predicates = source.predicates.items,
            .array_any = source.array_any.items,
            .array_contains = source.array_contains.items,
            .array_eq = source.array_eq.items,
            .in_predicates = source.in_predicates.items,
            .json_contains = source.json_contains.items,
            .json_path_eq = source.json_path_eq.items,
            .json_path_exists = source.json_path_exists.items,
            .text_patterns = source.text_patterns.items,
        });
    }

    fn accessPredicateBranchToGroupAlloc(
        self: *@This(),
        branch: *AccessPredicateBranch,
    ) !db_mod.types.RelationalRowsAccessPredicateGroup {
        var group: db_mod.types.RelationalRowsAccessPredicateGroup = .{};
        errdefer freeAccessPredicateGroup(self.alloc, group);
        group.predicates = try branch.predicates.toOwnedSlice(self.alloc);
        branch.predicates = .empty;
        group.array_any = try branch.array_any.toOwnedSlice(self.alloc);
        branch.array_any = .empty;
        group.array_contains = try branch.array_contains.toOwnedSlice(self.alloc);
        branch.array_contains = .empty;
        group.array_eq = try branch.array_eq.toOwnedSlice(self.alloc);
        branch.array_eq = .empty;
        group.in_predicates = try branch.in_predicates.toOwnedSlice(self.alloc);
        branch.in_predicates = .empty;
        group.json_contains = try branch.json_contains.toOwnedSlice(self.alloc);
        branch.json_contains = .empty;
        group.json_path_eq = try branch.json_path_eq.toOwnedSlice(self.alloc);
        branch.json_path_eq = .empty;
        group.json_path_exists = try branch.json_path_exists.toOwnedSlice(self.alloc);
        branch.json_path_exists = .empty;
        group.text_patterns = try branch.text_patterns.toOwnedSlice(self.alloc);
        branch.text_patterns = .empty;
        return group;
    }

    fn freeAccessPredicateBranches(
        self: *@This(),
        branches: *std.ArrayListUnmanaged(AccessPredicateBranch),
    ) void {
        for (branches.items) |*branch| self.freeAccessPredicateBranch(branch);
        branches.deinit(self.alloc);
    }

    fn freeAccessPredicateBranch(self: *@This(), branch: *AccessPredicateBranch) void {
        freeRelationalChecks(self.alloc, branch.predicates.items);
        branch.predicates.deinit(self.alloc);
        freeArrayAny(self.alloc, branch.array_any.items);
        branch.array_any.deinit(self.alloc);
        freeArrayContains(self.alloc, branch.array_contains.items);
        branch.array_contains.deinit(self.alloc);
        freeArrayEq(self.alloc, branch.array_eq.items);
        branch.array_eq.deinit(self.alloc);
        freeInPredicates(self.alloc, branch.in_predicates.items);
        branch.in_predicates.deinit(self.alloc);
        freeJsonContains(self.alloc, branch.json_contains.items);
        branch.json_contains.deinit(self.alloc);
        freeJsonPathEq(self.alloc, branch.json_path_eq.items);
        branch.json_path_eq.deinit(self.alloc);
        freeJsonPathExists(self.alloc, branch.json_path_exists.items);
        branch.json_path_exists.deinit(self.alloc);
        freeTextPatterns(self.alloc, branch.text_patterns.items);
        branch.text_patterns.deinit(self.alloc);
    }

    fn parenthesizedExpressionOrWhereCanStart(self: *@This()) bool {
        if (!self.peekKind(.lparen)) return false;
        const inner = self.predicateStartIndexAfterOpenParens(self.pos);
        if (!self.expressionCanStartAt(inner) and !self.jsonExtractExpressionPredicateCanStartAt(inner)) return false;

        var depth: usize = 0;
        var i = self.pos;
        while (i < self.tokens.len) : (i += 1) {
            const token = self.tokens[i];
            switch (token.kind) {
                .lparen => depth += 1,
                .rparen => {
                    if (depth == 0) return false;
                    depth -= 1;
                    if (depth == 0) return false;
                },
                .identifier => if (depth == 1 and std.ascii.eqlIgnoreCase(token.text, "or")) return true,
                .semicolon => return false,
                else => {},
            }
        }
        return false;
    }

    fn predicateStartIndexAfterOpenParens(self: *@This(), index: usize) usize {
        var out = index;
        while (out < self.tokens.len and self.tokens[out].kind == .lparen) : (out += 1) {}
        return out;
    }

    fn jsonExtractExpressionCanStartAt(self: *@This(), index: usize) bool {
        if (index + 2 >= self.tokens.len) return false;
        if (self.tokens[index].kind != .identifier) return false;
        if (!tokenKindIsJsonExtractOperator(self.tokens[index + 1].kind)) return false;
        return self.tokens[index + 2].kind == .string or self.tokens[index + 2].kind == .placeholder;
    }

    fn jsonExtractExpressionPredicateCanStartAt(self: *@This(), index: usize) bool {
        if (index + 3 >= self.tokens.len) return false;
        if (!self.jsonExtractExpressionCanStartAt(index)) return false;
        return switch (self.tokens[index + 3].kind) {
            .eq, .neq => true,
            else => false,
        };
    }

    fn jsonExtractNullSafeDistinctPredicateCanStartAt(self: *@This(), index: usize) bool {
        if (index + 5 >= self.tokens.len) return false;
        if (!self.jsonExtractExpressionCanStartAt(index)) return false;
        if (self.tokens[index + 3].kind != .identifier or
            !std.ascii.eqlIgnoreCase(self.tokens[index + 3].text, "is"))
        {
            return false;
        }
        var distinct_index = index + 4;
        if (self.tokens[distinct_index].kind == .identifier and
            std.ascii.eqlIgnoreCase(self.tokens[distinct_index].text, "not"))
        {
            distinct_index += 1;
        }
        return distinct_index + 1 < self.tokens.len and
            self.tokens[distinct_index].kind == .identifier and
            std.ascii.eqlIgnoreCase(self.tokens[distinct_index].text, "distinct") and
            self.tokens[distinct_index + 1].kind == .identifier and
            std.ascii.eqlIgnoreCase(self.tokens[distinct_index + 1].text, "from");
    }

    fn jsonExtractNullTestPredicateCanStartAt(self: *@This(), index: usize) bool {
        if (index + 4 >= self.tokens.len) return false;
        if (!self.jsonExtractExpressionCanStartAt(index)) return false;
        if (self.tokens[index + 3].kind != .identifier or
            !std.ascii.eqlIgnoreCase(self.tokens[index + 3].text, "is"))
        {
            return false;
        }
        var null_index = index + 4;
        if (self.tokens[null_index].kind == .identifier and
            std.ascii.eqlIgnoreCase(self.tokens[null_index].text, "not"))
        {
            null_index += 1;
        }
        return null_index < self.tokens.len and
            self.tokens[null_index].kind == .identifier and
            std.ascii.eqlIgnoreCase(self.tokens[null_index].text, "null");
    }

    fn expressionNullSafeDistinctPredicateCanStartAt(self: *@This(), index: usize) bool {
        if (!self.expressionCanStartAt(index)) return false;
        var depth: usize = 0;
        var i = index;
        while (i < self.tokens.len) : (i += 1) {
            const token = self.tokens[i];
            switch (token.kind) {
                .lparen => depth += 1,
                .rparen => {
                    if (depth == 0) return false;
                    depth -= 1;
                },
                .identifier => if (depth == 0 and std.ascii.eqlIgnoreCase(token.text, "is")) {
                    var distinct_index = i + 1;
                    if (distinct_index < self.tokens.len and
                        self.tokens[distinct_index].kind == .identifier and
                        std.ascii.eqlIgnoreCase(self.tokens[distinct_index].text, "not"))
                    {
                        distinct_index += 1;
                    }
                    return distinct_index + 1 < self.tokens.len and
                        self.tokens[distinct_index].kind == .identifier and
                        std.ascii.eqlIgnoreCase(self.tokens[distinct_index].text, "distinct") and
                        self.tokens[distinct_index + 1].kind == .identifier and
                        std.ascii.eqlIgnoreCase(self.tokens[distinct_index + 1].text, "from");
                } else if (depth == 0 and rowExpressionBoundaryKeyword(token.text)) {
                    return false;
                },
                .semicolon, .comma => if (depth == 0) return false,
                else => {},
            }
        }
        return false;
    }

    fn jsonExtractMembershipPredicateCanStartAt(self: *@This(), index: usize) bool {
        if (index + 3 >= self.tokens.len) return false;
        if (self.tokens[index].kind != .identifier) return false;
        if (!tokenKindIsJsonExtractOperator(self.tokens[index + 1].kind)) return false;
        if (self.tokens[index + 2].kind != .string and self.tokens[index + 2].kind != .placeholder) return false;
        const op = self.tokens[index + 3];
        if (op.kind == .identifier and std.ascii.eqlIgnoreCase(op.text, "in")) return true;
        if (op.kind == .identifier and std.ascii.eqlIgnoreCase(op.text, "not")) {
            return index + 4 < self.tokens.len and
                self.tokens[index + 4].kind == .identifier and
                std.ascii.eqlIgnoreCase(self.tokens[index + 4].text, "in");
        }
        if (op.kind == .eq) {
            return index + 4 < self.tokens.len and
                self.tokens[index + 4].kind == .identifier and
                (sqlKeywordIsAnyOrSome(self.tokens[index + 4].text) or
                    std.ascii.eqlIgnoreCase(self.tokens[index + 4].text, "all"));
        }
        if (op.kind == .neq) {
            return index + 4 < self.tokens.len and
                self.tokens[index + 4].kind == .identifier and
                (sqlKeywordIsAnyOrSome(self.tokens[index + 4].text) or
                    std.ascii.eqlIgnoreCase(self.tokens[index + 4].text, "all"));
        }
        return false;
    }

    fn jsonKeySetExpressionCanStartAt(self: *@This(), index: usize) bool {
        return index + 1 < self.tokens.len and
            self.tokens[index].kind == .identifier and
            (self.tokens[index + 1].kind == .question_any or self.tokens[index + 1].kind == .question_all);
    }

    fn textPatternSetPredicateCanStartAt(self: *@This(), index: usize) bool {
        if (index >= self.tokens.len) return false;
        if (self.tokens[index].kind != .identifier and !self.expressionCanStartAt(index)) return false;
        var depth: usize = 0;
        var i = index;
        while (i < self.tokens.len) : (i += 1) {
            const token = self.tokens[i];
            switch (token.kind) {
                .lparen => depth += 1,
                .rparen => {
                    if (depth == 0) return false;
                    depth -= 1;
                },
                .semicolon, .comma => if (depth == 0) return false,
                .identifier => if (depth == 0) {
                    if (std.ascii.eqlIgnoreCase(token.text, "like") or
                        std.ascii.eqlIgnoreCase(token.text, "ilike"))
                    {
                        return self.tokenAtIsAnySomeOrAll(i + 1);
                    }
                    if (std.ascii.eqlIgnoreCase(token.text, "not") and i + 2 < self.tokens.len and
                        self.tokens[i + 1].kind == .identifier and
                        (std.ascii.eqlIgnoreCase(self.tokens[i + 1].text, "like") or
                            std.ascii.eqlIgnoreCase(self.tokens[i + 1].text, "ilike")))
                    {
                        return self.tokenAtIsAnySomeOrAll(i + 2);
                    }
                    if (rowExpressionBoundaryKeyword(token.text)) return false;
                },
                else => {},
            }
        }
        return false;
    }

    fn canParseExpressionNotWhere(self: *@This()) bool {
        if (!self.peekKeyword("not") or self.pos + 2 >= self.tokens.len or self.tokens[self.pos + 1].kind != .lparen) return false;
        const inner = self.predicateStartIndexAfterOpenParens(self.pos + 1);
        return self.expressionCanStartAt(inner) or
            self.jsonKeySetExpressionCanStartAt(inner) or
            self.jsonExtractExpressionPredicateCanStartAt(inner) or
            self.jsonExtractNullTestPredicateCanStartAt(inner);
    }

    fn expressionPredicateCanStartAt(self: *@This(), index: usize) bool {
        if (self.expressionCanStartAt(index) or
            self.textPatternSetPredicateCanStartAt(index) or
            self.jsonKeySetExpressionCanStartAt(index) or
            self.jsonExtractExpressionPredicateCanStartAt(index) or
            self.jsonExtractNullTestPredicateCanStartAt(index) or
            self.jsonExtractNullSafeDistinctPredicateCanStartAt(index) or
            self.jsonExtractMembershipPredicateCanStartAt(index))
        {
            return true;
        }
        if (index + 1 >= self.tokens.len or self.tokens[index].kind != .identifier) return false;
        const next = self.tokens[index + 1];
        return switch (next.kind) {
            .eq, .neq, .gt, .gte, .lt, .lte => true,
            .identifier => std.ascii.eqlIgnoreCase(next.text, "is") or
                std.ascii.eqlIgnoreCase(next.text, "in") or
                std.ascii.eqlIgnoreCase(next.text, "not") or
                std.ascii.eqlIgnoreCase(next.text, "between") or
                std.ascii.eqlIgnoreCase(next.text, "like") or
                std.ascii.eqlIgnoreCase(next.text, "ilike"),
            else => false,
        };
    }

    fn expressionCanStartAt(self: *@This(), index: usize) bool {
        if (index >= self.tokens.len) return false;
        const token = self.tokens[index];
        if (token.kind == .minus) return true;
        if (token.kind == .number or token.kind == .string or token.kind == .placeholder) return true;
        if (token.kind != .identifier) return false;
        if (self.arrayLengthFunctionStartsAt(index) or
            self.arrayPositionFunctionStartsAt(index) or
            std.ascii.eqlIgnoreCase(token.text, "case") or
            std.ascii.eqlIgnoreCase(token.text, "cast") or
            std.ascii.eqlIgnoreCase(token.text, "coalesce") or
            std.ascii.eqlIgnoreCase(token.text, "concat") or
            std.ascii.eqlIgnoreCase(token.text, "concat_ws") or
            std.ascii.eqlIgnoreCase(token.text, "convert_from") or
            std.ascii.eqlIgnoreCase(token.text, "current_date") or
            std.ascii.eqlIgnoreCase(token.text, "current_timestamp") or
            self.functionCallStartsAt(index, "gen_random_uuid") or
            self.functionCallStartsAt(index, "uuid_generate_v4") or
            std.ascii.eqlIgnoreCase(token.text, "false") or
            std.ascii.eqlIgnoreCase(token.text, "abs") or
            std.ascii.eqlIgnoreCase(token.text, "ascii") or
            self.functionCallStartsAt(index, "floor") or
            self.functionCallStartsAt(index, "ceil") or
            self.functionCallStartsAt(index, "sqrt") or
            self.functionCallStartsAt(index, "sign") or
            self.functionCallStartsAt(index, "mod") or
            self.functionCallStartsAt(index, "power") or
            std.ascii.eqlIgnoreCase(token.text, "chr") or
            std.ascii.eqlIgnoreCase(token.text, "length") or
            std.ascii.eqlIgnoreCase(token.text, "lower") or
            std.ascii.eqlIgnoreCase(token.text, "now") or
            std.ascii.eqlIgnoreCase(token.text, "null") or
            std.ascii.eqlIgnoreCase(token.text, "nullif") or
            std.ascii.eqlIgnoreCase(token.text, "octet_length") or
            sqlKeywordIsOverlayFunction(token.text) or
            std.ascii.eqlIgnoreCase(token.text, "round") or
            self.functionCallStartsAt(index, "trunc") or
            std.ascii.eqlIgnoreCase(token.text, "array_append") or
            std.ascii.eqlIgnoreCase(token.text, "array_prepend") or
            std.ascii.eqlIgnoreCase(token.text, "array_cat") or
            std.ascii.eqlIgnoreCase(token.text, "array_remove") or
            std.ascii.eqlIgnoreCase(token.text, "array_replace") or
            std.ascii.eqlIgnoreCase(token.text, "array_to_string") or
            std.ascii.eqlIgnoreCase(token.text, "string_to_array") or
            std.ascii.eqlIgnoreCase(token.text, "trim") or
            sqlKeywordIsTrimVariantFunction(token.text) or
            sqlKeywordIsPadFunction(token.text) or
            sqlKeywordIsRepeatFunction(token.text) or
            sqlKeywordIsReverseFunction(token.text) or
            sqlKeywordIsInitcapFunction(token.text) or
            sqlKeywordIsMd5Function(token.text) or
            sqlKeywordIsStartsWithFunction(token.text) or
            sqlKeywordIsEndsWithFunction(token.text) or
            sqlKeywordIsDateTruncFunction(token.text) or
            sqlKeywordIsDateBinFunction(token.text) or
            sqlKeywordIsDatePartFunction(token.text) or
            (sqlKeywordIsJsonExtractPathFunction(token.text) and index + 1 < self.tokens.len and self.tokens[index + 1].kind == .lparen) or
            (sqlKeywordIsJsonTypeofFunction(token.text) and index + 1 < self.tokens.len and self.tokens[index + 1].kind == .lparen) or
            (sqlKeywordIsJsonArrayLengthFunction(token.text) and index + 1 < self.tokens.len and self.tokens[index + 1].kind == .lparen) or
            (sqlKeywordIsJsonBuildObjectFunction(token.text) and index + 1 < self.tokens.len and self.tokens[index + 1].kind == .lparen) or
            (std.ascii.eqlIgnoreCase(token.text, "to_jsonb") and index + 1 < self.tokens.len and self.tokens[index + 1].kind == .lparen) or
            sqlKeywordIsRegexpMatchFunction(token.text) or
            sqlKeywordIsRegexpCountFunction(token.text) or
            sqlKeywordIsRegexpSubstrFunction(token.text) or
            sqlKeywordIsRegexpInstrFunction(token.text) or
            std.ascii.eqlIgnoreCase(token.text, "replace") or
            sqlKeywordIsTranslateFunction(token.text) or
            std.ascii.eqlIgnoreCase(token.text, "true") or
            std.ascii.eqlIgnoreCase(token.text, "upper"))
        {
            return true;
        }
        if (self.jsonExtractMembershipPredicateCanStartAt(index) or
            self.jsonExtractNullSafeDistinctPredicateCanStartAt(index) or
            self.jsonExtractNullTestPredicateCanStartAt(index))
        {
            return true;
        }
        return index + 1 < self.tokens.len and switch (self.tokens[index + 1].kind) {
            .plus, .minus, .star, .slash, .percent => true,
            else => false,
        };
    }

    fn parenthesizedBooleanIsPredicateCanStartAt(self: *@This(), index: usize) bool {
        if (index >= self.tokens.len or self.tokens[index].kind != .lparen) return false;
        const inner = self.predicateStartIndexAfterOpenParens(index);
        if (!self.booleanExpressionCanStartAt(inner)) return false;
        const close = findMatchingRParenIndex(self.tokens, index) orelse return false;
        if (close + 2 >= self.tokens.len) return false;
        if (self.tokens[close + 1].kind != .identifier or
            !std.ascii.eqlIgnoreCase(self.tokens[close + 1].text, "is"))
        {
            return false;
        }
        var value_index = close + 2;
        if (self.tokens[value_index].kind == .identifier and
            std.ascii.eqlIgnoreCase(self.tokens[value_index].text, "not"))
        {
            value_index += 1;
        }
        if (value_index >= self.tokens.len or self.tokens[value_index].kind != .identifier) return false;
        return std.ascii.eqlIgnoreCase(self.tokens[value_index].text, "true") or
            std.ascii.eqlIgnoreCase(self.tokens[value_index].text, "false") or
            std.ascii.eqlIgnoreCase(self.tokens[value_index].text, "unknown");
    }

    fn parseExpressionNotWhere(
        self: *@This(),
        expression_not_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
    ) !void {
        try self.expectKeyword("not");
        try self.expect(.lparen);
        while (true) {
            var groups = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
            var groups_transferred = false;
            defer groups.deinit(self.alloc);
            errdefer {
                if (!groups_transferred) freeExpressionPredicateGroups(self.alloc, groups.items);
            }
            try groups.append(self.alloc, .{ .conditions = &.{} });

            while (true) {
                var alternatives = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
                defer alternatives.deinit(self.alloc);
                errdefer freeExpressionPredicateGroups(self.alloc, alternatives.items);
                try self.parseExpressionWhereConditionAlternatives(&alternatives);
                try self.andExpressionPredicateAlternatives(&groups, alternatives.items);
                freeExpressionPredicateGroups(self.alloc, alternatives.items);
                if (!self.matchKeyword("and")) break;
            }
