            var upper_transferred = false;
            errdefer if (!upper_transferred) freeExpression(self.alloc, upper_expression);

            if (symmetric) {
                freeExpression(self.alloc, upper_lhs);
                upper_lhs_transferred = true;
                try self.appendExpressionBetweenSymmetricGroups(expression_or_predicates, lhs, lower_expression, upper_expression, false);
                freeExpression(self.alloc, lhs);
                freeExpression(self.alloc, lower_expression);
                freeExpression(self.alloc, upper_expression);
                lhs_transferred = true;
                lower_transferred = true;
                upper_transferred = true;
                return;
            }

            const lower_rhs = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
            var lower_rhs_transferred = false;
            errdefer if (!lower_rhs_transferred) self.alloc.free(lower_rhs);
            lower_rhs[0] = lower_expression;

            const upper_rhs = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
            var upper_rhs_transferred = false;
            errdefer if (!upper_rhs_transferred) self.alloc.free(upper_rhs);
            upper_rhs[0] = upper_expression;

            try expression_predicates.append(self.alloc, .{
                .lhs = lhs,
                .op = .gte,
                .rhs = lower_rhs,
            });
            lhs_transferred = true;
            lower_transferred = true;
            lower_rhs_transferred = true;

            try expression_predicates.append(self.alloc, .{
                .lhs = upper_lhs,
                .op = .lte,
                .rhs = upper_rhs,
            });
            upper_lhs_transferred = true;
            upper_transferred = true;
            upper_rhs_transferred = true;
            return;
        }

        const op: runtime_schema.RelationalCheckOp = if (self.matchKeyword("is")) blk: {
            const not = self.matchKeyword("not");
            if (self.matchKeyword("distinct")) {
                try self.expectKeyword("from");
                break :blk if (not) .is_not_distinct else .is_distinct;
            }
            if (self.matchKeyword("unknown")) {
                try self.validateBooleanRowExpression(lhs);
                try expression_predicates.append(self.alloc, expressionNullTestCondition(lhs, if (not) .is_not_null else .is_null));
                lhs_transferred = true;
                return;
            }
            if (self.matchKeyword("true") or self.matchKeyword("false")) {
                const value = std.ascii.eqlIgnoreCase(self.tokens[self.pos - 1].text, "true");
                try self.validateBooleanRowExpression(lhs);
                if (not) {
                    try self.appendExpressionBooleanIsNotGroups(expression_or_predicates, lhs, value);
                    freeExpression(self.alloc, lhs);
                    lhs_transferred = true;
                    return;
                }
                const condition = try self.expressionBooleanComparisonConditionAlloc(lhs, .eq, value);
                var condition_transferred = false;
                errdefer if (!condition_transferred) freeExpressionCondition(self.alloc, condition);
                try expression_predicates.append(self.alloc, condition);
                condition_transferred = true;
                lhs_transferred = true;
                return;
            }
            try self.expectKeyword("null");
            break :blk if (not) .is_not_null else .is_null;
        } else if (self.matchPostfixNullTest()) |postfix_null_test|
            postfix_null_test
        else
            try self.parseComparisonOp();

        if (op == .eq and self.matchAnyOrSomeKeyword()) {
            try self.expect(.lparen);
            const values_json = try self.parseJsonArrayValueAlloc();
            defer self.alloc.free(values_json);
            try self.expect(.rparen);
            try self.appendExpressionValuesJsonOrGroups(expression_or_predicates, lhs, values_json);
            freeExpression(self.alloc, lhs);
            lhs_transferred = true;
            return;
        }
        if (op == .ne and self.matchAnyOrSomeKeyword()) {
            try self.expect(.lparen);
            const values_json = try self.parseJsonArrayValueAlloc();
            defer self.alloc.free(values_json);
            try self.expect(.rparen);
            try self.appendExpressionValuesJsonComparisonGroups(expression_or_predicates, lhs, values_json, .ne);
            freeExpression(self.alloc, lhs);
            lhs_transferred = true;
            return;
        }
        if (op == .eq and self.matchKeyword("all")) {
            try self.expect(.lparen);
            const values_json = try self.parseJsonArrayValueAlloc();
            defer self.alloc.free(values_json);
            try self.expect(.rparen);
            try self.appendExpressionValuesJsonConjunction(expression_predicates, lhs, values_json);
            freeExpression(self.alloc, lhs);
            lhs_transferred = true;
            return;
        }
        if (op == .ne and self.matchKeyword("all")) {
            try self.expect(.lparen);
            const values_json = try self.parseJsonArrayValueAlloc();
            defer self.alloc.free(values_json);
            try self.expect(.rparen);
            try self.appendExpressionValuesJsonOrGroups(expression_not_predicates, lhs, values_json);
            freeExpression(self.alloc, lhs);
            lhs_transferred = true;
            return;
        }

        const rhs = switch (op) {
            .is_null, .is_not_null => &.{},
            else => blk: {
                const out = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
                var out_transferred = false;
                errdefer if (!out_transferred) self.alloc.free(out);
                out[0] = try self.parseRowExpressionAlloc();
                out_transferred = true;
                break :blk out;
            },
        };
        var rhs_transferred = false;
        errdefer if (!rhs_transferred and rhs.len > 0) {
            for (rhs) |expression| freeExpression(self.alloc, expression);
            self.alloc.free(rhs);
        };
        try self.validateExpressionConditionTypes(lhs, op, rhs);

        try expression_predicates.append(self.alloc, .{
            .lhs = lhs,
            .op = op,
            .rhs = rhs,
        });
        lhs_transferred = true;
        rhs_transferred = true;
    }

    fn expressionLikeConditionAlloc(
        self: *@This(),
        expression: db_mod.types.RelationalRowsExpression,
        case_insensitive: bool,
        negated: bool,
    ) !db_mod.types.RelationalRowsExpressionCondition {
        try self.validateTextRowExpression(expression);
        const raw_pattern = try self.parseSqlStringValueAlloc();
        defer self.alloc.free(raw_pattern);
        const normalized_pattern = if (self.matchKeyword("escape")) blk: {
            const escape = try self.parseSqlStringValueAlloc();
            defer self.alloc.free(escape);
            break :blk try normalizeSqlLikePatternEscapeAlloc(self.alloc, raw_pattern, escape);
        } else try self.alloc.dupe(u8, raw_pattern);
        defer self.alloc.free(normalized_pattern);

        const source_expression = try cloneExpressionAlloc(self.alloc, expression);
        var source_expression_transferred = false;
        errdefer if (!source_expression_transferred) freeExpression(self.alloc, source_expression);

        const rhs_json = try self.alloc.dupe(u8, booleanJson(!negated));
        var rhs_json_transferred = false;
        errdefer if (!rhs_json_transferred) self.alloc.free(rhs_json);
        const rhs = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
        var rhs_transferred = false;
        errdefer if (!rhs_transferred) {
            if (rhs_json_transferred) freeExpression(self.alloc, rhs[0]);
            self.alloc.free(rhs);
        };
        rhs[0] = .{
            .kind = .value,
            .value_json = rhs_json,
        };
        rhs_json_transferred = true;

        const pattern_json = try std.json.Stringify.valueAlloc(self.alloc, std.json.Value{ .string = normalized_pattern }, .{});
        var pattern_json_transferred = false;
        errdefer if (!pattern_json_transferred) self.alloc.free(pattern_json);
        const like_operands = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 2);
        var like_operands_transferred = false;
        errdefer if (!like_operands_transferred) self.alloc.free(like_operands);
        like_operands[0] = source_expression;
        like_operands[1] = .{
            .kind = .value,
            .value_json = pattern_json,
        };
        source_expression_transferred = true;
        pattern_json_transferred = true;
        rhs_transferred = true;
        like_operands_transferred = true;

        return .{
            .lhs = .{
                .kind = if (case_insensitive) .ilike else .like,
                .operands = like_operands,
            },
            .op = .eq,
            .rhs = rhs,
        };
    }

    const RegexPredicateOperator = struct {
        case_insensitive: bool,
        negated: bool,
    };

    fn matchRegexPredicateOperator(self: *@This()) ?RegexPredicateOperator {
        if (self.match(.regex_match) != null) return .{ .case_insensitive = false, .negated = false };
        if (self.match(.regex_imatch) != null) return .{ .case_insensitive = true, .negated = false };
        if (self.match(.regex_not_match) != null) return .{ .case_insensitive = false, .negated = true };
        if (self.match(.regex_not_imatch) != null) return .{ .case_insensitive = true, .negated = true };
        return null;
    }

    fn expressionRegexpMatchConditionAlloc(
        self: *@This(),
        expression: db_mod.types.RelationalRowsExpression,
