    fn expressionLikeSetExpressionAlloc(
        self: *@This(),
        expression: db_mod.types.RelationalRowsExpression,
        values_json: []const u8,
        case_insensitive: bool,
        negated: bool,
        quantifier: SqlPatternQuantifier,
    ) !db_mod.types.RelationalRowsExpression {
        var parsed = std.json.parseFromSlice(std.json.Value, self.alloc, values_json, .{}) catch return error.UnsupportedSqlShape;
        defer parsed.deinit();
        if (parsed.value != .array or parsed.value.array.items.len == 0 or parsed.value.array.items.len > max_scalar_or_expanded_branches) return error.UnsupportedSqlShape;

        var operands = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpression).empty;
        var operands_transferred = false;
        errdefer {
            if (!operands_transferred) {
                for (operands.items) |operand| freeExpression(self.alloc, operand);
                operands.deinit(self.alloc);
            }
        }

        for (parsed.value.array.items) |value| {
            if (value != .string) return error.UnsupportedSqlShape;
            var operand = try self.expressionLikePatternExpressionAlloc(expression, value.string, case_insensitive);
            var operand_transferred = false;
            errdefer if (!operand_transferred) freeExpression(self.alloc, operand);
            if (negated) {
                operand = try self.wrapBooleanNotExpressionAlloc(operand);
            }
            try operands.append(self.alloc, operand);
            operand_transferred = true;
        }

        if (operands.items.len == 1) {
            const out = operands.items[0];
            operands.clearRetainingCapacity();
            operands.deinit(self.alloc);
            operands_transferred = true;
            return out;
        }

        const owned_operands = try operands.toOwnedSlice(self.alloc);
        operands = .empty;
        operands_transferred = true;
        return .{
            .kind = if (quantifier == .all) .bool_and else .bool_or,
            .operands = owned_operands,
        };
    }

    fn expressionLikePatternExpressionAlloc(
