        const pattern_json = try std.json.Stringify.valueAlloc(self.alloc, std.json.Value{ .string = pattern }, .{});
        var pattern_json_transferred = false;
        errdefer if (!pattern_json_transferred) self.alloc.free(pattern_json);
        const operands = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 2);
        var operands_transferred = false;
        errdefer if (!operands_transferred) self.alloc.free(operands);
        operands[0] = source_expression;
        operands[1] = .{
            .kind = .value,
            .value_json = pattern_json,
        };
        source_expression_transferred = true;
        pattern_json_transferred = true;
        operands_transferred = true;
        return .{
            .kind = if (case_insensitive) .ilike else .like,
