    fn appendJsonContainsClone(
        self: *@This(),
        branch: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonContainsPredicate),
        predicate: db_mod.types.RelationalRowsJsonContainsPredicate,
    ) !void {
        const field = try self.alloc.dupe(u8, predicate.field);
        var field_transferred = false;
        errdefer if (!field_transferred) self.alloc.free(field);
        const value_json = try self.alloc.dupe(u8, predicate.value_json);
        var value_transferred = false;
        errdefer if (!value_transferred) self.alloc.free(value_json);
        try branch.append(self.alloc, .{ .field = field, .value_json = value_json });
        field_transferred = true;
        value_transferred = true;
    }

    fn appendJsonPathEqClone(
        self: *@This(),
        branch: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonPathEqPredicate),
        predicate: db_mod.types.RelationalRowsJsonPathEqPredicate,
    ) !void {
        const field = try self.alloc.dupe(u8, predicate.field);
        var field_transferred = false;
        errdefer if (!field_transferred) self.alloc.free(field);
        const path = try self.alloc.dupe(u8, predicate.path);
        var path_transferred = false;
        errdefer if (!path_transferred) self.alloc.free(path);
        const value_json = try self.alloc.dupe(u8, predicate.value_json);
        var value_transferred = false;
