        try self.expectKeyword("and");
        const upper_json = try self.parseSqlColumnValueAlloc(column);
        var upper_transferred = false;
        defer if (!upper_transferred) self.alloc.free(upper_json);

        if (symmetric) {
            if (!negated) {
                try self.appendBetweenScalarGroup(or_predicates, field, .gte, lower_json, .lte, upper_json);
                try self.appendBetweenScalarGroup(or_predicates, field, .gte, upper_json, .lte, lower_json);
            } else {
                try self.appendBetweenScalarGroup(or_predicates, field, .lt, lower_json, .lt, upper_json);
                try self.appendBetweenScalarGroup(or_predicates, field, .gt, lower_json, .gt, upper_json);
            }
