        period: runtime_schema.RelationalPeriod,
        range: PeriodRangeValuePair,
    ) !void {
        if (!std.mem.eql(u8, range.start_json, "null") and
            !std.mem.eql(u8, range.end_json, "null") and
            std.mem.eql(u8, range.start_json, range.end_json))
