            var start_transferred = false;
            errdefer if (!start_transferred) freePredicateGroup(self.alloc, start_group);
            try or_predicates.append(self.alloc, start_group);
            start_transferred = true;
        }

        if (!std.mem.eql(u8, range.start_json, "null")) {
            const end_group = try self.temporalRangeBoundPredicateGroupAlloc(period.end_column, .gt, range.start_json);
            var end_transferred = false;
            errdefer if (!end_transferred) freePredicateGroup(self.alloc, end_group);
