    fn temporalRangeBoundPredicateGroupAlloc(
        self: *@This(),
        field: []const u8,
        op: runtime_schema.RelationalCheckOp,
        point_json: []const u8,
    ) !db_mod.types.RelationalRowsPredicateGroup {
        const predicates = try self.alloc.alloc(runtime_schema.RelationalCheck, 2);
        var initialized: usize = 0;
        errdefer {
            for (predicates[0..initialized]) |predicate| {
                self.alloc.free(predicate.field);
                if (predicate.value_json) |value| self.alloc.free(value);
            }
            self.alloc.free(predicates);
        }

        const predicate_field = try self.alloc.dupe(u8, field);
        var predicate_field_transferred = false;
        errdefer if (!predicate_field_transferred) self.alloc.free(predicate_field);

        const predicate_value = try self.alloc.dupe(u8, point_json);
        var predicate_value_transferred = false;
        errdefer if (!predicate_value_transferred) self.alloc.free(predicate_value);

        predicates[0] = .{
            .name = "",
            .field = predicate_field,
            .op = op,
            .value_json = predicate_value,
        };
        predicate_field_transferred = true;
        predicate_value_transferred = true;
        initialized = 1;

        const null_predicate_field = try self.alloc.dupe(u8, field);
        var null_predicate_field_transferred = false;
        errdefer if (!null_predicate_field_transferred) self.alloc.free(null_predicate_field);

        predicates[1] = .{
            .name = "",
            .field = null_predicate_field,
            .op = .is_null,
            .value_json = null,
        };
        null_predicate_field_transferred = true;
        initialized = 2;
        return .{ .predicates = predicates };
    }

