    fn appendTextPatternPredicate(
        self: *@This(),
        text_patterns: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsTextPatternPredicate),
        field: []const u8,
        column: runtime_schema.RelationalColumn,
        case_insensitive: bool,
        negated: bool,
    ) !void {
        if (column.field_type != .keyword and column.field_type != .text and column.field_type != .link) return error.InvalidSqlCatalog;
        const pattern_json = try self.parseSqlColumnValueAlloc(column);
        defer self.alloc.free(pattern_json);
        const parsed_pattern = try jsonStringLiteralValueAlloc(self.alloc, pattern_json);
        defer self.alloc.free(parsed_pattern);
        const pattern = if (self.matchKeyword("escape")) blk: {
            const escape = try self.parseSqlStringValueAlloc();
            defer self.alloc.free(escape);
            break :blk try normalizeSqlLikePatternEscapeAlloc(self.alloc, parsed_pattern, escape);
        } else try self.alloc.dupe(u8, parsed_pattern);
        var pattern_transferred = false;
        errdefer if (!pattern_transferred) self.alloc.free(pattern);
        const predicate_field = try self.alloc.dupe(u8, field);
        var field_transferred = false;
        errdefer if (!field_transferred) self.alloc.free(predicate_field);
        try text_patterns.append(self.alloc, .{
            .field = predicate_field,
            .pattern = pattern,
            .case_insensitive = case_insensitive,
            .negated = negated,
        });
        field_transferred = true;
        pattern_transferred = true;
    }

    fn parseSqlStringValueAlloc(self: *@This()) ![]const u8 {
        if (self.match(.placeholder)) |token| {
            const value = try self.boundValue(token);
            return switch (value) {
                .string => |text| try self.alloc.dupe(u8, text),
                else => error.UnsupportedSqlShape,
            };
        }
        if (self.match(.string)) |token| return try self.alloc.dupe(u8, token.text);
        return error.UnsupportedSqlShape;
    }

    fn normalizeSqlLikePatternEscapeAlloc(alloc: std.mem.Allocator, pattern: []const u8, escape: []const u8) ![]const u8 {
        if (escape.len != 1) return error.UnsupportedSqlShape;
        const escape_char = escape[0];
        if (escape_char == '\\') return try alloc.dupe(u8, pattern);

        var out = std.ArrayListUnmanaged(u8).empty;
        errdefer out.deinit(alloc);
        var index: usize = 0;
        while (index < pattern.len) {
            const byte = pattern[index];
            if (byte == escape_char) {
                if (index + 1 >= pattern.len) return error.UnsupportedSqlShape;
                try out.append(alloc, '\\');
                try out.append(alloc, pattern[index + 1]);
                index += 2;
                continue;
            }
            if (byte == '\\') {
                try out.append(alloc, '\\');
                try out.append(alloc, '\\');
                index += 1;
                continue;
            }
            try out.append(alloc, byte);
            index += 1;
        }
        return try out.toOwnedSlice(alloc);
    }

    fn sqlLikePrefixLiteralAlloc(alloc: std.mem.Allocator, pattern: []const u8) !?[]const u8 {
        var out = std.ArrayListUnmanaged(u8).empty;
        errdefer out.deinit(alloc);
        var index: usize = 0;
        while (index < pattern.len) {
            const byte = pattern[index];
            if (byte == '\\') {
                if (index + 1 >= pattern.len) return error.UnsupportedSqlShape;
                try out.append(alloc, pattern[index + 1]);
                index += 2;
                continue;
            }
            if (byte == '_') {
                out.deinit(alloc);
                return null;
            }
            if (byte == '%') {
                if (index + 1 != pattern.len) {
                    out.deinit(alloc);
                    return null;
                }
                return try out.toOwnedSlice(alloc);
            }
            try out.append(alloc, byte);
            index += 1;
        }
        out.deinit(alloc);
        return null;
    }

    fn jsonStringLiteralValueAlloc(alloc: std.mem.Allocator, value_json: []const u8) ![]const u8 {
        var parsed = std.json.parseFromSlice(std.json.Value, alloc, value_json, .{}) catch return error.UnsupportedSqlShape;
        defer parsed.deinit();
        if (parsed.value != .string) return error.UnsupportedSqlShape;
        return try alloc.dupe(u8, parsed.value.string);
    }

    fn parseOrderBy(self: *@This(), order_by: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsQueryOrder)) !void {
        while (true) {
            var order = try self.parseOrderExpressionAlloc();
            var order_transferred = false;
            errdefer if (!order_transferred) {
                if (order.field.len > 0) self.alloc.free(order.field);
                if (order.expression) |expression| freeExpression(self.alloc, expression);
            };
            const explicit_nulls_first = try self.applyOrderModifiers(&order);
            try self.appendOrderWithNullPlacement(order_by, order, explicit_nulls_first);
            order_transferred = true;
            if (self.match(.comma) == null) break;
        }
    }

    fn parseSelectOutputOrderBy(
        self: *@This(),
        order_by: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsQueryOrder),
        select: SelectList,
    ) !void {
        while (true) {
            var order = if (self.match(.number)) |token| blk: {
                const ordinal = std.fmt.parseInt(u32, token.text, 10) catch return error.UnsupportedSqlShape;
                break :blk try self.selectOutputOrderByOrdinalAlloc(select, ordinal);
            } else if (try self.selectOutputOrderByNameMaybeAlloc(select)) |named_order| blk: {
                break :blk named_order;
            } else try self.parseOrderExpressionAlloc();
            var order_transferred = false;
            errdefer if (!order_transferred) {
                if (order.field.len > 0) self.alloc.free(order.field);
                if (order.expression) |expression| freeExpression(self.alloc, expression);
            };
            const explicit_nulls_first = try self.applyOrderModifiers(&order);
            try self.appendOrderWithNullPlacement(order_by, order, explicit_nulls_first);
            order_transferred = true;
            if (self.match(.comma) == null) break;
        }
    }

    fn applyOrderModifiers(
        self: *@This(),
        order: *db_mod.types.RelationalRowsQueryOrder,
    ) !?bool {
        order.direction = if (self.matchKeyword("using"))
            try self.parseOrderUsingDirection()
        else if (self.matchKeyword("desc"))
            .desc
        else blk: {
            _ = self.matchKeyword("asc");
            break :blk .asc;
        };
        return if (self.matchKeyword("nulls")) blk: {
            if (self.matchKeyword("first")) break :blk true;
            try self.expectKeyword("last");
            break :blk false;
        } else null;
    }

    fn parseOrderUsingDirection(self: *@This()) !db_mod.types.RelationalRowsQueryOrderDirection {
        if (self.match(.lt) != null or self.match(.lte) != null) return .asc;
        if (self.match(.gt) != null or self.match(.gte) != null) return .desc;
        return error.UnsupportedSqlShape;
    }

    fn appendOrderWithNullPlacement(
        self: *@This(),
        order_by: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsQueryOrder),
        order: db_mod.types.RelationalRowsQueryOrder,
        explicit_nulls_first: ?bool,
    ) !void {
        if (explicit_nulls_first) |nulls_first| {
            if (order.null_test != null) return error.UnsupportedSqlShape;
            var null_order = try self.cloneOrderForNullTestAlloc(order);
            var null_order_transferred = false;
            errdefer if (!null_order_transferred) {
                if (null_order.field.len > 0) self.alloc.free(null_order.field);
                if (null_order.expression) |expression| freeExpression(self.alloc, expression);
            };
            null_order.direction = if (nulls_first) .desc else .asc;
            null_order.null_test = .is_null;
            try order_by.append(self.alloc, null_order);
            null_order_transferred = true;
        }
        try order_by.append(self.alloc, order);
    }

    fn selectOutputOrderByNameMaybeAlloc(
        self: *@This(),
        select: SelectList,
    ) !?db_mod.types.RelationalRowsQueryOrder {
        if (!self.peekKind(.identifier)) return null;
        if (self.pos + 1 < self.tokens.len) {
            switch (self.tokens[self.pos + 1].kind) {
                .lparen, .arrow_json, .arrow_text, .path_arrow_json, .path_arrow_text, .plus, .minus, .star, .slash, .percent, .pipe_concat => return null,
                else => {},
            }
        }

        const name = self.tokens[self.pos].text;
        const output = (try self.selectOutputByName(name, select)) orelse return null;
        self.pos += 1;
        return try self.selectOutputOrderByRefAlloc(select, output);
    }

    fn selectOutputByName(
        self: *@This(),
        name: []const u8,
        select: SelectList,
    ) !?SelectOutputRef {
        var found: ?SelectOutputRef = null;
        for (select.outputs) |output| {
            const output_name = self.selectOutputName(select, output) orelse continue;
            if (!std.ascii.eqlIgnoreCase(output_name, name)) continue;
            if (found != null) return error.UnsupportedSqlShape;
            found = output;
        }
        return found;
    }

    fn selectOutputName(
        self: *@This(),
        select: SelectList,
        output: SelectOutputRef,
    ) ?[]const u8 {
        _ = self;
        return switch (output.kind) {
            .field => if (output.index < select.fields.len) select.fields[output.index] else null,
            .json_extract => if (output.index < select.json_extract.len) select.json_extract[output.index].output else null,
            .array_length => if (output.index < select.array_length.len) select.array_length[output.index].output else null,
            .coalesce => if (output.index < select.coalesce.len) select.coalesce[output.index].output else null,
            .field_alias => if (output.index < select.field_aliases.len) select.field_aliases[output.index].output else null,
            .expression => if (output.index < select.expressions.len) select.expressions[output.index].output else null,
        };
    }

    fn selectOutputOrderByOrdinalAlloc(
        self: *@This(),
        select: SelectList,
        ordinal: u32,
    ) !db_mod.types.RelationalRowsQueryOrder {
        if (ordinal == 0) return error.UnsupportedSqlShape;
        var index: usize = @intCast(ordinal - 1);
        if (select.select_all) {
