        ordinal: u32,
    ) ![]const u8 {
        if (ordinal == 0) return error.UnsupportedSqlShape;
        const index: usize = @intCast(ordinal - 1);
        if (index >= select.outputs.len) return error.UnsupportedSqlShape;
        const output = select.outputs[index];
        return switch (output.kind) {
            .field => try self.alloc.dupe(u8, select.fields[output.index]),
            .window => try self.alloc.dupe(u8, select.windows[output.index].output),
        };
    }

    fn windowOutputColumnsAlloc(
        self: *@This(),
        select: WindowSelectList,
    ) ![]runtime_schema.RelationalColumn {
        const total = select.fields.len + select.windows.len;
        if (total == 0) return &.{};
        const out = try self.alloc.alloc(runtime_schema.RelationalColumn, total);
        var initialized: usize = 0;
        errdefer self.alloc.free(out);
        for (select.fields) |field| {
            if (aggregateOutputColumnExists(out[0..initialized], field)) return error.UnsupportedSqlShape;
            const column = relationalColumnForField(self.schema, field, null) orelse return error.InvalidSqlCatalog;
            out[initialized] = .{
                .name = field,
                .path = field,
                .field_type = column.field_type,
                .array_item_type = column.array_item_type,
                .nullable = column.nullable,
            };
            initialized += 1;
        }
        for (select.windows) |window| {
            if (aggregateOutputColumnExists(out[0..initialized], window.output)) return error.UnsupportedSqlShape;
            out[initialized] = .{
                .name = window.output,
                .path = window.output,
                .field_type = try self.windowOutputType(window),
                .nullable = true,
            };
            initialized += 1;
        }
        return out;
    }

    fn windowOutputType(
        self: *@This(),
        window: db_mod.types.RelationalRowsWindowSpec,
    ) !runtime_schema.AntflyType {
        return switch (window.function) {
            .row_number, .rank, .dense_rank, .percent_rank, .cume_dist, .ntile, .count, .sum, .avg => .numeric,
            .lag, .lead, .first_value, .last_value, .nth_value, .min, .max => try self.rowExpressionOutputType(window.value_expression orelse return error.UnsupportedSqlShape),
            .bool_or, .bool_and => .boolean,
        };
    }

    fn parseAggregateHaving(
        self: *@This(),
        predicates: *std.ArrayListUnmanaged(runtime_schema.RelationalCheck),
        expressions: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition),
        any_groups: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
        not_groups: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
        group_fields: []const []const u8,
        group_expressions: []const db_mod.types.RelationalRowsExpressionProjection,
        aggregations: []const db_mod.types.RelationalRowsAggregateSpec,
    ) !void {
        if (try self.canParseBareBooleanAggregateHavingExpression(group_fields, group_expressions, aggregations)) {
            try self.parseBareBooleanAggregateHavingExpression(expressions, group_fields, group_expressions, aggregations);
            return;
        }
        if (self.whereHasTopLevelOr() or self.aggregateHavingHasBooleanIsNot()) {
            try self.parseAggregateHavingOrGroups(any_groups, group_fields, group_expressions, aggregations);
            return;
        }
        while (true) {
            if (self.canParseAggregateHavingNot()) {
                try self.parseAggregateHavingNotGroup(not_groups, group_fields, group_expressions, aggregations);
            } else if (self.matchStandaloneSqlBooleanLiteral()) |enabled| {
                if (!enabled) try self.appendBooleanConstantExpressionCondition(expressions, false);
            } else if (self.peekAggregateHavingExpression()) {
                const condition = try self.parseAggregateOutputExpressionConditionAlloc(group_fields, group_expressions, aggregations);
                var condition_transferred = false;
                errdefer if (!condition_transferred) freeExpressionCondition(self.alloc, condition);
                try expressions.append(self.alloc, condition);
                condition_transferred = true;
            } else {
                const field = try self.parseAggregateOutputFieldAlloc(group_fields, group_expressions, aggregations);
                var field_transferred = false;
                errdefer if (!field_transferred) self.alloc.free(field);
                if (!aggregateOutputFieldIsUnique(group_fields, group_expressions, aggregations, field)) return error.UnsupportedSqlShape;
                const column = try self.aggregateOutputColumnForFieldAlloc(group_fields, group_expressions, aggregations, field);
                var predicate_transferred = false;
                const op: runtime_schema.RelationalCheckOp = if (self.matchKeyword("is")) blk: {
                    const not = self.matchKeyword("not");
                    if (self.matchKeyword("distinct")) {
                        try self.expectKeyword("from");
                        break :blk if (not) .is_not_distinct else .is_distinct;
                    }
                    if (try self.parseSqlBooleanIsUnknown(column)) {
                        break :blk if (not) .is_not_null else .is_null;
                    }
                    if (try self.parseSqlBooleanIsValueAlloc(column, not)) |value_json| {
                        var value_transferred = false;
                        errdefer if (!value_transferred) self.alloc.free(value_json);
                        try predicates.append(self.alloc, .{
                            .name = "",
                            .field = field,
                            .op = .eq,
                            .value_json = value_json,
                        });
                        field_transferred = true;
                        value_transferred = true;
                        predicate_transferred = true;
                        break :blk .eq;
                    }
                    const null_op: runtime_schema.RelationalCheckOp = if (not) op_blk: {
                        try self.expectKeyword("null");
                        break :op_blk .is_not_null;
                    } else op_blk: {
                        try self.expectKeyword("null");
                        break :op_blk .is_null;
                    };
                    break :blk null_op;
                } else try self.parseComparisonOp();
                if (predicate_transferred) {
                    if (!self.matchKeyword("and")) break;
                    continue;
                }
                const value_json = switch (op) {
                    .is_null, .is_not_null => null,
                    else => try self.parseJsonValueAlloc(),
                };
                var value_transferred = false;
                errdefer if (!value_transferred) if (value_json) |json| self.alloc.free(json);
                try predicates.append(self.alloc, .{
                    .name = "",
                    .field = field,
                    .op = op,
                    .value_json = value_json,
                });
                field_transferred = true;
                value_transferred = true;
            }
            if (!self.matchKeyword("and")) break;
        }
    }

    fn canParseBareBooleanAggregateHavingExpression(
        self: *@This(),
        group_fields: []const []const u8,
        group_expressions: []const db_mod.types.RelationalRowsExpressionProjection,
        aggregations: []const db_mod.types.RelationalRowsAggregateSpec,
    ) !bool {
        const output_columns = try self.aggregateOutputColumnsAlloc(group_fields, group_expressions, aggregations);
        defer if (output_columns.len > 0) self.alloc.free(output_columns);
        const prior_schema = self.schema;
        self.schema = .{
            .storage_mode = .relational,
            .relational_columns = output_columns,
        };
        defer self.schema = prior_schema;
        return try self.canParseBareBooleanWhereExpression();
    }

    fn parseBareBooleanAggregateHavingExpression(
        self: *@This(),
        expressions: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition),
        group_fields: []const []const u8,
        group_expressions: []const db_mod.types.RelationalRowsExpressionProjection,
        aggregations: []const db_mod.types.RelationalRowsAggregateSpec,
    ) !void {
        const output_columns = try self.aggregateOutputColumnsAlloc(group_fields, group_expressions, aggregations);
        defer if (output_columns.len > 0) self.alloc.free(output_columns);
        const prior_schema = self.schema;
        self.schema = .{
            .storage_mode = .relational,
            .relational_columns = output_columns,
        };
        defer self.schema = prior_schema;
        try self.parseBareBooleanWhereExpression(expressions);
    }

    fn aggregateHavingHasBooleanIsNot(self: *@This()) bool {
        var depth: usize = 0;
        var i = self.pos;
        while (i + 2 < self.tokens.len) : (i += 1) {
            const token = self.tokens[i];
            switch (token.kind) {
                .lparen => depth += 1,
                .rparen => {
                    if (depth == 0) return false;
                    depth -= 1;
                },
                .identifier => {
                    if (depth == 0 and (std.ascii.eqlIgnoreCase(token.text, "order") or
                        std.ascii.eqlIgnoreCase(token.text, "limit") or
                        std.ascii.eqlIgnoreCase(token.text, "offset") or
                        std.ascii.eqlIgnoreCase(token.text, "fetch")))
                    {
                        return false;
                    }
                    if (std.ascii.eqlIgnoreCase(token.text, "is") and
                        self.tokens[i + 1].kind == .identifier and
                        std.ascii.eqlIgnoreCase(self.tokens[i + 1].text, "not") and
                        self.tokens[i + 2].kind == .identifier and
                        (std.ascii.eqlIgnoreCase(self.tokens[i + 2].text, "true") or
                            std.ascii.eqlIgnoreCase(self.tokens[i + 2].text, "false")))
                    {
                        return true;
                    }
                },
                else => {},
            }
        }
        return false;
    }

    fn canParseAggregateHavingNot(self: *@This()) bool {
        return self.peekKeyword("not") and self.pos + 1 < self.tokens.len and self.tokens[self.pos + 1].kind == .lparen;
    }

    fn parseAggregateHavingNotGroup(
        self: *@This(),
        not_groups: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
        group_fields: []const []const u8,
        group_expressions: []const db_mod.types.RelationalRowsExpressionProjection,
        aggregations: []const db_mod.types.RelationalRowsAggregateSpec,
    ) !void {
        try self.expectKeyword("not");
        try self.expect(.lparen);
        var groups = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
        var groups_transferred = false;
        defer groups.deinit(self.alloc);
        errdefer {
            if (!groups_transferred) freeExpressionPredicateGroups(self.alloc, groups.items);
        }
        try groups.append(self.alloc, .{ .conditions = &.{} });

        while (true) {
            var alternatives = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
            defer alternatives.deinit(self.alloc);
            errdefer freeExpressionPredicateGroups(self.alloc, alternatives.items);
            try self.parseAggregateHavingConditionAlternatives(&alternatives, group_fields, group_expressions, aggregations);
            try self.andExpressionPredicateAlternatives(&groups, alternatives.items);
            freeExpressionPredicateGroups(self.alloc, alternatives.items);
            if (!self.matchKeyword("and")) break;
        }
        if (groups.items.len == 0) return error.UnsupportedSqlShape;
        try self.expect(.rparen);

        try not_groups.appendSlice(self.alloc, groups.items);
        groups_transferred = true;
    }

    fn parseAggregateHavingOrGroups(
        self: *@This(),
        any_groups: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
        group_fields: []const []const u8,
        group_expressions: []const db_mod.types.RelationalRowsExpressionProjection,
        aggregations: []const db_mod.types.RelationalRowsAggregateSpec,
    ) !void {
        while (true) {
            const parenthesized = self.matchBooleanGroupOpen();
            var groups = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
            var groups_transferred = false;
            defer groups.deinit(self.alloc);
            errdefer {
                if (!groups_transferred) freeExpressionPredicateGroups(self.alloc, groups.items);
            }
            try groups.append(self.alloc, .{ .conditions = &.{} });

            while (true) {
                var alternatives = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
                defer alternatives.deinit(self.alloc);
                errdefer freeExpressionPredicateGroups(self.alloc, alternatives.items);
                try self.parseAggregateHavingConditionAlternatives(&alternatives, group_fields, group_expressions, aggregations);
                try self.andExpressionPredicateAlternatives(&groups, alternatives.items);
                freeExpressionPredicateGroups(self.alloc, alternatives.items);
                if (!self.matchKeyword("and")) break;
            }
            if (groups.items.len == 0) return error.UnsupportedSqlShape;
            if (parenthesized) try self.expect(.rparen);
            try any_groups.appendSlice(self.alloc, groups.items);
            groups_transferred = true;

            if (!self.matchKeyword("or")) break;
        }
    }

    fn parseAggregateHavingConditionAlternatives(
        self: *@This(),
        alternatives: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
        group_fields: []const []const u8,
        group_expressions: []const db_mod.types.RelationalRowsExpressionProjection,
        aggregations: []const db_mod.types.RelationalRowsAggregateSpec,
    ) !void {
        if (self.matchStandaloneSqlBooleanLiteral()) |enabled| {
            try self.appendBooleanConstantExpressionGroup(alternatives, enabled);
            return;
        }
        if (try self.parseAggregateHavingBooleanIsNotGroups(alternatives, group_fields, group_expressions, aggregations)) {
            return;
        }

        const condition = if (self.peekAggregateHavingExpression())
            try self.parseAggregateOutputExpressionConditionAlloc(group_fields, group_expressions, aggregations)
        else
            try self.parseAggregateOutputFieldExpressionConditionAlloc(group_fields, group_expressions, aggregations);
        var condition_transferred = false;
        errdefer if (!condition_transferred) freeExpressionCondition(self.alloc, condition);

        const conditions = try self.alloc.alloc(db_mod.types.RelationalRowsExpressionCondition, 1);
        var conditions_transferred = false;
        errdefer if (!conditions_transferred) self.alloc.free(conditions);
        conditions[0] = condition;
        condition_transferred = true;
        try alternatives.append(self.alloc, .{ .conditions = conditions });
        conditions_transferred = true;
    }

    fn parseAggregateHavingBooleanIsNotGroups(
        self: *@This(),
        groups: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
        group_fields: []const []const u8,
        group_expressions: []const db_mod.types.RelationalRowsExpressionProjection,
        aggregations: []const db_mod.types.RelationalRowsAggregateSpec,
    ) !bool {
        const saved_pos = self.pos;
        const field = self.parseAggregateOutputFieldAlloc(group_fields, group_expressions, aggregations) catch |err| {
            self.pos = saved_pos;
            return switch (err) {
                error.UnsupportedSqlShape => false,
                else => err,
            };
        };
        defer self.alloc.free(field);
        if (!self.matchKeyword("is")) {
            self.pos = saved_pos;
            return false;
        }
        if (!self.matchKeyword("not")) {
            self.pos = saved_pos;
            return false;
        }
        if (!(self.peekKeyword("true") or self.peekKeyword("false"))) {
            self.pos = saved_pos;
            return false;
        }

        const column = try self.aggregateOutputColumnForFieldAlloc(group_fields, group_expressions, aggregations, field);
        const value = (try self.parseSqlBooleanIsValue(column)) orelse return error.UnsupportedSqlShape;
        try self.appendBooleanIsNotExpressionGroups(groups, field, value);
        return true;
    }

    fn parseAggregateOutputFieldExpressionConditionAlloc(
        self: *@This(),
        group_fields: []const []const u8,
        group_expressions: []const db_mod.types.RelationalRowsExpressionProjection,
        aggregations: []const db_mod.types.RelationalRowsAggregateSpec,
    ) !db_mod.types.RelationalRowsExpressionCondition {
        const field = try self.parseAggregateOutputFieldAlloc(group_fields, group_expressions, aggregations);
        var field_transferred = false;
        errdefer if (!field_transferred) self.alloc.free(field);
        if (!aggregateOutputFieldIsUnique(group_fields, group_expressions, aggregations, field)) return error.UnsupportedSqlShape;
        const column = try self.aggregateOutputColumnForFieldAlloc(group_fields, group_expressions, aggregations, field);

        const op: runtime_schema.RelationalCheckOp = if (self.matchKeyword("is")) blk: {
            const not = self.matchKeyword("not");
            if (self.matchKeyword("distinct")) {
                try self.expectKeyword("from");
                break :blk if (not) .is_not_distinct else .is_distinct;
            }
            if (try self.parseSqlBooleanIsUnknown(column)) {
                break :blk if (not) .is_not_null else .is_null;
            }
            if (try self.parseSqlBooleanIsValueAlloc(column, not)) |value_json| {
                errdefer self.alloc.free(value_json);
                const lhs_field = field;
                field_transferred = true;
                const rhs = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
                var rhs_transferred = false;
                errdefer if (!rhs_transferred) self.alloc.free(rhs);
                rhs[0] = .{
                    .kind = .value,
                    .value_json = value_json,
                };
                rhs_transferred = true;
                return .{
                    .lhs = .{
                        .kind = .field,
                        .field = lhs_field,
                    },
                    .op = .eq,
                    .rhs = rhs,
                };
            }
            try self.expectKeyword("null");
            break :blk if (not) .is_not_null else .is_null;
        } else try self.parseComparisonOp();

        const lhs: db_mod.types.RelationalRowsExpression = .{
            .kind = .field,
            .field = field,
        };
        field_transferred = true;

        const rhs = switch (op) {
            .is_null, .is_not_null => &.{},
            else => blk: {
                const value_json = try self.parseJsonValueAlloc();
                var value_transferred = false;
                errdefer if (!value_transferred) self.alloc.free(value_json);
                const out = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
                var out_transferred = false;
                errdefer if (!out_transferred) self.alloc.free(out);
                out[0] = .{
                    .kind = .value,
                    .value_json = value_json,
                };
                value_transferred = true;
                out_transferred = true;
                break :blk out;
            },
        };

        return .{
            .lhs = lhs,
            .op = op,
            .rhs = rhs,
        };
    }

    fn aggregateOutputColumnForFieldAlloc(
        self: *@This(),
        group_fields: []const []const u8,
        group_expressions: []const db_mod.types.RelationalRowsExpressionProjection,
        aggregations: []const db_mod.types.RelationalRowsAggregateSpec,
        field: []const u8,
    ) !runtime_schema.RelationalColumn {
        const output_columns = try self.aggregateOutputColumnsAlloc(group_fields, group_expressions, aggregations);
        defer if (output_columns.len > 0) self.alloc.free(output_columns);
        for (output_columns) |column| {
            if (std.mem.eql(u8, column.name, field)) return column;
        }
        return error.UnsupportedSqlShape;
    }

    fn peekAggregateHavingExpression(self: *@This()) bool {
        if (self.nextIsAggregateFunction()) return false;
        if (self.pos >= self.tokens.len) return false;
        const token = self.tokens[self.pos];
        if (self.peekParenthesizedExpressionCondition()) return true;
        if (token.kind == .identifier) {
            if (self.pos + 1 >= self.tokens.len) return false;
            const next = self.tokens[self.pos + 1];
            if (next.kind == .eq or next.kind == .neq or next.kind == .gt or next.kind == .gte or next.kind == .lt or next.kind == .lte) return false;
            if (next.kind == .identifier and std.ascii.eqlIgnoreCase(next.text, "is")) return false;
            return true;
        }
        return token.kind == .minus or
            token.kind == .number or
            self.peekKeyword("lower") or
            self.peekKeyword("upper") or
            self.peekKeyword("trim") or
            self.peekTrimVariantFunctionCall() or
            self.peekKeyword("replace") or
            self.peekKeyword("regexp_replace") or
            self.peekRegexpSubstrFunctionCall() or
            self.peekRegexpMatchFunctionCall() or
            self.peekRegexpCountFunctionCall() or
            self.peekRegexpInstrFunctionCall() or
            self.peekTranslateFunctionCall() or
            self.peekKeyword("case") or
            self.peekKeyword("cast") or
            self.peekKeyword("coalesce") or
            self.peekKeyword("nullif") or
            self.peekTextLengthFunctionKeyword() or
            self.peekAsciiFunctionCall() or
            self.peekChrFunctionCall() or
            self.peekSubstringFunctionKeyword() or
            self.peekOverlayFunctionCall() or
            self.peekSplitPartFunctionKeyword() or
            self.peekStrposFunctionKeyword() or
            self.peekLeftRightFunctionCall() or
            self.peekPadFunctionCall() or
            self.peekRepeatFunctionCall() or
            self.peekReverseFunctionCall() or
            self.peekMd5FunctionCall() or
            self.peekStartsWithFunctionCall() or
            self.peekEndsWithFunctionCall() or
            self.peekDateTruncFunctionCall() or
            self.peekDateBinFunctionCall() or
            self.peekDatePartFunctionCall() or
            self.peekKeyword("position") or
            self.peekKeyword("abs") or
            self.peekKeyword("round") or
            self.peekFunctionCall("trunc") or
            self.peekFunctionCall("floor") or
            self.peekFunctionCall("ceil") or
            self.peekFunctionCall("sqrt") or
            self.peekFunctionCall("sign") or
            self.peekFunctionCall("mod") or
            self.peekFunctionCall("power") or
            self.peekKeyword("greatest") or
            self.peekKeyword("least");
    }

    fn parseAggregateOutputExpressionConditionAlloc(
        self: *@This(),
        group_fields: []const []const u8,
        group_expressions: []const db_mod.types.RelationalRowsExpressionProjection,
        aggregations: []const db_mod.types.RelationalRowsAggregateSpec,
    ) !db_mod.types.RelationalRowsExpressionCondition {
        const output_columns = try self.aggregateOutputColumnsAlloc(group_fields, group_expressions, aggregations);
        defer if (output_columns.len > 0) self.alloc.free(output_columns);
        const prior_schema = self.schema;
        self.schema = .{
            .storage_mode = .relational,
            .relational_columns = output_columns,
        };
        defer self.schema = prior_schema;
        return try self.parseCaseExpressionConditionAlloc();
    }

    fn aggregateOutputColumnsAlloc(
        self: *@This(),
        group_fields: []const []const u8,
        group_expressions: []const db_mod.types.RelationalRowsExpressionProjection,
        aggregations: []const db_mod.types.RelationalRowsAggregateSpec,
    ) ![]runtime_schema.RelationalColumn {
        const total = group_fields.len + group_expressions.len + aggregations.len;
        if (total == 0) return &.{};
        const out = try self.alloc.alloc(runtime_schema.RelationalColumn, total);
        var initialized: usize = 0;
        errdefer self.alloc.free(out);
        for (group_fields) |field| {
            if (aggregateOutputColumnExists(out[0..initialized], field)) return error.UnsupportedSqlShape;
            const column = relationalColumnForField(self.schema, field, null) orelse return error.InvalidSqlCatalog;
            out[initialized] = .{
                .name = field,
                .path = field,
                .field_type = column.field_type,
                .array_item_type = column.array_item_type,
                .nullable = column.nullable,
            };
            initialized += 1;
        }
        for (group_expressions) |projection| {
            if (aggregateOutputColumnExists(out[0..initialized], projection.output)) return error.UnsupportedSqlShape;
            out[initialized] = .{
                .name = projection.output,
                .path = projection.output,
                .field_type = try self.rowExpressionOutputType(projection.expression),
                .nullable = true,
            };
            initialized += 1;
        }
        for (aggregations) |aggregation| {
            if (aggregateOutputColumnExists(out[0..initialized], aggregation.name)) return error.UnsupportedSqlShape;
            out[initialized] = .{
                .name = aggregation.name,
                .path = aggregation.name,
                .field_type = aggregateOutputType(aggregation),
                .array_item_type = if (aggregation.op == .array_agg) .keyword else null,
                .nullable = false,
            };
            initialized += 1;
        }
        return out;
    }

    fn parseAggregateOutputFieldAlloc(
        self: *@This(),
        group_fields: []const []const u8,
        group_expressions: []const db_mod.types.RelationalRowsExpressionProjection,
        aggregations: []const db_mod.types.RelationalRowsAggregateSpec,
    ) ![]const u8 {
        if (self.nextIsAggregateFunction()) {
            const candidate = try self.parseAggregateSpecAlloc();
            defer freeAggregateSpec(self.alloc, candidate);
            var matched_name: ?[]const u8 = null;
            for (aggregations) |aggregation| {
                if (!aggregateSpecsEquivalent(candidate, aggregation)) continue;
                if (matched_name != null) return error.UnsupportedSqlShape;
                matched_name = aggregation.name;
            }
            const name = matched_name orelse return error.UnsupportedSqlShape;
            return try self.alloc.dupe(u8, name);
        }

        const field = try self.parseIdentifierOwned();
        errdefer self.alloc.free(field);
        if (!aggregateOutputFieldIsUnique(group_fields, group_expressions, aggregations, field)) return error.UnsupportedSqlShape;
        return field;
    }

    fn parseComparisonOp(self: *@This()) !runtime_schema.RelationalCheckOp {
        if (self.match(.eq) != null) return .eq;
        if (self.match(.neq) != null) return .ne;
        if (self.match(.gt) != null) return .gt;
        if (self.match(.gte) != null) return .gte;
        if (self.match(.lt) != null) return .lt;
        if (self.match(.lte) != null) return .lte;
        return error.UnsupportedSqlShape;
    }

    fn parseJsonValueAlloc(self: *@This()) ![]const u8 {
        if (self.peekKeyword("convert_from")) return try self.parseConvertFromJsonAlloc();
        if (self.peekKeyword("to_jsonb")) return try self.parseToJsonbValueJsonAlloc();
        if (self.matchKeyword("null")) return try self.alloc.dupe(u8, "null");
        if (self.matchKeyword("true")) return try self.alloc.dupe(u8, "true");
        if (self.matchKeyword("false")) return try self.alloc.dupe(u8, "false");
        if (self.match(.string)) |token| return try std.json.Stringify.valueAlloc(self.alloc, token.text, .{});
        if (self.match(.number)) |token| return try self.alloc.dupe(u8, token.text);
        if (self.match(.minus) != null) return try self.parseNegativeNumberJsonAlloc();
        if (self.match(.placeholder)) |token| return try self.boundValueJsonAlloc(token);
        return error.UnsupportedSqlShape;
    }

    fn parseToJsonbValueJsonAlloc(self: *@This()) anyerror![]const u8 {
        try self.expectKeyword("to_jsonb");
        try self.expect(.lparen);
        const value_json = try self.parseJsonValueAlloc();
        errdefer self.alloc.free(value_json);
        try self.expect(.rparen);
        return value_json;
    }

    fn parseJsonDocumentValueAlloc(self: *@This()) ![]const u8 {
        if (self.match(.placeholder)) |token| {
            const value = try self.boundValue(token);
            return switch (value) {
                .json => |json| blk: {
                    try validateJsonDocument(self.alloc, json);
                    break :blk try self.alloc.dupe(u8, json);
                },
                else => error.UnsupportedSqlShape,
            };
        }
        if (self.match(.string)) |token| {
            try validateJsonDocument(self.alloc, token.text);
            return try self.alloc.dupe(u8, token.text);
        }
        return error.UnsupportedSqlShape;
    }

    fn appendJsonObjectConcatSetValues(
        self: *@This(),
        field: []const u8,
        json_set: *std.ArrayListUnmanaged(JsonSetValue),
    ) !void {
        const object_json = try self.parseJsonDocumentValueAlloc();
        defer self.alloc.free(object_json);
        var parsed = std.json.parseFromSlice(std.json.Value, self.alloc, object_json, .{}) catch return error.UnsupportedSqlShape;
        defer parsed.deinit();
        if (parsed.value != .object) return error.UnsupportedSqlShape;
        if (parsed.value.object.count() == 0) return error.UnsupportedSqlShape;

        var it = parsed.value.object.iterator();
        while (it.next()) |entry| {
            if (std.mem.indexOfScalar(u8, entry.key_ptr.*, '.') != null) return error.UnsupportedSqlShape;
            const owned_field = try self.alloc.dupe(u8, field);
            var field_transferred = false;
            errdefer if (!field_transferred) self.alloc.free(owned_field);
            const path = try self.alloc.alloc([]const u8, 1);
            var path_transferred = false;
            errdefer if (!path_transferred) self.alloc.free(path);
            path[0] = try self.alloc.dupe(u8, entry.key_ptr.*);
            var path_item_transferred = false;
            errdefer if (!path_item_transferred) self.alloc.free(path[0]);
            const value_json = try std.json.Stringify.valueAlloc(self.alloc, entry.value_ptr.*, .{});
            var value_transferred = false;
            errdefer if (!value_transferred) self.alloc.free(value_json);
            try json_set.append(self.alloc, .{
                .field = owned_field,
                .path = path,
                .value_json = value_json,
            });
            field_transferred = true;
            path_transferred = true;
            path_item_transferred = true;
            value_transferred = true;
        }
    }

    fn parseJsonArrayValueAlloc(self: *@This()) ![]const u8 {
        const value_json = if (self.peekKeyword("array"))
            try self.parseSqlArrayConstructorJsonAlloc()
        else
            try self.parseJsonDocumentValueAlloc();
        errdefer self.alloc.free(value_json);
        try validateJsonArray(self.alloc, value_json);
        return value_json;
    }

    fn parseStructuredPredicateValueAlloc(self: *@This(), column: runtime_schema.RelationalColumn) ![]const u8 {
        return switch (column.field_type) {
            .array => try self.parseArrayPredicateValueAlloc(),
            .json => try self.parseJsonDocumentValueAlloc(),
            else => error.InvalidSqlCatalog,
        };
    }

    fn parseArrayPredicateValueAlloc(self: *@This()) ![]const u8 {
        return if (self.peekKeyword("array"))
            try self.parseSqlArrayConstructorJsonAlloc()
        else
            try self.parseJsonDocumentValueAlloc();
    }

    fn parseSqlArrayConstructorJsonAlloc(self: *@This()) ![]const u8 {
        try self.expectKeyword("array");
        try self.expect(.lbracket);
        var out: std.Io.Writer.Allocating = .init(self.alloc);
        errdefer out.deinit();
        const writer = &out.writer;
        try writer.writeByte('[');
        if (self.match(.rbracket) == null) {
            var first = true;
            while (true) {
                const value_json = try self.parseJsonValueAlloc();
                defer self.alloc.free(value_json);
                if (!first) try writer.writeByte(',');
                try writer.writeAll(value_json);
                first = false;
                if (self.match(.comma) == null) break;
            }
            try self.expect(.rbracket);
        }
        try writer.writeByte(']');
        return try out.toOwnedSlice();
    }

    fn parseSqlInValuesJsonAlloc(self: *@This()) ![]const u8 {
        try self.expect(.lparen);
        if (self.peekKind(.rparen)) return error.UnsupportedSqlShape;

        if (self.match(.placeholder)) |token| {
            const value = try self.boundValue(token);
            if (self.match(.rparen) != null) {
                return switch (value) {
                    .json => |json| blk: {
                        try validateJsonArray(self.alloc, json);
                        break :blk try self.alloc.dupe(u8, json);
                    },
                    else => try self.singleValueJsonArrayAlloc(value),
                };
            }
            const first_json = try value.jsonAlloc(self.alloc);
            defer self.alloc.free(first_json);
            return try self.parseSqlInRemainingValuesJsonAlloc(first_json);
        }

        const first_json = try self.parseJsonValueAlloc();
        defer self.alloc.free(first_json);
        return try self.parseSqlInRemainingValuesJsonAlloc(first_json);
    }

    fn parseSqlInRemainingValuesJsonAlloc(self: *@This(), first_json: []const u8) ![]const u8 {
        var out: std.Io.Writer.Allocating = .init(self.alloc);
        errdefer out.deinit();
        const writer = &out.writer;
        try writer.writeByte('[');
        try writer.writeAll(first_json);
        while (self.match(.comma) != null) {
            const value_json = try self.parseJsonValueAlloc();
            defer self.alloc.free(value_json);
            try writer.writeByte(',');
            try writer.writeAll(value_json);
        }
        try self.expect(.rparen);
        try writer.writeByte(']');
        return try out.toOwnedSlice();
    }

    fn singleValueJsonArrayAlloc(self: *@This(), value: SqlValue) ![]const u8 {
        const value_json = try value.jsonAlloc(self.alloc);
        defer self.alloc.free(value_json);
        var out: std.Io.Writer.Allocating = .init(self.alloc);
        errdefer out.deinit();
        const writer = &out.writer;
        try writer.writeByte('[');
        try writer.writeAll(value_json);
        try writer.writeByte(']');
        return try out.toOwnedSlice();
    }

    fn parseSqlColumnValueAlloc(self: *@This(), column: runtime_schema.RelationalColumn) ![]const u8 {
        if (self.matchKeyword("default")) {
            const default_value = column.default_value orelse return error.UnsupportedSqlShape;
            return try relational_rows.relationalDefaultValueJsonAlloc(self.alloc, default_value);
        }
        if (self.peekKeyword("now") or self.peekKeyword("current_timestamp")) {
            if (column.field_type != .numeric and column.field_type != .datetime) return error.InvalidSqlCatalog;
            return try self.parseNowValueJsonAlloc();
        }
        if (self.peekKeyword("current_date")) {
            if (column.field_type != .numeric and column.field_type != .datetime) return error.InvalidSqlCatalog;
            return try self.parseCurrentDateValueJsonAlloc();
        }
        if (column.field_type == .datetime and self.peekSqlTypedDatetimeLiteral()) {
            return try self.parseSqlTypedDatetimeLiteralValueJsonAlloc();
        }
        if (self.peekUuidV4FunctionCall()) {
            if (column.field_type != .keyword and column.field_type != .text and column.field_type != .link) return error.InvalidSqlCatalog;
            return try self.parseUuidV4ValueJsonAlloc();
        }
        if (self.peekKeyword("convert_from")) {
            if (column.field_type != .json) return error.InvalidSqlCatalog;
            return try self.parseConvertFromJsonAlloc();
        }
        if (self.peekKeyword("jsonb_build_object")) {
            if (column.field_type != .json) return error.InvalidSqlCatalog;
            return try self.parseJsonbBuildObjectAlloc();
        }
        if (self.peekKeyword("to_jsonb")) {
            if (column.field_type != .json) return error.InvalidSqlCatalog;
            return try self.parseToJsonbValueJsonAlloc();
        }
        if (self.match(.placeholder)) |token| {
            const value = try self.boundValue(token);
            if (column.field_type == .json) {
                return switch (value) {
                    .json => |json| try self.alloc.dupe(u8, json),
                    else => try value.jsonAlloc(self.alloc),
                };
            }
            return try value.jsonAlloc(self.alloc);
        }
        if (self.match(.string)) |token| {
            if (column.field_type == .json) {
                if (jsonValueIsValid(self.alloc, token.text)) return try self.alloc.dupe(u8, token.text);
            }
            return try std.json.Stringify.valueAlloc(self.alloc, token.text, .{});
        }
        if (self.matchKeyword("null")) return try self.alloc.dupe(u8, "null");
        if (self.matchKeyword("true")) return try self.alloc.dupe(u8, "true");
        if (self.matchKeyword("false")) return try self.alloc.dupe(u8, "false");
        if (self.match(.number)) |token| return try self.alloc.dupe(u8, token.text);
        if (self.match(.minus) != null) return try self.parseNegativeNumberJsonAlloc();
        return error.UnsupportedSqlShape;
    }

    fn parseSqlPeriodRangeValuePairAlloc(self: *@This(), period: runtime_schema.RelationalPeriod) !PeriodRangeValuePair {
        const start_column = relationalColumnForField(self.schema, period.start_column, null) orelse return error.InvalidSqlCatalog;
        const end_column = relationalColumnForField(self.schema, period.end_column, null) orelse return error.InvalidSqlCatalog;
        if (start_column.field_type != end_column.field_type or !relationalPeriodColumnType(start_column.field_type)) return error.InvalidSqlCatalog;
        if (self.match(.string)) |token| {
            return try self.parseSqlCanonicalRangeLiteralValuePairAlloc(token.text, start_column.field_type, period.range_type);
        }
        if (self.peekKind(.identifier) and self.pos + 1 < self.tokens.len and self.tokens[self.pos + 1].kind == .lparen) {
            return try self.parseSqlRangeConstructorValuePairAlloc(start_column.field_type);
        }
        return error.UnsupportedSqlShape;
    }

    fn freePeriodRangeValuePair(self: *@This(), value: PeriodRangeValuePair) void {
        self.alloc.free(value.start_json);
        self.alloc.free(value.end_json);
    }

    fn parseSqlRangeConstructorValuePairAlloc(self: *@This(), field_type: runtime_schema.AntflyType) !PeriodRangeValuePair {
        const function = self.match(.identifier) orelse return error.UnsupportedSqlShape;
        const constructor_type = ddlRangeBoundTypeForName(function.text) orelse return error.UnsupportedSqlShape;
        if (constructor_type != field_type) return error.UnsupportedSqlShape;
        try self.expect(.lparen);

        var start_json = try self.parseSqlRangeConstructorEndpointJsonAlloc(field_type);
        var start_transferred = false;
        errdefer if (!start_transferred) self.alloc.free(start_json);
        try self.expect(.comma);
        var end_json = try self.parseSqlRangeConstructorEndpointJsonAlloc(field_type);
        var end_transferred = false;
        errdefer if (!end_transferred) self.alloc.free(end_json);

        if (self.match(.comma) != null) {
            const bounds = self.match(.string) orelse return error.UnsupportedSqlShape;
            if (std.mem.eql(u8, bounds.text, "[)")) {
                // Already canonical.
            } else if (std.ascii.eqlIgnoreCase(function.text, "daterange")) {
                if (bounds.text.len != 2) return error.UnsupportedSqlShape;
                const lower_bound = bounds.text[0];
                const upper_bound = bounds.text[1];
                if (lower_bound != '[' and lower_bound != '(') return error.UnsupportedSqlShape;
                if (upper_bound != ')' and upper_bound != ']') return error.UnsupportedSqlShape;
                if (lower_bound == '(' and !std.mem.eql(u8, start_json, "null")) {
                    const canonical_start_json = try self.canonicalizeDiscreteDateRangeFiniteBoundAlloc(start_json);
                    self.alloc.free(start_json);
                    start_json = canonical_start_json;
                }
                if (upper_bound == ']') {
                    const canonical_end_json = try self.canonicalizeDiscreteDateRangeFiniteBoundAlloc(end_json);
                    self.alloc.free(end_json);
                    end_json = canonical_end_json;
                }
            } else {
                return error.UnsupportedSqlShape;
            }
        }
        try self.expect(.rparen);

        start_transferred = true;
        end_transferred = true;
        return .{
            .start_json = start_json,
            .end_json = end_json,
        };
    }

    fn canonicalizeDiscreteDateRangeFiniteBoundAlloc(self: *@This(), bound_json: []const u8) ![]const u8 {
        if (std.mem.eql(u8, bound_json, "null")) return error.UnsupportedSqlShape;
        const bound_ns = std.fmt.parseInt(u64, bound_json, 10) catch return error.UnsupportedSqlShape;
        if (std.math.maxInt(u64) - bound_ns < ns_per_day) return error.UnsupportedSqlShape;
        return try std.fmt.allocPrint(self.alloc, "{d}", .{bound_ns + ns_per_day});
    }

    fn parseSqlCanonicalRangeLiteralValuePairAlloc(
        self: *@This(),
        literal: []const u8,
        field_type: runtime_schema.AntflyType,
        range_type: ?runtime_schema.RelationalPeriodRangeType,
    ) !PeriodRangeValuePair {
        if (literal.len < 3) return error.UnsupportedSqlShape;
        const upper_bound = literal[literal.len - 1];
        const lower_bound = literal[0];
        if (lower_bound != '[' and lower_bound != '(') return error.UnsupportedSqlShape;
        if (upper_bound != ')' and upper_bound != ']') return error.UnsupportedSqlShape;
        const body = literal[1 .. literal.len - 1];
        const comma = std.mem.indexOfScalar(u8, body, ',') orelse return error.UnsupportedSqlShape;
        if (std.mem.indexOfScalar(u8, body[comma + 1 ..], ',') != null) return error.UnsupportedSqlShape;
        const start_text = std.mem.trim(u8, body[0..comma], " \t\r\n");
        const end_text = std.mem.trim(u8, body[comma + 1 ..], " \t\r\n");
        if (start_text.len != 0 and lower_bound == '(' and range_type != .daterange) return error.UnsupportedSqlShape;
        if (upper_bound == ']' and (range_type != .daterange or end_text.len == 0)) return error.UnsupportedSqlShape;

        var start_json = try self.parseSqlRangeEndpointJsonAlloc(start_text, field_type);
        var start_transferred = false;
        errdefer if (!start_transferred) self.alloc.free(start_json);
        var end_json = try self.parseSqlRangeEndpointJsonAlloc(end_text, field_type);
        var end_transferred = false;
        errdefer if (!end_transferred) self.alloc.free(end_json);
        if (lower_bound == '(' and start_text.len != 0) {
            const canonical_start_json = try self.canonicalizeDiscreteDateRangeFiniteBoundAlloc(start_json);
            self.alloc.free(start_json);
            start_json = canonical_start_json;
        }
        if (upper_bound == ']') {
            const canonical_end_json = try self.canonicalizeDiscreteDateRangeFiniteBoundAlloc(end_json);
            self.alloc.free(end_json);
            end_json = canonical_end_json;
        }

        start_transferred = true;
        end_transferred = true;
        return .{
            .start_json = start_json,
            .end_json = end_json,
        };
    }

    fn parseSqlRangeEndpointJsonAlloc(self: *@This(), endpoint: []const u8, field_type: runtime_schema.AntflyType) ![]const u8 {
        if (endpoint.len == 0) return try self.alloc.dupe(u8, "null");
        return switch (field_type) {
            .numeric => blk: {
                if (!sqlStringIsJsonNumber(self.alloc, endpoint)) return error.UnsupportedSqlShape;
                break :blk try self.alloc.dupe(u8, endpoint);
            },
            .datetime => blk: {
                if (sqlStringIsJsonNumber(self.alloc, endpoint)) return try self.alloc.dupe(u8, endpoint);
                const timestamp_ns = try parseSqlTimestampLiteralNs(endpoint);
                break :blk try std.fmt.allocPrint(self.alloc, "{d}", .{timestamp_ns});
            },
            else => error.InvalidSqlCatalog,
        };
    }

    fn parseSqlRangeConstructorEndpointJsonAlloc(self: *@This(), field_type: runtime_schema.AntflyType) ![]const u8 {
        if (self.matchKeyword("null")) return try self.alloc.dupe(u8, "null");
        if (field_type == .datetime) {
            if (self.peekKeyword("now") or self.peekKeyword("current_timestamp")) return try self.parseNowValueJsonAlloc();
            if (self.peekKeyword("current_date")) return try self.parseCurrentDateValueJsonAlloc();
            if (self.peekSqlTypedDatetimeLiteral()) return try self.parseSqlTypedDatetimeLiteralValueJsonAlloc();
        }
        if (self.match(.placeholder)) |token| {
            const value = try self.boundValue(token);
            return switch (field_type) {
                .numeric => switch (value) {
                    .integer, .float => try value.jsonAlloc(self.alloc),
                    .string => |text| try self.parseSqlRangeEndpointJsonAlloc(text, field_type),
                    else => error.UnsupportedSqlShape,
                },
                .datetime => switch (value) {
                    .integer => try value.jsonAlloc(self.alloc),
                    .string => |text| try self.parseSqlRangeEndpointJsonAlloc(text, field_type),
                    else => error.UnsupportedSqlShape,
                },
                else => error.InvalidSqlCatalog,
            };
        }
        if (self.match(.string)) |token| return try self.parseSqlRangeEndpointJsonAlloc(token.text, field_type);
        if (self.match(.number)) |token| return try self.parseSqlRangeEndpointJsonAlloc(token.text, field_type);
        if (self.match(.minus) != null) {
            const number = self.match(.number) orelse return error.UnsupportedSqlShape;
            const text = try std.fmt.allocPrint(self.alloc, "-{s}", .{number.text});
            defer self.alloc.free(text);
            return try self.parseSqlRangeEndpointJsonAlloc(text, field_type);
        }
        return error.UnsupportedSqlShape;
    }

    fn peekSqlTypedDatetimeLiteral(self: *@This()) bool {
        return self.pos + 1 < self.tokens.len and
            self.tokens[self.pos].kind == .identifier and
            self.tokens[self.pos + 1].kind == .string and
            (std.ascii.eqlIgnoreCase(self.tokens[self.pos].text, "date") or
                std.ascii.eqlIgnoreCase(self.tokens[self.pos].text, "timestamp") or
                std.ascii.eqlIgnoreCase(self.tokens[self.pos].text, "timestamptz"));
    }

    fn parseSqlTypedDatetimeLiteralValueJsonAlloc(self: *@This()) ![]const u8 {
        if (!self.matchKeyword("date") and
            !self.matchKeyword("timestamp") and
            !self.matchKeyword("timestamptz")) return error.UnsupportedSqlShape;
        const token = self.match(.string) orelse return error.UnsupportedSqlShape;
        return try self.parseSqlRangeEndpointJsonAlloc(token.text, .datetime);
    }

    fn parseNowValueJsonAlloc(self: *@This()) ![]const u8 {
        if (self.matchKeyword("now")) {
            try self.expect(.lparen);
            try self.expect(.rparen);
        } else if (self.matchKeyword("current_timestamp")) {
            try self.parseOptionalCurrentTimestampPrecision();
        } else {
            return error.UnsupportedSqlShape;
        }
        return try std.fmt.allocPrint(self.alloc, "{d}", .{platform_time.realtimeNs()});
    }

    fn parseCurrentDateValueJsonAlloc(self: *@This()) ![]const u8 {
        try self.expectKeyword("current_date");
        return try std.fmt.allocPrint(self.alloc, "{d}", .{currentUtcDateStartNs()});
    }

    fn parseUuidV4ValueJsonAlloc(self: *@This()) ![]const u8 {
        _ = self.matchKeyword("gen_random_uuid") or self.matchKeyword("uuid_generate_v4") or return error.UnsupportedSqlShape;
        try self.expect(.lparen);
        try self.expect(.rparen);
        return try relational_rows.relationalDefaultValueJsonAlloc(self.alloc, .{ .kind = .uuid_v4, .value_json = "" });
    }

    fn parseConvertFromJsonAlloc(self: *@This()) ![]const u8 {
        try self.expectKeyword("convert_from");
        try self.expect(.lparen);
        const decoded = try self.parseConvertFromInputAlloc();
        defer self.alloc.free(decoded);
        try self.expect(.comma);
        const encoding = self.match(.string) orelse return error.UnsupportedSqlShape;
        if (!std.ascii.eqlIgnoreCase(encoding.text, "UTF8") and !std.ascii.eqlIgnoreCase(encoding.text, "UTF-8")) return error.UnsupportedSqlShape;
        try self.expect(.rparen);
        if (!jsonValueIsValid(self.alloc, decoded)) return error.UnsupportedSqlShape;
        return try self.alloc.dupe(u8, decoded);
    }

    fn parseConvertFromInputAlloc(self: *@This()) ![]const u8 {
        if (self.match(.placeholder)) |token| {
            const value = try self.boundValue(token);
            return switch (value) {
                .string => |text| try self.alloc.dupe(u8, text),
                .json => |json| try self.alloc.dupe(u8, json),
                else => error.UnsupportedSqlShape,
            };
        }
        if (self.match(.string)) |token| return try self.alloc.dupe(u8, token.text);
        return error.UnsupportedSqlShape;
    }

    fn parseJsonbBuildObjectAlloc(self: *@This()) ![]const u8 {
        try self.expectKeyword("jsonb_build_object");
        try self.expect(.lparen);
        if (self.match(.rparen) != null) return try self.alloc.dupe(u8, "{}");

        var seen = std.StringHashMapUnmanaged(void).empty;
        defer seen.deinit(self.alloc);
        var out: std.Io.Writer.Allocating = .init(self.alloc);
        errdefer out.deinit();
        const writer = &out.writer;
        try writer.writeByte('{');
        var first = true;
        while (true) {
            const key = try self.parseJsonbBuildObjectKey();
            const entry = try seen.getOrPut(self.alloc, key);
            if (entry.found_existing) return error.UnsupportedSqlShape;
            try self.expect(.comma);
            const value_json = try self.parseJsonValueAlloc();
            defer self.alloc.free(value_json);
            if (!first) try writer.writeByte(',');
            first = false;
            try writer.print("{f}:", .{std.json.fmt(key, .{})});
            try writer.writeAll(value_json);
            if (self.match(.comma) == null) break;
        }
        try self.expect(.rparen);
        try writer.writeByte('}');
        return try out.toOwnedSlice();
    }

    fn parseJsonbBuildObjectKey(self: *@This()) ![]const u8 {
        if (self.match(.string)) |token| return token.text;
        if (self.match(.placeholder)) |token| {
            const value = try self.boundValue(token);
            return switch (value) {
                .string => |key| key,
                else => error.UnsupportedSqlShape,
            };
        }
        return error.UnsupportedSqlShape;
    }

    fn parseReturningListAlloc(self: *@This()) ![]const []const u8 {
        if (self.match(.star) != null) {
            const fields = try self.alloc.alloc([]const u8, 1);
            errdefer self.alloc.free(fields);
            fields[0] = try self.alloc.dupe(u8, "*");
            return fields;
        }

        var fields = std.ArrayListUnmanaged([]const u8).empty;
        errdefer {
            for (fields.items) |field| self.alloc.free(field);
            fields.deinit(self.alloc);
        }
        while (true) {
            const field = try self.parseIdentifierOwned();
            var field_transferred = false;
            errdefer if (!field_transferred) self.alloc.free(field);
            if (self.peekKind(.lparen) or self.peekJsonExtractOperator()) return error.UnsupportedSqlShape;
            if (relationalColumnForReturningField(self.schema, field) == null) return error.InvalidSqlCatalog;
            try fields.append(self.alloc, field);
            field_transferred = true;
            if (self.match(.comma) == null) break;
        }
        return try fields.toOwnedSlice(self.alloc);
    }

    fn parseReturningProjectionAlloc(
        self: *@This(),
        returning_qualifiers: []const []const u8,
    ) !ReturningProjection {
        const previous_returning_expression_qualifiers = self.returning_expression_qualifiers;
        self.returning_expression_qualifiers = returning_qualifiers;
        defer self.returning_expression_qualifiers = previous_returning_expression_qualifiers;
        const previous_field_expression_qualifiers = self.field_expression_qualifiers;
        self.field_expression_qualifiers = returning_qualifiers;
        defer self.field_expression_qualifiers = previous_field_expression_qualifiers;

        var saw_all = false;
        var fields = std.ArrayListUnmanaged([]const u8).empty;
        errdefer {
            for (fields.items) |field| self.alloc.free(field);
            fields.deinit(self.alloc);
        }
        var expressions = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionProjection).empty;
        errdefer {
            for (expressions.items) |projection| freeExpressionProjection(self.alloc, projection);
            expressions.deinit(self.alloc);
        }

        while (true) {
            const returning_all_item = self.match(.star) != null or try self.matchQualifiedReturningAll(returning_qualifiers);
            if (returning_all_item) {
                if (saw_all or fields.items.len != 0 or expressions.items.len != 0) return error.UnsupportedSqlShape;
                const all_field = try self.alloc.dupe(u8, "*");
                var all_field_transferred = false;
                errdefer if (!all_field_transferred) self.alloc.free(all_field);
                try fields.append(self.alloc, all_field);
