    fn normalizeJoinedMutationReturningSourceFieldAlloc(
        self: *@This(),
        field: []const u8,
        source_alias: []const u8,
    ) !?[]const u8 {
        var dot: ?usize = std.mem.indexOfScalar(u8, field, '.');
        while (dot) |index| {
            if (index > 0 and index + 1 < field.len) {
                const qualifier = field[0..index];
                const unqualified_field = field[index + 1 ..];
                if (try self.returningQualifierMatches(qualifier, &.{source_alias})) {
                    const source_schema = self.joined_source_schema orelse self.schema;
                    if (relationalColumnForReturningField(source_schema, unqualified_field) == null) return error.InvalidSqlCatalog;
                    return try self.alloc.dupe(u8, unqualified_field);
                }
            }
            dot = std.mem.indexOfScalarPos(u8, field, index + 1, '.');
        }
        return null;
    }

    fn parseJoinedMutationReturningSelectItem(
        self: *@This(),
        source_alias: []const u8,
        returning_qualifiers: []const []const u8,
    ) !SelectItem {
        const previous_joined_target_expression_qualifiers = self.joined_target_expression_qualifiers;
        const previous_joined_source_expression_qualifiers = self.joined_source_expression_qualifiers;
        const previous_defer_row_expression_field_validation = self.defer_row_expression_field_validation;
        const source_qualifiers = [_][]const u8{source_alias};
        self.joined_target_expression_qualifiers = returning_qualifiers;
        self.joined_source_expression_qualifiers = source_qualifiers[0..];
        self.defer_row_expression_field_validation = true;
        defer {
            self.joined_target_expression_qualifiers = previous_joined_target_expression_qualifiers;
            self.joined_source_expression_qualifiers = previous_joined_source_expression_qualifiers;
            self.defer_row_expression_field_validation = previous_defer_row_expression_field_validation;
        }
        return try self.parseSelectItem();
    }

    fn normalizeReturningFieldAlloc(
        self: *@This(),
        field: []const u8,
        returning_qualifiers: []const []const u8,
    ) ![]const u8 {
        if (relationalColumnForReturningField(self.schema, field) != null) {
            return try self.alloc.dupe(u8, field);
        }

        var dot: ?usize = std.mem.indexOfScalar(u8, field, '.');
        while (dot) |index| {
            if (index > 0 and index + 1 < field.len) {
                const qualifier = field[0..index];
                const unqualified_field = field[index + 1 ..];
                if (try self.returningQualifierMatches(qualifier, returning_qualifiers)) {
                    if (relationalColumnForReturningField(self.schema, unqualified_field) == null) return error.InvalidSqlCatalog;
                    return try self.alloc.dupe(u8, unqualified_field);
                }
            }
            dot = std.mem.indexOfScalarPos(u8, field, index + 1, '.');
        }

        return error.InvalidSqlCatalog;
    }

    fn matchQualifiedReturningAll(
        self: *@This(),
        returning_qualifiers: []const []const u8,
    ) !bool {
        if (!self.peekKind(.identifier) or self.pos + 1 >= self.tokens.len) return false;
        const token = self.tokens[self.pos];
        if (!std.mem.endsWith(u8, token.text, ".")) return false;
        if (self.tokens[self.pos + 1].kind != .star) return false;
        const qualifier = token.text[0 .. token.text.len - 1];
        if (qualifier.len == 0) return error.UnsupportedSqlShape;
        if (!try self.returningQualifierMatches(qualifier, returning_qualifiers)) return error.InvalidSqlCatalog;
        self.pos += 2;
        return true;
    }

    fn returningQualifierMatches(
        self: *@This(),
        qualifier: []const u8,
        returning_qualifiers: []const []const u8,
    ) !bool {
        for (returning_qualifiers) |expected| {
            if (std.mem.eql(u8, qualifier, expected)) return true;
        }
        const normalized = try normalizeSqlObjectIdentifierAlloc(self.alloc, qualifier);
        defer self.alloc.free(normalized);
        for (returning_qualifiers) |expected| {
            if (std.mem.eql(u8, normalized, expected)) return true;
        }
        return false;
    }

    fn validateReturningProjectionOutputs(
        schema: runtime_schema.TableSchema,
        fields: []const []const u8,
        expressions: []const db_mod.types.RelationalRowsExpressionProjection,
    ) !void {
        const returning_all = fields.len == 1 and std.mem.eql(u8, fields[0], "*");
        if (returning_all) {
            for (expressions) |projection| {
                if (projection.output.len == 0) return error.UnsupportedSqlShape;
                if (relationalColumnForReturningField(schema, projection.output) != null) return error.UnsupportedSqlShape;
                if (returningExpressionOutputCount(expressions, projection.output) > 1) return error.UnsupportedSqlShape;
            }
            return;
        }
        for (fields) |field| {
            if (field.len == 0 or std.mem.eql(u8, field, "*")) return error.UnsupportedSqlShape;
            if (returningFieldOutputCount(fields, field) > 1) return error.UnsupportedSqlShape;
            if (returningExpressionOutputCount(expressions, field) > 0) return error.UnsupportedSqlShape;
        }
        for (expressions) |projection| {
            if (projection.output.len == 0) return error.UnsupportedSqlShape;
            if (returningExpressionOutputCount(expressions, projection.output) > 1) return error.UnsupportedSqlShape;
            if (returningFieldOutputCount(fields, projection.output) > 0) return error.UnsupportedSqlShape;
        }
    }

    fn returningFieldOutputCount(fields: []const []const u8, output: []const u8) usize {
        var count: usize = 0;
        for (fields) |field| {
            if (std.mem.eql(u8, field, output)) count += 1;
        }
        return count;
    }

    fn returningExpressionOutputCount(expressions: []const db_mod.types.RelationalRowsExpressionProjection, output: []const u8) usize {
        var count: usize = 0;
        for (expressions) |projection| {
            if (std.mem.eql(u8, projection.output, output)) count += 1;
        }
        return count;
    }

    fn peekSimpleReturningField(self: *@This()) bool {
        if (!self.peekKind(.identifier)) return false;
        if (self.peekKeyword("lower") or self.peekKeyword("upper") or self.peekInitcapFunctionCall() or self.peekKeyword("trim") or self.peekKeyword("replace") or self.peekKeyword("regexp_replace") or self.peekRegexpSubstrFunctionCall() or self.peekRegexpMatchFunctionCall() or self.peekRegexpCountFunctionCall() or
            self.peekRegexpInstrFunctionCall() or
            self.peekTranslateFunctionCall() or self.peekKeyword("concat") or self.peekKeyword("concat_ws") or self.peekKeyword("coalesce") or self.peekKeyword("nullif") or self.peekTextLengthFunctionKeyword() or
            self.peekAsciiFunctionCall() or
            self.peekChrFunctionCall() or
            self.peekSubstringFunctionKeyword() or
            self.peekOverlayFunctionCall() or
            self.peekSplitPartFunctionKeyword() or
            self.peekStrposFunctionKeyword() or
            self.peekLeftRightFunctionCall() or
            self.peekPadFunctionCall() or
            self.peekRepeatFunctionCall() or
            self.peekReverseFunctionCall() or
            self.peekMd5FunctionCall() or
            self.peekStartsWithFunctionCall() or
            self.peekEndsWithFunctionCall() or
            self.peekDateTruncFunctionCall() or
            self.peekDateBinFunctionCall() or
            self.peekDatePartFunctionCall() or
            self.peekTrimVariantFunctionCall() or
            self.peekKeyword("position") or self.peekKeyword("abs") or self.peekKeyword("round") or self.peekFunctionCall("trunc") or self.peekFunctionCall("floor") or self.peekFunctionCall("ceil") or self.peekFunctionCall("sqrt") or self.peekFunctionCall("sign") or self.peekFunctionCall("mod") or self.peekFunctionCall("power") or self.peekKeyword("case") or self.peekKeyword("cast")) return false;
        if (self.pos + 1 >= self.tokens.len) return true;
        return switch (self.tokens[self.pos + 1].kind) {
            .plus, .minus, .star, .slash, .percent, .lparen, .arrow_json, .arrow_text, .path_arrow_json, .path_arrow_text, .pipe_concat => false,
            else => true,
        };
    }

    fn nextRowExpressionHasTopLevelPipeConcat(self: *@This()) bool {
        var depth: usize = 0;
        var i = self.pos;
        while (i < self.tokens.len) : (i += 1) {
            const token = self.tokens[i];
            switch (token.kind) {
                .lparen => depth += 1,
                .rparen => {
                    if (depth == 0) return false;
                    depth -= 1;
                },
                .pipe_concat => if (depth == 0) return true,
                .comma, .semicolon, .eq, .neq, .lt, .lte, .gt, .gte, .at_contains, .range_overlap, .question, .arrow_json, .arrow_text, .path_arrow_json, .path_arrow_text, .regex_match, .regex_imatch, .regex_not_match, .regex_not_imatch => if (depth == 0) return false,
                .identifier => if (depth == 0 and rowExpressionBoundaryKeyword(token.text)) return false,
                else => {},
            }
        }
        return false;
    }

    fn insertBodyJsonAlloc(self: *@This(), columns: []const []const u8, rows: InsertValueRows, conflicts: []const ConflictClause, returning: ReturningProjection) ![]u8 {
        if (rows.len == 0) return error.UnsupportedSqlShape;
        if (conflicts.len != 0 and conflicts.len != rows.len) return error.UnsupportedSqlShape;
        var out: std.Io.Writer.Allocating = .init(self.alloc);
        errdefer out.deinit();
        const writer = &out.writer;
        try writer.writeAll("{\"operations\":[");
        for (rows, 0..) |values, row_i| {
            if (values.len != columns.len) return error.UnsupportedSqlShape;
            if (row_i != 0) try writer.writeByte(',');
            try writer.writeAll("{\"op\":\"insert\",\"row\":{");
            for (columns, values, 0..) |column, value_json, i| {
                if (i != 0) try writer.writeByte(',');
                try writer.print("{f}:", .{std.json.fmt(column, .{})});
                try writer.writeAll(value_json);
            }
            try writer.writeByte('}');
            if (conflicts.len != 0) {
                const clause = conflicts[row_i];
                try writer.writeAll(",\"on_conflict\":{\"target\":");
                try self.writeConflictTargetJson(writer, clause.target);
                try writer.print(",\"action\":{f}", .{std.json.fmt(conflictActionToken(clause.action), .{})});
                if (clause.patch.len > 0) {
                    try writer.writeAll(",\"patch\":{");
                    for (clause.patch, 0..) |item, i| {
                        if (i != 0) try writer.writeByte(',');
                        try writer.print("{f}:", .{std.json.fmt(item.field, .{})});
                        try writer.writeAll(item.value_json);
                    }
                    try writer.writeByte('}');
                }
                if (clause.patch_expr.len > 0) {
                    try writer.writeAll(",\"patch_expr\":{");
                    for (clause.patch_expr, 0..) |item, i| {
                        if (i != 0) try writer.writeByte(',');
                        try writer.print("{f}:", .{std.json.fmt(item.field, .{})});
                        try writeRowExpressionJson(writer, item.expression);
                    }
                    try writer.writeByte('}');
                }
                if (clause.increment.len > 0) {
                    try writer.writeAll(",\"increment\":{");
                    for (clause.increment, 0..) |item, i| {
                        if (i != 0) try writer.writeByte(',');
                        try writer.print("{f}:", .{std.json.fmt(item.field, .{})});
                        try writer.writeAll(item.value_json);
                    }
                    try writer.writeByte('}');
                }
                if (clause.increment_expr.len > 0) {
                    try writer.writeAll(",\"increment_expr\":{");
                    for (clause.increment_expr, 0..) |item, i| {
                        if (i != 0) try writer.writeByte(',');
                        try writer.print("{f}:", .{std.json.fmt(item.field, .{})});
                        try writeRowExpressionJson(writer, item.expression);
                    }
                    try writer.writeByte('}');
                }
                if (clause.json_set.len > 0) {
                    try writeJsonSetValuesJson(writer, clause.json_set);
                }
                if (clause.array_update.len > 0) {
                    try writer.writeAll(",\"array_update\":[");
                    for (clause.array_update, 0..) |item, i| {
                        if (i != 0) try writer.writeByte(',');
                        try writer.print("{{\"field\":{f},\"op\":{f},\"value\":", .{
                            std.json.fmt(item.field, .{}),
                            std.json.fmt(arrayTransformOpToken(item.op), .{}),
                        });
                        try writer.writeAll(item.value_json);
                        try writer.writeByte('}');
                    }
                    try writer.writeByte(']');
                }
                if (clause.where_expression) |condition| {
                    try writer.writeAll(",\"where_expression\":");
                    try writeRowExpressionConditionJson(writer, condition);
                }
                if (clause.where_expressions.len > 0) {
                    try writer.writeAll(",\"where_expressions\":[");
                    for (clause.where_expressions, 0..) |condition, i| {
                        if (i != 0) try writer.writeByte(',');
                        try writeRowExpressionConditionJson(writer, condition);
                    }
                    try writer.writeByte(']');
                }
                if (clause.where_any.len > 0) {
                    try writer.writeByte(',');
                    try writeRowExpressionPredicateGroupsJson(writer, "where_any", clause.where_any);
                }
                if (clause.where_not.len > 0) {
                    try writer.writeByte(',');
                    try writeRowExpressionPredicateGroupsJson(writer, "where_not", clause.where_not);
                }
                try writer.writeByte('}');
            }
            try self.writeReturningProjectionJson(writer, returning);
            try writer.writeByte('}');
        }
        try writer.writeAll("]}");
        return try out.toOwnedSlice();
    }

    fn writeConflictTargetJson(self: *@This(), writer: *std.Io.Writer, target: ConflictTarget) !void {
        _ = self;
        switch (target) {
            .primary => try writer.writeAll("{\"primary\":true}"),
            .unique => |unique| {
                try writer.print("{{\"unique\":{{\"name\":{f}", .{std.json.fmt(unique.name, .{})});
                if (unique.where_json.len > 0) {
                    try writer.writeAll(",\"where\":");
                    try writer.writeAll(unique.where_json);
                }
                if (unique.where_expressions.len > 0) {
                    try writer.writeAll(",\"where_expressions\":[");
                    for (unique.where_expressions, 0..) |condition, i| {
                        if (i != 0) try writer.writeByte(',');
                        try writeRowExpressionConditionJson(writer, condition);
                    }
                    try writer.writeByte(']');
                }
                try writer.writeAll("}}");
            },
        }
    }

    fn parseU32Value(self: *@This()) !u32 {
        if (self.match(.number)) |token| {
            return try std.fmt.parseInt(u32, token.text, 10);
        }
        if (self.match(.placeholder)) |token| {
            const value = try self.boundValue(token);
            return try value.asU32();
        }
        return error.UnsupportedSqlShape;
    }

    fn parseNullableU32Value(self: *@This()) !?u32 {
        if (self.matchKeyword("null")) return null;
        if (self.match(.number)) |token| {
            return try std.fmt.parseInt(u32, token.text, 10);
        }
        if (self.match(.placeholder)) |token| {
            const value = try self.boundValue(token);
            return switch (value) {
                .null => null,
                else => try value.asU32(),
            };
        }
        return error.UnsupportedSqlShape;
    }

    fn parseLimitValue(self: *@This()) !?u32 {
        if (self.matchKeyword("all")) return null;
        return try self.parseNullableU32Value();
    }

    fn parseOffsetValue(self: *@This()) !u32 {
        const offset = (try self.parseNullableU32Value()) orelse 0;
        _ = self.matchKeyword("row") or self.matchKeyword("rows");
        return offset;
    }

    fn parseFetchLimitValue(self: *@This()) !?u32 {
        if (!(self.matchKeyword("first") or self.matchKeyword("next"))) return error.UnsupportedSqlShape;
        const limit: ?u32 = if (self.peekKeyword("row") or self.peekKeyword("rows"))
            1
        else
            try self.parseLimitValue();
        if (!(self.matchKeyword("row") or self.matchKeyword("rows"))) return error.UnsupportedSqlShape;
        try self.expectKeyword("only");
        return limit;
    }

    fn parseForRowClaimClause(self: *@This(), allowed_targets: []const []const u8) !SqlRowClaimClause {
        const mode: db_mod.types.RowClaimMode = if (self.matchKeyword("no")) blk: {
            try self.expectKeyword("key");
            try self.expectKeyword("update");
            break :blk .for_no_key_update;
        } else blk: {
            try self.expectKeyword("update");
            break :blk .for_update;
        };
        if (self.matchKeyword("of")) {
            while (true) {
                const target = try self.parseSqlTableReferenceIdentifierOwned();
                defer self.alloc.free(target);
                if (!self.rowClaimTargetAllowed(target, allowed_targets)) return error.UnsupportedSqlShape;
                if (self.match(.comma) == null) break;
            }
        }
        if (self.matchKeyword("skip")) {
            try self.expectKeyword("locked");
            return .{ .mode = mode, .wait_policy = .skip_locked };
        }
        if (self.matchKeyword("nowait")) {
            return .{ .mode = mode, .wait_policy = .nowait };
        }
        return .{ .mode = mode, .wait_policy = .wait };
    }

    fn rowClaimTargetAllowed(self: *@This(), target: []const u8, allowed_targets: []const []const u8) bool {
        for (allowed_targets) |allowed| {
            if (allowed.len > 0 and std.mem.eql(u8, target, allowed)) return true;
        }
        const normalized = normalizeSqlObjectIdentifierAlloc(self.alloc, target) catch return false;
        defer self.alloc.free(normalized);
        for (allowed_targets) |allowed| {
            if (allowed.len > 0 and std.mem.eql(u8, normalized, allowed)) return true;
        }
        return false;
    }

    fn parseSelectItem(self: *@This()) !SelectItem {
        if (self.nextRowExpressionHasTopLevelPipeConcat()) return .{ .expression = try self.parseTextExpressionProjectionAlloc() };
        if (self.peekKind(.minus)) return .{ .expression = try self.parseGenericExpressionProjectionAlloc() };
        if (self.peekKeyword("not")) return .{ .expression = try self.parseBooleanExpressionProjectionAlloc() };
        if (self.peekUuidV4FunctionCall()) return .{ .expression = try self.parseUuidV4ExpressionProjectionAlloc() };
        if (self.peekKeyword("now") or self.peekKeyword("current_timestamp")) return .{ .expression = try self.parseNowExpressionProjectionAlloc() };
        if (self.peekKeyword("current_date")) return .{ .expression = try self.parseCurrentDateExpressionProjectionAlloc() };
        if (self.peekSqlTypedDatetimeLiteral()) return .{ .expression = try self.parseTypedDatetimeLiteralExpressionProjectionAlloc() };
        if (self.peekJsonExtractPathFunctionCall()) return .{ .expression = try self.parseJsonExtractPathExpressionProjectionAlloc() };
        if (self.peekJsonTypeofFunctionCall()) return .{ .expression = try self.parseJsonTypeofExpressionProjectionAlloc() };
        if (self.peekJsonArrayLengthFunctionCall()) return .{ .expression = try self.parseJsonArrayLengthExpressionProjectionAlloc() };
        if (self.peekJsonBuildObjectFunctionCall()) return .{ .expression = try self.parseJsonBuildObjectExpressionProjectionAlloc() };
        if (self.peekKeyword("convert_from")) return .{ .expression = try self.parseJsonValueExpressionProjectionAlloc("convert_from") };
        if (self.peekKeyword("to_jsonb")) return .{ .expression = try self.parseToJsonbExpressionProjectionAlloc() };
        if (self.peekArrayLengthFunctionCall()) return .{ .expression = try self.parseArrayLengthExpressionProjectionAlloc() };
        if (self.peekArrayPositionFunctionCall()) return .{ .expression = try self.parseArrayPositionExpressionProjectionAlloc() };
        if (self.peekKeyword("array_append") or self.peekKeyword("array_prepend") or self.peekKeyword("array_cat") or self.peekKeyword("array_remove") or self.peekKeyword("array_replace")) return .{ .expression = try self.parseArrayElementTransformExpressionProjectionAlloc() };
        if (self.peekKeyword("array_to_string")) return .{ .expression = try self.parseArrayToStringExpressionProjectionAlloc() };
        if (self.peekKeyword("string_to_array")) return .{ .expression = try self.parseStringToArrayExpressionProjectionAlloc() };
        if (self.peekKeyword("coalesce")) return .{ .expression = try self.parseCoalesceExpressionProjectionAlloc() };
        if (self.peekKeyword("lower") or self.peekKeyword("upper") or self.peekInitcapFunctionCall() or self.peekKeyword("trim") or self.peekTrimVariantFunctionCall()) return .{ .expression = try self.parseCaseFoldExpressionProjectionAlloc() };
        if (self.peekKeyword("replace")) return .{ .expression = try self.parseReplaceExpressionProjectionAlloc() };
        if (self.peekKeyword("regexp_replace")) return .{ .expression = try self.parseRegexpReplaceExpressionProjectionAlloc() };
        if (self.peekRegexpSubstrFunctionCall()) return .{ .expression = try self.parseRegexpSubstrExpressionProjectionAlloc() };
        if (self.peekRegexpMatchFunctionCall()) return .{ .expression = try self.parseRegexpMatchExpressionProjectionAlloc() };
        if (self.peekRegexpCountFunctionCall()) return .{ .expression = try self.parseRegexpCountExpressionProjectionAlloc() };
        if (self.peekRegexpInstrFunctionCall()) return .{ .expression = try self.parseRegexpInstrExpressionProjectionAlloc() };
        if (self.peekTranslateFunctionCall()) return .{ .expression = try self.parseTranslateExpressionProjectionAlloc() };
        if (self.peekKeyword("concat") or self.peekKeyword("concat_ws")) return .{ .expression = try self.parseConcatExpressionProjectionAlloc() };
        if (self.peekKeyword("nullif")) return .{ .expression = try self.parseNullifExpressionProjectionAlloc() };
        if (self.peekTextLengthFunctionKeyword()) return .{ .expression = try self.parseLengthExpressionProjectionAlloc() };
        if (self.peekAsciiFunctionCall()) return .{ .expression = try self.parseAsciiExpressionProjectionAlloc() };
        if (self.peekChrFunctionCall()) return .{ .expression = try self.parseChrExpressionProjectionAlloc() };
        if (self.peekSubstringFunctionKeyword()) return .{ .expression = try self.parseSubstringExpressionProjectionAlloc() };
        if (self.peekOverlayFunctionCall()) return .{ .expression = try self.parseOverlayExpressionProjectionAlloc() };
        if (self.peekSplitPartFunctionKeyword()) return .{ .expression = try self.parseSplitPartExpressionProjectionAlloc() };
        if (self.peekStrposFunctionKeyword() or self.peekKeyword("position")) return .{ .expression = try self.parseStrposExpressionProjectionAlloc() };
        if (self.peekLeftRightFunctionCall()) return .{ .expression = try self.parseLeftRightExpressionProjectionAlloc() };
        if (self.peekPadFunctionCall()) return .{ .expression = try self.parsePadExpressionProjectionAlloc() };
        if (self.peekRepeatFunctionCall()) return .{ .expression = try self.parseRepeatExpressionProjectionAlloc() };
        if (self.peekReverseFunctionCall()) return .{ .expression = try self.parseReverseExpressionProjectionAlloc() };
        if (self.peekMd5FunctionCall()) return .{ .expression = try self.parseMd5ExpressionProjectionAlloc() };
        if (self.peekStartsWithFunctionCall()) return .{ .expression = try self.parseStartsWithExpressionProjectionAlloc() };
        if (self.peekEndsWithFunctionCall()) return .{ .expression = try self.parseEndsWithExpressionProjectionAlloc() };
        if (self.peekDateTruncFunctionCall()) return .{ .expression = try self.parseDateTruncExpressionProjectionAlloc() };
        if (self.peekDateBinFunctionCall()) return .{ .expression = try self.parseDateBinExpressionProjectionAlloc() };
        if (self.peekDatePartFunctionCall()) return .{ .expression = try self.parseDatePartExpressionProjectionAlloc() };
        if (self.peekKeyword("abs")) return .{ .expression = try self.parseAbsExpressionProjectionAlloc() };
        if (self.peekKeyword("round")) return .{ .expression = try self.parseRoundExpressionProjectionAlloc() };
        if (self.peekFunctionCall("trunc")) return .{ .expression = try self.parseFloorCeilExpressionProjectionAlloc(.trunc) };
        if (self.peekFunctionCall("floor")) return .{ .expression = try self.parseFloorCeilExpressionProjectionAlloc(.floor) };
        if (self.peekFunctionCall("ceil")) return .{ .expression = try self.parseFloorCeilExpressionProjectionAlloc(.ceil) };
        if (self.peekFunctionCall("sqrt")) return .{ .expression = try self.parseFloorCeilExpressionProjectionAlloc(.sqrt) };
        if (self.peekFunctionCall("sign")) return .{ .expression = try self.parseFloorCeilExpressionProjectionAlloc(.sign) };
        if (self.peekFunctionCall("mod")) return .{ .expression = try self.parseModuloExpressionProjectionAlloc() };
        if (self.peekFunctionCall("power")) return .{ .expression = try self.parsePowerExpressionProjectionAlloc() };
        if (self.peekKeyword("greatest") or self.peekKeyword("least")) return .{ .expression = try self.parseGreatestLeastExpressionProjectionAlloc() };
        if (self.peekKeyword("case")) return .{ .expression = try self.parseCaseExpressionProjectionAlloc() };
        if (self.peekKeyword("cast")) return .{ .expression = try self.parseCastExpressionProjectionAlloc() };
        if (self.peekKind(.lparen)) {
            if (self.peekParenthesizedNullTestProjection()) {
                return .{ .expression = try self.parseParenthesizedNullTestExpressionProjectionAlloc() };
            }
            return .{ .expression = try self.parseParenthesizedExpressionProjectionAlloc() };
        }

        const parsed_field = try self.parseFieldExpressionOwned();
        defer self.alloc.free(parsed_field);
        const field = try self.normalizeRowExpressionFieldAlloc(parsed_field);
        var field_owned = true;
        errdefer if (field_owned) self.alloc.free(field);
        if (self.peekKind(.lparen)) return error.UnsupportedSqlShape;
        if (self.matchJsonExtractOperator()) |operator| {
            const as_text = tokenKindIsJsonExtractTextOperator(operator);
            if (relationalColumnForField(self.schema, field, .json) == null) return error.InvalidSqlCatalog;
            const path = try self.parseJsonExtractOperatorPathOwned(operator);
            var path_owned = true;
            errdefer if (path_owned) self.alloc.free(path);
            const output = if (self.matchKeyword("as"))
                try self.parseIdentifierOwned()
            else
                try self.alloc.dupe(u8, path);
            var output_owned = true;
            errdefer if (output_owned) self.alloc.free(output);
            const operands = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
            var operands_owned = true;
            errdefer if (operands_owned) self.alloc.free(operands);
            operands[0] = .{ .kind = .field, .field = field, .field_source = self.rowExpressionFieldSource() };
            field_owned = false;
            path_owned = false;
            output_owned = false;
            operands_owned = false;
            return .{ .expression = .{
                .output = output,
                .expression = .{
                    .kind = .json_extract,
                    .json_path = path,
                    .json_as_text = as_text,
                    .operands = operands,
                },
            } };
        }
        if (self.match(.question) != null) {
            if (relationalColumnForField(self.schema, field, .json) == null) return error.InvalidSqlCatalog;
            const path = try self.parseJsonExistencePathOwned();
            var path_owned = true;
            errdefer if (path_owned) self.alloc.free(path);
            const output = if (self.matchKeyword("as"))
                try self.parseIdentifierOwned()
            else
                try self.alloc.dupe(u8, path);
            var output_owned = true;
            errdefer if (output_owned) self.alloc.free(output);
            const operands = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
            var operands_owned = true;
            errdefer if (operands_owned) self.alloc.free(operands);
            operands[0] = .{ .kind = .field, .field = field, .field_source = self.rowExpressionFieldSource() };
            field_owned = false;
            path_owned = false;
            output_owned = false;
            operands_owned = false;
            return .{ .expression = .{
                .output = output,
                .expression = .{
                    .kind = .json_path_exists,
                    .json_path = path,
                    .operands = operands,
                },
            } };
        }
        if (self.match(.question_any) != null or self.match(.question_all) != null) {
            const match_all = self.tokens[self.pos - 1].kind == .question_all;
            if (relationalColumnForField(self.schema, field, .json) == null) return error.InvalidSqlCatalog;
            const expression = try self.parseJsonKeySetExistsExpressionAlloc(field, self.rowExpressionFieldSource(), match_all);
            var expression_transferred = false;
            errdefer if (!expression_transferred) freeExpression(self.alloc, expression);
            const output = if (self.matchKeyword("as"))
                try self.parseIdentifierOwned()
            else
                try self.alloc.dupe(u8, if (match_all) "json_keys_all" else "json_keys_any");
            var output_owned = true;
            errdefer if (output_owned) self.alloc.free(output);
            expression_transferred = true;
            output_owned = false;
            self.alloc.free(field);
            field_owned = false;
            return .{ .expression = .{
                .output = output,
                .expression = expression,
            } };
        }
        const column = relationalColumnForField(self.schema, field, null) orelse return error.InvalidSqlCatalog;
        if (self.peekArithmeticOperator()) |_| {
            if (column.field_type != .numeric and column.field_type != .datetime) return error.InvalidSqlCatalog;
            field_owned = false;
            return .{ .expression = try self.parseArithmeticExpressionProjectionFromFieldAlloc(field) };
        }
        if (self.peekBooleanOperator()) |_| {
            if (column.field_type != .boolean) return error.InvalidSqlCatalog;
            field_owned = false;
            return .{ .expression = try self.parseBooleanExpressionProjectionFromFieldAlloc(field) };
        }
        const alias = try self.parseOptionalProjectionAliasAlloc();
        var alias_transferred = false;
        errdefer if (!alias_transferred) if (alias) |owned| self.alloc.free(owned);
        if (alias) |output| {
            if (!std.mem.eql(u8, output, field)) {
                alias_transferred = true;
                field_owned = false;
                return .{ .expression = .{
                    .output = output,
                    .expression = .{
                        .kind = .field,
                        .field = field,
                        .field_source = self.rowExpressionFieldSource(),
                    },
                } };
            }
            self.alloc.free(output);
            alias_transferred = true;
        }
        field_owned = false;
        return .{ .field = field };
    }

    fn parseTextExpressionProjectionAlloc(self: *@This()) !db_mod.types.RelationalRowsExpressionProjection {
        const expression = try self.parseRowExpressionAlloc();
        var expression_transferred = false;
        errdefer if (!expression_transferred) freeExpression(self.alloc, expression);
        try self.validateTextRowExpression(expression);
