    fn parseBooleanExpressionRestAlloc(
        self: *@This(),
        lhs: db_mod.types.RelationalRowsExpression,
        min_precedence: u8,
    ) anyerror!db_mod.types.RelationalRowsExpression {
        try self.validateBooleanRowExpression(lhs);
        var current = lhs;
        var current_owned = true;
        errdefer if (current_owned) freeExpression(self.alloc, current);

        while (self.peekBooleanOperator()) |op| {
            if (op.precedence < min_precedence) break;
            if (!self.matchKeyword(op.keyword)) unreachable;
            var rhs = try self.parseRowExpressionOperandAlloc();
            var rhs_owned = true;
            errdefer if (rhs_owned) freeExpression(self.alloc, rhs);
            try self.validateBooleanRowExpression(rhs);

            while (self.peekBooleanOperator()) |next_op| {
                if (next_op.precedence <= op.precedence) break;
                rhs_owned = false;
                rhs = try self.parseBooleanExpressionRestAlloc(rhs, next_op.precedence);
                rhs_owned = true;
            }

            const operands = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 2);
            var operands_owned = true;
            errdefer if (operands_owned) self.alloc.free(operands);
            operands[0] = current;
            operands[1] = rhs;
            current_owned = false;
            rhs_owned = false;
            operands_owned = false;
            current = .{
                .kind = op.kind,
                .operands = operands,
            };
            current_owned = true;
        }

        current_owned = false;
        return current;
    }

