    }

    fn parseBooleanNotRowExpressionAlloc(self: *@This()) anyerror!db_mod.types.RelationalRowsExpression {
        try self.expectKeyword("not");
        const operand = if (self.peekKind(.lparen))
            try self.parseParenthesizedBooleanRowExpressionAlloc()
        else
            try self.parseRowExpressionOperandAlloc();
        var operand_transferred = false;
        errdefer if (!operand_transferred) freeExpression(self.alloc, operand);
        try self.validateBooleanRowExpression(operand);

        const operands = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
        var operands_transferred = false;
        errdefer if (!operands_transferred) self.alloc.free(operands);
        operands[0] = operand;
        operand_transferred = true;
        operands_transferred = true;
        return .{
            .kind = .bool_not,
            .operands = operands,
        };
    }

    fn parseJsonKeySetExistsExpressionAlloc(
        self: *@This(),
        field: []const u8,
        source: db_mod.types.RelationalRowsExpressionFieldSource,
        match_all: bool,
    ) !db_mod.types.RelationalRowsExpression {
        const values_json = try self.parseJsonArrayValueAlloc();
        defer self.alloc.free(values_json);
        var parsed = std.json.parseFromSlice(std.json.Value, self.alloc, values_json, .{}) catch return error.UnsupportedSqlShape;
        defer parsed.deinit();
        if (parsed.value != .array or parsed.value.array.items.len == 0 or parsed.value.array.items.len > max_scalar_or_expanded_branches) return error.UnsupportedSqlShape;

        var operands = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpression).empty;
        var operands_transferred = false;
        errdefer {
            if (!operands_transferred) {
                for (operands.items) |operand| freeExpression(self.alloc, operand);
                operands.deinit(self.alloc);
            }
        }

        for (parsed.value.array.items) |value| {
            if (value != .string or value.string.len == 0 or std.mem.indexOfScalar(u8, value.string, '.') != null) return error.UnsupportedSqlShape;
            const owned_field = try self.alloc.dupe(u8, field);
            var field_transferred = false;
            errdefer if (!field_transferred) self.alloc.free(owned_field);
            const owned_path = try self.alloc.dupe(u8, value.string);
            var path_transferred = false;
            errdefer if (!path_transferred) self.alloc.free(owned_path);
            const exists_operands = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
            var exists_operands_transferred = false;
            errdefer if (!exists_operands_transferred) self.alloc.free(exists_operands);
            exists_operands[0] = .{ .kind = .field, .field = owned_field, .field_source = source };
            field_transferred = true;
            path_transferred = true;
            exists_operands_transferred = true;
            try operands.append(self.alloc, .{
                .kind = .json_path_exists,
                .json_path = owned_path,
                .operands = exists_operands,
            });
        }

        if (operands.items.len == 1) {
            const out = operands.items[0];
            operands.clearRetainingCapacity();
            operands.deinit(self.alloc);
            operands_transferred = true;
            return out;
        }

        const owned_operands = try operands.toOwnedSlice(self.alloc);
        operands = .empty;
        operands_transferred = true;
        return .{
            .kind = if (match_all) .bool_and else .bool_or,
            .operands = owned_operands,
        };
    }

    fn normalizeRowExpressionFieldAlloc(self: *@This(), field: []const u8) ![]const u8 {
        const qualifiers = if (self.field_expression_qualifiers.len != 0)
            self.field_expression_qualifiers
        else
            self.returning_expression_qualifiers;
        if (qualifiers.len == 0) {
            return try self.alloc.dupe(u8, field);
        }
        return try self.normalizeReturningFieldAlloc(field, qualifiers);
    }

    fn normalizePeriodReferenceAlloc(self: *@This(), field: []const u8) !?[]const u8 {
        if (relationalPeriodForDdl(self.schema.periods, field) != null) {
            return try self.alloc.dupe(u8, field);
        }
        const qualifiers = if (self.field_expression_qualifiers.len != 0)
            self.field_expression_qualifiers
        else
            self.returning_expression_qualifiers;
        if (qualifiers.len == 0) return null;
        var dot: ?usize = std.mem.indexOfScalar(u8, field, '.');
        while (dot) |index| {
            if (index > 0 and index + 1 < field.len) {
                const qualifier = field[0..index];
                const unqualified_field = field[index + 1 ..];
                if (relationalPeriodForDdl(self.schema.periods, unqualified_field) != null and try self.returningQualifierMatches(qualifier, qualifiers)) {
                    return try self.alloc.dupe(u8, unqualified_field);
                }
            }
            dot = std.mem.indexOfScalarPos(u8, field, index + 1, '.');
        }
        return null;
    }

    const ResolvedRowExpressionField = struct {
        field: []const u8,
        source: db_mod.types.RelationalRowsExpressionFieldSource,
        schema: runtime_schema.TableSchema,
    };

    fn resolveRowExpressionFieldAlloc(self: *@This(), field: []const u8) !ResolvedRowExpressionField {
        if (self.joined_source_expression_qualifiers.len != 0) {
            if (try self.normalizeQualifiedRowExpressionFieldAlloc(field, self.joined_source_expression_qualifiers, self.joined_source_schema orelse self.schema)) |source_field| {
                return .{
                    .field = source_field,
                    .source = .source,
                    .schema = self.joined_source_schema orelse self.schema,
                };
            }
        }
        if (self.joined_target_expression_qualifiers.len != 0) {
            if (try self.normalizeQualifiedRowExpressionFieldAlloc(field, self.joined_target_expression_qualifiers, self.schema)) |target_field| {
                return .{
                    .field = target_field,
                    .source = .row,
                    .schema = self.schema,
                };
            }
        }
        return .{
            .field = try self.normalizeRowExpressionFieldAlloc(field),
            .source = self.rowExpressionFieldSource(),
            .schema = if (self.rowExpressionFieldSource() == .source) self.joined_source_schema orelse self.schema else self.schema,
        };
    }

    fn normalizeQualifiedRowExpressionFieldAlloc(
        self: *@This(),
        field: []const u8,
        qualifiers: []const []const u8,
        schema: runtime_schema.TableSchema,
    ) !?[]const u8 {
        var dot: ?usize = std.mem.indexOfScalar(u8, field, '.');
        while (dot) |index| {
            if (index > 0 and index + 1 < field.len) {
                const qualifier = field[0..index];
                const unqualified_field = field[index + 1 ..];
                if (try self.returningQualifierMatches(qualifier, qualifiers)) {
                    if (relationalColumnForReturningField(schema, unqualified_field) == null) return error.InvalidSqlCatalog;
                    return try self.alloc.dupe(u8, unqualified_field);
                }
            }
            dot = std.mem.indexOfScalarPos(u8, field, index + 1, '.');
        }
        return null;
    }

    fn rowExpressionFieldSource(self: *@This()) db_mod.types.RelationalRowsExpressionFieldSource {
        return self.row_expression_field_source_override orelse .row;
    }

    fn parseParenthesizedRowExpressionAlloc(self: *@This()) anyerror!db_mod.types.RelationalRowsExpression {
        try self.expect(.lparen);
        const expression = try self.parseBooleanRowExpressionAlloc();
        var expression_transferred = false;
        errdefer if (!expression_transferred) freeExpression(self.alloc, expression);
        try self.expect(.rparen);
        expression_transferred = true;
        return expression;
    }

    fn parseParenthesizedBooleanRowExpressionAlloc(self: *@This()) anyerror!db_mod.types.RelationalRowsExpression {
        try self.expect(.lparen);
        const expression = try self.parseBooleanRowExpressionAlloc();
        var expression_transferred = false;
        errdefer if (!expression_transferred) freeExpression(self.alloc, expression);
        try self.expect(.rparen);
        expression_transferred = true;
        return expression;
    }

    fn parseUnaryNegativeRowExpressionAlloc(self: *@This()) anyerror!db_mod.types.RelationalRowsExpression {
        _ = self.match(.minus) orelse return error.UnsupportedSqlShape;
        if (self.match(.number)) |token| {
            return .{
                .kind = .value,
                .value_json = try std.fmt.allocPrint(self.alloc, "-{s}", .{token.text}),
            };
        }

        const operand = try self.parseRowExpressionOperandAlloc();
        var operand_transferred = false;
        errdefer if (!operand_transferred) freeExpression(self.alloc, operand);
        const negative_one = try self.alloc.dupe(u8, "-1");
        var negative_one_transferred = false;
        errdefer if (!negative_one_transferred) self.alloc.free(negative_one);
        const operands = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 2);
        var operands_transferred = false;
        errdefer if (!operands_transferred) self.alloc.free(operands);
        operands[0] = .{ .kind = .value, .value_json = negative_one };
        operands[1] = operand;
        negative_one_transferred = true;
        operand_transferred = true;
        operands_transferred = true;
        return .{
            .kind = .mul,
            .operands = operands,
        };
    }

    fn parseNowRowExpressionAlloc(self: *@This()) !db_mod.types.RelationalRowsExpression {
        if (self.matchKeyword("now")) {
            try self.expect(.lparen);
            try self.expect(.rparen);
        } else if (self.matchKeyword("current_timestamp")) {
            try self.parseOptionalCurrentTimestampPrecision();
        } else {
            return error.UnsupportedSqlShape;
        }
        return try self.buildNowRowExpressionAlloc();
    }

    fn buildNowRowExpressionAlloc(self: *@This()) !db_mod.types.RelationalRowsExpression {
        return .{
            .kind = .now,
            .value_json = try std.fmt.allocPrint(self.alloc, "{d}", .{platform_time.realtimeNs()}),
        };
    }

    fn parseCurrentDateRowExpressionAlloc(self: *@This()) !db_mod.types.RelationalRowsExpression {
        try self.expectKeyword("current_date");
        const operands = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 2);
        var initialized: usize = 0;
        errdefer {
            for (operands[0..initialized]) |operand| freeExpression(self.alloc, operand);
            self.alloc.free(operands);
        }

        operands[0] = .{
            .kind = .value,
            .value_json = try std.json.Stringify.valueAlloc(self.alloc, "day", .{}),
        };
        initialized += 1;
        operands[1] = try self.buildNowRowExpressionAlloc();
        initialized += 1;

        return .{
            .kind = .date_trunc,
            .operands = operands,
        };
    }

    fn parseSqlTypedDatetimeLiteralRowExpressionAlloc(self: *@This()) !db_mod.types.RelationalRowsExpression {
        return .{
            .kind = .value,
            .value_json = try self.parseSqlTypedDatetimeLiteralValueJsonAlloc(),
        };
    }

    fn parseUuidV4RowExpressionAlloc(self: *@This()) !db_mod.types.RelationalRowsExpression {
        _ = self.matchKeyword("gen_random_uuid") or self.matchKeyword("uuid_generate_v4") or return error.UnsupportedSqlShape;
        try self.expect(.lparen);
        try self.expect(.rparen);
        return .{ .kind = .uuid_v4 };
    }

    fn parseIntervalRowExpressionAlloc(self: *@This()) !db_mod.types.RelationalRowsExpression {
        const interval = try self.parseSqlIntervalLiteral();
        return try self.buildSingleIntervalLiteralExpressionAlloc(interval);
    }

    fn parseSqlIntervalLiteral(self: *@This()) !SqlIntervalLiteral {
        try self.expectKeyword("interval");
        const token = self.match(.string) orelse return error.UnsupportedSqlShape;
        return try sqlIntervalLiteral(token.text);
    }

    fn buildSingleIntervalLiteralExpressionAlloc(
        self: *@This(),
        interval: SqlIntervalLiteral,
    ) !db_mod.types.RelationalRowsExpression {
        const has_calendar = interval.calendar_months != 0 or (interval.saw_calendar and interval.fixed_ns == 0);
        const has_fixed = interval.fixed_ns != 0 or (interval.saw_fixed and !has_calendar);
        if (has_calendar and has_fixed) return error.UnsupportedSqlShape;
        if (has_calendar) return try self.buildIntervalComponentExpressionAlloc(.interval_months, interval.calendar_months);
        if (has_fixed) return try self.buildIntervalComponentExpressionAlloc(.interval_ns, interval.fixed_ns);
        return error.UnsupportedSqlShape;
    }

    fn buildIntervalComponentExpressionAlloc(
        self: *@This(),
        kind: db_mod.types.RelationalRowsExpressionKind,
        value: u64,
    ) !db_mod.types.RelationalRowsExpression {
        if (kind != .interval_ns and kind != .interval_months) return error.UnsupportedSqlShape;
        const value_json = try std.fmt.allocPrint(self.alloc, "{d}", .{value});
        var value_transferred = false;
        errdefer if (!value_transferred) self.alloc.free(value_json);
        const operands = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
        var operands_transferred = false;
        errdefer if (!operands_transferred) self.alloc.free(operands);
        operands[0] = .{ .kind = .value, .value_json = value_json };
        value_transferred = true;
        operands_transferred = true;
        return .{
            .kind = kind,
            .operands = operands,
        };
    }

    fn buildIntervalLiteralArithmeticAlloc(
        self: *@This(),
        lhs: db_mod.types.RelationalRowsExpression,
        op_kind: db_mod.types.RelationalRowsExpressionKind,
        interval: SqlIntervalLiteral,
    ) !db_mod.types.RelationalRowsExpression {
        if (op_kind != .add and op_kind != .sub) return error.UnsupportedSqlShape;

        const has_calendar = interval.calendar_months != 0;
        const has_fixed = interval.fixed_ns != 0;
        if (!has_calendar and !has_fixed) {
            const rhs = try self.buildSingleIntervalLiteralExpressionAlloc(interval);
            var rhs_owned = true;
            errdefer if (rhs_owned) freeExpression(self.alloc, rhs);
            const expression = try self.buildBinaryExpressionAlloc(op_kind, lhs, rhs);
            rhs_owned = false;
            return expression;
        }
        if (has_calendar and !has_fixed) {
            const rhs = try self.buildIntervalComponentExpressionAlloc(.interval_months, interval.calendar_months);
            var rhs_owned = true;
            errdefer if (rhs_owned) freeExpression(self.alloc, rhs);
            const expression = try self.buildBinaryExpressionAlloc(op_kind, lhs, rhs);
            rhs_owned = false;
            return expression;
        }
        if (!has_calendar and has_fixed) {
            const rhs = try self.buildIntervalComponentExpressionAlloc(.interval_ns, interval.fixed_ns);
            var rhs_owned = true;
            errdefer if (rhs_owned) freeExpression(self.alloc, rhs);
            const expression = try self.buildBinaryExpressionAlloc(op_kind, lhs, rhs);
            rhs_owned = false;
            return expression;
        }

        const calendar = try self.buildIntervalComponentExpressionAlloc(.interval_months, interval.calendar_months);
        var calendar_owned = true;
        errdefer if (calendar_owned) freeExpression(self.alloc, calendar);
        const fixed = try self.buildIntervalComponentExpressionAlloc(.interval_ns, interval.fixed_ns);
        var fixed_owned = true;
        errdefer if (fixed_owned) freeExpression(self.alloc, fixed);

        const inner_operands = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 2);
        var inner_operands_owned = true;
        errdefer if (inner_operands_owned) self.alloc.free(inner_operands);
        const outer_operands = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 2);
        var outer_operands_owned = true;
        errdefer if (outer_operands_owned) self.alloc.free(outer_operands);

        inner_operands[0] = lhs;
        inner_operands[1] = calendar;
        calendar_owned = false;
        inner_operands_owned = false;
        outer_operands[0] = .{
            .kind = op_kind,
            .operands = inner_operands,
        };
        outer_operands[1] = fixed;
        fixed_owned = false;
        outer_operands_owned = false;
        return .{
            .kind = op_kind,
            .operands = outer_operands,
        };
    }

    fn buildBinaryExpressionAlloc(
        self: *@This(),
        kind: db_mod.types.RelationalRowsExpressionKind,
        lhs: db_mod.types.RelationalRowsExpression,
        rhs: db_mod.types.RelationalRowsExpression,
    ) !db_mod.types.RelationalRowsExpression {
        const operands = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 2);
        var operands_owned = true;
        errdefer if (operands_owned) self.alloc.free(operands);
        operands[0] = lhs;
        operands[1] = rhs;
        operands_owned = false;
        return .{
            .kind = kind,
            .operands = operands,
        };
    }

    fn parseCastRowExpressionAlloc(self: *@This()) anyerror!db_mod.types.RelationalRowsExpression {
        try self.expectKeyword("cast");
        try self.expect(.lparen);
        const operand = try self.parseRowExpressionAlloc();
        var operand_transferred = false;
        errdefer if (!operand_transferred) freeExpression(self.alloc, operand);
        try self.expectKeyword("as");
        const cast_type = try self.parseExpressionCastType();
        try self.expect(.rparen);

        const operands = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
        var operands_transferred = false;
        errdefer if (!operands_transferred) self.alloc.free(operands);
        operands[0] = operand;

        operand_transferred = true;
        operands_transferred = true;
        return .{
            .kind = .cast,
            .operands = operands,
            .cast_type = cast_type,
        };
    }

    fn parseExpressionCastType(self: *@This()) !db_mod.types.RelationalRowsExpressionCastType {
        const token = self.match(.identifier) orelse return error.UnsupportedSqlShape;
        if (std.ascii.eqlIgnoreCase(token.text, "text")) return .text;
        if (std.ascii.eqlIgnoreCase(token.text, "numeric")) return .numeric;
        if (std.ascii.eqlIgnoreCase(token.text, "bool") or std.ascii.eqlIgnoreCase(token.text, "boolean")) return .bool;
        if (std.ascii.eqlIgnoreCase(token.text, "datetime") or
            std.ascii.eqlIgnoreCase(token.text, "timestamp") or
            std.ascii.eqlIgnoreCase(token.text, "timestamptz") or
            std.ascii.eqlIgnoreCase(token.text, "date")) return .datetime;
        return error.UnsupportedSqlShape;
    }

    fn parseCaseRowExpressionAlloc(self: *@This()) anyerror!db_mod.types.RelationalRowsExpression {
        try self.expectKeyword("case");

        var branches = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCaseBranch).empty;
        errdefer {
            for (branches.items) |branch| freeExpressionCaseBranch(self.alloc, branch);
            branches.deinit(self.alloc);
        }

        while (self.matchKeyword("when")) {
            const condition = try self.parseCaseExpressionConditionAlloc();
            var condition_transferred = false;
            errdefer if (!condition_transferred) freeExpressionCondition(self.alloc, condition);
            try self.expectKeyword("then");
            const then_expression = try self.parseRowExpressionOperandAlloc();
            var then_transferred = false;
            errdefer if (!then_transferred) freeExpression(self.alloc, then_expression);
            try branches.append(self.alloc, .{ .when = condition, .then = then_expression });
            condition_transferred = true;
            then_transferred = true;
        }
        if (branches.items.len == 0) return error.UnsupportedSqlShape;

        try self.expectKeyword("else");
        const else_expression = try self.parseRowExpressionOperandAlloc();
        var else_transferred = false;
        errdefer if (!else_transferred) freeExpression(self.alloc, else_expression);
        try self.expectKeyword("end");

        const owned_branches = try branches.toOwnedSlice(self.alloc);
        var branches_transferred = false;
        errdefer if (!branches_transferred) {
            for (owned_branches) |branch| freeExpressionCaseBranch(self.alloc, branch);
            self.alloc.free(owned_branches);
        };
        const fallback = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
        var fallback_initialized = false;
        var fallback_transferred = false;
        errdefer if (!fallback_transferred) {
            if (fallback_initialized) freeExpression(self.alloc, fallback[0]);
            self.alloc.free(fallback);
        };
        fallback[0] = else_expression;
        fallback_initialized = true;
        else_transferred = true;

        _ = try self.caseExpressionOutputType(owned_branches, fallback);

        branches_transferred = true;
        fallback_transferred = true;
        return .{
            .kind = .case,
            .case_branches = owned_branches,
            .case_else = fallback,
        };
    }

    fn parseCaseExpressionConditionAlloc(self: *@This()) anyerror!db_mod.types.RelationalRowsExpressionCondition {
        const lhs = try self.parseRowExpressionAlloc();
        var lhs_transferred = false;
        errdefer if (!lhs_transferred) freeExpression(self.alloc, lhs);

        const op: runtime_schema.RelationalCheckOp = if (self.matchKeyword("is")) blk: {
            const not = self.matchKeyword("not");
            if (self.matchKeyword("distinct")) {
                try self.expectKeyword("from");
                break :blk if (not) .is_not_distinct else .is_distinct;
            }
            try self.expectKeyword("null");
            break :blk if (not) .is_not_null else .is_null;
        } else try self.parseComparisonOp();

        const rhs = switch (op) {
            .is_null, .is_not_null => &.{},
            else => blk: {
                const out = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
                var out_transferred = false;
                errdefer if (!out_transferred) self.alloc.free(out);
                out[0] = try self.parseRowExpressionAlloc();
                out_transferred = true;
                break :blk out;
            },
        };
        var rhs_transferred = false;
        errdefer if (!rhs_transferred and rhs.len > 0) {
            for (rhs) |expression| freeExpression(self.alloc, expression);
            self.alloc.free(rhs);
        };
        try self.validateExpressionConditionTypes(lhs, op, rhs);

        lhs_transferred = true;
        rhs_transferred = true;
        return .{
            .lhs = lhs,
            .op = op,
            .rhs = rhs,
        };
    }

    fn parseCaseFoldRowExpressionAlloc(self: *@This()) anyerror!db_mod.types.RelationalRowsExpression {
        const kind: db_mod.types.RelationalRowsExpressionKind = if (self.matchKeyword("lower"))
            .lower
        else if (self.matchKeyword("upper"))
            .upper
        else if (self.matchInitcapFunctionKeyword())
            .initcap
        else if (self.matchKeyword("trim"))
            .trim
        else if (self.matchTrimVariantFunctionKind()) |trim_kind|
            trim_kind
        else
            return error.UnsupportedSqlShape;
        try self.expect(.lparen);
        if (try self.parsePeriodBoundRowExpressionAlloc(kind)) |expression| return expression;
        var operands = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpression).empty;
        errdefer {
            for (operands.items) |operand| freeExpression(self.alloc, operand);
            operands.deinit(self.alloc);
        }

        const operand = try self.parseRowExpressionAlloc();
        var operand_transferred = false;
        errdefer if (!operand_transferred) freeExpression(self.alloc, operand);
        try self.validateTextRowExpression(operand);
        try operands.append(self.alloc, operand);
        operand_transferred = true;

        if (kind == .trim or kind == .ltrim or kind == .rtrim) {
            if (self.match(.comma) != null) {
                const trim_operand = try self.parseRowExpressionAlloc();
                var trim_transferred = false;
                errdefer if (!trim_transferred) freeExpression(self.alloc, trim_operand);
                try self.validateTextRowExpression(trim_operand);
                try operands.append(self.alloc, trim_operand);
                trim_transferred = true;
            }
        }
        try self.expect(.rparen);

        return .{
            .kind = kind,
            .operands = try operands.toOwnedSlice(self.alloc),
        };
    }

    fn parsePeriodBoundRowExpressionAlloc(
        self: *@This(),
        kind: db_mod.types.RelationalRowsExpressionKind,
    ) !?db_mod.types.RelationalRowsExpression {
        if (kind != .lower and kind != .upper) return null;
        const start_pos = self.pos;
        const parsed_field = self.parseIdentifierOwned() catch |err| switch (err) {
            error.UnsupportedSqlShape => return null,
            else => return err,
        };
        defer self.alloc.free(parsed_field);
        const field = (try self.normalizePeriodReferenceAlloc(parsed_field)) orelse (self.normalizeRowExpressionFieldAlloc(parsed_field) catch |err| switch (err) {
            error.InvalidSqlCatalog, error.UnsupportedSqlShape => {
                self.pos = start_pos;
                return null;
            },
            else => return err,
        });
        defer self.alloc.free(field);
        const period = relationalPeriodForDdl(self.schema.periods, field) orelse {
            self.pos = start_pos;
            return null;
        };
        if (!self.peekKind(.rparen)) return error.UnsupportedSqlShape;
        try self.expect(.rparen);
        const bound_name = if (kind == .lower) period.start_column else period.end_column;
        const bound_column = relationalColumnForField(self.schema, bound_name, null) orelse return error.InvalidSqlCatalog;
        if (!relationalPeriodColumnType(bound_column.field_type)) return error.InvalidSqlCatalog;
        return .{
            .kind = .field,
            .field = try self.alloc.dupe(u8, bound_column.name),
            .field_source = self.rowExpressionFieldSource(),
        };
