            const op: runtime_schema.RelationalGeneratedOp = if (self.peekKeyword("lower")) .lower else if (self.peekKeyword("upper")) .upper else .md5;
            self.pos += 1;
            try self.expect(.lparen);
            const parsed_source = try self.parseIdentifierOwned();
            defer self.alloc.free(parsed_source);
            const source = try self.normalizeRowExpressionFieldAlloc(parsed_source);
            defer self.alloc.free(source);
            if (relationalColumnForField(self.schema, source, null) == null) return error.InvalidSqlCatalog;
            try self.expect(.rparen);
            const generated = generatedUnaryTextColumnForField(self.schema, op, source) orelse return error.UnsupportedSqlShape;
            return try self.alloc.dupe(u8, generated.name);
