    fn generatedConcatColumnAtCurrent(self: *@This()) !?runtime_schema.RelationalColumn {
        for (self.schema.relational_columns) |column| {
            const generated = column.generated orelse continue;
            if (generated.op != .concat and generated.op != .concat_ws) continue;
            if (try self.concatCallMatchesGeneratedAtCurrent(generated)) return column;
        }
        return null;
    }

    fn concatCallMatchesGeneratedAtCurrent(
        self: *@This(),
        generated: runtime_schema.RelationalGeneratedValue,
    ) !bool {
        if (generated.fields.len == 0) return false;
        if (self.pos + 2 >= self.tokens.len) return false;
        if (self.tokens[self.pos].kind != .identifier) return false;
        if (generated.op == .concat and !std.ascii.eqlIgnoreCase(self.tokens[self.pos].text, "concat")) return false;
        if (generated.op == .concat_ws and !std.ascii.eqlIgnoreCase(self.tokens[self.pos].text, "concat_ws")) return false;
        if (self.tokens[self.pos + 1].kind != .lparen) return false;
        var i: usize = self.pos + 2;
        if (generated.op == .concat_ws) {
            if (i >= self.tokens.len or self.tokens[i].kind != .string) return false;
            if (!std.mem.eql(u8, self.tokens[i].text, generated.separator)) return false;
            i += 1;
            if (i >= self.tokens.len or self.tokens[i].kind != .comma) return false;
            i += 1;
        }
        for (generated.fields, 0..) |field, field_index| {
            if (i >= self.tokens.len or self.tokens[i].kind != .identifier) return false;
            const normalized_field = try self.normalizeRowExpressionFieldAlloc(self.tokens[i].text);
            defer self.alloc.free(normalized_field);
            if (!std.mem.eql(u8, normalized_field, field)) return false;
            i += 1;
            if (field_index + 1 < generated.fields.len) {
                if (i >= self.tokens.len or self.tokens[i].kind != .comma) return false;
                i += 1;
                if (generated.op == .concat) {
                    if (i >= self.tokens.len or self.tokens[i].kind != .string) return false;
                    if (!std.mem.eql(u8, self.tokens[i].text, generated.separator)) return false;
                    i += 1;
                    if (i >= self.tokens.len or self.tokens[i].kind != .comma) return false;
                    i += 1;
                }
            }
        }
        return i < self.tokens.len and self.tokens[i].kind == .rparen;
    }

