            const segment = try self.parseJsonPathOwned();
            defer self.alloc.free(segment);
            if (segment.len == 0 or std.mem.indexOfScalar(u8, segment, '.') != null) return error.UnsupportedSqlShape;
            if (segments > 0) try path.append(self.alloc, '.');
            try path.appendSlice(self.alloc, segment);
            segments += 1;
