    fn matchKeyword(self: *@This(), keyword: []const u8) bool {
        if (self.pos >= self.tokens.len) return false;
        const token = self.tokens[self.pos];
        if (token.kind != .identifier) return false;
        if (!std.ascii.eqlIgnoreCase(token.text, keyword)) return false;
        self.pos += 1;
        return true;
    }

    fn matchAnyOrSomeKeyword(self: *@This()) bool {
        if (self.pos >= self.tokens.len) return false;
        const token = self.tokens[self.pos];
        if (token.kind != .identifier or !sqlKeywordIsAnyOrSome(token.text)) return false;
        self.pos += 1;
        return true;
    }

    fn tokenAtIsAnySomeOrAll(self: *@This(), index: usize) bool {
        if (index >= self.tokens.len) return false;
        const token = self.tokens[index];
        return token.kind == .identifier and
            (sqlKeywordIsAnyOrSome(token.text) or std.ascii.eqlIgnoreCase(token.text, "all"));
    }

    fn matchAnySomeOrAllKeyword(self: *@This()) ?SqlPatternQuantifier {
        if (self.pos >= self.tokens.len) return null;
        const token = self.tokens[self.pos];
        if (token.kind != .identifier) return null;
        if (sqlKeywordIsAnyOrSome(token.text)) {
            self.pos += 1;
            return .any;
        }
        if (std.ascii.eqlIgnoreCase(token.text, "all")) {
            self.pos += 1;
            return .all;
        }
        return null;
    }

