fn encodeSqlTxnIdHex(txn_id: db_mod.types.TxnId) [32]u8 {
    var out: [32]u8 = undefined;
    const hex = "0123456789abcdef";
    for (txn_id, 0..) |byte, i| {
        out[i * 2] = hex[byte >> 4];
        out[i * 2 + 1] = hex[byte & 0x0f];
    }
    return out;
}

fn md5HexTextAlloc(alloc: std.mem.Allocator, text: []const u8) ![]u8 {
    const digest = std.crypto.hash.Md5.hashResult(text);
    const out = try alloc.alloc(u8, 32);
    for (digest, 0..) |byte, i| {
        out[i * 2] = std.fmt.digitToChar(byte >> 4, .lower);
        out[i * 2 + 1] = std.fmt.digitToChar(byte & 0x0f, .lower);
    }
    return out;
}

fn initcapTextAlloc(alloc: std.mem.Allocator, text: []const u8) ![]u8 {
    const out = try alloc.dupe(u8, text);
    var at_word_start = true;
    for (out) |*byte| {
        if (std.ascii.isAlphanumeric(byte.*)) {
            byte.* = if (at_word_start) std.ascii.toUpper(byte.*) else std.ascii.toLower(byte.*);
            at_word_start = false;
        } else {
            at_word_start = true;
        }
    }
    return out;
}

fn tokenKindIsJsonExtractOperator(kind: TokenKind) bool {
    return kind == .arrow_json or kind == .arrow_text or kind == .path_arrow_json or kind == .path_arrow_text;
}

fn tokenKindIsJsonExtractTextOperator(kind: TokenKind) bool {
    return kind == .arrow_text or kind == .path_arrow_text;
}

fn tokenKindIsJsonExtractPathOperator(kind: TokenKind) bool {
    return kind == .path_arrow_json or kind == .path_arrow_text;
}

fn findCteByName(ctes: []const db_mod.types.RelationalRowsCte, name: []const u8) ?db_mod.types.RelationalRowsCte {
    for (ctes) |cte| {
        if (std.mem.eql(u8, cte.name, name)) return cte;
    }
    return null;
}

fn windowOutputFieldIsUnique(
    fields: []const []const u8,
    windows: []const db_mod.types.RelationalRowsWindowSpec,
    field: []const u8,
) bool {
    var matches: usize = 0;
    for (fields) |candidate| {
        if (std.mem.eql(u8, candidate, field)) matches += 1;
    }
    for (windows) |window| {
        if (std.mem.eql(u8, window.output, field)) matches += 1;
    }
    return matches == 1;
}

fn tokenizeAlloc(alloc: std.mem.Allocator, sql: []const u8) !std.ArrayListUnmanaged(Token) {
    var tokens = std.ArrayListUnmanaged(Token).empty;
    errdefer freeTokens(alloc, &tokens);

    var i: usize = 0;
    while (i < sql.len) {
        const ch = sql[i];
        if (std.ascii.isWhitespace(ch)) {
            i += 1;
            continue;
        }
        if (std.ascii.isAlphabetic(ch) or ch == '_') {
            const start = i;
            i += 1;
            while (i < sql.len and (std.ascii.isAlphanumeric(sql[i]) or sql[i] == '_' or sql[i] == '.')) i += 1;
            const end = i;
            i = skipSqlCast(sql, i);
            try tokens.append(alloc, .{ .kind = .identifier, .text = sql[start..end] });
            continue;
        }
        if (ch == '"') {
            const start = i + 1;
            i += 1;
            while (i < sql.len and sql[i] != '"') i += 1;
            if (i >= sql.len) return error.UnsupportedSqlShape;
            try tokens.append(alloc, .{ .kind = .identifier, .text = sql[start..i] });
            i += 1;
            i = skipSqlCast(sql, i);
            continue;
        }
        if (ch == '\'') {
            var out = std.ArrayListUnmanaged(u8).empty;
            errdefer out.deinit(alloc);
            i += 1;
            while (i < sql.len) {
                if (sql[i] == '\'') {
                    if (i + 1 < sql.len and sql[i + 1] == '\'') {
                        try out.append(alloc, '\'');
                        i += 2;
                        continue;
                    }
                    break;
                }
                try out.append(alloc, sql[i]);
                i += 1;
            }
            if (i >= sql.len) return error.UnsupportedSqlShape;
            const owned = try out.toOwnedSlice(alloc);
            errdefer alloc.free(owned);
            i += 1;
            if (sqlCastTypeAt(sql, i)) |cast_type| {
                i = cast_type.end;
                if (sqlCastTypeIsNumeric(cast_type.name)) {
                    if (!sqlStringIsJsonNumber(alloc, owned)) return error.UnsupportedSqlShape;
                    try tokens.append(alloc, .{ .kind = .number, .text = owned, .owned = true });
                } else if (sqlCastTypeIsBoolean(cast_type.name)) {
                    if (!std.ascii.eqlIgnoreCase(owned, "true") and !std.ascii.eqlIgnoreCase(owned, "false")) return error.UnsupportedSqlShape;
                    try tokens.append(alloc, .{ .kind = .identifier, .text = owned, .owned = true });
                } else {
                    try tokens.append(alloc, .{ .kind = .string, .text = owned });
                }
            } else {
                try tokens.append(alloc, .{ .kind = .string, .text = owned });
            }
            continue;
        }
        if (std.ascii.isDigit(ch)) {
            const start = i;
            i += 1;
            while (i < sql.len and (std.ascii.isDigit(sql[i]) or sql[i] == '.')) i += 1;
            const end = i;
            i = skipSqlNumericCast(sql, i);
            try tokens.append(alloc, .{ .kind = .number, .text = sql[start..end] });
            continue;
        }
        if (ch == '$') {
            const start = i;
            i += 1;
            while (i < sql.len and std.ascii.isDigit(sql[i])) i += 1;
            if (i == start + 1) return error.UnsupportedSqlShape;
            if (i + 1 < sql.len and sql[i] == ':' and sql[i + 1] == ':') {
                i += 2;
                while (i < sql.len and (std.ascii.isAlphanumeric(sql[i]) or sql[i] == '_' or sql[i] == '[' or sql[i] == ']')) i += 1;
            }
            try tokens.append(alloc, .{ .kind = .placeholder, .text = sql[start..i] });
            continue;
        }
        switch (ch) {
            ',' => {
                try tokens.append(alloc, .{ .kind = .comma, .text = sql[i .. i + 1] });
                i += 1;
            },
            '*' => {
                try tokens.append(alloc, .{ .kind = .star, .text = sql[i .. i + 1] });
                i += 1;
            },
            '+' => {
                try tokens.append(alloc, .{ .kind = .plus, .text = sql[i .. i + 1] });
                i += 1;
            },
            '/' => {
                try tokens.append(alloc, .{ .kind = .slash, .text = sql[i .. i + 1] });
                i += 1;
            },
            '%' => {
                try tokens.append(alloc, .{ .kind = .percent, .text = sql[i .. i + 1] });
                i += 1;
            },
            '(' => {
                try tokens.append(alloc, .{ .kind = .lparen, .text = sql[i .. i + 1] });
                i += 1;
            },
            ')' => {
                try tokens.append(alloc, .{ .kind = .rparen, .text = sql[i .. i + 1] });
                i += 1;
                i = skipSqlCast(sql, i);
            },
            '[' => {
                try tokens.append(alloc, .{ .kind = .lbracket, .text = sql[i .. i + 1] });
                i += 1;
            },
            ']' => {
                try tokens.append(alloc, .{ .kind = .rbracket, .text = sql[i .. i + 1] });
                i += 1;
                i = skipSqlCast(sql, i);
            },
            '@' => {
                if (i + 1 >= sql.len or sql[i + 1] != '>') return error.UnsupportedSqlShape;
                try tokens.append(alloc, .{ .kind = .at_contains, .text = sql[i .. i + 2] });
                i += 2;
            },
            '&' => {
                if (i + 1 >= sql.len or sql[i + 1] != '&') return error.UnsupportedSqlShape;
                try tokens.append(alloc, .{ .kind = .range_overlap, .text = sql[i .. i + 2] });
                i += 2;
            },
            '|' => {
                if (i + 1 >= sql.len or sql[i + 1] != '|') return error.UnsupportedSqlShape;
                try tokens.append(alloc, .{ .kind = .pipe_concat, .text = sql[i .. i + 2] });
                i += 2;
            },
            '?' => {
                if (i + 1 < sql.len and sql[i + 1] == '|') {
                    try tokens.append(alloc, .{ .kind = .question_any, .text = sql[i .. i + 2] });
                    i += 2;
                } else if (i + 1 < sql.len and sql[i + 1] == '&') {
                    try tokens.append(alloc, .{ .kind = .question_all, .text = sql[i .. i + 2] });
                    i += 2;
                } else {
                    try tokens.append(alloc, .{ .kind = .question, .text = sql[i .. i + 1] });
                    i += 1;
                }
            },
            '~' => {
                if (i + 1 < sql.len and sql[i + 1] == '*') {
                    try tokens.append(alloc, .{ .kind = .regex_imatch, .text = sql[i .. i + 2] });
                    i += 2;
                } else {
                    try tokens.append(alloc, .{ .kind = .regex_match, .text = sql[i .. i + 1] });
                    i += 1;
                }
            },
            '#' => {
                if (i + 2 < sql.len and sql[i + 1] == '>' and sql[i + 2] == '>') {
                    try tokens.append(alloc, .{ .kind = .path_arrow_text, .text = sql[i .. i + 3] });
                    i += 3;
                } else if (i + 1 < sql.len and sql[i + 1] == '>') {
                    try tokens.append(alloc, .{ .kind = .path_arrow_json, .text = sql[i .. i + 2] });
                    i += 2;
                } else {
                    return error.UnsupportedSqlShape;
                }
            },
            ';' => {
                try tokens.append(alloc, .{ .kind = .semicolon, .text = sql[i .. i + 1] });
                i += 1;
            },
            '=' => {
                try tokens.append(alloc, .{ .kind = .eq, .text = sql[i .. i + 1] });
                i += 1;
            },
            '!' => {
                if (i + 1 < sql.len and sql[i + 1] == '=') {
                    try tokens.append(alloc, .{ .kind = .neq, .text = sql[i .. i + 2] });
                    i += 2;
                } else if (i + 1 < sql.len and sql[i + 1] == '~') {
                    if (i + 2 < sql.len and sql[i + 2] == '*') {
                        try tokens.append(alloc, .{ .kind = .regex_not_imatch, .text = sql[i .. i + 3] });
                        i += 3;
                    } else {
                        try tokens.append(alloc, .{ .kind = .regex_not_match, .text = sql[i .. i + 2] });
                        i += 2;
                    }
                } else return error.UnsupportedSqlShape;
            },
            '<' => {
                if (i + 1 < sql.len and sql[i + 1] == '=') {
                    try tokens.append(alloc, .{ .kind = .lte, .text = sql[i .. i + 2] });
                    i += 2;
                } else if (i + 1 < sql.len and sql[i + 1] == '>') {
                    try tokens.append(alloc, .{ .kind = .neq, .text = sql[i .. i + 2] });
                    i += 2;
                } else {
                    try tokens.append(alloc, .{ .kind = .lt, .text = sql[i .. i + 1] });
                    i += 1;
                }
            },
            '>' => {
                if (i + 1 < sql.len and sql[i + 1] == '=') {
                    try tokens.append(alloc, .{ .kind = .gte, .text = sql[i .. i + 2] });
                    i += 2;
                } else {
                    try tokens.append(alloc, .{ .kind = .gt, .text = sql[i .. i + 1] });
                    i += 1;
                }
            },
            '-' => {
                if (i + 1 < sql.len and sql[i + 1] == '>' and i + 2 < sql.len and sql[i + 2] == '>') {
                    try tokens.append(alloc, .{ .kind = .arrow_text, .text = sql[i .. i + 3] });
                    i += 3;
                } else if (i + 1 < sql.len and sql[i + 1] == '>') {
                    try tokens.append(alloc, .{ .kind = .arrow_json, .text = sql[i .. i + 2] });
                    i += 2;
                } else {
                    try tokens.append(alloc, .{ .kind = .minus, .text = sql[i .. i + 1] });
                    i += 1;
                }
            },
            else => return error.UnsupportedSqlShape,
        }
    }
    return tokens;
}

fn skipSqlCast(sql: []const u8, start: usize) usize {
    return if (sqlCastTypeAt(sql, start)) |cast_type| cast_type.end else start;
}

fn skipSqlNumericCast(sql: []const u8, start: usize) usize {
    const cast_type = sqlCastTypeAt(sql, start) orelse return start;
    if (!sqlCastTypeIsNumeric(cast_type.name)) return start;
    return cast_type.end;
}

const SqlCastType = struct {
    name: []const u8,
    end: usize,
};

fn sqlCastTypeAt(sql: []const u8, start: usize) ?SqlCastType {
    if (start + 1 >= sql.len or sql[start] != ':' or sql[start + 1] != ':') return null;
    var i = start + 2;
    const type_start = i;
    while (i < sql.len and (std.ascii.isAlphanumeric(sql[i]) or sql[i] == '_')) i += 1;
    if (i == type_start) return null;
    const type_name = sql[type_start..i];
    if (i < sql.len and sql[i] == '[') {
        i += 1;
        if (i >= sql.len or sql[i] != ']') return null;
        i += 1;
    }
    return .{ .name = type_name, .end = i };
}

fn sqlCastTypeIsNumeric(type_name: []const u8) bool {
    return std.ascii.eqlIgnoreCase(type_name, "numeric") or
        std.ascii.eqlIgnoreCase(type_name, "decimal") or
        std.ascii.eqlIgnoreCase(type_name, "int") or
        std.ascii.eqlIgnoreCase(type_name, "int2") or
        std.ascii.eqlIgnoreCase(type_name, "int4") or
        std.ascii.eqlIgnoreCase(type_name, "int8") or
        std.ascii.eqlIgnoreCase(type_name, "integer") or
        std.ascii.eqlIgnoreCase(type_name, "smallint") or
        std.ascii.eqlIgnoreCase(type_name, "bigint") or
        std.ascii.eqlIgnoreCase(type_name, "real") or
        std.ascii.eqlIgnoreCase(type_name, "float4") or
        std.ascii.eqlIgnoreCase(type_name, "float8");
}

fn sqlCastTypeIsBoolean(type_name: []const u8) bool {
    return std.ascii.eqlIgnoreCase(type_name, "bool") or
        std.ascii.eqlIgnoreCase(type_name, "boolean");
}

fn sqlStringIsJsonNumber(alloc: std.mem.Allocator, text: []const u8) bool {
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, text, .{}) catch return false;
    defer parsed.deinit();
    return parsed.value == .integer or parsed.value == .float;
}

fn parseSqlTimestampLiteralNs(raw: []const u8) !i64 {
    const text = std.mem.trim(u8, trimSqlRangeEndpointQuotes(raw), " \t\r\n");
    if (text.len < "0000-00-00".len) return error.UnsupportedSqlShape;
    if (text[4] != '-' or text[7] != '-') return error.UnsupportedSqlShape;
    const year = try parseSqlFixedDigits(i64, text[0..4]);
    const month = try parseSqlFixedDigits(u8, text[5..7]);
    const day = try parseSqlFixedDigits(u8, text[8..10]);
    if (month < 1 or month > 12) return error.UnsupportedSqlShape;
    const max_day = sqlDaysInMonth(year, month);
    if (day < 1 or day > max_day) return error.UnsupportedSqlShape;

    var i: usize = 10;
    var hour: u8 = 0;
    var minute: u8 = 0;
    var second: u8 = 0;
    var fractional_ns: i64 = 0;
    var offset_seconds: i64 = 0;

    if (i < text.len) {
        if (text[i] != 'T' and text[i] != 't' and text[i] != ' ') return error.UnsupportedSqlShape;
        i += 1;
        if (i + 8 > text.len or text[i + 2] != ':' or text[i + 5] != ':') return error.UnsupportedSqlShape;
        hour = try parseSqlFixedDigits(u8, text[i .. i + 2]);
        minute = try parseSqlFixedDigits(u8, text[i + 3 .. i + 5]);
        second = try parseSqlFixedDigits(u8, text[i + 6 .. i + 8]);
        if (hour > 23 or minute > 59 or second > 59) return error.UnsupportedSqlShape;
        i += 8;
        if (i < text.len and text[i] == '.') {
            i += 1;
            const fraction_start = i;
            var multiplier: i64 = 100_000_000;
            while (i < text.len and std.ascii.isDigit(text[i])) : (i += 1) {
                if (i - fraction_start < 9) {
                    fractional_ns += @as(i64, text[i] - '0') * multiplier;
                    multiplier = @divExact(multiplier, 10);
                }
            }
            if (i == fraction_start) return error.UnsupportedSqlShape;
        }
        if (i < text.len) {
            offset_seconds = try parseSqlTimestampOffsetSeconds(text[i..]);
            i = text.len;
        }
    }

    if (i != text.len) return error.UnsupportedSqlShape;
    const day_ns = (@as(i64, hour) * 60 * 60 + @as(i64, minute) * 60 + @as(i64, second)) * std.time.ns_per_s + fractional_ns;
    const days = sqlDaysFromCivil(year, month, day);
    const total_ns = @as(i128, days) * @as(i128, std.time.ns_per_day) + @as(i128, day_ns) - @as(i128, offset_seconds) * @as(i128, std.time.ns_per_s);
    if (total_ns < std.math.minInt(i64) or total_ns > std.math.maxInt(i64)) return error.UnsupportedSqlShape;
    return @intCast(total_ns);
}

fn trimSqlRangeEndpointQuotes(text: []const u8) []const u8 {
    if (text.len >= 2 and ((text[0] == '"' and text[text.len - 1] == '"') or (text[0] == '\'' and text[text.len - 1] == '\''))) {
        return text[1 .. text.len - 1];
    }
    return text;
}

fn parseSqlFixedDigits(comptime T: type, text: []const u8) !T {
    if (text.len == 0) return error.UnsupportedSqlShape;
    var value: T = 0;
    for (text) |ch| {
        if (!std.ascii.isDigit(ch)) return error.UnsupportedSqlShape;
        value = value * 10 + @as(T, @intCast(ch - '0'));
    }
    return value;
}

fn parseSqlTimestampOffsetSeconds(text: []const u8) !i64 {
    if (text.len == 0) return 0;
    if (std.ascii.eqlIgnoreCase(text, "Z")) return 0;
    const sign: i64 = if (text[0] == '+') 1 else if (text[0] == '-') -1 else return error.UnsupportedSqlShape;
    if (text.len != 3 and text.len != 5 and text.len != 6) return error.UnsupportedSqlShape;
    const hour = try parseSqlFixedDigits(i64, text[1..3]);
    var minute: i64 = 0;
    if (text.len == 5) {
        minute = try parseSqlFixedDigits(i64, text[3..5]);
    } else if (text.len == 6) {
        if (text[3] != ':') return error.UnsupportedSqlShape;
        minute = try parseSqlFixedDigits(i64, text[4..6]);
    }
    if (hour > 23 or minute > 59) return error.UnsupportedSqlShape;
    return sign * (hour * 60 * 60 + minute * 60);
}

fn sqlDaysFromCivil(year_value: i64, month_value: u8, day_value: u8) i64 {
    var year = year_value;
    const month: i64 = month_value;
    const day: i64 = day_value;
    year -= if (month <= 2) 1 else 0;
    const era = @divFloor(year, 400);
    const yoe = year - era * 400;
    const month_prime = month + if (month > 2) @as(i64, -3) else @as(i64, 9);
    const doy = @divFloor(153 * month_prime + 2, 5) + day - 1;
    const doe = yoe * 365 + @divFloor(yoe, 4) - @divFloor(yoe, 100) + doy;
    return era * 146097 + doe - 719468;
}

fn sqlDaysInMonth(year: i64, month: u8) u8 {
    return switch (month) {
        1, 3, 5, 7, 8, 10, 12 => 31,
        4, 6, 9, 11 => 30,
        2 => if (sqlIsLeapYear(year)) 29 else 28,
        else => 0,
    };
}

fn sqlIsLeapYear(year: i64) bool {
    return @mod(year, 4) == 0 and (@mod(year, 100) != 0 or @mod(year, 400) == 0);
}

fn freeTokens(alloc: std.mem.Allocator, tokens: *std.ArrayListUnmanaged(Token)) void {
    for (tokens.items) |token| {
        if (token.kind == .string or token.owned) alloc.free(token.text);
    }
    tokens.deinit(alloc);
}

const SqlIntervalLiteral = struct {
    fixed_ns: u64,
    calendar_months: u64,
    saw_fixed: bool,
    saw_calendar: bool,
};

fn sqlIntervalLiteral(text: []const u8) !SqlIntervalLiteral {
    var parts = std.mem.tokenizeAny(u8, text, " \t\r\n");
    var fixed_total: u128 = 0;
    var calendar_total: u128 = 0;
    var saw_pair = false;
    var saw_fixed = false;
    var saw_calendar = false;
    while (parts.next()) |amount_text| {
        const unit_text = parts.next() orelse return error.UnsupportedSqlShape;
        const amount = std.fmt.parseInt(u64, amount_text, 10) catch return error.UnsupportedSqlShape;
        if (sqlIntervalUnitNs(unit_text)) |multiplier| {
            saw_fixed = true;
            fixed_total += @as(u128, amount) * @as(u128, multiplier);
            if (fixed_total > std.math.maxInt(u64)) return error.UnsupportedSqlShape;
        } else if (sqlIntervalUnitMonths(unit_text)) |months| {
            saw_calendar = true;
            calendar_total += @as(u128, amount) * @as(u128, months);
            if (calendar_total > std.math.maxInt(u64)) return error.UnsupportedSqlShape;
        } else {
            return error.UnsupportedSqlShape;
        }
        saw_pair = true;
    }
    if (!saw_pair) return error.UnsupportedSqlShape;
    return .{
        .fixed_ns = @intCast(fixed_total),
        .calendar_months = @intCast(calendar_total),
        .saw_fixed = saw_fixed,
        .saw_calendar = saw_calendar,
    };
}

fn sqlIntervalUnitNs(unit: []const u8) ?u64 {
    if (std.ascii.eqlIgnoreCase(unit, "ns") or
        std.ascii.eqlIgnoreCase(unit, "nanosecond") or
        std.ascii.eqlIgnoreCase(unit, "nanoseconds"))
        return 1;
    if (std.ascii.eqlIgnoreCase(unit, "us") or
        std.ascii.eqlIgnoreCase(unit, "microsecond") or
        std.ascii.eqlIgnoreCase(unit, "microseconds"))
        return 1_000;
    if (std.ascii.eqlIgnoreCase(unit, "ms") or
        std.ascii.eqlIgnoreCase(unit, "millisecond") or
        std.ascii.eqlIgnoreCase(unit, "milliseconds"))
        return 1_000_000;
    if (std.ascii.eqlIgnoreCase(unit, "s") or
        std.ascii.eqlIgnoreCase(unit, "sec") or
        std.ascii.eqlIgnoreCase(unit, "second") or
        std.ascii.eqlIgnoreCase(unit, "seconds"))
        return 1_000_000_000;
    if (std.ascii.eqlIgnoreCase(unit, "m") or
        std.ascii.eqlIgnoreCase(unit, "min") or
        std.ascii.eqlIgnoreCase(unit, "minute") or
        std.ascii.eqlIgnoreCase(unit, "minutes"))
        return 60 * 1_000_000_000;
    if (std.ascii.eqlIgnoreCase(unit, "h") or
        std.ascii.eqlIgnoreCase(unit, "hr") or
        std.ascii.eqlIgnoreCase(unit, "hour") or
        std.ascii.eqlIgnoreCase(unit, "hours"))
        return 60 * 60 * 1_000_000_000;
    if (std.ascii.eqlIgnoreCase(unit, "d") or
        std.ascii.eqlIgnoreCase(unit, "day") or
        std.ascii.eqlIgnoreCase(unit, "days"))
        return 24 * 60 * 60 * 1_000_000_000;
    if (std.ascii.eqlIgnoreCase(unit, "w") or
        std.ascii.eqlIgnoreCase(unit, "week") or
        std.ascii.eqlIgnoreCase(unit, "weeks"))
        return 7 * 24 * 60 * 60 * 1_000_000_000;
    return null;
}

fn sqlIntervalUnitMonths(unit: []const u8) ?u64 {
    if (std.ascii.eqlIgnoreCase(unit, "month") or
        std.ascii.eqlIgnoreCase(unit, "months"))
        return 1;
    if (std.ascii.eqlIgnoreCase(unit, "year") or
        std.ascii.eqlIgnoreCase(unit, "years"))
        return 12;
    return null;
}

fn relationalColumnForField(schema: runtime_schema.TableSchema, field: []const u8, expected_type: ?runtime_schema.AntflyType) ?runtime_schema.RelationalColumn {
    for (schema.relational_columns) |column| {
        if (!std.mem.eql(u8, column.name, field)) continue;
        if (expected_type) |field_type| {
            if (column.field_type != field_type) return null;
        }
        return column;
    }
    return null;
}

fn sqlArrayItemValueMatches(item_type: runtime_schema.AntflyType, value: std.json.Value) bool {
    return switch (item_type) {
        .text, .keyword, .link, .html, .search_as_you_type, .blob, .geoshape => value == .string,
        .numeric => value == .integer or value == .float or value == .number_string,
        .datetime => value == .integer or value == .float or value == .number_string,
        .boolean => value == .bool,
        .geopoint => value == .array or value == .object,
        .json => true,
        .array => value == .array,
        .embedding => false,
    };
}

fn sqlScalarValueMatches(field_type: runtime_schema.AntflyType, value: std.json.Value) bool {
    return switch (field_type) {
        .text, .keyword, .link, .html, .search_as_you_type, .blob, .geoshape => value == .string,
        .numeric => value == .integer or value == .float or value == .number_string,
        .datetime => value == .integer or value == .float or value == .number_string,
        .boolean => value == .bool,
        .geopoint => value == .array or value == .object,
        .json, .array, .embedding => false,
    };
}

fn generatedUnaryTextColumnForField(
    schema: runtime_schema.TableSchema,
    op: runtime_schema.RelationalGeneratedOp,
    field: []const u8,
) ?runtime_schema.RelationalColumn {
    switch (op) {
        .lower, .upper, .md5 => {},
        .concat, .concat_ws => return null,
    }
    for (schema.relational_columns) |column| {
        const generated = column.generated orelse continue;
        if (generated.op != op) continue;
        const generated_field = generated.field orelse continue;
        if (std.mem.eql(u8, generated_field, field)) return column;
    }
    return null;
}

fn generatedConcatColumnAt(
    schema: runtime_schema.TableSchema,
    tokens: []const Token,
    pos: usize,
) ?runtime_schema.RelationalColumn {
    for (schema.relational_columns) |column| {
        const generated = column.generated orelse continue;
        if (generated.op != .concat and generated.op != .concat_ws) continue;
        if (concatCallMatchesGenerated(tokens, pos, generated)) return column;
    }
    return null;
}

fn concatCallMatchesGenerated(
    tokens: []const Token,
    pos: usize,
    generated: runtime_schema.RelationalGeneratedValue,
) bool {
    if (generated.fields.len == 0) return false;
    if (pos + 2 >= tokens.len) return false;
    if (tokens[pos].kind != .identifier) return false;
    if (generated.op == .concat and !std.ascii.eqlIgnoreCase(tokens[pos].text, "concat")) return false;
    if (generated.op == .concat_ws and !std.ascii.eqlIgnoreCase(tokens[pos].text, "concat_ws")) return false;
    if (tokens[pos + 1].kind != .lparen) return false;
    var i: usize = pos + 2;
    if (generated.op == .concat_ws) {
        if (i >= tokens.len or tokens[i].kind != .string) return false;
        if (!std.mem.eql(u8, tokens[i].text, generated.separator)) return false;
        i += 1;
        if (i >= tokens.len or tokens[i].kind != .comma) return false;
        i += 1;
    }
    for (generated.fields, 0..) |field, field_index| {
        if (i >= tokens.len or tokens[i].kind != .identifier) return false;
        if (!std.mem.eql(u8, tokens[i].text, field)) return false;
        i += 1;
        if (field_index + 1 < generated.fields.len) {
            if (i >= tokens.len or tokens[i].kind != .comma) return false;
            i += 1;
            if (generated.op == .concat) {
                if (i >= tokens.len or tokens[i].kind != .string) return false;
                if (!std.mem.eql(u8, tokens[i].text, generated.separator)) return false;
                i += 1;
                if (i >= tokens.len or tokens[i].kind != .comma) return false;
                i += 1;
            }
        }
    }
    return i < tokens.len and tokens[i].kind == .rparen;
}

fn relationalColumnForReturningField(schema: runtime_schema.TableSchema, field: []const u8) ?runtime_schema.RelationalColumn {
    if (relationalColumnForField(schema, field, null)) |column| return column;
    const dot_index = std.mem.indexOfScalar(u8, field, '.') orelse return null;
    if (dot_index == 0 or dot_index + 1 >= field.len) return null;
    return relationalColumnForField(schema, field[0..dot_index], .json);
}

fn findUniqueConstraintByColumns(schema: runtime_schema.TableSchema, columns: []const []const u8, require_partial: bool) ?runtime_schema.UniqueConstraint {
    for (schema.unique_constraints) |constraint| {
        if (constraint.validation_state != .enforced) continue;
        if (constraint.expressions.len != 0) continue;
        if (require_partial and constraint.where.len == 0) continue;
        if (!require_partial and constraint.where.len != 0) continue;
        if (stringSlicesEqual(constraint.columns, columns)) return constraint;
    }
    return null;
}

fn findUniqueConstraintByColumnsAndExpressions(
    schema: runtime_schema.TableSchema,
    columns: []const []const u8,
    expressions: []const runtime_schema.UniqueExpression,
    require_partial: bool,
) ?runtime_schema.UniqueConstraint {
    for (schema.unique_constraints) |constraint| {
        if (constraint.validation_state != .enforced) continue;
        if (require_partial and constraint.where.len == 0) continue;
        if (!require_partial and constraint.where.len != 0) continue;
        if (!stringSlicesEqual(constraint.columns, columns)) continue;
        if (!uniqueExpressionsEqual(constraint.expressions, expressions)) continue;
        return constraint;
    }
    return null;
}

fn findUniqueConstraintByColumnsExpressionsAndConflictWhere(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    columns: []const []const u8,
    expressions: []const runtime_schema.UniqueExpression,
    where_json: []const u8,
    where_expressions: []const db_mod.types.RelationalRowsExpressionCondition,
) !?runtime_schema.UniqueConstraint {
    const has_field_where = where_json.len > 0;
    const has_expression_where = where_expressions.len > 0;
    if (has_field_where and has_expression_where) return error.UnsupportedSqlShape;

    for (schema.unique_constraints) |constraint| {
        if (constraint.validation_state != .enforced) continue;
        if (!stringSlicesEqual(constraint.columns, columns)) continue;
        if (!uniqueExpressionsEqual(constraint.expressions, expressions)) continue;

        if (!has_field_where and !has_expression_where) {
            if (constraint.where.len == 0 and constraint.where_expressions.len == 0) return constraint;
            continue;
        }

        if (has_field_where) {
            if (constraint.where.len != 0 and constraint.where_expressions.len == 0) {
                validateUniqueWhereJsonMatches(alloc, where_json, constraint.where) catch continue;
                return constraint;
            }
            if (constraint.where.len == 0 and constraint.where_expressions.len != 0) {
                const predicates = try relationalChecksFromUniqueWhereJsonAlloc(alloc, where_json);
                defer {
                    freeRelationalChecks(alloc, predicates);
                    if (predicates.len > 0) alloc.free(predicates);
                }
                if (try db_mod.DB.relationalRowsExpressionConditionsImpliedByEqualityPredicatesAlloc(
                    alloc,
                    predicates,
                    constraint.where_expressions,
                )) return constraint;
            }
            continue;
        }

        if (constraint.where.len != 0) continue;
        if (expressionConditionsEqual(constraint.where_expressions, where_expressions)) return constraint;
    }
    return null;
}

fn relationalChecksFromUniqueWhereJsonAlloc(
    alloc: std.mem.Allocator,
    where_json: []const u8,
) ![]runtime_schema.RelationalCheck {
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, where_json, .{}) catch return error.UnsupportedSqlShape;
    defer parsed.deinit();
    if (parsed.value != .object) return error.UnsupportedSqlShape;
    const all_value = parsed.value.object.get("all") orelse return error.UnsupportedSqlShape;
    if (all_value != .array) return error.UnsupportedSqlShape;
    const out = try alloc.alloc(runtime_schema.RelationalCheck, all_value.array.items.len);
    var initialized: usize = 0;
    errdefer {
        for (out[0..initialized]) |check| {
            alloc.free(check.field);
            if (check.value_json) |json| alloc.free(json);
        }
        alloc.free(out);
    }
    for (all_value.array.items) |item| {
        if (item != .object) return error.UnsupportedSqlShape;
        const field_value = item.object.get("field") orelse return error.UnsupportedSqlShape;
        const op_value = item.object.get("op") orelse return error.UnsupportedSqlShape;
        if (field_value != .string or op_value != .string) return error.UnsupportedSqlShape;
        const op = relationalCheckOpFromUniquePredicateToken(op_value.string) orelse return error.UnsupportedSqlShape;
        const field = try alloc.dupe(u8, field_value.string);
        var field_transferred = false;
        errdefer if (!field_transferred) alloc.free(field);
        const value_json: ?[]const u8 = if (item.object.get("value")) |value| try std.json.Stringify.valueAlloc(alloc, value, .{}) else null;
        var value_transferred = false;
        errdefer if (!value_transferred) if (value_json) |json| alloc.free(json);
        out[initialized] = .{
            .name = "",
            .field = field,
            .op = op,
            .value_json = value_json,
        };
        initialized += 1;
        field_transferred = true;
        value_transferred = true;
    }
    return out;
}

fn relationalCheckOpFromUniquePredicateToken(token: []const u8) ?runtime_schema.RelationalCheckOp {
    if (std.mem.eql(u8, token, "is_null")) return .is_null;
    if (std.mem.eql(u8, token, "is_not_null")) return .is_not_null;
    if (std.mem.eql(u8, token, "eq")) return .eq;
    if (std.mem.eql(u8, token, "ne")) return .ne;
    return null;
}

fn findUniqueConstraintByColumnSet(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    values: []const Parser.FieldJsonValue,
) ?runtime_schema.UniqueConstraint {
    for (schema.unique_constraints) |constraint| {
        if (constraint.validation_state != .enforced) continue;
        if (constraint.expressions.len != 0) continue;
        if (uniqueConstraintMatchesPointSelector(alloc, constraint, values)) return constraint;
    }
    return null;
}

fn uniqueConstraintMatchesPointSelector(
    alloc: std.mem.Allocator,
    constraint: runtime_schema.UniqueConstraint,
    values: []const Parser.FieldJsonValue,
) bool {
    if (constraint.where.len == 0 and constraint.where_expressions.len == 0) return fieldValuesMatchColumns(values, constraint.columns);
    for (constraint.columns) |column| {
        if (fieldValueFor(values, column) == null) return false;
    }
    for (values) |value| {
        if (!uniqueConstraintAllowsPointSelectorField(constraint, value.field)) return false;
    }
    for (constraint.where) |predicate| {
        if (!uniquePredicateProvenByFieldValues(predicate, values)) return false;
    }
    for (constraint.where_expressions) |condition| {
        if (!(uniqueExpressionPredicateProvenByFieldValues(alloc, condition, values) catch false)) return false;
    }
    return true;
}

fn uniqueConstraintAllowsPointSelectorField(constraint: runtime_schema.UniqueConstraint, field: []const u8) bool {
    if (stringSlicesContains(constraint.columns, field)) return true;
    for (constraint.where) |predicate| {
        if (std.mem.eql(u8, predicate.field, field)) return true;
    }
    for (constraint.where_expressions) |condition| {
        if (expressionConditionReferencesField(condition, field)) return true;
    }
    return false;
}

fn uniquePredicateProvenByFieldValues(predicate: runtime_schema.UniquePredicate, values: []const Parser.FieldJsonValue) bool {
    const value = fieldValueFor(values, predicate.field) orelse return false;
    return switch (predicate.op) {
        .eq => if (predicate.value_json) |expected| std.mem.eql(u8, value.value_json, expected) else false,
        .ne => if (predicate.value_json) |forbidden|
            !std.mem.eql(u8, value.value_json, "null") and !std.mem.eql(u8, value.value_json, forbidden)
        else
            false,
        .is_not_null => !std.mem.eql(u8, value.value_json, "null"),
        .is_null => std.mem.eql(u8, value.value_json, "null"),
    };
}

fn uniqueExpressionPredicateProvenByFieldValues(
    alloc: std.mem.Allocator,
    condition: db_mod.types.RelationalRowsExpressionCondition,
    values: []const Parser.FieldJsonValue,
) !bool {
    const lhs_json = try selectorExpressionValueJsonAlloc(alloc, condition.lhs, values);
    defer alloc.free(lhs_json);
    var lhs = std.json.parseFromSlice(std.json.Value, alloc, lhs_json, .{}) catch return false;
    defer lhs.deinit();

    return switch (condition.op) {
        .is_null => lhs.value == .null,
        .is_not_null => lhs.value != .null,
        .eq, .ne, .is_distinct, .is_not_distinct => blk: {
            if (condition.rhs.len != 1) return false;
            const rhs_json = try selectorExpressionValueJsonAlloc(alloc, condition.rhs[0], values);
            defer alloc.free(rhs_json);
            var rhs = std.json.parseFromSlice(std.json.Value, alloc, rhs_json, .{}) catch return false;
            defer rhs.deinit();
            const equal = selectorJsonValuesEqual(lhs.value, rhs.value);
            break :blk switch (condition.op) {
                .eq, .is_not_distinct => equal,
                .ne, .is_distinct => !equal,
                else => unreachable,
            };
        },
        .gt, .gte, .lt, .lte => blk: {
            if (condition.rhs.len != 1) return false;
            const rhs_json = try selectorExpressionValueJsonAlloc(alloc, condition.rhs[0], values);
            defer alloc.free(rhs_json);
            var rhs = std.json.parseFromSlice(std.json.Value, alloc, rhs_json, .{}) catch return false;
            defer rhs.deinit();
            const comparison = selectorCompareJsonScalars(lhs.value, rhs.value) orelse return false;
            break :blk switch (condition.op) {
                .gt => comparison == .gt,
                .gte => comparison == .gt or comparison == .eq,
                .lt => comparison == .lt,
                .lte => comparison == .lt or comparison == .eq,
                else => unreachable,
            };
        },
    };
}

fn selectorExpressionValueJsonAlloc(
    alloc: std.mem.Allocator,
    expression: db_mod.types.RelationalRowsExpression,
    values: []const Parser.FieldJsonValue,
) ![]u8 {
    return switch (expression.kind) {
        .field => blk: {
            if (expression.field_source != .row) return error.UnsupportedSqlShape;
            const value = fieldValueFor(values, expression.field) orelse return error.UnsupportedSqlShape;
            break :blk try alloc.dupe(u8, value.value_json);
        },
        .value => try alloc.dupe(u8, expression.value_json),
        .lower, .upper, .initcap, .md5 => blk: {
            if (expression.operands.len != 1) return error.UnsupportedSqlShape;
            const value_json = try selectorExpressionValueJsonAlloc(alloc, expression.operands[0], values);
            defer alloc.free(value_json);
            var parsed = std.json.parseFromSlice(std.json.Value, alloc, value_json, .{}) catch return error.UnsupportedSqlShape;
            defer parsed.deinit();
            switch (parsed.value) {
                .null => break :blk try alloc.dupe(u8, "null"),
                .string => |text| {
                    const transformed = switch (expression.kind) {
                        .lower => try std.ascii.allocLowerString(alloc, text),
                        .upper => try std.ascii.allocUpperString(alloc, text),
                        .initcap => try initcapTextAlloc(alloc, text),
                        .md5 => try md5HexTextAlloc(alloc, text),
                        else => unreachable,
                    };
                    defer alloc.free(transformed);
                    break :blk try std.json.Stringify.valueAlloc(alloc, std.json.Value{ .string = transformed }, .{});
                },
                else => return error.UnsupportedSqlShape,
            }
        },
        .concat => blk: {
            if (expression.operands.len == 0) return error.UnsupportedSqlShape;
            var joined = std.ArrayListUnmanaged(u8).empty;
            defer joined.deinit(alloc);
            for (expression.operands) |operand| {
                const value_json = try selectorExpressionValueJsonAlloc(alloc, operand, values);
                defer alloc.free(value_json);
                var parsed = std.json.parseFromSlice(std.json.Value, alloc, value_json, .{}) catch return error.UnsupportedSqlShape;
                defer parsed.deinit();
                if (parsed.value == .null) continue;
                const text = try selectorScalarJsonValueTextAlloc(alloc, parsed.value);
                defer alloc.free(text);
                try joined.appendSlice(alloc, text);
            }
            break :blk try std.json.Stringify.valueAlloc(alloc, std.json.Value{ .string = joined.items }, .{});
        },
        .concat_ws => blk: {
            if (expression.operands.len < 2) return error.UnsupportedSqlShape;
            const separator_json = try selectorExpressionValueJsonAlloc(alloc, expression.operands[0], values);
            defer alloc.free(separator_json);
            var parsed_separator = std.json.parseFromSlice(std.json.Value, alloc, separator_json, .{}) catch return error.UnsupportedSqlShape;
            defer parsed_separator.deinit();
            if (parsed_separator.value == .null) break :blk try alloc.dupe(u8, "null");
            if (parsed_separator.value != .string) return error.UnsupportedSqlShape;

            var joined = std.ArrayListUnmanaged(u8).empty;
            defer joined.deinit(alloc);
            var emitted = false;
            for (expression.operands[1..]) |operand| {
                const value_json = try selectorExpressionValueJsonAlloc(alloc, operand, values);
                defer alloc.free(value_json);
                var parsed = std.json.parseFromSlice(std.json.Value, alloc, value_json, .{}) catch return error.UnsupportedSqlShape;
                defer parsed.deinit();
                if (parsed.value == .null) continue;
                if (parsed.value != .string) return error.UnsupportedSqlShape;
                if (emitted) try joined.appendSlice(alloc, parsed_separator.value.string);
                try joined.appendSlice(alloc, parsed.value.string);
                emitted = true;
            }
            break :blk try std.json.Stringify.valueAlloc(alloc, std.json.Value{ .string = joined.items }, .{});
        },
        else => error.UnsupportedSqlShape,
    };
}

fn selectorScalarJsonValueTextAlloc(alloc: std.mem.Allocator, value: std.json.Value) ![]u8 {
    return switch (value) {
        .string => |text| try alloc.dupe(u8, text),
        .integer => |integer| try std.fmt.allocPrint(alloc, "{d}", .{integer}),
        .float => |float| try std.fmt.allocPrint(alloc, "{d}", .{float}),
        .number_string => |text| try alloc.dupe(u8, text),
        .bool => |enabled| try alloc.dupe(u8, if (enabled) "true" else "false"),
        else => error.UnsupportedSqlShape,
    };
}

fn selectorJsonValuesEqual(a: std.json.Value, b: std.json.Value) bool {
    if (a == .null or b == .null) return a == .null and b == .null;
    if (a == .bool and b == .bool) return a.bool == b.bool;
    if (a == .string and b == .string) return std.mem.eql(u8, a.string, b.string);
    if (selectorJsonNumber(a)) |left| {
        if (selectorJsonNumber(b)) |right| return left == right;
    }
    return false;
}

const SelectorJsonOrder = enum { lt, eq, gt };

fn selectorCompareJsonScalars(a: std.json.Value, b: std.json.Value) ?SelectorJsonOrder {
    if (selectorJsonNumber(a)) |left| {
        if (selectorJsonNumber(b)) |right| {
            if (left < right) return .lt;
            if (left > right) return .gt;
            return .eq;
        }
    }
    if (a == .string and b == .string) {
        const order = std.mem.order(u8, a.string, b.string);
        return switch (order) {
            .lt => .lt,
            .eq => .eq,
            .gt => .gt,
        };
    }
    return null;
}

fn selectorJsonNumber(value: std.json.Value) ?f64 {
    return switch (value) {
        .integer => |integer| @floatFromInt(integer),
        .float => |float| float,
        .number_string => |text| std.fmt.parseFloat(f64, text) catch null,
        else => null,
    };
}

fn expressionConditionReferencesField(condition: db_mod.types.RelationalRowsExpressionCondition, field: []const u8) bool {
    if (expressionReferencesField(condition.lhs, field)) return true;
    for (condition.rhs) |rhs| {
        if (expressionReferencesField(rhs, field)) return true;
    }
    return false;
}

fn expressionReferencesField(expression: db_mod.types.RelationalRowsExpression, field: []const u8) bool {
    if (expression.kind == .field and expression.field_source == .row and std.mem.eql(u8, expression.field, field)) return true;
    for (expression.operands) |operand| {
        if (expressionReferencesField(operand, field)) return true;
    }
    for (expression.case_branches) |branch| {
        if (expressionConditionReferencesField(branch.when, field)) return true;
        if (expressionReferencesField(branch.then, field)) return true;
    }
    for (expression.case_else) |fallback| {
        if (expressionReferencesField(fallback, field)) return true;
    }
    return false;
}

fn findUniqueConstraintByName(schema: runtime_schema.TableSchema, name: []const u8) ?runtime_schema.UniqueConstraint {
    for (schema.unique_constraints) |constraint| {
        if (constraint.validation_state != .enforced) continue;
        if (std.mem.eql(u8, constraint.name, name)) return constraint;
    }
    return null;
}

fn findUniqueConstraintByExpression(
    schema: runtime_schema.TableSchema,
    op: runtime_schema.UniqueExpressionOp,
    field: []const u8,
) ?runtime_schema.UniqueConstraint {
    for (schema.unique_constraints) |constraint| {
        if (constraint.validation_state != .enforced) continue;
        if (constraint.columns.len != 0 or constraint.expressions.len != 1) continue;
        const expression = constraint.expressions[0];
        if (expression.op == op and std.mem.eql(u8, expression.field, field)) return constraint;
    }
    return null;
}

fn uniqueExpressionsEqual(a: []const runtime_schema.UniqueExpression, b: []const runtime_schema.UniqueExpression) bool {
    if (a.len != b.len) return false;
    for (a, b) |left, right| {
        if (left.op != right.op) return false;
        if (!std.mem.eql(u8, left.field, right.field)) return false;
    }
    return true;
}

fn conflictInsertedValueForColumn(insert_columns: []const []const u8, row: []const []const u8, column: []const u8) ?[]const u8 {
    if (insert_columns.len != row.len) return null;
    for (insert_columns, row) |insert_column, value_json| {
        if (std.mem.eql(u8, insert_column, column)) return value_json;
    }
    return null;
}

fn stringSlicesEqual(a: []const []const u8, b: []const []const u8) bool {
    if (a.len != b.len) return false;
    for (a, b) |left, right| {
        if (!std.mem.eql(u8, left, right)) return false;
    }
    return true;
}

fn stringSlicesContains(values: []const []const u8, value: []const u8) bool {
    for (values) |candidate| {
        if (std.mem.eql(u8, candidate, value)) return true;
    }
    return false;
}

fn stringSlicesIntersect(a: []const []const u8, b: []const []const u8) bool {
    for (a) |value| {
        if (stringSlicesContains(b, value)) return true;
    }
    return false;
}

fn fieldValuesContain(values: []const Parser.FieldJsonValue, field: []const u8) bool {
    return fieldValueFor(values, field) != null;
}

fn fieldValueFor(values: []const Parser.FieldJsonValue, field: []const u8) ?Parser.FieldJsonValue {
    for (values) |value| {
        if (std.mem.eql(u8, value.field, field)) return value;
    }
    return null;
}

fn fieldValuesMatchColumns(values: []const Parser.FieldJsonValue, columns: []const []const u8) bool {
    if (values.len != columns.len) return false;
    for (columns) |column| {
        if (fieldValueFor(values, column) == null) return false;
    }
    return true;
}

fn writeFieldValuesObjectJson(
    writer: *std.Io.Writer,
    values: []const Parser.FieldJsonValue,
    columns: []const []const u8,
) !void {
    try writer.writeByte('{');
    for (columns, 0..) |column, i| {
        const value = fieldValueFor(values, column) orelse return error.UnsupportedSqlShape;
        if (i != 0) try writer.writeByte(',');
        try writer.print("{f}:", .{std.json.fmt(column, .{})});
        try writer.writeAll(value.value_json);
    }
    try writer.writeByte('}');
}

fn writeAllFieldValuesObjectJson(
    writer: *std.Io.Writer,
    values: []const Parser.FieldJsonValue,
) !void {
    try writer.writeByte('{');
    for (values, 0..) |value, i| {
        if (i != 0) try writer.writeByte(',');
        try writer.print("{f}:", .{std.json.fmt(value.field, .{})});
        try writer.writeAll(value.value_json);
    }
    try writer.writeByte('}');
}

fn generatedColumnReferencesAny(column: runtime_schema.RelationalColumn, fields: []const []const u8) bool {
    const generated = column.generated orelse return false;
    if (generated.field) |field| {
        if (stringSlicesContains(fields, field)) return true;
    }
    return stringSlicesIntersect(generated.fields, fields);
}

fn uniqueConstraintReferencesAny(
    constraint: runtime_schema.UniqueConstraint,
    fields: []const []const u8,
) bool {
    if (stringSlicesIntersect(constraint.columns, fields)) return true;
    for (constraint.expressions) |expression| {
        if (stringSlicesContains(fields, expression.field)) return true;
    }
    for (constraint.where) |predicate| {
        if (stringSlicesContains(fields, predicate.field)) return true;
    }
    return false;
}

fn columnsMatchPrimaryKey(primary_key: runtime_schema.PrimaryKey, columns: []const []const u8) bool {
    return stringSlicesEqual(primary_key.columns, columns);
}

fn primaryKeyContains(primary_key: runtime_schema.PrimaryKey, field: []const u8) bool {
    for (primary_key.columns) |column| {
        if (std.mem.eql(u8, column, field)) return true;
    }
    return false;
}

fn aggregateOpForName(name: []const u8) ?db_mod.types.RelationalRowsAggregateOp {
    if (std.ascii.eqlIgnoreCase(name, "count")) return .count;
    if (std.ascii.eqlIgnoreCase(name, "sum")) return .sum;
    if (std.ascii.eqlIgnoreCase(name, "min")) return .min;
    if (std.ascii.eqlIgnoreCase(name, "max")) return .max;
    if (std.ascii.eqlIgnoreCase(name, "avg")) return .avg;
    if (std.ascii.eqlIgnoreCase(name, "array_agg")) return .array_agg;
    if (std.ascii.eqlIgnoreCase(name, "string_agg")) return .string_agg;
    if (std.ascii.eqlIgnoreCase(name, "bool_or")) return .bool_or;
    if (std.ascii.eqlIgnoreCase(name, "bool_and")) return .bool_and;
    return null;
}

fn aggregateOpName(op: db_mod.types.RelationalRowsAggregateOp) []const u8 {
    return switch (op) {
        .count => "count",
        .sum => "sum",
        .min => "min",
        .max => "max",
        .avg => "avg",
        .array_agg => "array_agg",
        .string_agg => "string_agg",
        .bool_or => "bool_or",
        .bool_and => "bool_and",
    };
}

fn validateAggregateGroupBy(
    group_fields: []const []const u8,
    group_expressions: []const db_mod.types.RelationalRowsExpressionProjection,
    group_by: []const []const u8,
    parsed_group_expressions: []const db_mod.types.RelationalRowsExpressionProjection,
) !void {
    if (!stringSlicesEqual(group_fields, group_by)) return error.UnsupportedSqlShape;
    if (group_expressions.len != parsed_group_expressions.len) return error.UnsupportedSqlShape;
    for (group_expressions, parsed_group_expressions) |selected, parsed| {
        if (!expressionEqual(selected.expression, parsed.expression)) return error.UnsupportedSqlShape;
    }
}

fn aggregateOutputFieldIsUnique(
    group_fields: []const []const u8,
    group_expressions: []const db_mod.types.RelationalRowsExpressionProjection,
    aggregations: []const db_mod.types.RelationalRowsAggregateSpec,
    field: []const u8,
) bool {
    var matches: usize = 0;
    for (group_fields) |group_field| {
        if (std.mem.eql(u8, group_field, field)) matches += 1;
    }
    for (group_expressions) |projection| {
        if (std.mem.eql(u8, projection.output, field)) matches += 1;
    }
    for (aggregations) |aggregation| {
        if (std.mem.eql(u8, aggregation.name, field)) matches += 1;
    }
    return matches == 1;
}

fn aggregateOutputColumnExists(columns: []const runtime_schema.RelationalColumn, name: []const u8) bool {
    for (columns) |column| {
        if (std.mem.eql(u8, column.name, name)) return true;
    }
    return false;
}

fn aggregateOutputType(aggregation: db_mod.types.RelationalRowsAggregateSpec) runtime_schema.AntflyType {
    return switch (aggregation.op) {
        .array_agg => .array,
        .string_agg => .keyword,
        .count, .sum, .min, .max, .avg => .numeric,
        .bool_or, .bool_and => .boolean,
    };
}

fn aggregateSpecsEquivalent(
    lhs: db_mod.types.RelationalRowsAggregateSpec,
    rhs: db_mod.types.RelationalRowsAggregateSpec,
) bool {
    if (lhs.op != rhs.op or lhs.distinct != rhs.distinct) return false;
    if (!optionalStringEqual(lhs.field, rhs.field)) return false;
    if (!optionalStringEqual(lhs.string_delimiter, rhs.string_delimiter)) return false;
    if (!optionalExpressionEqual(lhs.expression, rhs.expression)) return false;
    if (!orderByEqual(lhs.array_order_by, rhs.array_order_by)) return false;
    if (!relationalChecksEqual(lhs.filter_predicates, rhs.filter_predicates)) return false;
    if (!structuredValuePredicatesEqual(lhs.filter_array_any, rhs.filter_array_any)) return false;
    if (!structuredValuePredicatesEqual(lhs.filter_array_contains, rhs.filter_array_contains)) return false;
    if (!structuredValuePredicatesEqual(lhs.filter_array_eq, rhs.filter_array_eq)) return false;
    if (!inPredicatesEqual(lhs.filter_in_predicates, rhs.filter_in_predicates)) return false;
    if (!jsonContainsEqual(lhs.filter_json_contains, rhs.filter_json_contains)) return false;
    if (!jsonPathEqEqual(lhs.filter_json_path_eq, rhs.filter_json_path_eq)) return false;
    if (!jsonPathExistsEqual(lhs.filter_json_path_exists, rhs.filter_json_path_exists)) return false;
    if (!textPatternsEqual(lhs.filter_text_patterns, rhs.filter_text_patterns)) return false;
    if (!expressionConditionsEqual(lhs.filter_expressions, rhs.filter_expressions)) return false;
    if (!expressionArrayContainsEqual(lhs.filter_expression_array_contains, rhs.filter_expression_array_contains)) return false;
    if (!expressionPredicateGroupsEqual(lhs.filter_any, rhs.filter_any)) return false;
    if (!expressionPredicateGroupsEqual(lhs.filter_not, rhs.filter_not)) return false;
    return true;
}

fn optionalStringEqual(lhs: ?[]const u8, rhs: ?[]const u8) bool {
    if (lhs == null or rhs == null) return lhs == null and rhs == null;
    return std.mem.eql(u8, lhs.?, rhs.?);
}

fn optionalExpressionEqual(lhs: ?db_mod.types.RelationalRowsExpression, rhs: ?db_mod.types.RelationalRowsExpression) bool {
    if (lhs == null or rhs == null) return lhs == null and rhs == null;
    return expressionEqual(lhs.?, rhs.?);
}

fn expressionEqual(lhs: db_mod.types.RelationalRowsExpression, rhs: db_mod.types.RelationalRowsExpression) bool {
    if (lhs.kind != rhs.kind or
        lhs.field_source != rhs.field_source or
        lhs.json_as_text != rhs.json_as_text or
        lhs.cast_type != rhs.cast_type or
        !std.mem.eql(u8, lhs.field, rhs.field) or
        !std.mem.eql(u8, lhs.value_json, rhs.value_json) or
        !std.mem.eql(u8, lhs.json_path, rhs.json_path) or
        lhs.operands.len != rhs.operands.len or
        lhs.case_branches.len != rhs.case_branches.len or
        lhs.case_else.len != rhs.case_else.len)
    {
        return false;
    }
    for (lhs.operands, rhs.operands) |lhs_operand, rhs_operand| {
        if (!expressionEqual(lhs_operand, rhs_operand)) return false;
    }
    for (lhs.case_branches, rhs.case_branches) |lhs_branch, rhs_branch| {
        if (!expressionConditionEqual(lhs_branch.when, rhs_branch.when)) return false;
        if (!expressionEqual(lhs_branch.then, rhs_branch.then)) return false;
    }
    for (lhs.case_else, rhs.case_else) |lhs_else, rhs_else| {
        if (!expressionEqual(lhs_else, rhs_else)) return false;
    }
    return true;
}

fn orderByEqual(lhs: []const db_mod.types.RelationalRowsQueryOrder, rhs: []const db_mod.types.RelationalRowsQueryOrder) bool {
    if (lhs.len != rhs.len) return false;
    for (lhs, rhs) |lhs_order, rhs_order| {
        if (lhs_order.direction != rhs_order.direction or
            lhs_order.null_test != rhs_order.null_test or
            !std.mem.eql(u8, lhs_order.field, rhs_order.field) or
            !optionalExpressionEqual(lhs_order.expression, rhs_order.expression))
        {
            return false;
        }
    }
    return true;
}

fn relationalChecksEqual(lhs: []const runtime_schema.RelationalCheck, rhs: []const runtime_schema.RelationalCheck) bool {
    if (lhs.len != rhs.len) return false;
    for (lhs, rhs) |lhs_check, rhs_check| {
        if (!std.mem.eql(u8, lhs_check.name, rhs_check.name) or
            !std.mem.eql(u8, lhs_check.field, rhs_check.field) or
            lhs_check.op != rhs_check.op or
            !optionalStringEqual(lhs_check.value_json, rhs_check.value_json))
        {
            return false;
        }
    }
    return true;
}

fn structuredValuePredicatesEqual(lhs: anytype, rhs: @TypeOf(lhs)) bool {
    if (lhs.len != rhs.len) return false;
    for (lhs, rhs) |lhs_predicate, rhs_predicate| {
        if (!std.mem.eql(u8, lhs_predicate.field, rhs_predicate.field) or
            !std.mem.eql(u8, lhs_predicate.value_json, rhs_predicate.value_json))
        {
            return false;
        }
    }
    return true;
}

fn inPredicatesEqual(
    lhs: []const db_mod.types.RelationalRowsInPredicate,
    rhs: []const db_mod.types.RelationalRowsInPredicate,
) bool {
    if (lhs.len != rhs.len) return false;
    for (lhs, rhs) |lhs_predicate, rhs_predicate| {
        if (!std.mem.eql(u8, lhs_predicate.field, rhs_predicate.field) or
            !std.mem.eql(u8, lhs_predicate.values_json, rhs_predicate.values_json) or
            lhs_predicate.negated != rhs_predicate.negated)
        {
            return false;
        }
    }
    return true;
}

fn jsonContainsEqual(
    lhs: []const db_mod.types.RelationalRowsJsonContainsPredicate,
    rhs: []const db_mod.types.RelationalRowsJsonContainsPredicate,
) bool {
    if (lhs.len != rhs.len) return false;
    for (lhs, rhs) |lhs_predicate, rhs_predicate| {
        if (!std.mem.eql(u8, lhs_predicate.field, rhs_predicate.field) or
            !std.mem.eql(u8, lhs_predicate.value_json, rhs_predicate.value_json))
        {
            return false;
        }
    }
    return true;
}

fn jsonPathEqEqual(
    lhs: []const db_mod.types.RelationalRowsJsonPathEqPredicate,
    rhs: []const db_mod.types.RelationalRowsJsonPathEqPredicate,
) bool {
    if (lhs.len != rhs.len) return false;
    for (lhs, rhs) |lhs_predicate, rhs_predicate| {
        if (!std.mem.eql(u8, lhs_predicate.field, rhs_predicate.field) or
            !std.mem.eql(u8, lhs_predicate.path, rhs_predicate.path) or
            !std.mem.eql(u8, lhs_predicate.value_json, rhs_predicate.value_json))
        {
            return false;
        }
    }
    return true;
}

fn jsonPathExistsEqual(
    lhs: []const db_mod.types.RelationalRowsJsonPathExistsPredicate,
    rhs: []const db_mod.types.RelationalRowsJsonPathExistsPredicate,
) bool {
    if (lhs.len != rhs.len) return false;
    for (lhs, rhs) |lhs_predicate, rhs_predicate| {
        if (!std.mem.eql(u8, lhs_predicate.field, rhs_predicate.field) or
            !std.mem.eql(u8, lhs_predicate.path, rhs_predicate.path))
        {
            return false;
        }
    }
    return true;
}

fn textPatternsEqual(
    lhs: []const db_mod.types.RelationalRowsTextPatternPredicate,
    rhs: []const db_mod.types.RelationalRowsTextPatternPredicate,
) bool {
    if (lhs.len != rhs.len) return false;
    for (lhs, rhs) |lhs_predicate, rhs_predicate| {
        if (!std.mem.eql(u8, lhs_predicate.field, rhs_predicate.field) or
            !std.mem.eql(u8, lhs_predicate.pattern, rhs_predicate.pattern) or
            lhs_predicate.case_insensitive != rhs_predicate.case_insensitive or
            lhs_predicate.negated != rhs_predicate.negated)
        {
            return false;
        }
    }
    return true;
}

fn expressionConditionsEqual(
    lhs: []const db_mod.types.RelationalRowsExpressionCondition,
    rhs: []const db_mod.types.RelationalRowsExpressionCondition,
) bool {
    if (lhs.len != rhs.len) return false;
    for (lhs, rhs) |lhs_condition, rhs_condition| {
        if (!expressionConditionEqual(lhs_condition, rhs_condition)) return false;
    }
    return true;
}

fn expressionArrayContainsEqual(
    lhs: []const db_mod.types.RelationalRowsExpressionArrayContainsPredicate,
    rhs: []const db_mod.types.RelationalRowsExpressionArrayContainsPredicate,
) bool {
    if (lhs.len != rhs.len) return false;
    for (lhs, rhs) |lhs_predicate, rhs_predicate| {
        if (!expressionEqual(lhs_predicate.expression, rhs_predicate.expression) or
            !std.mem.eql(u8, lhs_predicate.value_json, rhs_predicate.value_json))
        {
            return false;
        }
    }
    return true;
}

fn expressionPredicateGroupsEqual(
    lhs: []const db_mod.types.RelationalRowsExpressionPredicateGroup,
    rhs: []const db_mod.types.RelationalRowsExpressionPredicateGroup,
) bool {
    if (lhs.len != rhs.len) return false;
    for (lhs, rhs) |lhs_group, rhs_group| {
        if (!expressionConditionsEqual(lhs_group.conditions, rhs_group.conditions)) return false;
    }
    return true;
}

fn expressionConditionEqual(
    lhs: db_mod.types.RelationalRowsExpressionCondition,
    rhs: db_mod.types.RelationalRowsExpressionCondition,
) bool {
    if (lhs.op != rhs.op or lhs.rhs.len != rhs.rhs.len or !expressionEqual(lhs.lhs, rhs.lhs)) return false;
    for (lhs.rhs, rhs.rhs) |lhs_rhs, rhs_rhs| {
        if (!expressionEqual(lhs_rhs, rhs_rhs)) return false;
    }
    return true;
}

fn joinSideForQualifier(
    qualifier: []const u8,
    left_alias: []const u8,
    right_alias: []const u8,
) !db_mod.types.RelationalRowsJoinProjectionSide {
    if (std.mem.eql(u8, qualifier, left_alias)) return .left;
    if (std.mem.eql(u8, qualifier, right_alias)) return .right;
    return error.UnsupportedSqlShape;
}

fn joinProjectionOutputIsUnique(select: []const db_mod.types.RelationalRowsJoinProjection, field: []const u8) bool {
    var matches: usize = 0;
    for (select) |projection| {
        if (std.mem.eql(u8, projection.output, field)) matches += 1;
    }
    return matches == 1;
}

fn identifierContainsQualifier(identifier: []const u8) bool {
    const dot = std.mem.indexOfScalar(u8, identifier, '.') orelse return false;
    return dot > 0 and dot + 1 < identifier.len;
}

fn isSupportedUpdatedAtTriggerFunction(name: []const u8) bool {
    const dot = std.mem.lastIndexOfScalar(u8, name, '.');
    const base = if (dot) |index| name[index + 1 ..] else name;
    return std.ascii.eqlIgnoreCase(base, "touch_updated_at") or
        std.ascii.eqlIgnoreCase(base, "set_updated_at") or
        std.ascii.eqlIgnoreCase(base, "update_updated_at") or
        std.ascii.eqlIgnoreCase(base, "antfly_on_update_now") or
        std.ascii.eqlIgnoreCase(base, "antfly_touch_updated_at");
}

fn findDdlColumn(columns: []const runtime_schema.RelationalColumn, name: []const u8) ?runtime_schema.RelationalColumn {
    for (columns) |column| {
        if (std.mem.eql(u8, column.name, name)) return column;
    }
    return null;
}

fn ddlBaseTypeForName(name: []const u8) ?runtime_schema.AntflyType {
    if (std.ascii.eqlIgnoreCase(name, "uuid")) return .keyword;
    if (std.ascii.eqlIgnoreCase(name, "text")) return .keyword;
    if (std.ascii.eqlIgnoreCase(name, "varchar")) return .keyword;
    if (std.ascii.eqlIgnoreCase(name, "citext")) return .keyword;
    if (std.ascii.eqlIgnoreCase(name, "integer")) return .numeric;
    if (std.ascii.eqlIgnoreCase(name, "int")) return .numeric;
    if (std.ascii.eqlIgnoreCase(name, "int4")) return .numeric;
    if (std.ascii.eqlIgnoreCase(name, "bigint")) return .numeric;
    if (std.ascii.eqlIgnoreCase(name, "int8")) return .numeric;
    if (std.ascii.eqlIgnoreCase(name, "smallint")) return .numeric;
    if (std.ascii.eqlIgnoreCase(name, "numeric")) return .numeric;
    if (std.ascii.eqlIgnoreCase(name, "decimal")) return .numeric;
    if (std.ascii.eqlIgnoreCase(name, "real")) return .numeric;
    if (std.ascii.eqlIgnoreCase(name, "float4")) return .numeric;
    if (std.ascii.eqlIgnoreCase(name, "float8")) return .numeric;
    if (std.ascii.eqlIgnoreCase(name, "boolean")) return .boolean;
    if (std.ascii.eqlIgnoreCase(name, "bool")) return .boolean;
    if (std.ascii.eqlIgnoreCase(name, "date")) return .datetime;
    if (std.ascii.eqlIgnoreCase(name, "timestamptz")) return .datetime;
    if (std.ascii.eqlIgnoreCase(name, "json")) return .json;
    if (std.ascii.eqlIgnoreCase(name, "jsonb")) return .json;
    if (std.ascii.eqlIgnoreCase(name, "bytea")) return .blob;
    return null;
}

fn ddlRangeBoundTypeForName(name: []const u8) ?runtime_schema.AntflyType {
    if (std.ascii.eqlIgnoreCase(name, "daterange")) return .datetime;
    if (std.ascii.eqlIgnoreCase(name, "tsrange")) return .datetime;
    if (std.ascii.eqlIgnoreCase(name, "tstzrange")) return .datetime;
    if (std.ascii.eqlIgnoreCase(name, "numrange")) return .numeric;
    return null;
}

fn ddlRangeTypeForName(name: []const u8) ?runtime_schema.RelationalPeriodRangeType {
    if (std.ascii.eqlIgnoreCase(name, "numrange")) return .numrange;
    if (std.ascii.eqlIgnoreCase(name, "daterange")) return .daterange;
    if (std.ascii.eqlIgnoreCase(name, "tsrange")) return .tsrange;
    if (std.ascii.eqlIgnoreCase(name, "tstzrange")) return .tstzrange;
    return null;
}

fn relationalPeriodRangeTypeName(range_type: runtime_schema.RelationalPeriodRangeType) []const u8 {
    return switch (range_type) {
        .numrange => "numrange",
        .daterange => "daterange",
        .tsrange => "tsrange",
        .tstzrange => "tstzrange",
    };
}

fn relationalCheckOpToken(op: runtime_schema.RelationalCheckOp) []const u8 {
    return switch (op) {
        .is_null => "is_null",
        .is_not_null => "is_not_null",
        .is_distinct => "is_distinct",
        .is_not_distinct => "is_not_distinct",
        .eq => "eq",
        .ne => "ne",
        .gt => "gt",
        .gte => "gte",
        .lt => "lt",
        .lte => "lte",
    };
}

fn schemaJsonValueFromCreateTablePlanAlloc(alloc: std.mem.Allocator, plan: CreateTablePlan) !std.json.Value {
    var properties = std.json.ObjectMap.empty;
    for (plan.columns) |column| {
        try properties.put(alloc, try alloc.dupe(u8, column.name), try schemaJsonPropertyFromColumnAlloc(alloc, column));
    }

    var required = std.json.Array.init(alloc);
    for (plan.columns) |column| {
        if (!column.nullable) try required.append(.{ .string = try alloc.dupe(u8, column.name) });
    }

    var row_schema = std.json.ObjectMap.empty;
    try putJsonString(alloc, &row_schema, "type", "object");
    try row_schema.put(alloc, try alloc.dupe(u8, "properties"), .{ .object = properties });
    if (required.items.len > 0) try row_schema.put(alloc, try alloc.dupe(u8, "required"), .{ .array = required });
    try row_schema.put(alloc, try alloc.dupe(u8, "additionalProperties"), .{ .bool = false });

    var document_schema = std.json.ObjectMap.empty;
    try document_schema.put(alloc, try alloc.dupe(u8, "schema"), .{ .object = row_schema });

    var document_schemas = std.json.ObjectMap.empty;
    try document_schemas.put(alloc, try alloc.dupe(u8, "row"), .{ .object = document_schema });

    var root = std.json.ObjectMap.empty;
    try putJsonString(alloc, &root, "storage_mode", "relational");
    try putJsonString(alloc, &root, "default_type", "row");
    try root.put(alloc, try alloc.dupe(u8, "enforce_types"), .{ .bool = true });
    try root.put(alloc, try alloc.dupe(u8, "document_schemas"), .{ .object = document_schemas });
    if (plan.primary_key) |primary_key| try root.put(alloc, try alloc.dupe(u8, "primary_key"), try schemaJsonPrimaryKeyAlloc(alloc, primary_key));
    if (plan.periods.len > 0) try root.put(alloc, try alloc.dupe(u8, "periods"), try schemaJsonPeriodsAlloc(alloc, plan.periods));
    if (plan.unique_constraints.len > 0) try root.put(alloc, try alloc.dupe(u8, "unique_constraints"), try schemaJsonUniqueConstraintsAlloc(alloc, plan.unique_constraints));
    if (plan.foreign_keys.len > 0) try root.put(alloc, try alloc.dupe(u8, "foreign_keys"), try schemaJsonForeignKeysAlloc(alloc, plan.foreign_keys));
    if (plan.checks.len > 0) try root.put(alloc, try alloc.dupe(u8, "checks"), try schemaJsonRelationalChecksAlloc(alloc, plan.checks));
    return .{ .object = root };
}

fn applyCreateIndexPlanToSchemaJsonValue(
    alloc: std.mem.Allocator,
    root: *std.json.ObjectMap,
    plan: CreateIndexPlan,
) !bool {
    const schema_parts = try relationalSchemaJsonParts(root);
    if (try schemaJsonIndexNameExists(schema_parts.properties, root.getPtr("unique_constraints"), plan.index_name)) {
        if (plan.if_not_exists) return false;
        return error.InvalidSqlCatalog;
    }
    if (plan.method == .gin) {
        if (plan.unique or plan.columns.len != 1 or plan.include_columns.len != 0 or plan.expressions.len != 0 or plan.generated_expression != null) return error.UnsupportedSqlShape;
        const property_type = try schemaJsonPropertyType(schema_parts.properties, plan.columns[0]);
        if (std.mem.eql(u8, property_type, "json")) {
            if (plan.opclass == .array_ops) return error.InvalidSqlCatalog;
        } else if (std.mem.eql(u8, property_type, "array")) {
            if (plan.opclass == .jsonb_path_ops) return error.InvalidSqlCatalog;
        } else return error.InvalidSqlCatalog;
    }
    if (plan.unique) {
        try validateCreateIndexIncludeColumnsForSchemaJsonProperties(schema_parts.properties, plan.columns, plan.include_columns);
        const constraint: runtime_schema.UniqueConstraint = .{
            .name = plan.index_name,
            .columns = plan.columns,
            .expressions = plan.expressions,
            .include_columns = plan.include_columns,
            .without_overlaps_period = plan.without_overlaps_period,
            .where = plan.where,
            .where_expressions = plan.where_expressions,
            .validation_state = .unvalidated,
        };
        var constraints = try rootArrayFieldAlloc(alloc, root, "unique_constraints");
        try constraints.append(try schemaJsonUniqueConstraintAlloc(alloc, constraint));
        return true;
    }

    const index_generation = stableSecondaryIndexGeneration(plan);
    if (plan.generated_expression) |generated_expression| {
        if (plan.columns.len != 0 or plan.include_columns.len != 0 or plan.expressions.len != 0) return error.UnsupportedSqlShape;
        try validateGeneratedExpressionForSchemaJsonProperties(schema_parts.properties, plan.index_name, generated_expression);
        const column: runtime_schema.RelationalColumn = .{
            .name = plan.index_name,
            .path = plan.index_name,
            .field_type = .keyword,
            .nullable = true,
            .indexed = true,
            .index_lifecycle = .building,
            .index_generation = index_generation,
            .index_name = plan.index_name,
            .generated = generated_expression,
            .index_where = plan.where,
            .index_where_expressions = plan.where_expressions,
        };
        try schema_parts.properties.put(alloc, try alloc.dupe(u8, plan.index_name), try schemaJsonPropertyFromColumnAlloc(alloc, column));
        return true;
    }

    if (plan.columns.len == 0 or plan.expressions.len != 0) return error.UnsupportedSqlShape;
    try validateCreateIndexIncludeColumnsForSchemaJsonProperties(schema_parts.properties, plan.columns, plan.include_columns);
    for (plan.columns) |column| {
        const property = schema_parts.properties.getPtr(column) orelse return error.InvalidSqlCatalog;
        if (property.* != .object) return error.InvalidSqlCatalog;
        if (property.object.get("x-antfly-index-name")) |existing| {
            if (existing != .string or !std.mem.eql(u8, existing.string, plan.index_name)) return error.InvalidSqlCatalog;
        }
    }
    for (plan.columns) |column| {
        const property = schema_parts.properties.getPtr(column) orelse return error.InvalidSqlCatalog;
        if (property.* != .object) return error.InvalidSqlCatalog;
        try property.object.put(alloc, try alloc.dupe(u8, "x-antfly-index"), .{ .bool = true });
        try putJsonString(alloc, &property.object, "x-antfly-index-lifecycle", "building");
        try property.object.put(alloc, try alloc.dupe(u8, "x-antfly-index-generation"), .{ .integer = @intCast(index_generation) });
        try putJsonString(alloc, &property.object, "x-antfly-index-name", plan.index_name);
        if (plan.include_columns.len > 0) try property.object.put(alloc, try alloc.dupe(u8, "x-antfly-index-include"), try schemaJsonStringArrayAlloc(alloc, plan.include_columns));
        if (plan.where.len > 0) try property.object.put(alloc, try alloc.dupe(u8, "x-antfly-index-where"), try schemaJsonUniquePredicateDefinitionAlloc(alloc, plan.where));
        if (plan.where_expressions.len > 0) try property.object.put(alloc, try alloc.dupe(u8, "x-antfly-index-where-expressions"), try schemaJsonExpressionConditionsAlloc(alloc, plan.where_expressions));
    }
    return true;
}

fn applyDropIndexPlanToSchemaJsonValue(
    alloc: std.mem.Allocator,
    root: *std.json.ObjectMap,
    plan: DropIndexPlan,
) !void {
    if (try removeNamedConstraintFromJsonArray(root.getPtr("unique_constraints"), plan.index_name)) {
        removeCommentMapEntry(root, "indexes", plan.index_name);
        return;
    }
    const schema_parts = try relationalSchemaJsonParts(root);
    const property = schemaJsonPropertyForSecondaryIndex(schema_parts.properties, plan.index_name) orelse {
        if (plan.if_exists) return;
        return error.InvalidSqlCatalog;
    };
    if (property.* != .object) return error.InvalidSqlCatalog;
    if (property.object.get("generated") != null) {
        if (!schema_parts.properties.orderedRemove(plan.index_name)) return error.InvalidSqlCatalog;
        return;
    }
    var removed = false;
    var it = schema_parts.properties.iterator();
    while (it.next()) |entry| {
        if (entry.value_ptr.* != .object) continue;
        if (!schemaJsonPropertyHasSecondaryIndexName(entry.value_ptr.*, plan.index_name)) continue;
        if (entry.value_ptr.object.get("generated") != null) return error.InvalidSqlCatalog;
        try entry.value_ptr.object.put(alloc, try alloc.dupe(u8, "x-antfly-index"), .{ .bool = false });
        _ = entry.value_ptr.object.orderedRemove("x-antfly-index-lifecycle");
        _ = entry.value_ptr.object.orderedRemove("x-antfly-index-generation");
        _ = entry.value_ptr.object.orderedRemove("x-antfly-index-name");
        _ = entry.value_ptr.object.orderedRemove("x-antfly-index-include");
        _ = entry.value_ptr.object.orderedRemove("x-antfly-index-where");
        _ = entry.value_ptr.object.orderedRemove("x-antfly-index-where-expressions");
        removed = true;
    }
    if (!removed) return error.InvalidSqlCatalog;
    removeCommentMapEntry(root, "indexes", plan.index_name);
}

fn addColumnOperationToSchemaJsonValue(
    alloc: std.mem.Allocator,
    root: *std.json.ObjectMap,
    schema_parts: RelationalSchemaJsonParts,
    operation: AddColumnOperation,
) !void {
    if (schema_parts.properties.get(operation.column.name) != null) {
        if (operation.if_not_exists) return;
        return error.InvalidSqlCatalog;
    }
    try schema_parts.properties.put(alloc, try alloc.dupe(u8, operation.column.name), try schemaJsonPropertyFromColumnAlloc(alloc, operation.column));
    if (!operation.column.nullable) {
        var required = try rootArrayFieldAlloc(alloc, schema_parts.schema, "required");
        try required.append(.{ .string = try alloc.dupe(u8, operation.column.name) });
    }
    if (operation.unique_constraints.len > 0) {
        var constraints = try rootArrayFieldAlloc(alloc, root, "unique_constraints");
        for (operation.unique_constraints) |constraint| try constraints.append(try schemaJsonUniqueConstraintAlloc(alloc, constraint));
    }
    if (operation.foreign_keys.len > 0) {
        var foreign_keys = try rootArrayFieldAlloc(alloc, root, "foreign_keys");
        for (operation.foreign_keys) |foreign_key| try foreign_keys.append(try schemaJsonForeignKeyAlloc(alloc, foreign_key));
    }
    if (operation.checks.len > 0) {
        var checks = try rootArrayFieldAlloc(alloc, root, "checks");
        for (operation.checks) |check| try checks.append(try schemaJsonRelationalCheckAlloc(alloc, check));
    }
}

fn applyAlterTablePlanToSchemaJsonValue(
    alloc: std.mem.Allocator,
    root: *std.json.ObjectMap,
    plan: AlterTablePlan,
) !void {
    const schema_parts = try relationalSchemaJsonParts(root);
    for (plan.operations) |operation| {
        switch (operation) {
            .add_column => |add_column| try addColumnOperationToSchemaJsonValue(alloc, root, schema_parts, add_column),
            .add_period => |period| {
                var periods = try rootArrayFieldAlloc(alloc, root, "periods");
                try periods.append(try schemaJsonPeriodAlloc(alloc, period));
            },
            .add_primary_key => |primary_key| {
                if (root.get("primary_key") != null) return error.InvalidSqlCatalog;
                try root.put(alloc, try alloc.dupe(u8, "primary_key"), try schemaJsonPrimaryKeyAlloc(alloc, primary_key));
            },
            .rename_column => |rename_column| try renameColumnInSchemaJsonValue(alloc, root, schema_parts, rename_column),
            .rename_constraint => |rename_constraint| try renameConstraintInSchemaJsonValue(alloc, root, plan.table_name, rename_constraint),
            .drop_column => |drop_column| try dropColumnFromSchemaJsonValue(alloc, root, schema_parts, drop_column),
            .drop_constraint => |drop_constraint| try dropConstraintFromSchemaJsonValue(root, plan.table_name, drop_constraint),
            .drop_update_policy => |drop_update_policy| try dropUpdatePolicyFromSchemaJsonValue(schema_parts, drop_update_policy),
            .alter_column_default => |alter_column_default| try alterColumnDefaultInSchemaJsonValue(alloc, schema_parts, alter_column_default),
            .alter_column_nullability => |alter_column_nullability| try alterColumnNullabilityInSchemaJsonValue(alloc, root, schema_parts, alter_column_nullability),
            .alter_column_type => |alter_column_type| try alterColumnTypeInSchemaJsonValue(alloc, schema_parts, alter_column_type),
            .add_unique_constraint => |constraint| {
                var constraints = try rootArrayFieldAlloc(alloc, root, "unique_constraints");
                try constraints.append(try schemaJsonUniqueConstraintAlloc(alloc, constraint));
            },
            .add_foreign_key => |foreign_key| {
                var foreign_keys = try rootArrayFieldAlloc(alloc, root, "foreign_keys");
                try foreign_keys.append(try schemaJsonForeignKeyAlloc(alloc, foreign_key));
            },
            .add_check => |check| {
                var checks = try rootArrayFieldAlloc(alloc, root, "checks");
                try checks.append(try schemaJsonRelationalCheckAlloc(alloc, check));
            },
            .validate_constraint => |constraint_name| try validateConstraintByNameInSchemaJson(alloc, root, plan.table_name, constraint_name),
        }
    }
    try pruneSchemaJsonCommentsForCurrentSchema(root, plan.table_name);
}

fn applyCreateUpdatePolicyPlanToSchemaJsonValue(
    alloc: std.mem.Allocator,
    root: *std.json.ObjectMap,
    plan: CreateUpdatePolicyPlan,
) !void {
    const schema_parts = try relationalSchemaJsonParts(root);
    const property = schema_parts.properties.getPtr(plan.column_name) orelse return error.InvalidSqlCatalog;
    if (property.* != .object) return error.InvalidSqlCatalog;
    try property.object.put(alloc, try alloc.dupe(u8, "x-antfly-on-update"), try schemaJsonDefaultValueAlloc(alloc, plan.on_update_value, true));
}

fn applyCommentMetadataPlanToSchemaJsonValue(
    alloc: std.mem.Allocator,
    root: *std.json.ObjectMap,
    plan: CommentMetadataPlan,
) !void {
    const schema_parts = try relationalSchemaJsonParts(root);
    if (plan.object_name.len == 0) return error.InvalidSqlCatalog;

    const comments = try rootObjectFieldAlloc(alloc, root, "comments");
    switch (plan.target) {
        .table => try applyStringCommentValueToObject(alloc, comments, "table", plan.comment_json),
        .column => {
            const column_name = commentColumnName(plan.object_name);
            const property = schema_parts.properties.getPtr(column_name) orelse return error.InvalidSqlCatalog;
            if (property.* != .object) return error.InvalidSqlCatalog;
            const columns = try rootObjectFieldAlloc(alloc, comments, "columns");
            try applyStringCommentValueToObject(alloc, columns, column_name, plan.comment_json);
            removeEmptyCommentMap(comments, "columns");
        },
        .index => {
            if (!try schemaJsonIndexNameExists(schema_parts.properties, root.getPtr("unique_constraints"), plan.object_name)) return error.InvalidSqlCatalog;
            const indexes = try rootObjectFieldAlloc(alloc, comments, "indexes");
            try applyStringCommentValueToObject(alloc, indexes, plan.object_name, plan.comment_json);
            removeEmptyCommentMap(comments, "indexes");
        },
        .constraint => {
            const parent_table = plan.parent_table_name orelse return error.InvalidSqlCatalog;
            if (!try jsonConstraintNameExists(root, parent_table, plan.object_name)) return error.InvalidSqlCatalog;
            const constraints = try rootObjectFieldAlloc(alloc, comments, "constraints");
            try applyStringCommentValueToObject(alloc, constraints, plan.object_name, plan.comment_json);
            removeEmptyCommentMap(comments, "constraints");
        },
    }
    if (try schemaJsonCommentCountInObject(comments) == 0) _ = root.orderedRemove("comments");
}

fn commentColumnName(object_name: []const u8) []const u8 {
    const dot = std.mem.lastIndexOfScalar(u8, object_name, '.') orelse return object_name;
    return object_name[dot + 1 ..];
}

fn applyStringCommentValueToObject(
    alloc: std.mem.Allocator,
    object: *std.json.ObjectMap,
    key: []const u8,
    comment_json: ?[]const u8,
) !void {
    const raw = comment_json orelse {
        _ = object.orderedRemove(key);
        return;
    };
    var parsed = try std.json.parseFromSlice(std.json.Value, alloc, raw, .{});
    defer parsed.deinit();
    const value = switch (parsed.value) {
        .string => |value| value,
        else => return error.UnsupportedSqlShape,
    };
    try putJsonString(alloc, object, key, value);
}

fn removeEmptyCommentMap(comments: *std.json.ObjectMap, key: []const u8) void {
    const value = comments.get(key) orelse return;
    if (value != .object or value.object.count() != 0) return;
    _ = comments.orderedRemove(key);
}

fn schemaJsonCommentCountInRoot(root: *std.json.ObjectMap) !usize {
    const comments = root.get("comments") orelse return 0;
    if (comments != .object) return error.InvalidSqlCatalog;
    return try schemaJsonCommentCountInObject(&comments.object);
}

fn schemaJsonCommentCountInObject(comments: *const std.json.ObjectMap) !usize {
    var count: usize = 0;
    if (comments.get("table")) |table| {
        if (table != .string) return error.InvalidSqlCatalog;
        count += 1;
    }
    count += try schemaJsonCommentMapCount(comments.get("columns"));
    count += try schemaJsonCommentMapCount(comments.get("indexes"));
    count += try schemaJsonCommentMapCount(comments.get("constraints"));
    return count;
}

fn schemaJsonCommentMapCount(value: ?std.json.Value) !usize {
    const object_value = value orelse return 0;
    if (object_value != .object) return error.InvalidSqlCatalog;
    var it = object_value.object.iterator();
    var count: usize = 0;
    while (it.next()) |entry| {
        if (entry.value_ptr.* != .string) return error.InvalidSqlCatalog;
        count += 1;
    }
    return count;
}

fn removeCommentMapEntry(root: *std.json.ObjectMap, map_name: []const u8, key: []const u8) void {
    const comments_value = root.getPtr("comments") orelse return;
    if (comments_value.* != .object) return;
    const map_value = comments_value.object.getPtr(map_name) orelse return;
    if (map_value.* != .object) return;
    _ = map_value.object.orderedRemove(key);
    removeEmptyCommentMap(&comments_value.object, map_name);
    if ((schemaJsonCommentCountInObject(&comments_value.object) catch 1) == 0) _ = root.orderedRemove("comments");
}

fn renameCommentMapEntry(
    alloc: std.mem.Allocator,
    root: *std.json.ObjectMap,
    map_name: []const u8,
    old_name: []const u8,
    new_name: []const u8,
) !void {
    const comments_value = root.getPtr("comments") orelse return;
    if (comments_value.* != .object) return error.InvalidSqlCatalog;
    const map_value = comments_value.object.getPtr(map_name) orelse return;
    if (map_value.* != .object) return error.InvalidSqlCatalog;
    const comment = map_value.object.get(old_name) orelse return;
    if (comment != .string) return error.InvalidSqlCatalog;
    _ = map_value.object.orderedRemove(old_name);
    try putJsonString(alloc, &map_value.object, new_name, comment.string);
}

fn pruneSchemaJsonCommentsForCurrentSchema(root: *std.json.ObjectMap, table_name: []const u8) !void {
    const comments_value = root.getPtr("comments") orelse return;
    if (comments_value.* != .object) return error.InvalidSqlCatalog;
    const schema_parts = try relationalSchemaJsonParts(root);

    if (comments_value.object.getPtr("columns")) |columns| {
        if (columns.* != .object) return error.InvalidSqlCatalog;
        while (true) {
            var removed = false;
            var it = columns.object.iterator();
            while (it.next()) |entry| {
                if (entry.value_ptr.* != .string) return error.InvalidSqlCatalog;
                if (schema_parts.properties.get(entry.key_ptr.*) != null) continue;
                _ = columns.object.orderedRemove(entry.key_ptr.*);
                removed = true;
                break;
            }
            if (!removed) break;
        }
        removeEmptyCommentMap(&comments_value.object, "columns");
    }
    if (comments_value.object.getPtr("indexes")) |indexes| {
        if (indexes.* != .object) return error.InvalidSqlCatalog;
        while (true) {
            var removed = false;
            var it = indexes.object.iterator();
            while (it.next()) |entry| {
                if (entry.value_ptr.* != .string) return error.InvalidSqlCatalog;
                if (try schemaJsonIndexNameExists(schema_parts.properties, root.getPtr("unique_constraints"), entry.key_ptr.*)) continue;
                _ = indexes.object.orderedRemove(entry.key_ptr.*);
                removed = true;
                break;
            }
            if (!removed) break;
        }
        removeEmptyCommentMap(&comments_value.object, "indexes");
    }
    if (comments_value.object.getPtr("constraints")) |constraints| {
        if (constraints.* != .object) return error.InvalidSqlCatalog;
        while (true) {
            var removed = false;
            var it = constraints.object.iterator();
            while (it.next()) |entry| {
                if (entry.value_ptr.* != .string) return error.InvalidSqlCatalog;
                if (try jsonConstraintNameExists(root, table_name, entry.key_ptr.*)) continue;
                _ = constraints.object.orderedRemove(entry.key_ptr.*);
                removed = true;
                break;
            }
            if (!removed) break;
        }
        removeEmptyCommentMap(&comments_value.object, "constraints");
    }
    if (try schemaJsonCommentCountInObject(&comments_value.object) == 0) _ = root.orderedRemove("comments");
}

fn dropUpdatePolicyFromSchemaJsonValue(
    schema_parts: RelationalSchemaJsonParts,
    operation: DropUpdatePolicyOperation,
) !void {
    _ = operation.trigger_name;
    var policy_count: usize = 0;
    var it = schema_parts.properties.iterator();
    while (it.next()) |entry| {
        if (entry.value_ptr.* != .object) return error.InvalidSqlCatalog;
        if (entry.value_ptr.object.get("x-antfly-on-update") == null) continue;
        policy_count += 1;
    }
    if (policy_count == 0) {
        if (operation.if_exists) return;
        return error.InvalidSqlCatalog;
    }
    if (policy_count > 1) return error.InvalidSqlCatalog;

    var remove_it = schema_parts.properties.iterator();
    while (remove_it.next()) |entry| {
        if (entry.value_ptr.object.get("x-antfly-on-update") == null) continue;
        _ = entry.value_ptr.object.orderedRemove("x-antfly-on-update");
        return;
    }
    return error.InvalidSqlCatalog;
}

fn renameColumnInSchemaJsonValue(
    alloc: std.mem.Allocator,
    root: *std.json.ObjectMap,
    schema_parts: RelationalSchemaJsonParts,
    operation: RenameColumnOperation,
) !void {
    if (std.mem.eql(u8, operation.old_name, operation.new_name)) return error.InvalidSqlCatalog;
    if (schema_parts.properties.get(operation.new_name) != null) return error.InvalidSqlCatalog;
    const property = schema_parts.properties.get(operation.old_name) orelse return error.InvalidSqlCatalog;
    _ = schema_parts.properties.orderedRemove(operation.old_name);
    try schema_parts.properties.put(alloc, try alloc.dupe(u8, operation.new_name), property);

    try renameStringInJsonArray(alloc, schema_parts.schema.getPtr("required"), operation.old_name, operation.new_name);
    if (root.getPtr("primary_key")) |primary_key| try renamePrimaryKeyJsonFields(alloc, primary_key, operation.old_name, operation.new_name);

    var property_it = schema_parts.properties.iterator();
    while (property_it.next()) |entry| {
        try renameSchemaPropertyReferences(alloc, entry.value_ptr, operation.old_name, operation.new_name);
    }

    try renameConstraintArrayFields(alloc, root.getPtr("unique_constraints"), operation.old_name, operation.new_name, .unique);
    try renameConstraintArrayFields(alloc, root.getPtr("foreign_keys"), operation.old_name, operation.new_name, .foreign_key);
    try renameConstraintArrayFields(alloc, root.getPtr("checks"), operation.old_name, operation.new_name, .check);
    try renameCommentMapEntry(alloc, root, "columns", operation.old_name, operation.new_name);
}

fn dropColumnFromSchemaJsonValue(
    alloc: std.mem.Allocator,
    root: *std.json.ObjectMap,
    schema_parts: RelationalSchemaJsonParts,
    drop_column: DropColumnOperation,
) !void {
    if (schema_parts.properties.get(drop_column.name) == null) {
        if (drop_column.if_exists) return;
        return error.InvalidSqlCatalog;
    }

    var dropped = std.ArrayListUnmanaged([]const u8).empty;
    defer dropped.deinit(alloc);
    try appendUniqueBorrowedString(alloc, &dropped, drop_column.name);

    var changed = true;
    while (changed) {
        changed = false;
        var it = schema_parts.properties.iterator();
        while (it.next()) |entry| {
            if (stringSlicesContains(dropped.items, entry.key_ptr.*)) continue;
            if (propertyGeneratedReferencesAny(entry.value_ptr.*, dropped.items)) {
                try appendUniqueBorrowedString(alloc, &dropped, entry.key_ptr.*);
                changed = true;
            }
        }
    }

    try rejectPrimaryKeyDropFromSchemaJson(root, dropped.items);
    if (drop_column.dependency_mode == .restrict and try schemaJsonHasDropDependencies(root, dropped.items)) {
        return error.InvalidSqlCatalog;
    }

    for (dropped.items) |name| {
        if (!schema_parts.properties.orderedRemove(name)) return error.InvalidSqlCatalog;
    }
    try removeStringsFromJsonArray(schema_parts.schema.getPtr("required"), dropped.items);
    try removeDependentConstraintsFromJsonArray(root.getPtr("unique_constraints"), dropped.items, .unique);
    try removeDependentConstraintsFromJsonArray(root.getPtr("foreign_keys"), dropped.items, .foreign_key);
    try removeDependentConstraintsFromJsonArray(root.getPtr("checks"), dropped.items, .check);
}

fn schemaJsonHasDropDependencies(root: *std.json.ObjectMap, dropped: []const []const u8) !bool {
    if (dropped.len > 1) return true;
    if (try jsonConstraintArrayReferencesAny(root.getPtr("unique_constraints"), dropped, .unique)) return true;
    if (try jsonConstraintArrayReferencesAny(root.getPtr("foreign_keys"), dropped, .foreign_key)) return true;
    if (try jsonConstraintArrayReferencesAny(root.getPtr("checks"), dropped, .check)) return true;
    const schema_parts = try relationalSchemaJsonParts(root);
    var it = schema_parts.properties.iterator();
    while (it.next()) |entry| {
        if (schemaJsonSecondaryIndexReferencesAny(entry.value_ptr.*, dropped)) return true;
    }
    return false;
}

fn jsonConstraintArrayReferencesAny(
    value: ?*std.json.Value,
    fields: []const []const u8,
    kind: JsonConstraintKind,
) !bool {
    const array_value = value orelse return false;
    if (array_value.* != .array) return error.InvalidSqlCatalog;
    for (array_value.array.items) |item| {
        if (item != .object) return error.InvalidSqlCatalog;
        const references = switch (kind) {
            .unique => jsonUniqueConstraintReferencesAny(item, fields),
            .foreign_key => jsonStringArrayReferencesAny(item.object.get("columns") orelse return error.InvalidSqlCatalog, fields),
            .check => blk: {
                const field = item.object.get("field") orelse return error.InvalidSqlCatalog;
                break :blk field == .string and stringSlicesContains(fields, field.string);
            },
        };
        if (references) return true;
    }
    return false;
}

fn validateConstraintByNameInSchemaJson(
    alloc: std.mem.Allocator,
    root: *std.json.ObjectMap,
    table_name: []const u8,
    constraint_name: []const u8,
) !void {
    if (try schemaJsonPrimaryKeyNameEquals(root, table_name, constraint_name)) return;
    if (try setNamedConstraintValidationStateInArray(alloc, root, "unique_constraints", constraint_name, "enforced")) return;
    if (try setNamedConstraintValidationStateInArray(alloc, root, "foreign_keys", constraint_name, "enforced")) return;
    if (try setNamedConstraintValidationStateInArray(alloc, root, "checks", constraint_name, "enforced")) return;
    return error.InvalidSqlCatalog;
}

fn dropConstraintFromSchemaJsonValue(
    root: *std.json.ObjectMap,
    table_name: []const u8,
    drop_constraint: DropConstraintOperation,
) !void {
    if (try dropPrimaryKeyFromSchemaJsonValue(root, table_name, drop_constraint.name)) {
        removeCommentMapEntry(root, "constraints", drop_constraint.name);
        return;
    }
    if (try removeNamedConstraintFromJsonArray(root.getPtr("unique_constraints"), drop_constraint.name)) return;
    if (try removeNamedConstraintFromJsonArray(root.getPtr("foreign_keys"), drop_constraint.name)) return;
    if (try removeNamedConstraintFromJsonArray(root.getPtr("checks"), drop_constraint.name)) return;
    if (drop_constraint.if_exists) return;
    return error.InvalidSqlCatalog;
}

fn dropPrimaryKeyFromSchemaJsonValue(
    root: *std.json.ObjectMap,
    table_name: []const u8,
    constraint_name: []const u8,
) !bool {
    if (!try schemaJsonPrimaryKeyNameEquals(root, table_name, constraint_name)) return false;
    _ = root.orderedRemove("primary_key");
    return true;
}

fn renameConstraintInSchemaJsonValue(
    alloc: std.mem.Allocator,
    root: *std.json.ObjectMap,
    table_name: []const u8,
    operation: RenameConstraintOperation,
) !void {
    if (std.mem.eql(u8, operation.old_name, operation.new_name)) return error.InvalidSqlCatalog;
    if (try jsonConstraintNameExists(root, table_name, operation.new_name)) return error.InvalidSqlCatalog;
    const renamed =
        try renamePrimaryKeyConstraintInSchemaJsonValue(alloc, root, table_name, operation.old_name, operation.new_name) or
        try renameNamedConstraintInJsonArray(alloc, root.getPtr("unique_constraints"), operation.old_name, operation.new_name) or
        try renameNamedConstraintInJsonArray(alloc, root.getPtr("foreign_keys"), operation.old_name, operation.new_name) or
        try renameNamedConstraintInJsonArray(alloc, root.getPtr("checks"), operation.old_name, operation.new_name);
    if (!renamed) return error.InvalidSqlCatalog;
    try renameCommentMapEntry(alloc, root, "constraints", operation.old_name, operation.new_name);
    try renameCommentMapEntry(alloc, root, "indexes", operation.old_name, operation.new_name);
}

fn jsonConstraintNameExists(root: *std.json.ObjectMap, table_name: []const u8, constraint_name: []const u8) !bool {
    if (try schemaJsonPrimaryKeyNameEquals(root, table_name, constraint_name)) return true;
    if (try jsonConstraintArrayNameExists(root.getPtr("unique_constraints"), constraint_name)) return true;
    if (try jsonConstraintArrayNameExists(root.getPtr("foreign_keys"), constraint_name)) return true;
    if (try jsonConstraintArrayNameExists(root.getPtr("checks"), constraint_name)) return true;
    return false;
}

fn schemaJsonPrimaryKeyNameEquals(root: *std.json.ObjectMap, table_name: []const u8, constraint_name: []const u8) !bool {
    const primary_key = root.get("primary_key") orelse return false;
    if (primary_key == .null) return false;
    if (primary_key != .object) return error.InvalidSqlCatalog;
    if (primary_key.object.get("name")) |name| {
        if (name != .string) return error.InvalidSqlCatalog;
        return std.mem.eql(u8, name.string, constraint_name);
    }
    return defaultPrimaryKeyNameEquals(table_name, constraint_name);
}

fn renamePrimaryKeyConstraintInSchemaJsonValue(
    alloc: std.mem.Allocator,
    root: *std.json.ObjectMap,
    table_name: []const u8,
    old_name: []const u8,
    new_name: []const u8,
) !bool {
    const primary_key = root.getPtr("primary_key") orelse return false;
    if (primary_key.* == .null) return false;
    if (primary_key.* != .object) return error.InvalidSqlCatalog;
    if (primary_key.object.get("name")) |existing| {
        if (existing != .string) return error.InvalidSqlCatalog;
        if (!std.mem.eql(u8, existing.string, old_name)) return false;
        _ = primary_key.object.orderedRemove("name");
        try putJsonString(alloc, &primary_key.object, "name", new_name);
        return true;
    }
    if (!defaultPrimaryKeyNameEquals(table_name, old_name)) return false;
    _ = primary_key.object.orderedRemove("name");
    try putJsonString(alloc, &primary_key.object, "name", new_name);
    return true;
}

fn jsonConstraintArrayNameExists(
    value: ?*std.json.Value,
    constraint_name: []const u8,
) !bool {
    const array_value = value orelse return false;
    if (array_value.* != .array) return error.InvalidSqlCatalog;
    for (array_value.array.items) |item| {
        if (item != .object) return error.InvalidSqlCatalog;
        const name = item.object.get("name") orelse return error.InvalidSqlCatalog;
        if (name != .string) return error.InvalidSqlCatalog;
        if (std.mem.eql(u8, name.string, constraint_name)) return true;
    }
    return false;
}

fn renameNamedConstraintInJsonArray(
    alloc: std.mem.Allocator,
    value: ?*std.json.Value,
    old_name: []const u8,
    new_name: []const u8,
) !bool {
    const array_value = value orelse return false;
    if (array_value.* != .array) return error.InvalidSqlCatalog;
    for (array_value.array.items) |*item| {
        if (item.* != .object) return error.InvalidSqlCatalog;
        const name = item.object.get("name") orelse return error.InvalidSqlCatalog;
        if (name != .string) return error.InvalidSqlCatalog;
        if (!std.mem.eql(u8, name.string, old_name)) continue;
        try putJsonString(alloc, &item.object, "name", new_name);
        return true;
    }
    return false;
}

fn alterColumnDefaultInSchemaJsonValue(
    alloc: std.mem.Allocator,
    schema_parts: RelationalSchemaJsonParts,
    operation: AlterColumnDefaultOperation,
) !void {
    const property = schema_parts.properties.getPtr(operation.column_name) orelse return error.InvalidSqlCatalog;
    if (property.* != .object) return error.InvalidSqlCatalog;
    _ = property.object.orderedRemove("default");
    _ = property.object.orderedRemove("x-antfly-default");
    if (operation.default_value) |default_value| {
        const key = if (default_value.kind == .literal) "default" else "x-antfly-default";
        try property.object.put(alloc, try alloc.dupe(u8, key), try schemaJsonDefaultValueAlloc(alloc, default_value, default_value.kind != .literal));
    }
}

fn alterColumnNullabilityInSchemaJsonValue(
    alloc: std.mem.Allocator,
    root: *std.json.ObjectMap,
    schema_parts: RelationalSchemaJsonParts,
    operation: AlterColumnNullabilityOperation,
) !void {
    if (schema_parts.properties.get(operation.column_name) == null) return error.InvalidSqlCatalog;
    if (operation.nullable) {
        try rejectPrimaryKeyDropFromSchemaJson(root, &.{operation.column_name});
        try removeStringsFromJsonArray(schema_parts.schema.getPtr("required"), &.{operation.column_name});
        return;
    }
    const required = try rootArrayFieldAlloc(alloc, schema_parts.schema, "required");
    try appendUniqueJsonString(alloc, required, operation.column_name);
}

fn alterColumnTypeInSchemaJsonValue(
    alloc: std.mem.Allocator,
    schema_parts: RelationalSchemaJsonParts,
    operation: AlterColumnTypeOperation,
) !void {
    const property = schema_parts.properties.getPtr(operation.column_name) orelse return error.InvalidSqlCatalog;
    if (property.* != .object) return error.InvalidSqlCatalog;
    if (property.object.get("generated") != null) return error.UnsupportedSqlShape;
    if (operation.collation != null and !relationalFieldTypeSupportsCollation(operation.field_type)) return error.UnsupportedSqlShape;
    if (!relationalFieldTypeSupportsCollation(operation.field_type) and property.object.get("collation") != null) return error.UnsupportedSqlShape;
    try putJsonString(alloc, &property.object, "type", antflyTypeSchemaName(operation.field_type));
    _ = property.object.orderedRemove("items");
    if (operation.field_type == .array) {
        const item_type = operation.array_item_type orelse return error.InvalidSqlCatalog;
        var item_object = std.json.ObjectMap.empty;
        try putJsonString(alloc, &item_object, "type", antflyTypeSchemaName(item_type));
        try property.object.put(alloc, try alloc.dupe(u8, "items"), .{ .object = item_object });
    }
    if (operation.collation) |collation| try putJsonString(alloc, &property.object, "collation", collation);
}

fn relationalFieldTypeSupportsCollation(field_type: runtime_schema.AntflyType) bool {
    return switch (field_type) {
        .keyword, .text => true,
        else => false,
    };
}

fn appendUniqueJsonString(
    alloc: std.mem.Allocator,
    array: *std.json.Array,
    value: []const u8,
) !void {
    for (array.items) |item| {
        if (item != .string) return error.InvalidSqlCatalog;
        if (std.mem.eql(u8, item.string, value)) return;
    }
    try array.append(.{ .string = try alloc.dupe(u8, value) });
}

fn renamePrimaryKeyJsonFields(
    alloc: std.mem.Allocator,
    primary_key: *std.json.Value,
    old_name: []const u8,
    new_name: []const u8,
) !void {
    if (primary_key.* != .object) return error.InvalidSqlCatalog;
    try renameStringInJsonArray(alloc, primary_key.object.getPtr("columns"), old_name, new_name);
}

fn renameSchemaPropertyReferences(
    alloc: std.mem.Allocator,
    property: *std.json.Value,
    old_name: []const u8,
    new_name: []const u8,
) !void {
    if (property.* != .object) return;
    if (property.object.getPtr("generated")) |generated| try renameGeneratedJsonFields(alloc, generated, old_name, new_name);
    try renameStringInJsonArray(alloc, property.object.getPtr("x-antfly-index-include"), old_name, new_name);
    if (property.object.getPtr("x-antfly-index-where")) |where| try renameUniquePredicateDefinitionJsonFields(alloc, where, old_name, new_name);
    if (property.object.getPtr("x-antfly-index-where-expressions")) |where_expressions| try renameExpressionJsonFields(alloc, where_expressions, old_name, new_name);
}

fn renameGeneratedJsonFields(
    alloc: std.mem.Allocator,
    generated: *std.json.Value,
    old_name: []const u8,
    new_name: []const u8,
) !void {
    if (generated.* != .object) return error.InvalidSqlCatalog;
    try renameStringFieldInJsonObject(alloc, &generated.object, "field", old_name, new_name);
    try renameStringInJsonArray(alloc, generated.object.getPtr("fields"), old_name, new_name);
}

fn renameConstraintArrayFields(
    alloc: std.mem.Allocator,
    value: ?*std.json.Value,
    old_name: []const u8,
    new_name: []const u8,
    kind: JsonConstraintKind,
) !void {
    const array_value = value orelse return;
    if (array_value.* != .array) return error.InvalidSqlCatalog;
    for (array_value.array.items) |*item| {
        if (item.* != .object) return error.InvalidSqlCatalog;
        switch (kind) {
            .unique => {
                try renameStringInJsonArray(alloc, item.object.getPtr("columns"), old_name, new_name);
                if (item.object.getPtr("expressions")) |expressions| try renameUniqueExpressionJsonFields(alloc, expressions, old_name, new_name);
                try renameStringInJsonArray(alloc, item.object.getPtr("include_columns"), old_name, new_name);
                if (item.object.getPtr("where")) |where| try renameUniquePredicateDefinitionJsonFields(alloc, where, old_name, new_name);
                if (item.object.getPtr("where_expressions")) |where_expressions| try renameExpressionJsonFields(alloc, where_expressions, old_name, new_name);
            },
            .foreign_key => try renameStringInJsonArray(alloc, item.object.getPtr("columns"), old_name, new_name),
            .check => {
                try renameStringFieldInJsonObject(alloc, &item.object, "field", old_name, new_name);
                if (item.object.getPtr("expression")) |expression| try renameExpressionJsonFields(alloc, expression, old_name, new_name);
            },
        }
    }
}

fn renameUniqueExpressionJsonFields(
    alloc: std.mem.Allocator,
    expressions: *std.json.Value,
    old_name: []const u8,
    new_name: []const u8,
) !void {
    if (expressions.* != .array) return error.InvalidSqlCatalog;
    for (expressions.array.items) |*expression| {
        if (expression.* != .object) return error.InvalidSqlCatalog;
        try renameStringFieldInJsonObject(alloc, &expression.object, "field", old_name, new_name);
    }
}

fn renameUniquePredicateDefinitionJsonFields(
    alloc: std.mem.Allocator,
    value: *std.json.Value,
    old_name: []const u8,
    new_name: []const u8,
) !void {
    if (value.* != .object) return error.InvalidSqlCatalog;
    const all = value.object.getPtr("all") orelse return;
    if (all.* != .array) return error.InvalidSqlCatalog;
    for (all.array.items) |*item| {
        if (item.* != .object) return error.InvalidSqlCatalog;
        try renameStringFieldInJsonObject(alloc, &item.object, "field", old_name, new_name);
    }
}

fn renameExpressionJsonFields(
    alloc: std.mem.Allocator,
    value: *std.json.Value,
    old_name: []const u8,
    new_name: []const u8,
) !void {
    switch (value.*) {
        .object => |*object| {
            try renameStringFieldInJsonObject(alloc, object, "field", old_name, new_name);
            var it = object.iterator();
            while (it.next()) |entry| {
                try renameExpressionJsonFields(alloc, entry.value_ptr, old_name, new_name);
            }
        },
        .array => |*array| {
            for (array.items) |*item| {
                try renameExpressionJsonFields(alloc, item, old_name, new_name);
            }
        },
        else => {},
    }
}

fn renameStringInJsonArray(
    alloc: std.mem.Allocator,
    value: ?*std.json.Value,
    old_name: []const u8,
    new_name: []const u8,
) !void {
    const array_value = value orelse return;
    if (array_value.* != .array) return error.InvalidSqlCatalog;
    for (array_value.array.items) |*item| {
        if (item.* != .string) return error.InvalidSqlCatalog;
        if (std.mem.eql(u8, item.string, old_name)) item.* = .{ .string = try alloc.dupe(u8, new_name) };
    }
}

fn renameStringFieldInJsonObject(
    alloc: std.mem.Allocator,
    object: *std.json.ObjectMap,
    field_name: []const u8,
    old_name: []const u8,
    new_name: []const u8,
) !void {
    const value = object.get(field_name) orelse return;
    if (value != .string) return error.InvalidSqlCatalog;
    if (!std.mem.eql(u8, value.string, old_name)) return;
    try putJsonString(alloc, object, field_name, new_name);
}

fn removeNamedConstraintFromJsonArray(
    value: ?*std.json.Value,
    constraint_name: []const u8,
) !bool {
    const array_value = value orelse return false;
    if (array_value.* != .array) return error.InvalidSqlCatalog;
    var i: usize = 0;
    while (i < array_value.array.items.len) : (i += 1) {
        const item = array_value.array.items[i];
        if (item != .object) return error.InvalidSqlCatalog;
        const name = item.object.get("name") orelse return error.InvalidSqlCatalog;
        if (name != .string) return error.InvalidSqlCatalog;
        if (!std.mem.eql(u8, name.string, constraint_name)) continue;
        _ = array_value.array.orderedRemove(i);
        return true;
    }
    return false;
}

fn namedConstraintExistsInJsonArray(
    value: ?*std.json.Value,
    constraint_name: []const u8,
) !bool {
    const array_value = value orelse return false;
    if (array_value.* != .array) return error.InvalidSqlCatalog;
    for (array_value.array.items) |item| {
        if (item != .object) return error.InvalidSqlCatalog;
        const name = item.object.get("name") orelse return error.InvalidSqlCatalog;
        if (name != .string) return error.InvalidSqlCatalog;
        if (std.mem.eql(u8, name.string, constraint_name)) return true;
    }
    return false;
}

fn setNamedConstraintValidationStateInArray(
    alloc: std.mem.Allocator,
    root: *std.json.ObjectMap,
    field: []const u8,
    constraint_name: []const u8,
    validation_state: []const u8,
) !bool {
    const value = root.getPtr(field) orelse return false;
    if (value.* != .array) return error.InvalidSqlCatalog;
    for (value.array.items) |*item| {
        if (item.* != .object) return error.InvalidSqlCatalog;
        const name = item.object.get("name") orelse return error.InvalidSqlCatalog;
        if (name != .string) return error.InvalidSqlCatalog;
        if (!std.mem.eql(u8, name.string, constraint_name)) continue;
        try putJsonString(alloc, &item.object, "validation_state", validation_state);
        return true;
    }
    return false;
}

const RelationalSchemaJsonParts = struct {
    schema: *std.json.ObjectMap,
    properties: *std.json.ObjectMap,
};

fn relationalSchemaJsonParts(root: *std.json.ObjectMap) !RelationalSchemaJsonParts {
    const storage_mode = root.get("storage_mode") orelse return error.InvalidSqlCatalog;
    if (storage_mode != .string or !std.mem.eql(u8, storage_mode.string, "relational")) return error.InvalidSqlCatalog;
    const default_type = root.get("default_type") orelse return error.InvalidSqlCatalog;
    if (default_type != .string or default_type.string.len == 0) return error.InvalidSqlCatalog;
    const document_schemas = root.getPtr("document_schemas") orelse return error.InvalidSqlCatalog;
    if (document_schemas.* != .object) return error.InvalidSqlCatalog;
    const document_schema = document_schemas.object.getPtr(default_type.string) orelse return error.InvalidSqlCatalog;
    if (document_schema.* != .object) return error.InvalidSqlCatalog;
    const schema = document_schema.object.getPtr("schema") orelse return error.InvalidSqlCatalog;
    if (schema.* != .object) return error.InvalidSqlCatalog;
    const properties = schema.object.getPtr("properties") orelse return error.InvalidSqlCatalog;
    if (properties.* != .object) return error.InvalidSqlCatalog;
    return .{ .schema = &schema.object, .properties = &properties.object };
}

fn schemaJsonPropertyForSecondaryIndex(properties: *std.json.ObjectMap, index_name: []const u8) ?*std.json.Value {
    var it = properties.iterator();
    while (it.next()) |entry| {
        if (schemaJsonPropertyHasSecondaryIndexName(entry.value_ptr.*, index_name)) return entry.value_ptr;
    }
    return properties.getPtr(index_name);
}

fn schemaJsonPropertyHasSecondaryIndexName(property: std.json.Value, index_name: []const u8) bool {
    if (property != .object) return false;
    const declared = property.object.get("x-antfly-index-name") orelse return false;
    return declared == .string and std.mem.eql(u8, declared.string, index_name);
}

fn validateGeneratedExpressionForSchemaJsonProperties(
    properties: *std.json.ObjectMap,
    index_name: []const u8,
    generated: runtime_schema.RelationalGeneratedValue,
) !void {
    switch (generated.op) {
        .lower, .upper, .md5 => {
            const field = generated.field orelse return error.InvalidSqlCatalog;
            try validateGeneratedExpressionSourceForSchemaJsonProperties(properties, index_name, field);
        },
        .concat, .concat_ws => {
            if (generated.fields.len == 0) return error.InvalidSqlCatalog;
            for (generated.fields) |field| {
                try validateGeneratedExpressionSourceForSchemaJsonProperties(properties, index_name, field);
            }
        },
    }
}

fn validateGeneratedExpressionSourceForSchemaJsonProperties(
    properties: *std.json.ObjectMap,
    index_name: []const u8,
    field: []const u8,
) !void {
    if (std.mem.eql(u8, field, index_name)) return error.InvalidSqlCatalog;
    const property = properties.get(field) orelse return error.InvalidSqlCatalog;
    if (property != .object) return error.InvalidSqlCatalog;
    const property_type = property.object.get("type") orelse return error.InvalidSqlCatalog;
    if (property_type != .string) return error.InvalidSqlCatalog;
    if (std.mem.eql(u8, property_type.string, "json") or std.mem.eql(u8, property_type.string, "array")) return error.InvalidSqlCatalog;
}

fn schemaJsonPropertyType(
    properties: *std.json.ObjectMap,
    field: []const u8,
) ![]const u8 {
    const property = properties.get(field) orelse return error.InvalidSqlCatalog;
    if (property != .object) return error.InvalidSqlCatalog;
    const property_type = property.object.get("type") orelse return error.InvalidSqlCatalog;
    if (property_type != .string) return error.InvalidSqlCatalog;
    return property_type.string;
}

fn validateCreateIndexIncludeColumnsForSchemaJsonProperties(
    properties: *std.json.ObjectMap,
    key_columns: []const []const u8,
    include_columns: []const []const u8,
) !void {
    for (include_columns) |column| {
        if (stringSlicesContains(key_columns, column)) return error.InvalidSqlCatalog;
        const property = properties.get(column) orelse return error.InvalidSqlCatalog;
        if (property != .object) return error.InvalidSqlCatalog;
        const property_type = property.object.get("type") orelse return error.InvalidSqlCatalog;
        if (property_type != .string) return error.InvalidSqlCatalog;
    }
}

fn schemaJsonIndexNameExists(
    properties: *std.json.ObjectMap,
    unique_constraints: ?*std.json.Value,
    index_name: []const u8,
) !bool {
    if (try jsonConstraintArrayNameExists(unique_constraints, index_name)) return true;
    return schemaJsonPropertyForSecondaryIndex(properties, index_name) != null;
}

fn appendUniqueBorrowedString(
    alloc: std.mem.Allocator,
    values: *std.ArrayListUnmanaged([]const u8),
    value: []const u8,
) !void {
    if (stringSlicesContains(values.items, value)) return;
    try values.append(alloc, value);
}

fn propertyGeneratedReferencesAny(property: std.json.Value, fields: []const []const u8) bool {
    if (property != .object) return false;
    const generated = property.object.get("generated") orelse return false;
    if (generated != .object) return false;
    if (generated.object.get("field")) |field| {
        if (field == .string and stringSlicesContains(fields, field.string)) return true;
    }
    if (generated.object.get("fields")) |fields_value| {
        if (jsonStringArrayReferencesAny(fields_value, fields)) return true;
    }
    return false;
}

fn schemaJsonSecondaryIndexReferencesAny(property: std.json.Value, fields: []const []const u8) bool {
    if (property != .object) return false;
    if (property.object.get("x-antfly-index-name") == null) return false;
    if (property.object.get("x-antfly-index-include")) |include| {
        if (jsonStringArrayReferencesAny(include, fields)) return true;
    }
    if (property.object.get("x-antfly-index-where")) |where| {
        if (jsonUniquePredicateDefinitionReferencesAny(where, fields)) return true;
    }
    if (property.object.get("x-antfly-index-where-expressions")) |where_expressions| {
        if (jsonExpressionReferencesAny(where_expressions, fields)) return true;
    }
    return false;
}

fn jsonExpressionReferencesAny(value: std.json.Value, fields: []const []const u8) bool {
    switch (value) {
        .object => |object| {
            if (object.get("field")) |field| {
                if (field == .string and stringSlicesContains(fields, field.string)) return true;
            }
            var it = object.iterator();
            while (it.next()) |entry| {
                if (jsonExpressionReferencesAny(entry.value_ptr.*, fields)) return true;
            }
        },
        .array => |array| {
            for (array.items) |item| {
                if (jsonExpressionReferencesAny(item, fields)) return true;
            }
        },
        else => {},
    }
    return false;
}

fn removeStringsFromJsonArray(value: ?*std.json.Value, fields: []const []const u8) !void {
    const array_value = value orelse return;
    if (array_value.* != .array) return error.InvalidSqlCatalog;
    var i: usize = 0;
    while (i < array_value.array.items.len) {
        const item = array_value.array.items[i];
        if (item != .string) return error.InvalidSqlCatalog;
        if (stringSlicesContains(fields, item.string)) {
            _ = array_value.array.orderedRemove(i);
        } else {
            i += 1;
        }
    }
}

fn rejectPrimaryKeyDropFromSchemaJson(root: *std.json.ObjectMap, fields: []const []const u8) !void {
    const primary_key = root.get("primary_key") orelse return error.InvalidSqlCatalog;
    if (primary_key != .object) return error.InvalidSqlCatalog;
    const columns = primary_key.object.get("columns") orelse return error.InvalidSqlCatalog;
    if (jsonStringArrayReferencesAny(columns, fields)) return error.UnsupportedSqlShape;
}

const JsonConstraintKind = enum {
    unique,
    foreign_key,
    check,
};

fn removeDependentConstraintsFromJsonArray(
    value: ?*std.json.Value,
    fields: []const []const u8,
    kind: JsonConstraintKind,
) !void {
    const array_value = value orelse return;
    if (array_value.* != .array) return error.InvalidSqlCatalog;
    var i: usize = 0;
    while (i < array_value.array.items.len) {
        const item = array_value.array.items[i];
        if (item != .object) return error.InvalidSqlCatalog;
        const remove = switch (kind) {
            .unique => jsonUniqueConstraintReferencesAny(item, fields),
            .foreign_key => jsonStringArrayReferencesAny(item.object.get("columns") orelse return error.InvalidSqlCatalog, fields),
            .check => blk: {
                const field = item.object.get("field") orelse return error.InvalidSqlCatalog;
                break :blk field == .string and stringSlicesContains(fields, field.string);
            },
        };
        if (remove) {
            _ = array_value.array.orderedRemove(i);
        } else {
            i += 1;
        }
    }
}

fn jsonUniqueConstraintReferencesAny(value: std.json.Value, fields: []const []const u8) bool {
    if (value != .object) return false;
    if (value.object.get("columns")) |columns| {
        if (jsonStringArrayReferencesAny(columns, fields)) return true;
    }
    if (value.object.get("expressions")) |expressions| {
        if (expressions == .array) {
            for (expressions.array.items) |expression| {
                if (expression != .object) continue;
                const field = expression.object.get("field") orelse continue;
                if (field == .string and stringSlicesContains(fields, field.string)) return true;
            }
        }
    }
    if (value.object.get("include_columns")) |include_columns| {
        if (jsonStringArrayReferencesAny(include_columns, fields)) return true;
    }
    if (value.object.get("where")) |where| {
        if (jsonUniquePredicateDefinitionReferencesAny(where, fields)) return true;
    }
    return false;
}

fn jsonUniquePredicateDefinitionReferencesAny(value: std.json.Value, fields: []const []const u8) bool {
    if (value != .object) return false;
    const all = value.object.get("all") orelse return false;
    if (all != .array) return false;
    for (all.array.items) |item| {
        if (item != .object) continue;
        const field = item.object.get("field") orelse continue;
        if (field == .string and stringSlicesContains(fields, field.string)) return true;
    }
    return false;
}

fn jsonStringArrayReferencesAny(value: std.json.Value, fields: []const []const u8) bool {
    if (value != .array) return false;
    for (value.array.items) |item| {
        if (item == .string and stringSlicesContains(fields, item.string)) return true;
    }
    return false;
}

fn schemaJsonPropertyFromColumnAlloc(alloc: std.mem.Allocator, column: runtime_schema.RelationalColumn) !std.json.Value {
    var object = std.json.ObjectMap.empty;
    try putJsonString(alloc, &object, "type", antflyTypeSchemaName(column.field_type));
    if (column.field_type == .array) {
        const item_type = column.array_item_type orelse return error.InvalidSqlCatalog;
        var item_object = std.json.ObjectMap.empty;
        try putJsonString(alloc, &item_object, "type", antflyTypeSchemaName(item_type));
        try object.put(alloc, try alloc.dupe(u8, "items"), .{ .object = item_object });
    }
    if (!column.indexed) try object.put(alloc, try alloc.dupe(u8, "x-antfly-index"), .{ .bool = false });
    if (column.index_lifecycle != .ready) try putJsonString(alloc, &object, "x-antfly-index-lifecycle", relationalIndexLifecycleName(column.index_lifecycle));
    if (column.index_generation != 0) try object.put(alloc, try alloc.dupe(u8, "x-antfly-index-generation"), .{ .integer = @intCast(column.index_generation) });
    if (column.index_name) |index_name| try putJsonString(alloc, &object, "x-antfly-index-name", index_name);
    if (column.index_include_columns.len > 0) try object.put(alloc, try alloc.dupe(u8, "x-antfly-index-include"), try schemaJsonStringArrayAlloc(alloc, column.index_include_columns));
    if (column.collation) |collation| try putJsonString(alloc, &object, "collation", collation);
    if (column.index_where.len > 0) try object.put(alloc, try alloc.dupe(u8, "x-antfly-index-where"), try schemaJsonUniquePredicateDefinitionAlloc(alloc, column.index_where));
    if (column.index_where_expressions.len > 0) try object.put(alloc, try alloc.dupe(u8, "x-antfly-index-where-expressions"), try schemaJsonExpressionConditionsAlloc(alloc, column.index_where_expressions));
    if (column.default_value) |value| {
        const key = if (value.kind == .literal) "default" else "x-antfly-default";
        try object.put(alloc, try alloc.dupe(u8, key), try schemaJsonDefaultValueAlloc(alloc, value, value.kind != .literal));
    }
    if (column.on_update_value) |value| try object.put(alloc, try alloc.dupe(u8, "x-antfly-on-update"), try schemaJsonDefaultValueAlloc(alloc, value, true));
    if (column.generated) |generated| try object.put(alloc, try alloc.dupe(u8, "generated"), try schemaJsonGeneratedValueAlloc(alloc, generated));
    return .{ .object = object };
}

fn schemaJsonDefaultValueAlloc(alloc: std.mem.Allocator, value: runtime_schema.RelationalDefaultValue, force_server_default: bool) !std.json.Value {
    if (!force_server_default and value.kind == .literal) {
        var parsed = try std.json.parseFromSlice(std.json.Value, alloc, value.value_json, .{});
        defer parsed.deinit();
        return try json_helpers.cloneJsonValue(alloc, parsed.value);
    }
    var object = std.json.ObjectMap.empty;
    try putJsonString(alloc, &object, "op", switch (value.kind) {
        .literal => return error.InvalidSqlCatalog,
        .now_ns => "now_ns",
        .current_date_ns => "current_date_ns",
        .uuid_v4 => "uuid_v4",
    });
    return .{ .object = object };
}

fn schemaJsonGeneratedValueAlloc(alloc: std.mem.Allocator, generated: runtime_schema.RelationalGeneratedValue) !std.json.Value {
    var object = std.json.ObjectMap.empty;
    try putJsonString(alloc, &object, "op", switch (generated.op) {
        .lower => "lower",
        .upper => "upper",
        .md5 => "md5",
        .concat => "concat",
        .concat_ws => "concat_ws",
    });
    switch (generated.op) {
        .lower, .upper, .md5 => try putJsonString(alloc, &object, "field", generated.field orelse return error.InvalidSqlCatalog),
        .concat, .concat_ws => {
            try object.put(alloc, try alloc.dupe(u8, "fields"), try schemaJsonStringArrayAlloc(alloc, generated.fields));
            try putJsonString(alloc, &object, "separator", generated.separator);
        },
    }
    return .{ .object = object };
}

fn schemaJsonPrimaryKeyAlloc(alloc: std.mem.Allocator, primary_key: runtime_schema.PrimaryKey) !std.json.Value {
    var object = std.json.ObjectMap.empty;
    if (primary_key.name) |name| try putJsonString(alloc, &object, "name", name);
    try object.put(alloc, try alloc.dupe(u8, "columns"), try schemaJsonStringArrayAlloc(alloc, primary_key.columns));
    if (primary_key.without_overlaps_period) |period| try putJsonString(alloc, &object, "without_overlaps_period", period);
    return .{ .object = object };
}

fn schemaJsonPeriodsAlloc(alloc: std.mem.Allocator, periods: []const runtime_schema.RelationalPeriod) !std.json.Value {
    var array = std.json.Array.init(alloc);
    for (periods) |period| {
        try array.append(try schemaJsonPeriodAlloc(alloc, period));
    }
    return .{ .array = array };
}

fn schemaJsonPeriodAlloc(alloc: std.mem.Allocator, period: runtime_schema.RelationalPeriod) !std.json.Value {
    var object = std.json.ObjectMap.empty;
    try putJsonString(alloc, &object, "name", period.name);
    try putJsonString(alloc, &object, "start_column", period.start_column);
    try putJsonString(alloc, &object, "end_column", period.end_column);
    if (period.range_type) |range_type| try putJsonString(alloc, &object, "range_type", relationalPeriodRangeTypeName(range_type));
    return .{ .object = object };
}

fn schemaJsonUniqueConstraintsAlloc(alloc: std.mem.Allocator, constraints: []const runtime_schema.UniqueConstraint) !std.json.Value {
    var array = std.json.Array.init(alloc);
    for (constraints) |constraint| try array.append(try schemaJsonUniqueConstraintAlloc(alloc, constraint));
    return .{ .array = array };
}

fn schemaJsonUniqueConstraintAlloc(alloc: std.mem.Allocator, constraint: runtime_schema.UniqueConstraint) !std.json.Value {
    var object = std.json.ObjectMap.empty;
    try putJsonString(alloc, &object, "name", constraint.name);
    if (constraint.columns.len > 0) try object.put(alloc, try alloc.dupe(u8, "columns"), try schemaJsonStringArrayAlloc(alloc, constraint.columns));
    if (constraint.expressions.len > 0) try object.put(alloc, try alloc.dupe(u8, "expressions"), try schemaJsonUniqueExpressionsAlloc(alloc, constraint.expressions));
    if (constraint.include_columns.len > 0) try object.put(alloc, try alloc.dupe(u8, "include_columns"), try schemaJsonStringArrayAlloc(alloc, constraint.include_columns));
    if (constraint.without_overlaps_period) |period| try putJsonString(alloc, &object, "without_overlaps_period", period);
    if (constraint.where.len > 0) try object.put(alloc, try alloc.dupe(u8, "where"), try schemaJsonUniquePredicateDefinitionAlloc(alloc, constraint.where));
    if (constraint.where_expressions.len > 0) try object.put(alloc, try alloc.dupe(u8, "where_expressions"), try schemaJsonExpressionConditionsAlloc(alloc, constraint.where_expressions));
    if (constraint.validation_state != .enforced) try putJsonString(alloc, &object, "validation_state", uniqueConstraintValidationStateString(constraint.validation_state));
    return .{ .object = object };
}

fn uniqueConstraintValidationStateString(state: runtime_schema.UniqueConstraintValidationState) []const u8 {
    return switch (state) {
        .enforced => "enforced",
        .unvalidated => "unvalidated",
        .validating => "validating",
        .invalid => "invalid",
    };
}

fn schemaJsonUniqueExpressionsAlloc(alloc: std.mem.Allocator, expressions: []const runtime_schema.UniqueExpression) !std.json.Value {
    var array = std.json.Array.init(alloc);
    for (expressions) |expression| {
        var object = std.json.ObjectMap.empty;
        try putJsonString(alloc, &object, "op", switch (expression.op) {
            .lower => "lower",
            .upper => "upper",
            .md5 => "md5",
        });
        try putJsonString(alloc, &object, "field", expression.field);
        try array.append(.{ .object = object });
    }
    return .{ .array = array };
}

fn schemaJsonUniquePredicateDefinitionAlloc(alloc: std.mem.Allocator, predicates: []const runtime_schema.UniquePredicate) !std.json.Value {
    var object = std.json.ObjectMap.empty;
    var array = std.json.Array.init(alloc);
    for (predicates) |predicate| try array.append(try schemaJsonUniquePredicateAlloc(alloc, predicate));
    try object.put(alloc, try alloc.dupe(u8, "all"), .{ .array = array });
    return .{ .object = object };
}

fn schemaJsonExpressionConditionsAlloc(
    alloc: std.mem.Allocator,
    conditions: []const db_mod.types.RelationalRowsExpressionCondition,
) !std.json.Value {
    var out: std.Io.Writer.Allocating = .init(alloc);
    errdefer out.deinit();
    const writer = &out.writer;
    try writer.writeByte('[');
    for (conditions, 0..) |condition, i| {
        if (i != 0) try writer.writeByte(',');
        try Parser.writeRowExpressionConditionJson(writer, condition);
    }
    try writer.writeByte(']');
    const json = try out.toOwnedSlice();
    defer alloc.free(json);
    var parsed = try std.json.parseFromSlice(std.json.Value, alloc, json, .{});
    defer parsed.deinit();
    return try json_helpers.cloneJsonValue(alloc, parsed.value);
}

fn schemaJsonUniquePredicateAlloc(alloc: std.mem.Allocator, predicate: runtime_schema.UniquePredicate) !std.json.Value {
    var object = std.json.ObjectMap.empty;
    try putJsonString(alloc, &object, "field", predicate.field);
    try putJsonString(alloc, &object, "op", uniquePredicateOpToken(predicate.op));
    if (predicate.value_json) |value_json| {
        var parsed = try std.json.parseFromSlice(std.json.Value, alloc, value_json, .{});
        defer parsed.deinit();
        try object.put(alloc, try alloc.dupe(u8, "value"), try json_helpers.cloneJsonValue(alloc, parsed.value));
    }
    return .{ .object = object };
}

fn schemaJsonForeignKeysAlloc(alloc: std.mem.Allocator, foreign_keys: []const runtime_schema.ForeignKey) !std.json.Value {
    var array = std.json.Array.init(alloc);
    for (foreign_keys) |foreign_key| try array.append(try schemaJsonForeignKeyAlloc(alloc, foreign_key));
    return .{ .array = array };
}

fn schemaJsonForeignKeyAlloc(alloc: std.mem.Allocator, foreign_key: runtime_schema.ForeignKey) !std.json.Value {
    var reference = std.json.ObjectMap.empty;
    try putJsonString(alloc, &reference, "table", foreign_key.parent_table);
    try reference.put(alloc, try alloc.dupe(u8, "columns"), try schemaJsonStringArrayAlloc(alloc, foreign_key.parent_columns));
    if (foreign_key.parent_period) |period| try putJsonString(alloc, &reference, "period", period);

    var object = std.json.ObjectMap.empty;
    try putJsonString(alloc, &object, "name", foreign_key.name);
    try object.put(alloc, try alloc.dupe(u8, "columns"), try schemaJsonStringArrayAlloc(alloc, foreign_key.child_columns));
    if (foreign_key.child_period) |period| try putJsonString(alloc, &object, "period", period);
    try object.put(alloc, try alloc.dupe(u8, "references"), .{ .object = reference });
    try putJsonString(alloc, &object, "on_delete", foreignKeyActionName(foreign_key.on_delete));
    try putJsonString(alloc, &object, "on_update", foreignKeyActionName(foreign_key.on_update));
    try putJsonString(alloc, &object, "timing", foreignKeyTimingName(foreign_key.timing));
    try object.put(alloc, try alloc.dupe(u8, "deferrable"), .{ .bool = foreign_key.deferrable });
    try putJsonString(alloc, &object, "match", foreignKeyMatchName(foreign_key.match));
    try putJsonString(alloc, &object, "validation_state", foreignKeyValidationStateName(foreign_key.validation_state));
    return .{ .object = object };
}

fn schemaJsonRelationalChecksAlloc(alloc: std.mem.Allocator, checks: []const runtime_schema.RelationalCheck) !std.json.Value {
    var array = std.json.Array.init(alloc);
    for (checks) |check| try array.append(try schemaJsonRelationalCheckAlloc(alloc, check));
    return .{ .array = array };
}

fn schemaJsonRelationalCheckAlloc(alloc: std.mem.Allocator, check: runtime_schema.RelationalCheck) !std.json.Value {
    var object = std.json.ObjectMap.empty;
    try putJsonString(alloc, &object, "name", check.name);
    try putJsonString(alloc, &object, "field", check.field);
    try putJsonString(alloc, &object, "op", relationalCheckOpToken(check.op));
    if (check.validation_state != .enforced) try putJsonString(alloc, &object, "validation_state", relationalCheckValidationStateName(check.validation_state));
    if (check.value_json) |value_json| {
        var parsed = try std.json.parseFromSlice(std.json.Value, alloc, value_json, .{});
        defer parsed.deinit();
        try object.put(alloc, try alloc.dupe(u8, "value"), try json_helpers.cloneJsonValue(alloc, parsed.value));
    }
    return .{ .object = object };
}

fn relationalCheckValidationStateName(state: runtime_schema.RelationalCheckValidationState) []const u8 {
    return switch (state) {
        .enforced => "enforced",
        .unvalidated => "unvalidated",
        .validating => "validating",
        .invalid => "invalid",
    };
}

fn schemaJsonStringArrayAlloc(alloc: std.mem.Allocator, values: []const []const u8) !std.json.Value {
    var array = std.json.Array.init(alloc);
    for (values) |value| try array.append(.{ .string = try alloc.dupe(u8, value) });
    return .{ .array = array };
}

fn rootArrayFieldAlloc(alloc: std.mem.Allocator, object: *std.json.ObjectMap, field: []const u8) !*std.json.Array {
    const entry = try object.getOrPut(alloc, field);
    if (!entry.found_existing) {
        entry.key_ptr.* = try alloc.dupe(u8, field);
        entry.value_ptr.* = .{ .array = std.json.Array.init(alloc) };
    }
    if (entry.value_ptr.* != .array) return error.InvalidSqlCatalog;
    return &entry.value_ptr.array;
}

fn rootObjectFieldAlloc(alloc: std.mem.Allocator, object: *std.json.ObjectMap, field: []const u8) !*std.json.ObjectMap {
    const entry = try object.getOrPut(alloc, field);
    if (!entry.found_existing) {
        entry.key_ptr.* = try alloc.dupe(u8, field);
        entry.value_ptr.* = .{ .object = std.json.ObjectMap.empty };
    }
    if (entry.value_ptr.* != .object) return error.InvalidSqlCatalog;
    return &entry.value_ptr.object;
}

fn putJsonString(alloc: std.mem.Allocator, object: *std.json.ObjectMap, key: []const u8, value: []const u8) !void {
    try object.put(alloc, try alloc.dupe(u8, key), .{ .string = try alloc.dupe(u8, value) });
}

fn antflyTypeSchemaName(field_type: runtime_schema.AntflyType) []const u8 {
    return switch (field_type) {
        .text => "text",
        .keyword => "keyword",
        .numeric => "numeric",
        .embedding => "embedding",
        .boolean => "boolean",
        .datetime => "datetime",
        .geopoint => "geopoint",
        .geoshape => "geoshape",
        .blob => "blob",
        .html => "html",
        .search_as_you_type => "search_as_you_type",
        .json => "json",
        .array => "array",
        .link => "link",
    };
}

fn foreignKeyActionName(action: runtime_schema.ForeignKeyAction) []const u8 {
    return switch (action) {
        .restrict => "restrict",
        .set_null => "set_null",
        .cascade => "cascade",
        .no_action => "no_action",
    };
}

fn foreignKeyTimingName(timing: runtime_schema.ForeignKeyTiming) []const u8 {
    return switch (timing) {
        .immediate => "immediate",
        .deferred => "deferred",
    };
}

fn foreignKeyMatchName(match: runtime_schema.ForeignKeyMatch) []const u8 {
    return switch (match) {
        .simple => "simple",
        .full => "full",
        .partial => "partial",
    };
}

fn foreignKeyValidationStateName(state: runtime_schema.ForeignKeyValidationState) []const u8 {
    return switch (state) {
        .enforced => "enforced",
        .unvalidated => "unvalidated",
        .validating => "validating",
        .invalid => "invalid",
    };
}

fn validateDdlAppliedSchemaJsonAlloc(alloc: std.mem.Allocator, schema_json: []const u8) !void {
    var parsed_schema = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed_schema.deinit(alloc);
    const runtime = try schema_api.deriveRuntimeTableSchema(alloc, parsed_schema);
    defer runtime_schema.freeSchema(alloc, runtime);
    if (runtime.storage_mode != .relational) return error.InvalidSqlCatalog;
}

fn cloneStringSlice(alloc: std.mem.Allocator, values: []const []const u8) ![]const []const u8 {
    if (values.len == 0) return &.{};
    const out = try alloc.alloc([]const u8, values.len);
    var initialized: usize = 0;
    errdefer {
        for (out[0..initialized]) |value| alloc.free(value);
        alloc.free(out);
    }
    for (values, 0..) |value, i| {
        out[i] = try alloc.dupe(u8, value);
        initialized += 1;
    }
    return out;
}

fn cloneEmptyRuntimeSchemaAlloc(alloc: std.mem.Allocator, current: runtime_schema.TableSchema) !runtime_schema.TableSchema {
    const default_type = try alloc.dupe(u8, current.default_type);
    const ttl_field = alloc.dupe(u8, current.ttl_field) catch |err| {
        alloc.free(default_type);
        return err;
    };
    return .{
        .version = current.version,
        .default_type = default_type,
        .ttl_duration_ns = current.ttl_duration_ns,
        .ttl_field = ttl_field,
        .enforce_types = current.enforce_types,
        .storage_mode = current.storage_mode,
    };
}

fn cloneRelationalRuntimeSchemaAlloc(alloc: std.mem.Allocator, current: runtime_schema.TableSchema) !runtime_schema.TableSchema {
    if (current.storage_mode != .relational) return error.InvalidSqlCatalog;
    if (current.dynamic_templates.len != 0 or current.full_text_documents.len != 0) return error.UnsupportedSqlShape;

    var schema = try cloneEmptyRuntimeSchemaAlloc(alloc, current);
    errdefer runtime_schema.freeSchema(alloc, schema);
    schema.relational_columns = try cloneDdlRelationalColumns(alloc, current.relational_columns);
    schema.primary_key = try cloneDdlPrimaryKeyMaybe(alloc, current.primary_key);
    schema.periods = try cloneDdlPeriods(alloc, current.periods);
    schema.foreign_keys = try cloneDdlForeignKeys(alloc, current.foreign_keys);
    schema.unique_constraints = try cloneDdlUniqueConstraints(alloc, current.unique_constraints);
    schema.checks = try cloneDdlRelationalChecks(alloc, current.checks);
    return schema;
}

fn cloneDdlRelationalColumn(alloc: std.mem.Allocator, column: runtime_schema.RelationalColumn) !runtime_schema.RelationalColumn {
    const name = try alloc.dupe(u8, column.name);
    const path = alloc.dupe(u8, column.path) catch |err| {
        alloc.free(name);
        return err;
    };
    var out: runtime_schema.RelationalColumn = .{
        .name = name,
        .path = path,
        .field_type = column.field_type,
        .array_item_type = column.array_item_type,
        .nullable = column.nullable,
        .indexed = column.indexed,
        .index_lifecycle = column.index_lifecycle,
        .index_generation = column.index_generation,
    };
    errdefer freeDdlRelationalColumn(alloc, out);
    out.collation = if (column.collation) |collation| try alloc.dupe(u8, collation) else null;
    out.index_name = if (column.index_name) |index_name| try alloc.dupe(u8, index_name) else null;
    out.index_include_columns = try cloneStringSlice(alloc, column.index_include_columns);
    out.default_value = if (column.default_value) |value| try cloneDdlDefaultValue(alloc, value) else null;
    out.on_update_value = if (column.on_update_value) |value| try cloneDdlDefaultValue(alloc, value) else null;
    out.generated = if (column.generated) |generated| try cloneDdlGeneratedValue(alloc, generated) else null;
    out.index_where = try cloneDdlUniquePredicates(alloc, column.index_where);
    out.index_where_expressions = try cloneExpressionConditionsAlloc(alloc, column.index_where_expressions);
    return out;
}

fn cloneDdlRelationalColumns(alloc: std.mem.Allocator, columns: []const runtime_schema.RelationalColumn) ![]const runtime_schema.RelationalColumn {
    if (columns.len == 0) return &.{};
    const out = try alloc.alloc(runtime_schema.RelationalColumn, columns.len);
    var initialized: usize = 0;
    errdefer {
        for (out[0..initialized]) |column| freeDdlRelationalColumn(alloc, column);
        alloc.free(out);
    }
    for (columns, 0..) |column, i| {
        out[i] = try cloneDdlRelationalColumn(alloc, column);
        initialized += 1;
    }
    return out;
}

fn cloneDdlDefaultValue(alloc: std.mem.Allocator, value: runtime_schema.RelationalDefaultValue) !runtime_schema.RelationalDefaultValue {
    return .{
        .kind = value.kind,
        .value_json = try alloc.dupe(u8, value.value_json),
    };
}

fn cloneDdlGeneratedValue(alloc: std.mem.Allocator, generated: runtime_schema.RelationalGeneratedValue) !runtime_schema.RelationalGeneratedValue {
    var out: runtime_schema.RelationalGeneratedValue = .{
        .op = generated.op,
        .separator = try alloc.dupe(u8, generated.separator),
    };
    errdefer freeDdlGeneratedValue(alloc, out);
    out.field = if (generated.field) |field| try alloc.dupe(u8, field) else null;
    out.fields = try cloneStringSlice(alloc, generated.fields);
    return out;
}

fn cloneDdlPrimaryKeyMaybe(alloc: std.mem.Allocator, primary_key: ?runtime_schema.PrimaryKey) !?runtime_schema.PrimaryKey {
    return if (primary_key) |key| try cloneDdlPrimaryKey(alloc, key) else null;
}

fn cloneDdlPrimaryKey(alloc: std.mem.Allocator, primary_key: runtime_schema.PrimaryKey) !runtime_schema.PrimaryKey {
    const name = if (primary_key.name) |value| try alloc.dupe(u8, value) else null;
    errdefer if (name) |value| alloc.free(value);
    const columns = try cloneStringSlice(alloc, primary_key.columns);
    errdefer freeStringSlice(alloc, columns);
    const period = if (primary_key.without_overlaps_period) |value| try alloc.dupe(u8, value) else null;
    return .{
        .name = name,
        .columns = columns,
        .without_overlaps_period = period,
    };
}

fn cloneDdlPeriod(alloc: std.mem.Allocator, period: runtime_schema.RelationalPeriod) !runtime_schema.RelationalPeriod {
    return .{
        .name = try alloc.dupe(u8, period.name),
        .start_column = try alloc.dupe(u8, period.start_column),
        .end_column = try alloc.dupe(u8, period.end_column),
        .range_type = period.range_type,
    };
}

fn cloneDdlPeriods(alloc: std.mem.Allocator, periods: []const runtime_schema.RelationalPeriod) ![]const runtime_schema.RelationalPeriod {
    if (periods.len == 0) return &.{};
    const out = try alloc.alloc(runtime_schema.RelationalPeriod, periods.len);
    var initialized: usize = 0;
    errdefer {
        for (out[0..initialized]) |period| freeDdlPeriod(alloc, period);
        alloc.free(out);
    }
    for (periods, 0..) |period, i| {
        out[i] = try cloneDdlPeriod(alloc, period);
        initialized += 1;
    }
    return out;
}

fn cloneDdlUniqueExpression(alloc: std.mem.Allocator, expression: runtime_schema.UniqueExpression) !runtime_schema.UniqueExpression {
    return .{
        .op = expression.op,
        .field = try alloc.dupe(u8, expression.field),
    };
}

fn cloneDdlUniqueExpressions(alloc: std.mem.Allocator, expressions: []const runtime_schema.UniqueExpression) ![]const runtime_schema.UniqueExpression {
    if (expressions.len == 0) return &.{};
    const out = try alloc.alloc(runtime_schema.UniqueExpression, expressions.len);
    var initialized: usize = 0;
    errdefer {
        for (out[0..initialized]) |expression| alloc.free(expression.field);
        alloc.free(out);
    }
    for (expressions, 0..) |expression, i| {
        out[i] = try cloneDdlUniqueExpression(alloc, expression);
        initialized += 1;
    }
    return out;
}

fn cloneDdlUniquePredicate(alloc: std.mem.Allocator, predicate: runtime_schema.UniquePredicate) !runtime_schema.UniquePredicate {
    const field = try alloc.dupe(u8, predicate.field);
    const value_json = if (predicate.value_json) |value|
        alloc.dupe(u8, value) catch |err| {
            alloc.free(field);
            return err;
        }
    else
        null;
    return .{
        .field = field,
        .op = predicate.op,
        .value_json = value_json,
    };
}

fn cloneDdlUniquePredicates(alloc: std.mem.Allocator, predicates: []const runtime_schema.UniquePredicate) ![]const runtime_schema.UniquePredicate {
    if (predicates.len == 0) return &.{};
    const out = try alloc.alloc(runtime_schema.UniquePredicate, predicates.len);
    var initialized: usize = 0;
    errdefer {
        for (out[0..initialized]) |predicate| {
            alloc.free(predicate.field);
            if (predicate.value_json) |value| alloc.free(value);
        }
        alloc.free(out);
    }
    for (predicates, 0..) |predicate, i| {
        out[i] = try cloneDdlUniquePredicate(alloc, predicate);
        initialized += 1;
    }
    return out;
}

fn cloneDdlUniqueConstraint(alloc: std.mem.Allocator, constraint: runtime_schema.UniqueConstraint) !runtime_schema.UniqueConstraint {
    var out: runtime_schema.UniqueConstraint = .{
        .name = try alloc.dupe(u8, constraint.name),
    };
    errdefer freeDdlUniqueConstraint(alloc, out);
    out.columns = try cloneStringSlice(alloc, constraint.columns);
    out.expressions = try cloneDdlUniqueExpressions(alloc, constraint.expressions);
    out.include_columns = try cloneStringSlice(alloc, constraint.include_columns);
    out.without_overlaps_period = if (constraint.without_overlaps_period) |period| try alloc.dupe(u8, period) else null;
    out.where = try cloneDdlUniquePredicates(alloc, constraint.where);
    out.where_expressions = try cloneExpressionConditionsAlloc(alloc, constraint.where_expressions);
    out.validation_state = constraint.validation_state;
    return out;
}

fn cloneDdlUniqueConstraints(alloc: std.mem.Allocator, constraints: []const runtime_schema.UniqueConstraint) ![]const runtime_schema.UniqueConstraint {
    if (constraints.len == 0) return &.{};
    const out = try alloc.alloc(runtime_schema.UniqueConstraint, constraints.len);
    var initialized: usize = 0;
    errdefer {
        for (out[0..initialized]) |constraint| freeDdlUniqueConstraint(alloc, constraint);
        alloc.free(out);
    }
    for (constraints, 0..) |constraint, i| {
        out[i] = try cloneDdlUniqueConstraint(alloc, constraint);
        initialized += 1;
    }
    return out;
}

fn cloneDdlForeignKey(alloc: std.mem.Allocator, foreign_key: runtime_schema.ForeignKey) !runtime_schema.ForeignKey {
    const name = try alloc.dupe(u8, foreign_key.name);
    const parent_table = alloc.dupe(u8, foreign_key.parent_table) catch |err| {
        alloc.free(name);
        return err;
    };
    var out: runtime_schema.ForeignKey = .{
        .name = name,
        .parent_table = parent_table,
        .on_delete = foreign_key.on_delete,
        .on_update = foreign_key.on_update,
        .timing = foreign_key.timing,
        .deferrable = foreign_key.deferrable,
        .match = foreign_key.match,
        .validation_state = foreign_key.validation_state,
    };
    errdefer freeDdlForeignKey(alloc, out);
    out.child_period = if (foreign_key.child_period) |period| try alloc.dupe(u8, period) else null;
    out.parent_period = if (foreign_key.parent_period) |period| try alloc.dupe(u8, period) else null;
    out.child_columns = try cloneStringSlice(alloc, foreign_key.child_columns);
    out.parent_columns = try cloneStringSlice(alloc, foreign_key.parent_columns);
    return out;
}

fn cloneDdlForeignKeys(alloc: std.mem.Allocator, foreign_keys: []const runtime_schema.ForeignKey) ![]const runtime_schema.ForeignKey {
    if (foreign_keys.len == 0) return &.{};
    const out = try alloc.alloc(runtime_schema.ForeignKey, foreign_keys.len);
    var initialized: usize = 0;
    errdefer {
        for (out[0..initialized]) |foreign_key| freeDdlForeignKey(alloc, foreign_key);
        alloc.free(out);
    }
    for (foreign_keys, 0..) |foreign_key, i| {
        out[i] = try cloneDdlForeignKey(alloc, foreign_key);
        initialized += 1;
    }
    return out;
}

fn cloneDdlRelationalCheck(alloc: std.mem.Allocator, check: runtime_schema.RelationalCheck) !runtime_schema.RelationalCheck {
    const name = try alloc.dupe(u8, check.name);
    const field = alloc.dupe(u8, check.field) catch |err| {
        alloc.free(name);
        return err;
    };
    var out: runtime_schema.RelationalCheck = .{
        .name = name,
        .field = field,
        .op = check.op,
        .validation_state = check.validation_state,
    };
    errdefer freeDdlRelationalCheck(alloc, out);
    out.value_json = if (check.value_json) |value| try alloc.dupe(u8, value) else null;
    out.expression = if (check.expression) |expression| try cloneExpressionConditionAlloc(alloc, expression) else null;
    return out;
}

fn cloneDdlRelationalChecks(alloc: std.mem.Allocator, checks: []const runtime_schema.RelationalCheck) ![]const runtime_schema.RelationalCheck {
    if (checks.len == 0) return &.{};
    const out = try alloc.alloc(runtime_schema.RelationalCheck, checks.len);
