fn renameRelationalColumnAlloc(
    alloc: std.mem.Allocator,
    schema: *runtime_schema.TableSchema,
    operation: RenameColumnOperation,
) !void {
    if (std.mem.eql(u8, operation.old_name, operation.new_name)) return error.InvalidSqlCatalog;
    const index = relationalColumnIndex(schema.relational_columns, operation.old_name) orelse return error.InvalidSqlCatalog;
    if (relationalColumnIndex(schema.relational_columns, operation.new_name) != null) return error.InvalidSqlCatalog;

    const columns = @constCast(schema.relational_columns);
    const new_name = try alloc.dupe(u8, operation.new_name);
    errdefer alloc.free(new_name);
    const new_path = try alloc.dupe(u8, operation.new_name);
    errdefer alloc.free(new_path);
    alloc.free(columns[index].name);
    alloc.free(columns[index].path);
    columns[index].name = new_name;
    columns[index].path = new_path;

    for (columns) |*column| {
        if (column.generated) |*generated| try renameGeneratedValueFieldsAlloc(alloc, generated, operation.old_name, operation.new_name);
        try renameUniquePredicatesAlloc(alloc, column.index_where, operation.old_name, operation.new_name);
        try renameExpressionConditionsAlloc(alloc, column.index_where_expressions, operation.old_name, operation.new_name);
    }
    if (schema.primary_key) |*primary_key| try renameStringSliceValuesAlloc(alloc, primary_key.columns, operation.old_name, operation.new_name);
    for (@constCast(schema.unique_constraints)) |*constraint| {
        try renameStringSliceValuesAlloc(alloc, constraint.columns, operation.old_name, operation.new_name);
        for (@constCast(constraint.expressions)) |*expression| {
            try replaceOwnedStringIfEqualAlloc(alloc, &expression.field, operation.old_name, operation.new_name);
        }
        try renameStringSliceValuesAlloc(alloc, constraint.include_columns, operation.old_name, operation.new_name);
        try renameUniquePredicatesAlloc(alloc, constraint.where, operation.old_name, operation.new_name);
        try renameExpressionConditionsAlloc(alloc, constraint.where_expressions, operation.old_name, operation.new_name);
    }
    for (@constCast(schema.foreign_keys)) |*foreign_key| {
        try renameStringSliceValuesAlloc(alloc, foreign_key.child_columns, operation.old_name, operation.new_name);
    }
    for (@constCast(schema.checks)) |*check| {
        try replaceOwnedStringIfEqualAlloc(alloc, &check.field, operation.old_name, operation.new_name);
        if (check.expression) |*expression| try renameExpressionConditionAlloc(alloc, expression, operation.old_name, operation.new_name);
    }
}

fn renameGeneratedValueFieldsAlloc(
    alloc: std.mem.Allocator,
    generated: *runtime_schema.RelationalGeneratedValue,
    old_name: []const u8,
    new_name: []const u8,
) !void {
    if (generated.field) |*field| try replaceOwnedStringIfEqualAlloc(alloc, field, old_name, new_name);
    try renameStringSliceValuesAlloc(alloc, generated.fields, old_name, new_name);
}

fn renameUniquePredicatesAlloc(
    alloc: std.mem.Allocator,
    predicates: []const runtime_schema.UniquePredicate,
    old_name: []const u8,
    new_name: []const u8,
) !void {
    for (@constCast(predicates)) |*predicate| {
        try replaceOwnedStringIfEqualAlloc(alloc, &predicate.field, old_name, new_name);
    }
}

fn renameExpressionConditionsAlloc(
    alloc: std.mem.Allocator,
    conditions: []const db_mod.types.RelationalRowsExpressionCondition,
    old_name: []const u8,
    new_name: []const u8,
) !void {
    for (@constCast(conditions)) |*condition| {
        try renameExpressionConditionAlloc(alloc, condition, old_name, new_name);
    }
}

fn renameExpressionConditionAlloc(
    alloc: std.mem.Allocator,
    condition: *db_mod.types.RelationalRowsExpressionCondition,
    old_name: []const u8,
    new_name: []const u8,
) anyerror!void {
    try renameRowExpressionFieldsAlloc(alloc, &condition.lhs, old_name, new_name);
    for (@constCast(condition.rhs)) |*rhs| {
        try renameRowExpressionFieldsAlloc(alloc, rhs, old_name, new_name);
    }
}

fn renameRowExpressionFieldsAlloc(
    alloc: std.mem.Allocator,
    expression: *db_mod.types.RelationalRowsExpression,
    old_name: []const u8,
    new_name: []const u8,
) anyerror!void {
    if (expression.field_source == .row) try replaceOwnedStringIfEqualAlloc(alloc, &expression.field, old_name, new_name);
    for (@constCast(expression.operands)) |*operand| {
        try renameRowExpressionFieldsAlloc(alloc, operand, old_name, new_name);
    }
    for (@constCast(expression.case_branches)) |*branch| {
        try renameExpressionConditionAlloc(alloc, &branch.when, old_name, new_name);
        try renameRowExpressionFieldsAlloc(alloc, &branch.then, old_name, new_name);
    }
    for (@constCast(expression.case_else)) |*case_else| {
        try renameRowExpressionFieldsAlloc(alloc, case_else, old_name, new_name);
    }
}

fn renameStringSliceValuesAlloc(
    alloc: std.mem.Allocator,
    values: []const []const u8,
    old_name: []const u8,
    new_name: []const u8,
) !void {
    for (@constCast(values)) |*value| {
        try replaceOwnedStringIfEqualAlloc(alloc, value, old_name, new_name);
    }
}

fn replaceOwnedStringIfEqualAlloc(
    alloc: std.mem.Allocator,
    value: *[]const u8,
    old_name: []const u8,
    new_name: []const u8,
) !void {
    if (!std.mem.eql(u8, value.*, old_name)) return;
    const replacement = try alloc.dupe(u8, new_name);
    alloc.free(value.*);
    value.* = replacement;
}

fn dropRelationalColumnAlloc(
    alloc: std.mem.Allocator,
    schema: *runtime_schema.TableSchema,
    drop_column: DropColumnOperation,
) !void {
    if (relationalColumnIndex(schema.relational_columns, drop_column.name) == null) {
        if (drop_column.if_exists) return;
        return error.InvalidSqlCatalog;
    }

    var dropped = std.ArrayListUnmanaged([]const u8).empty;
    defer dropped.deinit(alloc);
    try appendUniqueBorrowedString(alloc, &dropped, drop_column.name);

    var changed = true;
    while (changed) {
        changed = false;
        for (schema.relational_columns) |column| {
            if (stringSlicesContains(dropped.items, column.name)) continue;
            if (generatedColumnReferencesAny(column, dropped.items)) {
                try appendUniqueBorrowedString(alloc, &dropped, column.name);
                changed = true;
            }
        }
    }

    if (schema.primary_key) |primary_key| {
        if (stringSlicesIntersect(primary_key.columns, dropped.items)) return error.UnsupportedSqlShape;
    }
    if (drop_column.dependency_mode == .restrict and schemaHasDropDependencies(schema.*, dropped.items)) {
        return error.InvalidSqlCatalog;
    }

    try dropRelationalColumnsAlloc(alloc, schema, dropped.items);
    try dropDependentUniqueConstraintsAlloc(alloc, schema, dropped.items);
    try dropDependentForeignKeysAlloc(alloc, schema, dropped.items);
    try dropDependentChecksAlloc(alloc, schema, dropped.items);
}

fn schemaHasDropDependencies(schema: runtime_schema.TableSchema, dropped: []const []const u8) bool {
    if (dropped.len > 1) return true;
    for (schema.unique_constraints) |constraint| {
        if (uniqueConstraintReferencesAny(constraint, dropped)) return true;
    }
    for (schema.foreign_keys) |foreign_key| {
        if (stringSlicesIntersect(foreign_key.child_columns, dropped)) return true;
    }
    for (schema.checks) |check| {
        if (stringSlicesContains(dropped, check.field)) return true;
    }
    return false;
}

fn dropRelationalColumnsAlloc(
    alloc: std.mem.Allocator,
    schema: *runtime_schema.TableSchema,
    dropped: []const []const u8,
) !void {
    var kept: usize = 0;
    for (schema.relational_columns) |column| {
        if (!stringSlicesContains(dropped, column.name)) kept += 1;
    }
    const out: []runtime_schema.RelationalColumn = if (kept > 0) try alloc.alloc(runtime_schema.RelationalColumn, kept) else &.{};
    var out_i: usize = 0;
    for (schema.relational_columns) |column| {
        if (stringSlicesContains(dropped, column.name)) {
            freeDdlRelationalColumn(alloc, column);
        } else {
            out[out_i] = column;
            out_i += 1;
        }
    }
    if (schema.relational_columns.len > 0) alloc.free(schema.relational_columns);
    schema.relational_columns = out;
}

fn dropDependentUniqueConstraintsAlloc(
    alloc: std.mem.Allocator,
    schema: *runtime_schema.TableSchema,
    dropped: []const []const u8,
) !void {
    var kept: usize = 0;
    for (schema.unique_constraints) |constraint| {
        if (!uniqueConstraintReferencesAny(constraint, dropped)) kept += 1;
    }
    const out: []runtime_schema.UniqueConstraint = if (kept > 0) try alloc.alloc(runtime_schema.UniqueConstraint, kept) else &.{};
    var out_i: usize = 0;
    for (schema.unique_constraints) |constraint| {
        if (uniqueConstraintReferencesAny(constraint, dropped)) {
            freeDdlUniqueConstraint(alloc, constraint);
        } else {
            out[out_i] = constraint;
            out_i += 1;
        }
    }
    if (schema.unique_constraints.len > 0) alloc.free(schema.unique_constraints);
    schema.unique_constraints = out;
}

fn dropDependentForeignKeysAlloc(
    alloc: std.mem.Allocator,
    schema: *runtime_schema.TableSchema,
    dropped: []const []const u8,
) !void {
    var kept: usize = 0;
    for (schema.foreign_keys) |foreign_key| {
        if (!stringSlicesIntersect(foreign_key.child_columns, dropped)) kept += 1;
    }
    const out: []runtime_schema.ForeignKey = if (kept > 0) try alloc.alloc(runtime_schema.ForeignKey, kept) else &.{};
    var out_i: usize = 0;
    for (schema.foreign_keys) |foreign_key| {
        if (stringSlicesIntersect(foreign_key.child_columns, dropped)) {
            freeDdlForeignKey(alloc, foreign_key);
        } else {
            out[out_i] = foreign_key;
            out_i += 1;
        }
    }
    if (schema.foreign_keys.len > 0) alloc.free(schema.foreign_keys);
    schema.foreign_keys = out;
}

fn dropDependentChecksAlloc(
    alloc: std.mem.Allocator,
    schema: *runtime_schema.TableSchema,
    dropped: []const []const u8,
) !void {
    var kept: usize = 0;
    for (schema.checks) |check| {
        if (!stringSlicesContains(dropped, check.field)) kept += 1;
    }
    const out: []runtime_schema.RelationalCheck = if (kept > 0) try alloc.alloc(runtime_schema.RelationalCheck, kept) else &.{};
    var out_i: usize = 0;
    for (schema.checks) |check| {
        if (stringSlicesContains(dropped, check.field)) {
            freeDdlRelationalCheck(alloc, check);
        } else {
            out[out_i] = check;
            out_i += 1;
        }
    }
    if (schema.checks.len > 0) alloc.free(schema.checks);
    schema.checks = out;
}

fn dropRelationalConstraintAlloc(
    alloc: std.mem.Allocator,
    schema: *runtime_schema.TableSchema,
    table_name: []const u8,
    drop_constraint: DropConstraintOperation,
) !void {
    if (try dropPrimaryKeyByNameAlloc(alloc, schema, table_name, drop_constraint.name)) return;
    if (try dropUniqueConstraintByNameAlloc(alloc, schema, drop_constraint.name)) return;
    if (try dropForeignKeyByNameAlloc(alloc, schema, drop_constraint.name)) return;
    if (try dropRelationalCheckByNameAlloc(alloc, schema, drop_constraint.name)) return;
    if (drop_constraint.if_exists) return;
    return error.InvalidSqlCatalog;
}

fn dropPrimaryKeyByNameAlloc(
    alloc: std.mem.Allocator,
    schema: *runtime_schema.TableSchema,
    table_name: []const u8,
    constraint_name: []const u8,
) !bool {
    const primary_key = schema.primary_key orelse return false;
    if (!primaryKeyNameEquals(primary_key, table_name, constraint_name)) return false;
    freeDdlPrimaryKey(alloc, primary_key);
    schema.primary_key = null;
    return true;
}

fn dropIndexFromRuntimeSchemaAlloc(
    alloc: std.mem.Allocator,
    schema: *runtime_schema.TableSchema,
    plan: DropIndexPlan,
) !void {
    if (try dropUniqueConstraintByNameAlloc(alloc, schema, plan.index_name)) return;
    if (try dropSecondaryIndexByNameAlloc(alloc, schema, plan.index_name)) return;
    if (plan.if_exists) return;
    return error.InvalidSqlCatalog;
}

fn dropSecondaryIndexByNameAlloc(
    alloc: std.mem.Allocator,
    schema: *runtime_schema.TableSchema,
    index_name: []const u8,
) !bool {
    const index = relationalColumnIndexForIndexName(schema.relational_columns, index_name) orelse return false;
    if (schema.relational_columns[index].generated != null) {
        const column_name = schema.relational_columns[index].name;
        try dropRelationalColumnAlloc(alloc, schema, .{ .name = column_name, .if_exists = false, .dependency_mode = .cascade });
        return true;
    }

    const columns = @constCast(schema.relational_columns);
    var removed = false;
    for (columns) |*column| {
        if (!relationalColumnHasIndexName(column.*, index_name)) continue;
        if (column.generated != null) return error.InvalidSqlCatalog;
        column.indexed = false;
        column.index_lifecycle = .ready;
        column.index_generation = 0;
        if (column.index_name) |existing| {
            alloc.free(existing);
            column.index_name = null;
        }
        freeStringSlice(alloc, column.index_include_columns);
        column.index_include_columns = &.{};
        freeDdlUniquePredicates(alloc, column.index_where);
        column.index_where = &.{};
        freeExpressionConditions(alloc, column.index_where_expressions);
        if (column.index_where_expressions.len > 0) alloc.free(column.index_where_expressions);
        column.index_where_expressions = &.{};
        removed = true;
    }
    return removed;
}

fn renameRelationalConstraintAlloc(
    alloc: std.mem.Allocator,
    schema: *runtime_schema.TableSchema,
    table_name: []const u8,
    operation: RenameConstraintOperation,
) !void {
    if (std.mem.eql(u8, operation.old_name, operation.new_name)) return error.InvalidSqlCatalog;
    if (relationalConstraintNameExists(schema.*, table_name, operation.new_name)) return error.InvalidSqlCatalog;
    if (try renamePrimaryKeyConstraintByNameAlloc(alloc, schema, table_name, operation.old_name, operation.new_name)) return;
    if (try renameUniqueConstraintByNameAlloc(alloc, schema, operation.old_name, operation.new_name)) return;
    if (try renameForeignKeyByNameAlloc(alloc, schema, operation.old_name, operation.new_name)) return;
    if (try renameRelationalCheckByNameAlloc(alloc, schema, operation.old_name, operation.new_name)) return;
    return error.InvalidSqlCatalog;
}

fn relationalConstraintNameExists(schema: runtime_schema.TableSchema, table_name: []const u8, name: []const u8) bool {
    return primaryKeyNameEquals(schema.primary_key, table_name, name) or
        uniqueConstraintNameExists(schema.unique_constraints, name) or
        foreignKeyNameExists(schema.foreign_keys, name) or
        relationalCheckNameExists(schema.checks, name);
}

fn primaryKeyNameEquals(primary_key: ?runtime_schema.PrimaryKey, table_name: []const u8, name: []const u8) bool {
    const key = primary_key orelse return false;
    if (key.name) |key_name| return std.mem.eql(u8, key_name, name);
    return defaultPrimaryKeyNameEquals(table_name, name);
}

fn defaultPrimaryKeyNameEquals(table_name: []const u8, name: []const u8) bool {
    const suffix = "_pkey";
    return name.len == table_name.len + suffix.len and
        std.mem.startsWith(u8, name, table_name) and
        std.mem.endsWith(u8, name, suffix);
}

fn renamePrimaryKeyConstraintByNameAlloc(
    alloc: std.mem.Allocator,
    schema: *runtime_schema.TableSchema,
    table_name: []const u8,
    old_name: []const u8,
    new_name: []const u8,
) !bool {
    if (schema.primary_key) |*primary_key| {
        if (primary_key.name) |*name| {
            if (!std.mem.eql(u8, name.*, old_name)) return false;
            try replaceOwnedStringIfEqualAlloc(alloc, name, old_name, new_name);
            return true;
        }
        if (!defaultPrimaryKeyNameEquals(table_name, old_name)) return false;
        primary_key.name = try alloc.dupe(u8, new_name);
        return true;
    }
    return false;
}

fn renameUniqueConstraintByNameAlloc(
    alloc: std.mem.Allocator,
    schema: *runtime_schema.TableSchema,
    old_name: []const u8,
    new_name: []const u8,
) !bool {
    for (@constCast(schema.unique_constraints)) |*constraint| {
        if (!std.mem.eql(u8, constraint.name, old_name)) continue;
        try replaceOwnedStringIfEqualAlloc(alloc, &constraint.name, old_name, new_name);
        return true;
    }
    return false;
}

fn renameForeignKeyByNameAlloc(
    alloc: std.mem.Allocator,
    schema: *runtime_schema.TableSchema,
    old_name: []const u8,
    new_name: []const u8,
) !bool {
    for (@constCast(schema.foreign_keys)) |*foreign_key| {
        if (!std.mem.eql(u8, foreign_key.name, old_name)) continue;
        try replaceOwnedStringIfEqualAlloc(alloc, &foreign_key.name, old_name, new_name);
        return true;
    }
    return false;
}

fn renameRelationalCheckByNameAlloc(
    alloc: std.mem.Allocator,
    schema: *runtime_schema.TableSchema,
    old_name: []const u8,
    new_name: []const u8,
) !bool {
    for (@constCast(schema.checks)) |*check| {
        if (!std.mem.eql(u8, check.name, old_name)) continue;
        try replaceOwnedStringIfEqualAlloc(alloc, &check.name, old_name, new_name);
        return true;
    }
    return false;
}

fn dropUniqueConstraintByNameAlloc(
    alloc: std.mem.Allocator,
    schema: *runtime_schema.TableSchema,
    constraint_name: []const u8,
) !bool {
    var found = false;
    for (schema.unique_constraints) |constraint| {
        if (std.mem.eql(u8, constraint.name, constraint_name)) {
            found = true;
            break;
        }
    }
    if (!found) return false;

    const kept = schema.unique_constraints.len - 1;
    const out: []runtime_schema.UniqueConstraint = if (kept > 0) try alloc.alloc(runtime_schema.UniqueConstraint, kept) else &.{};
    var out_i: usize = 0;
    for (schema.unique_constraints) |constraint| {
        if (std.mem.eql(u8, constraint.name, constraint_name)) {
            freeDdlUniqueConstraint(alloc, constraint);
        } else {
            out[out_i] = constraint;
            out_i += 1;
        }
    }
    if (schema.unique_constraints.len > 0) alloc.free(schema.unique_constraints);
    schema.unique_constraints = out;
    return true;
}

fn dropForeignKeyByNameAlloc(
    alloc: std.mem.Allocator,
    schema: *runtime_schema.TableSchema,
    constraint_name: []const u8,
) !bool {
    var found = false;
    for (schema.foreign_keys) |foreign_key| {
        if (std.mem.eql(u8, foreign_key.name, constraint_name)) {
            found = true;
            break;
        }
    }
    if (!found) return false;

    const kept = schema.foreign_keys.len - 1;
    const out: []runtime_schema.ForeignKey = if (kept > 0) try alloc.alloc(runtime_schema.ForeignKey, kept) else &.{};
    var out_i: usize = 0;
    for (schema.foreign_keys) |foreign_key| {
        if (std.mem.eql(u8, foreign_key.name, constraint_name)) {
            freeDdlForeignKey(alloc, foreign_key);
        } else {
            out[out_i] = foreign_key;
            out_i += 1;
        }
    }
    if (schema.foreign_keys.len > 0) alloc.free(schema.foreign_keys);
    schema.foreign_keys = out;
    return true;
}

fn dropRelationalCheckByNameAlloc(
    alloc: std.mem.Allocator,
    schema: *runtime_schema.TableSchema,
    constraint_name: []const u8,
) !bool {
    var found = false;
    for (schema.checks) |check| {
        if (std.mem.eql(u8, check.name, constraint_name)) {
            found = true;
            break;
        }
    }
    if (!found) return false;

    const kept = schema.checks.len - 1;
    const out: []runtime_schema.RelationalCheck = if (kept > 0) try alloc.alloc(runtime_schema.RelationalCheck, kept) else &.{};
    var out_i: usize = 0;
    for (schema.checks) |check| {
        if (std.mem.eql(u8, check.name, constraint_name)) {
            freeDdlRelationalCheck(alloc, check);
        } else {
            out[out_i] = check;
            out_i += 1;
        }
    }
    if (schema.checks.len > 0) alloc.free(schema.checks);
    schema.checks = out;
    return true;
}

fn validateConstraintByName(schema: *runtime_schema.TableSchema, table_name: []const u8, constraint_name: []const u8) !void {
    if (primaryKeyNameEquals(schema.primary_key, table_name, constraint_name)) return;
    {
        const constraints = @constCast(schema.unique_constraints);
        for (constraints) |*constraint| {
            if (!std.mem.eql(u8, constraint.name, constraint_name)) continue;
            constraint.validation_state = .enforced;
            return;
        }
    }
    {
        const foreign_keys = @constCast(schema.foreign_keys);
        for (foreign_keys) |*foreign_key| {
            if (!std.mem.eql(u8, foreign_key.name, constraint_name)) continue;
            foreign_key.validation_state = .enforced;
            return;
        }
    }
    {
        const checks = @constCast(schema.checks);
        for (checks) |*check| {
            if (!std.mem.eql(u8, check.name, constraint_name)) continue;
            check.validation_state = .enforced;
            return;
        }
    }
    return error.InvalidSqlCatalog;
}

fn alterRelationalColumnDefaultAlloc(
    alloc: std.mem.Allocator,
    schema: *runtime_schema.TableSchema,
    operation: AlterColumnDefaultOperation,
) !void {
    const index = relationalColumnIndex(schema.relational_columns, operation.column_name) orelse return error.InvalidSqlCatalog;
    const columns = @constCast(schema.relational_columns);
    if (columns[index].generated != null) return error.InvalidSqlCatalog;
    if (operation.default_value) |default_value| {
        try validateDefaultValueForColumnAlloc(alloc, columns[index], default_value);
    }
    if (columns[index].default_value) |existing| {
        alloc.free(existing.value_json);
        columns[index].default_value = null;
    }
    if (operation.default_value) |default_value| {
        columns[index].default_value = try cloneDdlDefaultValue(alloc, default_value);
    }
}

fn alterRelationalColumnNullability(
    schema: *runtime_schema.TableSchema,
    operation: AlterColumnNullabilityOperation,
) !void {
    const index = relationalColumnIndex(schema.relational_columns, operation.column_name) orelse return error.InvalidSqlCatalog;
    if (operation.nullable) {
        if (schema.primary_key) |primary_key| {
            if (primaryKeyContains(primary_key, operation.column_name)) return error.UnsupportedSqlShape;
        }
    }
    const columns = @constCast(schema.relational_columns);
    columns[index].nullable = operation.nullable;
}

fn alterRelationalColumnTypeAlloc(
    alloc: std.mem.Allocator,
    schema: *runtime_schema.TableSchema,
    operation: AlterColumnTypeOperation,
) !void {
    const index = relationalColumnIndex(schema.relational_columns, operation.column_name) orelse return error.InvalidSqlCatalog;
    const columns = @constCast(schema.relational_columns);
    if (columns[index].generated != null) return error.UnsupportedSqlShape;
    if (operation.collation != null and !relationalFieldTypeSupportsCollation(operation.field_type)) return error.UnsupportedSqlShape;
    if (!relationalFieldTypeSupportsCollation(operation.field_type) and columns[index].collation != null) return error.UnsupportedSqlShape;
    const new_array_item_type = if (operation.field_type == .array) operation.array_item_type orelse return error.InvalidSqlCatalog else null;
    const new_collation = if (operation.collation) |collation| try alloc.dupe(u8, collation) else null;
    columns[index].field_type = operation.field_type;
    columns[index].array_item_type = new_array_item_type;
    if (new_collation) |collation| {
        if (columns[index].collation) |existing| alloc.free(existing);
        columns[index].collation = collation;
    }
    if (columns[index].default_value) |default_value| try validateDefaultValueForColumnAlloc(alloc, columns[index], default_value);
    if (columns[index].on_update_value) |on_update_value| try validateDefaultValueForColumnAlloc(alloc, columns[index], on_update_value);
    try validateRelationalColumnCatalog(schema.relational_columns);
    try validateRelationalPeriodCatalog(schema.relational_columns, schema.periods);
    if (schema.primary_key) |primary_key| {
        try validatePrimaryKeyColumns(schema.relational_columns, primary_key);
        try validatePrimaryKeyTemporalCatalog(schema.periods, primary_key);
        if (primary_key.name) |name| {
            if (uniqueConstraintNameExists(schema.unique_constraints, name) or
                foreignKeyNameExists(schema.foreign_keys, name) or
                relationalCheckNameExists(schema.checks, name))
            {
                return error.InvalidSqlCatalog;
            }
        }
    }
    try validateUniqueConstraintCatalog(schema.relational_columns, schema.periods, schema.unique_constraints);
    try validateForeignKeyCatalog(schema.relational_columns, schema.periods, schema.foreign_keys);
    try validateRelationalCheckCatalog(schema.relational_columns, schema.checks);
}

fn validateDefaultValueForColumnAlloc(
    alloc: std.mem.Allocator,
    column: runtime_schema.RelationalColumn,
    default_value: runtime_schema.RelationalDefaultValue,
) !void {
    switch (default_value.kind) {
        .uuid_v4 => {
            if (column.field_type != .keyword and column.field_type != .text and column.field_type != .link) return error.UnsupportedSqlShape;
        },
        .now_ns => {
            if (column.field_type != .numeric and column.field_type != .datetime) return error.UnsupportedSqlShape;
        },
        .current_date_ns => {
            if (column.field_type != .numeric and column.field_type != .datetime) return error.UnsupportedSqlShape;
        },
        .literal => try validateLiteralDefaultForColumnAlloc(alloc, column, default_value.value_json),
    }
}

fn validateLiteralDefaultForColumnAlloc(
    alloc: std.mem.Allocator,
    column: runtime_schema.RelationalColumn,
    value_json: []const u8,
) !void {
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, value_json, .{}) catch return error.UnsupportedSqlShape;
    defer parsed.deinit();
    if (parsed.value == .null) return;
    switch (column.field_type) {
        .keyword, .text, .link, .blob, .datetime => {
            if (parsed.value != .string) return error.UnsupportedSqlShape;
        },
        .numeric => switch (parsed.value) {
            .integer, .float => {},
            else => return error.UnsupportedSqlShape,
        },
        .boolean => {
            if (parsed.value != .bool) return error.UnsupportedSqlShape;
        },
        .json => {},
        .array => {
            if (parsed.value != .array) return error.UnsupportedSqlShape;
        },
        else => return error.UnsupportedSqlShape,
    }
}

fn markColumnIndexedAlloc(
    alloc: std.mem.Allocator,
    schema: *runtime_schema.TableSchema,
    index_name: []const u8,
    column_name: []const u8,
    include_columns: []const []const u8,
    predicates: []const runtime_schema.UniquePredicate,
    expression_predicates: []const db_mod.types.RelationalRowsExpressionCondition,
    index_generation: u64,
) !void {
    const index = relationalColumnIndex(schema.relational_columns, column_name) orelse return error.InvalidSqlCatalog;
    const columns = @constCast(schema.relational_columns);
    if (columns[index].index_name) |existing| {
        if (!std.mem.eql(u8, existing, index_name)) return error.InvalidSqlCatalog;
    }
    const cloned_predicates = try cloneDdlUniquePredicates(alloc, predicates);
    errdefer freeDdlUniquePredicates(alloc, cloned_predicates);
    const cloned_expression_predicates = try cloneExpressionConditionsAlloc(alloc, expression_predicates);
    errdefer {
        freeExpressionConditions(alloc, cloned_expression_predicates);
        if (cloned_expression_predicates.len > 0) alloc.free(cloned_expression_predicates);
    }
    const cloned_index_name = try alloc.dupe(u8, index_name);
    errdefer alloc.free(cloned_index_name);
    const cloned_include_columns = try cloneStringSlice(alloc, include_columns);
    errdefer freeStringSlice(alloc, cloned_include_columns);
    freeDdlUniquePredicates(alloc, columns[index].index_where);
    freeExpressionConditions(alloc, columns[index].index_where_expressions);
    if (columns[index].index_where_expressions.len > 0) alloc.free(columns[index].index_where_expressions);
    if (columns[index].index_name) |existing| alloc.free(existing);
    freeStringSlice(alloc, columns[index].index_include_columns);
    columns[index].indexed = true;
    columns[index].index_lifecycle = .building;
    columns[index].index_generation = index_generation;
    columns[index].index_name = cloned_index_name;
    columns[index].index_include_columns = cloned_include_columns;
    columns[index].index_where = cloned_predicates;
    columns[index].index_where_expressions = cloned_expression_predicates;
}

fn markColumnsIndexedAlloc(
    alloc: std.mem.Allocator,
    schema: *runtime_schema.TableSchema,
    index_name: []const u8,
    column_names: []const []const u8,
    include_columns: []const []const u8,
    predicates: []const runtime_schema.UniquePredicate,
    expression_predicates: []const db_mod.types.RelationalRowsExpressionCondition,
    index_generation: u64,
) !void {
    for (column_names) |column_name| {
        const index = relationalColumnIndex(schema.relational_columns, column_name) orelse return error.InvalidSqlCatalog;
        if (schema.relational_columns[index].index_name) |existing| {
            if (!std.mem.eql(u8, existing, index_name)) return error.InvalidSqlCatalog;
        }
    }
    for (column_names) |column_name| {
        try markColumnIndexedAlloc(alloc, schema, index_name, column_name, include_columns, predicates, expression_predicates, index_generation);
    }
}

fn stableSecondaryIndexGeneration(plan: CreateIndexPlan) u64 {
    var hasher = std.hash.Wyhash.init(0x5149_2026_5345_4349);
    hashPlanField(&hasher, "secondary-index-v1");
    hashPlanField(&hasher, plan.index_name);
    hashPlanU64(&hasher, @intFromEnum(plan.method));
    hashPlanU64(&hasher, @intCast(plan.columns.len));
    for (plan.columns) |column| hashPlanField(&hasher, column);
    hashPlanU64(&hasher, @intCast(plan.include_columns.len));
    for (plan.include_columns) |column| hashPlanField(&hasher, column);
    hashPlanU64(&hasher, @intCast(plan.expressions.len));
    for (plan.expressions) |expression| {
        hashPlanU64(&hasher, @intFromEnum(expression.op));
        hashPlanField(&hasher, expression.field);
    }
    if (plan.generated_expression) |generated| {
        hasher.update(&.{1});
        hashPlanU64(&hasher, @intFromEnum(generated.op));
        if (generated.field) |field| {
            hasher.update(&.{1});
            hashPlanField(&hasher, field);
        } else {
            hasher.update(&.{0});
        }
        hashPlanU64(&hasher, @intCast(generated.fields.len));
        for (generated.fields) |field| hashPlanField(&hasher, field);
        hashPlanField(&hasher, generated.separator);
    } else {
        hasher.update(&.{0});
    }
    hashPlanU64(&hasher, @intCast(plan.where.len));
    for (plan.where) |predicate| {
        hashPlanU64(&hasher, @intFromEnum(predicate.op));
        hashPlanField(&hasher, predicate.field);
        if (predicate.value_json) |value| {
            hasher.update(&.{1});
            hashPlanField(&hasher, value);
        } else {
            hasher.update(&.{0});
        }
    }
    hashPlanU64(&hasher, @intCast(plan.where_expressions.len));
    for (plan.where_expressions) |condition| {
        hashPlanExpressionCondition(&hasher, condition);
    }
    const json_integer_max: u64 = @intCast(std.math.maxInt(i64));
    const generation = hasher.final() & json_integer_max;
    return if (generation == 0) 1 else generation;
}

fn hashPlanExpressionCondition(
    hasher: *std.hash.Wyhash,
    condition: db_mod.types.RelationalRowsExpressionCondition,
) void {
    hashPlanU64(hasher, @intFromEnum(condition.op));
    hashPlanExpression(hasher, condition.lhs);
    hashPlanU64(hasher, @intCast(condition.rhs.len));
    for (condition.rhs) |rhs| hashPlanExpression(hasher, rhs);
}

fn hashPlanExpression(
    hasher: *std.hash.Wyhash,
    expression: db_mod.types.RelationalRowsExpression,
) void {
    hashPlanU64(hasher, @intFromEnum(expression.kind));
    hashPlanU64(hasher, @intFromEnum(expression.field_source));
    hashPlanU64(hasher, @intCast(@intFromBool(expression.json_as_text)));
    hashPlanField(hasher, expression.field);
    hashPlanField(hasher, expression.value_json);
    hashPlanField(hasher, expression.json_path);
    if (expression.cast_type) |cast_type| {
        hasher.update(&.{1});
        hashPlanU64(hasher, @intFromEnum(cast_type));
    } else {
        hasher.update(&.{0});
    }
    hashPlanU64(hasher, @intCast(expression.operands.len));
    for (expression.operands) |operand| hashPlanExpression(hasher, operand);
    hashPlanU64(hasher, @intCast(expression.case_branches.len));
    for (expression.case_branches) |branch| {
        hashPlanExpressionCondition(hasher, branch.when);
        hashPlanExpression(hasher, branch.then);
    }
    hashPlanU64(hasher, @intCast(expression.case_else.len));
    for (expression.case_else) |case_else| hashPlanExpression(hasher, case_else);
}

fn hashPlanField(hasher: *std.hash.Wyhash, value: []const u8) void {
    hashPlanU64(hasher, @intCast(value.len));
    hasher.update(value);
}

fn hashPlanU64(hasher: *std.hash.Wyhash, value: u64) void {
    var buf: [8]u8 = undefined;
    std.mem.writeInt(u64, &buf, value, .big);
    hasher.update(&buf);
}

fn relationalIndexLifecycleName(lifecycle: runtime_schema.RelationalIndexLifecycle) []const u8 {
    return switch (lifecycle) {
        .ready => "ready",
        .building => "building",
        .invalid => "invalid",
        .dropping => "dropping",
    };
}

fn setColumnOnUpdatePolicyAlloc(
    alloc: std.mem.Allocator,
    schema: *runtime_schema.TableSchema,
    column_name: []const u8,
    value: runtime_schema.RelationalDefaultValue,
) !void {
    const index = relationalColumnIndex(schema.relational_columns, column_name) orelse return error.InvalidSqlCatalog;
    const columns = @constCast(schema.relational_columns);
    if (columns[index].field_type != .numeric and columns[index].field_type != .datetime) return error.InvalidSqlCatalog;
    const cloned_value = try cloneDdlDefaultValue(alloc, value);
    errdefer alloc.free(cloned_value.value_json);
    if (columns[index].on_update_value) |existing| alloc.free(existing.value_json);
    columns[index].on_update_value = cloned_value;
}

fn validateRelationalColumnCatalog(columns: []const runtime_schema.RelationalColumn) !void {
    for (columns, 0..) |column, i| {
        if (relationalColumnIndex(columns[0..i], column.name) != null) return error.InvalidSqlCatalog;
        if (!std.mem.eql(u8, column.name, column.path)) return error.InvalidSqlCatalog;
        if (column.collation != null and !relationalFieldTypeSupportsCollation(column.field_type)) return error.InvalidSqlCatalog;
        if (column.generated) |_| try validateGeneratedColumnForColumns(columns, column);
        try validateUniquePredicatesForColumns(columns, column.index_where);
        try validateUniquePredicateExpressionsForColumns(columns, column.index_where_expressions);
        try validateRelationalColumnIndexIncludes(columns, column);
        if (column.on_update_value) |_| {
            if (column.field_type != .numeric and column.field_type != .datetime) return error.InvalidSqlCatalog;
        }
    }
}

fn validateRelationalColumnIndexIncludes(columns: []const runtime_schema.RelationalColumn, column: runtime_schema.RelationalColumn) !void {
    if (column.index_include_columns.len == 0) return;
    if (!column.indexed or column.index_name == null) return error.InvalidSqlCatalog;
    for (column.index_include_columns) |field| {
        _ = relationalColumnForDdl(columns, field) orelse return error.InvalidSqlCatalog;
    }
    const index_name = column.index_name.?;
    for (columns) |peer| {
        if (!relationalColumnHasDeclaredIndexName(peer, index_name)) continue;
        if (!stringSlicesEqual(peer.index_include_columns, column.index_include_columns)) return error.InvalidSqlCatalog;
        if (stringSlicesContains(column.index_include_columns, peer.name)) return error.InvalidSqlCatalog;
    }
}

fn validateUniqueConstraintCatalog(columns: []const runtime_schema.RelationalColumn, periods: []const runtime_schema.RelationalPeriod, constraints: []const runtime_schema.UniqueConstraint) !void {
    for (constraints, 0..) |constraint, i| {
        if (uniqueConstraintNameExists(constraints[0..i], constraint.name)) return error.InvalidSqlCatalog;
        try validateUniqueConstraintForColumns(columns, periods, constraint);
    }
}

fn validateForeignKeyCatalog(columns: []const runtime_schema.RelationalColumn, periods: []const runtime_schema.RelationalPeriod, foreign_keys: []const runtime_schema.ForeignKey) !void {
    for (foreign_keys, 0..) |foreign_key, i| {
        if (foreignKeyNameExists(foreign_keys[0..i], foreign_key.name)) return error.InvalidSqlCatalog;
        try validateForeignKeyForColumns(columns, periods, foreign_key);
    }
}

fn validateRelationalCheckCatalog(columns: []const runtime_schema.RelationalColumn, checks: []const runtime_schema.RelationalCheck) !void {
    for (checks, 0..) |check, i| {
        if (relationalCheckNameExists(checks[0..i], check.name)) return error.InvalidSqlCatalog;
        try validateCheckForColumns(columns, check);
    }
}

fn validatePrimaryKeyColumns(columns: []const runtime_schema.RelationalColumn, primary_key: runtime_schema.PrimaryKey) !void {
    if (primary_key.columns.len == 0) return error.InvalidSqlCatalog;
    for (primary_key.columns) |column| {
        const found = relationalColumnForDdl(columns, column) orelse return error.InvalidSqlCatalog;
        if (found.nullable) return error.InvalidSqlCatalog;
    }
}

fn validateRelationalPeriodCatalog(columns: []const runtime_schema.RelationalColumn, periods: []const runtime_schema.RelationalPeriod) !void {
    for (periods, 0..) |period, i| {
        if (relationalPeriodNameExists(periods[0..i], period.name)) return error.InvalidSqlCatalog;
        if (std.mem.eql(u8, period.start_column, period.end_column)) return error.InvalidSqlCatalog;
        const start_column = relationalColumnForDdl(columns, period.start_column) orelse return error.InvalidSqlCatalog;
        const end_column = relationalColumnForDdl(columns, period.end_column) orelse return error.InvalidSqlCatalog;
        if (!relationalPeriodColumnType(start_column.field_type) or !relationalPeriodColumnType(end_column.field_type)) return error.InvalidSqlCatalog;
        if (start_column.field_type != end_column.field_type) return error.InvalidSqlCatalog;
        if (period.range_type) |range_type| {
            switch (range_type) {
                .numrange => if (start_column.field_type != .numeric) return error.InvalidSqlCatalog,
                .daterange, .tsrange, .tstzrange => if (start_column.field_type != .datetime) return error.InvalidSqlCatalog,
            }
        }
    }
}

fn validatePrimaryKeyTemporalCatalog(periods: []const runtime_schema.RelationalPeriod, primary_key: runtime_schema.PrimaryKey) !void {
    if (primary_key.without_overlaps_period) |period| {
        _ = relationalPeriodForDdl(periods, period) orelse return error.InvalidSqlCatalog;
    }
}

fn relationalPeriodColumnType(field_type: runtime_schema.AntflyType) bool {
    return field_type == .numeric or field_type == .datetime;
}

fn relationalPeriodForDdl(periods: []const runtime_schema.RelationalPeriod, name: []const u8) ?runtime_schema.RelationalPeriod {
    for (periods) |period| {
        if (std.mem.eql(u8, period.name, name)) return period;
    }
    return null;
}

fn relationalPeriodNameExists(periods: []const runtime_schema.RelationalPeriod, name: []const u8) bool {
    return relationalPeriodForDdl(periods, name) != null;
}

fn validateUniqueConstraintForColumns(columns: []const runtime_schema.RelationalColumn, periods: []const runtime_schema.RelationalPeriod, constraint: runtime_schema.UniqueConstraint) !void {
    if (constraint.columns.len == 0 and constraint.expressions.len == 0) return error.InvalidSqlCatalog;
    if (constraint.without_overlaps_period) |period| {
        _ = relationalPeriodForDdl(periods, period) orelse return error.InvalidSqlCatalog;
    }
    for (constraint.columns) |column| {
        const found = relationalColumnForDdl(columns, column) orelse return error.InvalidSqlCatalog;
        if (found.field_type == .json or found.field_type == .array) return error.InvalidSqlCatalog;
    }
    for (constraint.expressions) |expression| {
        switch (expression.op) {
            .lower, .upper, .md5 => {
                const found = relationalColumnForDdl(columns, expression.field) orelse return error.InvalidSqlCatalog;
                if (found.field_type == .json or found.field_type == .array) return error.InvalidSqlCatalog;
            },
        }
    }
    try validateCreateIndexIncludeColumns(columns, constraint.columns, constraint.include_columns);
    try validateUniquePredicatesForColumns(columns, constraint.where);
    try validateUniquePredicateExpressionsForColumns(columns, constraint.where_expressions);
}

fn validateForeignKeyForColumns(columns: []const runtime_schema.RelationalColumn, periods: []const runtime_schema.RelationalPeriod, foreign_key: runtime_schema.ForeignKey) !void {
    if (foreign_key.child_columns.len == 0 or foreign_key.child_columns.len != foreign_key.parent_columns.len) return error.InvalidSqlCatalog;
    if ((foreign_key.child_period == null) != (foreign_key.parent_period == null)) return error.InvalidSqlCatalog;
    if (foreign_key.child_period) |period| {
        if (!foreignKeyActionIsRestrictive(foreign_key.on_update)) return error.InvalidSqlCatalog;
        _ = relationalPeriodForDdl(periods, period) orelse return error.InvalidSqlCatalog;
    }
    for (foreign_key.child_columns) |column| {
        const found = relationalColumnForDdl(columns, column) orelse return error.InvalidSqlCatalog;
        if (found.field_type == .json or found.field_type == .array) return error.InvalidSqlCatalog;
    }
}

fn foreignKeyActionIsRestrictive(action: runtime_schema.ForeignKeyAction) bool {
    return action == .restrict or action == .no_action;
}

fn validateCheckForColumns(columns: []const runtime_schema.RelationalColumn, check: runtime_schema.RelationalCheck) !void {
    if (check.expression) |condition| {
        if (check.field.len != 0 or check.value_json != null) return error.InvalidSqlCatalog;
        return validateCheckExpressionConditionForColumns(columns, condition);
    }
    const column = relationalColumnForDdl(columns, check.field) orelse return error.InvalidSqlCatalog;
    switch (check.op) {
        .is_null, .is_not_null => if (check.value_json != null) return error.InvalidSqlCatalog,
        .eq, .ne, .is_distinct, .is_not_distinct, .gt, .gte, .lt, .lte => {
            const value_json = check.value_json orelse return error.InvalidSqlCatalog;
            const field_type: CheckExpressionType = .{ .type = column.field_type };
            const value_type = try checkExpressionLiteralType(value_json);
            if (!checkExpressionTypesComparable(field_type, value_type)) return error.InvalidSqlCatalog;
            switch (check.op) {
                .gt, .gte, .lt, .lte => if (!checkExpressionTypeOrderable(field_type) or !checkExpressionTypeOrderable(value_type)) return error.InvalidSqlCatalog,
                else => {},
            }
        },
    }
}

fn validateCheckExpressionConditionForColumns(
    columns: []const runtime_schema.RelationalColumn,
    condition: db_mod.types.RelationalRowsExpressionCondition,
) anyerror!void {
    switch (condition.op) {
        .is_null, .is_not_null => if (condition.rhs.len != 0) return error.InvalidSqlCatalog,
        .eq, .ne, .is_distinct, .is_not_distinct, .gt, .gte, .lt, .lte => if (condition.rhs.len != 1) return error.InvalidSqlCatalog,
    }
    const lhs_type = try checkExpressionTypeForColumns(columns, condition.lhs);
    if (condition.rhs.len == 0) return;
    const rhs_type = try checkExpressionTypeForColumns(columns, condition.rhs[0]);
    if (!checkExpressionTypesComparable(lhs_type, rhs_type)) return error.InvalidSqlCatalog;
    switch (condition.op) {
        .gt, .gte, .lt, .lte => if (!checkExpressionTypeOrderable(lhs_type) or !checkExpressionTypeOrderable(rhs_type)) return error.InvalidSqlCatalog,
        else => {},
    }
}

fn validateCheckExpressionForColumns(
    columns: []const runtime_schema.RelationalColumn,
    expression: db_mod.types.RelationalRowsExpression,
) anyerror!void {
    _ = try checkExpressionTypeForColumns(columns, expression);
}

const CheckExpressionType = union(enum) {
    type: runtime_schema.AntflyType,
    null,
};

fn checkExpressionContainsInterval(expression: db_mod.types.RelationalRowsExpression) bool {
    if (expression.kind == .interval_ns or expression.kind == .interval_months) return true;
    for (expression.operands) |operand| {
        if (checkExpressionContainsInterval(operand)) return true;
    }
    for (expression.case_branches) |branch| {
        if (checkExpressionContainsInterval(branch.then)) return true;
        if (checkExpressionContainsInterval(branch.when.lhs)) return true;
        for (branch.when.rhs) |rhs| {
            if (checkExpressionContainsInterval(rhs)) return true;
        }
    }
    for (expression.case_else) |case_else| {
        if (checkExpressionContainsInterval(case_else)) return true;
    }
    return false;
}

fn validateDateBinStrideExpressionForColumns(
    columns: []const runtime_schema.RelationalColumn,
    expression: db_mod.types.RelationalRowsExpression,
) anyerror!void {
    switch (expression.kind) {
        .interval_ns => {
            if (expression.operands.len != 1) return error.InvalidSqlCatalog;
            if (checkExpressionContainsInterval(expression.operands[0])) return error.InvalidSqlCatalog;
            if (!checkExpressionTypeEquals(try checkExpressionTypeForColumns(columns, expression.operands[0]), .numeric)) return error.InvalidSqlCatalog;
        },
        .interval_months => return error.InvalidSqlCatalog,
        else => {
            if (checkExpressionContainsInterval(expression)) return error.InvalidSqlCatalog;
            if (!checkExpressionTypeEquals(try checkExpressionTypeForColumns(columns, expression), .numeric)) return error.InvalidSqlCatalog;
        },
    }
}

fn checkExpressionTypeForColumns(
    columns: []const runtime_schema.RelationalColumn,
    expression: db_mod.types.RelationalRowsExpression,
) anyerror!CheckExpressionType {
    if (expression.kind == .field) {
        if (expression.field_source != .row) return error.InvalidSqlCatalog;
        const column = relationalColumnForDdl(columns, expression.field) orelse return error.InvalidSqlCatalog;
        return .{ .type = column.field_type };
    }
    if (expression.kind == .value) return checkExpressionLiteralType(expression.value_json);

    for (expression.case_branches) |branch| try validateCheckExpressionConditionForColumns(columns, branch.when);

    switch (expression.kind) {
        .field, .value => unreachable,
        .now => return .{ .type = .datetime },
        .uuid_v4 => return .{ .type = .text },
        .regexp_replace, .regexp_substr => {
            if (expression.kind == .regexp_replace and expression.operands.len != 3 and expression.operands.len != 4) return error.InvalidSqlCatalog;
            if (expression.kind == .regexp_substr and expression.operands.len != 2) return error.InvalidSqlCatalog;
            for (expression.operands) |operand| {
                if (!checkExpressionTypeTextLike(try checkExpressionTypeForColumns(columns, operand))) return error.InvalidSqlCatalog;
            }
            return .{ .type = .text };
        },
        .lower, .upper, .initcap, .trim, .ltrim, .rtrim, .replace, .translate, .substring, .overlay, .split_part, .left, .right, .lpad, .rpad, .repeat, .reverse, .chr, .md5, .concat, .concat_ws => {
            for (expression.operands) |operand| {
                if (!checkExpressionTypeTextLike(try checkExpressionTypeForColumns(columns, operand))) return error.InvalidSqlCatalog;
            }
            return .{ .type = .text };
        },
        .length, .octet_length, .ascii, .strpos => {
            for (expression.operands) |operand| {
                if (!checkExpressionTypeTextLike(try checkExpressionTypeForColumns(columns, operand))) return error.InvalidSqlCatalog;
            }
            return .{ .type = .numeric };
        },
        .regexp_count, .regexp_instr => {
            if (expression.operands.len != 2) return error.InvalidSqlCatalog;
            for (expression.operands) |operand| {
                if (!checkExpressionTypeTextLike(try checkExpressionTypeForColumns(columns, operand))) return error.InvalidSqlCatalog;
            }
            return .{ .type = .numeric };
        },
        .starts_with, .ends_with, .like, .ilike => {
            for (expression.operands) |operand| {
                if (!checkExpressionTypeTextLike(try checkExpressionTypeForColumns(columns, operand))) return error.InvalidSqlCatalog;
            }
            return .{ .type = .boolean };
        },
        .regexp_match => {
            if (expression.operands.len != 2 and expression.operands.len != 3) return error.InvalidSqlCatalog;
            for (expression.operands[0..2]) |operand| {
                if (!checkExpressionTypeTextLike(try checkExpressionTypeForColumns(columns, operand))) return error.InvalidSqlCatalog;
            }
            if (expression.operands.len == 3 and !checkExpressionTypeEquals(try checkExpressionTypeForColumns(columns, expression.operands[2]), .boolean)) return error.InvalidSqlCatalog;
            return .{ .type = .boolean };
        },
        .bool_and, .bool_or, .bool_not => {
            for (expression.operands) |operand| {
                if (!checkExpressionTypeEquals(try checkExpressionTypeForColumns(columns, operand), .boolean)) return error.InvalidSqlCatalog;
            }
            return .{ .type = .boolean };
        },
        .abs, .round, .trunc, .floor, .ceil, .sqrt, .sign, .power, .mul, .div, .mod, .interval_ns, .interval_months => {
            for (expression.operands) |operand| {
                if (!checkExpressionTypeEquals(try checkExpressionTypeForColumns(columns, operand), .numeric)) return error.InvalidSqlCatalog;
            }
            return .{ .type = .numeric };
        },
        .add, .sub => {
            var saw_datetime = false;
            for (expression.operands) |operand| {
                const operand_type = try checkExpressionTypeForColumns(columns, operand);
                switch (operand_type) {
                    .type => |field_type| {
                        if (field_type == .datetime) saw_datetime = true else if (field_type != .numeric) return error.InvalidSqlCatalog;
                    },
                    .null => return error.InvalidSqlCatalog,
                }
            }
            return .{ .type = if (saw_datetime) .datetime else .numeric };
        },
        .date_trunc => {
            if (expression.operands.len != 2) return error.InvalidSqlCatalog;
            if (!checkExpressionTypeTextLike(try checkExpressionTypeForColumns(columns, expression.operands[0]))) return error.InvalidSqlCatalog;
            const value_type = try checkExpressionTypeForColumns(columns, expression.operands[1]);
            if (!checkExpressionTypeEquals(value_type, .datetime) and !checkExpressionTypeEquals(value_type, .numeric)) return error.InvalidSqlCatalog;
            return .{ .type = .datetime };
        },
        .date_bin => {
            if (expression.operands.len != 3) return error.InvalidSqlCatalog;
            try validateDateBinStrideExpressionForColumns(columns, expression.operands[0]);
            const source_type = try checkExpressionTypeForColumns(columns, expression.operands[1]);
            if (!checkExpressionTypeEquals(source_type, .datetime) and !checkExpressionTypeEquals(source_type, .numeric)) return error.InvalidSqlCatalog;
            const origin_type = try checkExpressionTypeForColumns(columns, expression.operands[2]);
            if (!checkExpressionTypeEquals(origin_type, .datetime) and !checkExpressionTypeEquals(origin_type, .numeric)) return error.InvalidSqlCatalog;
            return .{ .type = .datetime };
        },
        .date_part => {
            if (expression.operands.len != 2) return error.InvalidSqlCatalog;
            if (!checkExpressionTypeTextLike(try checkExpressionTypeForColumns(columns, expression.operands[0]))) return error.InvalidSqlCatalog;
            const value_type = try checkExpressionTypeForColumns(columns, expression.operands[1]);
            if (!checkExpressionTypeEquals(value_type, .datetime) and !checkExpressionTypeEquals(value_type, .numeric)) return error.InvalidSqlCatalog;
            return .{ .type = .numeric };
        },
        .cast => return .{ .type = switch (expression.cast_type orelse return error.InvalidSqlCatalog) {
            .text => .text,
            .numeric => .numeric,
            .bool => .boolean,
            .datetime => .datetime,
        } },
        .json_extract => {
            if (expression.operands.len != 1) return error.InvalidSqlCatalog;
            if (!checkExpressionTypeEquals(try checkExpressionTypeForColumns(columns, expression.operands[0]), .json)) return error.InvalidSqlCatalog;
            return .{ .type = if (expression.json_as_text) .text else .json };
        },
        .json_path_exists => {
            if (expression.operands.len != 1 or expression.json_path.len == 0) return error.InvalidSqlCatalog;
            if (!checkExpressionTypeEquals(try checkExpressionTypeForColumns(columns, expression.operands[0]), .json)) return error.InvalidSqlCatalog;
            return .{ .type = .boolean };
        },
        .json_typeof => {
            if (expression.operands.len != 1) return error.InvalidSqlCatalog;
            if (!checkExpressionTypeEquals(try checkExpressionTypeForColumns(columns, expression.operands[0]), .json)) return error.InvalidSqlCatalog;
            return .{ .type = .text };
        },
        .json_array_length => {
            if (expression.operands.len != 1) return error.InvalidSqlCatalog;
            if (!checkExpressionTypeEquals(try checkExpressionTypeForColumns(columns, expression.operands[0]), .json)) return error.InvalidSqlCatalog;
            return .{ .type = .numeric };
        },
        .json_build_object => {
            if (expression.operands.len % 2 != 0) return error.InvalidSqlCatalog;
            var index: usize = 0;
            while (index < expression.operands.len) : (index += 2) {
                if (!checkExpressionTypeTextLike(try checkExpressionTypeForColumns(columns, expression.operands[index]))) return error.InvalidSqlCatalog;
                _ = try checkExpressionTypeForColumns(columns, expression.operands[index + 1]);
            }
            return .{ .type = .json };
        },
        .to_jsonb => {
            if (expression.operands.len != 1) return error.InvalidSqlCatalog;
            _ = try checkExpressionTypeForColumns(columns, expression.operands[0]);
            return .{ .type = .json };
        },
        .array_length => {
            if (expression.operands.len != 1) return error.InvalidSqlCatalog;
            if (!checkExpressionTypeEquals(try checkExpressionTypeForColumns(columns, expression.operands[0]), .array)) return error.InvalidSqlCatalog;
            return .{ .type = .numeric };
        },
        .array_position => {
            if (expression.operands.len != 2) return error.InvalidSqlCatalog;
            if (!checkExpressionTypeEquals(try checkExpressionTypeForColumns(columns, expression.operands[0]), .array)) return error.InvalidSqlCatalog;
            _ = try checkExpressionTypeForColumns(columns, expression.operands[1]);
            return .{ .type = .numeric };
        },
        .array_positions => {
            if (expression.operands.len != 2) return error.InvalidSqlCatalog;
            if (!checkExpressionTypeEquals(try checkExpressionTypeForColumns(columns, expression.operands[0]), .array)) return error.InvalidSqlCatalog;
            _ = try checkExpressionTypeForColumns(columns, expression.operands[1]);
            return .{ .type = .array };
        },
        .array_append, .array_prepend, .array_remove => {
            if (expression.operands.len != 2) return error.InvalidSqlCatalog;
            if (!checkExpressionTypeEquals(try checkExpressionTypeForColumns(columns, expression.operands[0]), .array)) return error.InvalidSqlCatalog;
            _ = try checkExpressionTypeForColumns(columns, expression.operands[1]);
            return .{ .type = .array };
        },
        .array_replace => {
            if (expression.operands.len != 3) return error.InvalidSqlCatalog;
            if (!checkExpressionTypeEquals(try checkExpressionTypeForColumns(columns, expression.operands[0]), .array)) return error.InvalidSqlCatalog;
            _ = try checkExpressionTypeForColumns(columns, expression.operands[1]);
            _ = try checkExpressionTypeForColumns(columns, expression.operands[2]);
            return .{ .type = .array };
        },
        .array_cat => {
            if (expression.operands.len != 2) return error.InvalidSqlCatalog;
            if (!checkExpressionTypeEquals(try checkExpressionTypeForColumns(columns, expression.operands[0]), .array)) return error.InvalidSqlCatalog;
            if (!checkExpressionTypeEquals(try checkExpressionTypeForColumns(columns, expression.operands[1]), .array)) return error.InvalidSqlCatalog;
            return .{ .type = .array };
        },
        .array_to_string => {
            if (expression.operands.len != 2 and expression.operands.len != 3) return error.InvalidSqlCatalog;
            if (!checkExpressionTypeEquals(try checkExpressionTypeForColumns(columns, expression.operands[0]), .array)) return error.InvalidSqlCatalog;
            if (!checkExpressionTypeTextLike(try checkExpressionTypeForColumns(columns, expression.operands[1]))) return error.InvalidSqlCatalog;
            if (expression.operands.len == 3 and !checkExpressionTypeTextLike(try checkExpressionTypeForColumns(columns, expression.operands[2]))) return error.InvalidSqlCatalog;
            return .{ .type = .text };
        },
        .string_to_array => {
            for (expression.operands) |operand| {
                if (!checkExpressionTypeTextLike(try checkExpressionTypeForColumns(columns, operand))) return error.InvalidSqlCatalog;
            }
            return .{ .type = .array };
        },
        .coalesce, .nullif, .greatest, .least => return try checkExpressionCommonType(columns, expression.operands),
        .case => {
            if (expression.case_else.len != 1) return error.InvalidSqlCatalog;
            var candidate = try checkExpressionTypeForColumns(columns, expression.case_else[0]);
            for (expression.case_branches) |branch| {
                const branch_type = try checkExpressionTypeForColumns(columns, branch.then);
                if (!checkExpressionTypesComparable(candidate, branch_type)) return error.InvalidSqlCatalog;
                if (candidate == .null) candidate = branch_type;
            }
            return candidate;
        },
    }
}

fn checkExpressionCommonType(
    columns: []const runtime_schema.RelationalColumn,
    expressions: []const db_mod.types.RelationalRowsExpression,
) anyerror!CheckExpressionType {
    if (expressions.len == 0) return error.InvalidSqlCatalog;
    var candidate = try checkExpressionTypeForColumns(columns, expressions[0]);
    for (expressions[1..]) |expression| {
        const expression_type = try checkExpressionTypeForColumns(columns, expression);
        if (!checkExpressionTypesComparable(candidate, expression_type)) return error.InvalidSqlCatalog;
        if (candidate == .null) candidate = expression_type;
    }
    return candidate;
}

fn checkExpressionLiteralType(value_json: []const u8) !CheckExpressionType {
    if (std.mem.eql(u8, value_json, "null")) return .null;
    if (std.mem.eql(u8, value_json, "true") or std.mem.eql(u8, value_json, "false")) return .{ .type = .boolean };
    if (value_json.len == 0) return error.InvalidSqlCatalog;
    return switch (value_json[0]) {
        '"' => .{ .type = .text },
        '[' => .{ .type = .array },
        '{' => .{ .type = .json },
        '-', '0'...'9' => .{ .type = .numeric },
        else => error.InvalidSqlCatalog,
    };
}

fn checkExpressionTypesComparable(lhs: CheckExpressionType, rhs: CheckExpressionType) bool {
    if (lhs == .null or rhs == .null) return true;
    if (checkExpressionTypeTextLike(lhs) and checkExpressionTypeTextLike(rhs)) return true;
    return switch (lhs) {
        .null => true,
        .type => |lhs_type| switch (rhs) {
            .null => true,
            .type => |rhs_type| (lhs_type == .datetime and rhs_type == .numeric) or
                (lhs_type == .numeric and rhs_type == .datetime) or
                lhs_type == rhs_type,
        },
    };
}

fn checkExpressionTypeEquals(value: CheckExpressionType, expected: runtime_schema.AntflyType) bool {
    return switch (value) {
        .null => false,
        .type => |actual| actual == expected,
    };
}

fn checkExpressionTypeTextLike(value: CheckExpressionType) bool {
    return switch (value) {
        .null => false,
        .type => |field_type| switch (field_type) {
            .text, .keyword, .link, .html, .search_as_you_type, .blob, .geoshape => true,
            else => false,
        },
    };
}

fn checkExpressionTypeOrderable(value: CheckExpressionType) bool {
    return checkExpressionTypeTextLike(value) or
        checkExpressionTypeEquals(value, .numeric) or
        checkExpressionTypeEquals(value, .datetime) or
        checkExpressionTypeEquals(value, .boolean);
}

fn validateGeneratedColumnForColumns(columns: []const runtime_schema.RelationalColumn, column: runtime_schema.RelationalColumn) !void {
    const generated = column.generated orelse return;
    switch (generated.op) {
        .lower, .upper, .md5 => {
            const field = generated.field orelse return error.InvalidSqlCatalog;
            if (std.mem.eql(u8, field, column.name)) return error.InvalidSqlCatalog;
            const source = relationalColumnForDdl(columns, field) orelse return error.InvalidSqlCatalog;
            if (source.field_type == .json or source.field_type == .array) return error.InvalidSqlCatalog;
        },
        .concat => {
            if (generated.fields.len == 0) return error.InvalidSqlCatalog;
            for (generated.fields) |field| {
                if (std.mem.eql(u8, field, column.name)) return error.InvalidSqlCatalog;
                const source = relationalColumnForDdl(columns, field) orelse return error.InvalidSqlCatalog;
                if (source.field_type == .json or source.field_type == .array) return error.InvalidSqlCatalog;
            }
        },
        .concat_ws => {
            if (generated.fields.len == 0) return error.InvalidSqlCatalog;
            for (generated.fields) |field| {
                if (std.mem.eql(u8, field, column.name)) return error.InvalidSqlCatalog;
                const source = relationalColumnForDdl(columns, field) orelse return error.InvalidSqlCatalog;
                if (!checkExpressionTypeTextLike(.{ .type = source.field_type })) return error.InvalidSqlCatalog;
            }
        },
    }
}

fn validateCreateIndexIncludeColumns(
    columns: []const runtime_schema.RelationalColumn,
    key_columns: []const []const u8,
    include_columns: []const []const u8,
) !void {
    for (include_columns) |column| {
        if (stringSlicesContains(key_columns, column)) return error.InvalidSqlCatalog;
        _ = relationalColumnForDdl(columns, column) orelse return error.InvalidSqlCatalog;
    }
}

fn validateUniquePredicatesForColumns(columns: []const runtime_schema.RelationalColumn, predicates: []const runtime_schema.UniquePredicate) !void {
    for (predicates) |predicate| {
        const found = relationalColumnForDdl(columns, predicate.field) orelse return error.InvalidSqlCatalog;
        if (found.field_type == .json or found.field_type == .array) return error.InvalidSqlCatalog;
    }
}

fn validateUniquePredicateExpressionsForColumns(
    columns: []const runtime_schema.RelationalColumn,
    conditions: []const db_mod.types.RelationalRowsExpressionCondition,
) !void {
    for (conditions) |condition| {
        try validateCheckExpressionConditionForColumns(columns, condition);
        if (!rowExpressionDeterministic(condition.lhs)) return error.InvalidSqlCatalog;
        for (condition.rhs) |rhs| {
            if (!rowExpressionDeterministic(rhs)) return error.InvalidSqlCatalog;
        }
    }
}

fn rowExpressionDeterministic(expression: db_mod.types.RelationalRowsExpression) bool {
    if (expression.field_source != .row) return false;
    if (expression.kind == .now or expression.kind == .uuid_v4) return false;
    for (expression.operands) |operand| {
        if (!rowExpressionDeterministic(operand)) return false;
    }
    for (expression.case_branches) |branch| {
        if (!rowExpressionConditionDeterministic(branch.when)) return false;
        if (!rowExpressionDeterministic(branch.then)) return false;
    }
    for (expression.case_else) |case_else| {
        if (!rowExpressionDeterministic(case_else)) return false;
    }
    return true;
}

fn rowExpressionConditionDeterministic(condition: db_mod.types.RelationalRowsExpressionCondition) bool {
    if (!rowExpressionDeterministic(condition.lhs)) return false;
    for (condition.rhs) |rhs| {
        if (!rowExpressionDeterministic(rhs)) return false;
    }
    return true;
}

fn relationalColumnForDdl(columns: []const runtime_schema.RelationalColumn, name: []const u8) ?runtime_schema.RelationalColumn {
    for (columns) |column| {
        if (std.mem.eql(u8, column.name, name)) return column;
    }
    return null;
}

fn relationalColumnIndex(columns: []const runtime_schema.RelationalColumn, name: []const u8) ?usize {
    for (columns, 0..) |column, i| {
        if (std.mem.eql(u8, column.name, name)) return i;
    }
    return null;
}

fn relationalColumnIndexForIndexName(columns: []const runtime_schema.RelationalColumn, index_name: []const u8) ?usize {
    for (columns, 0..) |column, i| {
        if (relationalColumnHasIndexName(column, index_name)) return i;
    }
    return null;
}

fn relationalColumnHasDeclaredIndexName(column: runtime_schema.RelationalColumn, index_name: []const u8) bool {
    const declared_index_name = column.index_name orelse return false;
    return std.mem.eql(u8, declared_index_name, index_name);
}

fn relationalColumnHasIndexName(column: runtime_schema.RelationalColumn, index_name: []const u8) bool {
    const declared_index_name = column.index_name orelse column.name;
    return std.mem.eql(u8, declared_index_name, index_name);
}

fn uniqueConstraintNameExists(constraints: []const runtime_schema.UniqueConstraint, name: []const u8) bool {
    for (constraints) |constraint| {
        if (std.mem.eql(u8, constraint.name, name)) return true;
    }
    return false;
}

fn foreignKeyNameExists(foreign_keys: []const runtime_schema.ForeignKey, name: []const u8) bool {
    for (foreign_keys) |foreign_key| {
        if (std.mem.eql(u8, foreign_key.name, name)) return true;
    }
    return false;
}

fn relationalCheckNameExists(checks: []const runtime_schema.RelationalCheck, name: []const u8) bool {
    for (checks) |check| {
        if (std.mem.eql(u8, check.name, name)) return true;
    }
    return false;
}

fn conflictActionToken(action: Parser.ConflictAction) []const u8 {
    return switch (action) {
        .nothing => "nothing",
        .update => "update",
    };
}

fn uniquePredicateOpToken(op: runtime_schema.UniquePredicateOp) []const u8 {
    return switch (op) {
        .is_null => "is_null",
        .is_not_null => "is_not_null",
        .eq => "eq",
        .ne => "ne",
    };
}

fn uniquePredicateAsRelationalCheckOp(op: runtime_schema.UniquePredicateOp) runtime_schema.RelationalCheckOp {
    return switch (op) {
        .is_null => .is_null,
        .is_not_null => .is_not_null,
        .eq => .eq,
        .ne => .ne,
    };
}

fn arrayTransformOpToken(op: db_mod.types.TransformOpType) []const u8 {
    return switch (op) {
        .push => "append",
        .pull => "remove",
        .add_to_set => "add_to_set",
        else => unreachable,
    };
}

fn validateUniqueWhereJsonMatches(alloc: std.mem.Allocator, where_json: []const u8, predicates: []const runtime_schema.UniquePredicate) !void {
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, where_json, .{}) catch return error.UnsupportedSqlShape;
    defer parsed.deinit();
    if (parsed.value != .object) return error.UnsupportedSqlShape;
    const all_value = parsed.value.object.get("all") orelse return error.UnsupportedSqlShape;
    if (all_value != .array or all_value.array.items.len != predicates.len) return error.UnsupportedSqlShape;
    for (all_value.array.items, predicates) |item, predicate| {
        if (item != .object) return error.UnsupportedSqlShape;
        const field_value = item.object.get("field") orelse return error.UnsupportedSqlShape;
        const op_value = item.object.get("op") orelse return error.UnsupportedSqlShape;
        if (field_value != .string or !std.mem.eql(u8, field_value.string, predicate.field)) return error.UnsupportedSqlShape;
        if (op_value != .string or !std.mem.eql(u8, op_value.string, uniquePredicateOpToken(predicate.op))) return error.UnsupportedSqlShape;
        const supplied_value = item.object.get("value");
        if (predicate.value_json) |expected_json| {
            const supplied = supplied_value orelse return error.UnsupportedSqlShape;
            const supplied_json = try std.json.Stringify.valueAlloc(alloc, supplied, .{});
            defer alloc.free(supplied_json);
            if (!std.mem.eql(u8, supplied_json, expected_json)) return error.UnsupportedSqlShape;
        } else if (supplied_value != null) {
            return error.UnsupportedSqlShape;
        }
    }
}

fn updateWillLookupExistingRow(schema: runtime_schema.TableSchema, returning: ReturningProjection) bool {
    if (returning.hasProjection() or schema.checks.len > 0) return true;
    for (schema.relational_columns) |column| {
        if (column.generated != null) return true;
    }
    return false;
}

fn validateJsonDocument(alloc: std.mem.Allocator, value: []const u8) !void {
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, value, .{}) catch return error.UnsupportedSqlShape;
    defer parsed.deinit();
    switch (parsed.value) {
        .object, .array => {},
        else => return error.UnsupportedSqlShape,
    }
}

fn validateJsonArray(alloc: std.mem.Allocator, value: []const u8) !void {
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, value, .{}) catch return error.UnsupportedSqlShape;
    defer parsed.deinit();
    if (parsed.value != .array) return error.UnsupportedSqlShape;
}

fn validateJsonStringArray(alloc: std.mem.Allocator, value: []const u8) !void {
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, value, .{}) catch return error.UnsupportedSqlShape;
    defer parsed.deinit();
    if (parsed.value != .array) return error.UnsupportedSqlShape;
    for (parsed.value.array.items) |item| {
        if (item != .string) return error.UnsupportedSqlShape;
    }
}

fn jsonSetTypedTransformPathAlloc(
    alloc: std.mem.Allocator,
    field: []const u8,
    path_segments: []const []const u8,
) ![]u8 {
    if (field.len == 0 or path_segments.len == 0) return error.UnsupportedSqlShape;
    var out: std.Io.Writer.Allocating = .init(alloc);
    errdefer out.deinit();
    const writer = &out.writer;
    try writer.writeAll(field);
    for (path_segments) |segment| {
        if (segment.len == 0 or std.mem.indexOfScalar(u8, segment, '.') != null) return error.UnsupportedSqlShape;
        try writer.writeByte('.');
        try writer.writeAll(segment);
    }
    return try out.toOwnedSlice();
}

fn jsonValueIsValid(alloc: std.mem.Allocator, value: []const u8) bool {
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, value, .{}) catch return false;
    parsed.deinit();
    return true;
}

