fn freeCoalesceOperand(alloc: std.mem.Allocator, value: db_mod.types.RelationalRowsCoalesceOperand) void {
    switch (value.kind) {
        .field => if (value.field.len > 0) alloc.free(value.field),
        .value => if (value.value_json.len > 0) alloc.free(value.value_json),
    }
}

fn freeCoalesceProjection(alloc: std.mem.Allocator, value: db_mod.types.RelationalRowsCoalesceProjection) void {
    alloc.free(value.output);
    for (value.operands) |operand| freeCoalesceOperand(alloc, operand);
    if (value.operands.len > 0) alloc.free(value.operands);
}

fn freeCoalesceProjections(alloc: std.mem.Allocator, values: []const db_mod.types.RelationalRowsCoalesceProjection) void {
    for (values) |value| freeCoalesceProjection(alloc, value);
    if (values.len > 0) alloc.free(values);
}

fn expressionProjectionFromCoalesceAlloc(
    alloc: std.mem.Allocator,
    projection: db_mod.types.RelationalRowsCoalesceProjection,
) !db_mod.types.RelationalRowsExpressionProjection {
    const output = try alloc.dupe(u8, projection.output);
    var output_transferred = false;
    errdefer if (!output_transferred) alloc.free(output);

    const operands = try alloc.alloc(db_mod.types.RelationalRowsExpression, projection.operands.len);
    var initialized: usize = 0;
    errdefer {
        for (operands[0..initialized]) |operand| freeExpression(alloc, operand);
        alloc.free(operands);
    }
    for (projection.operands) |operand| {
        operands[initialized] = switch (operand.kind) {
            .field => .{
                .kind = .field,
                .field = try alloc.dupe(u8, operand.field),
            },
            .value => .{
                .kind = .value,
                .value_json = try alloc.dupe(u8, operand.value_json),
            },
        };
        initialized += 1;
    }

    output_transferred = true;
    return .{
        .output = output,
        .expression = .{
            .kind = .coalesce,
            .operands = operands,
        },
    };
}

fn freeExpression(alloc: std.mem.Allocator, value: db_mod.types.RelationalRowsExpression) void {
    if (value.field.len > 0) alloc.free(value.field);
    if (value.value_json.len > 0) alloc.free(value.value_json);
    if (value.json_path.len > 0) alloc.free(value.json_path);
    for (value.operands) |operand| freeExpression(alloc, operand);
    if (value.operands.len > 0) alloc.free(value.operands);
    for (value.case_branches) |branch| freeExpressionCaseBranch(alloc, branch);
    if (value.case_branches.len > 0) alloc.free(value.case_branches);
    for (value.case_else) |fallback| freeExpression(alloc, fallback);
    if (value.case_else.len > 0) alloc.free(value.case_else);
}

fn freeExpressionSlice(alloc: std.mem.Allocator, values: []const db_mod.types.RelationalRowsExpression) void {
    for (values) |value| freeExpression(alloc, value);
    if (values.len > 0) alloc.free(values);
}

fn cloneExpressionAlloc(
    alloc: std.mem.Allocator,
    value: db_mod.types.RelationalRowsExpression,
) anyerror!db_mod.types.RelationalRowsExpression {
    var cloned: db_mod.types.RelationalRowsExpression = .{
        .kind = value.kind,
        .field_source = value.field_source,
        .cast_type = value.cast_type,
        .json_as_text = value.json_as_text,
    };
    errdefer freeExpression(alloc, cloned);

    if (value.field.len > 0) cloned.field = try alloc.dupe(u8, value.field);
    if (value.value_json.len > 0) cloned.value_json = try alloc.dupe(u8, value.value_json);
    if (value.json_path.len > 0) cloned.json_path = try alloc.dupe(u8, value.json_path);

    if (value.operands.len > 0) {
        const operands = try alloc.alloc(db_mod.types.RelationalRowsExpression, value.operands.len);
        var initialized: usize = 0;
        errdefer {
            for (operands[0..initialized]) |operand| freeExpression(alloc, operand);
            alloc.free(operands);
        }
        for (value.operands, 0..) |operand, i| {
            operands[i] = try cloneExpressionAlloc(alloc, operand);
            initialized += 1;
        }
        cloned.operands = operands;
    }

    if (value.case_branches.len > 0) {
        const branches = try alloc.alloc(db_mod.types.RelationalRowsExpressionCaseBranch, value.case_branches.len);
        var initialized: usize = 0;
        errdefer {
            for (branches[0..initialized]) |branch| freeExpressionCaseBranch(alloc, branch);
            alloc.free(branches);
        }
        for (value.case_branches, 0..) |branch, i| {
            branches[i] = try cloneExpressionCaseBranchAlloc(alloc, branch);
            initialized += 1;
        }
        cloned.case_branches = branches;
    }

    if (value.case_else.len > 0) {
        const fallback = try alloc.alloc(db_mod.types.RelationalRowsExpression, value.case_else.len);
        var initialized: usize = 0;
        errdefer {
            for (fallback[0..initialized]) |expression| freeExpression(alloc, expression);
            alloc.free(fallback);
        }
        for (value.case_else, 0..) |expression, i| {
            fallback[i] = try cloneExpressionAlloc(alloc, expression);
            initialized += 1;
        }
        cloned.case_else = fallback;
    }

    return cloned;
}

fn cloneOrderByAlloc(
    alloc: std.mem.Allocator,
    values: []const db_mod.types.RelationalRowsQueryOrder,
) ![]const db_mod.types.RelationalRowsQueryOrder {
    if (values.len == 0) return &.{};
    const out = try alloc.alloc(db_mod.types.RelationalRowsQueryOrder, values.len);
    var initialized: usize = 0;
    errdefer {
        freeOrderBy(alloc, out[0..initialized]);
        alloc.free(out);
    }
    for (values, 0..) |value, i| {
        out[i] = .{
            .direction = value.direction,
            .null_test = value.null_test,
        };
        if (value.field.len > 0) out[i].field = try alloc.dupe(u8, value.field);
        if (value.expression) |expression| out[i].expression = try cloneExpressionAlloc(alloc, expression);
        initialized += 1;
    }
    return out;
}

fn cloneNamedWindowDefinitionAlloc(
    alloc: std.mem.Allocator,
    value: Parser.NamedWindowSpec,
) !Parser.NamedWindowDefinition {
    const partition_by = try cloneStringSlice(alloc, value.partition_by);
    var partition_transferred = false;
    errdefer if (!partition_transferred) freeStringSlice(alloc, partition_by);
    const order_by = try cloneOrderByAlloc(alloc, value.order_by);
    var order_transferred = false;
    errdefer if (!order_transferred) {
        freeOrderBy(alloc, order_by);
        if (order_by.len > 0) alloc.free(order_by);
    };

    partition_transferred = true;
    order_transferred = true;
    return .{
        .partition_by = partition_by,
        .order_by = order_by,
        .frame = value.frame,
    };
}

fn rewriteExpressionFieldsToSource(value: *db_mod.types.RelationalRowsExpression) void {
    if (value.kind == .field) value.field_source = .source;
    for (@constCast(value.operands)) |*operand| rewriteExpressionFieldsToSource(operand);
    for (@constCast(value.case_branches)) |*branch| {
        rewriteExpressionConditionFieldsToSource(&branch.when);
        rewriteExpressionFieldsToSource(&branch.then);
    }
    for (@constCast(value.case_else)) |*fallback| rewriteExpressionFieldsToSource(fallback);
}

fn rewriteExpressionConditionFieldsToSource(value: *db_mod.types.RelationalRowsExpressionCondition) void {
    rewriteExpressionFieldsToSource(&value.lhs);
    for (@constCast(value.rhs)) |*rhs| rewriteExpressionFieldsToSource(rhs);
}

fn cloneSelectOutputsAlloc(
    alloc: std.mem.Allocator,
    values: []const SelectOutputRef,
) ![]const SelectOutputRef {
    if (values.len == 0) return &.{};
    return try alloc.dupe(SelectOutputRef, values);
}

fn cloneExpressionProjection(
    alloc: std.mem.Allocator,
    value: db_mod.types.RelationalRowsExpressionProjection,
) !db_mod.types.RelationalRowsExpressionProjection {
    const output = try alloc.dupe(u8, value.output);
    var output_transferred = false;
    errdefer if (!output_transferred) alloc.free(output);
    const expression = try cloneExpressionAlloc(alloc, value.expression);
    output_transferred = true;
    return .{
        .output = output,
        .expression = expression,
    };
}

fn cloneExpressionCaseBranchAlloc(
    alloc: std.mem.Allocator,
    value: db_mod.types.RelationalRowsExpressionCaseBranch,
) anyerror!db_mod.types.RelationalRowsExpressionCaseBranch {
    const when = try cloneExpressionConditionAlloc(alloc, value.when);
    var when_transferred = false;
    errdefer if (!when_transferred) freeExpressionCondition(alloc, when);
    const then_expression = try cloneExpressionAlloc(alloc, value.then);
    when_transferred = true;
    return .{
        .when = when,
        .then = then_expression,
    };
}

fn cloneExpressionConditionAlloc(
    alloc: std.mem.Allocator,
    value: db_mod.types.RelationalRowsExpressionCondition,
) anyerror!db_mod.types.RelationalRowsExpressionCondition {
    const lhs = try cloneExpressionAlloc(alloc, value.lhs);
    var lhs_transferred = false;
    errdefer if (!lhs_transferred) freeExpression(alloc, lhs);

    const rhs = if (value.rhs.len > 0) blk: {
        const out = try alloc.alloc(db_mod.types.RelationalRowsExpression, value.rhs.len);
        var initialized: usize = 0;
        errdefer {
            for (out[0..initialized]) |expression| freeExpression(alloc, expression);
            alloc.free(out);
        }
        for (value.rhs, 0..) |expression, i| {
            out[i] = try cloneExpressionAlloc(alloc, expression);
            initialized += 1;
        }
        break :blk out;
    } else &.{};

    lhs_transferred = true;
    return .{
        .lhs = lhs,
        .op = value.op,
        .rhs = rhs,
    };
}

fn cloneExpressionConditionsAlloc(
    alloc: std.mem.Allocator,
    values: []const db_mod.types.RelationalRowsExpressionCondition,
) anyerror![]db_mod.types.RelationalRowsExpressionCondition {
    if (values.len == 0) return &.{};
    const out = try alloc.alloc(db_mod.types.RelationalRowsExpressionCondition, values.len);
    var initialized: usize = 0;
    errdefer {
        for (out[0..initialized]) |condition| freeExpressionCondition(alloc, condition);
        alloc.free(out);
    }
    for (values) |condition| {
        out[initialized] = try cloneExpressionConditionAlloc(alloc, condition);
        initialized += 1;
    }
    return out;
}

fn cloneExpressionPredicateGroupsAlloc(
    alloc: std.mem.Allocator,
    values: []const db_mod.types.RelationalRowsExpressionPredicateGroup,
) anyerror![]db_mod.types.RelationalRowsExpressionPredicateGroup {
    if (values.len == 0) return &.{};
    const out = try alloc.alloc(db_mod.types.RelationalRowsExpressionPredicateGroup, values.len);
    var initialized: usize = 0;
    errdefer {
        for (out[0..initialized]) |group| freeExpressionPredicateGroup(alloc, group);
        alloc.free(out);
    }
    for (values) |group| {
        out[initialized] = .{ .conditions = try cloneExpressionConditionsAlloc(alloc, group.conditions) };
        initialized += 1;
    }
    return out;
}

fn cloneExpressionConditionsConcatAlloc(
    alloc: std.mem.Allocator,
    lhs: []const db_mod.types.RelationalRowsExpressionCondition,
    rhs: []const db_mod.types.RelationalRowsExpressionCondition,
) anyerror![]db_mod.types.RelationalRowsExpressionCondition {
    const out = try alloc.alloc(db_mod.types.RelationalRowsExpressionCondition, lhs.len + rhs.len);
    var initialized: usize = 0;
    errdefer {
        for (out[0..initialized]) |condition| freeExpressionCondition(alloc, condition);
        alloc.free(out);
    }
    for (lhs) |condition| {
        out[initialized] = try cloneExpressionConditionAlloc(alloc, condition);
        initialized += 1;
    }
    for (rhs) |condition| {
        out[initialized] = try cloneExpressionConditionAlloc(alloc, condition);
        initialized += 1;
    }
    return out;
}

fn freeExpressionCaseBranch(alloc: std.mem.Allocator, value: db_mod.types.RelationalRowsExpressionCaseBranch) void {
    freeExpressionCondition(alloc, value.when);
    freeExpression(alloc, value.then);
}

fn freeExpressionCondition(alloc: std.mem.Allocator, value: db_mod.types.RelationalRowsExpressionCondition) void {
    freeExpression(alloc, value.lhs);
    for (value.rhs) |rhs| freeExpression(alloc, rhs);
    if (value.rhs.len > 0) alloc.free(value.rhs);
}

fn freeExpressionConditions(alloc: std.mem.Allocator, values: []const db_mod.types.RelationalRowsExpressionCondition) void {
    for (values) |value| freeExpressionCondition(alloc, value);
}

fn freeExpressionPredicateGroup(alloc: std.mem.Allocator, value: db_mod.types.RelationalRowsExpressionPredicateGroup) void {
    freeExpressionConditions(alloc, value.conditions);
    if (value.conditions.len > 0) alloc.free(value.conditions);
}

fn freeExpressionPredicateGroups(alloc: std.mem.Allocator, values: []const db_mod.types.RelationalRowsExpressionPredicateGroup) void {
    for (values) |group| {
        freeExpressionPredicateGroup(alloc, group);
    }
}

fn freeExpressionProjection(alloc: std.mem.Allocator, value: db_mod.types.RelationalRowsExpressionProjection) void {
    alloc.free(value.output);
    freeExpression(alloc, value.expression);
}

fn freeExpressionProjections(alloc: std.mem.Allocator, values: []const db_mod.types.RelationalRowsExpressionProjection) void {
    for (values) |value| freeExpressionProjection(alloc, value);
    if (values.len > 0) alloc.free(values);
}

fn freeFieldAliasProjections(alloc: std.mem.Allocator, values: []const db_mod.types.RelationalRowsFieldAliasProjection) void {
    for (values) |value| {
        alloc.free(value.output);
        alloc.free(value.field);
    }
    if (values.len > 0) alloc.free(values);
}

fn freeWindowSpec(alloc: std.mem.Allocator, value: db_mod.types.RelationalRowsWindowSpec) void {
    alloc.free(value.output);
    freeStringSlice(alloc, value.partition_by);
    freeOrderBy(alloc, value.order_by);
    if (value.order_by.len > 0) alloc.free(value.order_by);
    if (value.value_expression) |expression| freeExpression(alloc, expression);
    if (value.default_json.len > 0) alloc.free(value.default_json);
    freeRelationalChecks(alloc, value.filter_predicates);
    if (value.filter_predicates.len > 0) alloc.free(value.filter_predicates);
    freeArrayAny(alloc, value.filter_array_any);
    if (value.filter_array_any.len > 0) alloc.free(value.filter_array_any);
    freeArrayContains(alloc, value.filter_array_contains);
    if (value.filter_array_contains.len > 0) alloc.free(value.filter_array_contains);
    freeArrayEq(alloc, value.filter_array_eq);
    if (value.filter_array_eq.len > 0) alloc.free(value.filter_array_eq);
    freeInPredicates(alloc, value.filter_in_predicates);
    if (value.filter_in_predicates.len > 0) alloc.free(value.filter_in_predicates);
    freeJsonContains(alloc, value.filter_json_contains);
    if (value.filter_json_contains.len > 0) alloc.free(value.filter_json_contains);
    freeJsonPathEq(alloc, value.filter_json_path_eq);
    if (value.filter_json_path_eq.len > 0) alloc.free(value.filter_json_path_eq);
    freeJsonPathExists(alloc, value.filter_json_path_exists);
    if (value.filter_json_path_exists.len > 0) alloc.free(value.filter_json_path_exists);
    freeTextPatterns(alloc, value.filter_text_patterns);
    if (value.filter_text_patterns.len > 0) alloc.free(value.filter_text_patterns);
    freeExpressionConditions(alloc, value.filter_expressions);
    if (value.filter_expressions.len > 0) alloc.free(value.filter_expressions);
    freeExpressionArrayContains(alloc, value.filter_expression_array_contains);
    if (value.filter_expression_array_contains.len > 0) alloc.free(value.filter_expression_array_contains);
    freeExpressionPredicateGroups(alloc, value.filter_any);
    if (value.filter_any.len > 0) alloc.free(value.filter_any);
    freeExpressionPredicateGroups(alloc, value.filter_not);
    if (value.filter_not.len > 0) alloc.free(value.filter_not);
}

fn freeWindowSpecs(alloc: std.mem.Allocator, values: []const db_mod.types.RelationalRowsWindowSpec) void {
    for (values) |value| freeWindowSpec(alloc, value);
}

fn freeNamedWindowDefinition(alloc: std.mem.Allocator, value: Parser.NamedWindowDefinition) void {
    freeStringSlice(alloc, value.partition_by);
    freeOrderBy(alloc, value.order_by);
    if (value.order_by.len > 0) alloc.free(value.order_by);
}

fn freeNamedWindowSpec(alloc: std.mem.Allocator, value: Parser.NamedWindowSpec) void {
    alloc.free(value.name);
    freeStringSlice(alloc, value.partition_by);
    freeOrderBy(alloc, value.order_by);
    if (value.order_by.len > 0) alloc.free(value.order_by);
}

fn freeNamedWindowSpecs(alloc: std.mem.Allocator, values: []const Parser.NamedWindowSpec) void {
    for (values) |value| freeNamedWindowSpec(alloc, value);
    if (values.len > 0) alloc.free(values);
}

fn freeOrderBy(alloc: std.mem.Allocator, values: []const db_mod.types.RelationalRowsQueryOrder) void {
    for (values) |value| {
        if (value.field.len > 0) alloc.free(value.field);
        if (value.expression) |expression| freeExpression(alloc, expression);
    }
}

test "postgres sql adapter lowers create table ddl into typed schema plan" {
    const alloc = std.testing.allocator;
    var lowered = try lowerDdlPlanAlloc(
        alloc,
        \\CREATE TABLE IF NOT EXISTS usage_records (
        \\  id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
        \\  tenant_id text NOT NULL,
        \\  amount numeric(18, 2) DEFAULT 0 CHECK (amount >= 0),
        \\  metadata jsonb,
        \\  tags text[],
        \\  created_at timestamptz DEFAULT now(),
        \\  email_key text GENERATED ALWAYS AS (lower(tenant_id)) STORED,
        \\  CONSTRAINT usage_records_tenant_key UNIQUE (tenant_id),
        \\  CONSTRAINT usage_records_tenant_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE
        \\);
        ,
    );
    defer lowered.deinit(alloc);

    switch (lowered) {
        .create_table => |plan| {
            try std.testing.expectEqualStrings("usage_records", plan.table_name);
            try std.testing.expect(plan.if_not_exists);
            try std.testing.expectEqual(@as(usize, 7), plan.columns.len);
            try std.testing.expectEqualStrings("id", plan.columns[0].name);
            try std.testing.expectEqual(runtime_schema.AntflyType.keyword, plan.columns[0].field_type);
            try std.testing.expect(!plan.columns[0].nullable);
            try std.testing.expect(plan.columns[0].default_value != null);
            try std.testing.expectEqual(runtime_schema.RelationalDefaultKind.uuid_v4, plan.columns[0].default_value.?.kind);
            try std.testing.expectEqualStrings("amount", plan.columns[2].name);
            try std.testing.expectEqual(runtime_schema.AntflyType.numeric, plan.columns[2].field_type);
            try std.testing.expect(plan.columns[2].default_value != null);
            try std.testing.expectEqual(runtime_schema.RelationalDefaultKind.literal, plan.columns[2].default_value.?.kind);
            try std.testing.expectEqualStrings("0", plan.columns[2].default_value.?.value_json);
            try std.testing.expectEqual(runtime_schema.AntflyType.json, plan.columns[3].field_type);
            try std.testing.expectEqual(runtime_schema.AntflyType.array, plan.columns[4].field_type);
            try std.testing.expectEqual(runtime_schema.AntflyType.keyword, plan.columns[4].array_item_type.?);
            try std.testing.expectEqual(runtime_schema.AntflyType.datetime, plan.columns[5].field_type);
            try std.testing.expect(plan.columns[5].default_value != null);
            try std.testing.expectEqual(runtime_schema.RelationalDefaultKind.now_ns, plan.columns[5].default_value.?.kind);
            try std.testing.expectEqualStrings("email_key", plan.columns[6].name);
            try std.testing.expect(plan.columns[6].generated != null);
            try std.testing.expectEqual(runtime_schema.RelationalGeneratedOp.lower, plan.columns[6].generated.?.op);
            try std.testing.expectEqualStrings("tenant_id", plan.columns[6].generated.?.field.?);
            try std.testing.expect(plan.primary_key != null);
            try std.testing.expectEqual(@as(usize, 1), plan.primary_key.?.columns.len);
            try std.testing.expectEqualStrings("id", plan.primary_key.?.columns[0]);
            try std.testing.expectEqual(@as(usize, 1), plan.unique_constraints.len);
            try std.testing.expectEqualStrings("usage_records_tenant_key", plan.unique_constraints[0].name);
            try std.testing.expectEqualStrings("tenant_id", plan.unique_constraints[0].columns[0]);
            try std.testing.expectEqual(@as(usize, 1), plan.foreign_keys.len);
            try std.testing.expectEqualStrings("usage_records_tenant_fkey", plan.foreign_keys[0].name);
            try std.testing.expectEqualStrings("tenant_id", plan.foreign_keys[0].child_columns[0]);
            try std.testing.expectEqualStrings("tenants", plan.foreign_keys[0].parent_table);
            try std.testing.expectEqual(runtime_schema.ForeignKeyAction.cascade, plan.foreign_keys[0].on_delete);
            try std.testing.expectEqual(@as(usize, 1), plan.checks.len);
            try std.testing.expectEqualStrings("amount", plan.checks[0].field);
            try std.testing.expectEqual(runtime_schema.RelationalCheckOp.gte, plan.checks[0].op);
            try std.testing.expectEqualStrings("0", plan.checks[0].value_json.?);
        },
        .create_index => return error.TestUnexpectedResult,
        .drop_index => return error.TestUnexpectedResult,
        .drop_table => return error.TestUnexpectedResult,
        .alter_table => return error.TestUnexpectedResult,
        .create_update_policy => return error.TestUnexpectedResult,
        else => return error.TestUnexpectedResult,
    }

    var casted_defaults = try lowerDdlPlanAlloc(
        alloc,
        \\CREATE TABLE casted_defaults (
        \\  id uuid PRIMARY KEY,
        \\  amount numeric DEFAULT '0'::numeric,
        \\  enabled boolean DEFAULT 'true'::boolean
        \\);
        ,
    );
    defer casted_defaults.deinit(alloc);
    switch (casted_defaults) {
        .create_table => |plan| {
            try std.testing.expectEqualStrings("casted_defaults", plan.table_name);
            try std.testing.expectEqual(@as(usize, 3), plan.columns.len);
            try std.testing.expectEqual(runtime_schema.AntflyType.numeric, plan.columns[1].field_type);
            try std.testing.expect(plan.columns[1].default_value != null);
            try std.testing.expectEqual(runtime_schema.RelationalDefaultKind.literal, plan.columns[1].default_value.?.kind);
            try std.testing.expectEqualStrings("0", plan.columns[1].default_value.?.value_json);
            try std.testing.expectEqual(runtime_schema.AntflyType.boolean, plan.columns[2].field_type);
            try std.testing.expect(plan.columns[2].default_value != null);
            try std.testing.expectEqual(runtime_schema.RelationalDefaultKind.literal, plan.columns[2].default_value.?.kind);
            try std.testing.expectEqualStrings("true", plan.columns[2].default_value.?.value_json);
            const applied = try applyDdlPlanToRuntimeSchemaAlloc(alloc, .{}, casted_defaults);
            defer runtime_schema.freeSchema(alloc, applied);
            try std.testing.expectEqual(@as(usize, 3), applied.relational_columns.len);
        },
        .create_index => return error.TestUnexpectedResult,
        .drop_index => return error.TestUnexpectedResult,
        .drop_table => return error.TestUnexpectedResult,
        .alter_table => return error.TestUnexpectedResult,
        .create_update_policy => return error.TestUnexpectedResult,
        else => return error.TestUnexpectedResult,
    }

    var no_primary_key = try lowerDdlPlanAlloc(
        alloc,
        "CREATE TABLE usage_stage (tenant_id text NOT NULL, id uuid NOT NULL, status text);",
    );
    defer no_primary_key.deinit(alloc);
    switch (no_primary_key) {
        .create_table => |plan| {
            try std.testing.expectEqualStrings("usage_stage", plan.table_name);
            try std.testing.expect(plan.primary_key == null);
            try std.testing.expectEqual(@as(usize, 3), plan.columns.len);
            const applied = try applyDdlPlanToRuntimeSchemaAlloc(alloc, .{}, no_primary_key);
            defer runtime_schema.freeSchema(alloc, applied);
            try std.testing.expectEqual(runtime_schema.StorageMode.relational, applied.storage_mode);
            try std.testing.expect(applied.primary_key == null);
            try std.testing.expectEqual(@as(usize, 3), applied.relational_columns.len);
            try std.testing.expectError(error.InvalidSqlCatalog, lowerInsertAlloc(
                alloc,
                "INSERT INTO usage_stage (tenant_id, id, status) VALUES ('t1', 'u1', 'open')",
                applied,
                &.{},
            ));
        },
        else => return error.TestUnexpectedResult,
    }

    try std.testing.expectError(error.UnsupportedSqlShape, lowerDdlPlanAlloc(
        alloc,
        "CREATE TABLE ONLY usage_records (id uuid PRIMARY KEY);",
    ));
    try std.testing.expectError(error.UnsupportedSqlShape, lowerDdlPlanAlloc(
        alloc,
        "CREATE TABLE duplicate_pk (tenant_id text, id text, PRIMARY KEY (tenant_id, tenant_id));",
    ));
    try std.testing.expectError(error.UnsupportedSqlShape, lowerDdlPlanAlloc(
        alloc,
        "CREATE TABLE duplicate_unique (id text PRIMARY KEY, tenant_id text, CONSTRAINT duplicate_unique_tenant_key UNIQUE (tenant_id, tenant_id));",
    ));
    try std.testing.expectError(error.UnsupportedSqlShape, lowerDdlPlanAlloc(
        alloc,
        "CREATE TABLE duplicate_fk (id text PRIMARY KEY, tenant_id text, FOREIGN KEY (tenant_id, tenant_id) REFERENCES tenants (id, id));",
    ));
}

test "postgres sql adapter preserves named inline create table constraints" {
    const alloc = std.testing.allocator;
    var lowered = try lowerDdlPlanAlloc(
        alloc,
        \\CREATE TABLE inline_named_constraints (
        \\  id uuid CONSTRAINT inline_named_constraints_pkey PRIMARY KEY,
        \\  tenant_id text CONSTRAINT inline_named_constraints_tenant_fkey REFERENCES tenants (id) ON DELETE CASCADE,
        \\  email text CONSTRAINT inline_named_constraints_email_key UNIQUE,
        \\  status text CONSTRAINT inline_named_constraints_status_check CHECK (lower(status) != 'deleted')
        \\);
        ,
    );
    defer lowered.deinit(alloc);

    switch (lowered) {
        .create_table => |plan| {
            try std.testing.expectEqualStrings("inline_named_constraints", plan.table_name);
            try std.testing.expectEqual(@as(usize, 4), plan.columns.len);
            try std.testing.expect(plan.primary_key != null);
            try std.testing.expectEqualStrings("inline_named_constraints_pkey", plan.primary_key.?.name.?);
            try std.testing.expectEqualStrings("id", plan.primary_key.?.columns[0]);
            try std.testing.expectEqual(@as(usize, 1), plan.unique_constraints.len);
            try std.testing.expectEqualStrings("inline_named_constraints_email_key", plan.unique_constraints[0].name);
            try std.testing.expectEqualStrings("email", plan.unique_constraints[0].columns[0]);
            try std.testing.expectEqual(@as(usize, 1), plan.foreign_keys.len);
            try std.testing.expectEqualStrings("inline_named_constraints_tenant_fkey", plan.foreign_keys[0].name);
            try std.testing.expectEqualStrings("tenant_id", plan.foreign_keys[0].child_columns[0]);
            try std.testing.expectEqualStrings("tenants", plan.foreign_keys[0].parent_table);
            try std.testing.expectEqual(runtime_schema.ForeignKeyAction.cascade, plan.foreign_keys[0].on_delete);
            try std.testing.expectEqual(@as(usize, 1), plan.checks.len);
            try std.testing.expectEqualStrings("inline_named_constraints_status_check", plan.checks[0].name);
            try std.testing.expect(plan.checks[0].expression != null);
            try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.lower, plan.checks[0].expression.?.lhs.kind);
            try std.testing.expectEqual(runtime_schema.RelationalCheckOp.ne, plan.checks[0].expression.?.op);
            try std.testing.expectEqualStrings("\"deleted\"", plan.checks[0].expression.?.rhs[0].value_json);
        },
        .create_index => return error.TestUnexpectedResult,
        .drop_index => return error.TestUnexpectedResult,
        .drop_table => return error.TestUnexpectedResult,
        .alter_table => return error.TestUnexpectedResult,
        .create_update_policy => return error.TestUnexpectedResult,
        else => return error.TestUnexpectedResult,
    }
}

test "postgres sql adapter lowers computed check constraints into native expression checks" {
    const alloc = std.testing.allocator;
    var lowered = try lowerDdlPlanAlloc(
        alloc,
        \\CREATE TABLE expression_checks (
        \\  id text PRIMARY KEY,
        \\  status text,
        \\  amount numeric,
        \\  fee numeric,
        \\  enabled boolean,
        \\  CONSTRAINT expression_checks_status_check CHECK (lower(status) != 'deleted'),
        \\  CONSTRAINT expression_checks_amount_check CHECK (amount + fee >= 0),
        \\  CONSTRAINT expression_checks_grouped_check CHECK (amount + fee >= 0 AND lower(status) != 'deleted' OR enabled IS TRUE),
        \\  CONSTRAINT expression_checks_nested_check CHECK ((amount + fee >= 0 OR enabled IS TRUE) AND lower(status) != 'archived'),
        \\  CONSTRAINT expression_checks_not_check CHECK (NOT (lower(status) = 'blocked' OR amount + fee < 0))
        \\);
        ,
    );
    defer lowered.deinit(alloc);

    switch (lowered) {
        .create_table => |plan| {
            try std.testing.expectEqual(@as(usize, 5), plan.checks.len);
            try std.testing.expectEqualStrings("expression_checks_status_check", plan.checks[0].name);
            try std.testing.expect(plan.checks[0].expression != null);
            try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.lower, plan.checks[0].expression.?.lhs.kind);
            try std.testing.expectEqual(runtime_schema.RelationalCheckOp.ne, plan.checks[0].expression.?.op);
            try std.testing.expectEqualStrings("\"deleted\"", plan.checks[0].expression.?.rhs[0].value_json);
            try std.testing.expectEqualStrings("expression_checks_amount_check", plan.checks[1].name);
            try std.testing.expect(plan.checks[1].expression != null);
            try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.add, plan.checks[1].expression.?.lhs.kind);
            try std.testing.expectEqual(runtime_schema.RelationalCheckOp.gte, plan.checks[1].expression.?.op);
            try std.testing.expectEqualStrings("0", plan.checks[1].expression.?.rhs[0].value_json);
            try std.testing.expectEqualStrings("expression_checks_grouped_check", plan.checks[2].name);
            try std.testing.expect(plan.checks[2].expression != null);
            const grouped = plan.checks[2].expression.?;
            try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.bool_or, grouped.lhs.kind);
            try std.testing.expectEqual(runtime_schema.RelationalCheckOp.eq, grouped.op);
            try std.testing.expectEqual(@as(usize, 1), grouped.rhs.len);
            try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.value, grouped.rhs[0].kind);
            try std.testing.expectEqualStrings("true", grouped.rhs[0].value_json);
            try std.testing.expectEqual(@as(usize, 2), grouped.lhs.operands.len);
            try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.bool_and, grouped.lhs.operands[0].kind);
            try std.testing.expectEqual(@as(usize, 2), grouped.lhs.operands[0].operands.len);
            try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.case, grouped.lhs.operands[0].operands[0].kind);
            try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.case, grouped.lhs.operands[0].operands[1].kind);
            try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.case, grouped.lhs.operands[1].kind);
            try std.testing.expectEqualStrings("expression_checks_nested_check", plan.checks[3].name);
            try std.testing.expect(plan.checks[3].expression != null);
            const nested = plan.checks[3].expression.?;
            try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.bool_or, nested.lhs.kind);
            try std.testing.expectEqual(@as(usize, 2), nested.lhs.operands.len);
            try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.bool_and, nested.lhs.operands[0].kind);
            try std.testing.expectEqual(@as(usize, 2), nested.lhs.operands[0].operands.len);
            try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.bool_and, nested.lhs.operands[1].kind);
            try std.testing.expectEqual(@as(usize, 2), nested.lhs.operands[1].operands.len);
            try std.testing.expectEqualStrings("expression_checks_not_check", plan.checks[4].name);
            try std.testing.expect(plan.checks[4].expression != null);
            const negated = plan.checks[4].expression.?;
            try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.bool_not, negated.lhs.kind);
            try std.testing.expectEqual(runtime_schema.RelationalCheckOp.eq, negated.op);
            try std.testing.expectEqual(@as(usize, 1), negated.rhs.len);
            try std.testing.expectEqualStrings("true", negated.rhs[0].value_json);
            try std.testing.expectEqual(@as(usize, 1), negated.lhs.operands.len);
            try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.bool_or, negated.lhs.operands[0].kind);

            const runtime = try runtimeSchemaFromCreateTablePlanAlloc(alloc, plan);
            defer runtime_schema.freeSchema(alloc, runtime);
            try std.testing.expectEqual(@as(usize, 5), runtime.checks.len);
            try std.testing.expect(runtime.checks[0].expression != null);
            try std.testing.expect(runtime.checks[1].expression != null);
            try std.testing.expect(runtime.checks[2].expression != null);
            try std.testing.expect(runtime.checks[3].expression != null);
            try std.testing.expect(runtime.checks[4].expression != null);
            try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.lower, runtime.checks[0].expression.?.lhs.kind);
            try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.add, runtime.checks[1].expression.?.lhs.kind);
            try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.bool_or, runtime.checks[2].expression.?.lhs.kind);
            try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.bool_or, runtime.checks[3].expression.?.lhs.kind);
            try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.bool_not, runtime.checks[4].expression.?.lhs.kind);
        },
        .create_index => return error.TestUnexpectedResult,
        .drop_index => return error.TestUnexpectedResult,
        .drop_table => return error.TestUnexpectedResult,
        .alter_table => return error.TestUnexpectedResult,
        .create_update_policy => return error.TestUnexpectedResult,
        else => return error.TestUnexpectedResult,
    }
}

test "postgres sql adapter lowers application-time temporal table constraints" {
    const alloc = std.testing.allocator;
    var lowered = try lowerDdlPlanAlloc(
        alloc,
        \\CREATE TABLE account_prices (
        \\  tenant_id text NOT NULL,
        \\  sku text NOT NULL,
        \\  valid_from timestamptz NOT NULL,
        \\  valid_to timestamptz NOT NULL,
        \\  PERIOD FOR valid_time (valid_from, valid_to),
        \\  PRIMARY KEY (tenant_id, sku, valid_time WITHOUT OVERLAPS),
        \\  CONSTRAINT account_prices_sku_time_key UNIQUE (sku, valid_time WITHOUT OVERLAPS)
        \\);
        ,
    );
    defer lowered.deinit(alloc);

    const create = switch (lowered) {
        .create_table => |plan| plan,
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expectEqual(@as(usize, 1), create.periods.len);
    try std.testing.expectEqualStrings("valid_time", create.periods[0].name);
    try std.testing.expectEqualStrings("valid_from", create.periods[0].start_column);
    try std.testing.expectEqualStrings("valid_to", create.periods[0].end_column);
    try std.testing.expect(create.primary_key != null);
    try std.testing.expectEqual(@as(usize, 2), create.primary_key.?.columns.len);
    try std.testing.expectEqualStrings("tenant_id", create.primary_key.?.columns[0]);
    try std.testing.expectEqualStrings("sku", create.primary_key.?.columns[1]);
    try std.testing.expectEqualStrings("valid_time", create.primary_key.?.without_overlaps_period.?);
    try std.testing.expectEqual(@as(usize, 1), create.unique_constraints.len);
    try std.testing.expectEqualStrings("account_prices_sku_time_key", create.unique_constraints[0].name);
    try std.testing.expectEqualStrings("valid_time", create.unique_constraints[0].without_overlaps_period.?);

    const runtime = try runtimeSchemaFromCreateTablePlanAlloc(alloc, create);
    defer runtime_schema.freeSchema(alloc, runtime);
    try std.testing.expectEqual(@as(usize, 1), runtime.periods.len);
    try std.testing.expectEqualStrings("valid_time", runtime.periods[0].name);
    try std.testing.expectEqualStrings("valid_time", runtime.primary_key.?.without_overlaps_period.?);

    const schema_json = try schemaJsonFromCreateTablePlanAlloc(alloc, create);
    defer alloc.free(schema_json);
    var parsed_schema = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed_schema.deinit(alloc);
    const derived_runtime = try schema_api.deriveRuntimeTableSchema(alloc, parsed_schema);
    defer runtime_schema.freeSchema(alloc, derived_runtime);
    try std.testing.expectEqual(@as(usize, 1), derived_runtime.periods.len);
    try std.testing.expectEqualStrings("valid_time", derived_runtime.periods[0].name);
    try std.testing.expectEqualStrings("valid_time", derived_runtime.primary_key.?.without_overlaps_period.?);

    var child_lowered = try lowerDdlPlanAlloc(
        alloc,
        \\CREATE TABLE price_adjustments (
        \\  tenant_id text NOT NULL,
        \\  sku text NOT NULL,
        \\  adjustment_id text NOT NULL,
        \\  valid_from timestamptz NOT NULL,
        \\  valid_to timestamptz NOT NULL,
        \\  PERIOD FOR valid_time (valid_from, valid_to),
        \\  PRIMARY KEY (tenant_id, sku, adjustment_id, valid_time WITHOUT OVERLAPS),
        \\  CONSTRAINT price_adjustments_price_fkey
        \\    FOREIGN KEY (tenant_id, sku, PERIOD valid_time)
        \\    REFERENCES account_prices (tenant_id, sku, PERIOD valid_time)
        \\    ON DELETE CASCADE
        \\);
        ,
    );
    defer child_lowered.deinit(alloc);
    const temporal_action_child_create = switch (child_lowered) {
        .create_table => |plan| plan,
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expectEqual(@as(usize, 1), temporal_action_child_create.foreign_keys.len);
    try std.testing.expectEqual(runtime_schema.ForeignKeyAction.cascade, temporal_action_child_create.foreign_keys[0].on_delete);
    try std.testing.expectEqual(runtime_schema.ForeignKeyAction.restrict, temporal_action_child_create.foreign_keys[0].on_update);
    try std.testing.expectEqualStrings("valid_time", temporal_action_child_create.foreign_keys[0].child_period.?);
    try std.testing.expectEqualStrings("valid_time", temporal_action_child_create.foreign_keys[0].parent_period.?);
    const temporal_action_child_schema_json = try schemaJsonFromCreateTablePlanAlloc(alloc, temporal_action_child_create);
    defer alloc.free(temporal_action_child_schema_json);
    var temporal_action_child_parsed_schema = try schema_api.parseValidatedTableSchema(alloc, temporal_action_child_schema_json);
    defer temporal_action_child_parsed_schema.deinit(alloc);

    try std.testing.expectError(error.UnsupportedSqlShape, lowerDdlPlanAlloc(
        alloc,
        \\CREATE TABLE price_adjustments_update (
        \\  tenant_id text,
        \\  sku text,
        \\  adjustment_id text NOT NULL,
        \\  valid_from timestamptz NOT NULL,
        \\  valid_to timestamptz NOT NULL,
        \\  PERIOD FOR valid_time (valid_from, valid_to),
        \\  PRIMARY KEY (adjustment_id, valid_time WITHOUT OVERLAPS),
        \\  CONSTRAINT price_adjustments_price_fkey
        \\    FOREIGN KEY (tenant_id, sku, PERIOD valid_time)
        \\    REFERENCES account_prices (tenant_id, sku, PERIOD valid_time)
        \\    ON UPDATE SET NULL
        \\);
        ,
    ));

    var alter_lowered = try lowerDdlPlanAlloc(
        alloc,
        \\ALTER TABLE account_prices
        \\  ADD PERIOD FOR sell_time (valid_from, valid_to),
        \\  ADD CONSTRAINT account_prices_sku_sell_time_key UNIQUE (sku, sell_time WITHOUT OVERLAPS);
        ,
    );
    defer alter_lowered.deinit(alloc);
    const alter = switch (alter_lowered) {
        .alter_table => |plan| plan,
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expectEqual(@as(usize, 2), alter.operations.len);
    switch (alter.operations[0]) {
        .add_period => |period| {
            try std.testing.expectEqualStrings("sell_time", period.name);
            try std.testing.expectEqualStrings("valid_from", period.start_column);
            try std.testing.expectEqualStrings("valid_to", period.end_column);
        },
        else => return error.TestUnexpectedResult,
    }
    switch (alter.operations[1]) {
        .add_unique_constraint => |constraint| {
            try std.testing.expectEqualStrings("account_prices_sku_sell_time_key", constraint.name);
            try std.testing.expectEqualStrings("sku", constraint.columns[0]);
            try std.testing.expectEqualStrings("sell_time", constraint.without_overlaps_period.?);
            try std.testing.expectEqual(runtime_schema.UniqueConstraintValidationState.unvalidated, constraint.validation_state);
        },
        else => return error.TestUnexpectedResult,
    }

    var range_lowered = try lowerDdlPlanAlloc(
        alloc,
        \\CREATE TABLE products (
        \\  product_id int NOT NULL,
        \\  product_name text NOT NULL,
        \\  price numeric,
        \\  valid_at daterange NOT NULL,
        \\  PRIMARY KEY (product_id, valid_at WITHOUT OVERLAPS)
        \\);
        ,
    );
    defer range_lowered.deinit(alloc);
    const range_create = switch (range_lowered) {
        .create_table => |plan| plan,
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expectEqual(@as(usize, 5), range_create.columns.len);
    try std.testing.expectEqualStrings("valid_at_start", range_create.columns[3].name);
    try std.testing.expectEqual(runtime_schema.AntflyType.datetime, range_create.columns[3].field_type);
    try std.testing.expect(range_create.columns[3].nullable);
    try std.testing.expectEqualStrings("valid_at_end", range_create.columns[4].name);
    try std.testing.expectEqual(runtime_schema.AntflyType.datetime, range_create.columns[4].field_type);
    try std.testing.expect(range_create.columns[4].nullable);
    try std.testing.expectEqual(@as(usize, 1), range_create.periods.len);
    try std.testing.expectEqualStrings("valid_at", range_create.periods[0].name);
    try std.testing.expectEqualStrings("valid_at_start", range_create.periods[0].start_column);
    try std.testing.expectEqualStrings("valid_at_end", range_create.periods[0].end_column);
    try std.testing.expectEqual(runtime_schema.RelationalPeriodRangeType.daterange, range_create.periods[0].range_type.?);
    try std.testing.expectEqualStrings("valid_at", range_create.primary_key.?.without_overlaps_period.?);
    const range_runtime = try runtimeSchemaFromCreateTablePlanAlloc(alloc, range_create);
    defer runtime_schema.freeSchema(alloc, range_runtime);
    var range_insert = try lowerInsertAlloc(
        alloc,
        "INSERT INTO products (product_id, product_name, price, valid_at) VALUES (1, 'widget', 19.5, '[2025-01-01,2025-07-01)'::daterange) RETURNING *",
        range_runtime,
        &.{},
    );
    defer range_insert.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 1), range_insert.batch.inserted);
    try std.testing.expectEqual(@as(usize, 1), range_insert.batch.returning_rows.len);
    var range_row = try std.json.parseFromSlice(std.json.Value, alloc, range_insert.batch.returning_rows[0], .{});
    defer range_row.deinit();
    try std.testing.expectEqual(@as(i64, 1), range_row.value.object.get("product_id").?.integer);
    try std.testing.expectEqualStrings("widget", range_row.value.object.get("product_name").?.string);
    try std.testing.expectEqual(@as(i64, 1_735_689_600_000_000_000), range_row.value.object.get("valid_at_start").?.integer);
    try std.testing.expectEqual(@as(i64, 1_751_328_000_000_000_000), range_row.value.object.get("valid_at_end").?.integer);
    var open_range_insert = try lowerInsertAlloc(
        alloc,
        "INSERT INTO products (product_id, product_name, price, valid_at) VALUES (2, 'gadget', 24.5, '[2026-01-01,)'::daterange) RETURNING *",
        range_runtime,
        &.{},
    );
    defer open_range_insert.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 1), open_range_insert.batch.inserted);
    var open_range_row = try std.json.parseFromSlice(std.json.Value, alloc, open_range_insert.batch.returning_rows[0], .{});
    defer open_range_row.deinit();
    try std.testing.expectEqual(@as(i64, 2), open_range_row.value.object.get("product_id").?.integer);
    try std.testing.expectEqual(@as(i64, 1_767_225_600_000_000_000), open_range_row.value.object.get("valid_at_start").?.integer);
    try std.testing.expect(open_range_row.value.object.get("valid_at_end").? == .null);
    var lower_open_range_insert = try lowerInsertAlloc(
        alloc,
        "INSERT INTO products (product_id, product_name, price, valid_at) VALUES (3, 'legacy', 21.5, '(,2026-01-01)'::daterange) RETURNING *",
        range_runtime,
        &.{},
    );
    defer lower_open_range_insert.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 1), lower_open_range_insert.batch.inserted);
    var lower_open_range_row = try std.json.parseFromSlice(std.json.Value, alloc, lower_open_range_insert.batch.returning_rows[0], .{});
    defer lower_open_range_row.deinit();
    try std.testing.expectEqual(@as(i64, 3), lower_open_range_row.value.object.get("product_id").?.integer);
    try std.testing.expect(lower_open_range_row.value.object.get("valid_at_start").? == .null);
    try std.testing.expectEqual(@as(i64, 1_767_225_600_000_000_000), lower_open_range_row.value.object.get("valid_at_end").?.integer);

    var constructor_range_insert = try lowerInsertAlloc(
        alloc,
        "INSERT INTO products (product_id, product_name, price, valid_at) VALUES (4, 'constructor', 26.5, daterange(DATE '2025-02-01', DATE '2025-03-01')) RETURNING *",
        range_runtime,
        &.{},
    );
    defer constructor_range_insert.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 1), constructor_range_insert.batch.inserted);
    var constructor_range_row = try std.json.parseFromSlice(std.json.Value, alloc, constructor_range_insert.batch.returning_rows[0], .{});
    defer constructor_range_row.deinit();
    try std.testing.expectEqual(@as(i64, 4), constructor_range_row.value.object.get("product_id").?.integer);
    try std.testing.expectEqual(@as(i64, 1_738_368_000_000_000_000), constructor_range_row.value.object.get("valid_at_start").?.integer);
    try std.testing.expectEqual(@as(i64, 1_740_787_200_000_000_000), constructor_range_row.value.object.get("valid_at_end").?.integer);

    var parameterized_constructor_range_insert = try lowerInsertAlloc(
        alloc,
        "INSERT INTO products (product_id, product_name, price, valid_at) VALUES (5, 'open-constructor', 27.5, daterange($1::date, null, '[)')) RETURNING *",
        range_runtime,
