    try std.testing.expectEqual(@as(usize, 0), missing_noop.schema_json.len);
    try std.testing.expect(!missing_noop.requires_rebuild);
    try std.testing.expect(!missing_noop.validation_required);

    var missing_table = try lowerDdlPlanAlloc(alloc, "ALTER TABLE missing_users ADD COLUMN status text;");
    defer missing_table.deinit(alloc);
    try std.testing.expectError(error.InvalidSqlCatalog, applyDdlPlanToSchemaJsonAlloc(alloc, "", missing_table));

    var missing_drop_index_if_exists = try lowerDdlPlanAlloc(alloc, "DROP INDEX IF EXISTS missing_users_status_idx;");
    defer missing_drop_index_if_exists.deinit(alloc);
    var missing_drop_noop = try applyDdlPlanToSchemaJsonAlloc(alloc, "", missing_drop_index_if_exists);
    defer missing_drop_noop.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 0), missing_drop_noop.schema_json.len);

    var drop_table = try lowerDdlPlanAlloc(alloc, "DROP TABLE users;");
    defer drop_table.deinit(alloc);
    var dropped_table = try applyDdlPlanToSchemaJsonAlloc(alloc, created.schema_json, drop_table);
    defer dropped_table.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 0), dropped_table.schema_json.len);
    try std.testing.expect(!dropped_table.requires_rebuild);
    try std.testing.expect(!dropped_table.validation_required);
    try std.testing.expect(!dropped_table.rewrite_required);
    try std.testing.expectError(error.InvalidSqlCatalog, applyDdlPlanToSchemaJsonAlloc(alloc, "", drop_table));

    var drop_table_if_exists = try lowerDdlPlanAlloc(alloc, "DROP TABLE IF EXISTS users;");
    defer drop_table_if_exists.deinit(alloc);
    var missing_drop_table_noop = try applyDdlPlanToSchemaJsonAlloc(alloc, "", drop_table_if_exists);
    defer missing_drop_table_noop.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 0), missing_drop_table_noop.schema_json.len);
}

test "postgres sql adapter rejects unsupported ddl shapes explicitly" {
    const alloc = std.testing.allocator;
    try std.testing.expectError(error.UnsupportedSqlShape, lowerDdlPlanAlloc(
        alloc,
        "CREATE OR REPLACE TABLE IF NOT EXISTS audit_log (id uuid PRIMARY KEY)",
    ));
    var no_primary_key = try lowerDdlPlanAlloc(
        alloc,
        "CREATE TABLE audit_log (id uuid, payload jsonb)",
    );
    defer no_primary_key.deinit(alloc);
    const no_primary_key_plan = switch (no_primary_key) {
        .create_table => |create_table| create_table,
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expect(no_primary_key_plan.primary_key == null);
    try std.testing.expectError(error.UnsupportedSqlShape, lowerDdlPlanAlloc(
        alloc,
        "CREATE TABLE audit_log (id uuid PRIMARY KEY, amount numeric DEFAULT 0::text)",
    ));
    var text_cast_numeric_default = try lowerDdlPlanAlloc(
        alloc,
        "CREATE TABLE audit_log (id uuid PRIMARY KEY, amount numeric DEFAULT '0'::text)",
    );
    defer text_cast_numeric_default.deinit(alloc);
    try std.testing.expectError(error.UnsupportedSqlShape, applyDdlPlanToRuntimeSchemaAlloc(alloc, .{}, text_cast_numeric_default));
    try std.testing.expectError(error.UnsupportedSqlShape, lowerDdlPlanAlloc(
        alloc,
        "CREATE TABLE audit_log (id uuid PRIMARY KEY, amount numeric COLLATE \"C\")",
    ));
    try std.testing.expectError(error.UnsupportedSqlShape, lowerDdlPlanAlloc(
        alloc,
        "ALTER TABLE audit_log ALTER COLUMN amount TYPE numeric USING amount + 1",
    ));
    try std.testing.expectError(error.UnsupportedSqlShape, lowerDdlPlanAlloc(
        alloc,
        "CREATE TRIGGER audit_row AFTER UPDATE ON usage_records EXECUTE FUNCTION audit_changes()",
    ));
    var drop_cascade = try lowerDdlPlanAlloc(alloc, "DROP TABLE usage_records CASCADE");
    defer drop_cascade.deinit(alloc);
    const drop_cascade_plan = switch (drop_cascade) {
        .drop_table => |drop_table| drop_table,
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expect(drop_cascade_plan.cascade);
    const drop_cascade_fingerprint = try ddlFingerprintAlloc(alloc, drop_cascade);
    defer alloc.free(drop_cascade_fingerprint);
    try std.testing.expectEqualStrings("ddl:drop_table:table=usage_records:if_exists=false:cascade=true", drop_cascade_fingerprint);

    try std.testing.expectError(error.UnsupportedSqlShape, lowerDdlPlanAlloc(
        alloc,
        "DROP TABLE usage_records, archived_usage_records",
    ));
}

test "postgres sql adapter lowers application queue select into row claim query" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"status":{"type":"keyword"},"billing_cycle_start":{"type":"datetime"},"metric_type":{"type":"keyword"},"bucket_start":{"type":"datetime"},"created_at":{"type":"datetime"}},"required":["id","status"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);
    var lowered = try lowerSelectAlloc(
        alloc,
        "SELECT id, metric_type FROM usage_records WHERE status = $1 ORDER BY billing_cycle_start ASC, metric_type ASC, bucket_start ASC, id ASC LIMIT $2 FOR UPDATE SKIP LOCKED",
        schema,
        &.{ .{ .string = "unrated" }, .{ .integer = 100 } },
    );
    defer lowered.deinit(alloc);

    try std.testing.expectEqualStrings("usage_records", lowered.table_name);
    try std.testing.expectEqual(@as(usize, 2), lowered.query.select.len);
    try std.testing.expectEqualStrings("id", lowered.query.select[0]);
    try std.testing.expect(!lowered.query.select_all);
    try std.testing.expectEqual(@as(usize, 1), lowered.query.predicates.len);
    try std.testing.expectEqualStrings("status", lowered.query.predicates[0].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.eq, lowered.query.predicates[0].op);
    try std.testing.expectEqualStrings("\"unrated\"", lowered.query.predicates[0].value_json.?);
    try std.testing.expectEqual(@as(usize, 4), lowered.query.order_by.len);
    try std.testing.expectEqualStrings("billing_cycle_start", lowered.query.order_by[0].field);
    try std.testing.expectEqual(@as(u32, 100), lowered.query.limit.?);
    try std.testing.expect(lowered.query.row_claim != null);
    try std.testing.expectEqual(db_mod.types.RowClaimWaitPolicy.skip_locked, lowered.query.row_claim.?.wait_policy);
    try std.testing.expectEqual(db_mod.types.RowClaimWaitPolicy.skip_locked, lowered.query.row_claim.?.effectiveWaitPolicy());
    try std.testing.expect(lowered.query.row_claim.?.skip_locked);

    var targeted_alias = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records AS u WHERE status = 'queued' ORDER BY id ASC LIMIT 1 FOR UPDATE OF u SKIP LOCKED",
        schema,
        &.{},
    );
    defer targeted_alias.deinit(alloc);
    try std.testing.expectEqualStrings("usage_records", targeted_alias.table_name);
    try std.testing.expect(targeted_alias.query.row_claim != null);
    try std.testing.expectEqual(db_mod.types.RowClaimWaitPolicy.skip_locked, targeted_alias.query.row_claim.?.wait_policy);
    try std.testing.expect(targeted_alias.query.row_claim.?.skip_locked);

    var targeted_table = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM public.usage_records WHERE status = 'queued' FOR UPDATE OF public.usage_records",
        schema,
        &.{},
    );
    defer targeted_table.deinit(alloc);
    try std.testing.expect(targeted_table.query.row_claim != null);
    try std.testing.expectEqual(db_mod.types.RowClaimMode.for_update, targeted_table.query.row_claim.?.mode);
    try std.testing.expectEqual(db_mod.types.RowClaimWaitPolicy.wait, targeted_table.query.row_claim.?.wait_policy);
    try std.testing.expect(!targeted_table.query.row_claim.?.skip_locked);

    var nowait_claim = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records AS u WHERE status = 'queued' FOR UPDATE OF u NOWAIT",
        schema,
        &.{},
    );
    defer nowait_claim.deinit(alloc);
    try std.testing.expect(nowait_claim.query.row_claim != null);
    try std.testing.expectEqual(db_mod.types.RowClaimMode.for_update, nowait_claim.query.row_claim.?.mode);
    try std.testing.expectEqual(db_mod.types.RowClaimWaitPolicy.nowait, nowait_claim.query.row_claim.?.wait_policy);
    try std.testing.expectEqual(db_mod.types.RowClaimWaitPolicy.nowait, nowait_claim.query.row_claim.?.effectiveWaitPolicy());
    try std.testing.expect(!nowait_claim.query.row_claim.?.skip_locked);

    var no_key_update_claim = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records AS u WHERE status = 'queued' FOR NO KEY UPDATE OF u SKIP LOCKED",
        schema,
        &.{},
    );
    defer no_key_update_claim.deinit(alloc);
    try std.testing.expect(no_key_update_claim.query.row_claim != null);
    try std.testing.expectEqual(db_mod.types.RowClaimMode.for_no_key_update, no_key_update_claim.query.row_claim.?.mode);
    try std.testing.expectEqual(db_mod.types.RowClaimWaitPolicy.skip_locked, no_key_update_claim.query.row_claim.?.wait_policy);
    try std.testing.expectEqual(db_mod.types.RowClaimWaitPolicy.skip_locked, no_key_update_claim.query.row_claim.?.effectiveWaitPolicy());
    try std.testing.expect(no_key_update_claim.query.row_claim.?.skip_locked);

    try std.testing.expectError(error.UnsupportedSqlShape, lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records AS u WHERE status = 'queued' FOR UPDATE OF archived_records",
        schema,
        &.{},
    ));
}

test "postgres sql adapter lowers select all with named extra projections" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"status":{"type":"keyword"},"metadata":{"type":"json"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);

    var lowered = try lowerSelectAlloc(
        alloc,
        "SELECT *, lower(status) AS status_key, metadata->>'source' AS source FROM usage_records ORDER BY id ASC LIMIT 5",
        schema,
        &.{},
    );
    defer lowered.deinit(alloc);

    try std.testing.expect(lowered.query.select_all);
    try std.testing.expectEqual(@as(usize, 0), lowered.query.select.len);
    try std.testing.expectEqual(@as(usize, 2), lowered.query.expressions.len);
    try std.testing.expectEqualStrings("status_key", lowered.query.expressions[0].output);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.lower, lowered.query.expressions[0].expression.kind);
    try std.testing.expectEqualStrings("source", lowered.query.expressions[1].output);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.json_extract, lowered.query.expressions[1].expression.kind);
    try std.testing.expectEqual(@as(usize, 1), lowered.query.order_by.len);
    try std.testing.expectEqual(@as(u32, 5), lowered.query.limit.?);

    try std.testing.expectError(error.UnsupportedSqlShape, lowerSelectAlloc(
        alloc,
        "SELECT *, id FROM usage_records ORDER BY id ASC",
        schema,
        &.{},
    ));
    try std.testing.expectError(error.UnsupportedSqlShape, lowerSelectAlloc(
        alloc,
        "SELECT *, lower(status) AS id FROM usage_records ORDER BY id ASC",
        schema,
        &.{},
    ));
    try std.testing.expectError(error.UnsupportedSqlShape, lowerSelectAlloc(
        alloc,
        "SELECT id, id FROM usage_records ORDER BY id ASC",
        schema,
        &.{},
    ));
    try std.testing.expectError(error.UnsupportedSqlShape, lowerSelectAlloc(
        alloc,
        "SELECT id, lower(status) AS id FROM usage_records ORDER BY id ASC",
        schema,
        &.{},
    ));
}

test "postgres sql adapter lowers limit all to unbounded typed plans" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"tenant_id":{"type":"keyword"},"status":{"type":"keyword"},"amount":{"type":"numeric"},"created_at":{"type":"datetime"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);

    var query = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE status = 'open' ORDER BY created_at DESC LIMIT ALL OFFSET 2",
        schema,
        &.{},
    );
    defer query.deinit(alloc);
    try std.testing.expect(query.query.limit == null);
    try std.testing.expectEqual(@as(u32, 2), query.query.offset);

    var null_pagination_query = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE status = 'open' ORDER BY created_at DESC LIMIT NULL OFFSET NULL",
        schema,
        &.{},
    );
    defer null_pagination_query.deinit(alloc);
    try std.testing.expect(null_pagination_query.query.limit == null);
    try std.testing.expectEqual(@as(u32, 0), null_pagination_query.query.offset);

    var bound_null_pagination_query = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE status = 'open' ORDER BY created_at DESC LIMIT $1 OFFSET $2",
        schema,
        &.{ .null, .null },
    );
    defer bound_null_pagination_query.deinit(alloc);
    try std.testing.expect(bound_null_pagination_query.query.limit == null);
    try std.testing.expectEqual(@as(u32, 0), bound_null_pagination_query.query.offset);

    var fetch_query = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE status = 'open' ORDER BY created_at DESC OFFSET 2 ROWS FETCH NEXT 3 ROWS ONLY",
        schema,
        &.{},
    );
    defer fetch_query.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 3), fetch_query.query.limit.?);
    try std.testing.expectEqual(@as(u32, 2), fetch_query.query.offset);

    var aggregate = try lowerAggregateAlloc(
        alloc,
        "SELECT status, SUM(amount) AS total FROM usage_records GROUP BY status ORDER BY total DESC LIMIT ALL OFFSET 3 ROWS",
        schema,
        &.{},
    );
    defer aggregate.deinit(alloc);
    try std.testing.expect(aggregate.aggregate.limit == null);
    try std.testing.expectEqual(@as(u32, 3), aggregate.aggregate.offset);

    var window = try lowerWindowPlanAlloc(
        alloc,
        "SELECT tenant_id, id, row_number() OVER (PARTITION BY tenant_id ORDER BY amount DESC) AS rn FROM usage_records WHERE status = 'open' ORDER BY rn ASC OFFSET 4 ROWS FETCH FIRST 2 ROWS ONLY",
        schema,
        &.{},
    );
    defer window.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 2), window.plan.window.limit.?);
    try std.testing.expectEqual(@as(u32, 4), window.plan.window.offset);

    const txn_id = [_]u8{ 0x20, 0x21, 0x22, 0x23, 0x24, 0x25, 0x26, 0x27, 0x28, 0x29, 0x2a, 0x2b, 0x2c, 0x2d, 0x2e, 0x2f };
    const claim: db_mod.types.RowClaimRequest = .{
        .mode = .for_update,
        .owner_id = "worker-limit-all",
        .txn_id = txn_id,
    };
    var mutation = try lowerUpdateMutationSourceAlloc(
        alloc,
        "UPDATE usage_records SET status = 'processing' WHERE status = 'queued' ORDER BY id ASC OFFSET 1 ROW FETCH FIRST ROW ONLY FOR UPDATE RETURNING id",
        schema,
        &.{},
        claim,
    );
    defer mutation.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 1), mutation.mutation.req.source.limit.?);
    try std.testing.expectEqual(@as(u32, 1), mutation.mutation.req.source.offset);
}

