test "postgres sql adapter lowers jsonb containment existence and extraction projection" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"metadata":{"type":"json"},"created_at":{"type":"datetime"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);

    var lowered = try lowerSelectAlloc(
        alloc,
        "SELECT metadata->>'source' AS source, metadata->'flags' AS flags FROM usage_records WHERE metadata @> $1::jsonb AND metadata ? 'flags' ORDER BY created_at DESC LIMIT 5",
        schema,
        &.{.{ .json = "{\"billing\":{\"plan\":\"pro\"}}" }},
    );
    defer lowered.deinit(alloc);

    try std.testing.expect(!lowered.query.select_all);
    try std.testing.expectEqual(@as(usize, 0), lowered.query.select.len);
    try std.testing.expectEqual(@as(usize, 0), lowered.query.json_extract.len);
    try std.testing.expectEqual(@as(usize, 2), lowered.query.expressions.len);
    try std.testing.expectEqualStrings("source", lowered.query.expressions[0].output);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.json_extract, lowered.query.expressions[0].expression.kind);
    try std.testing.expectEqualStrings("source", lowered.query.expressions[0].expression.json_path);
    try std.testing.expect(lowered.query.expressions[0].expression.json_as_text);
    try std.testing.expectEqual(@as(usize, 1), lowered.query.expressions[0].expression.operands.len);
    try std.testing.expectEqualStrings("metadata", lowered.query.expressions[0].expression.operands[0].field);
    try std.testing.expectEqualStrings("flags", lowered.query.expressions[1].output);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.json_extract, lowered.query.expressions[1].expression.kind);
    try std.testing.expectEqualStrings("flags", lowered.query.expressions[1].expression.json_path);
    try std.testing.expect(!lowered.query.expressions[1].expression.json_as_text);
    try std.testing.expectEqual(@as(usize, 1), lowered.query.expressions[1].expression.operands.len);
    try std.testing.expectEqualStrings("metadata", lowered.query.expressions[1].expression.operands[0].field);
    try std.testing.expectEqual(@as(usize, 1), lowered.query.json_contains.len);
    try std.testing.expectEqualStrings("metadata", lowered.query.json_contains[0].field);
    try std.testing.expectEqualStrings("{\"billing\":{\"plan\":\"pro\"}}", lowered.query.json_contains[0].value_json);
    try std.testing.expectEqual(@as(usize, 1), lowered.query.json_path_exists.len);
    try std.testing.expectEqualStrings("metadata", lowered.query.json_path_exists[0].field);
    try std.testing.expectEqualStrings("flags", lowered.query.json_path_exists[0].path);
    try std.testing.expectEqual(@as(u32, 5), lowered.query.limit.?);

    var parameterized = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE metadata ? $1::text ORDER BY created_at DESC LIMIT 1",
        schema,
        &.{.{ .string = "flags" }},
    );
    defer parameterized.deinit(alloc);

    try std.testing.expectEqual(@as(usize, 1), parameterized.query.json_path_exists.len);
    try std.testing.expectEqualStrings("metadata", parameterized.query.json_path_exists[0].field);
    try std.testing.expectEqualStrings("flags", parameterized.query.json_path_exists[0].path);

    var expression_exists = try lowerSelectAlloc(
        alloc,
        "SELECT metadata ? 'flags' AS has_flags FROM usage_records WHERE (metadata ? 'flags') IS TRUE ORDER BY id ASC LIMIT 5",
        schema,
        &.{},
    );
    defer expression_exists.deinit(alloc);

    try std.testing.expectEqual(@as(usize, 1), expression_exists.query.expressions.len);
    try std.testing.expectEqualStrings("has_flags", expression_exists.query.expressions[0].output);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.json_path_exists, expression_exists.query.expressions[0].expression.kind);
    try std.testing.expectEqualStrings("flags", expression_exists.query.expressions[0].expression.json_path);
    try std.testing.expectEqual(@as(usize, 1), expression_exists.query.expressions[0].expression.operands.len);
    try std.testing.expectEqualStrings("metadata", expression_exists.query.expressions[0].expression.operands[0].field);
    try std.testing.expectEqual(@as(usize, 1), expression_exists.query.expression_predicates.len);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.json_path_exists, expression_exists.query.expression_predicates[0].lhs.kind);
    try std.testing.expectEqualStrings("flags", expression_exists.query.expression_predicates[0].lhs.json_path);
    try std.testing.expectEqualStrings("true", expression_exists.query.expression_predicates[0].rhs[0].value_json);

    var key_set_exists = try lowerSelectAlloc(
        alloc,
        "SELECT metadata ?| ARRAY['flags', 'billing'] AS has_any_key FROM usage_records WHERE (metadata ?& ARRAY['flags', 'billing']) IS TRUE ORDER BY id ASC LIMIT 5",
        schema,
        &.{},
    );
    defer key_set_exists.deinit(alloc);

    try std.testing.expectEqual(@as(usize, 1), key_set_exists.query.expressions.len);
    try std.testing.expectEqualStrings("has_any_key", key_set_exists.query.expressions[0].output);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.bool_or, key_set_exists.query.expressions[0].expression.kind);
    try std.testing.expectEqual(@as(usize, 2), key_set_exists.query.expressions[0].expression.operands.len);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.json_path_exists, key_set_exists.query.expressions[0].expression.operands[0].kind);
    try std.testing.expectEqualStrings("flags", key_set_exists.query.expressions[0].expression.operands[0].json_path);
    try std.testing.expectEqualStrings("metadata", key_set_exists.query.expressions[0].expression.operands[0].operands[0].field);
    try std.testing.expectEqualStrings("billing", key_set_exists.query.expressions[0].expression.operands[1].json_path);
    try std.testing.expectEqual(@as(usize, 1), key_set_exists.query.expression_predicates.len);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.bool_and, key_set_exists.query.expression_predicates[0].lhs.kind);
    try std.testing.expectEqual(@as(usize, 2), key_set_exists.query.expression_predicates[0].lhs.operands.len);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.json_path_exists, key_set_exists.query.expression_predicates[0].lhs.operands[0].kind);
    try std.testing.expectEqualStrings("flags", key_set_exists.query.expression_predicates[0].lhs.operands[0].json_path);
    try std.testing.expectEqualStrings("billing", key_set_exists.query.expression_predicates[0].lhs.operands[1].json_path);
    try std.testing.expectEqualStrings("true", key_set_exists.query.expression_predicates[0].rhs[0].value_json);

    var negated_key_set_exists = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE NOT (metadata ?| ARRAY['debug', 'internal']) ORDER BY id ASC LIMIT 5",
        schema,
        &.{},
    );
    defer negated_key_set_exists.deinit(alloc);
