test "postgres sql adapter accepts casted jsonb document literals" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"metadata":{"type":"json"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);

    var lowered = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE metadata @> '{\"source\":\"autoscale_delta\"}'::jsonb",
        schema,
        &.{},
    );
    defer lowered.deinit(alloc);

    try std.testing.expectEqual(@as(usize, 1), lowered.query.json_contains.len);
    try std.testing.expectEqualStrings("{\"source\":\"autoscale_delta\"}", lowered.query.json_contains[0].value_json);
}

test "postgres sql adapter lowers array containment and equality predicates" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"tags":{"type":"array","items":{"type":"keyword"}}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);

    var contains = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE tags @> $1::text[]",
        schema,
        &.{.{ .json = "[\"hot\",\"new\"]" }},
    );
    defer contains.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), contains.query.array_contains.len);
    try std.testing.expectEqualStrings("tags", contains.query.array_contains[0].field);
    try std.testing.expectEqualStrings("[\"hot\",\"new\"]", contains.query.array_contains[0].value_json);

    var constructor_contains = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE tags @> ARRAY['hot','new']::text[]",
        schema,
        &.{},
    );
    defer constructor_contains.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), constructor_contains.query.array_contains.len);
    try std.testing.expectEqualStrings("tags", constructor_contains.query.array_contains[0].field);
    try std.testing.expectEqualStrings("[\"hot\",\"new\"]", constructor_contains.query.array_contains[0].value_json);

    var any = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE 'hot' = ANY(tags)",
        schema,
        &.{},
    );
    defer any.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), any.query.array_any.len);
    try std.testing.expectEqualStrings("tags", any.query.array_any[0].field);
    try std.testing.expectEqualStrings("\"hot\"", any.query.array_any[0].value_json);

    var overlap = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE tags && ARRAY['hot','new']::text[]",
        schema,
        &.{},
    );
    defer overlap.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 0), overlap.query.array_any.len);
    try std.testing.expectEqual(@as(usize, 2), overlap.query.access_or_predicates.len);
    try std.testing.expectEqual(@as(usize, 1), overlap.query.access_or_predicates[0].array_any.len);
    try std.testing.expectEqualStrings("tags", overlap.query.access_or_predicates[0].array_any[0].field);
    try std.testing.expectEqualStrings("\"hot\"", overlap.query.access_or_predicates[0].array_any[0].value_json);
    try std.testing.expectEqual(@as(usize, 1), overlap.query.access_or_predicates[1].array_any.len);
    try std.testing.expectEqualStrings("tags", overlap.query.access_or_predicates[1].array_any[0].field);
    try std.testing.expectEqualStrings("\"new\"", overlap.query.access_or_predicates[1].array_any[0].value_json);

    var overlap_and = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE tags && ARRAY['hot','new'] AND id = 'u1'",
        schema,
        &.{},
    );
    defer overlap_and.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 2), overlap_and.query.access_or_predicates.len);
    for (overlap_and.query.access_or_predicates) |group| {
        try std.testing.expectEqual(@as(usize, 1), group.predicates.len);
        try std.testing.expectEqualStrings("id", group.predicates[0].field);
        try std.testing.expectEqualStrings("\"u1\"", group.predicates[0].value_json.?);
        try std.testing.expectEqual(@as(usize, 1), group.array_any.len);
        try std.testing.expectEqualStrings("tags", group.array_any[0].field);
    }

    var overlap_or = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE (tags && ARRAY['hot','new'] AND id = 'u1') OR (tags && ARRAY['warm'] AND id = 'u2')",
        schema,
        &.{},
    );
    defer overlap_or.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 3), overlap_or.query.access_or_predicates.len);
    try std.testing.expectEqualStrings("\"hot\"", overlap_or.query.access_or_predicates[0].array_any[0].value_json);
    try std.testing.expectEqualStrings("\"new\"", overlap_or.query.access_or_predicates[1].array_any[0].value_json);
    try std.testing.expectEqualStrings("\"warm\"", overlap_or.query.access_or_predicates[2].array_any[0].value_json);

    var overlap_not = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE NOT (tags && ARRAY['hot','new'])",
        schema,
        &.{},
    );
    defer overlap_not.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 0), overlap_not.query.access_or_predicates.len);
    try std.testing.expectEqual(@as(usize, 2), overlap_not.query.access_not_predicates.len);
    try std.testing.expectEqualStrings("\"hot\"", overlap_not.query.access_not_predicates[0].array_any[0].value_json);
    try std.testing.expectEqualStrings("\"new\"", overlap_not.query.access_not_predicates[1].array_any[0].value_json);

    var eq = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE tags = $1::text[]",
        schema,
        &.{.{ .json = "[\"hot\"]" }},
    );
    defer eq.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), eq.query.array_eq.len);
    try std.testing.expectEqualStrings("tags", eq.query.array_eq[0].field);
    try std.testing.expectEqualStrings("[\"hot\"]", eq.query.array_eq[0].value_json);

    var constructor_eq = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE tags = ARRAY['hot']",
        schema,
        &.{},
    );
    defer constructor_eq.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), constructor_eq.query.array_eq.len);
    try std.testing.expectEqualStrings("tags", constructor_eq.query.array_eq[0].field);
    try std.testing.expectEqualStrings("[\"hot\"]", constructor_eq.query.array_eq[0].value_json);

    try std.testing.expectError(error.UnsupportedSqlShape, lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE tags @> $1::text[]",
        schema,
        &.{.{ .json = "[\"hot\",3]" }},
    ));
    try std.testing.expectError(error.UnsupportedSqlShape, lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE 3 = ANY(tags)",
        schema,
        &.{},
    ));
    try std.testing.expectError(error.UnsupportedSqlShape, lowerSelectAlloc(
        alloc,
