    try std.testing.expectEqual(@as(usize, 3), not_false_or_lowered.query.or_predicates.len);
    try std.testing.expectEqualStrings("enabled", not_false_or_lowered.query.or_predicates[0].predicates[0].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.ne, not_false_or_lowered.query.or_predicates[0].predicates[0].op);
    try std.testing.expectEqualStrings("false", not_false_or_lowered.query.or_predicates[0].predicates[0].value_json.?);
