test "postgres sql adapter lowers bare boolean where expressions into expression AST" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"enabled":{"type":"boolean"},"verified":{"type":"boolean"},"status":{"type":"keyword"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);

    var bare_field = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE enabled ORDER BY id",
        schema,
        &.{},
    );
    defer bare_field.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), bare_field.query.expression_predicates.len);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.field, bare_field.query.expression_predicates[0].lhs.kind);
    try std.testing.expectEqualStrings("enabled", bare_field.query.expression_predicates[0].lhs.field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.eq, bare_field.query.expression_predicates[0].op);
    try std.testing.expectEqualStrings("true", bare_field.query.expression_predicates[0].rhs[0].value_json);

    var and_not = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE enabled AND NOT verified ORDER BY id",
        schema,
        &.{},
    );
    defer and_not.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), and_not.query.expression_predicates.len);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.bool_and, and_not.query.expression_predicates[0].lhs.kind);
    try std.testing.expectEqualStrings("enabled", and_not.query.expression_predicates[0].lhs.operands[0].field);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.bool_not, and_not.query.expression_predicates[0].lhs.operands[1].kind);
    try std.testing.expectEqualStrings("verified", and_not.query.expression_predicates[0].lhs.operands[1].operands[0].field);

    var or_expression = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE enabled OR starts_with(status, 'op') ORDER BY id",
        schema,
        &.{},
    );
    defer or_expression.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), or_expression.query.expression_predicates.len);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.bool_or, or_expression.query.expression_predicates[0].lhs.kind);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.starts_with, or_expression.query.expression_predicates[0].lhs.operands[1].kind);

    var not_group = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE NOT (enabled OR verified) ORDER BY id",
        schema,
        &.{},
    );
    defer not_group.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), not_group.query.expression_predicates.len);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.bool_not, not_group.query.expression_predicates[0].lhs.kind);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.bool_or, not_group.query.expression_predicates[0].lhs.operands[0].kind);

    try std.testing.expectError(error.InvalidSqlCatalog, lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE status",
        schema,
        &.{},
    ));
}

test "postgres sql adapter lowers text pattern predicates" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"name":{"type":"text"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);

    var lowered = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE name ILIKE $1 AND name NOT LIKE 'bot%' AND name LIKE 'a!_%' ESCAPE '!'",
        schema,
        &.{.{ .string = "a%" }},
    );
    defer lowered.deinit(alloc);

    try std.testing.expectEqual(@as(usize, 3), lowered.query.text_patterns.len);
    try std.testing.expectEqualStrings("name", lowered.query.text_patterns[0].field);
    try std.testing.expectEqualStrings("a%", lowered.query.text_patterns[0].pattern);
    try std.testing.expect(lowered.query.text_patterns[0].case_insensitive);
    try std.testing.expect(!lowered.query.text_patterns[0].negated);
    try std.testing.expectEqualStrings("bot%", lowered.query.text_patterns[1].pattern);
    try std.testing.expect(!lowered.query.text_patterns[1].case_insensitive);
    try std.testing.expect(lowered.query.text_patterns[1].negated);
    try std.testing.expectEqualStrings("a\\_%", lowered.query.text_patterns[2].pattern);
    try std.testing.expect(!lowered.query.text_patterns[2].case_insensitive);
    try std.testing.expect(!lowered.query.text_patterns[2].negated);

    var parameterized_escape = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE name ILIKE $1 ESCAPE $2",
        schema,
        &.{ .{ .string = "A!%%" }, .{ .string = "!" } },
    );
    defer parameterized_escape.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), parameterized_escape.query.text_patterns.len);
    try std.testing.expectEqualStrings("A\\%%", parameterized_escape.query.text_patterns[0].pattern);
    try std.testing.expect(parameterized_escape.query.text_patterns[0].case_insensitive);

    var pattern_any = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE name ILIKE ANY($1::text[]) ORDER BY id",
        schema,
        &.{.{ .json = "[\"Ada%\",\"Grace%\"]" }},
    );
    defer pattern_any.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 0), pattern_any.query.text_patterns.len);
    try std.testing.expectEqual(@as(usize, 1), pattern_any.query.expression_predicates.len);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.bool_or, pattern_any.query.expression_predicates[0].lhs.kind);
    try std.testing.expectEqual(@as(usize, 2), pattern_any.query.expression_predicates[0].lhs.operands.len);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.ilike, pattern_any.query.expression_predicates[0].lhs.operands[0].kind);
    try std.testing.expectEqualStrings("name", pattern_any.query.expression_predicates[0].lhs.operands[0].operands[0].field);
    try std.testing.expectEqualStrings("\"Ada%\"", pattern_any.query.expression_predicates[0].lhs.operands[0].operands[1].value_json);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.ilike, pattern_any.query.expression_predicates[0].lhs.operands[1].kind);
    try std.testing.expectEqualStrings("\"Grace%\"", pattern_any.query.expression_predicates[0].lhs.operands[1].operands[1].value_json);
    try std.testing.expectEqualStrings("true", pattern_any.query.expression_predicates[0].rhs[0].value_json);

    var not_pattern_all = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE name NOT LIKE ALL(ARRAY['bot%', 'sys%']) ORDER BY id",
        schema,
        &.{},
    );
    defer not_pattern_all.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), not_pattern_all.query.expression_predicates.len);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.bool_and, not_pattern_all.query.expression_predicates[0].lhs.kind);
    try std.testing.expectEqual(@as(usize, 2), not_pattern_all.query.expression_predicates[0].lhs.operands.len);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.bool_not, not_pattern_all.query.expression_predicates[0].lhs.operands[0].kind);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.like, not_pattern_all.query.expression_predicates[0].lhs.operands[0].operands[0].kind);
    try std.testing.expectEqualStrings("\"bot%\"", not_pattern_all.query.expression_predicates[0].lhs.operands[0].operands[0].operands[1].value_json);

    var computed_pattern_any = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE lower(name) LIKE ANY(ARRAY['ada%', 'grace%']) ORDER BY id",
        schema,
        &.{},
    );
    defer computed_pattern_any.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 0), computed_pattern_any.query.text_patterns.len);
    try std.testing.expectEqual(@as(usize, 1), computed_pattern_any.query.expression_predicates.len);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.bool_or, computed_pattern_any.query.expression_predicates[0].lhs.kind);
    try std.testing.expectEqual(@as(usize, 2), computed_pattern_any.query.expression_predicates[0].lhs.operands.len);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.like, computed_pattern_any.query.expression_predicates[0].lhs.operands[0].kind);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.lower, computed_pattern_any.query.expression_predicates[0].lhs.operands[0].operands[0].kind);
    try std.testing.expectEqualStrings("name", computed_pattern_any.query.expression_predicates[0].lhs.operands[0].operands[0].operands[0].field);
    try std.testing.expectEqualStrings("\"ada%\"", computed_pattern_any.query.expression_predicates[0].lhs.operands[0].operands[1].value_json);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.like, computed_pattern_any.query.expression_predicates[0].lhs.operands[1].kind);
    try std.testing.expectEqualStrings("\"grace%\"", computed_pattern_any.query.expression_predicates[0].lhs.operands[1].operands[1].value_json);
    try std.testing.expectEqualStrings("true", computed_pattern_any.query.expression_predicates[0].rhs[0].value_json);

    var pattern_any_or = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE name LIKE ANY(ARRAY['a%', 'b%']) OR id = 'u1' ORDER BY id",
        schema,
        &.{},
    );
    defer pattern_any_or.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 0), pattern_any_or.query.access_or_predicates.len);
    try std.testing.expectEqual(@as(usize, 2), pattern_any_or.query.expression_or_predicates.len);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.bool_or, pattern_any_or.query.expression_or_predicates[0].conditions[0].lhs.kind);
    try std.testing.expectEqualStrings("id", pattern_any_or.query.expression_or_predicates[1].conditions[0].lhs.field);

    try std.testing.expectError(error.UnsupportedSqlShape, lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE name LIKE 'a!_%' ESCAPE '!!'",
        schema,
        &.{},
    ));
}

test "postgres sql adapter lowers scalar in predicates" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"status":{"type":"keyword"},"priority":{"type":"numeric"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);

    var literal = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE status IN ('active', 'pending')",
        schema,
        &.{},
    );
    defer literal.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), literal.query.in_predicates.len);
    try std.testing.expectEqualStrings("status", literal.query.in_predicates[0].field);
    try std.testing.expectEqualStrings("[\"active\",\"pending\"]", literal.query.in_predicates[0].values_json);
    try std.testing.expect(!literal.query.in_predicates[0].negated);

    try std.testing.expectError(error.UnsupportedSqlShape, lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE status IN ('active', 3)",
        schema,
        &.{},
    ));

    var array_param = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE status IN ($1::text[])",
        schema,
        &.{.{ .json = "[\"active\",\"pending\"]" }},
    );
    defer array_param.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), array_param.query.in_predicates.len);
    try std.testing.expectEqualStrings("[\"active\",\"pending\"]", array_param.query.in_predicates[0].values_json);

    var negated = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE priority NOT IN (1, 2, $1)",
        schema,
        &.{.{ .integer = 3 }},
    );
    defer negated.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), negated.query.in_predicates.len);
    try std.testing.expectEqualStrings("priority", negated.query.in_predicates[0].field);
    try std.testing.expectEqualStrings("[1,2,3]", negated.query.in_predicates[0].values_json);
    try std.testing.expect(negated.query.in_predicates[0].negated);

    try std.testing.expectError(error.UnsupportedSqlShape, lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE priority NOT IN (1, 'bad')",
        schema,
        &.{},
    ));
}

test "postgres sql adapter lowers scalar between predicates" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"priority":{"type":"numeric"},"status":{"type":"keyword"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);

    var ranged = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE priority BETWEEN $1 AND $2 AND status = 'active'",
        schema,
        &.{ .{ .integer = 10 }, .{ .integer = 20 } },
    );
    defer ranged.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 3), ranged.query.predicates.len);
    try std.testing.expectEqualStrings("priority", ranged.query.predicates[0].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.gte, ranged.query.predicates[0].op);
    try std.testing.expectEqualStrings("10", ranged.query.predicates[0].value_json.?);
    try std.testing.expectEqualStrings("priority", ranged.query.predicates[1].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.lte, ranged.query.predicates[1].op);
    try std.testing.expectEqualStrings("20", ranged.query.predicates[1].value_json.?);
    try std.testing.expectEqualStrings("status", ranged.query.predicates[2].field);

    var explicit_asymmetric = try lowerSelectAlloc(
        alloc,
