test "postgres sql adapter lowers null-safe distinct predicates" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"encryption_key_version":{"type":"numeric"},"encrypted_secret":{"type":"keyword"},"email":{"type":"keyword"},"metadata":{"type":"json"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);

    var lowered = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM secrets WHERE \"encryption_key_version\" IS NOT DISTINCT FROM $1 AND \"encrypted_secret\" IS NOT DISTINCT FROM $2",
        schema,
        &.{ .{ .integer = 7 }, .null },
    );
    defer lowered.deinit(alloc);

    try std.testing.expectEqual(@as(usize, 2), lowered.query.predicates.len);
    try std.testing.expectEqualStrings("encryption_key_version", lowered.query.predicates[0].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.is_not_distinct, lowered.query.predicates[0].op);
    try std.testing.expectEqualStrings("7", lowered.query.predicates[0].value_json.?);
    try std.testing.expectEqualStrings("encrypted_secret", lowered.query.predicates[1].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.is_not_distinct, lowered.query.predicates[1].op);
    try std.testing.expectEqualStrings("null", lowered.query.predicates[1].value_json.?);

    var distinct = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM secrets WHERE encrypted_secret IS DISTINCT FROM $1",
        schema,
        &.{.{ .string = "old" }},
    );
    defer distinct.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), distinct.query.predicates.len);
    try std.testing.expectEqualStrings("encrypted_secret", distinct.query.predicates[0].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.is_distinct, distinct.query.predicates[0].op);
    try std.testing.expectEqualStrings("\"old\"", distinct.query.predicates[0].value_json.?);

    var expression_distinct = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM secrets WHERE lower(email) IS NOT DISTINCT FROM $1 AND metadata->>'source' IS DISTINCT FROM 'internal'",
        schema,
        &.{.{ .string = "ada@example.test" }},
    );
    defer expression_distinct.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 0), expression_distinct.query.predicates.len);
    try std.testing.expectEqual(@as(usize, 2), expression_distinct.query.expression_predicates.len);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.lower, expression_distinct.query.expression_predicates[0].lhs.kind);
    try std.testing.expectEqualStrings("email", expression_distinct.query.expression_predicates[0].lhs.operands[0].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.is_not_distinct, expression_distinct.query.expression_predicates[0].op);
    try std.testing.expectEqualStrings("\"ada@example.test\"", expression_distinct.query.expression_predicates[0].rhs[0].value_json);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.json_extract, expression_distinct.query.expression_predicates[1].lhs.kind);
    try std.testing.expectEqualStrings("metadata", expression_distinct.query.expression_predicates[1].lhs.operands[0].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.is_distinct, expression_distinct.query.expression_predicates[1].op);
    try std.testing.expectEqualStrings("\"internal\"", expression_distinct.query.expression_predicates[1].rhs[0].value_json);
}

test "postgres sql adapter lowers scalar or predicates" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"status":{"type":"keyword"},"amount":{"type":"numeric"},"created_at":{"type":"numeric"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
