    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);

    var lowered = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE status = 'closed' OR status = 'open' AND amount > 20 ORDER BY created_at DESC",
        schema,
        &.{},
    );
    defer lowered.deinit(alloc);

    try std.testing.expectEqual(@as(usize, 0), lowered.query.predicates.len);
    try std.testing.expectEqual(@as(usize, 2), lowered.query.or_predicates.len);
    try std.testing.expectEqual(@as(usize, 1), lowered.query.or_predicates[0].predicates.len);
    try std.testing.expectEqualStrings("status", lowered.query.or_predicates[0].predicates[0].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.eq, lowered.query.or_predicates[0].predicates[0].op);
    try std.testing.expectEqualStrings("\"closed\"", lowered.query.or_predicates[0].predicates[0].value_json.?);
    try std.testing.expectEqual(@as(usize, 2), lowered.query.or_predicates[1].predicates.len);
    try std.testing.expectEqualStrings("status", lowered.query.or_predicates[1].predicates[0].field);
    try std.testing.expectEqualStrings("amount", lowered.query.or_predicates[1].predicates[1].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.gt, lowered.query.or_predicates[1].predicates[1].op);
    try std.testing.expectEqualStrings("20", lowered.query.or_predicates[1].predicates[1].value_json.?);
    try std.testing.expectEqual(@as(usize, 1), lowered.query.order_by.len);

    var parenthesized_lowered = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE (status = 'closed') OR (status = 'open' AND amount > 20) ORDER BY created_at DESC",
        schema,
        &.{},
    );
    defer parenthesized_lowered.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 0), parenthesized_lowered.query.predicates.len);
    try std.testing.expectEqual(@as(usize, 2), parenthesized_lowered.query.or_predicates.len);
    try std.testing.expectEqual(@as(usize, 1), parenthesized_lowered.query.or_predicates[0].predicates.len);
    try std.testing.expectEqualStrings("status", parenthesized_lowered.query.or_predicates[0].predicates[0].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.eq, parenthesized_lowered.query.or_predicates[0].predicates[0].op);
    try std.testing.expectEqualStrings("\"closed\"", parenthesized_lowered.query.or_predicates[0].predicates[0].value_json.?);
    try std.testing.expectEqual(@as(usize, 2), parenthesized_lowered.query.or_predicates[1].predicates.len);
    try std.testing.expectEqualStrings("status", parenthesized_lowered.query.or_predicates[1].predicates[0].field);
    try std.testing.expectEqualStrings("amount", parenthesized_lowered.query.or_predicates[1].predicates[1].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.gt, parenthesized_lowered.query.or_predicates[1].predicates[1].op);
    try std.testing.expectEqualStrings("20", parenthesized_lowered.query.or_predicates[1].predicates[1].value_json.?);

    var in_lowered = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE status IN ('closed', 'pending') OR status = 'open' AND amount > 20 ORDER BY created_at DESC",
        schema,
        &.{},
    );
    defer in_lowered.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 0), in_lowered.query.predicates.len);
    try std.testing.expectEqual(@as(usize, 3), in_lowered.query.or_predicates.len);
    try std.testing.expectEqual(@as(usize, 1), in_lowered.query.or_predicates[0].predicates.len);
    try std.testing.expectEqualStrings("status", in_lowered.query.or_predicates[0].predicates[0].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.eq, in_lowered.query.or_predicates[0].predicates[0].op);
    try std.testing.expectEqualStrings("\"closed\"", in_lowered.query.or_predicates[0].predicates[0].value_json.?);
    try std.testing.expectEqual(@as(usize, 1), in_lowered.query.or_predicates[1].predicates.len);
    try std.testing.expectEqualStrings("status", in_lowered.query.or_predicates[1].predicates[0].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.eq, in_lowered.query.or_predicates[1].predicates[0].op);
    try std.testing.expectEqualStrings("\"pending\"", in_lowered.query.or_predicates[1].predicates[0].value_json.?);
    try std.testing.expectEqual(@as(usize, 2), in_lowered.query.or_predicates[2].predicates.len);
    try std.testing.expectEqualStrings("status", in_lowered.query.or_predicates[2].predicates[0].field);
    try std.testing.expectEqualStrings("amount", in_lowered.query.or_predicates[2].predicates[1].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.gt, in_lowered.query.or_predicates[2].predicates[1].op);
    try std.testing.expectEqualStrings("20", in_lowered.query.or_predicates[2].predicates[1].value_json.?);

    var any_lowered = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE status = ANY($1::text[]) OR status = 'open' AND amount > 20 ORDER BY created_at DESC",
        schema,
        &.{.{ .json = "[\"closed\",\"pending\"]" }},
    );
    defer any_lowered.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 0), any_lowered.query.predicates.len);
    try std.testing.expectEqual(@as(usize, 3), any_lowered.query.or_predicates.len);
    try std.testing.expectEqual(@as(usize, 1), any_lowered.query.or_predicates[0].predicates.len);
    try std.testing.expectEqualStrings("status", any_lowered.query.or_predicates[0].predicates[0].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.eq, any_lowered.query.or_predicates[0].predicates[0].op);
    try std.testing.expectEqualStrings("\"closed\"", any_lowered.query.or_predicates[0].predicates[0].value_json.?);
    try std.testing.expectEqualStrings("\"pending\"", any_lowered.query.or_predicates[1].predicates[0].value_json.?);
    try std.testing.expectEqual(@as(usize, 2), any_lowered.query.or_predicates[2].predicates.len);
    try std.testing.expectEqualStrings("amount", any_lowered.query.or_predicates[2].predicates[1].field);

    var inequality_any_lowered = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE status != ANY($1::text[]) AND amount > 20 OR status = 'open' ORDER BY created_at DESC",
        schema,
        &.{.{ .json = "[\"closed\",\"pending\"]" }},
    );
    defer inequality_any_lowered.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 3), inequality_any_lowered.query.or_predicates.len);
    try std.testing.expectEqual(@as(usize, 2), inequality_any_lowered.query.or_predicates[0].predicates.len);
    try std.testing.expectEqualStrings("status", inequality_any_lowered.query.or_predicates[0].predicates[0].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.ne, inequality_any_lowered.query.or_predicates[0].predicates[0].op);
    try std.testing.expectEqualStrings("\"closed\"", inequality_any_lowered.query.or_predicates[0].predicates[0].value_json.?);
    try std.testing.expectEqualStrings("amount", inequality_any_lowered.query.or_predicates[0].predicates[1].field);
    try std.testing.expectEqual(@as(usize, 2), inequality_any_lowered.query.or_predicates[1].predicates.len);
    try std.testing.expectEqualStrings("\"pending\"", inequality_any_lowered.query.or_predicates[1].predicates[0].value_json.?);
    try std.testing.expectEqual(@as(usize, 1), inequality_any_lowered.query.or_predicates[2].predicates.len);
    try std.testing.expectEqualStrings("status", inequality_any_lowered.query.or_predicates[2].predicates[0].field);

    var inequality_some_lowered = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE status <> SOME($1::text[]) OR status = 'open' ORDER BY created_at DESC",
        schema,
        &.{.{ .json = "[\"closed\",\"pending\"]" }},
    );
    defer inequality_some_lowered.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 3), inequality_some_lowered.query.or_predicates.len);
    try std.testing.expectEqual(@as(usize, 1), inequality_some_lowered.query.or_predicates[0].predicates.len);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.ne, inequality_some_lowered.query.or_predicates[0].predicates[0].op);
    try std.testing.expectEqualStrings("\"closed\"", inequality_some_lowered.query.or_predicates[0].predicates[0].value_json.?);
    try std.testing.expectEqualStrings("\"pending\"", inequality_some_lowered.query.or_predicates[1].predicates[0].value_json.?);

    var all_lowered = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE status = ALL($1::text[]) OR status <> ALL($2::text[]) ORDER BY created_at DESC",
        schema,
        &.{ .{ .json = "[\"closed\",\"closed\"]" }, .{ .json = "[\"archived\",\"disabled\"]" } },
    );
    defer all_lowered.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 2), all_lowered.query.or_predicates.len);
    try std.testing.expectEqual(@as(usize, 2), all_lowered.query.or_predicates[0].predicates.len);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.eq, all_lowered.query.or_predicates[0].predicates[0].op);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.eq, all_lowered.query.or_predicates[0].predicates[1].op);
    try std.testing.expectEqual(@as(usize, 2), all_lowered.query.or_predicates[1].predicates.len);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.ne, all_lowered.query.or_predicates[1].predicates[0].op);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.ne, all_lowered.query.or_predicates[1].predicates[1].op);

    var not_in_lowered = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE status NOT IN ('closed', 'pending') AND amount > 20 OR status = 'open'",
        schema,
        &.{},
    );
    defer not_in_lowered.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 2), not_in_lowered.query.or_predicates.len);
    try std.testing.expectEqual(@as(usize, 3), not_in_lowered.query.or_predicates[0].predicates.len);
    try std.testing.expectEqualStrings("status", not_in_lowered.query.or_predicates[0].predicates[0].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.ne, not_in_lowered.query.or_predicates[0].predicates[0].op);
    try std.testing.expectEqualStrings("\"closed\"", not_in_lowered.query.or_predicates[0].predicates[0].value_json.?);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.ne, not_in_lowered.query.or_predicates[0].predicates[1].op);
    try std.testing.expectEqualStrings("\"pending\"", not_in_lowered.query.or_predicates[0].predicates[1].value_json.?);
    try std.testing.expectEqualStrings("amount", not_in_lowered.query.or_predicates[0].predicates[2].field);
    try std.testing.expectEqual(@as(usize, 1), not_in_lowered.query.or_predicates[1].predicates.len);

    try std.testing.expectError(error.UnsupportedSqlShape, lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE status NOT IN ('closed', NULL) OR status = 'open'",
        schema,
        &.{},
    ));
}

test "postgres sql adapter lowers scalar not predicate groups" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"status":{"type":"keyword"},"amount":{"type":"numeric"},"created_at":{"type":"numeric"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);

    var lowered = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE NOT (status = 'closed' AND amount > 20) AND created_at >= 10",
        schema,
        &.{},
    );
    defer lowered.deinit(alloc);

    try std.testing.expectEqual(@as(usize, 1), lowered.query.predicates.len);
    try std.testing.expectEqualStrings("created_at", lowered.query.predicates[0].field);
    try std.testing.expectEqual(@as(usize, 1), lowered.query.not_predicates.len);
    try std.testing.expectEqual(@as(usize, 2), lowered.query.not_predicates[0].predicates.len);
    try std.testing.expectEqualStrings("status", lowered.query.not_predicates[0].predicates[0].field);
    try std.testing.expectEqualStrings("amount", lowered.query.not_predicates[0].predicates[1].field);

    var not_or = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE NOT (status = 'closed' OR status = 'pending' AND amount > 20) AND created_at >= 10",
        schema,
        &.{},
    );
    defer not_or.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), not_or.query.predicates.len);
    try std.testing.expectEqualStrings("created_at", not_or.query.predicates[0].field);
    try std.testing.expectEqual(@as(usize, 2), not_or.query.not_predicates.len);
    try std.testing.expectEqual(@as(usize, 1), not_or.query.not_predicates[0].predicates.len);
    try std.testing.expectEqualStrings("status", not_or.query.not_predicates[0].predicates[0].field);
    try std.testing.expectEqualStrings("\"closed\"", not_or.query.not_predicates[0].predicates[0].value_json.?);
    try std.testing.expectEqual(@as(usize, 2), not_or.query.not_predicates[1].predicates.len);
    try std.testing.expectEqualStrings("status", not_or.query.not_predicates[1].predicates[0].field);
    try std.testing.expectEqualStrings("\"pending\"", not_or.query.not_predicates[1].predicates[0].value_json.?);
    try std.testing.expectEqualStrings("amount", not_or.query.not_predicates[1].predicates[1].field);
}

test "postgres sql adapter lowers null-test order expressions" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"expires_at":{"type":"numeric"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);

    var lowered = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM jobs ORDER BY (expires_at IS NULL), expires_at ASC, id ASC LIMIT 5",
        schema,
        &.{},
    );
    defer lowered.deinit(alloc);

    try std.testing.expectEqual(@as(usize, 3), lowered.query.order_by.len);
    try std.testing.expectEqualStrings("expires_at", lowered.query.order_by[0].field);
    try std.testing.expectEqual(db_mod.types.RelationalRowsQueryOrderNullTest.is_null, lowered.query.order_by[0].null_test.?);
    try std.testing.expectEqual(db_mod.types.RelationalRowsQueryOrderDirection.asc, lowered.query.order_by[0].direction);
    try std.testing.expectEqualStrings("expires_at", lowered.query.order_by[1].field);
    try std.testing.expect(lowered.query.order_by[1].null_test == null);
    try std.testing.expectEqualStrings("id", lowered.query.order_by[2].field);
    try std.testing.expectEqual(@as(u32, 5), lowered.query.limit.?);

    var explicit_nulls = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM jobs ORDER BY expires_at DESC NULLS LAST, id ASC NULLS FIRST LIMIT 5",
        schema,
        &.{},
    );
    defer explicit_nulls.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 4), explicit_nulls.query.order_by.len);
    try std.testing.expectEqualStrings("expires_at", explicit_nulls.query.order_by[0].field);
    try std.testing.expectEqual(db_mod.types.RelationalRowsQueryOrderNullTest.is_null, explicit_nulls.query.order_by[0].null_test.?);
    try std.testing.expectEqual(db_mod.types.RelationalRowsQueryOrderDirection.asc, explicit_nulls.query.order_by[0].direction);
    try std.testing.expectEqualStrings("expires_at", explicit_nulls.query.order_by[1].field);
    try std.testing.expect(explicit_nulls.query.order_by[1].null_test == null);
    try std.testing.expectEqual(db_mod.types.RelationalRowsQueryOrderDirection.desc, explicit_nulls.query.order_by[1].direction);
    try std.testing.expectEqualStrings("id", explicit_nulls.query.order_by[2].field);
    try std.testing.expectEqual(db_mod.types.RelationalRowsQueryOrderNullTest.is_null, explicit_nulls.query.order_by[2].null_test.?);
    try std.testing.expectEqual(db_mod.types.RelationalRowsQueryOrderDirection.desc, explicit_nulls.query.order_by[2].direction);
    try std.testing.expectEqualStrings("id", explicit_nulls.query.order_by[3].field);
    try std.testing.expectEqual(db_mod.types.RelationalRowsQueryOrderDirection.asc, explicit_nulls.query.order_by[3].direction);
}

