    try std.testing.expectEqualStrings("status", lowered.aggregate.order_by[2].field);
    try std.testing.expectEqual(db_mod.types.RelationalRowsQueryOrderNullTest.is_null, lowered.aggregate.order_by[2].null_test.?);
