    try std.testing.expectError(error.UnsupportedSqlShape, lowerAggregateAlloc(
        alloc,
        "SELECT customer, COUNT(*) FILTER (WHERE array_length(tags, 1) = ANY($1)) AS bad_tag_bucket FROM usage_records GROUP BY customer",
        schema,
        &.{.{ .json = "[1,\"bad\"]" }},
    ));
}

