    try std.testing.expectEqualStrings("enabled", lowered.query.expressions[0].expression.operands[0].field);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.bool_not, lowered.query.expressions[0].expression.operands[1].kind);
