    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.eq, expression_is_true.query.expression_predicates[0].op);
    try std.testing.expectEqualStrings("true", expression_is_true.query.expression_predicates[0].rhs[0].value_json);

    var expression_is_not_false = try lowerSelectAlloc(
        alloc,
