    try std.testing.expectEqual(@as(usize, 0), expression_is_not_false.query.expression_predicates.len);
    try std.testing.expectEqual(@as(usize, 2), expression_is_not_false.query.expression_or_predicates.len);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.bool_and, expression_is_not_false.query.expression_or_predicates[0].conditions[0].lhs.kind);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.ne, expression_is_not_false.query.expression_or_predicates[0].conditions[0].op);
    try std.testing.expectEqualStrings("false", expression_is_not_false.query.expression_or_predicates[0].conditions[0].rhs[0].value_json);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.bool_and, expression_is_not_false.query.expression_or_predicates[1].conditions[0].lhs.kind);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.is_null, expression_is_not_false.query.expression_or_predicates[1].conditions[0].op);
    try std.testing.expectEqual(@as(usize, 0), expression_is_not_false.query.expression_or_predicates[1].conditions[0].rhs.len);

    var expression_is_unknown = try lowerSelectAlloc(
