    try std.testing.expectEqual(@as(usize, 1), expression_is_unknown.query.expression_predicates.len);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.starts_with, expression_is_unknown.query.expression_predicates[0].lhs.kind);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.is_null, expression_is_unknown.query.expression_predicates[0].op);
    try std.testing.expectEqual(@as(usize, 0), expression_is_unknown.query.expression_predicates[0].rhs.len);

    var expression_postfix_notnull = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM users WHERE lower(status) NOTNULL ORDER BY id",
        schema,
        &.{},
    );
    defer expression_postfix_notnull.deinit(alloc);
