    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.is_not_null, expression_postfix_notnull.query.expression_predicates[0].op);
    try std.testing.expectEqual(@as(usize, 0), expression_postfix_notnull.query.expression_predicates[0].rhs.len);

    try std.testing.expectError(error.InvalidSqlCatalog, lowerSelectAlloc(
        alloc,
        "SELECT enabled AND status AS bad FROM users",
