test "postgres sql adapter lowers qualified single table select outputs" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"tenant_id":{"type":"keyword"},"status":{"type":"keyword"},"created_at":{"type":"numeric"},"metadata":{"type":"json"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);

    var lowered = try lowerSelectAlloc(
        alloc,
        "SELECT u.id, u.metadata->>'source' AS source, lower(u.status) AS status_key FROM usage_records AS u WHERE u.status = $1 ORDER BY u.created_at DESC LIMIT 5",
        schema,
        &.{.{ .string = "open" }},
    );
    defer lowered.deinit(alloc);

    try std.testing.expectEqualStrings("usage_records", lowered.table_name);
    try std.testing.expectEqual(@as(usize, 1), lowered.query.select.len);
    try std.testing.expectEqualStrings("id", lowered.query.select[0]);
    try std.testing.expectEqual(@as(usize, 2), lowered.query.expressions.len);
    try std.testing.expectEqualStrings("source", lowered.query.expressions[0].output);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.json_extract, lowered.query.expressions[0].expression.kind);
    try std.testing.expectEqualStrings("metadata", lowered.query.expressions[0].expression.operands[0].field);
    try std.testing.expectEqualStrings("status_key", lowered.query.expressions[1].output);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.lower, lowered.query.expressions[1].expression.kind);
    try std.testing.expectEqualStrings("status", lowered.query.expressions[1].expression.operands[0].field);
    try std.testing.expectEqual(@as(usize, 1), lowered.query.predicates.len);
    try std.testing.expectEqualStrings("status", lowered.query.predicates[0].field);
    try std.testing.expectEqual(@as(usize, 1), lowered.query.order_by.len);
    try std.testing.expectEqualStrings("created_at", lowered.query.order_by[0].field);

    var distinct = try lowerSelectAlloc(
        alloc,
        "SELECT DISTINCT ON (u.tenant_id) u.tenant_id, u.id FROM usage_records AS u ORDER BY u.tenant_id ASC, u.created_at DESC LIMIT 5",
        schema,
        &.{},
    );
    defer distinct.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), distinct.query.distinct_on_expressions.len);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.field, distinct.query.distinct_on_expressions[0].kind);
    try std.testing.expectEqualStrings("tenant_id", distinct.query.distinct_on_expressions[0].field);
    try std.testing.expectEqual(@as(usize, 2), distinct.query.select.len);
    try std.testing.expectEqualStrings("tenant_id", distinct.query.select[0]);
    try std.testing.expectEqualStrings("id", distinct.query.select[1]);
    try std.testing.expectEqualStrings("tenant_id", distinct.query.order_by[0].field);

    var expression_distinct = try lowerSelectAlloc(
        alloc,
        "SELECT DISTINCT ON (lower(u.status)) u.id, lower(u.status) AS status_key FROM usage_records AS u ORDER BY lower(u.status) ASC, u.created_at DESC LIMIT 5",
        schema,
        &.{},
    );
    defer expression_distinct.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), expression_distinct.query.distinct_on_expressions.len);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.lower, expression_distinct.query.distinct_on_expressions[0].kind);
    try std.testing.expectEqual(@as(usize, 2), expression_distinct.query.order_by.len);
    try std.testing.expect(expression_distinct.query.order_by[0].expression != null);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.lower, expression_distinct.query.order_by[0].expression.?.kind);
    try std.testing.expectEqual(@as(u32, 5), expression_distinct.query.limit.?);
}

