    try std.testing.expectEqual(@as(usize, 1), lowered_precision.query.expressions.len);
    try std.testing.expectEqualStrings("planned_at_ns", lowered_precision.query.expressions[0].output);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.now, lowered_precision.query.expressions[0].expression.kind);
    const bound_precision_now = try std.fmt.parseInt(u64, lowered_precision.query.expressions[0].expression.value_json, 10);
    try std.testing.expect(bound_precision_now > 0);

    var lowered_current_date = try lowerSelectAlloc(
        alloc,
        "SELECT CURRENT_DATE AS planned_day_ns FROM users WHERE id = $1",
        schema,
        &.{.{ .string = "u1" }},
    );
    defer lowered_current_date.deinit(alloc);

    try std.testing.expectEqual(@as(usize, 1), lowered_current_date.query.expressions.len);
    try std.testing.expectEqualStrings("planned_day_ns", lowered_current_date.query.expressions[0].output);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.date_trunc, lowered_current_date.query.expressions[0].expression.kind);
    try std.testing.expectEqual(@as(usize, 2), lowered_current_date.query.expressions[0].expression.operands.len);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.now, lowered_current_date.query.expressions[0].expression.operands[1].kind);

    var lowered_typed_literal = try lowerSelectAlloc(
        alloc,
        "SELECT TIMESTAMPTZ '2025-01-01T01:30:00+01:30' AS planned_at_ns FROM users WHERE id = $1",
        schema,
        &.{.{ .string = "u1" }},
    );
    defer lowered_typed_literal.deinit(alloc);

    try std.testing.expectEqual(@as(usize, 1), lowered_typed_literal.query.expressions.len);
    try std.testing.expectEqualStrings("planned_at_ns", lowered_typed_literal.query.expressions[0].output);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.value, lowered_typed_literal.query.expressions[0].expression.kind);
    try std.testing.expectEqualStrings("1735689600000000000", lowered_typed_literal.query.expressions[0].expression.value_json);
}

