    try std.testing.expectEqualStrings("tax", lowered.query.expressions[0].expression.operands[0].operands[1].operands[0].field);
    try std.testing.expectEqualStrings("rate", lowered.query.expressions[0].expression.operands[0].operands[1].operands[1].field);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.div, lowered.query.expressions[0].expression.operands[1].kind);
    try std.testing.expectEqualStrings("discount", lowered.query.expressions[0].expression.operands[1].operands[0].field);
    try std.testing.expectEqualStrings("divisor", lowered.query.expressions[0].expression.operands[1].operands[1].field);
    try std.testing.expectEqual(@as(usize, 1), lowered.query.predicates.len);
    try std.testing.expectEqualStrings("id", lowered.query.predicates[0].field);

    var lowered_mod = try lowerSelectAlloc(
        alloc,
        "SELECT amount % divisor AS amount_remainder FROM invoices WHERE id = $1",
        schema,
        &.{.{ .string = "inv1" }},
    );
    defer lowered_mod.deinit(alloc);

    try std.testing.expectEqual(@as(usize, 1), lowered_mod.query.expressions.len);
    try std.testing.expectEqualStrings("amount_remainder", lowered_mod.query.expressions[0].output);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.mod, lowered_mod.query.expressions[0].expression.kind);
    try std.testing.expectEqualStrings("amount", lowered_mod.query.expressions[0].expression.operands[0].field);
    try std.testing.expectEqualStrings("divisor", lowered_mod.query.expressions[0].expression.operands[1].field);

    var lowered_mod_function = try lowerSelectAlloc(
        alloc,
        "SELECT MOD(amount + tax, divisor) AS amount_remainder FROM invoices WHERE id = $1",
        schema,
        &.{.{ .string = "inv1" }},
    );
    defer lowered_mod_function.deinit(alloc);

    try std.testing.expectEqual(@as(usize, 1), lowered_mod_function.query.expressions.len);
    try std.testing.expectEqualStrings("amount_remainder", lowered_mod_function.query.expressions[0].output);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.mod, lowered_mod_function.query.expressions[0].expression.kind);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.add, lowered_mod_function.query.expressions[0].expression.operands[0].kind);
    try std.testing.expectEqualStrings("divisor", lowered_mod_function.query.expressions[0].expression.operands[1].field);

    try std.testing.expectError(error.InvalidSqlCatalog, lowerSelectAlloc(
        alloc,
        "SELECT amount + id AS bad FROM invoices WHERE id = $1",
        schema,
        &.{.{ .string = "inv1" }},
    ));
}

test "postgres sql adapter lowers interval arithmetic into expression AST" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"created_at_ns":{"type":"datetime"},"amount":{"type":"numeric"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
