    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.add, lowered.query.expressions[0].expression.kind);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.field, lowered.query.expressions[0].expression.operands[0].kind);
    try std.testing.expectEqualStrings("created_at_ns", lowered.query.expressions[0].expression.operands[0].field);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.interval_ns, lowered.query.expressions[0].expression.operands[1].kind);
    try std.testing.expectEqualStrings("5400000000000", lowered.query.expressions[0].expression.operands[1].operands[0].value_json);
    try std.testing.expectEqual(@as(usize, 1), lowered.query.expression_predicates.len);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.add, lowered.query.expression_predicates[0].lhs.kind);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.interval_ns, lowered.query.expression_predicates[0].lhs.operands[1].kind);
    try std.testing.expectEqualStrings("3600000000000", lowered.query.expression_predicates[0].lhs.operands[1].operands[0].value_json);
    try std.testing.expectEqual(@as(usize, 1), lowered.query.order_by.len);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.sub, lowered.query.order_by[0].expression.?.kind);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.interval_ns, lowered.query.order_by[0].expression.?.operands[1].kind);
    try std.testing.expectEqualStrings("604800000000000", lowered.query.order_by[0].expression.?.operands[1].operands[0].value_json);

    var calendar = try lowerSelectAlloc(
        alloc,
        "SELECT created_at_ns + INTERVAL '1 month' AS next_cycle FROM invoices WHERE id = $1",
        schema,
        &.{.{ .string = "inv1" }},
    );
    defer calendar.deinit(alloc);

    try std.testing.expectEqual(@as(usize, 1), calendar.query.expressions.len);
    try std.testing.expectEqualStrings("next_cycle", calendar.query.expressions[0].output);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.add, calendar.query.expressions[0].expression.kind);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.interval_months, calendar.query.expressions[0].expression.operands[1].kind);
    try std.testing.expectEqualStrings("1", calendar.query.expressions[0].expression.operands[1].operands[0].value_json);

    var yearly = try lowerSelectAlloc(
        alloc,
        "SELECT created_at_ns - INTERVAL '1 year' AS prior_cycle FROM invoices WHERE id = $1",
        schema,
        &.{.{ .string = "inv1" }},
    );
    defer yearly.deinit(alloc);

    try std.testing.expectEqual(@as(usize, 1), yearly.query.expressions.len);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.sub, yearly.query.expressions[0].expression.kind);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.interval_months, yearly.query.expressions[0].expression.operands[1].kind);
    try std.testing.expectEqualStrings("12", yearly.query.expressions[0].expression.operands[1].operands[0].value_json);

    var mixed = try lowerSelectAlloc(
        alloc,
        "SELECT created_at_ns + INTERVAL '1 month 1 day' AS next_cycle_plus_day FROM invoices WHERE id = $1",
        schema,
        &.{.{ .string = "inv1" }},
    );
    defer mixed.deinit(alloc);

    try std.testing.expectEqual(@as(usize, 1), mixed.query.expressions.len);
    try std.testing.expectEqualStrings("next_cycle_plus_day", mixed.query.expressions[0].output);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.add, mixed.query.expressions[0].expression.kind);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.add, mixed.query.expressions[0].expression.operands[0].kind);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.interval_months, mixed.query.expressions[0].expression.operands[0].operands[1].kind);
    try std.testing.expectEqualStrings("1", mixed.query.expressions[0].expression.operands[0].operands[1].operands[0].value_json);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.interval_ns, mixed.query.expressions[0].expression.operands[1].kind);
    try std.testing.expectEqualStrings("86400000000000", mixed.query.expressions[0].expression.operands[1].operands[0].value_json);

    var zero_months = try lowerSelectAlloc(
        alloc,
        "SELECT created_at_ns + INTERVAL '0 months 1 day' AS next_day FROM invoices WHERE id = $1",
