    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.add, zero_months.query.expressions[0].expression.kind);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.interval_ns, zero_months.query.expressions[0].expression.operands[1].kind);
    try std.testing.expectEqualStrings("86400000000000", zero_months.query.expressions[0].expression.operands[1].operands[0].value_json);
}

test "postgres sql adapter lowers case projection into expression AST" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"email":{"type":"keyword"},"status":{"type":"keyword"},"amount":{"type":"numeric"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);

    var lowered = try lowerSelectAlloc(
        alloc,
        "SELECT CASE WHEN email IS NULL THEN 'missing' WHEN email = 'blocked@example.test' THEN 'blocked' ELSE lower(status) END AS email_bucket FROM usage_records WHERE id = $1",
        schema,
        &.{.{ .string = "u1" }},
    );
    defer lowered.deinit(alloc);

    try std.testing.expectEqual(@as(usize, 0), lowered.query.select.len);
    try std.testing.expectEqual(@as(usize, 1), lowered.query.expressions.len);
    try std.testing.expectEqualStrings("email_bucket", lowered.query.expressions[0].output);
    const expression = lowered.query.expressions[0].expression;
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.case, expression.kind);
    try std.testing.expectEqual(@as(usize, 2), expression.case_branches.len);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.is_null, expression.case_branches[0].when.op);
    try std.testing.expectEqual(@as(usize, 0), expression.case_branches[0].when.rhs.len);
    try std.testing.expectEqualStrings("\"missing\"", expression.case_branches[0].then.value_json);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.eq, expression.case_branches[1].when.op);
    try std.testing.expectEqualStrings("email", expression.case_branches[1].when.lhs.field);
    try std.testing.expectEqual(@as(usize, 1), expression.case_branches[1].when.rhs.len);
    try std.testing.expectEqualStrings("\"blocked@example.test\"", expression.case_branches[1].when.rhs[0].value_json);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.lower, expression.case_else[0].kind);
    try std.testing.expectEqualStrings("status", expression.case_else[0].operands[0].field);

    var null_test_projection = try lowerSelectAlloc(
        alloc,
        "SELECT (email IS NULL) AS email_missing, (email IS NOT NULL) AS email_present FROM usage_records WHERE id = $1",
        schema,
        &.{.{ .string = "u1" }},
    );
    defer null_test_projection.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 0), null_test_projection.query.select.len);
    try std.testing.expectEqual(@as(usize, 2), null_test_projection.query.expressions.len);
    try std.testing.expectEqualStrings("email_missing", null_test_projection.query.expressions[0].output);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.case, null_test_projection.query.expressions[0].expression.kind);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.is_null, null_test_projection.query.expressions[0].expression.case_branches[0].when.op);
    try std.testing.expectEqualStrings("email", null_test_projection.query.expressions[0].expression.case_branches[0].when.lhs.field);
    try std.testing.expectEqualStrings("true", null_test_projection.query.expressions[0].expression.case_branches[0].then.value_json);
    try std.testing.expectEqualStrings("false", null_test_projection.query.expressions[0].expression.case_else[0].value_json);
    try std.testing.expectEqualStrings("email_present", null_test_projection.query.expressions[1].output);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.case, null_test_projection.query.expressions[1].expression.kind);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.is_not_null, null_test_projection.query.expressions[1].expression.case_branches[0].when.op);

    var null_first_case = try lowerSelectAlloc(
        alloc,
        "SELECT CASE WHEN email IS NULL THEN NULL ELSE email END AS maybe_email FROM usage_records WHERE id = $1",
        schema,
        &.{.{ .string = "u1" }},
    );
    defer null_first_case.deinit(alloc);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.case, null_first_case.query.expressions[0].expression.kind);

    try std.testing.expectError(error.UnsupportedSqlShape, lowerSelectAlloc(
        alloc,
        "SELECT CASE WHEN email = 3 THEN 'bad' ELSE status END AS bad_case FROM usage_records WHERE id = $1",
        schema,
        &.{.{ .string = "u1" }},
    ));
    try std.testing.expectError(error.UnsupportedSqlShape, lowerSelectAlloc(
        alloc,
        "SELECT CASE WHEN email IS NULL THEN 'missing' ELSE amount END AS bad_case FROM usage_records WHERE id = $1",
        schema,
        &.{.{ .string = "u1" }},
    ));
}

test "postgres sql adapter lowers cast projection into expression AST" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"amount":{"type":"numeric"},"active":{"type":"boolean"},"created_at_ns":{"type":"numeric"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);

    var lowered = try lowerSelectAlloc(
        alloc,
        "SELECT CAST(id AS text) AS id_text, CAST(amount AS text) AS amount_text, CAST(active AS bool) AS active_bool, CAST(amount + 1 AS text) AS next_amount_text, CAST(created_at_ns AS timestamptz) AS created_at FROM usage_records WHERE id = $1",
        schema,
        &.{.{ .string = "u1" }},
    );
    defer lowered.deinit(alloc);

    try std.testing.expectEqual(@as(usize, 0), lowered.query.select.len);
    try std.testing.expectEqual(@as(usize, 5), lowered.query.expressions.len);
    try std.testing.expectEqualStrings("id_text", lowered.query.expressions[0].output);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.cast, lowered.query.expressions[0].expression.kind);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionCastType.text, lowered.query.expressions[0].expression.cast_type.?);
    try std.testing.expectEqualStrings("id", lowered.query.expressions[0].expression.operands[0].field);
    try std.testing.expectEqualStrings("amount_text", lowered.query.expressions[1].output);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionCastType.text, lowered.query.expressions[1].expression.cast_type.?);
    try std.testing.expectEqualStrings("active_bool", lowered.query.expressions[2].output);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionCastType.bool, lowered.query.expressions[2].expression.cast_type.?);
    try std.testing.expectEqualStrings("next_amount_text", lowered.query.expressions[3].output);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.cast, lowered.query.expressions[3].expression.kind);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionCastType.text, lowered.query.expressions[3].expression.cast_type.?);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.add, lowered.query.expressions[3].expression.operands[0].kind);
    try std.testing.expectEqualStrings("created_at", lowered.query.expressions[4].output);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionCastType.datetime, lowered.query.expressions[4].expression.cast_type.?);
    try std.testing.expectEqualStrings("created_at_ns", lowered.query.expressions[4].expression.operands[0].field);

    try std.testing.expectError(error.UnsupportedSqlShape, lowerSelectAlloc(
        alloc,
        "SELECT CAST(id AS uuid) AS bad FROM usage_records WHERE id = $1",
        schema,
        &.{.{ .string = "u1" }},
    ));
}

