test "postgres sql adapter lowers insert values returning into row batch" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"status":{"type":"keyword"},"amount":{"type":"numeric"},"metadata":{"type":"json"},"tags":{"type":"array","items":{"type":"keyword"}}},"required":["id","status"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);
    const source_schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"archive_id":{"type":"keyword"},"archive_status":{"type":"keyword"},"archive_amount":{"type":"numeric"}},"required":["archive_id"],"additionalProperties":false}}},"primary_key":{"columns":["archive_id"]}}
    ;
    var parsed_source = try schema_api.parseValidatedTableSchema(alloc, source_schema_json);
    defer parsed_source.deinit(alloc);
    const source_schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed_source);
    defer runtime_schema.freeSchema(alloc, source_schema);

    var lowered = try lowerInsertAlloc(
        alloc,
        "INSERT INTO usage_records (id, status, metadata) VALUES ($1, $2, $3::jsonb) RETURNING id, status, metadata",
        schema,
        &.{
            .{ .string = "u1" },
            .{ .string = "pending" },
            .{ .json = "{\"source\":\"autoscale_delta\"}" },
        },
    );
    defer lowered.deinit(alloc);

    try std.testing.expectEqualStrings("usage_records", lowered.table_name);
    try std.testing.expectEqual(@as(u32, 1), lowered.batch.inserted);
    try std.testing.expectEqual(@as(usize, 1), lowered.batch.writes.len);
    try std.testing.expectEqual(@as(usize, 1), lowered.batch.returning_rows.len);

    var returned = try std.json.parseFromSlice(std.json.Value, alloc, lowered.batch.returning_rows[0], .{});
    defer returned.deinit();
    try std.testing.expectEqualStrings("u1", returned.value.object.get("id").?.string);
    try std.testing.expectEqualStrings("pending", returned.value.object.get("status").?.string);
    try std.testing.expectEqualStrings("autoscale_delta", returned.value.object.get("metadata").?.object.get("source").?.string);

    var multi_row = try lowerInsertAlloc(
        alloc,
        "INSERT INTO usage_records (id, status, amount) VALUES ('u_multi_1', 'open', 1), ('u_multi_2', 'closed', 2) RETURNING id, status",
        schema,
        &.{},
    );
    defer multi_row.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 2), multi_row.batch.inserted);
    try std.testing.expectEqual(@as(usize, 2), multi_row.batch.writes.len);
    try std.testing.expectEqual(@as(usize, 2), multi_row.batch.returning_rows.len);
    var multi_first = try std.json.parseFromSlice(std.json.Value, alloc, multi_row.batch.returning_rows[0], .{});
    defer multi_first.deinit();
    var multi_second = try std.json.parseFromSlice(std.json.Value, alloc, multi_row.batch.returning_rows[1], .{});
    defer multi_second.deinit();
    try std.testing.expectEqualStrings("u_multi_1", multi_first.value.object.get("id").?.string);
    try std.testing.expectEqualStrings("open", multi_first.value.object.get("status").?.string);
    try std.testing.expectEqualStrings("u_multi_2", multi_second.value.object.get("id").?.string);
    try std.testing.expectEqualStrings("closed", multi_second.value.object.get("status").?.string);

    var multi_conflict_resolver = TestPrimaryResolver{ .row_json = "{\"id\":\"u_multi_1\",\"status\":\"open\"}", .version = 1 };
    var multi_conflict = try lowerInsertWithResolverAlloc(
        alloc,
        "INSERT INTO usage_records (id, status) VALUES ('u_multi_1', 'open'), ('u_multi_2', 'closed') ON CONFLICT (id) DO NOTHING RETURNING id",
        schema,
        &.{},
        multi_conflict_resolver.resolver(),
    );
    defer multi_conflict.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 0), multi_conflict.batch.inserted);
    try std.testing.expectEqual(@as(usize, 0), multi_conflict.batch.writes.len);
    try std.testing.expectEqual(@as(usize, 0), multi_conflict.batch.returning_rows.len);

    var insert_source_plan = try lowerWritePlanAlloc(
        alloc,
        "INSERT INTO usage_records (id, status, amount) SELECT id, status, amount FROM usage_records WHERE status = 'ready' ON CONFLICT (id) DO NOTHING RETURNING id, status",
        schema,
        &.{},
        .{ .unique_resolver = multi_conflict_resolver.resolver() },
    );
    defer insert_source_plan.deinit(alloc);
    switch (insert_source_plan) {
        .insert_source => |insert_source| {
            try std.testing.expectEqualStrings("usage_records", insert_source.table_name);
            try std.testing.expectEqualStrings("usage_records", insert_source.insert_source.req.source_table);
            try std.testing.expectEqual(@as(usize, 3), insert_source.insert_source.req.assignments.len);
            try std.testing.expectEqual(@as(usize, 1), insert_source.insert_source.req.source.predicates.len);
            try std.testing.expectEqual(@as(usize, 2), insert_source.insert_source.req.returning.len);
            try std.testing.expect(insert_source.insert_source.req.on_conflict != null);
            try std.testing.expectEqual(db_mod.types.RelationalRowsConflictAction.nothing, insert_source.insert_source.req.on_conflict.?.action);
        },
        else => return error.TestUnexpectedResult,
    }

    var insert_source_computed_pattern_plan = try lowerWritePlanAlloc(
        alloc,
        "INSERT INTO usage_records (id, status, amount) SELECT id, status, amount FROM usage_records WHERE lower(status) LIKE ANY(ARRAY['ready%', 'queued%']) RETURNING id, status",
        schema,
        &.{},
        .{ .unique_resolver = multi_conflict_resolver.resolver() },
    );
    defer insert_source_computed_pattern_plan.deinit(alloc);
    switch (insert_source_computed_pattern_plan) {
        .insert_source => |insert_source| {
            try std.testing.expectEqualStrings("usage_records", insert_source.table_name);
            try std.testing.expectEqualStrings("usage_records", insert_source.insert_source.req.source_table);
            try std.testing.expectEqual(@as(usize, 3), insert_source.insert_source.req.assignments.len);
            try std.testing.expectEqual(@as(usize, 1), insert_source.insert_source.req.source.expression_predicates.len);
            try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.bool_or, insert_source.insert_source.req.source.expression_predicates[0].lhs.kind);
            try std.testing.expectEqual(@as(usize, 2), insert_source.insert_source.req.source.expression_predicates[0].lhs.operands.len);
            try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.like, insert_source.insert_source.req.source.expression_predicates[0].lhs.operands[0].kind);
            try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.lower, insert_source.insert_source.req.source.expression_predicates[0].lhs.operands[0].operands[0].kind);
            try std.testing.expectEqualStrings("\"ready%\"", insert_source.insert_source.req.source.expression_predicates[0].lhs.operands[0].operands[1].value_json);
            try std.testing.expectEqual(@as(usize, 2), insert_source.insert_source.req.returning.len);
        },
        else => return error.TestUnexpectedResult,
    }

    var insert_source_expression_or_plan = try lowerWritePlanAlloc(
        alloc,
        "INSERT INTO usage_records (id, status, amount) SELECT id, status, amount FROM usage_records WHERE array_length(tags, 1) NOT BETWEEN 1 AND 3 RETURNING id, status",
        schema,
        &.{},
        .{ .unique_resolver = multi_conflict_resolver.resolver() },
    );
    defer insert_source_expression_or_plan.deinit(alloc);
