fn expressionOrderCount(order_by: []const db_mod.types.RelationalRowsQueryOrder) usize {
    var count: usize = 0;
    for (order_by) |order| {
        if (order.expression != null) count += 1;
    }
    return count;
}

fn aggregateFilterExpressionCount(aggregations: []const db_mod.types.RelationalRowsAggregateSpec) usize {
    var count: usize = 0;
    for (aggregations) |aggregation| {
        count += aggregation.filter_expressions.len;
    }
    return count;
}

fn aggregateFilterExpressionArrayCount(aggregations: []const db_mod.types.RelationalRowsAggregateSpec) usize {
    var count: usize = 0;
    for (aggregations) |aggregation| {
        count += aggregation.filter_expression_array_contains.len;
    }
    return count;
}

fn aggregateFilterJsonAccessCount(aggregations: []const db_mod.types.RelationalRowsAggregateSpec) usize {
    var count: usize = 0;
    for (aggregations) |aggregation| {
        count += aggregation.filter_json_contains.len +
            aggregation.filter_json_path_eq.len +
            aggregation.filter_json_path_exists.len;
    }
    return count;
}

fn aggregateFilterStructuredAccessCount(aggregations: []const db_mod.types.RelationalRowsAggregateSpec) usize {
    var count: usize = 0;
    for (aggregations) |aggregation| {
        count += aggregation.filter_array_any.len +
            aggregation.filter_array_contains.len +
            aggregation.filter_array_eq.len +
            aggregation.filter_in_predicates.len +
            aggregation.filter_text_patterns.len;
    }
    return count;
}

fn aggregateFilterGroupCount(aggregations: []const db_mod.types.RelationalRowsAggregateSpec) usize {
    var count: usize = 0;
    for (aggregations) |aggregation| {
        count += aggregation.filter_any.len + aggregation.filter_not.len;
    }
    return count;
}

fn aggregateInputExpressionCount(aggregations: []const db_mod.types.RelationalRowsAggregateSpec) usize {
    var count: usize = 0;
    for (aggregations) |aggregation| {
        if (aggregation.expression != null) count += 1;
    }
    return count;
}

fn windowValueExpressionCount(windows: []const db_mod.types.RelationalRowsWindowSpec) usize {
    var count: usize = 0;
    for (windows) |window| {
        if (window.value_expression != null) count += 1;
    }
    return count;
}

fn windowDefaultCount(windows: []const db_mod.types.RelationalRowsWindowSpec) usize {
    var count: usize = 0;
    for (windows) |window| {
        if (window.default_json.len > 0) count += 1;
    }
    return count;
}

fn windowFilterPredicateCount(windows: []const db_mod.types.RelationalRowsWindowSpec) usize {
    var count: usize = 0;
    for (windows) |window| {
        count += window.filter_predicates.len;
    }
    return count;
}

fn windowFilterExpressionCount(windows: []const db_mod.types.RelationalRowsWindowSpec) usize {
    var count: usize = 0;
    for (windows) |window| {
        count += window.filter_expressions.len;
    }
    return count;
}

fn windowFilterAccessCount(windows: []const db_mod.types.RelationalRowsWindowSpec) usize {
    var count: usize = 0;
    for (windows) |window| {
        count += window.filter_array_any.len +
            window.filter_array_contains.len +
            window.filter_array_eq.len +
            window.filter_in_predicates.len +
            window.filter_json_contains.len +
            window.filter_json_path_eq.len +
            window.filter_json_path_exists.len +
            window.filter_text_patterns.len +
            window.filter_expression_array_contains.len;
    }
    return count;
}

fn windowFilterGroupCount(windows: []const db_mod.types.RelationalRowsWindowSpec) usize {
    var count: usize = 0;
    for (windows) |window| {
        count += window.filter_any.len + window.filter_not.len;
    }
    return count;
}

fn windowFrameSignature(windows: []const db_mod.types.RelationalRowsWindowSpec) u64 {
    var signature: u64 = 0;
    for (windows) |window| {
        if (window.frame) |frame| {
            signature = signature *% 131 +% 17;
            signature = signature *% 131 +% windowFrameUnitCode(frame.unit);
            signature = signature *% 131 +% windowFrameBoundCode(frame.start);
            signature = signature *% 131 +% @as(u64, @intCast(frame.start_offset));
            signature = signature *% 131 +% windowFrameBoundCode(frame.end);
            signature = signature *% 131 +% @as(u64, @intCast(frame.end_offset));
        } else {
            signature = signature *% 131;
        }
    }
    return signature;
}

fn windowFrameUnitCode(unit: db_mod.types.RelationalRowsWindowFrameUnit) u64 {
    return switch (unit) {
        .rows => 1,
        .range => 2,
    };
}

fn windowFrameBoundCode(bound: db_mod.types.RelationalRowsWindowFrameBound) u64 {
    return switch (bound) {
        .unbounded_preceding => 1,
        .offset_preceding => 2,
        .current_row => 3,
        .offset_following => 4,
        .unbounded_following => 5,
    };
}

fn sqlRowClaimForClause(clause: SqlRowClaimClause) db_mod.types.RowClaimRequest {
    return .{
        .mode = clause.mode,
        .wait_policy = clause.wait_policy,
        .skip_locked = clause.wait_policy == .skip_locked,
    };
}

fn setSqlRowClaimClause(claim: *db_mod.types.RowClaimRequest, clause: SqlRowClaimClause) void {
    claim.mode = clause.mode;
    claim.wait_policy = clause.wait_policy;
    claim.skip_locked = clause.wait_policy == .skip_locked;
}

fn sqlRowClaimModeName(mode: db_mod.types.RowClaimMode) []const u8 {
    return switch (mode) {
        .for_update => "for_update",
        .for_no_key_update => "for_no_key_update",
    };
}

fn sqlRowClaimWaitPolicyName(wait_policy: db_mod.types.RowClaimWaitPolicy) []const u8 {
    return switch (wait_policy) {
        .wait => "wait",
        .nowait => "nowait",
        .skip_locked => "skip_locked",
    };
}

fn sqlRowClaimFingerprintName(claim: db_mod.types.RowClaimRequest) []const u8 {
    return switch (claim.mode) {
        .for_update => switch (claim.effectiveWaitPolicy()) {
            .wait => "locked",
            .nowait => "nowait",
            .skip_locked => "skip_locked",
        },
        .for_no_key_update => switch (claim.effectiveWaitPolicy()) {
            .wait => "no_key_update",
            .nowait => "no_key_update_nowait",
            .skip_locked => "no_key_update_skip_locked",
        },
    };
}

fn queryFingerprintAlloc(alloc: std.mem.Allocator, family: []const u8, table_name: []const u8, query: db_mod.types.RelationalRowsQueryRequest, ctes: usize) ![]u8 {
    const claim = if (query.row_claim) |claim_value| sqlRowClaimFingerprintName(claim_value) else "none";
    const order_expr = expressionOrderCount(query.order_by);
    const distinct_on_count = query.distinct_on.len + query.distinct_on_expressions.len;
    if (distinct_on_count > 0) {
        return try std.fmt.allocPrint(
            alloc,
            "{s}:table={s}:ctes={d}:pred={d}:expr_pred={d}:json_eq={d}:or={d}:not={d}:select={d}:expr={d}:alias={d}:distinct_on={d}:order={d}:order_expr={d}:limit={d}:claim={s}",
            .{
                family,
                table_name,
                ctes,
                query.predicates.len,
                query.expression_predicates.len,
                query.json_path_eq.len,
                query.or_predicates.len,
                query.not_predicates.len,
                query.select.len,
                query.expressions.len,
                query.field_aliases.len,
                distinct_on_count,
                query.order_by.len,
                order_expr,
                appParityLimitValue(query.limit),
                claim,
            },
        );
    }
    if (ctes > 0 or query.source_cte.len > 0) {
        return try std.fmt.allocPrint(
            alloc,
            "{s}:table={s}:ctes={d}:source_cte={d}:pred={d}:array_any={d}:expr_pred={d}:expr_or={d}:expr_not={d}:expr_array={d}:json_eq={d}:or={d}:not={d}:select={d}:expr={d}:alias={d}:order={d}:order_expr={d}:limit={d}:claim={s}",
            .{
                family,
                table_name,
                ctes,
                @as(u8, if (query.source_cte.len > 0) 1 else 0),
                query.predicates.len,
                query.array_any.len,
                query.expression_predicates.len,
                query.expression_or_predicates.len,
                query.expression_not_predicates.len,
                query.expression_array_contains.len,
                query.json_path_eq.len,
                query.or_predicates.len,
                query.not_predicates.len,
                query.select.len,
                query.expressions.len,
                query.field_aliases.len,
                query.order_by.len,
                order_expr,
                appParityLimitValue(query.limit),
                claim,
            },
        );
    }
    if (query.array_any.len > 0 or query.expression_or_predicates.len > 0 or query.expression_not_predicates.len > 0) {
        return try std.fmt.allocPrint(
            alloc,
            "{s}:table={s}:ctes={d}:pred={d}:array_any={d}:expr_pred={d}:expr_or={d}:expr_not={d}:expr_array={d}:json_eq={d}:or={d}:not={d}:select={d}:expr={d}:alias={d}:order={d}:order_expr={d}:limit={d}:claim={s}",
            .{
                family,
                table_name,
                ctes,
                query.predicates.len,
                query.array_any.len,
                query.expression_predicates.len,
                query.expression_or_predicates.len,
                query.expression_not_predicates.len,
                query.expression_array_contains.len,
                query.json_path_eq.len,
                query.or_predicates.len,
                query.not_predicates.len,
                query.select.len,
                query.expressions.len,
                query.field_aliases.len,
                query.order_by.len,
                order_expr,
                appParityLimitValue(query.limit),
                claim,
            },
        );
    }
    if (query.expression_array_contains.len > 0) {
        if (query.limit) |limit| {
            return try std.fmt.allocPrint(
                alloc,
                "{s}:table={s}:ctes={d}:pred={d}:expr_pred={d}:expr_array={d}:json_eq={d}:or={d}:not={d}:select={d}:expr={d}:alias={d}:order={d}:order_expr={d}:limit={d}:claim={s}",
                .{
                    family,
                    table_name,
                    ctes,
                    query.predicates.len,
                    query.expression_predicates.len,
                    query.expression_array_contains.len,
                    query.json_path_eq.len,
                    query.or_predicates.len,
                    query.not_predicates.len,
                    query.select.len,
                    query.expressions.len,
                    query.field_aliases.len,
                    query.order_by.len,
                    order_expr,
                    limit,
                    claim,
                },
            );
        }
        return try std.fmt.allocPrint(
            alloc,
            "{s}:table={s}:ctes={d}:pred={d}:expr_pred={d}:expr_array={d}:json_eq={d}:or={d}:not={d}:select={d}:expr={d}:alias={d}:order={d}:order_expr={d}:limit=none:claim={s}",
            .{
                family,
                table_name,
                ctes,
                query.predicates.len,
                query.expression_predicates.len,
                query.expression_array_contains.len,
                query.json_path_eq.len,
                query.or_predicates.len,
                query.not_predicates.len,
                query.select.len,
                query.expressions.len,
                query.field_aliases.len,
                query.order_by.len,
                order_expr,
                claim,
            },
        );
    }
    if (query.text_patterns.len > 0) {
        if (query.limit) |limit| {
            return try std.fmt.allocPrint(
                alloc,
                "{s}:table={s}:ctes={d}:pred={d}:expr_pred={d}:json_eq={d}:text_pattern={d}:or={d}:not={d}:select={d}:expr={d}:alias={d}:order={d}:order_expr={d}:limit={d}:claim={s}",
                .{
                    family,
                    table_name,
                    ctes,
                    query.predicates.len,
                    query.expression_predicates.len,
                    query.json_path_eq.len,
                    query.text_patterns.len,
                    query.or_predicates.len,
                    query.not_predicates.len,
                    query.select.len,
                    query.expressions.len,
                    query.field_aliases.len,
                    query.order_by.len,
                    order_expr,
                    limit,
                    claim,
                },
            );
        }
        return try std.fmt.allocPrint(
            alloc,
            "{s}:table={s}:ctes={d}:pred={d}:expr_pred={d}:json_eq={d}:text_pattern={d}:or={d}:not={d}:select={d}:expr={d}:alias={d}:order={d}:order_expr={d}:limit=none:claim={s}",
            .{
                family,
                table_name,
                ctes,
                query.predicates.len,
                query.expression_predicates.len,
                query.json_path_eq.len,
                query.text_patterns.len,
                query.or_predicates.len,
                query.not_predicates.len,
                query.select.len,
                query.expressions.len,
                query.field_aliases.len,
                query.order_by.len,
                order_expr,
                claim,
            },
        );
    }
    if (query.limit) |limit| {
        return try std.fmt.allocPrint(
            alloc,
            "{s}:table={s}:ctes={d}:pred={d}:expr_pred={d}:json_eq={d}:or={d}:not={d}:select={d}:expr={d}:alias={d}:order={d}:order_expr={d}:limit={d}:claim={s}",
            .{
                family,
                table_name,
                ctes,
                query.predicates.len,
                query.expression_predicates.len,
                query.json_path_eq.len,
                query.or_predicates.len,
                query.not_predicates.len,
                query.select.len,
                query.expressions.len,
                query.field_aliases.len,
                query.order_by.len,
                order_expr,
                limit,
                claim,
            },
        );
    }
    return try std.fmt.allocPrint(
        alloc,
        "{s}:table={s}:ctes={d}:pred={d}:expr_pred={d}:json_eq={d}:or={d}:not={d}:select={d}:expr={d}:alias={d}:order={d}:order_expr={d}:limit=none:claim={s}",
        .{
            family,
            table_name,
            ctes,
            query.predicates.len,
            query.expression_predicates.len,
            query.json_path_eq.len,
            query.or_predicates.len,
            query.not_predicates.len,
            query.select.len,
            query.expressions.len,
            query.field_aliases.len,
            query.order_by.len,
            order_expr,
            claim,
        },
    );
}

fn appendQueryAccessPathFingerprintAlloc(
    alloc: std.mem.Allocator,
    owned_base: []u8,
    query: db_mod.types.RelationalRowsQueryRequest,
) ![]u8 {
    var fingerprint = owned_base;
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "in", query.in_predicates.len);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "json_contains", query.json_contains.len);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "json_exists", query.json_path_exists.len);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "array_contains", query.array_contains.len);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "array_eq", query.array_eq.len);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "access_or", query.access_or_predicates.len);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "access_not", query.access_not_predicates.len);
    return fingerprint;
}

