            ),
            .advisory_lock => |lock| try std.fmt.allocPrint(
                alloc,
                "ddl:transaction_control:kind=advisory_lock:action={s}:keys={d}",
                .{ @tagName(lock.action), if (lock.key2 != null) @as(usize, 2) else @as(usize, 1) },
