                try expectOptionalUsize(summary.operations, prepare.parameter_count);
            },
            .execute => |execute| {
                try std.testing.expectEqual(AppParityDdlTag.execute_statement, expected);
                try expectOptionalTableName(summary.table_name, execute.statement_name);
                try expectOptionalUsize(summary.operations, execute.argument_count);
            },
            .deallocate => |deallocate| {
                try std.testing.expectEqual(AppParityDdlTag.deallocate_statement, expected);
                if (deallocate.statement_name) |name| {
                    try expectOptionalTableName(summary.table_name, name);
                }
            },
        },
        .cursor_portal => |plan| switch (plan) {
            .declare => |declare| {
                try std.testing.expectEqual(AppParityDdlTag.declare_cursor, expected);
                try expectOptionalTableName(summary.table_name, declare.portal_name);
            },
            .fetch => |fetch| {
                try std.testing.expectEqual(AppParityDdlTag.fetch_cursor, expected);
                try expectOptionalTableName(summary.table_name, fetch.portal_name);
                if (fetch.count) |count| try expectOptionalUsize(summary.operations, @intCast(count));
            },
            .close => |close| {
                try std.testing.expectEqual(AppParityDdlTag.close_cursor, expected);
                if (close.portal_name) |portal| {
                    try expectOptionalTableName(summary.table_name, portal);
                }
            },
        },
        .savepoint_transaction => |plan| switch (plan) {
            .savepoint => |savepoint| {
                try std.testing.expectEqual(AppParityDdlTag.savepoint_transaction, expected);
                try expectOptionalTableName(summary.table_name, savepoint.savepoint_name);
            },
            .release => |release| {
                try std.testing.expectEqual(AppParityDdlTag.release_savepoint, expected);
                try expectOptionalTableName(summary.table_name, release.savepoint_name);
            },
            .rollback_to => |rollback| {
                try std.testing.expectEqual(AppParityDdlTag.rollback_to_savepoint, expected);
                try expectOptionalTableName(summary.table_name, rollback.savepoint_name);
            },
        },
        .comment_metadata => |plan| {
            try std.testing.expectEqual(AppParityDdlTag.comment_metadata, expected);
            try expectOptionalTableName(summary.table_name, plan.object_name);
            if (summary.operations) |expected_operations| {
                try std.testing.expectEqual(expected_operations, @intFromBool(plan.comment_json != null));
            }
        },
        .transaction_control => |plan| switch (plan) {
            .table_lock => |lock| {
                try std.testing.expectEqual(AppParityDdlTag.table_lock, expected);
                if (summary.table_name) |table_name| try std.testing.expectEqualStrings(table_name, lock.table_names[0]);
                try expectOptionalUsize(summary.operations, lock.table_names.len);
            },
            .constraint_mode => |constraints| {
                try std.testing.expectEqual(AppParityDdlTag.constraint_mode, expected);
                try expectOptionalUsize(summary.operations, constraints.constraint_names.len + @as(usize, @intFromBool(constraints.all)));
            },
            .transaction_mode => |transaction| {
                try std.testing.expectEqual(AppParityDdlTag.transaction_mode, expected);
                const option_count: usize = @as(usize, @intFromBool(transaction.isolation_level != null)) +
                    @as(usize, @intFromBool(transaction.access_mode != null)) +
                    @as(usize, @intFromBool(transaction.deferrable != null));
                try expectOptionalUsize(summary.operations, option_count);
            },
            .advisory_lock => |lock| {
                try std.testing.expectEqual(AppParityDdlTag.advisory_lock, expected);
                try expectOptionalUsize(summary.operations, if (lock.key2 != null) @as(usize, 2) else @as(usize, 1));
            },
        },
        .create_index => |plan| {
            try std.testing.expectEqual(AppParityDdlTag.create_index, expected);
            try expectOptionalTableName(summary.table_name, plan.table_name);
            try expectOptionalUsize(summary.select, plan.columns.len + plan.expressions.len + appParityGeneratedExpressionCount(plan));
            try expectOptionalUsize(summary.predicates, plan.where.len);
        },
        .drop_index => |plan| {
            try std.testing.expectEqual(AppParityDdlTag.drop_index, expected);
            _ = plan;
        },
        .drop_table => |plan| {
            try std.testing.expectEqual(AppParityDdlTag.drop_table, expected);
            try expectOptionalTableName(summary.table_name, plan.table_name);
        },
        .alter_table => |plan| {
            try std.testing.expectEqual(AppParityDdlTag.alter_table, expected);
            try expectOptionalTableName(summary.table_name, plan.table_name);
            try expectOptionalUsize(summary.operations, plan.operations.len);
        },
        .create_update_policy => |plan| {
            try std.testing.expectEqual(AppParityDdlTag.create_update_policy, expected);
            try expectOptionalTableName(summary.table_name, plan.table_name);
        },
    }
}

fn sourceQueryUsesExtendedPredicates(query: db_mod.types.RelationalRowsQueryRequest) bool {
    return query.array_any.len > 0 or
        query.in_predicates.len > 0 or
        query.json_contains.len > 0 or
        query.json_path_exists.len > 0 or
        query.array_contains.len > 0 or
        query.array_eq.len > 0 or
        query.access_or_predicates.len > 0 or
        query.access_not_predicates.len > 0 or
        query.expression_predicates.len > 0 or
        query.expression_or_predicates.len > 0 or
        query.expression_not_predicates.len > 0 or
        query.expression_array_contains.len > 0;
}

fn expressionAssignmentComputedCount(assignments: []const db_mod.types.RelationalRowsExpressionAssignment) usize {
    var count: usize = 0;
    for (assignments) |assignment| {
        if (assignment.expression.kind != .field) count += 1;
    }
    return count;
}

fn insertSourceFingerprintAlloc(alloc: std.mem.Allocator, lowered: LoweredInsertSource) ![]u8 {
    const req = lowered.insert_source.req;
    const source = req.source;
    const conflict = req.on_conflict != null;
    const base = if (sourceQueryUsesExtendedPredicates(source))
        try std.fmt.allocPrint(
            alloc,
            "insert_source:table={s}:source_table={s}:source_pred={d}:source_array_any={d}:source_expr_pred={d}:source_expr_or={d}:source_expr_not={d}:source_expr_array={d}:source_order={d}:source_limit={d}:assignments={d}:conflict={d}:returning={d}:returning_expr={d}:returning_all={d}",
            .{
                lowered.table_name,
                req.source_table,
                source.predicates.len,
                source.array_any.len,
                source.expression_predicates.len,
                source.expression_or_predicates.len,
                source.expression_not_predicates.len,
                source.expression_array_contains.len,
                source.order_by.len,
                appParityLimitValue(source.limit),
                req.assignments.len,
                appParityBoolValue(conflict),
                req.returning.len,
                req.returning_expressions.len,
                appParityBoolValue(req.returning_all),
            },
        )
    else
        try std.fmt.allocPrint(
            alloc,
            "insert_source:table={s}:source_table={s}:source_pred={d}:source_order={d}:source_limit={d}:assignments={d}:conflict={d}:returning={d}:returning_expr={d}:returning_all={d}",
            .{
                lowered.table_name,
                req.source_table,
                source.predicates.len,
                source.order_by.len,
                appParityLimitValue(source.limit),
                req.assignments.len,
                appParityBoolValue(conflict),
                req.returning.len,
                req.returning_expressions.len,
                appParityBoolValue(req.returning_all),
            },
        );
    const with_in = try appendNonZeroUsizeFingerprintAlloc(alloc, base, "source_in", source.in_predicates.len);
    const with_or = try appendNonZeroUsizeFingerprintAlloc(alloc, with_in, "source_or", source.or_predicates.len);
    const with_not = try appendNonZeroUsizeFingerprintAlloc(alloc, with_or, "source_not", source.not_predicates.len);
    const with_access = try appendSourceQueryAccessOnlyFingerprintAlloc(alloc, with_not, source);
    const with_assignment_expr = try appendNonZeroUsizeFingerprintAlloc(alloc, with_access, "assignment_expr", expressionAssignmentComputedCount(req.assignments));
    const with_ctes = try appendNonZeroUsizeFingerprintAlloc(alloc, with_assignment_expr, "ctes", lowered.ctes.len);
    const with_source_cte = try appendTrueBoolFingerprintAlloc(alloc, with_ctes, "source_cte", source.source_cte.len != 0);
    const with_cte_access = try appendCteAccessPathFingerprintAlloc(alloc, with_source_cte, lowered.ctes);
    if (req.on_conflict) |on_conflict| {
        const with_action = try std.fmt.allocPrint(alloc, "{s}:conflict_action={s}", .{ with_cte_access, conflictActionName(on_conflict.action) });
        alloc.free(with_cte_access);
        const with_ops = try appendNonZeroUsizeFingerprintAlloc(alloc, with_action, "conflict_ops", on_conflict.operations.len);
        const with_patch = try appendNonZeroUsizeFingerprintAlloc(alloc, with_ops, "conflict_patch_expr", on_conflict.patch_expressions.len);
        const with_increment = try appendNonZeroUsizeFingerprintAlloc(alloc, with_patch, "conflict_increment_expr", on_conflict.increment_expressions.len);
        const with_json_set = try appendNonZeroUsizeFingerprintAlloc(alloc, with_increment, "conflict_json_set_expr", on_conflict.json_set_expressions.len);
        const with_where = try appendTrueBoolFingerprintAlloc(alloc, with_json_set, "conflict_where_expr", on_conflict.where_expression != null);
        const with_where_all = try appendNonZeroUsizeFingerprintAlloc(alloc, with_where, "conflict_where_exprs", on_conflict.where_expressions.len);
        const with_where_any = try appendNonZeroUsizeFingerprintAlloc(alloc, with_where_all, "conflict_where_any", on_conflict.where_any.len);
        return try appendNonZeroUsizeFingerprintAlloc(alloc, with_where_any, "conflict_where_not", on_conflict.where_not.len);
    }
    return with_cte_access;
}

fn conflictActionName(action: db_mod.types.RelationalRowsConflictAction) []const u8 {
    return switch (action) {
        .update => "update",
        .nothing => "nothing",
    };
}

fn updateSourceFingerprintAlloc(alloc: std.mem.Allocator, lowered: LoweredMutationSource) ![]u8 {
    const source = lowered.mutation.req.source;
