fn truncateSourceFingerprintAlloc(alloc: std.mem.Allocator, lowered: LoweredMutationSource) ![]u8 {
    const delete_fingerprint = try deleteSourceFingerprintAlloc(alloc, lowered);
    defer alloc.free(delete_fingerprint);
    const delete_prefix = "delete_source:";
    if (!std.mem.startsWith(u8, delete_fingerprint, delete_prefix)) return error.TestUnexpectedResult;
    return try std.fmt.allocPrint(alloc, "truncate_source:{s}", .{delete_fingerprint[delete_prefix.len..]});
}

fn joinedSourceFingerprintAlloc(
    alloc: std.mem.Allocator,
    prefix: []const u8,
    lowered: LoweredJoinedMutationSource,
) ![]u8 {
    const req = lowered.mutation.req;
    const claim = if (req.join.left.row_claim) |claim_value| sqlRowClaimFingerprintName(claim_value) else "none";
    const source_table = if (req.source_table.len > 0) req.source_table else lowered.source_table_name;
    var fingerprint = try std.fmt.allocPrint(
        alloc,
        "{s}:target={s}:source={s}:left_pred={d}:right_pred={d}:on={d}:order={d}:limit={d}:claim={s}:source_assignments={d}:ops={d}:returning={d}:returning_expr={d}:returning_all={d}",
        .{
            prefix,
            lowered.target_table_name,
            source_table,
            req.join.left.predicates.len,
            req.join.right.predicates.len,
            req.join.on.len,
            req.join.order_by.len,
            appParityLimitValue(req.join.limit),
            claim,
            req.source_assignments.len,
            req.operations.len,
            req.returning.len,
            req.returning_expressions.len,
            appParityBoolValue(req.returning_all),
        },
    );
    fingerprint = try appendNonZeroU32FingerprintAlloc(alloc, fingerprint, "offset", req.join.offset);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "patch_expr", req.patch_expressions.len);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "increment_expr", req.increment_expressions.len);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "json_set_expr", req.json_set_expressions.len);
    fingerprint = try appendNamedNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "left", "expr_pred", req.join.left.expression_predicates.len);
    fingerprint = try appendNamedNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "left", "expr_or", req.join.left.expression_or_predicates.len);
    fingerprint = try appendNamedNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "left", "expr_not", req.join.left.expression_not_predicates.len);
    fingerprint = try appendNamedNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "left", "expr_array", req.join.left.expression_array_contains.len);
    fingerprint = try appendNamedNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "right", "expr_pred", req.join.right.expression_predicates.len);
    fingerprint = try appendNamedNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "right", "expr_or", req.join.right.expression_or_predicates.len);
    fingerprint = try appendNamedNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "right", "expr_not", req.join.right.expression_not_predicates.len);
    fingerprint = try appendNamedNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "right", "expr_array", req.join.right.expression_array_contains.len);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "on_expr_pred", req.join.on_expression_predicates.len);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "on_expr_or", req.join.on_expression_or_predicates.len);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "on_expr_not", req.join.on_expression_not_predicates.len);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "on_expr_array", req.join.on_expression_array_contains.len);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "match_expr_pred", req.match_expression_predicates.len);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "match_expr_or", req.match_expression_or_predicates.len);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "match_expr_not", req.match_expression_not_predicates.len);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "match_expr_array", req.match_expression_array_contains.len);
    fingerprint = try appendTrueBoolFingerprintAlloc(alloc, fingerprint, "rewrite", req.rewrite_identity);
    fingerprint = try appendSideQueryAccessOnlyFingerprintAlloc(alloc, fingerprint, "left", req.join.left);
    fingerprint = try appendSideQueryAccessOnlyFingerprintAlloc(alloc, fingerprint, "right", req.join.right);
    return fingerprint;
}

fn aggregateFingerprintAlloc(alloc: std.mem.Allocator, lowered: LoweredAggregate) ![]u8 {
    const source = lowered.aggregate.source;
    const filter_groups = aggregateFilterGroupCount(lowered.aggregate.aggregations);
    const filter_expression_arrays = aggregateFilterExpressionArrayCount(lowered.aggregate.aggregations);
    const filter_json_access = aggregateFilterJsonAccessCount(lowered.aggregate.aggregations);
    const filter_structured_access = aggregateFilterStructuredAccessCount(lowered.aggregate.aggregations);
    if (lowered.aggregate.having_expressions.len > 0 or lowered.aggregate.having_any.len > 0 or lowered.aggregate.having_not.len > 0 or filter_groups > 0 or filter_expression_arrays > 0 or filter_json_access > 0 or filter_structured_access > 0) {
        const base = try std.fmt.allocPrint(
            alloc,
            "aggregate:table={s}:source_pred={d}:source_array_any={d}:source_expr_pred={d}:source_expr_or={d}:source_expr_not={d}:source_expr_array={d}:source_json_eq={d}:group={d}:group_expr={d}:aggs={d}:agg_expr={d}:filter_expr={d}:filter_groups={d}:having={d}:having_expr={d}:having_any={d}:having_not={d}:order={d}:limit={d}",
            .{
                lowered.table_name,
                source.predicates.len,
                source.array_any.len,
                source.expression_predicates.len,
                source.expression_or_predicates.len,
                source.expression_not_predicates.len,
                source.expression_array_contains.len,
                source.json_path_eq.len,
                lowered.aggregate.group_by.len,
                lowered.aggregate.group_expressions.len,
                lowered.aggregate.aggregations.len,
                aggregateInputExpressionCount(lowered.aggregate.aggregations),
                aggregateFilterExpressionCount(lowered.aggregate.aggregations),
                filter_groups,
                lowered.aggregate.having_predicates.len,
                lowered.aggregate.having_expressions.len,
                lowered.aggregate.having_any.len,
                lowered.aggregate.having_not.len,
                lowered.aggregate.order_by.len,
                appParityLimitValue(lowered.aggregate.limit),
            },
        );
        var fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, base, "order_expr", expressionOrderCount(lowered.aggregate.order_by));
        fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "filter_expr_array", filter_expression_arrays);
        fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "filter_json", filter_json_access);
        fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "filter_structured", filter_structured_access);
        fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "source_in", source.in_predicates.len);
        return try appendSourceQueryAccessOnlyFingerprintAlloc(alloc, fingerprint, source);
    }
    if (sourceQueryUsesExtendedPredicates(source)) {
        const base = try std.fmt.allocPrint(
            alloc,
            "aggregate:table={s}:source_pred={d}:source_array_any={d}:source_expr_pred={d}:source_expr_or={d}:source_expr_not={d}:source_expr_array={d}:source_json_eq={d}:group={d}:group_expr={d}:aggs={d}:agg_expr={d}:filter_expr={d}:having={d}:order={d}:limit={d}",
            .{
                lowered.table_name,
                source.predicates.len,
                source.array_any.len,
                source.expression_predicates.len,
                source.expression_or_predicates.len,
                source.expression_not_predicates.len,
                source.expression_array_contains.len,
                source.json_path_eq.len,
                lowered.aggregate.group_by.len,
                lowered.aggregate.group_expressions.len,
                lowered.aggregate.aggregations.len,
                aggregateInputExpressionCount(lowered.aggregate.aggregations),
                aggregateFilterExpressionCount(lowered.aggregate.aggregations),
                lowered.aggregate.having_predicates.len,
                lowered.aggregate.order_by.len,
                appParityLimitValue(lowered.aggregate.limit),
            },
        );
        var fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, base, "order_expr", expressionOrderCount(lowered.aggregate.order_by));
        fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "source_in", source.in_predicates.len);
        return try appendSourceQueryAccessOnlyFingerprintAlloc(alloc, fingerprint, source);
    }
    const base = try std.fmt.allocPrint(
        alloc,
        "aggregate:table={s}:source_pred={d}:source_json_eq={d}:group={d}:group_expr={d}:aggs={d}:agg_expr={d}:filter_expr={d}:having={d}:order={d}:limit={d}",
        .{
            lowered.table_name,
            source.predicates.len,
            source.json_path_eq.len,
            lowered.aggregate.group_by.len,
            lowered.aggregate.group_expressions.len,
            lowered.aggregate.aggregations.len,
            aggregateInputExpressionCount(lowered.aggregate.aggregations),
            aggregateFilterExpressionCount(lowered.aggregate.aggregations),
            lowered.aggregate.having_predicates.len,
            lowered.aggregate.order_by.len,
            appParityLimitValue(lowered.aggregate.limit),
        },
    );
    var fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, base, "order_expr", expressionOrderCount(lowered.aggregate.order_by));
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "source_in", source.in_predicates.len);
    return try appendSourceQueryAccessOnlyFingerprintAlloc(alloc, fingerprint, source);
}

fn aggregatePlanFingerprintAlloc(alloc: std.mem.Allocator, lowered: LoweredAggregatePlan) ![]u8 {
    const aggregate = LoweredAggregate{
        .table_name = lowered.table_name,
        .aggregate = lowered.plan.aggregate,
    };
    var fingerprint = try aggregateFingerprintAlloc(alloc, aggregate);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "ctes", lowered.plan.ctes.len);
    fingerprint = try appendCteAccessPathFingerprintAlloc(alloc, fingerprint, lowered.plan.ctes);
    return fingerprint;
}

fn joinFingerprintAlloc(alloc: std.mem.Allocator, lowered: LoweredJoin) ![]u8 {
    const left = lowered.join.left;
    const right = lowered.join.right;
    var fingerprint = try std.fmt.allocPrint(
        alloc,
        "join:left={s}:right={s}:left_pred={d}:left_array_any={d}:left_expr_pred={d}:left_expr_or={d}:left_expr_not={d}:left_expr_array={d}:left_json_eq={d}:left_text={d}:right_pred={d}:right_array_any={d}:right_expr_pred={d}:right_expr_or={d}:right_expr_not={d}:right_expr_array={d}:right_json_eq={d}:right_text={d}:on={d}:select={d}:order={d}:order_expr={d}:limit={d}",
        .{
            lowered.left_table_name,
            lowered.right_table_name,
            left.predicates.len,
            left.array_any.len,
            left.expression_predicates.len,
            left.expression_or_predicates.len,
            left.expression_not_predicates.len,
            left.expression_array_contains.len,
            left.json_path_eq.len,
            left.text_patterns.len,
            right.predicates.len,
            right.array_any.len,
            right.expression_predicates.len,
            right.expression_or_predicates.len,
            right.expression_not_predicates.len,
            right.expression_array_contains.len,
            right.json_path_eq.len,
            right.text_patterns.len,
            lowered.join.on.len,
            lowered.join.select.len,
            lowered.join.order_by.len,
            expressionOrderCount(lowered.join.order_by),
            appParityLimitValue(lowered.join.limit),
        },
    );
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "on_expr_pred", lowered.join.on_expression_predicates.len);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "on_expr_or", lowered.join.on_expression_or_predicates.len);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "on_expr_not", lowered.join.on_expression_not_predicates.len);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "on_expr_array", lowered.join.on_expression_array_contains.len);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "match_expr_pred", lowered.join.match_expression_predicates.len);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "match_expr_or", lowered.join.match_expression_or_predicates.len);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "match_expr_not", lowered.join.match_expression_not_predicates.len);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "match_expr_array", lowered.join.match_expression_array_contains.len);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "ctes", lowered.ctes.len);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "left_source_cte", if (lowered.join.left.source_cte.len > 0) 1 else 0);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "right_source_cte", if (lowered.join.right.source_cte.len > 0) 1 else 0);
    fingerprint = try appendSideQueryAccessOnlyFingerprintAlloc(alloc, fingerprint, "left", left);
    fingerprint = try appendSideQueryAccessOnlyFingerprintAlloc(alloc, fingerprint, "right", right);
    return fingerprint;
}

fn lateralFingerprintAlloc(alloc: std.mem.Allocator, lowered: LoweredLateralPlan) ![]u8 {
    const left = lowered.plan.lateral.left;
    const right = lowered.plan.lateral.right;
    var fingerprint = try std.fmt.allocPrint(
        alloc,
        "lateral:left={s}:right={s}:ctes={d}:left_pred={d}:left_array_any={d}:left_expr_pred={d}:left_expr_or={d}:left_expr_not={d}:left_expr_array={d}:left_json_eq={d}:left_text={d}:right_pred={d}:right_array_any={d}:right_expr_pred={d}:right_expr_or={d}:right_expr_not={d}:right_expr_array={d}:right_json_eq={d}:right_text={d}:right_order={d}:right_order_expr={d}:right_limit={d}:corr={d}:select={d}:order={d}:order_expr={d}:limit={d}",
        .{
            lowered.left_table_name,
            lowered.right_table_name,
            lowered.plan.ctes.len,
            left.predicates.len,
            left.array_any.len,
            left.expression_predicates.len,
            left.expression_or_predicates.len,
            left.expression_not_predicates.len,
            left.expression_array_contains.len,
            left.json_path_eq.len,
            left.text_patterns.len,
            right.predicates.len,
            right.array_any.len,
            right.expression_predicates.len,
            right.expression_or_predicates.len,
            right.expression_not_predicates.len,
            right.expression_array_contains.len,
            right.json_path_eq.len,
            right.text_patterns.len,
            right.order_by.len,
            expressionOrderCount(right.order_by),
            appParityLimitValue(right.limit),
            lowered.plan.lateral.correlations.len,
            lowered.plan.lateral.select.len,
            lowered.plan.lateral.order_by.len,
            expressionOrderCount(lowered.plan.lateral.order_by),
            appParityLimitValue(lowered.plan.lateral.limit),
        },
    );
    fingerprint = try appendSideQueryAccessOnlyFingerprintAlloc(alloc, fingerprint, "left", left);
    fingerprint = try appendSideQueryAccessOnlyFingerprintAlloc(alloc, fingerprint, "right", right);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "match_expr_pred", lowered.plan.lateral.match_expression_predicates.len);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "match_expr_or", lowered.plan.lateral.match_expression_or_predicates.len);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "match_expr_not", lowered.plan.lateral.match_expression_not_predicates.len);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "match_expr_array", lowered.plan.lateral.match_expression_array_contains.len);
    return fingerprint;
}

fn readFingerprintWithPrefixAlloc(
    alloc: std.mem.Allocator,
    owned_fingerprint: []u8,
    family: []const u8,
) ![]u8 {
    defer alloc.free(owned_fingerprint);
    return try std.fmt.allocPrint(alloc, "read:{s}:{s}", .{ family, owned_fingerprint });
}

fn relationPopulationFingerprintAlloc(
    alloc: std.mem.Allocator,
    lowered: LoweredRelationPopulationPlan,
) ![]u8 {
    const source = try readPlanFingerprintAlloc(alloc, lowered.source);
    defer alloc.free(source);
    return try std.fmt.allocPrint(
        alloc,
        "relation_population:mode={s}:target={s}:source={s}",
        .{ relationPopulationModeName(lowered.mode), lowered.target_table_name, source },
    );
}

fn relationPopulationModeName(mode: RelationPopulationMode) []const u8 {
    return switch (mode) {
        .create_table_as => "create_table_as",
        .select_into => "select_into",
    };
}

fn mergeMatchedPredicateCount(arms: []const MergeMatchedArm) usize {
    var total: usize = 0;
    for (arms) |arm| total += arm.predicates.len;
    return total;
}

fn mergeMatchedUpdateCount(arms: []const MergeMatchedArm) usize {
    var total: usize = 0;
    for (arms) |arm| total += arm.update.len;
    return total;
}

fn mergeMatchedUpdateExpressionCount(arms: []const MergeMatchedArm) usize {
    var total: usize = 0;
    for (arms) |arm| total += arm.update_expressions.len;
    return total;
}

fn mergeMatchedExpressionPredicateCount(arms: []const MergeMatchedArm) usize {
    var total: usize = 0;
    for (arms) |arm| total += arm.expression_predicates.len;
    return total;
}

fn mergeMatchedExpressionOrPredicateCount(arms: []const MergeMatchedArm) usize {
    var total: usize = 0;
    for (arms) |arm| total += arm.expression_or_predicates.len;
    return total;
}

fn mergeMatchedExpressionNotPredicateCount(arms: []const MergeMatchedArm) usize {
    var total: usize = 0;
    for (arms) |arm| total += arm.expression_not_predicates.len;
    return total;
}

fn mergeMatchedHasDelete(arms: []const MergeMatchedArm) bool {
    for (arms) |arm| if (arm.delete) return true;
    return false;
}

fn mergeMatchedHasDoNothing(arms: []const MergeMatchedArm) bool {
    for (arms) |arm| if (arm.do_nothing) return true;
    return false;
}

fn mergeNotMatchedPredicateCount(arms: []const MergeNotMatchedArm) usize {
    var total: usize = 0;
    for (arms) |arm| total += arm.predicates.len;
    return total;
}

fn mergeNotMatchedInsertCount(arms: []const MergeNotMatchedArm) usize {
    var total: usize = 0;
    for (arms) |arm| total += arm.insert.len;
    return total;
}

fn mergeNotMatchedInsertExpressionCount(arms: []const MergeNotMatchedArm) usize {
    var total: usize = 0;
    for (arms) |arm| total += arm.insert_expressions.len;
    return total;
}

fn mergeNotMatchedExpressionPredicateCount(arms: []const MergeNotMatchedArm) usize {
    var total: usize = 0;
    for (arms) |arm| total += arm.expression_predicates.len;
    return total;
}

fn mergeNotMatchedExpressionOrPredicateCount(arms: []const MergeNotMatchedArm) usize {
    var total: usize = 0;
    for (arms) |arm| total += arm.expression_or_predicates.len;
    return total;
}

fn mergeNotMatchedExpressionNotPredicateCount(arms: []const MergeNotMatchedArm) usize {
    var total: usize = 0;
    for (arms) |arm| total += arm.expression_not_predicates.len;
    return total;
}

fn mergeNotMatchedHasDoNothing(arms: []const MergeNotMatchedArm) bool {
    for (arms) |arm| if (arm.do_nothing) return true;
    return false;
}

fn writePlanFingerprintAlloc(alloc: std.mem.Allocator, lowered: LoweredWritePlan) ![]u8 {
    return switch (lowered) {
        .insert => |insert| blk: {
            const operations = if (insert.batch.transforms.len == 0) 0 else insert.batch.transforms[0].operations.len;
            var fingerprint = try std.fmt.allocPrint(
                alloc,
                "insert:table={s}:writes={d}:transforms={d}:ops={d}:deletes={d}:returning_rows={d}:returning_expr={d}",
                .{
                    insert.table_name,
                    insert.batch.writes.len,
                    insert.batch.transforms.len,
                    operations,
                    insert.batch.deletes.len,
                    insert.batch.returning_rows.len,
                    insert.returning_expression_count,
                },
            );
            fingerprint = try appendTrueBoolFingerprintAlloc(alloc, fingerprint, "returning_all", insert.returning_all);
            fingerprint = try appendTrueBoolFingerprintAlloc(alloc, fingerprint, "conflict_where", insert.conflict_where);
            break :blk fingerprint;
        },
        .insert_source => |insert_source| blk: {
            var fingerprint = try insertSourceFingerprintAlloc(alloc, insert_source);
            fingerprint = try appendNonZeroU32FingerprintAlloc(alloc, fingerprint, "source_offset", insert_source.insert_source.req.source.offset);
            fingerprint = try appendTrueBoolFingerprintAlloc(alloc, fingerprint, "conflict_where", insert_source.conflict_where);
            break :blk fingerprint;
        },
        .update => |update| blk: {
            const operations = if (update.batch.transforms.len == 0) 0 else update.batch.transforms[0].operations.len;
            var fingerprint = try std.fmt.allocPrint(
                alloc,
                "update:table={s}:transforms={d}:ops={d}:returning_rows={d}:returning_expr={d}",
                .{ update.table_name, update.batch.transforms.len, operations, update.batch.returning_rows.len, update.returning_expression_count },
            );
            fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "writes", update.batch.writes.len);
            fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "deletes", update.batch.deletes.len);
            fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "identity_rewrites", update.batch.relational_identity_rewrites.len);
            fingerprint = try appendTrueBoolFingerprintAlloc(alloc, fingerprint, "returning_all", update.returning_all);
            break :blk fingerprint;
        },
        .delete => |delete| blk: {
            var fingerprint = try std.fmt.allocPrint(
                alloc,
                "delete:table={s}:deletes={d}:returning_rows={d}:returning_expr={d}",
                .{ delete.table_name, delete.batch.deletes.len, delete.batch.returning_rows.len, delete.returning_expression_count },
            );
            fingerprint = try appendTrueBoolFingerprintAlloc(alloc, fingerprint, "returning_all", delete.returning_all);
            break :blk fingerprint;
        },
        .update_source => |update_source| blk: {
            var fingerprint = try updateSourceFingerprintAlloc(alloc, update_source);
            fingerprint = try appendNonZeroU32FingerprintAlloc(alloc, fingerprint, "source_offset", update_source.mutation.req.source.offset);
            break :blk fingerprint;
        },
        .delete_source => |delete_source| blk: {
            var fingerprint = try deleteSourceFingerprintAlloc(alloc, delete_source);
            fingerprint = try appendNonZeroU32FingerprintAlloc(alloc, fingerprint, "source_offset", delete_source.mutation.req.source.offset);
            break :blk fingerprint;
        },
        .truncate_source => |truncate_source| blk: {
            var fingerprint = try truncateSourceFingerprintAlloc(alloc, truncate_source);
            fingerprint = try appendNonZeroU32FingerprintAlloc(alloc, fingerprint, "source_offset", truncate_source.mutation.req.source.offset);
            break :blk fingerprint;
        },
        .update_joined_source => |update_joined_source| try joinedSourceFingerprintAlloc(alloc, "update_joined_source", update_joined_source),
        .delete_joined_source => |delete_joined_source| try joinedSourceFingerprintAlloc(alloc, "delete_joined_source", delete_joined_source),
        .merge_mutation => |merge| blk: {
            var fingerprint = try std.fmt.allocPrint(
                alloc,
                "merge_mutation:target={s}:source={s}:match={d}:matched_pred={d}:matched_update={d}:matched_delete={d}:matched_noop={d}:not_matched_pred={d}:not_matched_insert={d}:not_matched_noop={d}:returning={d}:returning_expr={d}:returning_all={d}",
                .{
                    merge.target_table_name,
                    merge.source_table_name,
                    merge.match_fields.len,
                    mergeMatchedPredicateCount(merge.matched_arms),
                    mergeMatchedUpdateCount(merge.matched_arms),
                    appParityBoolValue(mergeMatchedHasDelete(merge.matched_arms)),
                    appParityBoolValue(mergeMatchedHasDoNothing(merge.matched_arms)),
                    mergeNotMatchedPredicateCount(merge.not_matched_arms),
                    mergeNotMatchedInsertCount(merge.not_matched_arms),
                    appParityBoolValue(mergeNotMatchedHasDoNothing(merge.not_matched_arms)),
                    merge.returning.fields.len,
                    merge.returning.expressions.len,
                    appParityBoolValue(merge.returning.returnsAll()),
                },
            );
            fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "matched_update_expr", mergeMatchedUpdateExpressionCount(merge.matched_arms));
            fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "not_matched_insert_expr", mergeNotMatchedInsertExpressionCount(merge.not_matched_arms));
            fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "matched_expr_pred", mergeMatchedExpressionPredicateCount(merge.matched_arms));
            fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "matched_expr_or", mergeMatchedExpressionOrPredicateCount(merge.matched_arms));
            fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "matched_expr_not", mergeMatchedExpressionNotPredicateCount(merge.matched_arms));
            fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "not_matched_expr_pred", mergeNotMatchedExpressionPredicateCount(merge.not_matched_arms));
            fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "not_matched_expr_or", mergeNotMatchedExpressionOrPredicateCount(merge.not_matched_arms));
            fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "not_matched_expr_not", mergeNotMatchedExpressionNotPredicateCount(merge.not_matched_arms));
            fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "matched_arms", if (merge.matched_arms.len > 1) merge.matched_arms.len else 0);
            fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "not_matched_arms", if (merge.not_matched_arms.len > 1) merge.not_matched_arms.len else 0);
            break :blk fingerprint;
        },
    };
}

fn windowFingerprintAlloc(alloc: std.mem.Allocator, lowered: LoweredWindowPlan) ![]u8 {
    var fingerprint = try std.fmt.allocPrint(
        alloc,
        "window:table={s}:ctes={d}:source_cte={d}:source_pred={d}:windows={d}:window_expr={d}:window_default={d}:window_frame_sig={d}:select={d}:order={d}:limit={d}",
        .{
            lowered.table_name,
            lowered.plan.ctes.len,
            @as(u8, if (lowered.plan.window.source.source_cte.len > 0) 1 else 0),
            lowered.plan.window.source.predicates.len,
            lowered.plan.window.windows.len,
            windowValueExpressionCount(lowered.plan.window.windows),
            windowDefaultCount(lowered.plan.window.windows),
            windowFrameSignature(lowered.plan.window.windows),
            lowered.plan.window.select.len,
            lowered.plan.window.order_by.len,
            appParityLimitValue(lowered.plan.window.limit),
        },
    );
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "order_expr", expressionOrderCount(lowered.plan.window.order_by));
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "window_filter", windowFilterPredicateCount(lowered.plan.window.windows));
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "window_filter_expr", windowFilterExpressionCount(lowered.plan.window.windows));
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "window_filter_access", windowFilterAccessCount(lowered.plan.window.windows));
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "window_filter_groups", windowFilterGroupCount(lowered.plan.window.windows));
    fingerprint = try appendSourceQueryAccessPathFingerprintAlloc(alloc, fingerprint, lowered.plan.window.source);
    fingerprint = try appendCteAccessPathFingerprintAlloc(alloc, fingerprint, lowered.plan.ctes);
    fingerprint = try appendNonZeroU32FingerprintAlloc(alloc, fingerprint, "offset", lowered.plan.window.offset);
    return fingerprint;
}

fn readPlanFingerprintAlloc(alloc: std.mem.Allocator, lowered: LoweredReadPlan) ![]u8 {
    return switch (lowered) {
        .query => |query| blk: {
            var fingerprint = try queryFingerprintAlloc(alloc, "query", query.table_name, query.plan.query, query.plan.ctes.len);
            fingerprint = try appendNonZeroU32FingerprintAlloc(alloc, fingerprint, "offset", query.plan.query.offset);
            fingerprint = try appendTrueBoolFingerprintAlloc(alloc, fingerprint, "select_all", query.plan.query.select_all);
            fingerprint = try appendQueryAccessPathFingerprintAlloc(alloc, fingerprint, query.plan.query);
            fingerprint = try appendCteAccessPathFingerprintAlloc(alloc, fingerprint, query.plan.ctes);
            break :blk try readFingerprintWithPrefixAlloc(alloc, fingerprint, "query");
        },
        .aggregate => |aggregate| blk: {
            var fingerprint = try aggregatePlanFingerprintAlloc(alloc, aggregate);
            fingerprint = try appendNonZeroU32FingerprintAlloc(alloc, fingerprint, "offset", aggregate.plan.aggregate.offset);
            break :blk try readFingerprintWithPrefixAlloc(alloc, fingerprint, "aggregate");
        },
        .join => |join| blk: {
            var fingerprint = try joinFingerprintAlloc(alloc, join);
            fingerprint = try appendNonZeroU32FingerprintAlloc(alloc, fingerprint, "offset", join.join.offset);
            break :blk try readFingerprintWithPrefixAlloc(alloc, fingerprint, "join");
        },
        .lateral => |lateral| blk: {
            var fingerprint = try lateralFingerprintAlloc(alloc, lateral);
            fingerprint = try appendNonZeroU32FingerprintAlloc(alloc, fingerprint, "right_offset", lateral.plan.lateral.right.offset);
            fingerprint = try appendNonZeroU32FingerprintAlloc(alloc, fingerprint, "offset", lateral.plan.lateral.offset);
            break :blk try readFingerprintWithPrefixAlloc(alloc, fingerprint, "lateral");
        },
        .window => |window| blk: {
            const fingerprint = try windowFingerprintAlloc(alloc, window);
            break :blk try readFingerprintWithPrefixAlloc(alloc, fingerprint, "window");
        },
    };
}

fn explainPlanFingerprintAlloc(alloc: std.mem.Allocator, lowered: LoweredExplainPlan) ![]u8 {
    var subject_kind: []const u8 = undefined;
    const inner = switch (lowered.subject) {
        .read => |read| blk: {
            subject_kind = "read";
            break :blk try readPlanFingerprintAlloc(alloc, read);
        },
        .write => |write| blk: {
            subject_kind = "write";
            break :blk try writePlanFingerprintAlloc(alloc, write);
        },
    };
    defer alloc.free(inner);
    var fingerprint = try std.fmt.allocPrint(
        alloc,
        "explain:kind={s}:analyze={}:inner={s}",
        .{ subject_kind, lowered.analyze, inner },
    );
    if (lowered.format != .text) {
        fingerprint = try appendStringFingerprintAlloc(
            alloc,
            fingerprint,
            "format",
            explainFormatName(lowered.format),
        );
    }
    if (lowered.verbose) {
        fingerprint = try appendBoolFingerprintAlloc(alloc, fingerprint, "verbose", lowered.verbose);
    }
    if (!lowered.costs) {
        fingerprint = try appendBoolFingerprintAlloc(alloc, fingerprint, "costs", lowered.costs);
    }
    return fingerprint;
}

fn explainFormatName(format: ExplainFormat) []const u8 {
    return switch (format) {
        .text => "text",
        .json => "json",
    };
}

fn lowerAppParityReadPlanAlloc(
    alloc: std.mem.Allocator,
    effective_schema: runtime_schema.TableSchema,
    entry: AppParityCorpusEntry,
) !LoweredReadPlan {
    if (try appParitySourceTableNameAlloc(alloc, entry)) |source_table_name| {
        defer alloc.free(@constCast(source_table_name));
        var catalog = AppParitySourceSchemaCatalog.init(source_table_name, entry.source_schema_json);
        return try lowerReadPlanWithCatalogAlloc(
            alloc,
            entry.sql,
            effective_schema,
            entry.params,
            catalog.iface(),
        );
    }
    return try lowerReadPlanAlloc(alloc, entry.sql, effective_schema, entry.params);
}

fn lowerAppParityExplainPlanAlloc(
    alloc: std.mem.Allocator,
    effective_schema: runtime_schema.TableSchema,
    entry: AppParityCorpusEntry,
    unique_resolver: relational_rows.UniqueSelectorResolver,
    row_claim: db_mod.types.RowClaimRequest,
) !LoweredExplainPlan {
    if (try appParitySourceTableNameAlloc(alloc, entry)) |source_table_name| {
        defer alloc.free(@constCast(source_table_name));
        var catalog = AppParitySourceSchemaCatalog.init(source_table_name, entry.source_schema_json);
        return try lowerExplainPlanWithOptionsAndCatalogAlloc(
            alloc,
            entry.sql,
            effective_schema,
            entry.params,
            .{
                .unique_resolver = unique_resolver,
                .row_claim = row_claim,
            },
            catalog.iface(),
        );
    }
    return try lowerExplainPlanWithOptionsAlloc(alloc, entry.sql, effective_schema, entry.params, .{
        .unique_resolver = unique_resolver,
        .row_claim = row_claim,
    });
}

fn expectAppParityReadPlanEntry(
    alloc: std.mem.Allocator,
    effective_schema: runtime_schema.TableSchema,
    entry: AppParityCorpusEntry,
) !void {
    var lowered = try lowerAppParityReadPlanAlloc(alloc, effective_schema, entry);
    defer lowered.deinit(alloc);

    switch (entry.family) {
        .query => switch (lowered) {
            .query => |query| {
                try expectOptionalTableName(entry.summary.table_name, query.table_name);
                try expectOptionalUsize(entry.summary.ctes, query.plan.ctes.len);
                try expectQuerySummary(entry.summary, query.plan.query);
                var fingerprint = try queryFingerprintAlloc(alloc, "query", query.table_name, query.plan.query, query.plan.ctes.len);
                fingerprint = try appendNonZeroU32FingerprintAlloc(alloc, fingerprint, "offset", query.plan.query.offset);
                fingerprint = try appendTrueBoolFingerprintAlloc(alloc, fingerprint, "select_all", query.plan.query.select_all);
                fingerprint = try appendQueryAccessPathFingerprintAlloc(alloc, fingerprint, query.plan.query);
                fingerprint = try appendCteAccessPathFingerprintAlloc(alloc, fingerprint, query.plan.ctes);
                defer alloc.free(fingerprint);
                try expectAppParityPlan(entry.plan, fingerprint);
            },
            else => return error.TestUnexpectedResult,
        },
        .aggregate => switch (lowered) {
            .aggregate => |aggregate| {
                try expectOptionalTableName(entry.summary.table_name, aggregate.table_name);
                try expectOptionalUsize(entry.summary.ctes, aggregate.plan.ctes.len);
                try expectQuerySourceSummary(entry.summary, aggregate.plan.aggregate.source);
                try expectOptionalUsize(entry.summary.group_by, aggregate.plan.aggregate.group_by.len);
                try expectOptionalUsize(entry.summary.group_expressions, aggregate.plan.aggregate.group_expressions.len);
                try expectOptionalUsize(entry.summary.aggregations, aggregate.plan.aggregate.aggregations.len);
                try expectOptionalUsize(entry.summary.filter_groups, aggregateFilterGroupCount(aggregate.plan.aggregate.aggregations));
                try expectOptionalUsize(entry.summary.having, aggregate.plan.aggregate.having_predicates.len);
                try expectOptionalUsize(entry.summary.having_expressions, aggregate.plan.aggregate.having_expressions.len);
                try expectOptionalUsize(entry.summary.having_any, aggregate.plan.aggregate.having_any.len);
                try expectOptionalUsize(entry.summary.having_not, aggregate.plan.aggregate.having_not.len);
                try expectOptionalUsize(entry.summary.order_by, aggregate.plan.aggregate.order_by.len);
                try expectOptionalU32(entry.summary.limit, aggregate.plan.aggregate.limit);
                if (entry.summary.offset) |expected| try std.testing.expectEqual(expected, aggregate.plan.aggregate.offset);
                var fingerprint = try aggregatePlanFingerprintAlloc(alloc, aggregate);
                fingerprint = try appendNonZeroU32FingerprintAlloc(alloc, fingerprint, "offset", aggregate.plan.aggregate.offset);
                defer alloc.free(fingerprint);
                try expectAppParityPlan(entry.plan, fingerprint);
            },
            else => return error.TestUnexpectedResult,
        },
        .join => switch (lowered) {
            .join => |join| {
                try expectOptionalTableName(entry.summary.table_name, join.left_table_name);
                try expectCombinedQuerySourceSummary(entry.summary, join.join.left, join.join.right);
                try expectOptionalUsize(entry.summary.join_on, join.join.on.len);
                try expectOptionalUsize(entry.summary.join_select, join.join.select.len);
                try expectOptionalUsize(entry.summary.order_by, join.join.order_by.len);
                try expectOptionalU32(entry.summary.limit, join.join.limit);
                if (entry.summary.offset) |expected| try std.testing.expectEqual(expected, join.join.offset);
                var fingerprint = try joinFingerprintAlloc(alloc, join);
                fingerprint = try appendNonZeroU32FingerprintAlloc(alloc, fingerprint, "offset", join.join.offset);
                defer alloc.free(fingerprint);
                try expectAppParityPlan(entry.plan, fingerprint);
            },
            else => return error.TestUnexpectedResult,
        },
        .lateral => switch (lowered) {
            .lateral => |lateral| {
                try expectOptionalTableName(entry.summary.table_name, lateral.left_table_name);
                try expectCombinedQuerySourceSummary(entry.summary, lateral.plan.lateral.left, lateral.plan.lateral.right);
                try expectOptionalUsize(entry.summary.lateral_correlations, lateral.plan.lateral.correlations.len);
                try expectOptionalUsize(entry.summary.join_select, lateral.plan.lateral.select.len);
                try expectOptionalUsize(entry.summary.order_by, lateral.plan.lateral.order_by.len);
                try expectOptionalU32(entry.summary.limit, lateral.plan.lateral.limit);
                if (entry.summary.offset) |expected| try std.testing.expectEqual(expected, lateral.plan.lateral.offset);
                if (entry.summary.right_offset) |expected| try std.testing.expectEqual(expected, lateral.plan.lateral.right.offset);
                var fingerprint = try lateralFingerprintAlloc(alloc, lateral);
                fingerprint = try appendNonZeroU32FingerprintAlloc(alloc, fingerprint, "right_offset", lateral.plan.lateral.right.offset);
                fingerprint = try appendNonZeroU32FingerprintAlloc(alloc, fingerprint, "offset", lateral.plan.lateral.offset);
                defer alloc.free(fingerprint);
                try expectAppParityPlan(entry.plan, fingerprint);
            },
            else => return error.TestUnexpectedResult,
        },
        .window => switch (lowered) {
            .window => |window| {
                try expectOptionalTableName(entry.summary.table_name, window.table_name);
                try expectOptionalUsize(entry.summary.ctes, window.plan.ctes.len);
                try expectQuerySourceSummary(entry.summary, window.plan.window.source);
                try expectOptionalUsize(entry.summary.windows, window.plan.window.windows.len);
                try expectOptionalUsize(entry.summary.select, window.plan.window.select.len);
                try expectOptionalUsize(entry.summary.order_by, window.plan.window.order_by.len);
                try expectOptionalU32(entry.summary.limit, window.plan.window.limit);
                if (entry.summary.offset) |expected| try std.testing.expectEqual(expected, window.plan.window.offset);
                const fingerprint = try windowFingerprintAlloc(alloc, window);
                defer alloc.free(fingerprint);
                try expectAppParityPlan(entry.plan, fingerprint);
            },
            else => return error.TestUnexpectedResult,
        },
        else => return error.TestUnexpectedResult,
    }
}

fn appParityPlanFamilyIsSupportedRead(family: AppParityCorpusPlanFamily) bool {
    return switch (family) {
        .query,
        .aggregate,
        .join,
        .lateral,
        .window,
        => true,
        else => false,
    };
}

fn lowerAppParityWritePlanAlloc(
    alloc: std.mem.Allocator,
    effective_schema: runtime_schema.TableSchema,
    entry: AppParityCorpusEntry,
    unique_resolver: relational_rows.UniqueSelectorResolver,
    row_claim: db_mod.types.RowClaimRequest,
) !LoweredWritePlan {
    if (try appParitySourceTableNameAlloc(alloc, entry)) |source_table_name| {
        defer alloc.free(@constCast(source_table_name));
        var catalog = AppParitySourceSchemaCatalog.init(source_table_name, entry.source_schema_json);
        return try lowerWritePlanWithCatalogAlloc(alloc, entry.sql, effective_schema, entry.params, .{
            .unique_resolver = unique_resolver,
            .row_claim = row_claim,
        }, catalog.iface());
    }
    return try lowerWritePlanAlloc(alloc, entry.sql, effective_schema, entry.params, .{
        .unique_resolver = unique_resolver,
        .row_claim = row_claim,
    });
}

fn expectAppParityWritePlanEntry(
    alloc: std.mem.Allocator,
    effective_schema: runtime_schema.TableSchema,
    entry: AppParityCorpusEntry,
    unique_resolver: relational_rows.UniqueSelectorResolver,
    row_claim: db_mod.types.RowClaimRequest,
) !void {
    var lowered = try lowerAppParityWritePlanAlloc(alloc, effective_schema, entry, unique_resolver, row_claim);
    defer lowered.deinit(alloc);

    switch (entry.family) {
        .insert => switch (lowered) {
            .insert => |insert| {
                try expectOptionalTableName(entry.summary.table_name, insert.table_name);
                try expectOptionalUsize(entry.summary.operations, if (insert.batch.transforms.len == 0) 0 else insert.batch.transforms[0].operations.len);
                try expectOptionalUsize(entry.summary.returning, insert.batch.returning_rows.len);
                if (entry.summary.returning_all) |expected| try std.testing.expectEqual(expected, insert.returning_all);
                if (entry.summary.conflict_where) |expected| try std.testing.expectEqual(expected, insert.conflict_where);
                const operations = if (insert.batch.transforms.len == 0) 0 else insert.batch.transforms[0].operations.len;
                var fingerprint = try std.fmt.allocPrint(
                    alloc,
                    "insert:table={s}:writes={d}:transforms={d}:ops={d}:deletes={d}:returning_rows={d}:returning_expr={d}",
                    .{
                        insert.table_name,
                        insert.batch.writes.len,
                        insert.batch.transforms.len,
                        operations,
                        insert.batch.deletes.len,
                        insert.batch.returning_rows.len,
                        insert.returning_expression_count,
                    },
                );
                fingerprint = try appendTrueBoolFingerprintAlloc(alloc, fingerprint, "returning_all", insert.returning_all);
                fingerprint = try appendTrueBoolFingerprintAlloc(alloc, fingerprint, "conflict_where", insert.conflict_where);
                defer alloc.free(fingerprint);
                try expectAppParityPlan(entry.plan, fingerprint);
                try expectAppParityReturningRows(entry.returning_rows, insert.batch.returning_rows);
            },
            else => return error.TestUnexpectedResult,
        },
        .insert_source => switch (lowered) {
            .insert_source => |insert_source| {
                try expectOptionalTableName(entry.summary.table_name, insert_source.table_name);
                try expectOptionalUsize(entry.summary.ctes, insert_source.ctes.len);
                try expectQuerySummary(entry.summary, insert_source.insert_source.req.source);
                try expectOptionalUsize(entry.summary.operations, insert_source.insert_source.req.assignments.len);
                const conflict_patch_expressions = if (insert_source.insert_source.req.on_conflict) |conflict| conflict.patch_expressions.len else 0;
                const conflict_increment_expressions = if (insert_source.insert_source.req.on_conflict) |conflict| conflict.increment_expressions.len else 0;
                const conflict_json_set_expressions = if (insert_source.insert_source.req.on_conflict) |conflict| conflict.json_set_expressions.len else 0;
                try expectOptionalUsize(entry.summary.patch_expressions, conflict_patch_expressions);
                try expectOptionalUsize(entry.summary.increment_expressions, conflict_increment_expressions);
                try expectOptionalUsize(entry.summary.json_set_expressions, conflict_json_set_expressions);
                try expectOptionalUsize(entry.summary.returning, insert_source.insert_source.req.returning.len);
                if (entry.summary.returning_all) |expected| try std.testing.expectEqual(expected, insert_source.insert_source.req.returning_all);
                if (entry.summary.conflict_where) |expected| try std.testing.expectEqual(expected, insert_source.conflict_where);
                var fingerprint = try insertSourceFingerprintAlloc(alloc, insert_source);
                fingerprint = try appendNonZeroU32FingerprintAlloc(alloc, fingerprint, "source_offset", insert_source.insert_source.req.source.offset);
                fingerprint = try appendTrueBoolFingerprintAlloc(alloc, fingerprint, "conflict_where", insert_source.conflict_where);
                defer alloc.free(fingerprint);
                try expectAppParityPlan(entry.plan, fingerprint);
            },
            else => return error.TestUnexpectedResult,
        },
        .update => switch (lowered) {
            .update => |update| {
                try expectOptionalTableName(entry.summary.table_name, update.table_name);
                try expectOptionalUsize(entry.summary.operations, if (update.batch.transforms.len == 0) 0 else update.batch.transforms[0].operations.len);
                try expectOptionalUsize(entry.summary.returning, update.batch.returning_rows.len);
                if (entry.summary.returning_all) |expected| try std.testing.expectEqual(expected, update.returning_all);
                const operations = if (update.batch.transforms.len == 0) 0 else update.batch.transforms[0].operations.len;
                var fingerprint = try std.fmt.allocPrint(
                    alloc,
                    "update:table={s}:transforms={d}:ops={d}:returning_rows={d}:returning_expr={d}",
                    .{ update.table_name, update.batch.transforms.len, operations, update.batch.returning_rows.len, update.returning_expression_count },
                );
                fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "writes", update.batch.writes.len);
                fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "deletes", update.batch.deletes.len);
                fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "identity_rewrites", update.batch.relational_identity_rewrites.len);
                fingerprint = try appendTrueBoolFingerprintAlloc(alloc, fingerprint, "returning_all", update.returning_all);
                defer alloc.free(fingerprint);
                try expectAppParityPlan(entry.plan, fingerprint);
                try expectAppParityReturningRows(entry.returning_rows, update.batch.returning_rows);
            },
            else => return error.TestUnexpectedResult,
        },
        .delete => switch (lowered) {
            .delete => |delete| {
                try expectOptionalTableName(entry.summary.table_name, delete.table_name);
                try expectOptionalUsize(entry.summary.returning, delete.batch.returning_rows.len);
                if (entry.summary.returning_all) |expected| try std.testing.expectEqual(expected, delete.returning_all);
                var fingerprint = try std.fmt.allocPrint(
                    alloc,
                    "delete:table={s}:deletes={d}:returning_rows={d}:returning_expr={d}",
                    .{ delete.table_name, delete.batch.deletes.len, delete.batch.returning_rows.len, delete.returning_expression_count },
                );
                fingerprint = try appendTrueBoolFingerprintAlloc(alloc, fingerprint, "returning_all", delete.returning_all);
                defer alloc.free(fingerprint);
                try expectAppParityPlan(entry.plan, fingerprint);
                try expectAppParityReturningRows(entry.returning_rows, delete.batch.returning_rows);
            },
            else => return error.TestUnexpectedResult,
        },
        .update_source => switch (lowered) {
            .update_source => |update_source| {
                try expectOptionalTableName(entry.summary.table_name, update_source.table_name);
                try expectQuerySummary(entry.summary, update_source.mutation.req.source);
                try expectOptionalUsize(entry.summary.operations, update_source.mutation.req.operations.len);
                try expectOptionalUsize(entry.summary.patch_expressions, update_source.mutation.req.patch_expressions.len);
                try expectOptionalUsize(entry.summary.increment_expressions, update_source.mutation.req.increment_expressions.len);
                try expectOptionalUsize(entry.summary.json_set_expressions, update_source.mutation.req.json_set_expressions.len);
                try expectOptionalUsize(entry.summary.returning, update_source.mutation.req.returning.len);
                if (entry.summary.returning_all) |expected| try std.testing.expectEqual(expected, update_source.mutation.req.returning_all);
                var fingerprint = try updateSourceFingerprintAlloc(alloc, update_source);
                fingerprint = try appendNonZeroU32FingerprintAlloc(alloc, fingerprint, "source_offset", update_source.mutation.req.source.offset);
                defer alloc.free(fingerprint);
                try expectAppParityPlan(entry.plan, fingerprint);
            },
            else => return error.TestUnexpectedResult,
        },
        .delete_source => switch (lowered) {
            .delete_source => |delete_source| {
                try expectOptionalTableName(entry.summary.table_name, delete_source.table_name);
                try expectQuerySummary(entry.summary, delete_source.mutation.req.source);
                try expectOptionalUsize(entry.summary.returning, delete_source.mutation.req.returning.len);
                if (entry.summary.returning_all) |expected| try std.testing.expectEqual(expected, delete_source.mutation.req.returning_all);
                var fingerprint = try deleteSourceFingerprintAlloc(alloc, delete_source);
                fingerprint = try appendNonZeroU32FingerprintAlloc(alloc, fingerprint, "source_offset", delete_source.mutation.req.source.offset);
                defer alloc.free(fingerprint);
                try expectAppParityPlan(entry.plan, fingerprint);
            },
            else => return error.TestUnexpectedResult,
        },
        .truncate_source => switch (lowered) {
            .truncate_source => |truncate_source| {
                try expectOptionalTableName(entry.summary.table_name, truncate_source.table_name);
                try expectQuerySummary(entry.summary, truncate_source.mutation.req.source);
                try std.testing.expectEqual(db_mod.types.RelationalRowsMutationKind.delete, truncate_source.mutation.req.kind);
                try std.testing.expectEqual(@as(usize, 0), truncate_source.mutation.req.returning.len);
                try std.testing.expect(!truncate_source.mutation.req.returning_all);
                var fingerprint = try truncateSourceFingerprintAlloc(alloc, truncate_source);
                fingerprint = try appendNonZeroU32FingerprintAlloc(alloc, fingerprint, "source_offset", truncate_source.mutation.req.source.offset);
                defer alloc.free(fingerprint);
                try expectAppParityPlan(entry.plan, fingerprint);
            },
            else => return error.TestUnexpectedResult,
        },
        .update_joined_source => switch (lowered) {
            .update_joined_source => |update_joined_source| {
                try expectOptionalTableName(entry.summary.table_name, update_joined_source.target_table_name);
                try expectCombinedQuerySourceSummary(entry.summary, update_joined_source.mutation.req.join.left, update_joined_source.mutation.req.join.right);
                try expectOptionalUsize(entry.summary.join_on, update_joined_source.mutation.req.join.on.len);
                try expectOptionalUsize(entry.summary.order_by, update_joined_source.mutation.req.join.order_by.len);
                try expectOptionalU32(entry.summary.limit, update_joined_source.mutation.req.join.limit);
                try expectOptionalU32(entry.summary.offset, update_joined_source.mutation.req.join.offset);
                try expectOptionalUsize(entry.summary.operations, update_joined_source.mutation.req.operations.len);
                try expectOptionalUsize(entry.summary.source_assignments, update_joined_source.mutation.req.source_assignments.len);
                try expectOptionalUsize(entry.summary.patch_expressions, update_joined_source.mutation.req.patch_expressions.len);
                try expectOptionalUsize(entry.summary.increment_expressions, update_joined_source.mutation.req.increment_expressions.len);
                try expectOptionalUsize(entry.summary.json_set_expressions, update_joined_source.mutation.req.json_set_expressions.len);
                try expectOptionalUsize(entry.summary.returning, update_joined_source.mutation.req.returning.len);
                if (entry.summary.returning_all) |expected| try std.testing.expectEqual(expected, update_joined_source.mutation.req.returning_all);
                const fingerprint = try joinedSourceFingerprintAlloc(alloc, "update_joined_source", update_joined_source);
                defer alloc.free(fingerprint);
                try expectAppParityPlan(entry.plan, fingerprint);
            },
            else => return error.TestUnexpectedResult,
        },
        .delete_joined_source => switch (lowered) {
            .delete_joined_source => |delete_joined_source| {
                try expectOptionalTableName(entry.summary.table_name, delete_joined_source.target_table_name);
                try expectCombinedQuerySourceSummary(entry.summary, delete_joined_source.mutation.req.join.left, delete_joined_source.mutation.req.join.right);
                try expectOptionalUsize(entry.summary.join_on, delete_joined_source.mutation.req.join.on.len);
                try expectOptionalUsize(entry.summary.order_by, delete_joined_source.mutation.req.join.order_by.len);
                try expectOptionalU32(entry.summary.limit, delete_joined_source.mutation.req.join.limit);
                try expectOptionalU32(entry.summary.offset, delete_joined_source.mutation.req.join.offset);
                try expectOptionalUsize(entry.summary.returning, delete_joined_source.mutation.req.returning.len);
                if (entry.summary.returning_all) |expected| try std.testing.expectEqual(expected, delete_joined_source.mutation.req.returning_all);
                const fingerprint = try joinedSourceFingerprintAlloc(alloc, "delete_joined_source", delete_joined_source);
                defer alloc.free(fingerprint);
                try expectAppParityPlan(entry.plan, fingerprint);
            },
            else => return error.TestUnexpectedResult,
        },
        .merge_mutation => switch (lowered) {
            .merge_mutation => |merge_mutation| {
                try expectOptionalTableName(entry.summary.table_name, merge_mutation.target_table_name);
                try expectOptionalUsize(entry.summary.join_on, merge_mutation.match_fields.len);
                try expectOptionalUsize(entry.summary.matched_predicates, mergeMatchedPredicateCount(merge_mutation.matched_arms));
                try expectOptionalUsize(entry.summary.operations, mergeMatchedUpdateCount(merge_mutation.matched_arms));
                if (entry.summary.matched_delete) |expected| try std.testing.expectEqual(expected, mergeMatchedHasDelete(merge_mutation.matched_arms));
                if (entry.summary.matched_do_nothing) |expected| try std.testing.expectEqual(expected, mergeMatchedHasDoNothing(merge_mutation.matched_arms));
                try expectOptionalUsize(entry.summary.not_matched_predicates, mergeNotMatchedPredicateCount(merge_mutation.not_matched_arms));
                try expectOptionalUsize(entry.summary.select, mergeNotMatchedInsertCount(merge_mutation.not_matched_arms));
                if (entry.summary.not_matched_do_nothing) |expected| try std.testing.expectEqual(expected, mergeNotMatchedHasDoNothing(merge_mutation.not_matched_arms));
                try expectOptionalUsize(entry.summary.returning, merge_mutation.returning.fields.len);
                if (entry.summary.returning_all) |expected| try std.testing.expectEqual(expected, merge_mutation.returning.returnsAll());
                const fingerprint = try writePlanFingerprintAlloc(alloc, lowered);
                defer alloc.free(fingerprint);
                try expectAppParityPlan(entry.plan, fingerprint);
            },
            else => return error.TestUnexpectedResult,
        },
        else => return error.TestUnexpectedResult,
    }
}

fn appParityPlanFamilyIsSupportedWrite(family: AppParityCorpusPlanFamily) bool {
    return switch (family) {
        .insert,
        .insert_source,
        .update,
        .delete,
        .update_source,
        .delete_source,
        .truncate_source,
        .update_joined_source,
        .delete_joined_source,
        .merge_mutation,
        => true,
        else => false,
    };
}

fn expectAppParityCorpusEntry(
    alloc: std.mem.Allocator,
    base_schema_json: []const u8,
    schema: runtime_schema.TableSchema,
    entry: AppParityCorpusEntry,
    unique_resolver: relational_rows.UniqueSelectorResolver,
    row_claim: db_mod.types.RowClaimRequest,
) !void {
    var effective_schema = schema;
    var owned_setup_schema: ?runtime_schema.TableSchema = null;
    defer if (owned_setup_schema) |value| runtime_schema.freeSchema(alloc, value);
    if (entry.family != .ddl and entry.apply_setup_sql.len > 0) {
        const setup_schema_json = try schemaJsonFromSetupSqlAlloc(alloc, entry.apply_setup_sql);
        defer alloc.free(setup_schema_json);
        var parsed_setup_schema = try schema_api.parseValidatedTableSchema(alloc, setup_schema_json);
        defer parsed_setup_schema.deinit(alloc);
        owned_setup_schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed_setup_schema);
        effective_schema = owned_setup_schema.?;
    }
    var override_resolver_ctx = TestPrimaryResolver{
        .row_json = entry.resolver_row_json,
        .version = entry.resolver_version,
        .exists = entry.resolver_exists orelse true,
    };
    const effective_unique_resolver = if (entry.resolver_row_json.len > 0 or entry.resolver_exists != null)
        override_resolver_ctx.resolver()
    else
        unique_resolver;

    if (appParityPlanFamilyIsSupportedRead(entry.family)) {
        return try expectAppParityReadPlanEntry(alloc, effective_schema, entry);
    }
    if (appParityPlanFamilyIsSupportedWrite(entry.family)) {
        return try expectAppParityWritePlanEntry(alloc, effective_schema, entry, effective_unique_resolver, row_claim);
    }

    switch (entry.family) {
        .ddl => {
            var lowered = try lowerDdlPlanAlloc(alloc, entry.sql);
            defer lowered.deinit(alloc);
            try expectDdlSummary(entry.summary, lowered);
            const fingerprint = try ddlFingerprintAlloc(alloc, lowered);
            defer alloc.free(fingerprint);
            try expectAppParityPlan(entry.plan, fingerprint);
            try expectAppliedDdlCorpusPlan(alloc, base_schema_json, entry, lowered);
        },
        .read => {
            var lowered = try lowerAppParityReadPlanAlloc(alloc, effective_schema, entry);
            defer lowered.deinit(alloc);
            const fingerprint = try readPlanFingerprintAlloc(alloc, lowered);
            defer alloc.free(fingerprint);
            try expectAppParityPlan(entry.plan, fingerprint);
        },
        .query => {
            var lowered = try lowerQueryPlanAlloc(alloc, entry.sql, effective_schema, entry.params);
            defer lowered.deinit(alloc);
            try expectOptionalTableName(entry.summary.table_name, lowered.table_name);
            try expectOptionalUsize(entry.summary.ctes, lowered.plan.ctes.len);
            try expectQuerySummary(entry.summary, lowered.plan.query);
            var fingerprint = try queryFingerprintAlloc(alloc, "query", lowered.table_name, lowered.plan.query, lowered.plan.ctes.len);
            fingerprint = try appendNonZeroU32FingerprintAlloc(alloc, fingerprint, "offset", lowered.plan.query.offset);
            fingerprint = try appendTrueBoolFingerprintAlloc(alloc, fingerprint, "select_all", lowered.plan.query.select_all);
            fingerprint = try appendQueryAccessPathFingerprintAlloc(alloc, fingerprint, lowered.plan.query);
            fingerprint = try appendCteAccessPathFingerprintAlloc(alloc, fingerprint, lowered.plan.ctes);
            defer alloc.free(fingerprint);
            try expectAppParityPlan(entry.plan, fingerprint);
        },
        .aggregate => {
            var lowered = try lowerAggregatePlanAlloc(alloc, entry.sql, effective_schema, entry.params);
            defer lowered.deinit(alloc);
            try expectOptionalTableName(entry.summary.table_name, lowered.table_name);
            try expectOptionalUsize(entry.summary.ctes, lowered.plan.ctes.len);
            try expectQuerySourceSummary(entry.summary, lowered.plan.aggregate.source);
            try expectOptionalUsize(entry.summary.group_by, lowered.plan.aggregate.group_by.len);
            try expectOptionalUsize(entry.summary.group_expressions, lowered.plan.aggregate.group_expressions.len);
            try expectOptionalUsize(entry.summary.aggregations, lowered.plan.aggregate.aggregations.len);
            try expectOptionalUsize(entry.summary.filter_groups, aggregateFilterGroupCount(lowered.plan.aggregate.aggregations));
            try expectOptionalUsize(entry.summary.having, lowered.plan.aggregate.having_predicates.len);
            try expectOptionalUsize(entry.summary.having_expressions, lowered.plan.aggregate.having_expressions.len);
            try expectOptionalUsize(entry.summary.having_any, lowered.plan.aggregate.having_any.len);
            try expectOptionalUsize(entry.summary.having_not, lowered.plan.aggregate.having_not.len);
            try expectOptionalUsize(entry.summary.order_by, lowered.plan.aggregate.order_by.len);
            try expectOptionalU32(entry.summary.limit, lowered.plan.aggregate.limit);
            if (entry.summary.offset) |expected| try std.testing.expectEqual(expected, lowered.plan.aggregate.offset);
            var fingerprint = try aggregatePlanFingerprintAlloc(alloc, lowered);
            fingerprint = try appendNonZeroU32FingerprintAlloc(alloc, fingerprint, "offset", lowered.plan.aggregate.offset);
            defer alloc.free(fingerprint);
            try expectAppParityPlan(entry.plan, fingerprint);
        },
        .join => {
            var lowered = try lowerJoinAlloc(alloc, entry.sql, effective_schema, entry.params);
            defer lowered.deinit(alloc);
            try expectOptionalTableName(entry.summary.table_name, lowered.left_table_name);
            try expectCombinedQuerySourceSummary(entry.summary, lowered.join.left, lowered.join.right);
            try expectOptionalUsize(entry.summary.join_on, lowered.join.on.len);
            try expectOptionalUsize(entry.summary.join_select, lowered.join.select.len);
            try expectOptionalUsize(entry.summary.order_by, lowered.join.order_by.len);
            try expectOptionalU32(entry.summary.limit, lowered.join.limit);
            if (entry.summary.offset) |expected| try std.testing.expectEqual(expected, lowered.join.offset);
            var fingerprint = try joinFingerprintAlloc(alloc, lowered);
            fingerprint = try appendNonZeroU32FingerprintAlloc(alloc, fingerprint, "offset", lowered.join.offset);
            defer alloc.free(fingerprint);
            try expectAppParityPlan(entry.plan, fingerprint);
        },
        .lateral => {
            var lowered = try lowerLateralPlanAlloc(alloc, entry.sql, effective_schema, entry.params);
            defer lowered.deinit(alloc);
            try expectOptionalTableName(entry.summary.table_name, lowered.left_table_name);
            try expectCombinedQuerySourceSummary(entry.summary, lowered.plan.lateral.left, lowered.plan.lateral.right);
            try expectOptionalUsize(entry.summary.lateral_correlations, lowered.plan.lateral.correlations.len);
            try expectOptionalUsize(entry.summary.join_select, lowered.plan.lateral.select.len);
            try expectOptionalUsize(entry.summary.order_by, lowered.plan.lateral.order_by.len);
            try expectOptionalU32(entry.summary.limit, lowered.plan.lateral.limit);
            if (entry.summary.offset) |expected| try std.testing.expectEqual(expected, lowered.plan.lateral.offset);
            if (entry.summary.right_offset) |expected| try std.testing.expectEqual(expected, lowered.plan.lateral.right.offset);
            var fingerprint = try lateralFingerprintAlloc(alloc, lowered);
            fingerprint = try appendNonZeroU32FingerprintAlloc(alloc, fingerprint, "right_offset", lowered.plan.lateral.right.offset);
            fingerprint = try appendNonZeroU32FingerprintAlloc(alloc, fingerprint, "offset", lowered.plan.lateral.offset);
            defer alloc.free(fingerprint);
            try expectAppParityPlan(entry.plan, fingerprint);
        },
        .window => {
            var lowered = try lowerWindowPlanAlloc(alloc, entry.sql, effective_schema, entry.params);
            defer lowered.deinit(alloc);
            try expectOptionalTableName(entry.summary.table_name, lowered.table_name);
            try expectOptionalUsize(entry.summary.ctes, lowered.plan.ctes.len);
            try expectQuerySourceSummary(entry.summary, lowered.plan.window.source);
            try expectOptionalUsize(entry.summary.windows, lowered.plan.window.windows.len);
            try expectOptionalUsize(entry.summary.select, lowered.plan.window.select.len);
            try expectOptionalUsize(entry.summary.order_by, lowered.plan.window.order_by.len);
            try expectOptionalU32(entry.summary.limit, lowered.plan.window.limit);
            if (entry.summary.offset) |expected| try std.testing.expectEqual(expected, lowered.plan.window.offset);
            const fingerprint = try windowFingerprintAlloc(alloc, lowered);
            defer alloc.free(fingerprint);
            try expectAppParityPlan(entry.plan, fingerprint);
        },
        .explain => {
            var lowered = try lowerAppParityExplainPlanAlloc(
                alloc,
                effective_schema,
                entry,
                effective_unique_resolver,
                row_claim,
            );
            defer lowered.deinit(alloc);
            const fingerprint = try explainPlanFingerprintAlloc(alloc, lowered);
            defer alloc.free(fingerprint);
            try expectAppParityPlan(entry.plan, fingerprint);
        },
        .relation_population => {
            var lowered = try lowerRelationPopulationPlanAlloc(alloc, entry.sql, effective_schema, entry.params);
            defer lowered.deinit(alloc);
            try expectOptionalTableName(entry.summary.table_name, lowered.target_table_name);
            const fingerprint = try relationPopulationFingerprintAlloc(alloc, lowered);
            defer alloc.free(fingerprint);
            try expectAppParityPlan(entry.plan, fingerprint);
        },
        .insert => {
            var lowered = try lowerInsertWithResolverAlloc(alloc, entry.sql, effective_schema, entry.params, effective_unique_resolver);
            defer lowered.deinit(alloc);
            try expectOptionalTableName(entry.summary.table_name, lowered.table_name);
            try expectOptionalUsize(entry.summary.operations, if (lowered.batch.transforms.len == 0) 0 else lowered.batch.transforms[0].operations.len);
            try expectOptionalUsize(entry.summary.returning, lowered.batch.returning_rows.len);
            if (entry.summary.returning_all) |expected| try std.testing.expectEqual(expected, lowered.returning_all);
            if (entry.summary.conflict_where) |expected| try std.testing.expectEqual(expected, lowered.conflict_where);
            const operations = if (lowered.batch.transforms.len == 0) 0 else lowered.batch.transforms[0].operations.len;
            var fingerprint = try std.fmt.allocPrint(
                alloc,
                "insert:table={s}:writes={d}:transforms={d}:ops={d}:deletes={d}:returning_rows={d}:returning_expr={d}",
                .{
                    lowered.table_name,
                    lowered.batch.writes.len,
                    lowered.batch.transforms.len,
                    operations,
                    lowered.batch.deletes.len,
                    lowered.batch.returning_rows.len,
                    lowered.returning_expression_count,
                },
            );
            fingerprint = try appendTrueBoolFingerprintAlloc(alloc, fingerprint, "returning_all", lowered.returning_all);
            fingerprint = try appendTrueBoolFingerprintAlloc(alloc, fingerprint, "conflict_where", lowered.conflict_where);
            defer alloc.free(fingerprint);
