test "postgres sql adapter lowers update patch with explicit version predicate" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"email":{"type":"keyword"},"status":{"type":"keyword"},"enabled":{"type":"boolean"},"metadata":{"type":"json"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]},"unique_constraints":[{"name":"usage_records_email_key","columns":["email"]}]}
    ;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);
    var resolver_ctx = TestPrimaryResolver{ .row_json = "{\"id\":\"u1\",\"email\":\"a@example.test\",\"status\":\"pending\",\"metadata\":{\"billing\":{\"plan\":\"free\"},\"source\":\"seed\"}}", .version = 42 };

    var lowered = try lowerUpdateAlloc(
        alloc,
        "UPDATE usage_records SET status = $1 WHERE id = $2",
        schema,
        &.{ .{ .string = "active" }, .{ .string = "u1" } },
        resolver_ctx.resolver(),
    );
    defer lowered.deinit(alloc);

    try std.testing.expectEqualStrings("usage_records", lowered.table_name);
    try std.testing.expectEqual(@as(u32, 1), lowered.batch.transformed);
    try std.testing.expectEqual(@as(usize, 1), lowered.batch.transforms.len);
    try std.testing.expectEqual(@as(usize, 1), lowered.batch.transforms[0].operations.len);
    try std.testing.expectEqualStrings("status", lowered.batch.transforms[0].operations[0].path);
    try std.testing.expectEqualStrings("\"active\"", lowered.batch.transforms[0].operations[0].value_json.?);
    try std.testing.expectEqual(@as(usize, 1), lowered.batch.predicates.len);
    try std.testing.expectEqual(@as(u64, 42), lowered.batch.predicates[0].expected_version);

    var row_assignment = try lowerUpdateAlloc(
        alloc,
        "UPDATE usage_records SET (status, email) = ($1, lower(email)) WHERE id = $2 RETURNING status, email",
        schema,
        &.{ .{ .string = "active" }, .{ .string = "u1" } },
        resolver_ctx.resolver(),
    );
    defer row_assignment.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 1), row_assignment.batch.transformed);
    try std.testing.expectEqual(@as(usize, 2), row_assignment.batch.transforms[0].operations.len);
    try std.testing.expectEqual(db_mod.types.TransformOpType.set, row_assignment.batch.transforms[0].operations[0].op);
    try std.testing.expectEqualStrings("status", row_assignment.batch.transforms[0].operations[0].path);
    try std.testing.expectEqualStrings("\"active\"", row_assignment.batch.transforms[0].operations[0].value_json.?);
    try std.testing.expectEqual(db_mod.types.TransformOpType.set, row_assignment.batch.transforms[0].operations[1].op);
    try std.testing.expectEqualStrings("email", row_assignment.batch.transforms[0].operations[1].path);
    try std.testing.expectEqualStrings("\"a@example.test\"", row_assignment.batch.transforms[0].operations[1].value_json.?);
    try std.testing.expectEqualStrings("{\"status\":\"active\",\"email\":\"a@example.test\"}", row_assignment.batch.returning_rows[0]);

    var identity_rewrite = try lowerUpdateAlloc(
        alloc,
        "UPDATE usage_records SET id = 'u2', status = 'moved' WHERE id = 'u1' RETURNING id, status",
        schema,
        &.{},
        resolver_ctx.resolver(),
    );
    defer identity_rewrite.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 1), identity_rewrite.batch.inserted);
    try std.testing.expectEqual(@as(u32, 1), identity_rewrite.batch.deleted);
    try std.testing.expectEqual(@as(usize, 0), identity_rewrite.batch.writes.len);
    try std.testing.expectEqual(@as(usize, 0), identity_rewrite.batch.deletes.len);
    try std.testing.expectEqual(@as(usize, 1), identity_rewrite.batch.relational_identity_rewrites.len);
    try std.testing.expect(!std.mem.eql(u8, identity_rewrite.batch.relational_identity_rewrites[0].old_key, identity_rewrite.batch.relational_identity_rewrites[0].new_key));
    try std.testing.expectEqualStrings("{\"id\":\"u2\",\"email\":\"a@example.test\",\"status\":\"moved\",\"metadata\":{\"billing\":{\"plan\":\"free\"},\"source\":\"seed\"}}", identity_rewrite.batch.relational_identity_rewrites[0].value);
    try std.testing.expectEqual(@as(usize, 2), identity_rewrite.batch.predicates.len);
    try std.testing.expectEqual(@as(u64, 42), identity_rewrite.batch.predicates[0].expected_version);
    try std.testing.expectEqual(@as(u64, 0), identity_rewrite.batch.predicates[1].expected_version);
    try std.testing.expectEqualStrings("{\"id\":\"u2\",\"status\":\"moved\"}", identity_rewrite.batch.returning_rows[0]);

    try std.testing.expectError(error.UnsupportedSqlShape, lowerUpdateAlloc(
        alloc,
        "UPDATE usage_records SET status = 'active', status = lower(status) WHERE id = $1",
        schema,
        &.{.{ .string = "u1" }},
        resolver_ctx.resolver(),
    ));

    var concat_patch = try lowerUpdateAlloc(
        alloc,
        "UPDATE usage_records SET status = status || '-done' WHERE id = $1 RETURNING status",
        schema,
        &.{.{ .string = "u1" }},
        resolver_ctx.resolver(),
    );
    defer concat_patch.deinit(alloc);

    try std.testing.expectEqual(@as(u32, 1), concat_patch.batch.transformed);
    try std.testing.expectEqual(@as(usize, 1), concat_patch.batch.transforms.len);
    try std.testing.expectEqualStrings("status", concat_patch.batch.transforms[0].operations[0].path);
    try std.testing.expectEqualStrings("\"pending-done\"", concat_patch.batch.transforms[0].operations[0].value_json.?);
    try std.testing.expectEqualStrings("{\"status\":\"pending-done\"}", concat_patch.batch.returning_rows[0]);

    var boolean_resolver_ctx = TestPrimaryResolver{ .row_json = "{\"id\":\"u1\",\"email\":\"a@example.test\",\"status\":\"pending\",\"enabled\":false,\"metadata\":{}}", .version = 43 };
    var boolean_patch = try lowerUpdateAlloc(
        alloc,
        "UPDATE usage_records SET enabled = enabled OR true WHERE id = $1 RETURNING enabled",
        schema,
        &.{.{ .string = "u1" }},
        boolean_resolver_ctx.resolver(),
    );
    defer boolean_patch.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 1), boolean_patch.batch.transformed);
    try std.testing.expectEqual(@as(usize, 1), boolean_patch.batch.transforms[0].operations.len);
    try std.testing.expectEqualStrings("enabled", boolean_patch.batch.transforms[0].operations[0].path);
    try std.testing.expectEqualStrings("true", boolean_patch.batch.transforms[0].operations[0].value_json.?);
    try std.testing.expectEqualStrings("{\"enabled\":true}", boolean_patch.batch.returning_rows[0]);

    var alias_all_returning = try lowerUpdateAlloc(
        alloc,
        "UPDATE usage_records AS u SET status = 'active' WHERE id = $1 RETURNING u.*",
        schema,
        &.{.{ .string = "u1" }},
        resolver_ctx.resolver(),
    );
    defer alias_all_returning.deinit(alloc);
    try std.testing.expectEqualStrings("usage_records", alias_all_returning.table_name);
    try std.testing.expect(alias_all_returning.returning_all);
    try std.testing.expectEqual(@as(usize, 1), alias_all_returning.batch.returning_rows.len);
    var alias_all_row = try std.json.parseFromSlice(std.json.Value, alloc, alias_all_returning.batch.returning_rows[0], .{});
    defer alias_all_row.deinit();
    try std.testing.expectEqualStrings("u1", alias_all_row.value.object.get("id").?.string);
    try std.testing.expectEqualStrings("active", alias_all_row.value.object.get("status").?.string);

    var alias_qualified_fields = try lowerUpdateAlloc(
        alloc,
        "UPDATE usage_records AS u SET status = 'active' WHERE id = $1 RETURNING u.id, u.status AS returned_status",
        schema,
        &.{.{ .string = "u1" }},
        resolver_ctx.resolver(),
    );
    defer alias_qualified_fields.deinit(alloc);
    try std.testing.expectEqualStrings("usage_records", alias_qualified_fields.table_name);
    try std.testing.expectEqual(@as(usize, 1), alias_qualified_fields.batch.returning_rows.len);
    var alias_qualified_row = try std.json.parseFromSlice(std.json.Value, alloc, alias_qualified_fields.batch.returning_rows[0], .{});
    defer alias_qualified_row.deinit();
    try std.testing.expectEqualStrings("u1", alias_qualified_row.value.object.get("id").?.string);
    try std.testing.expectEqualStrings("active", alias_qualified_row.value.object.get("returned_status").?.string);

    var alias_qualified_expressions = try lowerUpdateAlloc(
        alloc,
        "UPDATE usage_records AS u SET status = 'active' WHERE id = $1 RETURNING u.status || ':' || u.id AS status_key, lower(u.status) AS lower_status, u.metadata->>'source' AS metadata_source",
        schema,
        &.{.{ .string = "u1" }},
        resolver_ctx.resolver(),
    );
    defer alias_qualified_expressions.deinit(alloc);
    try std.testing.expectEqualStrings("usage_records", alias_qualified_expressions.table_name);
    try std.testing.expectEqual(@as(usize, 1), alias_qualified_expressions.batch.returning_rows.len);
    var alias_expression_row = try std.json.parseFromSlice(std.json.Value, alloc, alias_qualified_expressions.batch.returning_rows[0], .{});
    defer alias_expression_row.deinit();
    try std.testing.expectEqualStrings("active:u1", alias_expression_row.value.object.get("status_key").?.string);
    try std.testing.expectEqualStrings("active", alias_expression_row.value.object.get("lower_status").?.string);
    try std.testing.expectEqualStrings("seed", alias_expression_row.value.object.get("metadata_source").?.string);

    var unique_selector = try lowerUpdateAlloc(
        alloc,
        "UPDATE usage_records SET status = 'active' WHERE email = $1 RETURNING id, status",
        schema,
        &.{.{ .string = "a@example.test" }},
        resolver_ctx.resolver(),
    );
    defer unique_selector.deinit(alloc);
    try std.testing.expectEqualStrings("usage_records", unique_selector.table_name);
    try std.testing.expectEqual(@as(u32, 1), unique_selector.batch.transformed);
    try std.testing.expectEqualStrings("test-existing-primary", unique_selector.batch.transforms[0].key);
    try std.testing.expectEqual(@as(u64, 42), unique_selector.batch.predicates[0].expected_version);
    try std.testing.expectEqualStrings("{\"id\":\"u1\",\"status\":\"active\"}", unique_selector.batch.returning_rows[0]);
}

test "postgres sql adapter evaluates now returning expression from typed plan" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"status":{"type":"keyword"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"name":"usage_records_id_pk","columns":["id"]}}
    ;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);
    var resolver_ctx = TestPrimaryResolver{ .row_json = "{\"id\":\"u1\",\"status\":\"pending\"}", .version = 42 };

    var lowered = try lowerUpdateAlloc(
        alloc,
        "UPDATE usage_records SET status = $1 WHERE id = $2 RETURNING now() AS planned_at_ns",
        schema,
        &.{ .{ .string = "active" }, .{ .string = "u1" } },
        resolver_ctx.resolver(),
    );
    defer lowered.deinit(alloc);

    try std.testing.expectEqual(@as(usize, 1), lowered.batch.returning_rows.len);
    var parsed_row = try std.json.parseFromSlice(std.json.Value, alloc, lowered.batch.returning_rows[0], .{});
    defer parsed_row.deinit();
    const planned_at = parsed_row.value.object.get("planned_at_ns") orelse return error.TestExpectedEqual;
    const planned_at_ns: u64 = switch (planned_at) {
        .integer => |value| if (value > 0) @intCast(value) else return error.TestExpectedEqual,
        .number_string => |value| try std.fmt.parseInt(u64, value, 10),
        else => return error.TestExpectedEqual,
    };
    try std.testing.expect(planned_at_ns > 0);
}

test "postgres sql adapter lowers arithmetic updates into typed increments" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"amount":{"type":"numeric"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);
    var resolver_ctx = TestPrimaryResolver{ .row_json = "{\"id\":\"u1\",\"amount\":5}", .version = 21 };

    var plus = try lowerUpdateAlloc(
        alloc,
        "UPDATE usage_records SET amount = amount + $1 WHERE id = $2 RETURNING amount, amount * 2 AS doubled_amount",
        schema,
        &.{ .{ .integer = 2 }, .{ .string = "u1" } },
        resolver_ctx.resolver(),
    );
    defer plus.deinit(alloc);

