    try std.testing.expectEqualStrings("enabled", boolean_is_not_source.mutation.req.source.or_predicates[0].predicates[0].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.ne, boolean_is_not_source.mutation.req.source.or_predicates[0].predicates[0].op);
    try std.testing.expectEqualStrings("true", boolean_is_not_source.mutation.req.source.or_predicates[0].predicates[0].value_json.?);
    try std.testing.expectEqualStrings("enabled", boolean_is_not_source.mutation.req.source.or_predicates[1].predicates[0].field);
