    try std.testing.expectEqual(@as(u32, 10), lowered.mutation.req.source.limit.?);
    try std.testing.expect(lowered.mutation.req.source.row_claim != null);
    try std.testing.expect(!lowered.mutation.req.source.row_claim.?.skip_locked);
    try std.testing.expectEqual(@as(usize, 0), lowered.mutation.req.operations.len);
    try std.testing.expectEqual(@as(usize, 1), lowered.mutation.req.returning.len);
    try std.testing.expectEqualStrings("id", lowered.mutation.req.returning[0]);
    try std.testing.expectEqual(@as(usize, 2), lowered.mutation.req.returning_expressions.len);
    try std.testing.expectEqualStrings("status_key", lowered.mutation.req.returning_expressions[0].output);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.lower, lowered.mutation.req.returning_expressions[0].expression.kind);
    try std.testing.expectEqualStrings("next_expires_at", lowered.mutation.req.returning_expressions[1].output);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.add, lowered.mutation.req.returning_expressions[1].expression.kind);

    var alias_all_returning = try lowerDeleteMutationSourceAlloc(
        alloc,
        "DELETE FROM usage_records AS u WHERE status = 'expired' FOR UPDATE RETURNING u.*",
        schema,
        &.{},
        claim,
    );
    defer alias_all_returning.deinit(alloc);
    try std.testing.expectEqualStrings("usage_records", alias_all_returning.table_name);
    try std.testing.expect(alias_all_returning.mutation.req.returning_all);
    try std.testing.expectEqual(@as(usize, 0), alias_all_returning.mutation.req.returning.len);

    var alias_qualified_fields = try lowerDeleteMutationSourceAlloc(
        alloc,
        "DELETE FROM usage_records AS u WHERE status = 'expired' FOR UPDATE RETURNING u.id, u.status AS deleted_status",
        schema,
        &.{},
        claim,
    );
    defer alias_qualified_fields.deinit(alloc);
    try std.testing.expectEqualStrings("usage_records", alias_qualified_fields.table_name);
    try std.testing.expectEqual(@as(usize, 1), alias_qualified_fields.mutation.req.returning.len);
    try std.testing.expectEqualStrings("id", alias_qualified_fields.mutation.req.returning[0]);
    try std.testing.expectEqual(@as(usize, 1), alias_qualified_fields.mutation.req.returning_expressions.len);
    try std.testing.expectEqualStrings("deleted_status", alias_qualified_fields.mutation.req.returning_expressions[0].output);
    try std.testing.expectEqualStrings("status", alias_qualified_fields.mutation.req.returning_expressions[0].expression.field);

    var boolean_unknown = try lowerDeleteMutationSourceAlloc(
        alloc,
        "DELETE FROM usage_records WHERE enabled IS UNKNOWN FOR UPDATE RETURNING id",
        schema,
        &.{},
        claim,
    );
    defer boolean_unknown.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), boolean_unknown.mutation.req.source.predicates.len);
    try std.testing.expectEqualStrings("enabled", boolean_unknown.mutation.req.source.predicates[0].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.is_null, boolean_unknown.mutation.req.source.predicates[0].op);
    try std.testing.expect(boolean_unknown.mutation.req.source.predicates[0].value_json == null);

    var table_wide = try lowerDeleteMutationSourceAlloc(
        alloc,
        "DELETE FROM usage_records RETURNING id, LOWER(status) AS status_key",
        schema,
        &.{},
        claim,
    );
    defer table_wide.deinit(alloc);
    try std.testing.expectEqualStrings("usage_records", table_wide.table_name);
    try std.testing.expectEqual(db_mod.types.RelationalRowsMutationKind.delete, table_wide.mutation.req.kind);
    try std.testing.expectEqual(@as(usize, 0), table_wide.mutation.req.source.predicates.len);
    try std.testing.expectEqual(@as(usize, 0), table_wide.mutation.req.source.order_by.len);
    try std.testing.expectEqual(@as(?u32, null), table_wide.mutation.req.source.limit);
    try std.testing.expect(table_wide.mutation.req.source.row_claim != null);
    try std.testing.expectEqualStrings("cleanup", table_wide.mutation.req.source.row_claim.?.owner_id);
    try std.testing.expectEqual(@as(usize, 1), table_wide.mutation.req.returning.len);
    try std.testing.expectEqualStrings("id", table_wide.mutation.req.returning[0]);
    try std.testing.expectEqual(@as(usize, 1), table_wide.mutation.req.returning_expressions.len);
    try std.testing.expectEqualStrings("status_key", table_wide.mutation.req.returning_expressions[0].output);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.lower, table_wide.mutation.req.returning_expressions[0].expression.kind);
}

test "postgres sql adapter routes write sql through typed plan families" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"kind":{"type":"keyword"},"source_id":{"type":"keyword"},"status":{"type":"keyword"},"organization_id":{"type":"keyword"},"quantity":{"type":"numeric"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);
    var resolver_ctx = TestPrimaryResolver{ .row_json = "{\"id\":\"u1\",\"status\":\"active\",\"organization_id\":\"o1\"}", .version = 9 };
    const txn_id = [_]u8{ 0x30, 0x31, 0x32, 0x33, 0x34, 0x35, 0x36, 0x37, 0x38, 0x39, 0x3a, 0x3b, 0x3c, 0x3d, 0x3e, 0x3f };
    const claim: db_mod.types.RowClaimRequest = .{
        .mode = .for_update,
        .owner_id = "sql-writer",
        .txn_id = txn_id,
    };
    const options = LowerWritePlanOptions{
        .unique_resolver = resolver_ctx.resolver(),
        .row_claim = claim,
    };

    var insert_plan = try lowerWritePlanAlloc(
        alloc,
        "INSERT INTO usage_records (id, status, organization_id) VALUES ('u2', 'active', 'o1') RETURNING id",
        schema,
        &.{},
        options,
    );
    defer insert_plan.deinit(alloc);
    switch (insert_plan) {
        .insert => |insert| {
            try std.testing.expectEqualStrings("usage_records", insert.table_name);
            try std.testing.expectEqual(@as(u32, 1), insert.batch.inserted);
        },
        else => return error.TestUnexpectedResult,
    }

    var point_update_plan = try lowerWritePlanAlloc(
        alloc,
        "UPDATE usage_records SET status = 'disabled' WHERE id = 'u1' RETURNING id",
        schema,
        &.{},
        options,
    );
    defer point_update_plan.deinit(alloc);
    switch (point_update_plan) {
        .update => |update| {
            try std.testing.expectEqualStrings("usage_records", update.table_name);
            try std.testing.expectEqual(@as(u32, 1), update.batch.transformed);
        },
        else => return error.TestUnexpectedResult,
    }

    var source_update_plan = try lowerWritePlanAlloc(
        alloc,
        "UPDATE usage_records SET status = 'disabled' WHERE organization_id = 'o1' FOR UPDATE SKIP LOCKED RETURNING id",
        schema,
        &.{},
        options,
    );
    defer source_update_plan.deinit(alloc);
    switch (source_update_plan) {
        .update_source => |update_source| {
            try std.testing.expectEqualStrings("usage_records", update_source.table_name);
            try std.testing.expectEqual(db_mod.types.RelationalRowsMutationKind.update, update_source.mutation.req.kind);
            try std.testing.expectEqual(@as(usize, 1), update_source.mutation.req.source.predicates.len);
            try std.testing.expect(update_source.mutation.req.source.row_claim.?.skip_locked);
        },
        else => return error.TestUnexpectedResult,
    }

    var unclaimed_syntax_source_update_plan = try lowerWritePlanAlloc(
        alloc,
        "UPDATE usage_records SET status = 'disabled' WHERE organization_id = 'o1' RETURNING id",
        schema,
        &.{},
        options,
    );
    defer unclaimed_syntax_source_update_plan.deinit(alloc);
    switch (unclaimed_syntax_source_update_plan) {
        .update_source => |update_source| {
            try std.testing.expectEqualStrings("usage_records", update_source.table_name);
            try std.testing.expectEqual(db_mod.types.RelationalRowsMutationKind.update, update_source.mutation.req.kind);
            try std.testing.expectEqual(@as(usize, 1), update_source.mutation.req.source.predicates.len);
            try std.testing.expect(update_source.mutation.req.source.row_claim != null);
            try std.testing.expectEqual(db_mod.types.RowClaimWaitPolicy.wait, update_source.mutation.req.source.row_claim.?.wait_policy);
            try std.testing.expect(!update_source.mutation.req.source.row_claim.?.skip_locked);
        },
        else => return error.TestUnexpectedResult,
    }

    var table_wide_update_plan = try lowerWritePlanAlloc(
        alloc,
        "UPDATE usage_records SET status = 'archived' RETURNING id",
        schema,
        &.{},
        options,
    );
    defer table_wide_update_plan.deinit(alloc);
    switch (table_wide_update_plan) {
        .update_source => |update_source| {
            try std.testing.expectEqualStrings("usage_records", update_source.table_name);
            try std.testing.expectEqual(db_mod.types.RelationalRowsMutationKind.update, update_source.mutation.req.kind);
            try std.testing.expectEqual(@as(usize, 0), update_source.mutation.req.source.predicates.len);
            try std.testing.expectEqual(@as(usize, 0), update_source.mutation.req.source.order_by.len);
            try std.testing.expectEqual(@as(?u32, null), update_source.mutation.req.source.limit);
            try std.testing.expect(update_source.mutation.req.source.row_claim != null);
            try std.testing.expectEqual(db_mod.types.RowClaimWaitPolicy.wait, update_source.mutation.req.source.row_claim.?.wait_policy);
            try std.testing.expect(!update_source.mutation.req.source.row_claim.?.skip_locked);
            try std.testing.expectEqual(@as(usize, 1), update_source.mutation.req.operations.len);
            try std.testing.expectEqual(@as(usize, 1), update_source.mutation.req.returning.len);
        },
        else => return error.TestUnexpectedResult,
    }

    var joined_update_plan = try lowerWritePlanAlloc(
        alloc,
        "UPDATE usage_records SET status = source.status FROM usage_records AS source WHERE usage_records.id = source.id FOR UPDATE RETURNING id",
        schema,
        &.{},
        options,
    );
    defer joined_update_plan.deinit(alloc);
    switch (joined_update_plan) {
        .update_joined_source => |update_joined_source| {
            try std.testing.expectEqualStrings("usage_records", update_joined_source.target_table_name);
            try std.testing.expectEqualStrings("usage_records", update_joined_source.source_table_name);
            try std.testing.expectEqual(db_mod.types.RelationalRowsMutationKind.update, update_joined_source.mutation.req.kind);
            try std.testing.expectEqual(@as(usize, 1), update_joined_source.mutation.req.join.on.len);
            try std.testing.expectEqual(@as(usize, 1), update_joined_source.mutation.req.source_assignments.len);
        },
        else => return error.TestUnexpectedResult,
    }

    var targeted_joined_update_plan = try lowerWritePlanAlloc(
        alloc,
        "UPDATE usage_records AS target SET status = source.status FROM usage_records AS source WHERE target.id = source.id FOR UPDATE OF target SKIP LOCKED RETURNING target.id",
        schema,
        &.{},
        options,
    );
    defer targeted_joined_update_plan.deinit(alloc);
    switch (targeted_joined_update_plan) {
        .update_joined_source => |update_joined_source| {
            try std.testing.expectEqualStrings("usage_records", update_joined_source.target_table_name);
            try std.testing.expectEqualStrings("usage_records", update_joined_source.source_table_name);
            try std.testing.expect(update_joined_source.mutation.req.join.left.row_claim != null);
            try std.testing.expect(update_joined_source.mutation.req.join.left.row_claim.?.skip_locked);
        },
        else => return error.TestUnexpectedResult,
    }

    try std.testing.expectError(error.UnsupportedSqlShape, lowerWritePlanAlloc(
        alloc,
        "UPDATE usage_records AS target SET status = source.status FROM usage_records AS source WHERE target.id = source.id FOR UPDATE OF source RETURNING target.id",
        schema,
        &.{},
        options,
    ));

    var semijoin_update_plan = try lowerWritePlanAlloc(
        alloc,
        "UPDATE usage_records SET status = 'archived' WHERE usage_records.id IN (SELECT archived_records.id FROM archived_records WHERE organization_id = 'o1') FOR UPDATE SKIP LOCKED RETURNING id",
        schema,
        &.{},
        options,
    );
    defer semijoin_update_plan.deinit(alloc);
    switch (semijoin_update_plan) {
        .update_joined_source => |update_joined_source| {
            try std.testing.expectEqualStrings("usage_records", update_joined_source.target_table_name);
