test "postgres sql adapter lowers non recursive cte query plans" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"status":{"type":"keyword"},"amount":{"type":"numeric"},"created_at":{"type":"numeric"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);

    var lowered = try lowerQueryPlanAlloc(
        alloc,
        "WITH open_orders AS (SELECT id, status, amount, created_at FROM orders WHERE status = 'open'), expensive_open_orders AS (SELECT id, amount, created_at FROM open_orders WHERE amount > 10) SELECT id FROM expensive_open_orders ORDER BY created_at DESC LIMIT 2",
        schema,
        &.{},
    );
    defer lowered.deinit(alloc);

    try std.testing.expectEqualStrings("orders", lowered.table_name);
    try std.testing.expectEqual(@as(usize, 2), lowered.plan.ctes.len);
    try std.testing.expectEqualStrings("open_orders", lowered.plan.ctes[0].name);
    try std.testing.expectEqualStrings("", lowered.plan.ctes[0].query.source_cte);
    try std.testing.expectEqual(@as(usize, 1), lowered.plan.ctes[0].query.predicates.len);
    try std.testing.expectEqualStrings("status", lowered.plan.ctes[0].query.predicates[0].field);
    try std.testing.expectEqualStrings("\"open\"", lowered.plan.ctes[0].query.predicates[0].value_json.?);
    try std.testing.expectEqualStrings("expensive_open_orders", lowered.plan.ctes[1].name);
    try std.testing.expectEqualStrings("open_orders", lowered.plan.ctes[1].query.source_cte);
    try std.testing.expectEqual(@as(usize, 1), lowered.plan.ctes[1].query.predicates.len);
    try std.testing.expectEqualStrings("amount", lowered.plan.ctes[1].query.predicates[0].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.gt, lowered.plan.ctes[1].query.predicates[0].op);
    try std.testing.expectEqualStrings("10", lowered.plan.ctes[1].query.predicates[0].value_json.?);
    try std.testing.expectEqualStrings("expensive_open_orders", lowered.plan.query.source_cte);
    try std.testing.expectEqual(@as(usize, 1), lowered.plan.query.select.len);
    try std.testing.expectEqualStrings("id", lowered.plan.query.select[0]);
    try std.testing.expectEqual(@as(usize, 1), lowered.plan.query.order_by.len);
    try std.testing.expectEqualStrings("created_at", lowered.plan.query.order_by[0].field);
    try std.testing.expectEqual(@as(u32, 2), lowered.plan.query.limit.?);

    var direct_select = try lowerSelectAlloc(
        alloc,
        "WITH open_orders AS (SELECT id, status, created_at FROM orders WHERE status = 'open') SELECT id FROM open_orders ORDER BY created_at DESC LIMIT 5",
        schema,
        &.{},
    );
    defer direct_select.deinit(alloc);
    try std.testing.expectEqualStrings("orders", direct_select.table_name);
    try std.testing.expectEqual(@as(usize, 1), direct_select.ctes.len);
    try std.testing.expectEqualStrings("open_orders", direct_select.ctes[0].name);
    try std.testing.expectEqual(@as(usize, 1), direct_select.ctes[0].query.predicates.len);
    try std.testing.expectEqualStrings("status", direct_select.ctes[0].query.predicates[0].field);
    try std.testing.expectEqualStrings("open_orders", direct_select.query.source_cte);
    try std.testing.expectEqual(@as(usize, 1), direct_select.query.select.len);
    try std.testing.expectEqualStrings("id", direct_select.query.select[0]);
    try std.testing.expectEqual(@as(usize, 1), direct_select.query.order_by.len);
    try std.testing.expectEqualStrings("created_at", direct_select.query.order_by[0].field);
    try std.testing.expectEqual(@as(u32, 5), direct_select.query.limit.?);

    var plain = try lowerQueryPlanAlloc(
        alloc,
        "SELECT id FROM orders WHERE status = 'open'",
        schema,
        &.{},
    );
    defer plain.deinit(alloc);
    try std.testing.expectEqualStrings("orders", plain.table_name);
    try std.testing.expectEqual(@as(usize, 0), plain.plan.ctes.len);
    try std.testing.expectEqual(@as(usize, 1), plain.plan.query.predicates.len);

    try std.testing.expectError(error.UnsupportedSqlShape, lowerQueryPlanAlloc(
        alloc,
        "WITH early AS (SELECT id FROM later), later AS (SELECT id FROM orders) SELECT id FROM early",
        schema,
        &.{},
    ));
    try std.testing.expectError(error.UnsupportedSqlShape, lowerQueryPlanAlloc(
        alloc,
        "WITH ids_only AS (SELECT id FROM orders) SELECT amount FROM ids_only",
        schema,
        &.{},
    ));
    try std.testing.expectError(error.UnsupportedSqlShape, lowerQueryPlanAlloc(
        alloc,
        "WITH ids_only AS (SELECT id FROM orders), bad AS (SELECT amount FROM ids_only) SELECT amount FROM bad",
        schema,
        &.{},
    ));
}

test "postgres sql adapter lowers direct select set operation query plans" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"status":{"type":"keyword"},"enabled":{"type":"boolean"},"amount":{"type":"numeric"},"created_at":{"type":"datetime"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);

    var disjoint_union = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE status = 'open' UNION ALL SELECT id FROM usage_records WHERE status = 'closed' ORDER BY id ASC LIMIT 5 OFFSET 2",
        schema,
        &.{},
    );
    defer disjoint_union.deinit(alloc);
    try std.testing.expectEqualStrings("usage_records", disjoint_union.table_name);
    try std.testing.expectEqual(@as(usize, 0), disjoint_union.ctes.len);
    try std.testing.expectEqual(@as(usize, 0), disjoint_union.query.predicates.len);
    try std.testing.expectEqual(@as(usize, 2), disjoint_union.query.or_predicates.len);
    try std.testing.expectEqualStrings("status", disjoint_union.query.or_predicates[0].predicates[0].field);
    try std.testing.expectEqualStrings("\"open\"", disjoint_union.query.or_predicates[0].predicates[0].value_json.?);
    try std.testing.expectEqualStrings("\"closed\"", disjoint_union.query.or_predicates[1].predicates[0].value_json.?);
    try std.testing.expectEqual(@as(usize, 1), disjoint_union.query.order_by.len);
    try std.testing.expectEqualStrings("id", disjoint_union.query.order_by[0].field);
    try std.testing.expectEqual(@as(u32, 5), disjoint_union.query.limit.?);
    try std.testing.expectEqual(@as(u32, 2), disjoint_union.query.offset);

    var except = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records EXCEPT SELECT id FROM usage_records WHERE status = 'deleted'",
        schema,
        &.{},
    );
    defer except.deinit(alloc);
    try std.testing.expectEqualStrings("usage_records", except.table_name);
    try std.testing.expectEqual(@as(usize, 1), except.query.not_predicates.len);
    try std.testing.expectEqualStrings("status", except.query.not_predicates[0].predicates[0].field);
    try std.testing.expectEqualStrings("\"deleted\"", except.query.not_predicates[0].predicates[0].value_json.?);

    var mixed_except = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE enabled IS TRUE EXCEPT SELECT id FROM usage_records WHERE status = 'deleted' AND lower(status) = 'archived'",
        schema,
        &.{},
    );
    defer mixed_except.deinit(alloc);
    try std.testing.expectEqualStrings("usage_records", mixed_except.table_name);
    try std.testing.expectEqual(@as(usize, 1), mixed_except.query.predicates.len);
    try std.testing.expectEqualStrings("enabled", mixed_except.query.predicates[0].field);
    try std.testing.expectEqual(@as(usize, 0), mixed_except.query.not_predicates.len);
    try std.testing.expectEqual(@as(usize, 1), mixed_except.query.expression_not_predicates.len);
    try std.testing.expectEqual(@as(usize, 2), mixed_except.query.expression_not_predicates[0].conditions.len);
    try std.testing.expectEqualStrings("status", mixed_except.query.expression_not_predicates[0].conditions[0].lhs.field);
    try std.testing.expectEqualStrings("\"deleted\"", mixed_except.query.expression_not_predicates[0].conditions[0].rhs[0].value_json);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.lower, mixed_except.query.expression_not_predicates[0].conditions[1].lhs.kind);
    try std.testing.expectEqualStrings("\"archived\"", mixed_except.query.expression_not_predicates[0].conditions[1].rhs[0].value_json);

    try std.testing.expectError(error.UnsupportedSqlShape, lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE status = 'open' UNION ALL SELECT id FROM usage_records WHERE enabled IS TRUE",
        schema,
        &.{},
    ));
}

test "postgres sql adapter lowers non recursive cte aggregate plans" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"tenant":{"type":"keyword"},"status":{"type":"keyword"},"amount":{"type":"numeric"},"created_at":{"type":"numeric"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
