test "postgres sql adapter lowers non recursive cte join and lateral plans" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"kind":{"type":"keyword"},"tenant":{"type":"keyword"},"id":{"type":"keyword"},"organization_id":{"type":"keyword"},"customer_id":{"type":"keyword"},"status":{"type":"keyword"},"amount":{"type":"numeric"},"created_at":{"type":"numeric"},"name":{"type":"keyword"}},"required":["kind","tenant","id"],"additionalProperties":false}}},"primary_key":{"columns":["kind","tenant","id"]}}
    ;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);

    var join = try lowerJoinAlloc(
        alloc,
        "WITH open_orders AS (SELECT id, tenant, customer_id, amount FROM usage_records WHERE kind = 'order'), active_customers AS (SELECT id, tenant, name FROM usage_records WHERE kind = 'customer') SELECT o.id AS order_id, c.name AS customer_name FROM open_orders AS o LEFT JOIN active_customers AS c ON o.tenant = c.tenant AND o.customer_id = c.id ORDER BY order_id ASC LIMIT 3",
        schema,
        &.{},
    );
    defer join.deinit(alloc);
    try std.testing.expectEqualStrings("usage_records", join.left_table_name);
    try std.testing.expectEqualStrings("usage_records", join.right_table_name);
    const join_plan = join.asPlan();
    try std.testing.expectEqualStrings("usage_records", join_plan.left_table);
    try std.testing.expectEqualStrings("usage_records", join_plan.right_table);
    try std.testing.expectEqual(@as(usize, 2), join.ctes.len);
    try std.testing.expectEqualStrings("open_orders", join.ctes[0].name);
    try std.testing.expectEqualStrings("active_customers", join.ctes[1].name);
    try std.testing.expectEqualStrings("open_orders", join.join.left.source_cte);
    try std.testing.expectEqualStrings("active_customers", join.join.right.source_cte);
    try std.testing.expectEqual(@as(usize, 2), join.join.on.len);
    try std.testing.expectEqualStrings("tenant", join.join.on[0].left_field);
    try std.testing.expectEqualStrings("tenant", join.join.on[0].right_field);
    try std.testing.expectEqualStrings("customer_id", join.join.on[1].left_field);
    try std.testing.expectEqualStrings("id", join.join.on[1].right_field);
    try std.testing.expectEqual(@as(usize, 2), join.join.select.len);
    try std.testing.expectEqualStrings("order_id", join.join.select[0].output);
    try std.testing.expectEqual(@as(u32, 3), join.join.limit.?);

    var read_join = try lowerReadPlanAlloc(
        alloc,
        "WITH open_orders AS (SELECT id, tenant, customer_id FROM usage_records WHERE kind = 'order'), active_customers AS (SELECT id, tenant, name FROM usage_records WHERE kind = 'customer') SELECT o.id AS order_id, c.name AS customer_name FROM open_orders AS o LEFT JOIN active_customers AS c ON o.tenant = c.tenant AND o.customer_id = c.id ORDER BY order_id ASC LIMIT 3",
        schema,
        &.{},
    );
    defer read_join.deinit(alloc);
    switch (read_join) {
        .join => |lowered| {
            try std.testing.expectEqual(@as(usize, 2), lowered.ctes.len);
            try std.testing.expectEqualStrings("open_orders", lowered.join.left.source_cte);
            try std.testing.expectEqualStrings("active_customers", lowered.join.right.source_cte);
        },
        else => return error.TestUnexpectedResult,
    }

    var lateral = try lowerLateralPlanAlloc(
        alloc,
        "WITH orgs AS (SELECT id, kind FROM usage_records WHERE kind = 'organization'), balances AS (SELECT organization_id, amount, created_at, kind FROM usage_records WHERE kind = 'balance') SELECT org.id AS organization_id, latest.amount AS latest_amount FROM orgs AS org LEFT JOIN LATERAL (SELECT amount, created_at FROM balances AS bal WHERE bal.organization_id = org.id ORDER BY 2 DESC LIMIT 1) AS latest ON true ORDER BY 1 ASC LIMIT 5",
        schema,
        &.{},
    );
    defer lateral.deinit(alloc);
    try std.testing.expectEqualStrings("usage_records", lateral.left_table_name);
    try std.testing.expectEqualStrings("usage_records", lateral.right_table_name);
    try std.testing.expectEqualStrings("usage_records", lateral.plan.left_table);
    try std.testing.expectEqualStrings("usage_records", lateral.plan.right_table);
    try std.testing.expectEqual(@as(usize, 2), lateral.plan.ctes.len);
    try std.testing.expectEqualStrings("orgs", lateral.plan.lateral.left.source_cte);
    try std.testing.expectEqualStrings("balances", lateral.plan.lateral.right.source_cte);
    try std.testing.expectEqual(@as(usize, 1), lateral.plan.lateral.correlations.len);
    try std.testing.expectEqualStrings("id", lateral.plan.lateral.correlations[0].left_field);
    try std.testing.expectEqualStrings("organization_id", lateral.plan.lateral.correlations[0].right_field);
    try std.testing.expectEqual(@as(u32, 1), lateral.plan.lateral.right.limit.?);
    try std.testing.expectEqual(@as(u32, 5), lateral.plan.lateral.limit.?);

    try std.testing.expectError(error.UnsupportedSqlShape, lowerJoinAlloc(
        alloc,
        "WITH ids_only AS (SELECT id FROM usage_records) SELECT o.id AS order_id, c.id AS customer_id FROM ids_only AS o LEFT JOIN usage_records AS c ON o.tenant = c.tenant",
        schema,
        &.{},
    ));
    try std.testing.expectError(error.UnsupportedSqlShape, lowerLateralPlanAlloc(
        alloc,
        "WITH ids_only AS (SELECT id FROM usage_records) SELECT org.id AS organization_id, latest.amount AS latest_amount FROM ids_only AS org LEFT JOIN LATERAL (SELECT amount FROM usage_records AS bal WHERE bal.organization_id = org.tenant LIMIT 1) AS latest ON true",
        schema,
        &.{},
    ));
}

test "postgres sql adapter classifies read sql into typed plan families" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"kind":{"type":"keyword"},"tenant":{"type":"keyword"},"id":{"type":"keyword"},"organization_id":{"type":"keyword"},"customer_id":{"type":"keyword"},"status":{"type":"keyword"},"amount":{"type":"numeric"},"created_at":{"type":"numeric"},"name":{"type":"keyword"}},"required":["kind","tenant","id"],"additionalProperties":false}}},"primary_key":{"columns":["kind","tenant","id"]}}
    ;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);

    var query = try lowerReadPlanAlloc(
        alloc,
        "SELECT id, status FROM usage_records WHERE kind = 'order' ORDER BY created_at DESC LIMIT 5",
        schema,
        &.{},
    );
    defer query.deinit(alloc);
    switch (query) {
        .query => |lowered| {
            try std.testing.expectEqualStrings("usage_records", lowered.table_name);
            try std.testing.expectEqual(@as(usize, 1), lowered.plan.query.predicates.len);
        },
        else => return error.TestUnexpectedResult,
    }

    var aggregate = try lowerReadPlanAlloc(
        alloc,
        "SELECT status, SUM(amount) AS total FROM usage_records WHERE kind = 'order' GROUP BY status ORDER BY total DESC LIMIT 5",
        schema,
        &.{},
    );
    defer aggregate.deinit(alloc);
    switch (aggregate) {
        .aggregate => |lowered| {
            try std.testing.expectEqualStrings("usage_records", lowered.table_name);
            try std.testing.expectEqual(@as(usize, 0), lowered.plan.ctes.len);
            try std.testing.expectEqual(@as(usize, 1), lowered.plan.aggregate.aggregations.len);
            try std.testing.expectEqual(db_mod.types.RelationalRowsAggregateOp.sum, lowered.plan.aggregate.aggregations[0].op);
        },
        else => return error.TestUnexpectedResult,
    }

    var cte_aggregate = try lowerReadPlanAlloc(
        alloc,
        "WITH open_usage AS (SELECT tenant, amount, status FROM usage_records WHERE status = 'open') SELECT tenant, SUM(amount) AS total FROM open_usage GROUP BY tenant ORDER BY total DESC LIMIT 5",
        schema,
        &.{},
    );
    defer cte_aggregate.deinit(alloc);
    switch (cte_aggregate) {
        .aggregate => |lowered| {
            try std.testing.expectEqualStrings("usage_records", lowered.table_name);
            try std.testing.expectEqual(@as(usize, 1), lowered.plan.ctes.len);
            try std.testing.expectEqualStrings("open_usage", lowered.plan.aggregate.source.source_cte);
            try std.testing.expectEqual(@as(usize, 1), lowered.plan.aggregate.aggregations.len);
        },
        else => return error.TestUnexpectedResult,
    }

    var join = try lowerReadPlanAlloc(
        alloc,
        "SELECT o.id AS order_id, c.name AS customer_name FROM usage_records AS o LEFT JOIN usage_records AS c ON o.tenant = c.tenant AND o.customer_id = c.id WHERE o.kind = 'order' AND c.kind = 'customer' ORDER BY order_id ASC LIMIT 5",
        schema,
        &.{},
    );
    defer join.deinit(alloc);
    switch (join) {
        .join => |lowered| {
            try std.testing.expectEqualStrings("usage_records", lowered.left_table_name);
            try std.testing.expectEqualStrings("usage_records", lowered.right_table_name);
            try std.testing.expectEqual(@as(usize, 2), lowered.join.on.len);
            try std.testing.expectEqual(@as(usize, 2), lowered.join.select.len);
        },
        else => return error.TestUnexpectedResult,
    }

    var lateral = try lowerReadPlanAlloc(
        alloc,
        "SELECT org.id AS organization_id, latest.amount AS latest_amount FROM usage_records AS org LEFT JOIN LATERAL (SELECT amount, created_at FROM usage_records AS bal WHERE bal.organization_id = org.id AND bal.kind = 'balance' ORDER BY 2 DESC LIMIT 1) AS latest ON true WHERE org.kind = 'organization' ORDER BY latest_amount DESC LIMIT 10",
        schema,
        &.{},
    );
    defer lateral.deinit(alloc);
    switch (lateral) {
        .lateral => |lowered| {
            try std.testing.expectEqualStrings("usage_records", lowered.left_table_name);
            try std.testing.expectEqual(@as(usize, 1), lowered.plan.lateral.correlations.len);
        },
        else => return error.TestUnexpectedResult,
    }

    var window = try lowerReadPlanAlloc(
        alloc,
        "SELECT tenant, id, row_number() OVER (PARTITION BY tenant ORDER BY amount DESC, id ASC) AS row_num FROM usage_records WHERE status = 'open' ORDER BY row_num ASC LIMIT 5",
        schema,
        &.{},
    );
    defer window.deinit(alloc);
    switch (window) {
        .window => |lowered| {
            try std.testing.expectEqualStrings("usage_records", lowered.table_name);
            try std.testing.expectEqual(@as(usize, 1), lowered.plan.window.windows.len);
        },
        else => return error.TestUnexpectedResult,
    }
}

test "postgres sql adapter typed read plans execute through relational storage" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"kind":{"type":"keyword"},"tenant":{"type":"keyword"},"id":{"type":"keyword"},"customer_id":{"type":"keyword"},"organization_id":{"type":"keyword"},"status":{"type":"keyword"},"name":{"type":"keyword"},"amount":{"type":"numeric"},"created_at":{"type":"numeric"}},"required":["kind","tenant","id"],"additionalProperties":false}}},"primary_key":{"columns":["kind","tenant","id"]}}
    ;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);

    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    const path = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/sql-read-plan-execution", .{tmp.sub_path});
    defer alloc.free(path);

    var db = try db_mod.DB.open(alloc, path, .{});
    defer db.close();
    try db.applyTableSchemaJson(alloc, schema_json, .{});

    try db.batch(.{
        .writes = &.{
            .{ .key = "row:c1", .value = "{\"kind\":\"customer\",\"tenant\":\"t1\",\"id\":\"c1\",\"name\":\"Alice\"}" },
            .{ .key = "row:c2", .value = "{\"kind\":\"customer\",\"tenant\":\"t1\",\"id\":\"c2\",\"name\":\"Bob\"}" },
            .{ .key = "row:o1", .value = "{\"kind\":\"order\",\"tenant\":\"t1\",\"id\":\"o1\",\"customer_id\":\"c1\",\"status\":\"open\",\"amount\":10}" },
            .{ .key = "row:o2", .value = "{\"kind\":\"order\",\"tenant\":\"t1\",\"id\":\"o2\",\"customer_id\":\"missing\",\"status\":\"open\",\"amount\":5}" },
            .{ .key = "row:o3", .value = "{\"kind\":\"order\",\"tenant\":\"t2\",\"id\":\"o3\",\"customer_id\":\"c1\",\"status\":\"open\",\"amount\":7}" },
            .{ .key = "row:p1", .value = "{\"kind\":\"pattern\",\"tenant\":\"t1\",\"id\":\"p1\",\"status\":\"op_en\"}" },
            .{ .key = "row:p2", .value = "{\"kind\":\"pattern\",\"tenant\":\"t1\",\"id\":\"p2\",\"status\":\"open\"}" },
            .{ .key = "row:p3", .value = "{\"kind\":\"pattern\",\"tenant\":\"t1\",\"id\":\"p3\",\"status\":\"OP_en\"}" },
            .{ .key = "row:org1", .value = "{\"kind\":\"organization\",\"tenant\":\"t1\",\"id\":\"org1\"}" },
            .{ .key = "row:org2", .value = "{\"kind\":\"organization\",\"tenant\":\"t1\",\"id\":\"org2\"}" },
            .{ .key = "row:org3", .value = "{\"kind\":\"organization\",\"tenant\":\"t1\",\"id\":\"org3\"}" },
            .{ .key = "row:b1", .value = "{\"kind\":\"balance\",\"tenant\":\"t1\",\"id\":\"b1\",\"organization_id\":\"org1\",\"amount\":4,\"created_at\":10}" },
            .{ .key = "row:b2", .value = "{\"kind\":\"balance\",\"tenant\":\"t1\",\"id\":\"b2\",\"organization_id\":\"org1\",\"amount\":9,\"created_at\":20}" },
            .{ .key = "row:b3", .value = "{\"kind\":\"balance\",\"tenant\":\"t1\",\"id\":\"b3\",\"organization_id\":\"org2\",\"amount\":7,\"created_at\":15}" },
        },
        .sync_level = .write,
    });

    var escaped_pattern_plan = try lowerReadPlanAlloc(
        alloc,
        "SELECT id, status FROM usage_records WHERE kind = 'pattern' AND status ILIKE $1 ESCAPE $2 ORDER BY id",
        schema,
        &.{ .{ .string = "OP!_%" }, .{ .string = "!" } },
    );
    defer escaped_pattern_plan.deinit(alloc);

    switch (escaped_pattern_plan) {
        .query => |lowered| {
            try std.testing.expectEqual(@as(usize, 1), lowered.plan.query.predicates.len);
            try std.testing.expectEqual(@as(usize, 1), lowered.plan.query.text_patterns.len);
            try std.testing.expectEqualStrings("OP\\_%", lowered.plan.query.text_patterns[0].pattern);
            try std.testing.expect(lowered.plan.query.text_patterns[0].case_insensitive);
            var result = try db.queryRelationalRows(alloc, schema, lowered.plan.query);
            defer result.deinit(alloc);

            try std.testing.expectEqual(@as(u32, 2), result.total);
            try std.testing.expectEqual(@as(usize, 2), result.rows.len);
            try std.testing.expectEqualStrings("{\"id\":\"p1\",\"status\":\"op_en\"}", result.rows[0]);
            try std.testing.expectEqualStrings("{\"id\":\"p3\",\"status\":\"OP_en\"}", result.rows[1]);
        },
        else => return error.TestUnexpectedResult,
    }

    var computed_pattern_plan = try lowerReadPlanAlloc(
        alloc,
        "SELECT id, status FROM usage_records WHERE kind = 'pattern' AND lower(status) LIKE $1 ESCAPE $2 ORDER BY id",
        schema,
        &.{ .{ .string = "%!_en" }, .{ .string = "!" } },
    );
    defer computed_pattern_plan.deinit(alloc);

    switch (computed_pattern_plan) {
        .query => |lowered| {
            try std.testing.expectEqual(@as(usize, 1), lowered.plan.query.predicates.len);
            try std.testing.expectEqual(@as(usize, 1), lowered.plan.query.expression_predicates.len);
            try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.like, lowered.plan.query.expression_predicates[0].lhs.kind);
            var result = try db.queryRelationalRows(alloc, schema, lowered.plan.query);
            defer result.deinit(alloc);

            try std.testing.expectEqual(@as(u32, 2), result.total);
            try std.testing.expectEqual(@as(usize, 2), result.rows.len);
            try std.testing.expectEqualStrings("{\"id\":\"p1\",\"status\":\"op_en\"}", result.rows[0]);
            try std.testing.expectEqualStrings("{\"id\":\"p3\",\"status\":\"OP_en\"}", result.rows[1]);
        },
        else => return error.TestUnexpectedResult,
    }

    var regexp_match_plan = try lowerReadPlanAlloc(
        alloc,
        "SELECT id, status FROM usage_records WHERE kind = 'pattern' AND status ~ $1 AND status !~* 'closed' ORDER BY id",
        schema,
        &.{.{ .string = "^op" }},
    );
    defer regexp_match_plan.deinit(alloc);

    switch (regexp_match_plan) {
        .query => |lowered| {
            try std.testing.expectEqual(@as(usize, 1), lowered.plan.query.predicates.len);
            try std.testing.expectEqual(@as(usize, 2), lowered.plan.query.expression_predicates.len);
            try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.regexp_match, lowered.plan.query.expression_predicates[0].lhs.kind);
            try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.regexp_match, lowered.plan.query.expression_predicates[1].lhs.kind);
            var result = try db.queryRelationalRows(alloc, schema, lowered.plan.query);
            defer result.deinit(alloc);

            try std.testing.expectEqual(@as(u32, 2), result.total);
            try std.testing.expectEqual(@as(usize, 2), result.rows.len);
            try std.testing.expectEqualStrings("{\"id\":\"p1\",\"status\":\"op_en\"}", result.rows[0]);
            try std.testing.expectEqualStrings("{\"id\":\"p2\",\"status\":\"open\"}", result.rows[1]);
        },
        else => return error.TestUnexpectedResult,
    }

    var regexp_like_plan = try lowerReadPlanAlloc(
        alloc,
        "SELECT id, regexp_like(status, $2, true) AS matches_suffix FROM usage_records WHERE kind = 'pattern' AND regexp_like(status, $1) ORDER BY id",
        schema,
        &.{ .{ .string = "^op" }, .{ .string = "_EN$" } },
    );
    defer regexp_like_plan.deinit(alloc);

    switch (regexp_like_plan) {
        .query => |lowered| {
            try std.testing.expectEqual(@as(usize, 1), lowered.plan.query.predicates.len);
            try std.testing.expectEqual(@as(usize, 1), lowered.plan.query.expression_predicates.len);
            try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.regexp_match, lowered.plan.query.expression_predicates[0].lhs.kind);
            try std.testing.expectEqual(@as(usize, 1), lowered.plan.query.expressions.len);
            try std.testing.expectEqualStrings("matches_suffix", lowered.plan.query.expressions[0].output);
            try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.regexp_match, lowered.plan.query.expressions[0].expression.kind);
            try std.testing.expectEqual(@as(usize, 3), lowered.plan.query.expressions[0].expression.operands.len);
            var result = try db.queryRelationalRows(alloc, schema, lowered.plan.query);
            defer result.deinit(alloc);

            try std.testing.expectEqual(@as(u32, 2), result.total);
            try std.testing.expectEqual(@as(usize, 2), result.rows.len);
            try std.testing.expectEqualStrings("{\"id\":\"p1\",\"matches_suffix\":true}", result.rows[0]);
            try std.testing.expectEqualStrings("{\"id\":\"p2\",\"matches_suffix\":false}", result.rows[1]);
        },
        else => return error.TestUnexpectedResult,
    }

    var computed_pattern_any_plan = try lowerReadPlanAlloc(
        alloc,
        "SELECT id, status FROM usage_records WHERE kind = 'pattern' AND lower(status) LIKE ANY(ARRAY['op_en', 'open']) ORDER BY id",
        schema,
        &.{},
    );
    defer computed_pattern_any_plan.deinit(alloc);

    switch (computed_pattern_any_plan) {
        .query => |lowered| {
            try std.testing.expectEqual(@as(usize, 1), lowered.plan.query.predicates.len);
            try std.testing.expectEqual(@as(usize, 1), lowered.plan.query.expression_predicates.len);
            try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.bool_or, lowered.plan.query.expression_predicates[0].lhs.kind);
            var result = try db.queryRelationalRows(alloc, schema, lowered.plan.query);
            defer result.deinit(alloc);

            try std.testing.expectEqual(@as(u32, 3), result.total);
            try std.testing.expectEqual(@as(usize, 3), result.rows.len);
            try std.testing.expectEqualStrings("{\"id\":\"p1\",\"status\":\"op_en\"}", result.rows[0]);
            try std.testing.expectEqualStrings("{\"id\":\"p2\",\"status\":\"open\"}", result.rows[1]);
            try std.testing.expectEqualStrings("{\"id\":\"p3\",\"status\":\"OP_en\"}", result.rows[2]);
        },
        else => return error.TestUnexpectedResult,
    }

    var mixed_except_plan = try lowerReadPlanAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE kind = 'order' EXCEPT SELECT id FROM usage_records WHERE status = 'open' AND lower(tenant) = 't1' ORDER BY id ASC",
        schema,
        &.{},
    );
    defer mixed_except_plan.deinit(alloc);

    switch (mixed_except_plan) {
        .query => |lowered| {
            try std.testing.expectEqual(@as(usize, 1), lowered.plan.query.predicates.len);
            try std.testing.expectEqual(@as(usize, 1), lowered.plan.query.expression_not_predicates.len);
            try std.testing.expectEqual(@as(usize, 2), lowered.plan.query.expression_not_predicates[0].conditions.len);
            var result = try db.queryRelationalRows(alloc, schema, lowered.plan.query);
            defer result.deinit(alloc);

            try std.testing.expectEqual(@as(u32, 1), result.total);
            try std.testing.expectEqual(@as(usize, 1), result.rows.len);
            try std.testing.expectEqualStrings("{\"id\":\"o3\"}", result.rows[0]);
        },
        else => return error.TestUnexpectedResult,
    }

    var join_plan = try lowerReadPlanAlloc(
        alloc,
        "SELECT o.id AS order_id, c.name AS customer_name, o.amount AS amount FROM usage_records AS o LEFT JOIN usage_records AS c ON o.tenant = c.tenant AND o.customer_id = c.id WHERE o.kind = 'order' ORDER BY amount DESC LIMIT 10",
        schema,
        &.{},
    );
    defer join_plan.deinit(alloc);

    switch (join_plan) {
        .join => |lowered| {
            try std.testing.expectEqual(db_mod.types.RelationalRowsJoinType.left, lowered.join.join_type);
            var result = try db.joinRelationalRows(alloc, schema, lowered.join);
            defer result.deinit(alloc);

            try std.testing.expectEqual(@as(u32, 3), result.total_rows);
            try std.testing.expectEqual(@as(usize, 3), result.rows.len);
            try std.testing.expectEqualStrings("{\"order_id\":\"o1\",\"customer_name\":\"Alice\",\"amount\":10}", result.rows[0]);
            try std.testing.expectEqualStrings("{\"order_id\":\"o3\",\"customer_name\":null,\"amount\":7}", result.rows[1]);
            try std.testing.expectEqualStrings("{\"order_id\":\"o2\",\"customer_name\":null,\"amount\":5}", result.rows[2]);
        },
        else => return error.TestUnexpectedResult,
    }

    var aggregate_plan = try lowerReadPlanAlloc(
        alloc,
        "WITH open_usage AS (SELECT tenant, id, amount, status FROM usage_records WHERE kind = 'order' AND status = 'open') SELECT tenant, SUM(amount) AS total_amount, string_agg(id, '|' ORDER BY amount DESC) AS order_ids FROM open_usage GROUP BY tenant ORDER BY total_amount DESC LIMIT 5",
        schema,
        &.{},
    );
    defer aggregate_plan.deinit(alloc);

    switch (aggregate_plan) {
        .aggregate => |lowered| {
            try std.testing.expectEqual(@as(usize, 1), lowered.plan.ctes.len);
            try std.testing.expectEqualStrings("open_usage", lowered.plan.aggregate.source.source_cte);
            var result = try db.aggregateRelationalRowsPlan(alloc, schema, lowered.plan);
            defer result.deinit(alloc);

            try std.testing.expectEqual(@as(u32, 2), result.total_groups);
            try std.testing.expectEqual(@as(usize, 2), result.rows.len);
            try std.testing.expectEqualStrings("{\"tenant\":\"t1\",\"total_amount\":15,\"order_ids\":\"o1|o2\"}", result.rows[0]);
            try std.testing.expectEqualStrings("{\"tenant\":\"t2\",\"total_amount\":7,\"order_ids\":\"o3\"}", result.rows[1]);
        },
        else => return error.TestUnexpectedResult,
    }

    var window_plan = try lowerReadPlanAlloc(
        alloc,
        "SELECT tenant, id, row_number() OVER (PARTITION BY tenant ORDER BY amount DESC, id ASC) AS row_num FROM usage_records WHERE kind = 'order' ORDER BY row_num ASC, id ASC LIMIT 10",
        schema,
        &.{},
    );
    defer window_plan.deinit(alloc);

    switch (window_plan) {
        .window => |lowered| {
            var result = try db.windowRelationalRowsPlan(alloc, schema, lowered.plan);
            defer result.deinit(alloc);

            try std.testing.expectEqual(@as(u32, 3), result.total_rows);
            try std.testing.expectEqual(@as(usize, 3), result.rows.len);
            try std.testing.expectEqualStrings("{\"tenant\":\"t1\",\"id\":\"o1\",\"row_num\":1}", result.rows[0]);
            try std.testing.expectEqualStrings("{\"tenant\":\"t2\",\"id\":\"o3\",\"row_num\":1}", result.rows[1]);
            try std.testing.expectEqualStrings("{\"tenant\":\"t1\",\"id\":\"o2\",\"row_num\":2}", result.rows[2]);
        },
        else => return error.TestUnexpectedResult,
    }

    var unordered_count_window_plan = try lowerReadPlanAlloc(
        alloc,
        "SELECT id, count(*) OVER () AS total_orders FROM usage_records WHERE kind = 'order' ORDER BY id ASC",
        schema,
        &.{},
    );
    defer unordered_count_window_plan.deinit(alloc);

    switch (unordered_count_window_plan) {
        .window => |lowered| {
            var result = try db.windowRelationalRowsPlan(alloc, schema, lowered.plan);
            defer result.deinit(alloc);

            try std.testing.expectEqual(@as(u32, 3), result.total_rows);
            try std.testing.expectEqual(@as(usize, 3), result.rows.len);
            try std.testing.expectEqualStrings("{\"id\":\"o1\",\"total_orders\":3}", result.rows[0]);
            try std.testing.expectEqualStrings("{\"id\":\"o2\",\"total_orders\":3}", result.rows[1]);
            try std.testing.expectEqualStrings("{\"id\":\"o3\",\"total_orders\":3}", result.rows[2]);
        },
        else => return error.TestUnexpectedResult,
    }

    var unordered_partition_window_plan = try lowerReadPlanAlloc(
        alloc,
        "SELECT tenant, id, sum(amount) OVER (PARTITION BY tenant) AS tenant_amount FROM usage_records WHERE kind = 'order' ORDER BY id ASC",
        schema,
        &.{},
    );
    defer unordered_partition_window_plan.deinit(alloc);

    switch (unordered_partition_window_plan) {
        .window => |lowered| {
            var result = try db.windowRelationalRowsPlan(alloc, schema, lowered.plan);
            defer result.deinit(alloc);

            try std.testing.expectEqual(@as(u32, 3), result.total_rows);
            try std.testing.expectEqual(@as(usize, 3), result.rows.len);
            try std.testing.expectEqualStrings("{\"tenant\":\"t1\",\"id\":\"o1\",\"tenant_amount\":15}", result.rows[0]);
            try std.testing.expectEqualStrings("{\"tenant\":\"t1\",\"id\":\"o2\",\"tenant_amount\":15}", result.rows[1]);
            try std.testing.expectEqualStrings("{\"tenant\":\"t2\",\"id\":\"o3\",\"tenant_amount\":7}", result.rows[2]);
        },
        else => return error.TestUnexpectedResult,
    }

    var following_rows_window_plan = try lowerReadPlanAlloc(
        alloc,
        "SELECT id, count(*) OVER (ORDER BY amount DESC, id ASC ROWS BETWEEN CURRENT ROW AND 1 FOLLOWING) AS current_and_next FROM usage_records WHERE kind = 'order' ORDER BY current_and_next DESC, id ASC",
        schema,
        &.{},
    );
    defer following_rows_window_plan.deinit(alloc);

    switch (following_rows_window_plan) {
        .window => |lowered| {
            var result = try db.windowRelationalRowsPlan(alloc, schema, lowered.plan);
            defer result.deinit(alloc);

            try std.testing.expectEqual(@as(u32, 3), result.total_rows);
            try std.testing.expectEqual(@as(usize, 3), result.rows.len);
            try std.testing.expectEqualStrings("{\"id\":\"o1\",\"current_and_next\":2}", result.rows[0]);
            try std.testing.expectEqualStrings("{\"id\":\"o3\",\"current_and_next\":2}", result.rows[1]);
            try std.testing.expectEqualStrings("{\"id\":\"o2\",\"current_and_next\":1}", result.rows[2]);
        },
        else => return error.TestUnexpectedResult,
    }

    var lateral_plan = try lowerReadPlanAlloc(
        alloc,
        "SELECT org.id AS organization_id, latest.amount AS latest_amount, latest.created_at AS latest_created_at FROM usage_records AS org LEFT JOIN LATERAL (SELECT amount, created_at FROM usage_records AS bal WHERE bal.organization_id = org.id AND bal.kind = 'balance' ORDER BY 2 DESC LIMIT 1) AS latest ON true WHERE org.kind = 'organization' ORDER BY latest_amount DESC NULLS LAST LIMIT 10",
        schema,
        &.{},
    );
    defer lateral_plan.deinit(alloc);

    switch (lateral_plan) {
        .lateral => |lowered| {
            var result = try db.lateralRelationalRowsPlan(alloc, schema, lowered.plan);
            defer result.deinit(alloc);

            try std.testing.expectEqual(@as(u32, 3), result.total_rows);
            try std.testing.expectEqual(@as(usize, 3), result.rows.len);
            try std.testing.expectEqualStrings("{\"organization_id\":\"org1\",\"latest_amount\":9,\"latest_created_at\":20}", result.rows[0]);
            try std.testing.expectEqualStrings("{\"organization_id\":\"org2\",\"latest_amount\":7,\"latest_created_at\":15}", result.rows[1]);
            try std.testing.expectEqualStrings("{\"organization_id\":\"org3\",\"latest_amount\":null,\"latest_created_at\":null}", result.rows[2]);
        },
        else => return error.TestUnexpectedResult,
    }
}

test "postgres sql adapter lowers row_number window query plans" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"tenant":{"type":"keyword"},"id":{"type":"keyword"},"status":{"type":"keyword"},"enabled":{"type":"boolean"},"amount":{"type":"numeric"},"created_at":{"type":"numeric"}},"required":["tenant","id"],"additionalProperties":false}}},"primary_key":{"columns":["tenant","id"]}}
    ;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);

    var lowered = try lowerWindowPlanAlloc(
        alloc,
        "SELECT tenant, id, row_number() OVER (PARTITION BY tenant ORDER BY amount DESC, id ASC) AS row_num FROM usage_records WHERE status = 'open' ORDER BY row_num ASC LIMIT 5",
        schema,
        &.{},
    );
    defer lowered.deinit(alloc);

    try std.testing.expectEqualStrings("usage_records", lowered.table_name);
    try std.testing.expectEqual(@as(usize, 0), lowered.plan.ctes.len);
    try std.testing.expectEqual(@as(usize, 1), lowered.plan.window.source.predicates.len);
    try std.testing.expectEqualStrings("status", lowered.plan.window.source.predicates[0].field);
    try std.testing.expectEqualStrings("\"open\"", lowered.plan.window.source.predicates[0].value_json.?);
    try std.testing.expectEqual(@as(usize, 2), lowered.plan.window.select.len);
    try std.testing.expectEqualStrings("tenant", lowered.plan.window.select[0]);
    try std.testing.expectEqualStrings("id", lowered.plan.window.select[1]);
    try std.testing.expectEqual(@as(usize, 1), lowered.plan.window.windows.len);
    try std.testing.expectEqual(db_mod.types.RelationalRowsWindowFunction.row_number, lowered.plan.window.windows[0].function);
    try std.testing.expectEqualStrings("row_num", lowered.plan.window.windows[0].output);
    try std.testing.expectEqual(@as(usize, 1), lowered.plan.window.windows[0].partition_by.len);
    try std.testing.expectEqualStrings("tenant", lowered.plan.window.windows[0].partition_by[0]);
    try std.testing.expectEqual(@as(usize, 2), lowered.plan.window.windows[0].order_by.len);
    try std.testing.expectEqualStrings("amount", lowered.plan.window.windows[0].order_by[0].field);
    try std.testing.expectEqual(db_mod.types.RelationalRowsQueryOrderDirection.desc, lowered.plan.window.windows[0].order_by[0].direction);
    try std.testing.expectEqualStrings("id", lowered.plan.window.windows[0].order_by[1].field);
    try std.testing.expectEqual(@as(usize, 1), lowered.plan.window.order_by.len);
    try std.testing.expectEqualStrings("row_num", lowered.plan.window.order_by[0].field);
    try std.testing.expectEqual(@as(u32, 5), lowered.plan.window.limit.?);

    var unordered_count = try lowerWindowPlanAlloc(
        alloc,
        "SELECT id, count(*) OVER () AS total_rows FROM usage_records WHERE status = 'open' ORDER BY id ASC LIMIT 5",
        schema,
        &.{},
    );
    defer unordered_count.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), unordered_count.plan.window.windows.len);
    try std.testing.expectEqual(db_mod.types.RelationalRowsWindowFunction.count, unordered_count.plan.window.windows[0].function);
    try std.testing.expectEqual(@as(usize, 0), unordered_count.plan.window.windows[0].partition_by.len);
    try std.testing.expectEqual(@as(usize, 0), unordered_count.plan.window.windows[0].order_by.len);
    try std.testing.expect(unordered_count.plan.window.windows[0].frame == null);
    try std.testing.expectEqualStrings("total_rows", unordered_count.plan.window.windows[0].output);

    var partition_only_sum = try lowerWindowPlanAlloc(
        alloc,
        "SELECT tenant, id, sum(amount) OVER usage_partition AS tenant_amount FROM usage_records WHERE status = 'open' WINDOW usage_partition AS (PARTITION BY tenant) ORDER BY tenant ASC, id ASC LIMIT 5",
        schema,
        &.{},
    );
    defer partition_only_sum.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), partition_only_sum.plan.window.windows.len);
    try std.testing.expectEqual(db_mod.types.RelationalRowsWindowFunction.sum, partition_only_sum.plan.window.windows[0].function);
    try std.testing.expectEqualStrings("tenant", partition_only_sum.plan.window.windows[0].partition_by[0]);
    try std.testing.expectEqual(@as(usize, 0), partition_only_sum.plan.window.windows[0].order_by.len);
    try std.testing.expectEqualStrings("tenant_amount", partition_only_sum.plan.window.windows[0].output);

    try std.testing.expectError(error.UnsupportedSqlShape, lowerWindowPlanAlloc(
        alloc,
        "SELECT id, rank() OVER () AS bad_rank FROM usage_records",
        schema,
        &.{},
    ));
    try std.testing.expectError(error.UnsupportedSqlShape, lowerWindowPlanAlloc(
        alloc,
        "SELECT id, sum(amount) OVER (ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) AS bad_sum FROM usage_records",
        schema,
        &.{},
    ));

    var named_window = try lowerWindowPlanAlloc(
        alloc,
        "SELECT tenant, id, row_number() OVER usage_window AS row_num, rank() OVER usage_window AS usage_rank FROM usage_records WHERE status = 'open' WINDOW usage_window AS (PARTITION BY tenant ORDER BY amount DESC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) ORDER BY row_num ASC LIMIT 5",
        schema,
        &.{},
    );
    defer named_window.deinit(alloc);
    try std.testing.expectEqualStrings("usage_records", named_window.table_name);
    try std.testing.expectEqual(@as(usize, 2), named_window.plan.window.windows.len);
    try std.testing.expectEqual(db_mod.types.RelationalRowsWindowFunction.row_number, named_window.plan.window.windows[0].function);
    try std.testing.expectEqual(db_mod.types.RelationalRowsWindowFunction.rank, named_window.plan.window.windows[1].function);
    try std.testing.expectEqualStrings("tenant", named_window.plan.window.windows[0].partition_by[0]);
    try std.testing.expectEqualStrings("tenant", named_window.plan.window.windows[1].partition_by[0]);
    try std.testing.expectEqualStrings("amount", named_window.plan.window.windows[0].order_by[0].field);
    try std.testing.expectEqualStrings("amount", named_window.plan.window.windows[1].order_by[0].field);
    try std.testing.expectEqual(db_mod.types.RelationalRowsWindowFrameUnit.rows, named_window.plan.window.windows[0].frame.?.unit);
    try std.testing.expectEqual(db_mod.types.RelationalRowsWindowFrameUnit.rows, named_window.plan.window.windows[1].frame.?.unit);
    try std.testing.expectEqualStrings("row_num", named_window.plan.window.order_by[0].field);

    var alias_source = try lowerWindowPlanAlloc(
        alloc,
        "SELECT u.tenant, u.id, row_number() OVER (PARTITION BY u.tenant ORDER BY u.amount DESC, u.id ASC) AS row_num FROM usage_records AS u WHERE u.status = 'open' ORDER BY row_num ASC LIMIT 5",
        schema,
        &.{},
    );
    defer alias_source.deinit(alloc);
    try std.testing.expectEqualStrings("usage_records", alias_source.table_name);
    try std.testing.expectEqual(@as(usize, 2), alias_source.plan.window.select.len);
    try std.testing.expectEqualStrings("tenant", alias_source.plan.window.select[0]);
    try std.testing.expectEqualStrings("id", alias_source.plan.window.select[1]);
    try std.testing.expectEqualStrings("tenant", alias_source.plan.window.windows[0].partition_by[0]);
    try std.testing.expectEqualStrings("amount", alias_source.plan.window.windows[0].order_by[0].field);
    try std.testing.expectEqualStrings("id", alias_source.plan.window.windows[0].order_by[1].field);
    try std.testing.expectEqual(@as(usize, 1), alias_source.plan.window.source.predicates.len);
    try std.testing.expectEqualStrings("status", alias_source.plan.window.source.predicates[0].field);
    try std.testing.expectEqualStrings("\"open\"", alias_source.plan.window.source.predicates[0].value_json.?);

    var ordinal_order = try lowerWindowPlanAlloc(
        alloc,
        "SELECT tenant, id, row_number() OVER (PARTITION BY tenant ORDER BY amount DESC, id ASC) AS row_num FROM usage_records WHERE status = 'open' ORDER BY 3 DESC NULLS FIRST LIMIT 5",
        schema,
        &.{},
    );
    defer ordinal_order.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 2), ordinal_order.plan.window.order_by.len);
    try std.testing.expectEqualStrings("row_num", ordinal_order.plan.window.order_by[0].field);
    try std.testing.expectEqual(db_mod.types.RelationalRowsQueryOrderNullTest.is_null, ordinal_order.plan.window.order_by[0].null_test.?);
    try std.testing.expectEqual(db_mod.types.RelationalRowsQueryOrderDirection.desc, ordinal_order.plan.window.order_by[0].direction);
    try std.testing.expectEqualStrings("row_num", ordinal_order.plan.window.order_by[1].field);
    try std.testing.expect(ordinal_order.plan.window.order_by[1].null_test == null);
    try std.testing.expectEqual(db_mod.types.RelationalRowsQueryOrderDirection.desc, ordinal_order.plan.window.order_by[1].direction);

    var expression_order = try lowerWindowPlanAlloc(
        alloc,
        "SELECT tenant, id, row_number() OVER (PARTITION BY tenant ORDER BY amount DESC, id ASC) AS row_num FROM usage_records WHERE status = 'open' ORDER BY (row_num + 1) DESC LIMIT 5",
        schema,
        &.{},
    );
    defer expression_order.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), expression_order.plan.window.order_by.len);
    try std.testing.expectEqualStrings("", expression_order.plan.window.order_by[0].field);
    try std.testing.expectEqual(db_mod.types.RelationalRowsQueryOrderDirection.desc, expression_order.plan.window.order_by[0].direction);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.add, expression_order.plan.window.order_by[0].expression.?.kind);
    try std.testing.expectEqual(@as(usize, 2), expression_order.plan.window.order_by[0].expression.?.operands.len);
    try std.testing.expectEqualStrings("row_num", expression_order.plan.window.order_by[0].expression.?.operands[0].field);

    var ranked = try lowerWindowPlanAlloc(
        alloc,
        "SELECT tenant, id, rank() OVER (PARTITION BY tenant ORDER BY amount DESC, id ASC) AS usage_rank, dense_rank() OVER (PARTITION BY tenant ORDER BY amount DESC, id ASC) AS usage_dense_rank FROM usage_records WHERE status = 'open' ORDER BY usage_rank ASC LIMIT 5",
        schema,
        &.{},
    );
    defer ranked.deinit(alloc);
    try std.testing.expectEqualStrings("usage_records", ranked.table_name);
    try std.testing.expectEqual(@as(usize, 2), ranked.plan.window.windows.len);
    try std.testing.expectEqual(db_mod.types.RelationalRowsWindowFunction.rank, ranked.plan.window.windows[0].function);
    try std.testing.expectEqualStrings("usage_rank", ranked.plan.window.windows[0].output);
    try std.testing.expectEqual(db_mod.types.RelationalRowsWindowFunction.dense_rank, ranked.plan.window.windows[1].function);
    try std.testing.expectEqualStrings("usage_dense_rank", ranked.plan.window.windows[1].output);
    try std.testing.expectEqual(@as(usize, 1), ranked.plan.window.order_by.len);
    try std.testing.expectEqualStrings("usage_rank", ranked.plan.window.order_by[0].field);

    var relative_ranked = try lowerWindowPlanAlloc(
        alloc,
        "SELECT tenant, id, percent_rank() OVER (PARTITION BY tenant ORDER BY amount DESC, id ASC) AS usage_percent_rank, cume_dist() OVER (PARTITION BY tenant ORDER BY amount DESC, id ASC) AS usage_cume_dist FROM usage_records WHERE status = 'open' ORDER BY usage_percent_rank ASC LIMIT 5",
        schema,
        &.{},
    );
    defer relative_ranked.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 2), relative_ranked.plan.window.windows.len);
    try std.testing.expectEqual(db_mod.types.RelationalRowsWindowFunction.percent_rank, relative_ranked.plan.window.windows[0].function);
    try std.testing.expectEqualStrings("usage_percent_rank", relative_ranked.plan.window.windows[0].output);
